        private bool ShouldRunStrategySchedulerNow()
        {
            var now = GetStrategySchedulerClockUtc();
            var interval = GetStrategySchedulerIntervalSeconds();
            var intervalTicks = TimeSpan.FromSeconds(interval).Ticks;
            var slotStartUtc = new DateTime(now.Ticks - (now.Ticks % intervalTicks), DateTimeKind.Utc);
            if (_lastStrategySchedulerRunUtc < slotStartUtc)
                return true;

            // Historical time can freeze over weekend gaps. Keep a real one-minute heartbeat
            // so the dashboard proves the scheduler is alive even when no new bar can exist.
            return IsBacktestingRuntime() &&
                (_lastStrategySchedulerWallUtc == DateTime.MinValue ||
                 (DateTime.UtcNow - _lastStrategySchedulerWallUtc).TotalSeconds >= 60);
        }

        private void MarkStrategySchedulerSlotProcessed()
        {
            var interval = GetStrategySchedulerIntervalSeconds();
            var intervalTicks = TimeSpan.FromSeconds(interval).Ticks;
            var now = GetStrategySchedulerClockUtc();
            _lastStrategySchedulerRunUtc = new DateTime(now.Ticks - (now.Ticks % intervalTicks), DateTimeKind.Utc);
            _lastStrategySchedulerWallUtc = DateTime.UtcNow;
        }

        private int GetStrategySchedulerIntervalSeconds()
        {
            // A backtest must observe every configured timeframe independently of the chart
            // timeframe. One simulated-minute cadence is the maximum permitted gap.
            if (IsBacktestingRuntime())
                return 60;
            return Math.Max(5, Math.Min(300, StrategyScanSeconds));
        }

        private DateTime GetStrategySchedulerClockUtc()
        {
            if (IsBacktestingRuntime())
            {
                try
                {
                    var simulatedTime = NormalizeBotTimeToUtc(Server.Time);
                    if (simulatedTime != DateTime.MinValue)
                        return simulatedTime;
                }
                catch
                {
                }
            }
            return DateTime.UtcNow;
        }

