        private string NormalizeCanonicalEventCacheTimeFrameKey(TimeFrame timeFrame)
        {
            var minutes = TimeFrameToMinutes(timeFrame);
            if (minutes == 1) return "1";
            if (minutes == 5) return "5";
            if (minutes == 15) return "15";
            if (minutes == 60) return "60";
            if (minutes == 240) return "240";
            if (minutes == 1440) return "1440";
            return SafePathPart(minutes > 0 ? minutes.ToString(CultureInfo.InvariantCulture) : GetMiniChartLabel(timeFrame), "default");
        }

        private string GetCanonicalEventCacheFilePath(string symbolName, TimeFrame timeFrame)
        {
            var baseRoot = GetBaseServerRootPath();
            var safeSymbol = SafePathPart(string.IsNullOrWhiteSpace(symbolName) ? "UNKNOWN" : symbolName.Trim().ToUpperInvariant(), "UNKNOWN");
            var tfKey = NormalizeCanonicalEventCacheTimeFrameKey(timeFrame);
            return Path.Combine(baseRoot, "data", "market_data", safeSymbol, "chart", tfKey, CanonicalEventCacheFileName);
        }

        private string GetAnalysisCacheFilePath(string symbolName, TimeFrame timeFrame, string fileName)
        {
            var baseRoot = GetBaseServerRootPath();
            var safeSymbol = SafePathPart(string.IsNullOrWhiteSpace(symbolName) ? "UNKNOWN" : symbolName.Trim().ToUpperInvariant(), "UNKNOWN");
            return Path.Combine(baseRoot, "data", "market_data", safeSymbol, "chart", NormalizeCanonicalEventCacheTimeFrameKey(timeFrame), fileName);
        }

        private string BuildCandlePatternDefinitionSignature(IEnumerable<CandlePatternDefinition> definitions)
        {
            return string.Join("|", (definitions ?? Enumerable.Empty<CandlePatternDefinition>())
                .Where(definition => definition != null)
                .Select(GetCandlePatternDefinitionKey)
                .OrderBy(value => value, StringComparer.OrdinalIgnoreCase));
        }

        private PersistedCandlePatternCache LoadPersistedCandlePatternCache(string symbolName, TimeFrame timeFrame)
        {
            var key = "patterns|" + BuildDashboardEventCacheKey(symbolName, timeFrame);
            PersistedCandlePatternCache cached;
            if (_persistedCandlePatternCache.TryGetValue(key, out cached))
                return cached;

            var snapshot = new PersistedCandlePatternCache();
            var filePath = GetAnalysisCacheFilePath(symbolName, timeFrame, CandlePatternCacheFileName);
            var status = "not_found";
            try
            {
                if (System.IO.File.Exists(filePath))
                {
                    status = "loaded";
                    foreach (var rawLine in System.IO.File.ReadAllLines(filePath))
                    {
                        var parts = (rawLine ?? "").Split('\t');
                        if (parts.Length < 3 || !string.Equals(parts[1], CandlePatternCacheVersion, StringComparison.Ordinal))
                            continue;
                        if (string.Equals(parts[0], "META", StringComparison.OrdinalIgnoreCase))
                        {
                            snapshot.DefinitionSignature = parts[2] ?? "";
                            continue;
                        }
                        long barTimeUnix;
                        if (!long.TryParse(parts[2], NumberStyles.Integer, CultureInfo.InvariantCulture, out barTimeUnix) || barTimeUnix <= 0)
                            continue;
                        if (string.Equals(parts[0], "BAR", StringComparison.OrdinalIgnoreCase))
                            snapshot.ComputedBarTimesUnix.Add(barTimeUnix);
                        else if (string.Equals(parts[0], "PAT", StringComparison.OrdinalIgnoreCase) && parts.Length >= 4)
                            snapshot.Matches.Add(new PersistedCandlePatternMatch { BarTimeUnix = barTimeUnix, DefinitionKey = parts[3] ?? "" });
                    }
                }
            }
            catch (Exception ex)
            {
                status = "load_error";
                SafePrint("[Perf] CandlePatternCacheLoad failed: {0}", ex.Message);
            }
            _persistedCandlePatternCache[key] = snapshot;
            SafePrint(
                "[AnalysisCache] load patterns symbol={0} tf={1} file={2} status={3} coverage={4} bars={5} matches={6} types={7}",
                symbolName,
                GetTimeFrameShortLabel(timeFrame),
                filePath,
                status,
                FormatAnalysisCacheCoverage(snapshot.ComputedBarTimesUnix),
                snapshot.ComputedBarTimesUnix.Count,
                snapshot.Matches.Count,
                FormatPatternCacheTypeCounts(snapshot.Matches));
            return snapshot;
        }

        private void WritePersistedCandlePatternCache(string symbolName, TimeFrame timeFrame, PersistedCandlePatternCache snapshot)
        {
            if (snapshot == null)
                return;
            try
            {
                var lines = new List<string> { "META\t" + CandlePatternCacheVersion + "\t" + (snapshot.DefinitionSignature ?? "") };
                foreach (var barTime in snapshot.ComputedBarTimesUnix.OrderBy(value => value))
                    lines.Add(string.Format(CultureInfo.InvariantCulture, "BAR\t{0}\t{1}", CandlePatternCacheVersion, barTime));
                foreach (var match in snapshot.Matches.Where(match => match != null).OrderBy(match => match.BarTimeUnix).ThenBy(match => match.DefinitionKey))
                    lines.Add(string.Format(CultureInfo.InvariantCulture, "PAT\t{0}\t{1}\t{2}", CandlePatternCacheVersion, match.BarTimeUnix, match.DefinitionKey ?? ""));
                var filePath = GetAnalysisCacheFilePath(symbolName, timeFrame, CandlePatternCacheFileName);
                WriteAnalysisCacheFile(filePath, lines);
                SafePrint(
                    "[AnalysisCache] save patterns symbol={0} tf={1} file={2} coverage={3} bars={4} matches={5} types={6}",
                    symbolName,
                    GetTimeFrameShortLabel(timeFrame),
                    filePath,
                    FormatAnalysisCacheCoverage(snapshot.ComputedBarTimesUnix),
                    snapshot.ComputedBarTimesUnix.Count,
                    snapshot.Matches.Count,
                    FormatPatternCacheTypeCounts(snapshot.Matches));
            }
            catch (Exception ex) { SafePrint("[Perf] CandlePatternCacheStore failed: {0}", ex.Message); }
        }

        private void WriteAnalysisCacheFile(string filePath, IEnumerable<string> lines)
        {
            var folder = Path.GetDirectoryName(filePath);
            if (!string.IsNullOrWhiteSpace(folder)) Directory.CreateDirectory(folder);
            var tempPath = filePath + "." + Process.GetCurrentProcess().Id + "." + DateTime.UtcNow.Ticks + ".tmp";
            System.IO.File.WriteAllLines(tempPath, lines ?? Enumerable.Empty<string>(), new UTF8Encoding(false));
            if (System.IO.File.Exists(filePath)) System.IO.File.Delete(filePath);
            System.IO.File.Move(tempPath, filePath);
        }

        private string FormatAnalysisCacheCoverage(IEnumerable<long> barTimesUnix)
        {
            var values = (barTimesUnix ?? Enumerable.Empty<long>()).Where(value => value > 0).OrderBy(value => value).ToList();
            if (values.Count == 0) return "empty";
            return FormatAnalysisCacheTime(values.First()) + "->" + FormatAnalysisCacheTime(values.Last());
        }

        private string FormatAnalysisCacheTime(long unixSeconds)
        {
            if (unixSeconds <= 0) return "?";
            return DateTimeOffset.FromUnixTimeSeconds(unixSeconds).UtcDateTime.ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture) + "Z";
        }

        private string FormatPatternCacheTypeCounts(IEnumerable<PersistedCandlePatternMatch> matches)
        {
            var parts = (matches ?? Enumerable.Empty<PersistedCandlePatternMatch>())
                .Where(match => match != null && !string.IsNullOrWhiteSpace(match.DefinitionKey))
                .GroupBy(match => GetPatternCacheTypeLabel(match.DefinitionKey), StringComparer.OrdinalIgnoreCase)
                .OrderBy(group => group.Key, StringComparer.OrdinalIgnoreCase)
                .Select(group => group.Key + ":" + group.Count())
                .ToList();
            return parts.Count == 0 ? "none" : string.Join(",", parts);
        }

        private string GetPatternCacheTypeLabel(string definitionKey)
        {
            var parts = (definitionKey ?? "").Split(':');
            if (parts.Length < 2) return string.IsNullOrWhiteSpace(definitionKey) ? "?" : definitionKey;
            return parts[0].ToLowerInvariant() + "." + (string.Equals(parts[1], "B", StringComparison.OrdinalIgnoreCase) ? "up" : "down");
        }

        private string FormatScoredZoneCacheSummary(PersistedScoredZoneCache snapshot)
        {
            var zones = snapshot != null && snapshot.Zones != null ? snapshot.Zones : new List<ScoredPriceZone>();
            var kinds = zones
                .GroupBy(zone => zone.Kind)
                .OrderBy(group => group.Key.ToString(), StringComparer.OrdinalIgnoreCase)
                .Select(group => group.Key.ToString().ToLowerInvariant() + ":" + group.Count());
            var start = zones.Where(zone => zone.StartTime != DateTime.MinValue).Select(zone => zone.StartTime).DefaultIfEmpty(DateTime.MinValue).Min();
            return string.Format(
                CultureInfo.InvariantCulture,
                "last_closed={0} range={1}->{2} lookback={3} zones={4} types={5}",
                FormatAnalysisCacheTime(snapshot != null ? snapshot.LastClosedBarTimeUnix : 0),
                start == DateTime.MinValue ? "?" : start.ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture) + "Z",
                FormatAnalysisCacheTime(snapshot != null ? snapshot.LastClosedBarTimeUnix : 0),
                snapshot != null ? snapshot.LookbackBars : 0,
                zones.Count,
                string.Join(",", kinds));
        }

        private PersistedScoredZoneCache LoadPersistedScoredZoneCache(string symbolName, TimeFrame timeFrame, int lastClosedIndex)
        {
            var key = "zones|" + BuildDashboardEventCacheKey(symbolName, timeFrame);
            PersistedScoredZoneCache cached;
            if (_persistedScoredZoneCache.TryGetValue(key, out cached)) return cached;
            cached = new PersistedScoredZoneCache();
            var filePath = GetAnalysisCacheFilePath(symbolName, timeFrame, ScoredZoneCacheFileName);
            var status = "not_found";
            try
            {
                if (System.IO.File.Exists(filePath))
                {
                    status = "loaded";
                    foreach (var rawLine in System.IO.File.ReadAllLines(filePath))
                    {
                        var parts = (rawLine ?? "").Split('\t');
                        if (parts.Length < 3 || !string.Equals(parts[1], ScoredZoneCacheVersion, StringComparison.Ordinal)) continue;
                        if (string.Equals(parts[0], "META", StringComparison.OrdinalIgnoreCase))
                        {
                            long.TryParse(parts[2], NumberStyles.Integer, CultureInfo.InvariantCulture, out cached.LastClosedBarTimeUnix);
                            if (parts.Length > 3) int.TryParse(parts[3], NumberStyles.Integer, CultureInfo.InvariantCulture, out cached.LookbackBars);
                            continue;
                        }
                        if (!string.Equals(parts[0], "ZONE", StringComparison.OrdinalIgnoreCase) || parts.Length < 9) continue;
                        ScoredPriceZoneKind kind;
                        double low, high;
                        int score, visits;
                        if (!Enum.TryParse(parts[2], true, out kind) ||
                            !double.TryParse(parts[4], NumberStyles.Float, CultureInfo.InvariantCulture, out low) ||
                            !double.TryParse(parts[5], NumberStyles.Float, CultureInfo.InvariantCulture, out high) ||
                            !int.TryParse(parts[6], NumberStyles.Integer, CultureInfo.InvariantCulture, out score) ||
                            !int.TryParse(parts[7], NumberStyles.Integer, CultureInfo.InvariantCulture, out visits)) continue;
                        long startTimeUnix;
                        long.TryParse(parts[8], NumberStyles.Integer, CultureInfo.InvariantCulture, out startTimeUnix);
                        cached.Zones.Add(new ScoredPriceZone { Kind = kind, Label = parts[3], Low = low, High = high, Score = score, VisitCount = visits, LastTouchBarIndex = lastClosedIndex, StartTime = startTimeUnix > 0 ? DateTimeOffset.FromUnixTimeSeconds(startTimeUnix).UtcDateTime : DateTime.MinValue });
                    }
                }
            }
            catch (Exception ex) { status = "load_error"; SafePrint("[Perf] ScoredZoneCacheLoad failed: {0}", ex.Message); }
            _persistedScoredZoneCache[key] = cached;
            SafePrint("[AnalysisCache] load zones symbol={0} tf={1} file={2} status={3} {4}", symbolName, GetTimeFrameShortLabel(timeFrame), filePath, status, FormatScoredZoneCacheSummary(cached));
            return cached;
        }

        private void WritePersistedScoredZoneCache(string symbolName, TimeFrame timeFrame, PersistedScoredZoneCache snapshot)
        {
            if (snapshot == null) return;
            try
            {
                var lines = new List<string> { string.Format(CultureInfo.InvariantCulture, "META\t{0}\t{1}\t{2}", ScoredZoneCacheVersion, snapshot.LastClosedBarTimeUnix, snapshot.LookbackBars) };
                foreach (var zone in snapshot.Zones ?? new List<ScoredPriceZone>())
                    lines.Add(string.Format(CultureInfo.InvariantCulture, "ZONE\t{0}\t{1}\t{2}\t{3:0.#####}\t{4:0.#####}\t{5}\t{6}\t{7}", ScoredZoneCacheVersion, zone.Kind, zone.Label ?? "", zone.Low, zone.High, zone.Score, zone.VisitCount, ToUnixSecondsSafe(zone.StartTime)));
                var filePath = GetAnalysisCacheFilePath(symbolName, timeFrame, ScoredZoneCacheFileName);
                WriteAnalysisCacheFile(filePath, lines);
                SafePrint("[AnalysisCache] save zones symbol={0} tf={1} file={2} {3}", symbolName, GetTimeFrameShortLabel(timeFrame), filePath, FormatScoredZoneCacheSummary(snapshot));
            }
            catch (Exception ex) { SafePrint("[Perf] ScoredZoneCacheStore failed: {0}", ex.Message); }
        }

        private void MarkAnalysisCacheDirty(string kind, string symbolName, TimeFrame timeFrame)
        {
            _cacheEngine.MarkAnalysisDirty(kind, symbolName, TimeFrameToMinutes(timeFrame));
        }

        private void FlushAnalysisCachesHourly(bool force = false)
        {
            var now = DateTime.UtcNow;
            if (!_cacheEngine.ShouldFlushAnalysis(now, TimeSpan.FromMinutes(AnalysisCacheFlushMinutes), force)) return;
            foreach (var key in _cacheEngine.SnapshotDirtyAnalysisKeys())
            {
                var parts = key.Split('|');
                if (parts.Length != 3) continue;
                var cacheKey = parts[0] + "|" + parts[1] + "|" + parts[2];
                var timeFrame = ResolveAnalysisCacheTimeFrame(parts[2]);
                if (timeFrame == null) continue;
                if (string.Equals(parts[0], "patterns", StringComparison.OrdinalIgnoreCase))
                {
                    PersistedCandlePatternCache cache;
                    if (_persistedCandlePatternCache.TryGetValue("patterns|" + BuildDashboardEventCacheKey(parts[1], timeFrame), out cache))
                    {
                        var symbolName = parts[1];
                        var snapshot = ClonePersistedCandlePatternCache(cache);
                        QueueAnalysisPersistence(() => WritePersistedCandlePatternCache(symbolName, timeFrame, snapshot));
                    }
                }
                else if (string.Equals(parts[0], "zones", StringComparison.OrdinalIgnoreCase))
                {
                    PersistedScoredZoneCache cache;
                    if (_persistedScoredZoneCache.TryGetValue("zones|" + BuildDashboardEventCacheKey(parts[1], timeFrame), out cache))
                    {
                        var symbolName = parts[1];
                        var snapshot = ClonePersistedScoredZoneCache(cache);
                        QueueAnalysisPersistence(() => WritePersistedScoredZoneCache(symbolName, timeFrame, snapshot));
                    }
                }
                _cacheEngine.MarkAnalysisFlushed(key);
            }
            _cacheEngine.CompleteAnalysisFlush(DateTime.UtcNow);
            if (force)
                WaitForAnalysisPersistence();
        }

        private PersistedCandlePatternCache ClonePersistedCandlePatternCache(PersistedCandlePatternCache source)
        {
            var clone = new PersistedCandlePatternCache();
            if (source == null)
                return clone;

            clone.DefinitionSignature = source.DefinitionSignature ?? "";
            clone.ComputedBarTimesUnix = new HashSet<long>(source.ComputedBarTimesUnix ?? new HashSet<long>());
            clone.Matches = (source.Matches ?? new List<PersistedCandlePatternMatch>())
                .Where(match => match != null)
                .Select(match => new PersistedCandlePatternMatch
                {
                    BarTimeUnix = match.BarTimeUnix,
                    DefinitionKey = match.DefinitionKey
                })
                .ToList();
            return clone;
        }

        private PersistedScoredZoneCache ClonePersistedScoredZoneCache(PersistedScoredZoneCache source)
        {
            return new PersistedScoredZoneCache
            {
                LastClosedBarTimeUnix = source != null ? source.LastClosedBarTimeUnix : 0,
                LookbackBars = source != null ? source.LookbackBars : 0,
                Zones = source != null && source.Zones != null
                    ? new List<ScoredPriceZone>(source.Zones)
                    : new List<ScoredPriceZone>()
            };
        }

        private void QueueAnalysisPersistence(Action writeAction)
        {
            if (writeAction == null)
                return;
            _cacheEngine.EnqueuePersistence(
                writeAction,
                ex => SafePrint("[Perf] Analysis persistence failed: {0}", ex.Message));
        }

        private void WaitForAnalysisPersistence()
        {
            var pending = _cacheEngine.PersistenceSnapshot();

            try
            {
                if (pending != null && !pending.Wait(TimeSpan.FromSeconds(10)))
                    SafePrint("[Perf] Analysis persistence did not finish within 10s");
            }
            catch (Exception ex)
            {
                SafePrint("[Perf] Analysis persistence wait failed: {0}", ex.Message);
            }
        }

        private TimeFrame ResolveAnalysisCacheTimeFrame(string rawMinutes)
        {
            int minutes;
            if (!int.TryParse(rawMinutes, NumberStyles.Integer, CultureInfo.InvariantCulture, out minutes)) return null;
            if (minutes == 1) return TimeFrame.Minute;
            if (minutes == 5) return TimeFrame.Minute5;
            if (minutes == 15) return TimeFrame.Minute15;
            if (minutes == 30) return TimeFrame.Minute30;
            if (minutes == 60) return TimeFrame.Hour;
            if (minutes == 240) return TimeFrame.Hour4;
            if (minutes == 1440) return TimeFrame.Daily;
            return null;
        }

        private PersistedCanonicalEventCache LoadPersistedCanonicalEventCache(string symbolName, TimeFrame timeFrame)
        {
            var cacheKey = BuildDashboardEventCacheKey(symbolName, timeFrame);

            // Read the persisted snapshot from disk at most once per runtime (start of day).
            // After that, memory is the single source of truth until the end-of-day flush.
            if (_cacheEngine.IsCanonicalLoaded(cacheKey))
            {
                TimedCacheEntry<PersistedCanonicalEventCache> cached;
                if (_persistedCanonicalEventCache.TryGetValue(cacheKey, out cached) &&
                    cached != null &&
                    cached.Value != null)
                {
                    return cached.Value;
                }
                return new PersistedCanonicalEventCache();
            }

            var snapshot = new PersistedCanonicalEventCache();
            var filePath = GetCanonicalEventCacheFilePath(symbolName, timeFrame);
            var fileFound = false;
            var loadStatus = "not_found";
            try
            {
                fileFound = System.IO.File.Exists(filePath);
                if (fileFound)
                {
                    loadStatus = "loaded";
                    foreach (var rawLine in System.IO.File.ReadAllLines(filePath))
                    {
                        var line = string.IsNullOrWhiteSpace(rawLine) ? "" : rawLine.Trim();
                        if (string.IsNullOrWhiteSpace(line))
                            continue;

                        var parts = line.Split('\t');
                        if (parts.Length < 3)
                            continue;

                        if (!string.Equals(parts[1], CanonicalEventCacheVersion, StringComparison.Ordinal))
                            continue;

                        long barTimeUnix;
                        if (!long.TryParse(parts[2], NumberStyles.Integer, CultureInfo.InvariantCulture, out barTimeUnix) || barTimeUnix <= 0)
                            continue;

                        if (string.Equals(parts[0], "BAR", StringComparison.OrdinalIgnoreCase))
                        {
                            snapshot.ComputedBarTimesUnix.Add(barTimeUnix);
                            continue;
                        }

                        if (!string.Equals(parts[0], "EVT", StringComparison.OrdinalIgnoreCase) || parts.Length < 11)
                            continue;

                        CanonicalEventType eventType;
                        CanonicalEventReason reason;
                        CanonicalEventAction action;
                        if (!Enum.TryParse(parts[4], true, out eventType) ||
                            !Enum.TryParse(parts[6], true, out reason) ||
                            !Enum.TryParse(parts[7], true, out action))
                            continue;

                        double priceRef;
                        int score;
                        int confidence;
                        if (!double.TryParse(parts[8], NumberStyles.Float, CultureInfo.InvariantCulture, out priceRef))
                            priceRef = 0;
                        if (!int.TryParse(parts[9], NumberStyles.Integer, CultureInfo.InvariantCulture, out score))
                            score = 0;
                        if (!int.TryParse(parts[10], NumberStyles.Integer, CultureInfo.InvariantCulture, out confidence))
                            confidence = 0;

                        double zoneLow = 0;
                        double zoneHigh = 0;
                        if (parts.Length > 12)
                        {
                            if (!double.TryParse(parts[11], NumberStyles.Float, CultureInfo.InvariantCulture, out zoneLow))
                                zoneLow = 0;
                            if (!double.TryParse(parts[12], NumberStyles.Float, CultureInfo.InvariantCulture, out zoneHigh))
                                zoneHigh = 0;
                        }
                        var levelKind = parts.Length > 13 ? parts[13] ?? "" : "";

                        var evtTime = DateTimeOffset.FromUnixTimeSeconds(barTimeUnix).UtcDateTime;
                        snapshot.Events.Add(new CanonicalMarketEvent
                        {
                            EventKey = parts[3] ?? "",
                            SymbolName = string.IsNullOrWhiteSpace(symbolName) ? "" : symbolName.Trim().ToUpperInvariant(),
                            TimeFrameLabel = GetMiniChartLabel(timeFrame),
                            EventType = eventType,
                            IsBullish = string.Equals(parts[5], "bullish", StringComparison.OrdinalIgnoreCase),
                            Reason = reason,
                            Action = action,
                            BarTime = evtTime,
                            PriceRef = priceRef,
                            Score = score,
                            Confidence = confidence,
                            SourceTimeFrame = timeFrame,
                            ZoneLow = zoneLow,
                            ZoneHigh = zoneHigh,
                            LevelKind = levelKind
                        });
                    }
                }
            }
            catch (Exception ex)
            {
                loadStatus = "load_error";
                SafePrint("[Perf] CanonicalEventsCacheLoad failed: {0}", ex.Message);
            }

            snapshot.Events = DeduplicateCanonicalEvents(snapshot.Events);
            SafePrint(
                "[HistoryCache] symbol={0} tf={1} file={2} status={3} bars={4} events={5}",
                string.IsNullOrWhiteSpace(symbolName) ? "?" : symbolName.Trim().ToUpperInvariant(),
                GetTimeFrameShortLabel(timeFrame),
                filePath,
                loadStatus,
                snapshot.ComputedBarTimesUnix.Count,
                snapshot.Events.Count);
            _persistedCanonicalEventCache[cacheKey] = new TimedCacheEntry<PersistedCanonicalEventCache>
            {
                CreatedAtUtc = DateTime.UtcNow,
                Value = snapshot
            };
            _cacheEngine.MarkCanonicalLoaded(cacheKey);
            TrackPersistedCanonicalEventCacheKey(symbolName, timeFrame);
            return snapshot;
        }

        private void TrackPersistedCanonicalEventCacheKey(string symbolName, TimeFrame timeFrame)
        {
            if (string.IsNullOrWhiteSpace(symbolName) || timeFrame == null)
                return;

            _cacheEngine.TrackCanonical(symbolName, timeFrame, BuildDashboardEventCacheKey);
        }

        private void StorePersistedCanonicalEventCache(string symbolName, TimeFrame timeFrame, PersistedCanonicalEventCache snapshot)
        {
            if (snapshot == null)
                return;

            // During the trading day, recomputed events are kept in memory only; the single
            // disk write is deferred to the end-of-day flush (CheckCanonicalCacheDayFlush).
            _persistedCanonicalEventCache[BuildDashboardEventCacheKey(symbolName, timeFrame)] = new TimedCacheEntry<PersistedCanonicalEventCache>
            {
                CreatedAtUtc = DateTime.UtcNow,
                Value = snapshot
            };
            TrackPersistedCanonicalEventCacheKey(symbolName, timeFrame);
        }

        // Writes a single persisted snapshot to disk. Only called by the end-of-day flush
        // (and best-effort on stop), so the trading day never pays per-recompute disk I/O.
        private void WritePersistedCanonicalEventCacheToDisk(string symbolName, TimeFrame timeFrame, PersistedCanonicalEventCache snapshot)
        {
            if (snapshot == null)
                return;

            try
            {
                var lines = new List<string>();
                foreach (var barTimeUnix in snapshot.ComputedBarTimesUnix.OrderBy(value => value))
                {
                    lines.Add(string.Format(
                        CultureInfo.InvariantCulture,
                        "BAR\t{0}\t{1}",
                        CanonicalEventCacheVersion,
                        barTimeUnix));
                }

                foreach (var evt in DeduplicateCanonicalEvents(snapshot.Events).OrderBy(value => value.BarTime).ThenBy(value => value.Score))
                {
                    lines.Add(string.Format(
                        CultureInfo.InvariantCulture,
                        "EVT\t{0}\t{1}\t{2}\t{3}\t{4}\t{5}\t{6}\t{7}\t{8}\t{9}\t{10}\t{11}\t{12}",
                        CanonicalEventCacheVersion,
                        ToUnixSecondsSafe(evt.BarTime),
                        evt.EventKey ?? "",
                        evt.EventType,
                        evt.IsBullish ? "bullish" : "bearish",
                        evt.Reason,
                        evt.Action,
                        evt.PriceRef.ToString("0.#####", CultureInfo.InvariantCulture),
                        evt.Score,
                        evt.Confidence,
                        evt.ZoneLow.ToString("0.#####", CultureInfo.InvariantCulture),
                        evt.ZoneHigh.ToString("0.#####", CultureInfo.InvariantCulture),
                        evt.LevelKind ?? ""));
                }

                var filePath = GetCanonicalEventCacheFilePath(symbolName, timeFrame);
                var folder = Path.GetDirectoryName(filePath);
                if (!string.IsNullOrWhiteSpace(folder))
                    Directory.CreateDirectory(folder);

                var tempPath = string.Format(
                    CultureInfo.InvariantCulture,
                    "{0}.{1}.{2}.tmp",
                    filePath,
                    Process.GetCurrentProcess().Id,
                    DateTime.UtcNow.Ticks);
                System.IO.File.WriteAllLines(tempPath, lines, new UTF8Encoding(false));
                if (System.IO.File.Exists(filePath))
                    System.IO.File.Delete(filePath);
                System.IO.File.Move(tempPath, filePath);
            }
            catch (Exception ex)
            {
                SafePrint("[Perf] CanonicalEventsCacheStore failed: {0}", ex.Message);
            }
        }

        private PersistedCanonicalEventCache ClonePersistedCanonicalEventCache(PersistedCanonicalEventCache source)
        {
            return new PersistedCanonicalEventCache
            {
                ComputedBarTimesUnix = source != null
                    ? new HashSet<long>(source.ComputedBarTimesUnix)
                    : new HashSet<long>(),
                Events = source != null
                    ? new List<CanonicalMarketEvent>(source.Events)
                    : new List<CanonicalMarketEvent>()
            };
        }

        // End-of-day flush: snapshots memory on the timer thread, then serializes all disk
        // writes through the background persistence queue so rollover cannot stall trading.
        private void FlushPersistedCanonicalEventCachesToDisk(bool waitForCompletion = false)
        {
            if (_cacheEngine.CanonicalCount == 0)
            {
                if (waitForCompletion)
                    WaitForAnalysisPersistence();
                return;
            }

            try
            {
                var keys = _cacheEngine.SnapshotCanonicalKeys();
                foreach (var key in keys)
                {
                    TimedCacheEntry<PersistedCanonicalEventCache> cached;
                    if (!_persistedCanonicalEventCache.TryGetValue(BuildDashboardEventCacheKey(key.Item1, key.Item2), out cached))
                        continue;
                    if (cached == null || cached.Value == null)
                        continue;
                    var symbolName = key.Item1;
                    var timeFrame = key.Item2;
                    var snapshot = ClonePersistedCanonicalEventCache(cached.Value);
                    QueueAnalysisPersistence(() => WritePersistedCanonicalEventCacheToDisk(symbolName, timeFrame, snapshot));
                }

            }
            catch (Exception ex)
            {
                SafePrint("[Perf] CanonicalEventsCacheFlush failed: {0}", ex.Message);
            }

            if (waitForCompletion)
                WaitForAnalysisPersistence();
        }

        // Called every master tick: when the reference day rolls over, persist the day's
        // in-memory canonical events once (write-once-after-end-of-day).
        private void CheckCanonicalCacheDayFlush()
        {
            if (_persistedCanonicalEventCache.Count == 0)
                return;

            var dayStart = GetCurrentDayStartTime(GetReferenceNow());
            if (_lastCanonicalCacheFlushDay != DateTime.MinValue && dayStart != _lastCanonicalCacheFlushDay)
                FlushPersistedCanonicalEventCachesToDisk();
            _lastCanonicalCacheFlushDay = dayStart;
        }

        private List<CanonicalMarketEvent> DeduplicateCanonicalEvents(IEnumerable<CanonicalMarketEvent> events)
        {
            return (events ?? Enumerable.Empty<CanonicalMarketEvent>())
                .OrderByDescending(evt => evt.BarTime)
                .ThenByDescending(evt => evt.Score)
                .ThenByDescending(evt => evt.PriceRef)
                .GroupBy(evt => string.Format(
                    CultureInfo.InvariantCulture,
                    "{0}|{1}|{2}|{3}",
                    evt.EventKey,
                    evt.TimeFrameLabel,
                    evt.BarTime.Ticks,
                    Math.Round(evt.PriceRef, 6)))
                .Select(group => group.First())
                .ToList();
        }

        private bool HasCanonicalEventCacheCoverage(PersistedCanonicalEventCache snapshot, Bars bars, int startIndex, int endIndex)
        {
            if (snapshot == null || bars == null || startIndex < 0 || endIndex < startIndex || endIndex >= bars.Count)
                return false;

            for (var index = startIndex; index <= endIndex; index++)
            {
                var barTimeUnix = ToUnixSecondsSafe(bars.OpenTimes[index]);
                if (barTimeUnix <= 0 || !snapshot.ComputedBarTimesUnix.Contains(barTimeUnix))
                    return false;
            }

            return true;
        }

        private void MergeCanonicalEventCacheCoverage(PersistedCanonicalEventCache snapshot, Bars bars, int startIndex, int endIndex, IEnumerable<CanonicalMarketEvent> events)
        {
            if (snapshot == null || bars == null || startIndex < 0 || endIndex < startIndex)
                return;

            var startUnix = ToUnixSecondsSafe(bars.OpenTimes[startIndex]);
            var endUnix = ToUnixSecondsSafe(bars.OpenTimes[Math.Min(endIndex, bars.Count - 1)]);
            for (var index = startIndex; index <= endIndex && index < bars.Count; index++)
            {
                var barTimeUnix = ToUnixSecondsSafe(bars.OpenTimes[index]);
                if (barTimeUnix > 0)
                    snapshot.ComputedBarTimesUnix.Add(barTimeUnix);
            }

            snapshot.Events = snapshot.Events
                .Where(evt =>
                {
                    var barTimeUnix = ToUnixSecondsSafe(evt.BarTime);
                    return barTimeUnix < startUnix || barTimeUnix > endUnix;
                })
                .ToList();

            snapshot.Events.AddRange(events ?? Enumerable.Empty<CanonicalMarketEvent>());
            snapshot.Events = DeduplicateCanonicalEvents(snapshot.Events);
        }

        private void PruneCanonicalEventCache(PersistedCanonicalEventCache snapshot, Bars bars, int latestClosedIndex)
        {
            if (snapshot == null || bars == null || latestClosedIndex < 0 || bars.Count == 0)
                return;

            var oldestIndex = Math.Max(0, latestClosedIndex - CanonicalEventCacheMaxBars + 1);
            var minUnix = ToUnixSecondsSafe(bars.OpenTimes[oldestIndex]);
            snapshot.ComputedBarTimesUnix = new HashSet<long>(snapshot.ComputedBarTimesUnix.Where(value => value >= minUnix));
            snapshot.Events = snapshot.Events
                .Where(evt => ToUnixSecondsSafe(evt.BarTime) >= minUnix)
                .ToList();
        }

