        private string ResolveSyncedTradeSource(string label, string comment)
        {
            var note = ExtractBrokerCommentNote(comment);
            if (!string.IsNullOrWhiteSpace(note) &&
                (note.StartsWith("ai_", StringComparison.OrdinalIgnoreCase) ||
                 note.StartsWith("pa_", StringComparison.OrdinalIgnoreCase) ||
                 note.StartsWith("manual", StringComparison.OrdinalIgnoreCase)))
                return NormalizeTradeSource(note, SyncChannelName);

            var normalizedLabel = string.IsNullOrWhiteSpace(label) ? "" : label.Trim();
            if (!string.IsNullOrWhiteSpace(normalizedLabel))
            {
                var firstToken = normalizedLabel.Split('/').FirstOrDefault();
                if (!string.IsNullOrWhiteSpace(firstToken) &&
                    (firstToken.IndexOf("ai_", StringComparison.OrdinalIgnoreCase) >= 0 ||
                     firstToken.IndexOf("manual", StringComparison.OrdinalIgnoreCase) >= 0))
                    return NormalizeTradeSource(firstToken, SyncChannelName);
            }

            return SyncChannelName;
        }

        private string NormalizeTradeProfile(string profileRaw, string tfRaw)
        {
            var value = string.IsNullOrWhiteSpace(profileRaw) ? "" : profileRaw.Trim().ToLowerInvariant();
            if (value.Contains("scalp")) return "scalp";
            if (value.Contains("swing")) return "swing";
            if (value.Contains("daily") || value.Contains("intraday")) return "daily";

            var tf = string.IsNullOrWhiteSpace(tfRaw) ? "" : tfRaw.Trim().ToLowerInvariant();
            if (tf == "1" || tf == "1m" || tf == "m1") return "scalp";
            if (tf == "5" || tf == "5m" || tf == "m5") return "swing";
            if (!string.IsNullOrEmpty(tf)) return "daily";
            return "";
        }

        private string NormalizeTradeTfLabel(string tfRaw)
        {
            var tf = string.IsNullOrWhiteSpace(tfRaw) ? "" : tfRaw.Trim().ToLowerInvariant();
            if (string.IsNullOrEmpty(tf)) return "";
            switch (tf)
            {
                case "1":
                case "1m":
                case "m1":
                    return "m1";
                case "5":
                case "5m":
                case "m5":
                    return "m5";
                case "15":
                case "15m":
                case "m15":
                    return "m15";
                case "30":
                case "30m":
                case "m30":
                    return "m30";
                case "60":
                case "1h":
                case "h1":
                    return "h1";
                case "240":
                case "4h":
                case "h4":
                    return "h4";
                case "1440":
                case "1d":
                case "d1":
                case "daily":
                    return "d1";
                default:
                    return tfRaw.Trim();
            }
        }

