        {
            return CTraderChartEngine.NormalizeToolbarTradeProfile(
                raw, _chartSelectedTradeProfile);
        }

        private string GetChartTradeProfileRaw(string raw = null)
        {
            var normalized = NormalizeChartTradeProfileSelection(raw);
            return normalized.ToLowerInvariant();
        }

        private string GetCustomUiSettingsFilePath()
        {
            try
            {
                var configPath = GetBaseServerConfigPath();
                return Path.Combine(configPath, CustomUiSettingsFileName);
            }
            catch
            {
                return Path.Combine(Environment.CurrentDirectory, CustomUiSettingsFileName);
            }
        }

        private void LoadCustomUiSettings()
        {
            if (DisableCustomUiSettingsPersistenceForIsolation)
                return;

            _customUiSettings.Clear();
            _customUiSettingsSerializedSnapshot = "";

            try
            {
                var path = GetCustomUiSettingsFilePath();
                if (!System.IO.File.Exists(path))
                    return;

                foreach (var rawLine in System.IO.File.ReadAllLines(path))
                {
                    var line = rawLine ?? "";
                    var separatorIndex = line.IndexOf('=');
                    if (separatorIndex <= 0)
                        continue;

                    var key = line.Substring(0, separatorIndex).Trim();
                    var value = line.Substring(separatorIndex + 1);
                    if (string.IsNullOrWhiteSpace(key))
                        continue;

                    _customUiSettings[key] = value ?? "";
                }

                _customUiSettingsSerializedSnapshot = SerializeCustomUiSettingsSnapshot();
            }
            catch (Exception ex)
            {
                SafeLog("ERROR", "[Settings] Load failed: {0}", ex.Message);
            }
        }

        private string SerializeCustomUiSettingsSnapshot()
        {
            return string.Join(
                Environment.NewLine,
                _customUiSettings
                    .OrderBy(kv => kv.Key, StringComparer.OrdinalIgnoreCase)
                    .Select(kv => string.Format(CultureInfo.InvariantCulture, "{0}={1}", kv.Key, kv.Value ?? ""))
                    .ToArray());
        }

        private void SaveCustomUiSettings()
        {
            if (DisableCustomUiSettingsPersistenceForIsolation)
                return;

            var serialized = SerializeCustomUiSettingsSnapshot();
            if (string.Equals(serialized, _customUiSettingsSerializedSnapshot, StringComparison.Ordinal))
                return;

            // Mark the snapshot saved in memory first so repeated combo changes do not
            // enqueue identical work. One worker serializes local/API writes and coalesces
            // rapid changes to the latest pending snapshot.
            _customUiSettingsSerializedSnapshot = serialized;

            lock (_customUiSettingsPersistenceLock)
            {
                _pendingCustomUiSettingsSnapshot = serialized;
                if (_customUiSettingsPersistenceActive)
                    return;

                _customUiSettingsPersistenceActive = true;
                _customUiSettingsPersistenceTask = Task.Run(ProcessCustomUiSettingsPersistenceAsync);
            }
        }

        private async Task ProcessCustomUiSettingsPersistenceAsync()
        {
            while (true)
            {
                string serialized;
                lock (_customUiSettingsPersistenceLock)
                {
                    serialized = _pendingCustomUiSettingsSnapshot;
                    _pendingCustomUiSettingsSnapshot = null;
                    if (serialized == null)
                    {
                        _customUiSettingsPersistenceActive = false;
                        return;
                    }
                }

                try
                {
                    WriteCustomUiSettingsFile(serialized);
                }
                catch (Exception ex)
                {
                    SafeLog("ERROR", "[Settings] Save failed: {0}", ex.Message);
                }

                try
                {
                    await SaveUiSettingsToApiAsync(serialized);
                }
                catch (Exception ex)
                {
                    SafePrint("[Settings] API save failed: {0}", ex.Message);
                }
            }
        }

        private void WaitForCustomUiSettingsPersistence()
        {
            Task pending;
            lock (_customUiSettingsPersistenceLock)
                pending = _customUiSettingsPersistenceTask;

            try
            {
                if (pending != null && !pending.Wait(TimeSpan.FromSeconds(5)))
                    SafePrint("[Settings] Persistence did not finish within 5s");
            }
            catch (Exception ex)
            {
                SafePrint("[Settings] Persistence wait failed: {0}", ex.Message);
            }
        }

        private void WriteCustomUiSettingsFile(string serialized)
        {
            var path = GetCustomUiSettingsFilePath();
            var folder = Path.GetDirectoryName(path);
            if (!string.IsNullOrWhiteSpace(folder))
                Directory.CreateDirectory(folder);

            var lines = string.IsNullOrEmpty(serialized)
                ? new string[0]
                : serialized.Split(new[] { Environment.NewLine }, StringSplitOptions.None);
            // Atomic replacement protects the last good file if the process stops mid-write.
            var tempPath = string.Format(
                CultureInfo.InvariantCulture,
                "{0}.{1}.{2}.tmp",
                path,
                Process.GetCurrentProcess().Id,
                DateTime.UtcNow.Ticks);
            System.IO.File.WriteAllLines(tempPath, lines, new UTF8Encoding(false));
            if (System.IO.File.Exists(path))
                System.IO.File.Delete(path);
            System.IO.File.Move(tempPath, path);
            PrintBypassLogFilter("[Settings] Saved custom UI settings to {0}", path);
        }

        // Mirrors the chart UI settings to the 42trade API as a fire-and-forget async call.
        // The local file remains the load source at startup; the API copy lets other
        // consumers (or a future multi-machine setup) read the same selections.
        private async Task SaveUiSettingsToApiAsync(string serializedSettings)
        {
            var payload = new Dictionary<string, object>
            {
                ["source_id"] = BridgeSourceId,
                ["settings"] = ParseCustomUiSettingsDictionary(serializedSettings)
            };
            var content = new StringContent(SerializeJsonValue(payload), Encoding.UTF8, "application/json");
            content.Headers.Add("x-api-key", EaApiKey);
            var response = await _httpClient.PostAsync(BuildServerApiUrl("broker/ui-settings"), content);
            if (response == null || !response.IsSuccessStatusCode)
                SafePrint("[Settings] API save HTTP {0}", response == null ? "null" : ((int)response.StatusCode).ToString(CultureInfo.InvariantCulture));
        }

        private Dictionary<string, string> ParseCustomUiSettingsDictionary(string serialized)
        {
            var result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            if (string.IsNullOrWhiteSpace(serialized))
                return result;

            foreach (var rawLine in serialized.Split(new[] { Environment.NewLine }, StringSplitOptions.None))
            {
                var line = rawLine ?? "";
                var separatorIndex = line.IndexOf('=');
                if (separatorIndex <= 0)
                    continue;
                var key = line.Substring(0, separatorIndex).Trim();
                var value = line.Substring(separatorIndex + 1);
                if (string.IsNullOrWhiteSpace(key))
                    continue;
                result[key] = value ?? "";
            }
            return result;
        }

        private string GetCustomUiSetting(string key, string fallback = "")
        {
            string value;
            return !string.IsNullOrWhiteSpace(key) && _customUiSettings.TryGetValue(key, out value)
                ? (value ?? "")
                : fallback;
        }

        private bool TryParseFlexibleBool(string raw, out bool value)
        {
            value = false;
            if (string.IsNullOrWhiteSpace(raw))
                return false;

            var normalized = raw.Trim();
            bool parsedBool;
            if (bool.TryParse(normalized, out parsedBool))
            {
                value = parsedBool;
                return true;
            }

            switch (normalized.ToLowerInvariant())
            {
                case "yes":
                case "y":
                case "1":
                case "on":
                    value = true;
                    return true;
                case "no":
                case "n":
                case "0":
                case "off":
                    value = false;
                    return true;
                default:
                    return false;
            }
        }

        private bool TryGetCustomUiBool(string key, out bool value)
        {
            value = false;
            var raw = GetCustomUiSetting(key, null);
            return TryParseFlexibleBool(raw, out value);
        }

        private void SetCustomUiSetting(string key, string value)
        {
            if (string.IsNullOrWhiteSpace(key))
                return;
            _customUiSettings[key] = value ?? "";
