        private TimeFrame GetChartTradeStructureTimeFrame(string profileRaw)
        {
            switch (NormalizeTradeProfile(profileRaw, ""))
            {
                case "swing":
                    return TimeFrame.Hour4;
                case "daily":
                    return TimeFrame.Daily;
                case "scalp":
                default:
                    return TimeFrame.Hour;
            }
        }

        private string GetChartTradeStructureTfLabel(string profileRaw)
        {
            var profile = NormalizeTradeProfile(profileRaw, "");
            if (profile == "scalp") return "CUR+HTF";
            var timeFrame = GetChartTradeStructureTimeFrame(profileRaw);
            if (timeFrame == TimeFrame.Daily) return "d1";
            if (timeFrame == TimeFrame.Hour4) return "h4";
            return "h1";
        }

        private List<TimeFrame> GetChartTradeStructureTimeFrames(string profileRaw)
        {
            var frames = new List<TimeFrame>();
            var profile = NormalizeTradeProfile(profileRaw, "");
            if (profile == "daily")
            {
                frames.Add(TimeFrame.Daily);
                return frames;
            }

            if (profile == "swing")
            {
                frames.Add(TimeFrame.Hour4);
                return frames;
            }

            var currentTf = Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
            frames.Add(currentTf);
            frames.AddRange(GetAutoHigherTimeframes(currentTf));

            return frames
                .Where(tf => tf != null)
                .Distinct()
                .ToList();
        }

        private TimeFrame GetChartEntrySourceTimeFrame(string profileRaw)
        {
            return Chart != null ? Chart.TimeFrame : GetChartTradeStructureTimeFrame(profileRaw);
        }

        private List<TimeFrame> GetChartProtectionSourceTimeFrames(string profileRaw)
        {
            var frames = new List<TimeFrame>();
            var chartTimeFrame = Chart != null ? Chart.TimeFrame : GetChartTradeStructureTimeFrame(profileRaw);
            var chartMinutes = Math.Max(1, TimeFrameToMinutes(chartTimeFrame));

            foreach (var tf in GetAutoHigherTimeframes(chartTimeFrame))
            {
                if (TimeFrameToMinutes(tf) > chartMinutes)
                    frames.Add(tf);
            }

            var structureTimeFrame = GetChartTradeStructureTimeFrame(profileRaw);
            if (TimeFrameToMinutes(structureTimeFrame) > chartMinutes)
                frames.Add(structureTimeFrame);

            if (frames.Count == 0)
                frames.Add(structureTimeFrame);

            return frames
                .Where(tf => tf != null)
                .Distinct()
                .OrderBy(tf => TimeFrameToMinutes(tf))
                .ToList();
        }

