        private bool _displayPrefsApplied;

        private void ApplyChartDisplayPreferences()
        {
            if (_displayPrefsApplied)
                return;
            try
            {
                var displaySettings = Chart != null ? Chart.DisplaySettings : null;
                if (displaySettings == null)
                    return; // Chart not ready yet — retried on the next lite pass.

                var chartTfMinutes = Math.Max(1, TimeFrameToMinutes(Chart != null ? Chart.TimeFrame : TimeFrame.Minute));
                TrySetPropertyValue(displaySettings, "Grid", false);
                // Let cTrader keep the native day separator on sub-4H charts; the bot only
                // draws the intraday HTF ladder there. On 4H+ charts keep native separators
                // off so the custom splitters remain the only vertical guides.
                TrySetPropertyValue(displaySettings, "PeriodSeparators", chartTfMinutes < 240);
                _displayPrefsApplied = true;
            }
            catch
            {
            }
        }

        // Apply the Chart Visuals master combos once at startup: All/None/specific-item override
        // the per-item toggles. Per Item (default) keeps the per-item params/toolbar settings.
        private void ApplyVisualGroupCombos()
        {
            ApplySmcZoneCombo();
            ApplyStructureEventCombo();
            ApplyMomentumTechnicalCombo();
            ApplyCandleCombo();
            // Re-sync native chart indicators against the final combo state. The startup sync
            // ran BEFORE the combos were applied (from the per-item params), so None / All
            // Custom would otherwise leave the native EMA/VWAP/BB/Ichimoku/RSI/Stoch/MACD
            // indicators on the chart. All Custom removes them inside SyncChartTechnicalOverlays.
            try { SyncChartOscillatorIndicators(); } catch (Exception ex) { SafePrint("[Visuals] Oscillator re-sync failed: {0}", ex.Message); }
            try { SyncChartTechnicalOverlays(); } catch (Exception ex) { SafePrint("[Visuals] Overlay re-sync failed: {0}", ex.Message); }
        }

        private void ApplySmcZoneCombo()
        {
            var ob = false; var fvg = false; var key = false; var liq = false; var htfZones = false; var kz = false; var sd = false;
            switch (SmcZonesCombo)
            {
                case SmcZoneComboMode.None:
                    break;
                case SmcZoneComboMode.All:
                    ob = true; fvg = true; key = true; liq = true; htfZones = true; kz = true; sd = true;
                    break;
                case SmcZoneComboMode.OrderBlocks:
                    ob = true;
                    break;
                case SmcZoneComboMode.FvgZones:
                    fvg = true;
                    break;
                case SmcZoneComboMode.KeyLevels:
                    key = true;
                    break;
                case SmcZoneComboMode.Liquidity:
                    liq = true;
                    break;
                case SmcZoneComboMode.HigherTimeframeZones:
                    htfZones = true;
                    break;
                case SmcZoneComboMode.KillerZones:
                    kz = true;
                    break;
                case SmcZoneComboMode.SupplyDemand:
                    sd = true;
                    break;
                default:
                    return;
            }
            _toggleOrderBlocks = ob;
            _toggleFvgZones = fvg;
            _toggleKeyLevels = key;
            _toggleLiquidityLevels = liq;
            _toggleHigherTimeframeZones = htfZones;
            _toggleKillerZones = kz;
            _toggleSupplyDemand = sd;
        }

        private bool ResolveStructureEventToggle(StructureEventToggleMode mode, out StructureEventFollowUpFilter filter)
        {
            filter = StructureEventFollowUpFilter.Any;
            switch (mode)
            {
                case StructureEventToggleMode.Yes:
                    return true;
                case StructureEventToggleMode.Yes_c:
                    filter = StructureEventFollowUpFilter.Continue;
                    return true;
                case StructureEventToggleMode.Yes_r:
                    filter = StructureEventFollowUpFilter.Reverse;
                    return true;
                default:
                    return false;
            }
        }

        private void SetAllStructureEventFollowUpFilters(StructureEventFollowUpFilter filter)
        {
            _sweepEventFollowUpFilter = filter;
            _bosEventFollowUpFilter = filter;
            _chochEventFollowUpFilter = filter;
            _rejectionEventFollowUpFilter = filter;
            _breakoutEventFollowUpFilter = filter;
            _pullbackEventFollowUpFilter = filter;
            _continuationEventFollowUpFilter = filter;
            _impulseEventFollowUpFilter = filter;
        }

        private void ApplyStructureEventCombo()
        {
            var sweep = false; var bos = false; var choch = false; var rj = false; var br = false;
            var pb = false; var ct = false; var im = false;
            SetAllStructureEventFollowUpFilters(StructureEventFollowUpFilter.Any);
            switch (StructureEventsCombo)
            {
                case StructureEventComboMode.None:
                    break;
                case StructureEventComboMode.All:
                    sweep = true; bos = true; choch = true; rj = true; br = true; pb = true; ct = true; im = true;
                    break;
                case StructureEventComboMode.All_c:
                    sweep = true; bos = true; choch = true; rj = true; br = true; pb = true; ct = true; im = true;
                    SetAllStructureEventFollowUpFilters(StructureEventFollowUpFilter.Continue);
                    break;
                case StructureEventComboMode.All_r:
                    sweep = true; bos = true; choch = true; rj = true; br = true; pb = true; ct = true; im = true;
                    SetAllStructureEventFollowUpFilters(StructureEventFollowUpFilter.Reverse);
                    break;
                case StructureEventComboMode.Swp_Sweep:
                    sweep = true;
                    break;
                case StructureEventComboMode.Bos_BreakOfStructure:
                    bos = true;
                    break;
                case StructureEventComboMode.Choch_ChangeOfCharacter:
                    choch = true;
                    break;
                case StructureEventComboMode.Rj_Rejection:
                    rj = true;
                    break;
                case StructureEventComboMode.Br_Breakout:
                    br = true;
                    break;
                case StructureEventComboMode.Pb_Pullback:
                    pb = true;
                    break;
                case StructureEventComboMode.Ct_Continuation:
                    ct = true;
                    break;
                case StructureEventComboMode.Im_Impulse:
                    im = true;
                    break;
                case StructureEventComboMode.PerItem:
                    sweep = ResolveStructureEventToggle(DrawSweepDetections, out _sweepEventFollowUpFilter);
                    bos = ResolveStructureEventToggle(DrawBosDetections, out _bosEventFollowUpFilter);
                    choch = ResolveStructureEventToggle(DrawChochDetections, out _chochEventFollowUpFilter);
                    rj = ResolveStructureEventToggle(DrawRejectionDetections, out _rejectionEventFollowUpFilter);
                    br = ResolveStructureEventToggle(DrawBreakoutDetections, out _breakoutEventFollowUpFilter);
                    pb = ResolveStructureEventToggle(DrawPullbackDetections, out _pullbackEventFollowUpFilter);
                    ct = ResolveStructureEventToggle(DrawContinuationDetections, out _continuationEventFollowUpFilter);
                    im = ResolveStructureEventToggle(DrawImpulseDetections, out _impulseEventFollowUpFilter);
                    break;
                default:
                    return;
            }
            _toggleSweepDetections = sweep;
            _toggleBosDetections = bos;
            _toggleChochDetections = choch;
            _toggleRejectionDetections = rj;
            _toggleBreakoutDetections = br;
            _togglePullbackDetections = pb;
            _toggleContinuationDetections = ct;
            _toggleImpulseDetections = im;
        }

        private void ApplyMomentumTechnicalCombo()
        {
            _forceCustomTechnicalOverlays =
                MomentumTechnicalCombo == MomentumTechnicalComboMode.AllCustom ||
                MomentumTechnicalCombo == MomentumTechnicalComboMode.PerItem_Custom;
            var ema = false; var vwap = false; var bb = false; var ichi = false;
            var emaE = false; var vwapE = false; var bbE = false; var rsiE = false; var stoE = false; var macdE = false;
            switch (MomentumTechnicalCombo)
            {
                case MomentumTechnicalComboMode.None:
                    break;
                case MomentumTechnicalComboMode.All:
                case MomentumTechnicalComboMode.AllCustom:
                    ema = true; vwap = true; bb = true; ichi = true;
                    emaE = true; vwapE = true; bbE = true; rsiE = true; stoE = true; macdE = true;
                    break;
                case MomentumTechnicalComboMode.PerItem:
                case MomentumTechnicalComboMode.PerItem_Custom:
                    ema = DrawEmaOverlay != EmaVisualMode.Off;
                    vwap = DrawVwapOverlay != VwapVisualMode.Off;
                    bb = DrawBollingerOverlay != BollingerVisualMode.Off;
                    ichi = DrawIchimokuOverlay != IchimokuVisualMode.Off;
                    emaE = DrawEmaEvents == EventToggleMode.On && DrawEmaOverlay != EmaVisualMode.Off;
                    vwapE = DrawVwapEvents == EventToggleMode.On && DrawVwapOverlay != VwapVisualMode.Off;
                    bbE = DrawBollingerEvents == EventToggleMode.On && DrawBollingerOverlay != BollingerVisualMode.Off;
                    rsiE = DrawRsiEvents == EventToggleMode.On && DrawRsiMode != RsiVisualMode.Off;
                    stoE = DrawStochasticEvents == EventToggleMode.On && DrawStochasticMode != StochasticVisualMode.Off;
                    macdE = DrawMacdEvents == EventToggleMode.On && DrawMacdMode != MacdVisualMode.Off;
                    break;
                case MomentumTechnicalComboMode.Ema:
                    ema = true;
                    break;
                case MomentumTechnicalComboMode.Vwap:
                    vwap = true;
                    break;
                case MomentumTechnicalComboMode.Bollinger:
                    bb = true;
                    break;
                case MomentumTechnicalComboMode.Ichimoku:
                    ichi = true;
                    break;
                case MomentumTechnicalComboMode.EmaEvents:
                    emaE = true;
                    break;
                case MomentumTechnicalComboMode.VwapEvents:
                    vwapE = true;
                    break;
                case MomentumTechnicalComboMode.BollingerEvents:
                    bbE = true;
                    break;
                case MomentumTechnicalComboMode.RsiEvents:
                    rsiE = true;
                    break;
                case MomentumTechnicalComboMode.StochasticEvents:
                    stoE = true;
                    break;
                case MomentumTechnicalComboMode.MacdEvents:
                    macdE = true;
                    break;
                default:
                    return;
            }
            _toggleEmaOverlay = ema;
            _toggleVwapOverlay = vwap;
            _toggleBollingerOverlay = bb;
            _toggleIchimokuOverlay = ichi;
            _toggleEmaEvents = emaE;
            _toggleVwapEvents = vwapE;
            _toggleBollingerEvents = bbE;
            _toggleRsiEvents = rsiE;
            _toggleStochasticEvents = stoE;
            _toggleMacdEvents = macdE;
        }

        private void ApplyCandleCombo()
        {
            var pin = false; var eng = false; var big = false; var mor = false; var eve = false;
            var ham = false; var hgm = false; var sst = false; var ihm = false; var prc = false;
            var dcc = false; var tws = false; var tbc = false; var har = false;
            SetAllCandlePatternFollowUpFilters(StructureEventFollowUpFilter.Any);
            switch (CandlesCombo)
            {
                case CandleComboMode.None:
                    break;
                case CandleComboMode.All:
                    pin = true; eng = true; big = true; mor = true; eve = true;
                    ham = true; hgm = true; sst = true; ihm = true; prc = true;
                    dcc = true; tws = true; tbc = true; har = true;
                    break;
                case CandleComboMode.All_c:
                    pin = true; eng = true; big = true; mor = true; eve = true;
                    ham = true; hgm = true; sst = true; ihm = true; prc = true;
                    dcc = true; tws = true; tbc = true; har = true;
                    SetAllCandlePatternFollowUpFilters(StructureEventFollowUpFilter.Continue);
                    break;
                case CandleComboMode.All_r:
                    pin = true; eng = true; big = true; mor = true; eve = true;
                    ham = true; hgm = true; sst = true; ihm = true; prc = true;
                    dcc = true; tws = true; tbc = true; har = true;
                    SetAllCandlePatternFollowUpFilters(StructureEventFollowUpFilter.Reverse);
                    break;
                case CandleComboMode.Pin_PinBar:
                    pin = true;
                    break;
                case CandleComboMode.Eng_Engulfing:
                    eng = true;
                    break;
                case CandleComboMode.Big_BigCandle:
                    big = true;
                    break;
                case CandleComboMode.Mor_MorningStar:
                    mor = true;
                    break;
                case CandleComboMode.Eve_EveningStar:
                    eve = true;
                    break;
                case CandleComboMode.Ham_Hammer:
                    ham = true;
                    break;
                case CandleComboMode.Hgm_HangingMan:
                    hgm = true;
                    break;
                case CandleComboMode.Sst_ShootingStar:
                    sst = true;
                    break;
                case CandleComboMode.Ihm_InvertedHammer:
                    ihm = true;
                    break;
                case CandleComboMode.Prc_PiercingLine:
                    prc = true;
                    break;
                case CandleComboMode.Dcc_DarkCloudCover:
                    dcc = true;
                    break;
                case CandleComboMode.Tws_ThreeWhiteSoldiers:
                    tws = true;
                    break;
                case CandleComboMode.Tbc_ThreeBlackCrows:
                    tbc = true;
                    break;
                case CandleComboMode.Har_Harami:
                    har = true;
                    break;
                case CandleComboMode.PerItem:
                    pin = ResolveCandlePatternToggle(DrawPinBarPatterns, out _pinBarPatternFollowUpFilter);
                    eng = ResolveCandlePatternToggle(DrawEngulfingPatterns, out _engulfingPatternFollowUpFilter);
                    big = ResolveCandlePatternToggle(DrawBigCandlePatterns, out _bigCandlePatternFollowUpFilter);
                    mor = ResolveCandlePatternToggle(DrawMorningStarPatterns, out _morningStarPatternFollowUpFilter);
                    eve = ResolveCandlePatternToggle(DrawEveningStarPatterns, out _eveningStarPatternFollowUpFilter);
                    ham = ResolveCandlePatternToggle(DrawHammerPatterns, out _hammerPatternFollowUpFilter);
                    hgm = ResolveCandlePatternToggle(DrawHangingManPatterns, out _hangingManPatternFollowUpFilter);
                    sst = ResolveCandlePatternToggle(DrawShootingStarPatterns, out _shootingStarPatternFollowUpFilter);
                    ihm = ResolveCandlePatternToggle(DrawInvertedHammerPatterns, out _invertedHammerPatternFollowUpFilter);
                    prc = ResolveCandlePatternToggle(DrawPiercingLinePatterns, out _piercingLinePatternFollowUpFilter);
                    dcc = ResolveCandlePatternToggle(DrawDarkCloudCoverPatterns, out _darkCloudCoverPatternFollowUpFilter);
                    tws = ResolveCandlePatternToggle(DrawThreeWhiteSoldiersPatterns, out _threeWhiteSoldiersPatternFollowUpFilter);
                    tbc = ResolveCandlePatternToggle(DrawThreeBlackCrowsPatterns, out _threeBlackCrowsPatternFollowUpFilter);
                    har = ResolveCandlePatternToggle(DrawHaramiPatterns, out _haramiPatternFollowUpFilter);
                    break;
                default:
                    return;
            }
            _togglePinBarPatterns = pin; _toggleEngulfingPatterns = eng; _toggleBigCandlePatterns = big;
            _toggleMorningStarPatterns = mor; _toggleEveningStarPatterns = eve; _toggleHammerPatterns = ham;
            _toggleHangingManPatterns = hgm; _toggleShootingStarPatterns = sst; _toggleInvertedHammerPatterns = ihm;
            _togglePiercingLinePatterns = prc; _toggleDarkCloudCoverPatterns = dcc;
            _toggleThreeWhiteSoldiersPatterns = tws; _toggleThreeBlackCrowsPatterns = tbc; _toggleHaramiPatterns = har;
        }

        private bool ResolveCandlePatternToggle(CandlePatternToggleMode mode, out StructureEventFollowUpFilter filter)
        {
            filter = StructureEventFollowUpFilter.Any;
            switch (mode)
            {
                case CandlePatternToggleMode.Yes:
                    return true;
                case CandlePatternToggleMode.Yes_c:
                    filter = StructureEventFollowUpFilter.Continue;
                    return true;
                case CandlePatternToggleMode.Yes_r:
                    filter = StructureEventFollowUpFilter.Reverse;
                    return true;
                default:
                    return false;
            }
        }

