        private void DrawLiteZoneOverlays()
        {
            try
            {
                if (!AreChartVisualsEnabled())
                {
                    RemoveChartVisualObjects();
                    RemoveManagedOscillatorIndicators();
                    RemoveManagedTechnicalOverlays();
                    _pendingDetectionsStateKey = "";
                    _pendingDetectionsBarsCount = -1;
                    _pendingDetectionsPhase = 0;
                    return;
                }

                if (Chart == null || Bars == null || Bars.Count < 5)
                    return;

                // Native chart display prefs (grid / period separators) may not be available
                // during OnStart — retry here until they apply.
                try { ApplyChartDisplayPreferences(); } catch { }

                var sw = Stopwatch.StartNew();
                var breakdown = new List<string>();
                var objectIndex = 0;
                var phase = _liteVisualRefreshPhase;
                var phaseName = phase == 0 ? "splitters" : phase == 1 ? "background" : phase == 2 ? "mini" : phase == 3 ? "detections" : phase == 4 ? "technicals" : "dashboard";
                WriteBridgeDebugLog("Visuals: lite." + phaseName + " start objects=" + Chart.Objects.Count.ToString(CultureInfo.InvariantCulture));
                switch (phase)
                {
                    case 0:
                        objectIndex = RefreshLite4HSplitters(objectIndex, breakdown);
                        break;
                    case 1:
                        objectIndex = RefreshLiteHtfBackground(objectIndex, breakdown);
                        break;
                    case 2:
                        objectIndex = RefreshLiteMiniCharts(objectIndex, breakdown);
                        break;
                    case 3:
                        objectIndex = RefreshLiteDetections(objectIndex, breakdown);
                        break;
                    case 4:
                        objectIndex = RefreshLiteTechnicalOverlays(objectIndex, breakdown);
                        break;
                    default:
                        // Dashboard text painting must stay lightweight; the full event/
                        // confluence analysis can be expensive enough to stall the timer.
                        RefreshDebugPanelNow(false, false);
                        RefreshChartSummaryPanel(BuildPanelRiskGateStateSafe());
                        break;
                }
                _liteVisualRefreshPhase = CTraderChartEngine.AdvanceRefreshPhase(
                    _liteVisualRefreshPhase, LiteVisualRefreshPhaseCount);
                WriteBridgeDebugLog("Visuals: lite." + phaseName + " complete added=" + objectIndex.ToString(CultureInfo.InvariantCulture));

                sw.Stop();
                _lastLiteOverlayDrawMs = sw.ElapsedMilliseconds;
                _lastLiteOverlayObjectCount = objectIndex;
                _lastLiteOverlayBreakdown = string.Join(" ", breakdown.ToArray());
                _lastLiteOverlayAtUtc = DateTime.UtcNow;
                LogSlowChartStep("visuals.lite", sw, _lastLiteOverlayBreakdown);
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Lite zones failed: {0}", ex.Message);
                // Never let one overlay family pin the phased renderer before its dashboard
                // turn; otherwise Scan and health text remain frozen indefinitely.
                _liteVisualRefreshPhase = CTraderChartEngine.AdvanceRefreshPhase(
                    _liteVisualRefreshPhase, LiteVisualRefreshPhaseCount);
            }
        }

        private static void CommitLiteBreakdown(List<string> breakdown, int beforeCount, int afterCount, string label)
        {
            CTraderChartEngine.CommitBreakdown(breakdown, beforeCount, afterCount, label);
        }

        // 4H splitter grid: only changes at 4H boundaries / visible window edge / day rollover.
        private int RefreshLite4HSplitters(int objectIndex, List<string> breakdown)
        {
            var stateKey = Build4HSplitterStateKey();
            if (!CTraderChartEngine.ShouldRefresh(
                    _last4HSplitterBarsCount, _last4HSplitterStateKey, Bars.Count, stateKey,
                    DateTime.MinValue, DateTime.UtcNow, 0))
                return objectIndex;
            _last4HSplitterBarsCount = Bars.Count;
            _last4HSplitterStateKey = stateKey;

            var before = objectIndex;
            RemoveChartObjectsByPrefixes("H4SPLIT_", "DSPLIT_", "SPLIT_");
            objectIndex = DrawFourHourSplitters(objectIndex);
            CommitLiteBreakdown(breakdown, before, objectIndex, "h4split");
            return objectIndex;
        }

        private int DrawMiniCandleOverlay(
            int objectIndex,
            int leftBarIndex,
            int rightBarIndex,
            double high,
            double low,
            double open,
            double close,
            Color wickBorderColor,
            Color bodyFillColor,
            Color bodyBorderColor)
        {
            if (rightBarIndex <= leftBarIndex)
                rightBarIndex = leftBarIndex + 1;

            var bodyHigh = Math.Max(open, close);
            var bodyLow = Math.Min(open, close);
            var chartSymbol = ResolveLoadedSymbol(Chart != null ? Chart.SymbolName : "") ?? Symbol;
            var minimumBodyHeight = Math.Max(chartSymbol != null ? chartSymbol.PipSize : 0.0000001, (high - low) * 0.015);
            if (bodyHigh - bodyLow < minimumBodyHeight)
            {
                var bodyMid = (bodyHigh + bodyLow) * 0.5;
                bodyHigh = bodyMid + (minimumBodyHeight * 0.5);
                bodyLow = bodyMid - (minimumBodyHeight * 0.5);
            }

            var centerBarIndex = leftBarIndex + Math.Max(0, (rightBarIndex - leftBarIndex) / 2);
            if (high > bodyHigh)
            {
                var upperWick = Chart.DrawTrendLine(
                    "MINI_WU_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                    centerBarIndex,
                    high,
                    centerBarIndex,
                    bodyHigh,
                    bodyFillColor);
                TrySetPropertyValue(upperWick, "Thickness", 1);
                TrySetPropertyValue(upperWick, "ZIndex", 9);
                objectIndex++;
            }

            if (low < bodyLow)
            {
                var lowerWick = Chart.DrawTrendLine(
                    "MINI_WL_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                    centerBarIndex,
                    bodyLow,
                    centerBarIndex,
                    low,
                    bodyFillColor);
                TrySetPropertyValue(lowerWick, "Thickness", 1);
                TrySetPropertyValue(lowerWick, "ZIndex", 9);
                objectIndex++;
            }

            var body = Chart.DrawRectangle(
                "MINI_BODY_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                leftBarIndex,
                bodyHigh,
                rightBarIndex,
                bodyLow,
                bodyFillColor);
            TrySetPropertyValue(body, "IsFilled", true);
            TrySetPropertyValue(body, "Color", bodyFillColor);
            TrySetPropertyValue(body, "BorderColor", bodyBorderColor);
            TrySetPropertyValue(body, "Thickness", 1);
            TrySetPropertyValue(body, "ZIndex", 10);
            return objectIndex + 1;
        }

        // HTF background candles: only change when a completed 1D/4H/NY-30 bar changes.
        private int RefreshLiteHtfBackground(int objectIndex, List<string> breakdown)
        {
            var stateKey = BuildHtfBackgroundStateKey();
            if (!CTraderChartEngine.ShouldRefresh(
                    _lastHtfBackgroundBarsCount, _lastHtfBackgroundStateKey, Bars.Count, stateKey,
                    DateTime.MinValue, DateTime.UtcNow, 0))
                return objectIndex;
            _lastHtfBackgroundBarsCount = Bars.Count;
            _lastHtfBackgroundStateKey = stateKey;

            var before = objectIndex;
            RemoveChartObjectsByPrefixes("HTFBG_", "HTFBOX_");
            // Track exact TF candle identities, not just timeframes. The completed background
            // candle and latest pattern candle can belong to the same TF but different bars.
            var drawnHtfCandleKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (ShouldDrawHtfBackground())
                objectIndex = DrawBackgroundAutoHigherTimeframeCandles(objectIndex, drawnHtfCandleKeys);
            if (AreChartVisualsEnabled())
                objectIndex = DrawHtfCandlePatternBoxes(objectIndex, drawnHtfCandleKeys);
            CommitLiteBreakdown(breakdown, before, objectIndex, "bg");
            return objectIndex;
        }

        // HTF mini charts: anchored to the chart's right edge + completed HTF bars, so they
        // refresh once per chart bar instead of on every forming-bar tick; throttled on fast
        // timeframes so the strip doesn't rebuild every few seconds.
        private int RefreshLiteMiniCharts(int objectIndex, List<string> breakdown)
        {
            var stateKey = BuildMiniChartStateKey();
            var nowUtc = DateTime.UtcNow;
            if (!CTraderChartEngine.ShouldRefresh(
                    _lastMiniChartBarsCount, _lastMiniChartStateKey, Bars.Count, stateKey,
                    _lastMiniChartRedrawAtUtc, nowUtc, LiteRedrawMinIntervalSeconds))
                return objectIndex;
            _lastMiniChartBarsCount = Bars.Count;
            _lastMiniChartStateKey = stateKey;
            _lastMiniChartRedrawAtUtc = nowUtc;

            var before = objectIndex;
            RemoveChartObjectsByPrefixes("MINI_");
            if (ShouldDrawHtfMiniChart())
                objectIndex = DrawHtfMiniCharts(objectIndex);
            CommitLiteBreakdown(breakdown, before, objectIndex, "mini");
            return objectIndex;
        }

        // Completed-bar detections (killer zones, HTF zones, key levels, liquidity, canonical
        // events): keyed on the last completed bar, never the forming bar.
        // All completed-bar detections in one family (killer zones, HTF zones, key levels,
        // liquidity, canonical events, FVG/order blocks, sweeps, BOS/CHOCH, scored price
        // zones, candle patterns): keyed on the last completed bar (+ toggles + day rollover)
        // and throttled so fast timeframes can't redraw the heavy set every few seconds.
        private int RefreshLiteDetections(int objectIndex, List<string> breakdown)
        {
            var stateKey = BuildDetectionsStateKey();
            var nowUtc = DateTime.UtcNow;
            var refreshPending = !string.IsNullOrEmpty(_pendingDetectionsStateKey);
            if (!refreshPending)
            {
                if (_lastDetectionsBarsCount == Bars.Count &&
                    string.Equals(_lastDetectionsStateKey, stateKey, StringComparison.Ordinal))
                    return objectIndex;
                if (_lastDetectionsRedrawAtUtc != DateTime.MinValue &&
                    (nowUtc - _lastDetectionsRedrawAtUtc).TotalSeconds < LiteRedrawMinIntervalSeconds)
                    return objectIndex;

                _pendingDetectionsStateKey = stateKey;
                _pendingDetectionsBarsCount = Bars.Count;
                _pendingDetectionsPhase = 0;
            }
            else if (_pendingDetectionsBarsCount != Bars.Count ||
                     !string.Equals(_pendingDetectionsStateKey, stateKey, StringComparison.Ordinal))
            {
                // A newer completed bar or setting change supersedes the unfinished cycle.
                _pendingDetectionsStateKey = stateKey;
                _pendingDetectionsBarsCount = Bars.Count;
                _pendingDetectionsPhase = 0;
            }

            var phaseStopwatch = Stopwatch.StartNew();
            var before = objectIndex;
            var phaseLabel = "det" + _pendingDetectionsPhase.ToString(CultureInfo.InvariantCulture);
            WriteBridgeDebugLog("Visuals: " + phaseLabel + " start objects=" + (Chart != null ? Chart.Objects.Count.ToString(CultureInfo.InvariantCulture) : "0"));
            switch (_pendingDetectionsPhase)
            {
                case 0:
                    // Candle patterns are the fastest high-signal visual. Draw them first so
                    // a later, heavier zone/event phase cannot starve their render pass.
                    RemoveChartObjectsByPrefixes("PIN_", "ENG_", "BIG_", "PAT_", "STR_", "SEQ_", "CANDLE_CFL");
                    if (_togglePinBarPatterns || _toggleEngulfingPatterns || _toggleBigCandlePatterns ||
                        _toggleMorningStarPatterns || _toggleEveningStarPatterns || _toggleHammerPatterns ||
                        _toggleHangingManPatterns || _toggleShootingStarPatterns || _toggleInvertedHammerPatterns ||
                        _togglePiercingLinePatterns || _toggleDarkCloudCoverPatterns || _toggleThreeWhiteSoldiersPatterns ||
                        _toggleThreeBlackCrowsPatterns || _toggleHaramiPatterns)
                        objectIndex = DrawDirectionalCandlePatternsOnChart(objectIndex);
                    break;
                case 1:
                    RemoveChartObjectsByPrefixes("KZ_", "FVG_", "OB_", "HTF_FVG_", "HTF_OB_", "ZONE_TXT_");
                    if (_toggleKillerZones) objectIndex = DrawConfiguredKillerZones(objectIndex);
                    if (!ChartObjectsOverBudget() && _toggleFvgZones) objectIndex = DrawRecentFvgZones(GetCurrentChartVisualBars(), Chart.TimeFrame, "FVG_", objectIndex, GetCurrentChartEndTime());
                    if (!ChartObjectsOverBudget() && _toggleOrderBlocks) objectIndex = DrawRecentOrderBlocks(GetCurrentChartVisualBars(), Chart.TimeFrame, "OB_", objectIndex, GetCurrentChartEndTime());
                    if (!ChartObjectsOverBudget() && _toggleHigherTimeframeZones) objectIndex = DrawHigherTimeframeZonesOnChart(objectIndex);
                    break;
                case 2:
                    RemoveChartObjectsByPrefixes("KEY_", "PZ_", "LIQ_");
                    if (_toggleKeyLevels) objectIndex = DrawKeyLevelsOnChart(objectIndex);
                    if (!ChartObjectsOverBudget() && _toggleSupplyDemand) objectIndex = DrawScoredPriceZones(objectIndex);
                    if (!ChartObjectsOverBudget() && _toggleLiquidityLevels) objectIndex = DrawLiquidityLevelsOnChart(objectIndex);
                    break;
                case 3:
                    RemoveChartObjectsByPrefixes("SWEEP_", "BOS_", "CHOCH_");
                    if (_toggleSweepDetections) objectIndex = DrawSweepDetectionsOnChart(objectIndex, _sweepEventFollowUpFilter);
                    if (!ChartObjectsOverBudget() && _toggleBosDetections) objectIndex = DrawStructureBreakDetectionsOnChart(objectIndex, false, _bosEventFollowUpFilter);
                    if (!ChartObjectsOverBudget() && _toggleChochDetections) objectIndex = DrawStructureBreakDetectionsOnChart(objectIndex, true, _chochEventFollowUpFilter);
                    break;
                case 4:
                    RemoveChartObjectsByPrefixes("RJ_", "BR_", "PB_", "CT_", "IM_");
                    if (_toggleRejectionDetections) objectIndex = DrawCanonicalEventsOnChart(objectIndex, CanonicalEventType.Rejection, _rejectionEventFollowUpFilter);
                    if (!ChartObjectsOverBudget() && _toggleBreakoutDetections) objectIndex = DrawCanonicalEventsOnChart(objectIndex, CanonicalEventType.Breakout, _breakoutEventFollowUpFilter);
                    if (!ChartObjectsOverBudget() && _togglePullbackDetections) objectIndex = DrawCanonicalEventsOnChart(objectIndex, CanonicalEventType.Pullback, _pullbackEventFollowUpFilter);
                    if (!ChartObjectsOverBudget() && _toggleContinuationDetections) objectIndex = DrawCanonicalEventsOnChart(objectIndex, CanonicalEventType.Continuation, _continuationEventFollowUpFilter);
                    if (!ChartObjectsOverBudget() && _toggleImpulseDetections) objectIndex = DrawCanonicalEventsOnChart(objectIndex, CanonicalEventType.Impulse, _impulseEventFollowUpFilter);
                    break;
                default:
                    break;
            }
            CommitLiteBreakdown(breakdown, before, objectIndex, phaseLabel);
            LogSlowChartStep("visuals." + phaseLabel, phaseStopwatch, "objects=" + (objectIndex - before).ToString(CultureInfo.InvariantCulture));
            WriteBridgeDebugLog("Visuals: " + phaseLabel + " complete added=" + (objectIndex - before).ToString(CultureInfo.InvariantCulture));

            _pendingDetectionsPhase++;
            if (_pendingDetectionsPhase >= DetectionRefreshPhaseCount)
            {
                _lastDetectionsBarsCount = _pendingDetectionsBarsCount;
                _lastDetectionsStateKey = _pendingDetectionsStateKey;
                _lastDetectionsRedrawAtUtc = nowUtc;
                _pendingDetectionsStateKey = "";
                _pendingDetectionsBarsCount = -1;
                _pendingDetectionsPhase = 0;
            }
            return objectIndex;
        }

        // Technical overlays (EMA/VWAP/Bollinger/Ichimoku): already dirty-keyed separately.
        private int RefreshLiteTechnicalOverlays(int objectIndex, List<string> breakdown)
        {
            var shouldShowTechnicalOverlays = _toggleEmaOverlay || _toggleVwapOverlay || _toggleBollingerOverlay || _toggleIchimokuOverlay;
            if (!shouldShowTechnicalOverlays)
            {
                if (_lastTechnicalOverlayBarsCount >= 0 || !string.IsNullOrEmpty(_lastTechnicalOverlayStateKey))
                {
                    RemoveTechnicalOverlayObjects();
                    _lastTechnicalOverlayBarsCount = -1;
                    _lastTechnicalOverlayStateKey = "";
                }
                return objectIndex;
            }
            if (NativeTechnicalOverlaysActive())
            {
                // Clean any custom overlay objects drawn before native indicators took
                // over (one-time, only if custom was previously rendered).
                if (_lastTechnicalOverlayBarsCount >= 0 || !string.IsNullOrEmpty(_lastTechnicalOverlayStateKey))
                {
                    RemoveTechnicalOverlayObjects();
                    _lastTechnicalOverlayBarsCount = -1;
                    _lastTechnicalOverlayStateKey = "";
                }
                return objectIndex;
            }

            var technicalStateKey = BuildTechnicalOverlayStateKey();
            var technicalNeedsRefresh = _lastTechnicalOverlayBarsCount != Bars.Count ||
                                        !string.Equals(_lastTechnicalOverlayStateKey, technicalStateKey, StringComparison.Ordinal);
            if (technicalNeedsRefresh)
            {
                // Throttle on fast timeframes: indicator series are rebuilt per bar, but on
                // 1s/5s charts that would still rebuild every few seconds.
                var nowUtc = DateTime.UtcNow;
                if (_lastTechOverlayRedrawAtUtc != DateTime.MinValue &&
                    (nowUtc - _lastTechOverlayRedrawAtUtc).TotalSeconds < LiteRedrawMinIntervalSeconds)
                    return objectIndex;
                _lastTechOverlayRedrawAtUtc = nowUtc;
                RemoveTechnicalOverlayObjects();
                var before = objectIndex;
                objectIndex = DrawLiteTrendOverlays(objectIndex);
                CommitLiteBreakdown(breakdown, before, objectIndex, "tech");
                _lastTechnicalOverlayBarsCount = Bars.Count;
                _lastTechnicalOverlayStateKey = technicalStateKey;
            }
            return objectIndex;
        }

        private int DrawLiteTrendOverlays(int objectIndex)
        {
            if (Chart == null || Bars == null || Bars.Count < 24)
                return objectIndex;

            try
            {
                if (_toggleEmaOverlay && !NativeEmaOverlayActive())
                {
                    var emaColor = Color.FromArgb(255, 56, 189, 248);
                    var emaFastValues = BuildExponentialMovingAverageSeries(Bars, _resolvedEmaOverlayConfig.FastPeriod);
                    var emaMidValues = BuildExponentialMovingAverageSeries(Bars, _resolvedEmaOverlayConfig.MidPeriod);
                    objectIndex = DrawIndicatorSeriesLine(objectIndex, "EMA20_", index => emaFastValues[index], emaColor, 1, "Dots", 180);
                    objectIndex = DrawIndicatorSeriesLine(objectIndex, "EMA50_", index => emaMidValues[index], emaColor, 1, "Dots", 180);
                    if (_resolvedEmaOverlayConfig.SlowPeriod > 0 && _resolvedEmaOverlayConfig.SlowPeriod != _resolvedEmaOverlayConfig.MidPeriod)
                    {
                        var emaSlowValues = BuildExponentialMovingAverageSeries(Bars, _resolvedEmaOverlayConfig.SlowPeriod);
                        objectIndex = DrawIndicatorSeriesLine(objectIndex, "EMA200_", index => emaSlowValues[index], emaColor, 1, "Dots", 220, GetEmaOverlayPairLabel(), 9, 1);
                    }
                    else
                        DrawRightEdgeIndicatorLabel("EMA200_", objectIndex, emaMidValues[Bars.Count - 1], emaColor, GetEmaOverlayPairLabel(), 9, 1);
                }

                if (_toggleVwapOverlay && !NativeVwapOverlayActive())
                {
                    var vwapColor = Color.FromArgb(255, 250, 204, 21);
                    objectIndex = DrawIndicatorSeriesLine(objectIndex, "VWAP20_", index => ComputeRollingVwapAtIndex(Bars, _resolvedVwapOverlayConfig.Length, index), vwapColor, 1, "Dots", 180, GetVwapOverlayPairLabel(), 9, 0);
                }

                if (_toggleBollingerOverlay && !NativeBollingerOverlayActive())
                {
                    var bollingerColor = Color.FromArgb(255, 244, 114, 182);
                    objectIndex = DrawIndicatorSeriesLine(objectIndex, "BBMID_", index => ComputeSimpleMovingAverage(Bars, index, _resolvedBollingerOverlayConfig.Period), bollingerColor, 1, "Dots", 180, GetBollingerOverlayPairLabel(), 9, -1);
                    objectIndex = DrawIndicatorSeriesLine(objectIndex, "BBUP_", index => ComputeBollingerUpper(Bars, index, _resolvedBollingerOverlayConfig.Period, _resolvedBollingerOverlayConfig.StdDevMultiplier), bollingerColor, 1, "Dots", 180);
                    objectIndex = DrawIndicatorSeriesLine(objectIndex, "BBDN_", index => ComputeBollingerLower(Bars, index, _resolvedBollingerOverlayConfig.Period, _resolvedBollingerOverlayConfig.StdDevMultiplier), bollingerColor, 1, "Dots", 180);
                }

                if (_toggleIchimokuOverlay && !NativeIchimokuOverlayActive())
                {
                    objectIndex = RenderIchimokuOverlay(objectIndex, 180);
                }
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Lite trend overlays failed: {0}", ex.Message);
            }

            return objectIndex;
        }

        private void DrawChartVisualOverlays()
        {
            if (!AreChartVisualsEnabled())
            {
                RemoveChartVisualObjects();
                RemoveManagedOscillatorIndicators();
                RemoveManagedTechnicalOverlays();
                return;
            }

            try
            {
                try { SyncChartOscillatorIndicators(); } catch (Exception ex) { SafePrint("[Visuals] Oscillator panels refresh failed: {0}", ex.Message); }
                try { SyncChartTechnicalOverlays(); } catch (Exception ex) { SafePrint("[Visuals] Technical overlays sync failed: {0}", ex.Message); }

                // Only rebuild the heavy chart objects when something they draw actually changed
                // (new completed bar, toggle change, symbol/timeframe change, day rollover, marker
                // added). The forming bar's OHLC is intentionally NOT part of the key, so ticks
                // don't force a full remove+redraw every few seconds.
                var fullStateKey = BuildFullOverlayStateKey();
                var fullNeedsRefresh = _forceChartVisualsRefresh ||
                                       _lastFullOverlayBarsCount != (Bars != null ? Bars.Count : -1) ||
                                       !string.Equals(_lastFullOverlayStateKey, fullStateKey, StringComparison.Ordinal);
                if (!fullNeedsRefresh)
                    return;

                // Throttle: rapid state changes (e.g. strategy markers added mid-bar) can
                // otherwise trigger the heavy remove+redraw several times a minute on low TFs.
                // Skipped when the user pressed the manual refresh button.
                var nowUtc = DateTime.UtcNow;
                if (!_forceChartVisualsRefresh &&
                    _lastFullOverlayRedrawAtUtc != DateTime.MinValue &&
                    (nowUtc - _lastFullOverlayRedrawAtUtc).TotalSeconds < FullOverlayRedrawMinIntervalSeconds)
                    return;
                _forceChartVisualsRefresh = false;
                _lastFullOverlayRedrawAtUtc = nowUtc;

                RemoveChartVisualObjects();
                if (Bars == null || Bars.Count < 5 || Chart == null)
                    return;

                var objectIndex = 0;
                var drawnHtfCandleKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                // Directional events are the primary chart output. Draw them before mini charts,
                // background candles, and zones so the chart-object safety cap cannot starve them.
                if (_togglePinBarPatterns || _toggleEngulfingPatterns || _toggleBigCandlePatterns ||
                    _toggleMorningStarPatterns || _toggleEveningStarPatterns || _toggleHammerPatterns ||
                    _toggleHangingManPatterns || _toggleShootingStarPatterns || _toggleInvertedHammerPatterns ||
                    _togglePiercingLinePatterns || _toggleDarkCloudCoverPatterns || _toggleThreeWhiteSoldiersPatterns ||
                    _toggleThreeBlackCrowsPatterns || _toggleHaramiPatterns)
                    objectIndex = DrawDirectionalCandlePatternsOnChart(objectIndex);
                if (!DisableTechnicalVisualRenderingForIsolation && (_toggleEmaEvents || _toggleVwapEvents || _toggleBollingerEvents || _toggleRsiEvents || _toggleStochasticEvents || _toggleMacdEvents))
                    objectIndex = DrawDirectionalIndicatorEventsOnChart(objectIndex);
                if (_toggleSweepDetections)
                {
                    objectIndex = DrawSweepDetectionsOnChart(objectIndex, _sweepEventFollowUpFilter);
                }
                if (_toggleBosDetections)
                {
                    objectIndex = DrawStructureBreakDetectionsOnChart(objectIndex, false, _bosEventFollowUpFilter);
                }
                if (_toggleChochDetections)
                {
                    objectIndex = DrawStructureBreakDetectionsOnChart(objectIndex, true, _chochEventFollowUpFilter);
                }
                if (_toggleRejectionDetections)
                {
                    objectIndex = DrawCanonicalEventsOnChart(objectIndex, CanonicalEventType.Rejection, _rejectionEventFollowUpFilter);
                }
                if (_toggleBreakoutDetections)
                {
                    objectIndex = DrawCanonicalEventsOnChart(objectIndex, CanonicalEventType.Breakout, _breakoutEventFollowUpFilter);
                }
                if (_togglePullbackDetections)
                {
                    objectIndex = DrawCanonicalEventsOnChart(objectIndex, CanonicalEventType.Pullback, _pullbackEventFollowUpFilter);
                }
                if (_toggleContinuationDetections)
                {
                    objectIndex = DrawCanonicalEventsOnChart(objectIndex, CanonicalEventType.Continuation, _continuationEventFollowUpFilter);
                }
                if (_toggleImpulseDetections)
                {
                    objectIndex = DrawCanonicalEventsOnChart(objectIndex, CanonicalEventType.Impulse, _impulseEventFollowUpFilter);
                }
                if (_toggleTrendlines)
                {
                    objectIndex = DrawTrendlinesOnChart(objectIndex);
                }
                if (_toggleDivergence)
                {
                    objectIndex = DrawDivergenceOnChart(objectIndex);
                }
                if (ShouldDrawHtfBackground())
                    objectIndex = DrawBackgroundAutoHigherTimeframeCandles(objectIndex, drawnHtfCandleKeys);
                if (AreChartVisualsEnabled())
                    objectIndex = DrawHtfCandlePatternBoxes(objectIndex, drawnHtfCandleKeys);
                if (ShouldDrawHtfMiniChart())
                    objectIndex = DrawHtfMiniCharts(objectIndex);
                if (_toggleKillerZones)
                    objectIndex = DrawConfiguredKillerZones(objectIndex);
                if (_toggleLiquidityLevels)
                    objectIndex = DrawLiquidityLevelsOnChart(objectIndex);
                if (!DisableTechnicalVisualRenderingForIsolation && !NativeTechnicalOverlaysActive() && (_toggleEmaOverlay || _toggleVwapOverlay || _toggleBollingerOverlay || _toggleIchimokuOverlay))
                {
                    objectIndex = DrawIndicatorOverlaysOnChart(objectIndex);
                }
                if (_toggleFvgZones)
                {
                    objectIndex = DrawRecentFvgZones(GetCurrentChartVisualBars(), Chart.TimeFrame, "FVG_", objectIndex, GetCurrentChartEndTime());
                }
                if (_toggleOrderBlocks)
                {
                    objectIndex = DrawRecentOrderBlocks(GetCurrentChartVisualBars(), Chart.TimeFrame, "OB_", objectIndex, GetCurrentChartEndTime());
                }
                if (_toggleHigherTimeframeZones)
                {
                    objectIndex = DrawHigherTimeframeZonesOnChart(objectIndex);
                }
                if (_toggleKeyLevels)
                    objectIndex = DrawKeyLevelsOnChart(objectIndex);
                if (_toggleSupplyDemand)
                    objectIndex = DrawScoredPriceZones(objectIndex);
                if (_toggleStrategyMarkers)
                    objectIndex = DrawStrategyMarkersOnChart(objectIndex);
                objectIndex = DrawClosedTradesOnChart(objectIndex);
                // The full sweep above removes SPLIT_* along with every other managed chart
                // object, so restore splitters in this same frame. Otherwise the lite phase can
                // regard its previous state as current and leave the grid absent indefinitely.
                // Draw them last so event visuals retain first access to the chart-object budget.
                objectIndex = DrawFourHourSplitters(objectIndex);
                _last4HSplitterBarsCount = Bars.Count;
                _last4HSplitterStateKey = Build4HSplitterStateKey();

                _lastFullOverlayBarsCount = Bars.Count;
                _lastFullOverlayStateKey = fullStateKey;
                if (_toggleEmaOverlay || _toggleVwapOverlay || _toggleBollingerOverlay || _toggleIchimokuOverlay)
                {
                    _lastTechnicalOverlayBarsCount = Bars.Count;
                    _lastTechnicalOverlayStateKey = BuildTechnicalOverlayStateKey();
                }
                else
                {
                    _lastTechnicalOverlayBarsCount = -1;
                    _lastTechnicalOverlayStateKey = "";
                }
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Draw failed: {0}", ex.Message);
            }
        }

        // Manual refresh invalidates every layer and performs one complete rebuild. The user
        // explicitly requested a refresh, so leaving four detection phases queued behind the
        // timer makes the button appear broken for minutes.
        private void ForceRefreshChartVisuals()
        {
            try
            {
                if (Chart == null || Bars == null || Bars.Count < 5)
                    return;

                _forceChartVisualsRefresh = true;
                // Invalidate all lite-family dirty keys + throttles so the per-family
                // redraws also run on the next lite pass instead of being skipped.
                _last4HSplitterBarsCount = -1;
                _last4HSplitterStateKey = "";
                _lastHtfBackgroundBarsCount = -1;
                _lastHtfBackgroundStateKey = "";
                _lastMiniChartBarsCount = -1;
                _lastMiniChartStateKey = "";
                _lastDetectionsBarsCount = -1;
                _lastDetectionsStateKey = "";
                _pendingDetectionsStateKey = "";
                _pendingDetectionsBarsCount = -1;
                _pendingDetectionsPhase = 0;
                _lastTechnicalOverlayBarsCount = -1;
                _lastTechnicalOverlayStateKey = "";
                _lastMiniChartRedrawAtUtc = DateTime.MinValue;
                _lastDetectionsRedrawAtUtc = DateTime.MinValue;
                _lastTechOverlayRedrawAtUtc = DateTime.MinValue;

                DrawChartVisualOverlays();
                RefreshDebugPanelNow(false, true);
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Manual refresh failed: {0}", ex.Message);
            }
        }

        private int DrawBackgroundAutoHigherTimeframeCandles(int objectIndex, HashSet<string> drawnCandleKeys)
        {
            var chartTfMinutes = TimeFrameToMinutes(Chart != null ? Chart.TimeFrame : TimeFrame.Minute);
            if (chartTfMinutes <= 0)
                return objectIndex;
            if (ChartObjectsOverBudget())
                return objectIndex;

            try
            {
                objectIndex = DrawLatestCompletedBackgroundCandle(objectIndex, TimeFrame.Daily, "HTFBG_1D", drawnCandleKeys);

                if (chartTfMinutes < 15)
                {
                    objectIndex = DrawLatestCompletedBackgroundCandle(objectIndex, TimeFrame.Hour4, "HTFBG_4H", drawnCandleKeys);
                }

                if (chartTfMinutes <= 15)
                    objectIndex = DrawFirstNewYorkThirtyMinuteBackground(objectIndex, drawnCandleKeys);
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] HTF background skipped: {0}", ex.Message);
            }

            return objectIndex;
        }

        private int DrawLatestCompletedBackgroundCandle(int objectIndex, TimeFrame sourceTimeFrame, string objectPrefix, HashSet<string> drawnCandleKeys)
        {
            var sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, Chart.SymbolName);
            if (sourceBars == null || sourceBars.Count < 4)
                return objectIndex;

            int sourceIndex;
            if (!TryGetPreviousCompletedPeriodBarIndex(sourceBars, sourceTimeFrame, out sourceIndex))
                return objectIndex;
            return DrawCompletedHtfBackgroundAtIndex(
                objectIndex,
                sourceBars,
                sourceTimeFrame,
                sourceIndex,
                objectPrefix,
                drawnCandleKeys);
        }

        private int DrawFirstNewYorkThirtyMinuteBackground(int objectIndex, HashSet<string> drawnCandleKeys)
        {
            var sourceTimeFrame = TimeFrame.Minute30;
            var sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, Chart.SymbolName);
            if (sourceBars == null || sourceBars.Count < 4)
                return objectIndex;

            var lastCompletedIndex = sourceBars.Count - 2;
            if (lastCompletedIndex < 0)
                return objectIndex;

            var sourceIndex = -1;
            for (var dayOffset = 1; dayOffset <= 6 && sourceIndex < 0; dayOffset++)
            {
                DateTime sessionStartUtc;
                DateTime sessionEndUtc;
                if (!TryGetSessionUtcRange("NY", sourceBars.OpenTimes[lastCompletedIndex].Date.AddDays(-dayOffset), out sessionStartUtc, out sessionEndUtc))
                    continue;

                for (var i = 0; i <= lastCompletedIndex; i++)
                {
                    if (sourceBars.OpenTimes[i] >= sessionStartUtc && sourceBars.OpenTimes[i] < sessionEndUtc)
                    {
                        sourceIndex = i;
                        break;
                    }
                }
            }

            if (sourceIndex < 0)
                return objectIndex;
            return DrawCompletedHtfBackgroundAtIndex(
                objectIndex,
                sourceBars,
                sourceTimeFrame,
                sourceIndex,
                "HTFBG_NY30",
                drawnCandleKeys);
        }

        private string BuildHtfBackgroundCandleKey(Bars sourceBars, TimeFrame sourceTimeFrame, int sourceIndex)
        {
            if (sourceBars == null || sourceTimeFrame == null || sourceIndex < 0 || sourceIndex >= sourceBars.Count)
                return "";
            return string.Format(
                CultureInfo.InvariantCulture,
                "{0}|{1}",
                GetMiniChartLabel(sourceTimeFrame),
                sourceBars.OpenTimes[sourceIndex].Ticks);
        }

        // Draw only the guide for the last completed HTF candle. Pattern highlights are an
        // independent layer and may refer to an earlier completed HTF candle.
        private int DrawCompletedHtfBackgroundAtIndex(
            int objectIndex,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int sourceIndex,
            string objectPrefix,
            HashSet<string> drawnCandleKeys)
        {
            var candleKey = BuildHtfBackgroundCandleKey(sourceBars, sourceTimeFrame, sourceIndex);
            if (string.IsNullOrWhiteSpace(candleKey))
                return objectIndex;
            var guideKey = "guide|" + candleKey;
            if (drawnCandleKeys != null && !drawnCandleKeys.Add(guideKey))
                return objectIndex;

            return DrawHtfCompletedBarHighLowGuides(
                objectIndex,
                sourceBars,
                sourceTimeFrame,
                sourceIndex,
                objectPrefix);
        }

        private int DrawPatternQualifiedHigherTimeframeBackgroundCandles(int objectIndex, HashSet<TimeFrame> drawnFixedFrames)
        {
            if (Chart == null || Bars == null || Bars.Count < 8)
                return objectIndex;

            var patternDefinitions = BuildEnabledCandlePatternDefinitions();
            if (patternDefinitions == null || patternDefinitions.Count == 0)
                return objectIndex;

            var chartTimeFrame = Chart.TimeFrame;
            var chartTfMinutes = Math.Max(1, TimeFrameToMinutes(chartTimeFrame));
            var higherFrames = GetEnabledAutoHigherTimeframes(chartTimeFrame)
                .Where(tf => TimeFrameToMinutes(tf) > chartTfMinutes)
                .Distinct()
                .OrderBy(tf => TimeFrameToMinutes(tf))
                .ToList();

            foreach (var sourceTimeFrame in higherFrames)
            {
                if (drawnFixedFrames != null && drawnFixedFrames.Contains(sourceTimeFrame))
                    continue;

                try
                {
                    var sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, Chart.SymbolName);
                    if (sourceBars == null || sourceBars.Count < 4)
                        continue;

                    int sourceIndex;
                    if (!TryGetPreviousCompletedPeriodBarIndex(sourceBars, sourceTimeFrame, out sourceIndex))
                        continue;

                    if (!HasAnyEnabledCandlePatternAtIndex(sourceBars, sourceTimeFrame, sourceIndex, patternDefinitions))
                        continue;

                    var objectPrefix = "HTFBG_" + GetMiniChartLabel(sourceTimeFrame);
                    objectIndex = DrawBackgroundCandleOverlayAtIndex(objectIndex, sourceBars, sourceTimeFrame, sourceIndex, objectPrefix);
                }
                catch (Exception ex)
                {
                    SafePrint("[Visuals] HTF pattern background {0} skipped: {1}", sourceTimeFrame, ex.Message);
                }
            }

            return objectIndex;
        }

        private bool HasAnyEnabledCandlePatternAtIndex(Bars sourceBars, TimeFrame sourceTimeFrame, int barIndex, List<CandlePatternDefinition> patternDefinitions)
        {
            if (sourceBars == null || patternDefinitions == null || patternDefinitions.Count == 0 || barIndex <= 0 || barIndex >= sourceBars.Count)
                return false;

            HashSet<string> sharedDetections = null;
            foreach (var definition in patternDefinitions)
            {
                if (definition == null)
                    continue;

                if (definition.NativeMatch != null)
                {
                    if (definition.NativeMatch(sourceBars, barIndex))
                        return true;
                    continue;
                }

                if (string.IsNullOrWhiteSpace(definition.SharedPatternType))
                    continue;

                if (sharedDetections == null)
                    sharedDetections = GetDetectedSharedRulePatternSet(sourceBars, sourceTimeFrame, barIndex);

                if (sharedDetections.Contains(definition.SharedPatternType))
                    return true;
            }

            return false;
        }

        // All HTF candle layers share this geometry. The candle is rendered as one narrow
        // current-chart glyph centered in its HTF period; the event box is one current-chart
        // bar wide around the same center. This prevents either layer from becoming a full
        // HTF-period background panel or drifting away from the other.
        private void ResolveHtfCandleGlyphTimeRange(
            DateTime periodStartTime,
            DateTime periodEndTime,
            out DateTime glyphCenterTime,
            out DateTime glyphStartTime,
            out DateTime glyphEndTime,
            out DateTime eventBoxStartTime,
            out DateTime eventBoxEndTime)
        {
            var periodMinutes = Math.Max(1.0, (periodEndTime - periodStartTime).TotalMinutes);
            var chartMinutes = Chart != null ? (double)TimeFrameToMinutes(Chart.TimeFrame) : 0.0;
            if (chartMinutes <= 0)
                chartMinutes = Math.Max(1.0, periodMinutes * 0.12);

            glyphCenterTime = periodStartTime.AddMinutes(periodMinutes * 0.5);
            var glyphWidthMinutes = Math.Max(0.4, Math.Min(periodMinutes * 0.18, chartMinutes * 0.70));
            var eventBoxWidthMinutes = Math.Max(
                glyphWidthMinutes + 0.2,
                Math.Min(periodMinutes * 0.24, chartMinutes));
            glyphStartTime = glyphCenterTime.AddMinutes(glyphWidthMinutes * -0.5);
            glyphEndTime = glyphCenterTime.AddMinutes(glyphWidthMinutes * 0.5);
            eventBoxStartTime = glyphCenterTime.AddMinutes(eventBoxWidthMinutes * -0.5);
            eventBoxEndTime = glyphCenterTime.AddMinutes(eventBoxWidthMinutes * 0.5);
        }

        private void ResolveHtfCandleGlyphBodyTimeRange(
            DateTime periodStartTime,
            DateTime periodEndTime,
            out DateTime glyphStartTime,
            out DateTime glyphEndTime)
        {
            DateTime glyphCenterTime;
            DateTime eventBoxStartTime;
            DateTime eventBoxEndTime;
            ResolveHtfCandleGlyphTimeRange(
                periodStartTime,
                periodEndTime,
                out glyphCenterTime,
                out glyphStartTime,
                out glyphEndTime,
                out eventBoxStartTime,
                out eventBoxEndTime);
        }

        private int DrawBackgroundCandleOverlayAtIndex(int objectIndex, Bars sourceBars, TimeFrame sourceTimeFrame, int sourceIndex, string objectPrefix, string overlayLabel = null)
        {
            if (sourceBars == null || sourceIndex < 0 || sourceIndex >= sourceBars.Count)
                return objectIndex;

            var startTime = sourceBars.OpenTimes[sourceIndex];
            var endTime = sourceIndex + 1 < sourceBars.Count
                ? sourceBars.OpenTimes[sourceIndex + 1]
                : startTime.AddMinutes(Math.Max(1, TimeFrameToMinutes(sourceTimeFrame)));
            if (endTime <= startTime)
                endTime = startTime.AddMinutes(Math.Max(1, TimeFrameToMinutes(sourceTimeFrame)));
            var chartBars = GetCurrentChartVisualBars();
            if (chartBars != null && chartBars.Count > 0 && endTime < chartBars.OpenTimes[0])
                return objectIndex;

            var open = sourceBars.OpenPrices[sourceIndex];
            var close = sourceBars.ClosePrices[sourceIndex];
            var high = sourceBars.HighPrices[sourceIndex];
            var low = sourceBars.LowPrices[sourceIndex];
            DateTime candleStartTime;
            DateTime candleEndTime;
            ResolveHtfCandleGlyphBodyTimeRange(
                startTime,
                endTime,
                out candleStartTime,
                out candleEndTime);

            var isBullish = close >= open;
            // Lower alpha = more translucent = blurrier background. Reduced from 34/22/96 so
            // the HTF background candles sit softer under the current-TF candles.
            var bullishFill = Color.FromArgb(24, 38, 166, 154);
            var bearishFill = Color.FromArgb(24, 239, 83, 80);
            var bullishWickFill = Color.FromArgb(14, 38, 166, 154);
            var bearishWickFill = Color.FromArgb(14, 239, 83, 80);
            var wickFill = isBullish ? bullishWickFill : bearishWickFill;
            var bodyFill = isBullish ? bullishFill : bearishFill;
            var directionalColor = isBullish
                ? Color.FromArgb(255, 38, 166, 154)
                : Color.FromArgb(255, 239, 83, 80);
            var borderColor = WithAlpha(directionalColor, 90);

            var nextObjectIndex = DrawBlurredCandleOverlay(
                objectPrefix,
                objectIndex,
                candleStartTime,
                candleEndTime,
                high,
                low,
                open,
                close,
                wickFill,
                borderColor,
                bodyFill,
                borderColor);

            return nextObjectIndex;
        }

        // Two independent layers per configured HTF slot:
        //  1) the last completed candle (plain background candle), and
        //  2) the latest completed pattern candle (background candle + surrounding box).
        // When both resolve to the same candle, the combined version is drawn only once.
        private int DrawHtfCandlePatternBoxes(int objectIndex, HashSet<string> drawnCandleKeys)
        {
            var chartTimeFrame = Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
            var chartTfMinutes = TimeFrameToMinutes(chartTimeFrame);
            if (chartTfMinutes <= 0)
                return objectIndex;
            if (ChartObjectsOverBudget())
                return objectIndex;

            try
            {
                var higherFrames = GetEnabledAutoHigherTimeframes(chartTimeFrame)
                    .Where(tf => TimeFrameToMinutes(tf) > chartTfMinutes)
                    .Distinct()
                    .OrderBy(tf => TimeFrameToMinutes(tf))
                    .ToList();
                foreach (var sourceTimeFrame in higherFrames)
                {
                    var sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, Chart.SymbolName);
                    if (sourceBars == null || sourceBars.Count < 4)
                        continue;

                    int completedIndex;
                    if (!TryGetPreviousCompletedPeriodBarIndex(sourceBars, sourceTimeFrame, out completedIndex))
                        continue;

                    var objectPrefix = "HTFBOX_" + GetMiniChartLabel(sourceTimeFrame);
                    if (ShouldDrawHtfBackground())
                    {
                        objectIndex = DrawCompletedHtfBackgroundAtIndex(
                            objectIndex,
                            sourceBars,
                            sourceTimeFrame,
                            completedIndex,
                            objectPrefix + "_LAST",
                            drawnCandleKeys);
                    }

                    int latestPatternIndex;
                    if (!TryGetLatestPatternQualifiedBarIndex(sourceBars, sourceTimeFrame, out latestPatternIndex))
                        continue;

                    var patternCandleKey = BuildHtfBackgroundCandleKey(sourceBars, sourceTimeFrame, latestPatternIndex);
                    var patternKey = "pattern|" + patternCandleKey;
                    if (string.IsNullOrWhiteSpace(patternCandleKey) ||
                        (drawnCandleKeys != null && !drawnCandleKeys.Add(patternKey)))
                        continue;

                    objectIndex = DrawHtfCompletedCandleHighlight(
                        objectIndex,
                        sourceBars,
                        sourceTimeFrame,
                        latestPatternIndex,
                        objectPrefix + "_PAT",
                        false);
                }
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] HTF box skipped: {0}", ex.Message);
            }

            return objectIndex;
        }

        // HTF candle highlight for the selected HTF candle, bottom -> top:
        //  1. high & low guide lines (always)
        //  2. narrow trigger-event box (green/red by pattern direction, independent of candle direction)
        //  3. background HTF candle (wick + body) on top of the box with LOWER alpha (always),
        //     plus the "{tf}.{pattern}" label (e.g. "4h.pin") when a pattern matched.
        private int DrawHtfCompletedCandleHighlight(int objectIndex, Bars sourceBars, TimeFrame sourceTimeFrame, int sourceIndex, string objectPrefix, bool drawGuides = true)
        {
            if (Chart == null || sourceBars == null || sourceIndex < 0 || sourceIndex >= sourceBars.Count)
                return objectIndex;

            var startTime = sourceBars.OpenTimes[sourceIndex];
            var endTime = sourceIndex + 1 < sourceBars.Count
                ? sourceBars.OpenTimes[sourceIndex + 1]
                : startTime.AddMinutes(Math.Max(1, TimeFrameToMinutes(sourceTimeFrame)));
            if (endTime <= startTime)
                endTime = startTime.AddMinutes(Math.Max(1, TimeFrameToMinutes(sourceTimeFrame)));
            var chartBars = GetCurrentChartVisualBars();
            if (chartBars != null && chartBars.Count > 0 && endTime < chartBars.OpenTimes[0])
                return objectIndex;

            var high = sourceBars.HighPrices[sourceIndex];
            var low = sourceBars.LowPrices[sourceIndex];
            if (!IsFiniteNumber(high) || !IsFiniteNumber(low))
                return objectIndex;

            var open = sourceBars.OpenPrices[sourceIndex];
            var close = sourceBars.ClosePrices[sourceIndex];
            var candleIsBullish = close >= open;
            string patternCode;
            bool eventIsBullish;
            if (!TryResolveHtfCandlePatternEvent(sourceBars, sourceTimeFrame, sourceIndex, out patternCode, out eventIsBullish))
                return objectIndex;
            var baseColor = GetTimeFrameStructureColor(sourceTimeFrame);
            var objId = objectIndex.ToString(CultureInfo.InvariantCulture);
            PrintBypassLogFilter(
                "[HTFHL] frame={0} idx={1} start={2:yyyy-MM-dd HH:mm} end={3:yyyy-MM-dd HH:mm} chartLast={4:yyyy-MM-dd HH:mm} nowUtc={5:yyyy-MM-dd HH:mm}",
                GetMiniChartLabel(sourceTimeFrame),
                sourceIndex,
                startTime,
                endTime,
                Bars != null && Bars.Count > 0 ? Bars.OpenTimes[Bars.Count - 1] : DateTime.MinValue,
                NormalizeBotTimeToUtc(Server.Time));

            if (drawGuides)
                objectIndex = DrawHtfCompletedBarHighLowGuides(objectIndex, sourceBars, sourceTimeFrame, sourceIndex, objectPrefix);

            // 2) Surround only the trigger bar, centered on the HTF candle glyph. The event
            // direction comes from the matched pattern definition and deliberately remains
            // independent of the candle's own open/close direction.
            var boxColor = eventIsBullish
                ? Color.FromArgb(255, 34, 139, 34)
                : Color.FromArgb(255, 239, 68, 68);
            var boxFill = WithAlpha(boxColor, 30);
            var eventRange = ResolvePatternRangeBox(sourceBars, sourceTimeFrame, sourceIndex, 1);
            DateTime glyphCenterTime;
            DateTime glyphStartTime;
            DateTime glyphEndTime;
            DateTime triggerStartTime;
            DateTime triggerEndTime;
            ResolveHtfCandleGlyphTimeRange(
                startTime,
                endTime,
                out glyphCenterTime,
                out glyphStartTime,
                out glyphEndTime,
                out triggerStartTime,
                out triggerEndTime);
            var boxHigh = eventRange != null ? eventRange.Item3 : high;
            var boxLow = eventRange != null ? eventRange.Item4 : low;
            var box = Chart.DrawRectangle(objectPrefix + "_BOX_" + objId, triggerStartTime, boxHigh, triggerEndTime, boxLow, boxFill);
            TrySetPropertyValue(box, "IsFilled", true);
            TrySetPropertyValue(box, "Thickness", 1);
            TrySetPropertyValue(box, "Color", boxFill);
            TrySetPropertyValue(box, "BorderColor", WithAlpha(boxColor, 30));
            TrySetPropertyValue(box, "ZIndex", 4);
            objectIndex++;

            // 3) Always draw the background HTF candle (wick + body) on top of the box, with
            //    LOWER alpha than the box. Its bullish/bearish color stays OHLC-based.
            Print(string.Format(CultureInfo.InvariantCulture, "[HTFHL] frame={0} idx={1} pattern='{2}'", GetMiniChartLabel(sourceTimeFrame), sourceIndex, string.IsNullOrWhiteSpace(patternCode) ? "none" : patternCode));

            var bullishCandle = Color.FromArgb(38, 166, 154);
            var bearishCandle = Color.FromArgb(239, 83, 80);
            var candleColor = candleIsBullish ? bullishCandle : bearishCandle;
            // Filled strips (same mechanism as the background candle path) so body vs wick
            // separation is actually visible on top of the blurry box. Not pushed to
            // background so the candle stays above the surrounding box (ZIndex 4).
            var wickFill = WithAlpha(candleColor, 16);
            var bodyFill = WithAlpha(candleColor, 34);
            var wickBorderColor = WithAlpha(candleColor, 110);
            var bodyBorder = WithAlpha(candleColor, 110);
            var bodyHigh = Math.Max(open, close);
            var bodyLow = Math.Min(open, close);
            var glyphDurationMinutes = Math.Max(0.4, (glyphEndTime - glyphStartTime).TotalMinutes);
            var wickStart = glyphStartTime.AddMinutes(glyphDurationMinutes * 0.44);
            var wickEnd = glyphStartTime.AddMinutes(glyphDurationMinutes * 0.56);
            if (wickEnd <= wickStart)
                wickEnd = wickStart.AddMinutes(0.2);

            // Wick strips (upper + lower): faint fill, edge at the body boundary.
            if (high > bodyHigh)
            {
                var upperWick = Chart.DrawRectangle(objectPrefix + "_WICK_U_" + objId, wickStart, high, wickEnd, bodyHigh, wickFill);
                TrySetPropertyValue(upperWick, "IsFilled", true);
                TrySetPropertyValue(upperWick, "Color", wickFill);
                TrySetPropertyValue(upperWick, "BorderColor", wickBorderColor);
                TrySetPropertyValue(upperWick, "Thickness", 1);
                TrySetPropertyValue(upperWick, "ZIndex", 5);
            }
            if (bodyLow > low)
            {
                var lowerWick = Chart.DrawRectangle(objectPrefix + "_WICK_L_" + objId, wickStart, bodyLow, wickEnd, low, wickFill);
                TrySetPropertyValue(lowerWick, "IsFilled", true);
                TrySetPropertyValue(lowerWick, "Color", wickFill);
                TrySetPropertyValue(lowerWick, "BorderColor", wickBorderColor);
                TrySetPropertyValue(lowerWick, "Thickness", 1);
                TrySetPropertyValue(lowerWick, "ZIndex", 5);
            }

            // Body strip: stronger fill than the wicks so the candle body stands out.
            var body = Chart.DrawRectangle(objectPrefix + "_BODY_" + objId, glyphStartTime, bodyHigh, glyphEndTime, bodyLow, bodyFill);
            TrySetPropertyValue(body, "IsFilled", true);
            TrySetPropertyValue(body, "Color", bodyFill);
            TrySetPropertyValue(body, "BorderColor", bodyBorder);
            TrySetPropertyValue(body, "Thickness", 1);
            TrySetPropertyValue(body, "ZIndex", 5);
            objectIndex++;

            if (string.IsNullOrWhiteSpace(patternCode))
                return objectIndex;

            var label = string.Format(
                CultureInfo.InvariantCulture,
                "{0}.{1}",
                GetTimeFrameShortLabel(sourceTimeFrame),
                patternCode);
            var labelTime = glyphCenterTime;
            var labelRange = Math.Max(high - low, Symbol != null ? Symbol.PipSize * 8.0 : 0.0000001);
            var labelPad = Math.Max(Symbol != null ? Symbol.PipSize * 2.0 : 0.0000001, labelRange * 0.035);
            var labelPrice = eventIsBullish ? low - labelPad : high + labelPad;
            var text = Chart.DrawText(objectPrefix + "_TXT_" + objId, label, labelTime, labelPrice, baseColor);
            TryStyleChartText(text, GetNormalChartLabelFontSize(), "Courier New", true);
            TrySetPropertyValue(text, "ZIndex", 6);
            return objectIndex;
        }

        private int DrawHtfCompletedBarHighLowGuides(int objectIndex, Bars sourceBars, TimeFrame sourceTimeFrame, int sourceIndex, string objectPrefix)
        {
            if (Chart == null || sourceBars == null || sourceIndex < 0 || sourceIndex >= sourceBars.Count)
                return objectIndex;

            var startTime = sourceBars.OpenTimes[sourceIndex];
            var endTime = sourceIndex + 1 < sourceBars.Count
                ? sourceBars.OpenTimes[sourceIndex + 1]
                : startTime.AddMinutes(Math.Max(1, TimeFrameToMinutes(sourceTimeFrame)));
            if (endTime <= startTime)
                endTime = startTime.AddMinutes(Math.Max(1, TimeFrameToMinutes(sourceTimeFrame)));
            var chartBars = GetCurrentChartVisualBars();
            if (chartBars != null && chartBars.Count > 0 && endTime < chartBars.OpenTimes[0])
                return objectIndex;

            var high = sourceBars.HighPrices[sourceIndex];
            var low = sourceBars.LowPrices[sourceIndex];
            if (!IsFiniteNumber(high) || !IsFiniteNumber(low))
                return objectIndex;

            var baseColor = GetTimeFrameStructureColor(sourceTimeFrame);
            var objId = objectIndex.ToString(CultureInfo.InvariantCulture);

            // Preserve the completed HTF candle itself as the primary reference; only its
            // projection into later/current price action is visually muted.
            var completedColor = WithAlpha(baseColor, 100);
            var liveColor = WithAlpha(baseColor, 30);
            var highLine = Chart.DrawTrendLine(objectPrefix + "_H_DONE_" + objId, startTime, high, endTime, high, completedColor);
            TrySetPropertyValue(highLine, "Thickness", 1);
            TrySetEnumPropertyValue(highLine, "LineStyle", "Solid");
            TrySetPropertyValue(highLine, "ZIndex", 3);
            var lowLine = Chart.DrawTrendLine(objectPrefix + "_L_DONE_" + objId, startTime, low, endTime, low, completedColor);
            TrySetPropertyValue(lowLine, "Thickness", 1);
            TrySetEnumPropertyValue(lowLine, "LineStyle", "Solid");
            TrySetPropertyValue(lowLine, "ZIndex", 3);

            var liveEndTime = NormalizeBotTimeToUtc(Server.Time);
            if (liveEndTime <= endTime)
                liveEndTime = GetCurrentChartEndTime();
            if (liveEndTime > endTime)
            {
                var highProjection = Chart.DrawTrendLine(objectPrefix + "_H_LIVE_" + objId, endTime, high, liveEndTime, high, liveColor);
                TrySetPropertyValue(highProjection, "Thickness", 1);
                TrySetEnumPropertyValue(highProjection, "LineStyle", "Dots");
                TrySetPropertyValue(highProjection, "ZIndex", 3);
                var lowProjection = Chart.DrawTrendLine(objectPrefix + "_L_LIVE_" + objId, endTime, low, liveEndTime, low, liveColor);
                TrySetPropertyValue(lowProjection, "Thickness", 1);
                TrySetEnumPropertyValue(lowProjection, "LineStyle", "Dots");
                TrySetPropertyValue(lowProjection, "ZIndex", 3);
            }
            return objectIndex + 1;
        }

        private bool TryGetLatestPatternQualifiedBarIndex(Bars sourceBars, TimeFrame sourceTimeFrame, out int sourceIndex)
        {
            sourceIndex = -1;
            if (sourceBars == null || sourceBars.Count < 4)
                return false;

            var patternDefinitions = BuildEnabledCandlePatternDefinitions();
            if (patternDefinitions == null || patternDefinitions.Count == 0)
                return false;

            int lastCompletedIndex;
            if (!TryGetPreviousCompletedPeriodBarIndex(sourceBars, sourceTimeFrame, out lastCompletedIndex))
                return false;

            for (var i = lastCompletedIndex; i >= 1; i--)
            {
                if (HasAnyEnabledCandlePatternAtIndex(sourceBars, sourceTimeFrame, i, patternDefinitions))
                {
                    sourceIndex = i;
                    return true;
                }
            }

            return false;
        }

        // Resolve the first enabled pattern matching the trigger bar. Direction belongs to
        // the event definition, not to the trigger candle's open/close direction.
        private bool TryResolveHtfCandlePatternEvent(Bars sourceBars, TimeFrame sourceTimeFrame, int barIndex, out string patternCode, out bool isBullish)
        {
            patternCode = "";
            isBullish = false;
            if (sourceBars == null || barIndex < 0 || barIndex >= sourceBars.Count)
                return false;
            var definitions = BuildEnabledCandlePatternDefinitions();
            if (definitions == null || definitions.Count == 0)
                return false;
            foreach (var definition in definitions)
            {
                if (definition == null)
                    continue;
                var matched = definition.NativeMatch != null
                    ? definition.NativeMatch(sourceBars, barIndex)
                    : (!string.IsNullOrWhiteSpace(definition.SharedPatternType) &&
                       GetDetectedSharedRulePatternSet(sourceBars, sourceTimeFrame, barIndex).Contains(definition.SharedPatternType));
                if (!matched)
                    continue;
                patternCode = (definition.ShortLabel ?? "").Trim().ToLowerInvariant();
                isBullish = definition.IsBullish;
                return true;
            }
            return false;
        }

        // Pattern short code of the first enabled pattern matching the bar, or "" when none.
        private string TryResolveHtfCandlePatternCode(Bars sourceBars, TimeFrame sourceTimeFrame, int barIndex)
        {
            string patternCode;
            bool isBullish;
            return TryResolveHtfCandlePatternEvent(sourceBars, sourceTimeFrame, barIndex, out patternCode, out isBullish)
                ? patternCode
                : "";
        }

        private Color GetSessionAccentColor(string sessionName)
        {
            switch (NormalizeSessionAlias(sessionName))
            {
                case "Asia":
                    return Color.FromArgb(235, 0, 224, 255);
                case "London":
                    return Color.FromArgb(235, 110, 255, 120);
                case "NewYork":
                    return Color.FromArgb(235, 255, 196, 64);
                default:
                    return Color.FromArgb(235, 180, 180, 180);
            }
        }

        private Color GetSessionLabelColor()
        {
            return Color.FromArgb(235, 210, 210, 210);
        }

        private bool TryGetKillerZoneProjectionEnd(string sessionName, DateTime date, bool useFullSession, DateTime sessionEndUtc, out DateTime projectionEndUtc)
        {
            projectionEndUtc = sessionEndUtc;
            var normalized = NormalizeSessionAlias(sessionName);
            var nextSession = normalized == "Asia" ? "London" : normalized == "London" ? "NewYork" : normalized == "NewYork" ? "Asia" : "";
            if (string.IsNullOrWhiteSpace(nextSession))
                return false;

            // NY hands off to the following Asia session; Asia and London use the same
            // reference market date. The time-zone-aware range resolver handles DST.
            var nextDate = normalized == "NewYork" ? date.Date.AddDays(1) : date.Date;
            DateTime nextStartUtc;
            DateTime nextEndUtc;
            if (!TryGetContextUtcRange(nextSession, nextDate, useFullSession, out nextStartUtc, out nextEndUtc))
                return false;
            if (nextEndUtc <= sessionEndUtc)
                return false;

            projectionEndUtc = nextEndUtc;
            return true;
        }

        private bool TryGetKillerZoneUtcRange(string sessionName, DateTime referenceDate, out DateTime startUtc, out DateTime endUtc)
        {
            startUtc = DateTime.MinValue;
            endUtc = DateTime.MinValue;

            SessionWindowDefinition definition;
            if (!TryGetSessionWindowDefinition(sessionName, out definition))
                return false;

            TimeZoneInfo timeZone;
            if (!TryGetSessionTimeZone(definition, out timeZone))
                return false;

            var localDate = referenceDate.Date;
            var localStart = DateTime.SpecifyKind(localDate.Add(definition.LocalStart), DateTimeKind.Unspecified);
            var localEnd = localStart.AddHours(3);
            var fullLocalEnd = DateTime.SpecifyKind(localDate.Add(definition.LocalEnd), DateTimeKind.Unspecified);
            if (localEnd > fullLocalEnd)
                localEnd = fullLocalEnd;

            startUtc = TimeZoneInfo.ConvertTimeToUtc(localStart, timeZone);
            endUtc = TimeZoneInfo.ConvertTimeToUtc(localEnd, timeZone);
            return endUtc > startUtc;
        }

        private bool TryGetContextUtcRange(string sessionName, DateTime referenceDate, bool useFullSession, out DateTime startUtc, out DateTime endUtc)
        {
            if (useFullSession)
                return TryGetSessionUtcRange(sessionName, referenceDate, out startUtc, out endUtc);

            return TryGetKillerZoneUtcRange(sessionName, referenceDate, out startUtc, out endUtc);
        }

        // Splitter Grid:
        // - Auto: draw a ladder of higher-timeframe splitter families (clearer as TF rises).
        // - Fixed: draw a single splitter family at the selected fixed step.
        private int DrawFourHourSplitters(int objectIndex)
        {
            if (Bars == null || Bars.Count < 2)
                return objectIndex;

            var chartTfMinutes = Math.Max(1, TimeFrameToMinutes(Chart != null ? Chart.TimeFrame : TimeFrame.Minute));

            RemoveChartObjectsByPrefixes("H4SPLIT_", "DSPLIT_", "SPLIT_", "SPLIT1_", "SPLIT2_", "SPLIT_FIXED_");

            if (DrawSplitterGrid == SplitterGridMode.No)
            {
                return objectIndex;
            }

            try
            {
                if (DrawSplitterGrid == SplitterGridMode.Auto)
                {
                    var drawnFrames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    foreach (var splitTimeFrame in GetAutoSplitterTimeFrames(Chart != null ? Chart.TimeFrame : TimeFrame.Minute))
                    {
                        if (splitTimeFrame == null)
                            continue;

                        var splitLabel = GetMiniChartLabel(splitTimeFrame);
                        if (!drawnFrames.Add(splitLabel))
                            continue;

                        ResolveAutoSplitterStyle(splitTimeFrame, out var styledColor, out var thickness, out var lineStyle);
                        objectIndex = DrawSplitterFamily(
                            objectIndex,
                            splitTimeFrame,
                            "SPLIT_" + splitLabel + "_",
                            styledColor,
                            thickness,
                            lineStyle);
                    }
                    return objectIndex;
                }

                var stepMinutes = ResolveSplitterGridStepMinutes(chartTfMinutes);
                if (stepMinutes <= 0)
                    return objectIndex;
                objectIndex = DrawSplitterFamily(
                    objectIndex,
                    null,
                    "SPLIT_FIXED_",
                    WithAlpha(Color.White, 40),
                    1,
                    "Dots",
                    stepMinutes);
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Splitter grid skipped: {0}", ex.Message);
            }

            return objectIndex;
        }

        private List<TimeFrame> GetAutoSplitterTimeFrames(TimeFrame chartTimeFrame)
        {
            return CTraderChartEngine.GetAutoSplitterTimeFrames(chartTimeFrame);
        }

        private void ResolveAutoSplitterStyle(TimeFrame splitTimeFrame, out Color color, out int thickness, out string lineStyle)
        {
            var style = CTraderChartEngine.ResolveAutoSplitterStyle(
                splitTimeFrame, GetTimeFrameStructureColor(splitTimeFrame));
            color = style.Color;
            thickness = style.Thickness;
            lineStyle = style.LineStyle;
        }

        private int DrawSplitterFamily(
            int objectIndex,
            TimeFrame splitTimeFrame,
            string objectPrefix,
            Color splitterColor,
            int thickness,
            string lineStyle,
            int explicitStepMinutes = 0)
        {
            if (Bars == null || Bars.Count < 2)
                return objectIndex;

            var chartTfMinutes = Math.Max(1, TimeFrameToMinutes(Chart != null ? Chart.TimeFrame : TimeFrame.Minute));
            var stepMinutes = explicitStepMinutes > 0
                ? explicitStepMinutes
                : Math.Max(1, TimeFrameToMinutes(splitTimeFrame));
            if (stepMinutes <= 0)
                return objectIndex;

            var chartStart = Bars.OpenTimes[0];
            var chartEnd = GetCurrentChartEndTime();
            if (chartEnd <= chartStart)
                return objectIndex;

            var baseTf = ResolveSplitterBaseTimeFrame(stepMinutes, out int baseMinutes, out int nth);
            if (baseTf == null)
                return objectIndex;
            var baseBars = GetBarsForCurrentMasterTimer(baseTf, Chart.SymbolName);
            if (baseBars == null || baseBars.Count < 2)
                return objectIndex;

            var boundaries = new List<DateTime>();
            DateTime? lastBoundary = null;
            var absoluteIndex = 0;
            foreach (var boundary in baseBars.OpenTimes)
            {
                if (boundary > chartEnd)
                    break;
                if (absoluteIndex % nth == 0 && boundary >= chartStart)
                {
                    boundaries.Add(boundary);
                    lastBoundary = boundary;
                }
                absoluteIndex++;
            }

            if (lastBoundary.HasValue)
            {
                // Extend from the last REAL broker boundary, not from calendar midnight.
                // This keeps higher-timeframe splitters aligned with lower-timeframe families
                // (for example d1 landing exactly on the 6th h4 line).
                var extensionLimit = GetNextDayStartTime(chartEnd).AddMinutes(stepMinutes);
                var nextBoundary = lastBoundary.Value.AddMinutes(stepMinutes);
                while (nextBoundary <= extensionLimit)
                {
                    boundaries.Add(nextBoundary);
                    nextBoundary = nextBoundary.AddMinutes(stepMinutes);
                }
            }

            boundaries = boundaries
                .Distinct()
                .OrderBy(boundary => boundary)
                .TakeLast(MaxSplitterObjects)
                .ToList();

            foreach (var boundary in boundaries)
            {
                var splitter = Chart.DrawVerticalLine(
                    objectPrefix + objectIndex.ToString(CultureInfo.InvariantCulture),
                    boundary,
                    splitterColor);
                TrySetPropertyValue(splitter, "Thickness", Math.Max(1, thickness));
                TrySetEnumPropertyValue(splitter, "LineStyle", lineStyle);
                objectIndex++;
            }

            return objectIndex;
        }

        // Splitter Grid step in minutes: Auto = HTF1 (first auto higher timeframe slot).
        private int ResolveSplitterGridStepMinutes(int chartTfMinutes)
        {
            switch (DrawSplitterGrid)
            {
                case SplitterGridMode.Auto:
                    var htf1 = ResolveConfiguredHtfSlotTimeFrame(Chart != null ? Chart.TimeFrame : TimeFrame.Minute, 0);
                    return htf1 != null ? Math.Max(1, TimeFrameToMinutes(htf1)) : 0;
                case SplitterGridMode.m30:
                    return 30;
                case SplitterGridMode.h1:
                    return 60;
                case SplitterGridMode.h2:
                    return 120;
                case SplitterGridMode.h4:
                    return 240;
                case SplitterGridMode.h8:
                    return 480;
                case SplitterGridMode.d1:
                    return 1440;
                case SplitterGridMode.w1:
                    return 10080;
                default:
                    return 0; // No
            }
        }

        // Largest native timeframe that divides the step evenly, so non-native steps (2h/8h)
        // still land on real bar boundaries; N = number of base bars per step.
        private TimeFrame ResolveSplitterBaseTimeFrame(int stepMinutes, out int baseMinutes, out int nth)
        {
            return CTraderChartEngine.ResolveSplitterBaseTimeFrame(stepMinutes, out baseMinutes, out nth);
        }

        private int DrawHtfMiniCharts(int objectIndex)
        {
            var chartTimeFrame = Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
            var chartTfMinutes = TimeFrameToMinutes(chartTimeFrame);
            var chartBars = GetCurrentChartVisualBars();
            if (chartTfMinutes <= 0 || chartBars == null || chartBars.Count < 40)
                return objectIndex;
            if (ChartObjectsOverBudget())
                return objectIndex;

            try
            {
                // HTF1 (lower TF) leads the strip and its first bar starts exactly on the
                // day splitter; HTF2 follows after the divider. Order by TF size ascending
                // so the finer frame is drawn first (HTF1 -> HTF2).
                var miniFrames = GetEnabledAutoHigherTimeframes(chartTimeFrame)
                    .Where(tf => TimeFrameToMinutes(tf) > chartTfMinutes)
                    .OrderBy(tf => TimeFrameToMinutes(tf))
                    .Take(2)
                    .ToList();
                if (miniFrames.Count == 0)
                {
                    SafePrint("[Mini] {0} chartTf={1} frames=none mode={2} auto1={3} auto2={4}", Chart != null ? Chart.SymbolName : "", chartTfMinutes, DrawHtfMiniChartMode, DrawAutoHtf1, DrawAutoHtf2);
                    return objectIndex;
                }

                // Shared price levels: lowest low (label baseline) and highest high across all
                // mini frames so labels and the divider line align across the slots.
                var sharedLabelPrice = double.MaxValue;
                var sharedHighPrice = double.MinValue;
                foreach (var tf in miniFrames)
                {
                    var effectiveCount = GetMiniChartBarsForTimeFrame(tf);
                    sharedLabelPrice = Math.Min(sharedLabelPrice, GetMiniChartWindowedLow(tf, effectiveCount));
                    sharedHighPrice = Math.Max(sharedHighPrice, GetMiniChartWindowedHigh(tf, effectiveCount));
                }
                if (sharedLabelPrice == double.MaxValue || sharedLabelPrice <= 0)
                    sharedLabelPrice = 0;
                if (sharedHighPrice == double.MinValue || sharedHighPrice <= 0)
                {
                    var chartSymbol = ResolveLoadedSymbol(Chart != null ? Chart.SymbolName : "") ?? Symbol;
                    var chartPipSize = chartSymbol != null ? chartSymbol.PipSize : 0.0000001;
                    sharedHighPrice = sharedLabelPrice > 0 ? sharedLabelPrice + Math.Max(chartPipSize * 200.0, 0.000001) : 0;
                }

                // Each mini candle is roughly 3 chart bars wide (per-frame, sized by the
                // frame's own candle count) so the strip stays compact.
                const double slotSpacingBars = 6.0;
                // Lead gap: the strip anchors to the NEXT 4H boundary on low timeframes
                // (1m/5m) — anchoring to tomorrow would leave a full day of empty space —
                // and to the next day boundary on higher TFs. HTF1 is drawn one chart-bar
                // width to the LEFT of the anchor (see the slot loop below).
                var chartEndTime = GetCurrentChartEndTime();
                var leadGapBars = GetMiniChartLeadGapBars(chartTfMinutes);
                objectIndex = DrawMiniChartSpacer(chartTfMinutes, GetMiniChartTotalFutureBars(chartTfMinutes), objectIndex);

                var futureOffsetBars = leadGapBars;
                SafePrint("[Mini] {0} chartTf={1} frames={2} leadGap={3:F1} mode={4}",
                    Chart != null ? Chart.SymbolName : "",
                    chartTfMinutes,
                    string.Join("/", miniFrames.Select(tf => GetMiniChartDisplayLabel(tf))),
                    leadGapBars,
                    DrawHtfMiniChartMode);
                for (var slotIndex = 0; slotIndex < miniFrames.Count; slotIndex++)
                {
                    try
                    {
                        var tf = miniFrames[slotIndex];
                        // Per-timeframe mini chart config: bar count and candle width are
                        // keyed by the frame (D=7×2, W=4×3, 4H=12×1, 1H/15m=24×1).
                        var miniBarCount = GetMiniChartBarsForTimeFrame(tf);
                        var slotWidthBars = GetMiniChartSlotWidthBars(tf, miniBarCount);
                        // HTF1 (slot 0) sits one chart-bar width to the LEFT of the day splitter;
                        // the divider follows it so the spacing to HTF2 stays symmetric.
                        var slotStartBars = slotIndex == 0
                            ? Math.Max(0.0, futureOffsetBars - 1.0)
                            : futureOffsetBars;
                        objectIndex = DrawSingleMiniChart(tf, chartTfMinutes, slotStartBars, slotIndex, objectIndex, sharedLabelPrice, miniBarCount, slotWidthBars);

                        // Tiny dotted vertical divider between the mini charts.
                        if (slotIndex < miniFrames.Count - 1)
                        {
                            var dividerBars = slotStartBars + slotWidthBars + (slotSpacingBars * 0.5);
                            var dividerBarIndex = chartBars.Count + (int)Math.Round(dividerBars);
                            var divider = Chart.DrawVerticalLine(
                                "MINI_DIV_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                                dividerBarIndex,
                                WithAlpha(Color.White, 25));
                            TrySetPropertyValue(divider, "Thickness", 1);
                            TrySetEnumPropertyValue(divider, "LineStyle", "Dots");
                            objectIndex++;
                        }

                        futureOffsetBars += slotWidthBars + slotSpacingBars;
                    }
                    catch (Exception ex)
                    {
                        SafePrint("[Mini] Slot {0} ({1}) skipped: {2}", slotIndex, GetMiniChartDisplayLabel(miniFrames[slotIndex]), ex.Message);
                        futureOffsetBars += slotSpacingBars;
                    }
                }
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] HTF mini chart skipped: {0}", ex.Message);
            }

            return objectIndex;
        }

        // Lead gap (in chart-TF bars) between the last bar and the start of the HTF mini
        // chart strip. The strip should always begin AFTER the next daily edge so it never
        // occupies the space before the final day splitter.
        private double GetMiniChartLeadGapBars(int chartTfMinutes)
        {
            try
            {
                var chartEndTime = GetCurrentChartEndTime();
                var anchorStart = GetNextDayStartTime(chartEndTime);

                var naturalGapBars = Math.Max(0.0, (anchorStart - chartEndTime).TotalMinutes / Math.Max(1, chartTfMinutes));
                return Math.Max(MiniChartStartAfterLabelColumnsBars, naturalGapBars);
            }
            catch
            {
                return MiniChartStartAfterLabelColumnsBars;
            }
        }

        // Both HTF slots use the same candle width so their bodies and centered wicks
        // remain visually aligned regardless of the source timeframe.
        private double GetMiniChartSlotWidthBars(TimeFrame timeFrame, int miniBarCount)
        {
            return CTraderChartEngine.GetMiniChartSlotWidth(
                miniBarCount, GetMiniChartBarWidthBars(timeFrame));
        }

        // Candle width in normal chart bars, shared by HTF1 and HTF2.
        private double GetMiniChartBarWidthBars(TimeFrame timeFrame)
        {
            return MiniChartCandleWidthBars;
        }

        // Total width (in chart-TF bars) of the HTF mini chart area to the right of the
        // last bar: next-day lead gap + day-split slots + divider spacing + trailing pad.
        // Shared by DrawHtfMiniCharts and the zoom buttons so the viewport can end exactly
        // at the mini chart's right edge (no dead space).
        private double GetMiniChartTotalFutureBars(int chartTfMinutes)
        {
            try
            {
                var miniFrames = GetEnabledAutoHigherTimeframes(Chart != null ? Chart.TimeFrame : TimeFrame.Minute)
                    .Where(tf => TimeFrameToMinutes(tf) > chartTfMinutes)
                    .Take(2)
                    .ToList();
                if (miniFrames.Count == 0)
                    return 0;

                var leadGapBars = GetMiniChartLeadGapBars(chartTfMinutes);
                const double slotSpacingBars = 6.0;

                var totalSlotBars = miniFrames
                    .Select(tf => GetMiniChartSlotWidthBars(tf, GetMiniChartBarsForTimeFrame(tf)))
                    .Sum();
                return leadGapBars + totalSlotBars + (Math.Max(0, miniFrames.Count - 1) * slotSpacingBars) + 2.0;
            }
            catch
            {
                return 0;
            }
        }

        private double GetMiniChartWindowedLow(TimeFrame timeFrame, int miniBarCount = 0)
        {
            try
            {
                var sourceBars = GetBarsForCurrentMasterTimer(timeFrame, Chart.SymbolName);
                if (sourceBars == null || sourceBars.Count < 4)
                    return double.MaxValue;

                var lastVisibleIndex = sourceBars.Count - 1;
                var candlesToDraw = miniBarCount > 0
                    ? Math.Max(2, Math.Min(miniBarCount, lastVisibleIndex + 1))
                    : Math.Max(2, Math.Min(GetMiniChartBarsForTimeFrame(timeFrame), lastVisibleIndex + 1));
                var firstSourceIndex = Math.Max(0, lastVisibleIndex - candlesToDraw + 1);

                var low = double.MaxValue;
                for (var i = firstSourceIndex; i <= lastVisibleIndex; i++)
                    low = Math.Min(low, sourceBars.LowPrices[i]);
                return low;
            }
            catch
            {
                return double.MaxValue;
            }
        }

        private double GetMiniChartWindowedHigh(TimeFrame timeFrame, int miniBarCount = 0)
        {
            try
            {
                var sourceBars = GetBarsForCurrentMasterTimer(timeFrame, Chart.SymbolName);
                if (sourceBars == null || sourceBars.Count < 4)
                    return double.MinValue;

                var lastVisibleIndex = sourceBars.Count - 1;
                var candlesToDraw = miniBarCount > 0
                    ? Math.Max(2, Math.Min(miniBarCount, lastVisibleIndex + 1))
                    : Math.Max(2, Math.Min(GetMiniChartBarsForTimeFrame(timeFrame), lastVisibleIndex + 1));
                var firstSourceIndex = Math.Max(0, lastVisibleIndex - candlesToDraw + 1);

                var high = double.MinValue;
                for (var i = firstSourceIndex; i <= lastVisibleIndex; i++)
                    high = Math.Max(high, sourceBars.HighPrices[i]);
                return high;
            }
            catch
            {
                return double.MinValue;
            }
        }

        private int DrawSingleMiniChart(TimeFrame timeFrame, int chartTfMinutes, double futureOffsetBars, int miniSlotIndex, int objectIndex, double sharedLabelPrice = 0, int miniBarCount = 0, double slotWidthBars = 0)
        {
            var sourceBars = GetBarsForCurrentMasterTimer(timeFrame, Chart.SymbolName);
            var chartBars = GetCurrentChartVisualBars();
            var chartSymbol = ResolveLoadedSymbol(Chart != null ? Chart.SymbolName : "") ?? Symbol;
            if (sourceBars == null || sourceBars.Count < 4 || chartBars == null || chartBars.Count < 4)
                return objectIndex;

            var lastVisibleIndex = sourceBars.Count - 1;
            if (lastVisibleIndex < 0)
                return objectIndex;

            var candlesToDraw = miniBarCount > 0
                ? Math.Max(2, Math.Min(miniBarCount, lastVisibleIndex + 1))
                : Math.Max(2, Math.Min(GetMiniChartBarsForTimeFrame(timeFrame), lastVisibleIndex + 1));
            var firstSourceIndex = Math.Max(0, lastVisibleIndex - candlesToDraw + 1);
            var actualCount = lastVisibleIndex - firstSourceIndex + 1;
            if (actualCount <= 0)
                return objectIndex;

            var priceHigh = double.MinValue;
            var priceLow = double.MaxValue;
            for (var i = firstSourceIndex; i <= lastVisibleIndex; i++)
            {
                priceHigh = Math.Max(priceHigh, sourceBars.HighPrices[i]);
                priceLow = Math.Min(priceLow, sourceBars.LowPrices[i]);
            }

            if (priceHigh <= priceLow || priceHigh == double.MinValue || priceLow == double.MaxValue)
                return objectIndex;

            var tfBaseColor = GetTimeFrameStructureColor(timeFrame);
            var bullishBodyFill = Color.FromArgb(64, 38, 166, 154);
            var bearishBodyFill = Color.FromArgb(64, 239, 83, 80);
            var bullishBorder = Color.FromArgb(220, 38, 166, 154);
            var bearishBorder = Color.FromArgb(220, 239, 83, 80);
            var labelColor = WithAlpha(tfBaseColor, 220);
            var chartPipSize = chartSymbol != null ? chartSymbol.PipSize : 0.0000001;
            var priceRange = Math.Max(priceHigh - priceLow, chartPipSize * 20);
            var displayWidthBars = slotWidthBars > 0 ? slotWidthBars : GetBarsPerFullDay(chartTfMinutes);
            var slotBarWidth = Math.Max(3.0, displayWidthBars / Math.Max(1, actualCount));
            var chartBaseBarIndex = chartBars.Count;
            var labelBarIndex = chartBaseBarIndex + (int)Math.Round(futureOffsetBars + (displayWidthBars * 0.5));
            var slotBarsBySourceIndex = new Dictionary<int, Tuple<int, int>>();

            for (var localIndex = 0; localIndex < actualCount; localIndex++)
            {
                var sourceIndex = firstSourceIndex + localIndex;
                var slotLeftBars = futureOffsetBars + (localIndex * slotBarWidth);
                var slotRightBars = futureOffsetBars + ((localIndex + 1) * slotBarWidth);
                var slotLeftBarIndex = chartBaseBarIndex + (int)Math.Floor(slotLeftBars);
                var slotRightBarIndex = chartBaseBarIndex + (int)Math.Ceiling(slotRightBars);
                var horizontalGapBars = Math.Max(1, (int)Math.Floor((slotRightBarIndex - slotLeftBarIndex) * 0.12));
                var leftBarIndex = slotLeftBarIndex + horizontalGapBars;
                var rightBarIndex = slotRightBarIndex - horizontalGapBars;
                if (rightBarIndex <= leftBarIndex)
                {
                    leftBarIndex = slotLeftBarIndex;
                    rightBarIndex = Math.Max(leftBarIndex + 1, slotRightBarIndex);
                }
                slotBarsBySourceIndex[sourceIndex] = Tuple.Create(leftBarIndex, rightBarIndex);
                var high = sourceBars.HighPrices[sourceIndex];
                var low = sourceBars.LowPrices[sourceIndex];
                var open = sourceBars.OpenPrices[sourceIndex];
                var close = sourceBars.ClosePrices[sourceIndex];
                var isBullish = close >= open;
                var bodyFill = isBullish ? bullishBodyFill : bearishBodyFill;
                var candleBorder = isBullish ? bullishBorder : bearishBorder;
                objectIndex = DrawMiniCandleOverlay(
                    objectIndex,
                    leftBarIndex,
                    rightBarIndex,
                    high,
                    low,
                    open,
                    close,
                    candleBorder,
                    bodyFill,
                    candleBorder);
            }

            // Markers/events are best-effort: a failure here must not kill the candles.
            try
            {
                objectIndex = DrawMiniChartMarkersForTimeFrame(
                    objectIndex,
                    sourceBars,
                    timeFrame,
                    firstSourceIndex,
                    lastVisibleIndex,
                    slotBarsBySourceIndex,
                    priceRange);
            }
            catch (Exception ex)
            {
                SafePrint("[Mini] Marker layer skipped for {0}: {1}", GetMiniChartDisplayLabel(timeFrame), ex.Message);
            }

            try
            {
                // Timeframe tag (e.g. "4H", "D") at the bottom of the mini chart, aligned to the
                // shared price level (lowest low across all mini frames) so labels line up.
                var labelGap = Math.Max(chartPipSize * 20.0, 0.000001);
                var bottomLabelPrice = sharedLabelPrice > 0 ? sharedLabelPrice : priceLow;
                var bottomLabelY = bottomLabelPrice - labelGap;

                var bottomLabelText = Chart.DrawText(
                    "MINI_TXT_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                    GetMiniChartDisplayLabel(timeFrame),
                    labelBarIndex,
                    bottomLabelY,
                    labelColor);
                TryStyleChartText(bottomLabelText, GetNormalChartLabelFontSize(), "Courier New", true);
                TrySetChartObjectBackground(bottomLabelText);
            }
            catch (Exception ex)
            {
                SafePrint("[Mini] Label skipped for {0}: {1}", GetMiniChartDisplayLabel(timeFrame), ex.Message);
            }
            return objectIndex + 1;
        }

        private int DrawMiniChartMarkersForTimeFrame(
            int objectIndex,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int firstSourceIndex,
            int lastVisibleIndex,
            Dictionary<int, Tuple<int, int>> slotBarsBySourceIndex,
            double priceRange)
        {
            if (sourceBars == null || slotBarsBySourceIndex == null || slotBarsBySourceIndex.Count == 0)
                return objectIndex;

            var aggregatedMarkers = new List<DirectionalPatternMarkerAggregate>();

            var patternDefinitions = BuildEnabledCandlePatternDefinitions();
            if (patternDefinitions != null && patternDefinitions.Count > 0)
            {
                CollectRecentDirectionalCandlePatternMarkersOptimized(
                    aggregatedMarkers,
                    sourceBars,
                    sourceTimeFrame,
                    patternDefinitions,
                    firstSourceIndex,
                    Chart != null ? Chart.SymbolName : (Symbol != null ? Symbol.Name : ""));
            }

            foreach (var marker in aggregatedMarkers
                .Where(item => item != null && item.BarIndex >= firstSourceIndex && item.BarIndex <= lastVisibleIndex)
                .Where(item => slotBarsBySourceIndex.ContainsKey(item.BarIndex))
                .OrderByDescending(item => item.BarIndex)
                .ThenBy(item => item.IsNeutral ? 2 : item.IsBullish ? 0 : 1)
                .ThenBy(item => item.SlotIndex)
                .Take(2)
                .OrderBy(item => item.BarIndex)
                .ThenBy(item => item.IsNeutral ? 2 : item.IsBullish ? 0 : 1))
            {
                var slotBars = slotBarsBySourceIndex[marker.BarIndex];
                objectIndex = DrawMiniChartDirectionalMarker(
                    objectIndex,
                    marker.SourceBars,
                    marker.SourceTimeFrame,
                    marker.BarIndex,
                    marker.IsBullish,
                    marker.SlotIndex,
                    marker.PatternSpan,
                    marker.HighlightPatternRange,
                    FormatCandleMarkerChartLabel(marker),
                    slotBars.Item1,
                    slotBars.Item2,
                    priceRange,
                    marker.IsNeutral);
            }

            objectIndex = DrawMiniChartCanonicalEventsForRange(
                objectIndex,
                sourceBars,
                sourceTimeFrame,
                firstSourceIndex,
                lastVisibleIndex,
                slotBarsBySourceIndex,
                priceRange);

            return objectIndex;
        }

        private int DrawMiniChartBarMarkers(
            int objectIndex,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int chartTfMinutes,
            double futureOffsetBars,
            double displayWidthBars,
            int firstSourceIndex,
            int actualCount,
            int sourceIndex,
            int leftBarIndex,
            int rightBarIndex,
            double priceRange)
        {
            if (sourceBars == null || Symbol == null || sourceIndex < 0 || sourceIndex >= sourceBars.Count)
                return objectIndex;

            var markerTexts = new List<Tuple<string, bool, int>>();

            var patternDefinitions = BuildEnabledCandlePatternDefinitions();
            if (patternDefinitions != null && patternDefinitions.Count > 0 && sourceIndex < sourceBars.Count - 1)
            {
                var sharedPatternCache = new Dictionary<int, HashSet<string>>();
                for (var i = 0; i < patternDefinitions.Count; i++)
                {
                    var definition = patternDefinitions[i];
                    if (definition == null)
                        continue;

                    var matched = false;
                    if (definition.NativeMatch != null)
                        matched = definition.NativeMatch(sourceBars, sourceIndex);
                    else if (!string.IsNullOrWhiteSpace(definition.SharedPatternType))
                        matched = GetDetectedSharedRulePatternSetCached(sourceBars, sourceTimeFrame, sourceIndex, sharedPatternCache).Contains(definition.SharedPatternType);

                    if (!matched)
                        continue;

                    markerTexts.Add(Tuple.Create((definition.ShortLabel ?? "").Trim().ToLowerInvariant(), definition.IsBullish, i));
                }
            }

            var indicatorDefinitions = BuildIndicatorEventDefinitions();
            if (indicatorDefinitions != null && indicatorDefinitions.Count > 0 && sourceIndex > 0 && sourceIndex < sourceBars.Count)
            {
                var requirements = GetIndicatorSnapshotRequirements();
                var scanCache = BuildIndicatorEventScanCache(sourceBars, Math.Max(0, sourceIndex - 1), requirements);
                var previousSnapshot = GetSharedIndicatorSnapshotCached(sourceBars, sourceIndex - 1, scanCache);
                var currentSnapshot = GetSharedIndicatorSnapshotCached(sourceBars, sourceIndex, scanCache);
                foreach (var definition in indicatorDefinitions)
                {
                    if (definition == null || definition.Match == null)
                        continue;
                    if (!definition.Match(sourceBars, sourceIndex, previousSnapshot, currentSnapshot))
                        continue;

                    markerTexts.Add(Tuple.Create((definition.ShortLabel ?? "").Trim().ToLowerInvariant(), definition.IsBullish, definition.SlotIndex));
                }
            }

            if (markerTexts.Count > 0)
            {
                var uniqueMarkerTexts = markerTexts
                    .GroupBy(item => string.Format(CultureInfo.InvariantCulture, "{0}|{1}|{2}", item.Item1, item.Item2 ? "B" : "S", item.Item3))
                    .Select(group => group.First())
                    .OrderBy(item => item.Item3)
                    .ToList();
                foreach (var marker in uniqueMarkerTexts)
                {
                    objectIndex = DrawMiniChartDirectionalMarker(
                        objectIndex,
                        sourceBars,
                        sourceTimeFrame,
                        sourceIndex,
                        marker.Item2,
                        marker.Item3,
                        1,
                        false,
                        marker.Item1,
                        leftBarIndex,
                        rightBarIndex,
                        priceRange);
                }
            }

            return objectIndex;
        }

        private int DrawMiniChartCanonicalEventsForRange(
            int objectIndex,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int firstSourceIndex,
            int lastVisibleIndex,
            Dictionary<int, Tuple<int, int>> slotBarsBySourceIndex,
            double priceRange)
        {
            if (sourceBars == null || Symbol == null || slotBarsBySourceIndex == null || slotBarsBySourceIndex.Count == 0)
                return objectIndex;

            var symbolName = Chart != null && !string.IsNullOrWhiteSpace(Chart.SymbolName)
                ? Chart.SymbolName
                : Symbol.Name;
            if (string.IsNullOrWhiteSpace(symbolName))
                return objectIndex;

            var enabledEventTypes = new List<Tuple<CanonicalEventType, string>>();
            if (_toggleRejectionDetections) enabledEventTypes.Add(Tuple.Create(CanonicalEventType.Rejection, "RJ"));
            if (_toggleBreakoutDetections) enabledEventTypes.Add(Tuple.Create(CanonicalEventType.Breakout, "BR"));
            if (_togglePullbackDetections) enabledEventTypes.Add(Tuple.Create(CanonicalEventType.Pullback, "PB"));
            if (_toggleContinuationDetections) enabledEventTypes.Add(Tuple.Create(CanonicalEventType.Continuation, "CT"));
            if (_toggleImpulseDetections) enabledEventTypes.Add(Tuple.Create(CanonicalEventType.Impulse, "IM"));
            if (enabledEventTypes.Count == 0)
                return objectIndex;

            var tfMinutes = Math.Max(1, TimeFrameToMinutes(sourceTimeFrame));
            var drawnKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var candidates = new List<Tuple<int, CanonicalMarketEvent, string>>();

            foreach (var eventType in enabledEventTypes)
            {
                var matchingEvents = GetCanonicalEventsForSymbolTimeFrame(symbolName, sourceTimeFrame, 24)
                    .Where(evt => evt.EventType == eventType.Item1)
                    .OrderByDescending(evt => evt.BarTime)
                    .ThenByDescending(evt => evt.Score)
                    .ToList();
                if (matchingEvents.Count == 0)
                    continue;

                foreach (var evt in matchingEvents.OrderBy(item => item.BarTime))
                {
                    var sourceIndex = -1;
                    for (var i = firstSourceIndex; i <= lastVisibleIndex; i++)
                    {
                        if (Math.Abs((sourceBars.OpenTimes[i] - evt.BarTime).TotalMinutes) <= tfMinutes)
                        {
                            sourceIndex = i;
                            break;
                        }
                    }

                    if (sourceIndex < firstSourceIndex || sourceIndex > lastVisibleIndex)
                        continue;
                    if (!slotBarsBySourceIndex.ContainsKey(sourceIndex))
                        continue;

                    var dedupeKey = string.Format(
                        CultureInfo.InvariantCulture,
                        "{0}:{1}:{2}",
                        sourceIndex,
                        eventType.Item2,
                        evt.IsBullish ? "B" : "S");
                    if (!drawnKeys.Add(dedupeKey))
                        continue;

                    candidates.Add(Tuple.Create(sourceIndex, evt, eventType.Item2));
                }
            }

            foreach (var candidate in candidates
                .OrderByDescending(item => item.Item2.BarTime)
                .ThenByDescending(item => item.Item2.Score)
                .Take(2)
                .OrderBy(item => item.Item2.BarTime))
            {
                var slotBars = slotBarsBySourceIndex[candidate.Item1];
                objectIndex = DrawMiniChartCanonicalEventAtSlot(
                    objectIndex,
                    sourceBars,
                    sourceTimeFrame,
                    candidate.Item1,
                    candidate.Item2,
                    candidate.Item3,
                    slotBars.Item1,
                    slotBars.Item2,
                    priceRange);
            }

            return objectIndex;
        }

        private int DrawMiniChartDirectionalMarker(
            int objectIndex,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int barIndex,
            bool isBullish,
            int slotIndex,
            int patternSpan,
            bool highlightPatternRange,
            string labelText,
            int leftBarIndex,
            int rightBarIndex,
            double priceRange,
            bool isNeutral = false)
        {
            if (sourceBars == null || Symbol == null || barIndex < 0 || barIndex >= sourceBars.Count)
                return objectIndex;

            var anchorPrice = isBullish ? sourceBars.LowPrices[barIndex] : sourceBars.HighPrices[barIndex];
            var barRange = Math.Max(sourceBars.HighPrices[barIndex] - sourceBars.LowPrices[barIndex], Symbol.PipSize * 8.0);
            // Bullish icons/labels use a darker green tone; bearish a red tone. The surrounding box
            // was removed: its x-position used real HTF bar times, which never matched the mini
            // chart's compressed per-bar slots, so it rendered off-position.
            // A neutral pattern has not established a bullish/bearish direction yet. Keep its
            // range visually neutral instead of implying direction through the timeframe color.
            var patternBoxColor = isNeutral ? Color.LightGray : isBullish ? Color.FromArgb(255, 34, 139, 34) : Color.FromArgb(255, 239, 68, 68);
            var textY = ResolveDirectionalLabelPrice(isBullish, anchorPrice, barRange, slotIndex, priceRange);
            // Icon sits left of the horizontal middle of the bar slot (label follows to its right).
            var iconBarIndex = leftBarIndex + Math.Max(0, (rightBarIndex - leftBarIndex) / 2);
            if (isNeutral)
            {
                var spanStartIndex = Math.Max(0, barIndex - Math.Max(1, patternSpan) + 1);
                var patternHigh = double.MinValue;
                var patternLow = double.MaxValue;
                for (var i = spanStartIndex; i <= barIndex; i++)
                {
                    patternHigh = Math.Max(patternHigh, sourceBars.HighPrices[i]);
                    patternLow = Math.Min(patternLow, sourceBars.LowPrices[i]);
                }
                var slotWidthBars = Math.Max(1, rightBarIndex - leftBarIndex);
                var boxLeftBarIndex = leftBarIndex - (slotWidthBars * Math.Max(0, patternSpan - 1));
                var box = Chart.DrawRectangle(
                    "MINI_PAT_BOX_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                    boxLeftBarIndex,
                    patternHigh,
                    rightBarIndex,
                    patternLow,
                    WithAlpha(patternBoxColor, 20));
                TrySetPropertyValue(box, "IsFilled", true);
                TrySetPropertyValue(box, "BorderColor", WithAlpha(patternBoxColor, 70));
                TrySetPropertyValue(box, "ZIndex", 12);
                anchorPrice = patternHigh;
                textY = patternHigh + Math.Max(Symbol.PipSize * 2.0, barRange * 0.03);
            }
            else
            {
                var icon = Chart.DrawIcon(
                    "MINI_PAT_ICON_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                    GetDirectionalChartIconType(isBullish),
                    iconBarIndex,
                    anchorPrice,
                    patternBoxColor);
                TrySetPropertyValue(icon, "ZIndex", 14);
                TrySetPropertyValue(icon, "IsInteractive", false);
            }

            var cleanLabel = string.IsNullOrWhiteSpace(labelText)
                ? ResolveMarkerPatternFallbackLabel(sourceBars, sourceTimeFrame, barIndex)
                : labelText.Trim().ToLowerInvariant();
            if (string.IsNullOrWhiteSpace(labelText))
                Print(string.Format(CultureInfo.InvariantCulture, "[Mini] marker label fallback tf={0} bar={1} -> '{2}'", GetMiniChartLabel(sourceTimeFrame), barIndex, cleanLabel));
            if (string.IsNullOrWhiteSpace(cleanLabel))
                return objectIndex + 1;
            var label = Chart.DrawText(
                "MINI_PAT_LBL_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                " " + cleanLabel,
                Math.Min(rightBarIndex, iconBarIndex + 1),
                textY,
                patternBoxColor);
            TryStyleChartText(label, GetNormalChartLabelFontSize(), "Courier New", true);
            TrySetPropertyValue(label, "ZIndex", 14);
            return objectIndex + 1;
        }

        private int DrawMiniChartCanonicalEventAtSlot(
            int objectIndex,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int sourceIndex,
            CanonicalMarketEvent evt,
            string shortLabel,
            int leftBarIndex,
            int rightBarIndex,
            double priceRange)
        {
            if (sourceBars == null || Symbol == null || sourceIndex < 0 || sourceIndex >= sourceBars.Count)
                return objectIndex;

            var baseColor = GetTimeFrameStructureColor(sourceTimeFrame);
            var directionalColor = GetDirectionalEventColor(evt.IsBullish);
            var markerColor = evt.EventType == CanonicalEventType.Rejection ? directionalColor : baseColor;
            if (evt.EventType == CanonicalEventType.Rejection || evt.EventType == CanonicalEventType.Breakout)
            {
                var levelLine = Chart.DrawTrendLine(
                    "MINI_EVT_LVL_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                    leftBarIndex,
                    evt.PriceRef,
                    rightBarIndex,
                    evt.PriceRef,
                    WithAlpha(baseColor, evt.EventType == CanonicalEventType.Breakout ? 132 : 118));
                TrySetPropertyValue(levelLine, "Thickness", 1);
                TrySetEnumPropertyValue(levelLine, "LineStyle", "Dots");
                TrySetPropertyValue(levelLine, "ZIndex", 13);
            }

            var anchorPrice = evt.IsBullish ? sourceBars.LowPrices[sourceIndex] : sourceBars.HighPrices[sourceIndex];
            var barRange = Math.Max(sourceBars.HighPrices[sourceIndex] - sourceBars.LowPrices[sourceIndex], Symbol.PipSize * 8.0);
            var eventBoxColor = directionalColor;
            var eventBox = Chart.DrawRectangle(
                "MINI_EVT_BOX_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                leftBarIndex,
                sourceBars.HighPrices[sourceIndex],
                rightBarIndex,
                sourceBars.LowPrices[sourceIndex],
                WithAlpha(eventBoxColor, 60));
            TrySetPropertyValue(eventBox, "IsFilled", true);
            TrySetPropertyValue(eventBox, "BorderColor", WithAlpha(eventBoxColor, 210));
            TrySetPropertyValue(eventBox, "ZIndex", 8);
            var textY = ResolveDirectionalLabelPrice(evt.IsBullish, anchorPrice, barRange, 0, priceRange);
            var textBarIndex = leftBarIndex + Math.Max(0, (rightBarIndex - leftBarIndex) / 3);
            var icon = Chart.DrawIcon(
                "MINI_EVT_ICON_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                GetDirectionalChartIconType(evt.IsBullish),
                textBarIndex,
                anchorPrice,
                markerColor);
            TrySetPropertyValue(icon, "ZIndex", 14);
            TrySetPropertyValue(icon, "IsInteractive", false);

            var text = Chart.DrawText(
                "MINI_EVT_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                " " + BuildChartEventDisplayLabel(evt),
                Math.Min(rightBarIndex, textBarIndex + 1),
                textY,
                markerColor);
            TryStyleChartText(text, GetNormalChartLabelFontSize(), "Courier New", true);
            TrySetPropertyValue(text, "ZIndex", 14);

            return objectIndex + 1;
        }

        private int DrawMiniChartCanonicalEventsForBar(
            int objectIndex,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int sourceIndex,
            DateTime leftTime,
            DateTime rightTime,
            double priceRange)
        {
            if (sourceBars == null || Symbol == null || sourceIndex < 0 || sourceIndex >= sourceBars.Count)
                return objectIndex;

            var symbolName = Chart != null && !string.IsNullOrWhiteSpace(Chart.SymbolName)
                ? Chart.SymbolName
                : Symbol.Name;
            if (string.IsNullOrWhiteSpace(symbolName))
                return objectIndex;

            var enabledEventTypes = new List<Tuple<CanonicalEventType, string>>();
            if (_toggleRejectionDetections) enabledEventTypes.Add(Tuple.Create(CanonicalEventType.Rejection, "RJ"));
            if (_toggleBreakoutDetections) enabledEventTypes.Add(Tuple.Create(CanonicalEventType.Breakout, "BR"));
            if (_togglePullbackDetections) enabledEventTypes.Add(Tuple.Create(CanonicalEventType.Pullback, "PB"));
            if (_toggleContinuationDetections) enabledEventTypes.Add(Tuple.Create(CanonicalEventType.Continuation, "CT"));
            if (_toggleImpulseDetections) enabledEventTypes.Add(Tuple.Create(CanonicalEventType.Impulse, "IM"));
            if (enabledEventTypes.Count == 0)
                return objectIndex;

            var barTime = sourceBars.OpenTimes[sourceIndex];
            var tfMinutes = Math.Max(1, TimeFrameToMinutes(sourceTimeFrame));
            var relevantEvents = GetCanonicalEventsForSymbolTimeFrame(symbolName, sourceTimeFrame, 24)
                .Where(evt => enabledEventTypes.Any(item => item.Item1 == evt.EventType))
                .Where(evt => Math.Abs((evt.BarTime - barTime).TotalMinutes) <= tfMinutes)
                .OrderByDescending(evt => evt.Score)
                .ThenBy(evt => evt.EventType)
                .ToList();

            if (relevantEvents.Count == 0)
                return objectIndex;

            foreach (var evt in relevantEvents)
            {
                var shortLabel = enabledEventTypes.First(item => item.Item1 == evt.EventType).Item2;
                var baseColor = GetTimeFrameStructureColor(sourceTimeFrame);
                var directionalColor = GetDirectionalEventColor(evt.IsBullish);
                var markerColor = evt.EventType == CanonicalEventType.Rejection ? directionalColor : baseColor;
                if (evt.EventType == CanonicalEventType.Rejection || evt.EventType == CanonicalEventType.Breakout)
                {
                    var levelLine = Chart.DrawTrendLine(
                        "MINI_EVT_LVL_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                        leftTime,
                        evt.PriceRef,
                        rightTime,
                        evt.PriceRef,
                        WithAlpha(baseColor, evt.EventType == CanonicalEventType.Breakout ? 132 : 118));
                    TrySetPropertyValue(levelLine, "Thickness", 1);
                    TrySetEnumPropertyValue(levelLine, "LineStyle", "Dots");
                    TrySetPropertyValue(levelLine, "ZIndex", 13);
                }

                var anchorPrice = evt.IsBullish ? sourceBars.LowPrices[sourceIndex] : sourceBars.HighPrices[sourceIndex];
                var verticalPad = Math.Max(Symbol.PipSize * 7.0, priceRange * 0.03);
                var eventBoxColor = directionalColor;
                var eventBox = Chart.DrawRectangle(
                    "MINI_EVT_BOX_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                    leftTime,
                    sourceBars.HighPrices[sourceIndex],
                    rightTime,
                    sourceBars.LowPrices[sourceIndex],
                    WithAlpha(eventBoxColor, 60));
                TrySetPropertyValue(eventBox, "IsFilled", true);
                TrySetPropertyValue(eventBox, "BorderColor", WithAlpha(eventBoxColor, 210));
                TrySetPropertyValue(eventBox, "ZIndex", 8);
                var textY = evt.IsBullish ? anchorPrice - verticalPad : anchorPrice + verticalPad;
                var textTime = leftTime.AddMinutes(Math.Max(0.2, (rightTime - leftTime).TotalMinutes * 0.18));
            var text = Chart.DrawText(
                "MINI_EVT_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                BuildChartEventDisplayLabel(evt),
                textTime,
                textY,
                markerColor);
                TryStyleChartText(text, GetNormalChartLabelFontSize(), "Courier New", true);
                TrySetPropertyValue(text, "ZIndex", 14);

                objectIndex++;
            }

            return objectIndex;
        }

        // Number of source bars that fit inside one full day (1440 minutes).
        private static int GetBarsPerFullDay(int tfMinutes)
        {
            var minutes = Math.Max(1, tfMinutes);
            return Math.Max(1, (int)Math.Ceiling(1440.0 / minutes));
        }

        // Per-timeframe mini chart bar count (what each HTF mini chart shows):
        // W=4, D=7, 4H=12, 1H/30m/15m and below=24.
        private int GetMiniChartBarsForTimeFrame(TimeFrame timeFrame)
        {
            return CTraderChartEngine.GetMiniChartBars(timeFrame);
        }

        private int DrawMiniChartSpacer(int chartTfMinutes, double futureOffsetBars, int objectIndex)
        {
            var chartBars = GetCurrentChartVisualBars();
            if (chartBars == null || chartBars.Count < 10)
                return objectIndex;

            var lookbackBars = Math.Min(chartBars.Count, 200);
            var start = Math.Max(0, chartBars.Count - lookbackBars);
            var chartHigh = double.MinValue;
            var chartLow = double.MaxValue;
            for (var i = start; i < chartBars.Count; i++)
            {
                chartHigh = Math.Max(chartHigh, chartBars.HighPrices[i]);
                chartLow = Math.Min(chartLow, chartBars.LowPrices[i]);
            }

            if (chartHigh <= chartLow || chartHigh == double.MinValue || chartLow == double.MaxValue)
                return objectIndex;

            var padStartBarIndex = chartBars.Count + Math.Max(5, (int)Math.Ceiling(futureOffsetBars));
            var padEndBarIndex = padStartBarIndex + 8;
            var padColor = Color.FromArgb(1, 255, 255, 255);
            var rect = Chart.DrawRectangle("MINI_PAD_" + objectIndex.ToString(CultureInfo.InvariantCulture), padStartBarIndex, chartHigh, padEndBarIndex, chartLow, padColor);
            TrySetPropertyValue(rect, "IsFilled", true);
            TrySetPropertyValue(rect, "Color", padColor);
            TrySetPropertyValue(rect, "BorderColor", padColor);
            TrySetPropertyValue(rect, "Thickness", 1);
            TrySetChartObjectBackground(rect);
            return objectIndex + 1;
        }

        private void StoreBacktestExportTradeSnapshot(string ticket, BacktestStrategySignal signal, double approvedRiskMoney, double approvedVolumeUnits, double approvedVolumeLots)
        {
            var riskDistance = Math.Abs(signal.EntryPrice - signal.StopLoss);
            var rewardDistance = Math.Abs(signal.TakeProfit - signal.EntryPrice);
            var rewardRisk = riskDistance > 0 ? rewardDistance / riskDistance : 0;
            var equityBase = _backtestExportInitialEquity > 0 ? _backtestExportInitialEquity : _backtestExportInitialBalance;
            var riskPercent = equityBase > 0 && approvedRiskMoney > 0 ? (approvedRiskMoney / equityBase) * 100.0 : 0.0;
            var snapshot = new BacktestExportTradeSnapshot
            {
                StrategyId = signal.StrategyId ?? "",
                TradeType = signal.TradeType,
                SignalTime = signal.SignalTime,
                EntryPrice = signal.EntryPrice,
                StopLoss = signal.StopLoss,
                TakeProfit = signal.TakeProfit,
                RiskAmount = approvedRiskMoney,
                RiskPercent = riskPercent,
                RewardRisk = rewardRisk,
                VolumeInUnits = approvedVolumeUnits,
                VolumeLots = approvedVolumeLots
            };

            _backtestExportTradeSequence.Add(snapshot);

            if (!string.IsNullOrWhiteSpace(ticket))
                _backtestExportTradeSnapshots[ticket.Trim()] = snapshot;
        }

        private int FindBacktestExportTradeSnapshotIndex(
            List<BacktestExportTradeSnapshot> snapshots,
            HashSet<int> usedSnapshotIndexes,
            TradeType tradeType,
            DateTime openedAtUtc,
            double entryPrice,
            double volumeInUnits)
        {
            if (snapshots == null || snapshots.Count == 0)
                return -1;

            var bestIndex = -1;
            var bestScore = double.MaxValue;

            for (var i = 0; i < snapshots.Count; i++)
            {
                if (usedSnapshotIndexes != null && usedSnapshotIndexes.Contains(i))
                    continue;

                var snapshot = snapshots[i];
                if (snapshot.TradeType != tradeType)
                    continue;

                var score = 0.0;
                if (openedAtUtc != DateTime.MinValue && snapshot.SignalTime != DateTime.MinValue)
                    score += Math.Abs((openedAtUtc - snapshot.SignalTime).TotalSeconds);

                if (entryPrice > 0 && snapshot.EntryPrice > 0)
                    score += Math.Abs(entryPrice - snapshot.EntryPrice) * 100000.0;

                if (volumeInUnits > 0 && snapshot.VolumeInUnits > 0)
                    score += Math.Abs(volumeInUnits - snapshot.VolumeInUnits) * 10.0;

                if (bestIndex < 0 || score < bestScore)
                {
                    bestIndex = i;
                    bestScore = score;
                }
            }

            return bestIndex;
        }

        private List<TimeFrame> GetAutoHigherTimeframes(TimeFrame chartTimeFrame)
        {
            return CTraderChartEngine.GetAutoHigherTimeFrames(chartTimeFrame);
        }

        private TimeFrame ResolveConfiguredHtfSlotTimeFrame(TimeFrame chartTimeFrame, int slotIndex)
        {
            var selection = slotIndex == 0
                ? DrawAutoHtf1
                : DrawAutoHtf2;
            return CTraderChartEngine.ResolveHtfSlotTimeFrame(chartTimeFrame, slotIndex, selection);
        }

        private List<TimeFrame> GetEnabledAutoHigherTimeframes(TimeFrame chartTimeFrame)
        {
            return CTraderChartEngine.GetEnabledHigherTimeFrames(
                chartTimeFrame, DrawAutoHtf1, DrawAutoHtf2);
        }

        private string GetAutoHigherTimeframeButtonLabel(TimeFrame chartTimeFrame, int slotIndex)
        {
            var resolved = ResolveConfiguredHtfSlotTimeFrame(chartTimeFrame, slotIndex);
            if (resolved == null)
                return slotIndex == 0 ? "HTF1" : "HTF2";
            return GetMiniChartLabel(resolved);
        }

        private DateTime GetCurrentChartEndTime()
        {
            var chartBars = GetCurrentChartVisualBars();
            if (chartBars != null && chartBars.Count > 0)
                return chartBars.OpenTimes[chartBars.Count - 1];
            return Server.Time;
        }

        private DateTime GetNextDayStartTime(DateTime referenceTime)
        {
            try
            {
                var dailyBars = GetBarsForCurrentMasterTimer(TimeFrame.Daily, Chart.SymbolName);
                if (dailyBars != null && dailyBars.Count > 0)
                {
                    foreach (var openTime in dailyBars.OpenTimes)
                    {
                        if (openTime > referenceTime)
                            return openTime;
                    }
                }
            }
            catch
            {
            }

            return referenceTime.Date.AddDays(1);
        }

        private DateTime GetCurrentDayStartTime(DateTime referenceTime)
        {
            try
            {
                var dailyBars = GetBarsForCurrentMasterTimer(TimeFrame.Daily, Chart.SymbolName);
                if (dailyBars != null && dailyBars.Count > 0)
                {
                    for (var i = dailyBars.Count - 1; i >= 0; i--)
                    {
                        if (dailyBars.OpenTimes[i] <= referenceTime)
                            return dailyBars.OpenTimes[i];
                    }
                }
            }
            catch
            {
            }

            return referenceTime.Date;
        }

        private DateTime GetCurrentWeekStartTime(DateTime referenceTime)
        {
            var dayStart = GetCurrentDayStartTime(referenceTime);
            // Trading week starts Monday; Sunday (DayOfWeek=0) belongs to the prior week.
            var dayOfWeek = (int)dayStart.DayOfWeek;
            var daysBack = dayOfWeek == 0 ? 6 : dayOfWeek - 1;
            return dayStart.AddDays(-daysBack);
        }

        private int DrawHigherTimeframeZonesOnChart(int objectIndex)
        {
            var chartTimeFrame = Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
            var chartTfMinutes = TimeFrameToMinutes(chartTimeFrame);
            foreach (var tf in GetEnabledAutoHigherTimeframes(chartTimeFrame))
            {
                var tfMinutes = TimeFrameToMinutes(tf);
                if (tfMinutes <= 0 || tfMinutes <= chartTfMinutes)
                    continue;

                try
                {
                    var sourceBars = GetBarsForCurrentMasterTimer(tf, Chart.SymbolName);
                    if (sourceBars == null || sourceBars.Count < 5)
                        continue;

                    if (DrawFvgZones)
                        objectIndex = DrawRecentFvgZones(sourceBars, tf, "HTF_FVG_", objectIndex, GetCurrentChartEndTime());
                    if (DrawOrderBlocks)
                        objectIndex = DrawRecentOrderBlocks(sourceBars, tf, "HTF_OB_", objectIndex, GetCurrentChartEndTime());
                }
                catch (Exception ex)
                {
                    SafePrint("[Visuals] HTF {0} skipped: {1}", tf, ex.Message);
                }
            }

            return objectIndex;
        }

        private bool IsHigherTimeframeEnabled(TimeFrame timeFrame)
        {
            var chartTimeFrame = Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
            return GetEnabledAutoHigherTimeframes(chartTimeFrame)
                .Any(tf => tf == timeFrame);
        }

        private bool TryParseTimeFrameToken(string token, out TimeFrame timeFrame)
        {
            timeFrame = TimeFrame.Minute;
            var normalized = (token ?? "").Trim().ToUpperInvariant();
            normalized = normalized.Replace("_", "").Replace("-", "").Replace(" ", "");
            if (string.IsNullOrWhiteSpace(normalized))
                return false;

            if (TryParseNamedTimeFrame(normalized, out timeFrame))
                return true;

            int minutes;
            if (TryParseTimeFrameMinutes(normalized, out minutes) && TryMapMinutesToTimeFrame(minutes, out timeFrame))
                return true;

            return false;
        }

        private bool TryParseNamedTimeFrame(string normalized, out TimeFrame timeFrame)
        {
            timeFrame = TimeFrame.Minute;
            switch (normalized)
            {
                case "DAILY":
                    timeFrame = TimeFrame.Daily;
                    return true;
                case "WEEKLY":
                case "W1":
                case "1W":
                    timeFrame = TimeFrame.Weekly;
                    return true;
                case "MONTHLY":
                case "MN1":
                case "1MO":
                case "1MON":
                case "1MONTH":
                    timeFrame = TimeFrame.Monthly;
                    return true;
            }

            try
            {
                var property = typeof(TimeFrame)
                    .GetProperties(System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static)
                    .FirstOrDefault(p => p.PropertyType == typeof(TimeFrame) && string.Equals(p.Name, normalized, StringComparison.OrdinalIgnoreCase));
                if (property != null)
                {
                    var value = property.GetValue(null, null);
                    if (value is TimeFrame)
                    {
                        timeFrame = (TimeFrame)value;
                        return true;
                    }
                }
            }
            catch
            {
            }

            return false;
        }

        private bool TryParseTimeFrameMinutes(string normalized, out int minutes)
        {
            return CTraderTimeFrameEngine.TryParseMinutes(normalized, out minutes);
        }

        private bool TryMapMinutesToTimeFrame(int minutes, out TimeFrame timeFrame)
        {
            timeFrame = TimeFrame.Minute;
            if (minutes <= 0)
                return false;

            switch (minutes)
            {
                case 1: timeFrame = TimeFrame.Minute; return true;
                case 5: timeFrame = TimeFrame.Minute5; return true;
                case 15: timeFrame = TimeFrame.Minute15; return true;
                case 30: timeFrame = TimeFrame.Minute30; return true;
                case 60: timeFrame = TimeFrame.Hour; return true;
                case 240: timeFrame = TimeFrame.Hour4; return true;
                case 1440: timeFrame = TimeFrame.Daily; return true;
                case 10080: timeFrame = TimeFrame.Weekly; return true;
                case 43200: timeFrame = TimeFrame.Monthly; return true;
            }

            try
            {
                foreach (var property in typeof(TimeFrame).GetProperties(System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static))
                {
                    if (property.PropertyType != typeof(TimeFrame))
                        continue;

                    var value = property.GetValue(null, null);
                    if (!(value is TimeFrame))
                        continue;

                    var candidate = (TimeFrame)value;
                    if (TimeFrameToMinutes(candidate) == minutes)
                    {
                        timeFrame = candidate;
                        return true;
                    }
                }
            }
            catch
            {
            }

            return false;
        }

