        private Color GetTimeFrameStructureColor(TimeFrame timeFrame)
        {
            var minutes = TimeFrameToMinutes(timeFrame);
            if (minutes >= 10080) return Color.Orchid;
            if (minutes >= 1440) return Color.Gold;
            if (minutes >= 240) return Color.DarkOrange;
            if (minutes >= 60) return Color.MediumSlateBlue;
            if (minutes >= 30) return Color.Aqua;
            if (minutes >= 15) return Color.DodgerBlue;
            if (minutes >= 5) return Color.WhiteSmoke;
            return Color.Gainsboro;
        }

        private List<TimeFrame> GetDashboardEventTimeFrames()
        {
            return new List<TimeFrame>
            {
                TimeFrame.Minute,
                TimeFrame.Minute5,
                TimeFrame.Minute15,
                TimeFrame.Hour,
                TimeFrame.Hour4,
                TimeFrame.Daily
            };
        }

        private List<TimeFrame> GetTradeTriggerTimeFrames(TimeFrame baseTimeFrame = null)
        {
            var frames = GetDashboardEventTimeFrames();
            if (baseTimeFrame != null)
                frames.Add(baseTimeFrame);
            frames.AddRange(ResolveSharedStrategyTimeFrames(baseTimeFrame ?? (Chart != null ? Chart.TimeFrame : TimeFrame.Minute)));
            frames.AddRange(GetEnabledAutoHigherTimeframes(baseTimeFrame ?? (Chart != null ? Chart.TimeFrame : TimeFrame.Minute)));
            return frames
                .Where(timeFrame => timeFrame != null && TimeFrameToMinutes(timeFrame) > 0)
                .Distinct()
                .OrderByDescending(TimeFrameToMinutes)
                .ToList();
        }

        private int GetTradeTriggerRetentionCount(TimeFrame timeFrame)
        {
            var minutes = TimeFrameToMinutes(timeFrame);
            if (minutes >= 240) return 1;
            if (minutes >= 60) return 2;
            if (minutes >= 30) return 3;
            return 4;
        }

        private List<TradeTriggerEvent> GetTradeTriggerSequence(string symbolName, TimeFrame baseTimeFrame = null)
        {
            var empty = new List<TradeTriggerEvent>();
            if (string.IsNullOrWhiteSpace(symbolName))
                return empty;

            var normalizedSymbol = NormalizeSymbolAlias(symbolName);
            var frames = GetTradeTriggerTimeFrames(baseTimeFrame);
            var cacheKey = string.Format(
                CultureInfo.InvariantCulture,
                "{0}|{1}|{2}",
                normalizedSymbol,
                string.Join(",", frames.Select(GetMiniChartLabel)),
                BuildDashboardAnalysisToggleKey());
            TimedCacheEntry<List<TradeTriggerEvent>> cached;
            if (_tradeTriggerSequenceCache.TryGetValue(cacheKey, out cached) &&
                cached != null && cached.Value != null &&
                (DateTime.UtcNow - cached.CreatedAtUtc) <= TimeSpan.FromSeconds(3))
                return cached.Value.ToList();

            var retained = new List<TradeTriggerEvent>();
            foreach (var timeFrame in frames)
            {
                var candidates = CollectTradeTriggerCandidates(normalizedSymbol, timeFrame);
                retained.AddRange(candidates
                    .OrderByDescending(item => item.BarTime)
                    .ThenByDescending(item => item.Priority)
                    .Take(GetTradeTriggerRetentionCount(timeFrame)));
            }
            retained = KeepHighestTimeFrameSimilarTradeTriggers(retained);

            var anchor = retained
                .Where(item => !item.IsDirectionless)
                .OrderByDescending(item => TimeFrameToMinutes(item.SourceTimeFrame))
                .ThenByDescending(item => item.BarTime)
                .ThenByDescending(item => item.Priority)
                .FirstOrDefault();
            if (!string.IsNullOrWhiteSpace(anchor.Name))
            {
                retained = retained
                    .Where(item => item.IsDirectionless || item.IsBullish == anchor.IsBullish)
                    .ToList();
            }

            var sequence = retained
                .GroupBy(item => string.Format(
                    CultureInfo.InvariantCulture,
                    "{0}|{1}|{2}|{3}",
                    GetMiniChartLabel(item.SourceTimeFrame),
                    item.BarTime.Ticks,
                    item.Option,
                    item.IsDirectionless ? "N" : item.IsBullish ? "B" : "S"))
                .Select(group => group.First())
                .OrderByDescending(item => TimeFrameToMinutes(item.SourceTimeFrame))
                .ThenBy(item => item.BarTime)
                .ThenByDescending(item => item.Priority)
                .ToList();

            _tradeTriggerSequenceCache[cacheKey] = new TimedCacheEntry<List<TradeTriggerEvent>>
            {
                CreatedAtUtc = DateTime.UtcNow,
                Value = sequence
            };
            return sequence.ToList();
        }

        private List<TradeTriggerEvent> KeepHighestTimeFrameSimilarTradeTriggers(IEnumerable<TradeTriggerEvent> triggers)
        {
            return CTraderSequenceEngine.KeepHighestTimeFrame(
                triggers,
                trigger => trigger.Name,
                trigger => trigger.BarTime,
                trigger => TimeFrameToMinutes(trigger.SourceTimeFrame),
                trigger => trigger.IsDirectionless ? "N" : trigger.IsBullish ? "B" : "S",
                trigger => trigger.Priority);
        }

