        private string BuildTradeTriggerClosedBarsKey(string symbolName, TimeFrame baseTimeFrame)
        {
            var parts = new List<string>();
            foreach (var timeFrame in GetTradeTriggerTimeFrames(baseTimeFrame))
            {
                try
                {
                    var sourceBars = GetBarsForCurrentMasterTimer(timeFrame, symbolName);
                    var latestClosedTime = sourceBars != null && sourceBars.Count >= 2
                        ? sourceBars.OpenTimes[sourceBars.Count - 2]
                        : DateTime.MinValue;
                    parts.Add(GetMiniChartLabel(timeFrame) + ":" + latestClosedTime.Ticks.ToString(CultureInfo.InvariantCulture));
                }
                catch
                {
                    parts.Add(GetMiniChartLabel(timeFrame) + ":0");
                }
            }
            return string.Join(",", parts);
        }

        private List<TradeTriggerEvent> CollectTradeTriggerCandidates(string symbolName, TimeFrame timeFrame)
        {
            var candidates = new List<TradeTriggerEvent>();
            Bars sourceBars;
            try
            {
                sourceBars = GetBarsForCurrentMasterTimer(timeFrame, symbolName);
            }
            catch
            {
                sourceBars = null;
            }
            if (sourceBars == null || sourceBars.Count < 4)
                return candidates;

            var latestClosedIndex = sourceBars.Count - 2;
            var scanBars = Math.Max(8, GetTradeTriggerRetentionCount(timeFrame) * 4);
            var firstIndex = Math.Max(1, latestClosedIndex - scanBars + 1);
            var canonicalEvents = GetCanonicalEventsForSymbolTimeFrame(symbolName, timeFrame, 256)
                .OrderByDescending(evt => evt.BarTime)
                .ThenByDescending(evt => evt.Score)
                .ToList();
            var canonicalEventsByBarTime = IndexCanonicalEventsByBarTime(canonicalEvents);
            var noCanonicalEvents = new List<CanonicalMarketEvent>();

            for (var barIndex = latestClosedIndex; barIndex >= firstIndex; barIndex--)
            {
                var previous = BuildSharedIndicatorSnapshot(sourceBars, barIndex - 1);
                var current = BuildSharedIndicatorSnapshot(sourceBars, barIndex);
                var patterns = GetDetectedSharedRulePatternSet(sourceBars, timeFrame, barIndex);
                var barTime = sourceBars.OpenTimes[barIndex];
                List<CanonicalMarketEvent> eventsOnBar;
                if (!canonicalEventsByBarTime.TryGetValue(barTime, out eventsOnBar))
                    eventsOnBar = noCanonicalEvents;

                foreach (StrategyCustomEventOption option in Enum.GetValues(typeof(StrategyCustomEventOption)))
                {
                    if (option == StrategyCustomEventOption.Off ||
                        option.ToString().StartsWith("__Any", StringComparison.Ordinal) ||
                        !IsDashboardEventOptionEnabled(option))
                        continue;

                    StrategyCustomEventOption divergenceBaseOption;
                    StrategyEventFollowUpOutcome divergenceOutcome;
                    if (!TryMapStrategyFollowUpEventOption(option, out divergenceBaseOption, out divergenceOutcome))
                        divergenceBaseOption = option;
                    if (divergenceBaseOption == StrategyCustomEventOption.Div_Divergence && barIndex != latestClosedIndex)
                        continue;

                    bool bullish;
                    bool bearish;
                    bool directionless;
                    string label;
                    if (!TryEvaluateStrategyCustomEventOption(
                        option,
                        symbolName,
                        sourceBars,
                        timeFrame,
                        barIndex,
                        previous,
                        current,
                        patterns,
                        canonicalEvents,
                        eventsOnBar,
                        canonicalEventsByBarTime,
                        out bullish,
                        out bearish,
                        out directionless,
                        out label))
                        continue;

                    if (bullish)
                        candidates.Add(BuildTradeTriggerEvent(symbolName, timeFrame, sourceBars, barIndex, option, label, true, false, canonicalEventsByBarTime));
                    if (bearish)
                        candidates.Add(BuildTradeTriggerEvent(symbolName, timeFrame, sourceBars, barIndex, option, label, false, false, canonicalEventsByBarTime));
                    if (directionless)
                        candidates.Add(BuildTradeTriggerEvent(symbolName, timeFrame, sourceBars, barIndex, option, label, false, true, canonicalEventsByBarTime));
                }
            }

            return candidates;
        }

        private Dictionary<DateTime, List<CanonicalMarketEvent>> IndexCanonicalEventsByBarTime(IEnumerable<CanonicalMarketEvent> canonicalEvents)
        {
            var index = new Dictionary<DateTime, List<CanonicalMarketEvent>>();
            if (canonicalEvents == null)
                return index;

            foreach (var canonicalEvent in canonicalEvents)
            {
                List<CanonicalMarketEvent> eventsOnBar;
                if (!index.TryGetValue(canonicalEvent.BarTime, out eventsOnBar))
                {
                    eventsOnBar = new List<CanonicalMarketEvent>();
                    index[canonicalEvent.BarTime] = eventsOnBar;
                }
                eventsOnBar.Add(canonicalEvent);
            }
            return index;
        }

        private TradeTriggerEvent BuildTradeTriggerEvent(
            string symbolName,
            TimeFrame timeFrame,
            Bars sourceBars,
            int barIndex,
            StrategyCustomEventOption option,
            string label,
            bool bullish,
            bool directionless,
            Dictionary<DateTime, List<CanonicalMarketEvent>> canonicalEventsByBarTime)
        {
            StrategyCustomEventOption baseOption;
            StrategyEventFollowUpOutcome followUpOutcome;
            var isFollowUp = TryMapStrategyFollowUpEventOption(option, out baseOption, out followUpOutcome);
            if (!isFollowUp)
                baseOption = option;
            CanonicalEventType canonicalType;
            string canonicalLabel;
            var hasCanonicalType = TryMapStrategyCustomCanonicalEventOption(baseOption, out canonicalType, out canonicalLabel);
            string artifactKind;
            var hasArtifactReaction = TryMapStrategyArtifactReactionEventOption(baseOption, out canonicalType, out artifactKind, out canonicalLabel);
            hasCanonicalType = hasCanonicalType || hasArtifactReaction;
            var canonicalBarTime = isFollowUp && barIndex > 0
                ? sourceBars.OpenTimes[barIndex - 1]
                : sourceBars.OpenTimes[barIndex];
            var canonical = default(CanonicalMarketEvent);
            List<CanonicalMarketEvent> canonicalEventsOnBar;
            if (hasCanonicalType &&
                canonicalEventsByBarTime != null &&
                canonicalEventsByBarTime.TryGetValue(canonicalBarTime, out canonicalEventsOnBar))
            {
                var hasBestCanonical = false;
                foreach (var candidate in canonicalEventsOnBar)
                {
                    if (candidate.EventType != canonicalType || (!directionless && candidate.IsBullish != bullish))
                        continue;
                    if (hasArtifactReaction && !string.Equals(candidate.LevelKind, artifactKind, StringComparison.OrdinalIgnoreCase))
                        continue;
                    if (!hasBestCanonical || candidate.Score > canonical.Score)
                    {
                        canonical = candidate;
                        hasBestCanonical = true;
                    }
                }
            }
            var hasCanonical = !string.IsNullOrWhiteSpace(canonical.EventKey);
            if (hasCanonical && isFollowUp)
            {
                canonical.EventKey = canonical.EventKey + (followUpOutcome == StrategyEventFollowUpOutcome.Continue ? ".c" : ".r");
                canonical.BarTime = sourceBars.OpenTimes[barIndex];
            }
            var stopDistance = hasCanonical && canonical.ZoneHigh > canonical.ZoneLow && canonical.ZoneLow > 0
                ? canonical.ZoneHigh - canonical.ZoneLow
                : Math.Max(sourceBars.HighPrices[barIndex] - sourceBars.LowPrices[barIndex], 0);
            var normalizedLabel = string.IsNullOrWhiteSpace(label) ? option.ToString() : label;
            var name = directionless
                ? GetMiniChartLabel(timeFrame) + "." + FormatEventLabelForDisplay(normalizedLabel)
                : BuildCanonicalEventName(timeFrame, normalizedLabel, bullish);
            if (hasCanonical && !directionless)
            {
                var canonicalFollowUp = isFollowUp
                    ? (followUpOutcome == StrategyEventFollowUpOutcome.Continue ? ".c" : ".r")
                    : "";
                name = BuildCanonicalMarketEventName(canonical, canonicalFollowUp);
            }

            // Candle visuals and trade comments must identify the same event. A candle marker
            // carries its matched level in the canonical name (for example h1.pin↑.r.h4.p.l), so use
            // that same formatter for the executable trigger instead of reducing it to h1.pin↑.
            if (!directionless && GetCustomEventPatternBarSpan(baseOption) > 0)
            {
                var patternIndex = isFollowUp && barIndex > 0 ? barIndex - 1 : barIndex;
                List<CandleConfluenceMatch> confluenceMatches;
                if (ShouldKeepCandlePatternInline(
                    sourceBars,
                    timeFrame,
                    patternIndex,
                    bullish,
                    out confluenceMatches,
                    symbolName,
                    ResolveLoadedSymbol(symbolName)))
                {
                    name = FormatCanonicalCandlePatternEventName(
                        timeFrame,
                        normalizedLabel,
                        bullish,
                        confluenceMatches);
                }
            }

            return new TradeTriggerEvent
            {
                SymbolName = symbolName,
                Name = name,
                Family = GetTradeTriggerFamily(option),
                Option = option,
                SourceTimeFrame = timeFrame,
                BarTime = sourceBars.OpenTimes[barIndex],
                IsBullish = bullish,
                IsDirectionless = directionless,
                HasCanonicalEvent = hasCanonical,
                CanonicalEvent = canonical,
                StopDistance = stopDistance,
                Priority = GetEventLabelPriorityScore(normalizedLabel)
            };
        }

        private string GetTradeTriggerFamily(StrategyCustomEventOption option)
        {
            StrategyCustomEventOption baseOption;
            StrategyEventFollowUpOutcome outcome;
            if (!TryMapStrategyFollowUpEventOption(option, out baseOption, out outcome))
                baseOption = option;
            CanonicalEventType canonicalType;
            string label;
            if (TryMapStrategyCustomCanonicalEventOption(baseOption, out canonicalType, out label)) return "structure";
            string artifactKind;
            if (TryMapStrategyArtifactReactionEventOption(baseOption, out canonicalType, out artifactKind, out label)) return "structure";
            if (GetCustomEventPatternBarSpan(baseOption) > 0) return "candle";
            if (IsIndicatorCustomEventOption(baseOption)) return "technical";
            return "context";
        }

        private string BuildDashboardEventCacheKey(string symbolName, TimeFrame timeFrame)
        {
            return string.Format(
                CultureInfo.InvariantCulture,
                "{0}|{1}|{2}",
                string.IsNullOrWhiteSpace(symbolName) ? "" : symbolName.Trim().ToUpperInvariant(),
                GetMiniChartLabel(timeFrame),
                GetCanonicalStructureToggleCacheKey());
        }

        private string GetCanonicalStructureToggleCacheKey()
        {
            return string.Format(
                CultureInfo.InvariantCulture,
                "{0}{1}{2}{3}{4}{5}{6}{7}",
                _toggleChochDetections ? "1" : "0",
                _toggleBosDetections ? "1" : "0",
                _toggleSweepDetections ? "1" : "0",
                _toggleRejectionDetections ? "1" : "0",
                _toggleBreakoutDetections ? "1" : "0",
                _togglePullbackDetections ? "1" : "0",
                _toggleContinuationDetections ? "1" : "0",
                _toggleImpulseDetections ? "1" : "0");
        }

        private bool AreAllCanonicalStructureEventsEnabled()
        {
            return _toggleChochDetections &&
                _toggleBosDetections &&
                _toggleSweepDetections &&
                _toggleRejectionDetections &&
                _toggleBreakoutDetections &&
                _togglePullbackDetections &&
                _toggleContinuationDetections &&
                _toggleImpulseDetections;
        }

        private bool IsCanonicalStructureEventEnabled(CanonicalEventType eventType)
        {
            switch (eventType)
            {
                case CanonicalEventType.Choch:
                    return _toggleChochDetections;
                case CanonicalEventType.Bos:
                    return _toggleBosDetections;
                case CanonicalEventType.SweepReclaim:
                    return _toggleSweepDetections;
                case CanonicalEventType.Rejection:
                    return _toggleRejectionDetections;
                case CanonicalEventType.Breakout:
                    return _toggleBreakoutDetections;
                case CanonicalEventType.Pullback:
                    return _togglePullbackDetections;
                case CanonicalEventType.Continuation:
                    return _toggleContinuationDetections;
                case CanonicalEventType.Impulse:
                    return _toggleImpulseDetections;
                default:
                    return false;
            }
        }

        private CanonicalMarketEvent BuildCanonicalMarketEvent(
            string symbolName,
            TimeFrame timeFrame,
            CanonicalEventType eventType,
            bool isBullish,
            CanonicalEventReason reason,
            CanonicalEventAction action,
            DateTime barTime,
            double priceRef,
            int score,
            int confidence,
            double zoneLow = 0,
            double zoneHigh = 0,
            string levelKind = "")
        {
            var eventSuffix = eventType == CanonicalEventType.Choch
                ? "choch"
                : eventType == CanonicalEventType.Bos
                    ? "bos"
                    : eventType == CanonicalEventType.SweepReclaim
                        ? "sweep_reclaim"
                        : eventType == CanonicalEventType.Rejection
                            ? "rejection"
                            : eventType == CanonicalEventType.Breakout
                                ? "breakout"
                                : eventType == CanonicalEventType.Pullback
                                    ? "pullback"
                                    : eventType == CanonicalEventType.Continuation
                                        ? "continuation"
                                        : "impulse";

            return new CanonicalMarketEvent
            {
                EventKey = string.Format(
                    CultureInfo.InvariantCulture,
                    "{0}_{1}",
                    isBullish ? "bullish" : "bearish",
                    eventSuffix + (string.IsNullOrWhiteSpace(levelKind) ? "" : "_" + levelKind.Trim().ToLowerInvariant())),
                SymbolName = string.IsNullOrWhiteSpace(symbolName) ? "" : symbolName.Trim().ToUpperInvariant(),
                TimeFrameLabel = GetMiniChartLabel(timeFrame),
                EventType = eventType,
                IsBullish = isBullish,
                Reason = reason,
                Action = action,
                BarTime = barTime,
                PriceRef = priceRef,
                Score = score,
                Confidence = confidence,
                SourceTimeFrame = timeFrame,
                ZoneLow = zoneLow,
                ZoneHigh = zoneHigh,
                LevelKind = levelKind ?? ""
            };
        }

        private CanonicalMarketEvent MapStructureEventToCanonical(string symbolName, StructureEvent evt)
        {
            return BuildCanonicalMarketEvent(
                symbolName,
                evt.SourceTimeFrame,
                evt.IsChoch ? CanonicalEventType.Choch : CanonicalEventType.Bos,
                evt.IsBullish,
                evt.IsChoch ? CanonicalEventReason.StructureReclaim : CanonicalEventReason.StructureBreak,
                evt.IsBullish ? CanonicalEventAction.Buy : CanonicalEventAction.Sell,
                evt.Time,
                evt.Price,
                evt.IsChoch ? 3 : 4,
                evt.IsChoch ? 72 : 80);
        }

        private List<ChartLevelCandidate> CollectTimeFrameStructuralLevelCandidates(Symbol symbol, Bars sourceBars, TimeFrame sourceTimeFrame)
        {
            var candidates = new List<ChartLevelCandidate>();
            if (symbol == null || sourceBars == null || sourceBars.Count < 5)
                return candidates;

            var tolerance = Math.Max(symbol.PipSize * 2.0, 0.0000001);

            int previousIndex;
            if (TryGetPreviousCompletedPeriodBarIndex(sourceBars, sourceTimeFrame, out previousIndex))
            {
                AddChartLevelCandidate(candidates, sourceBars.HighPrices[previousIndex], tolerance, 2, "PERIOD_HIGH");
                AddChartLevelCandidate(candidates, sourceBars.LowPrices[previousIndex], tolerance, 2, "PERIOD_LOW");
            }

            var start = ResolveWorkingStartIndex(sourceBars, 2, 2, sourceTimeFrame);
            var resistance = double.MinValue;
            var support = double.MaxValue;
            for (var i = start; i < sourceBars.Count - 2; i++)
            {
                resistance = Math.Max(resistance, sourceBars.HighPrices[i]);
                support = Math.Min(support, sourceBars.LowPrices[i]);
            }

            if (resistance > double.MinValue)
                AddChartLevelCandidate(candidates, resistance, tolerance, 1, "RESISTANCE");
            if (support < double.MaxValue)
                AddChartLevelCandidate(candidates, support, tolerance, 1, "SUPPORT");

            foreach (var swing in CollectConfirmedSwings(sourceBars, ResolveWorkingSwingLookbackBars(sourceBars, sourceTimeFrame)).TakeLast(10))
                AddChartLevelCandidate(candidates, swing.Price, tolerance, 2, swing.IsHigh ? "SWING_HIGH" : "SWING_LOW");

            AddFvgZoneCandidates(candidates, sourceBars, tolerance, 1);
            AddOrderBlockZoneCandidates(candidates, sourceBars, tolerance, 1);

            foreach (var zone in DetectScoredPriceZones(sourceBars, symbol, ResolveWorkingLookbackBars(sourceBars, sourceTimeFrame), sourceTimeFrame))
            {
                var zoneWeight = Math.Max(1, Math.Min(4, zone.Score / 4));
                AddChartLevelCandidate(candidates, (zone.Low + zone.High) * 0.5, tolerance, zoneWeight, "SD");
                AddChartLevelCandidate(candidates, zone.Low, tolerance, 1, "SD");
                AddChartLevelCandidate(candidates, zone.High, tolerance, 1, "SD");
            }

            return candidates
                .Where(x => x.Price > 0 && x.Weight > 0)
                .OrderByDescending(x => x.Weight)
                .ThenBy(x => x.Price)
                .ToList();
        }

        private List<CanonicalMarketEvent> CollectCanonicalSweepReclaimEvents(string symbolName, Symbol symbol, Bars sourceBars, TimeFrame sourceTimeFrame, int lookbackBars)
        {
            var events = new List<CanonicalMarketEvent>();
            if (symbol == null || sourceBars == null || sourceBars.Count < 8)
                return events;

            var snapshot = BuildStructureSnapshotV2(sourceBars, lookbackBars);
            foreach (var value in snapshot.Events.Where(item => item.Type == StructureEventTypeV2.Sweep))
            {
                if (value.ConfirmationBarIndex < 0 || value.ConfirmationBarIndex > snapshot.LastClosedBarIndex)
                    continue;
                if (!HasEventVolumeSurge(sourceBars, value.ConfirmationBarIndex))
                    continue;

                events.Add(BuildCanonicalMarketEvent(
                    symbolName,
                    sourceTimeFrame,
                    CanonicalEventType.SweepReclaim,
                    value.IsBullish,
                    CanonicalEventReason.LiquiditySweep,
                    value.IsBullish ? CanonicalEventAction.Buy : CanonicalEventAction.Sell,
                    sourceBars.OpenTimes[value.ConfirmationBarIndex],
                    value.ReferencePrice,
                    3,
                    76));
            }

            return events;
        }

        private List<ChartLevelCandidate> CollectTrendlineLevelCandidatesAtBar(Bars sourceBars, TimeFrame sourceTimeFrame, int barIndex)
        {
            var candidates = new List<ChartLevelCandidate>();
            if (sourceBars == null || barIndex < 6 || barIndex >= sourceBars.Count)
                return candidates;

            // End the structure snapshot before the event bar so historical TL events cannot
            // use a swing that was only confirmed later.
            var swings = CollectConfirmedSwings(
                sourceBars,
                ResolveWorkingSwingLookbackBars(sourceBars, sourceTimeFrame),
                barIndex - 1);
            foreach (var isHighLine in new[] { true, false })
            {
                var points = swings.Where(value => value.IsHigh == isHighLine).TakeLast(2).ToList();
                if (points.Count < 2 || points[1].BarIndex <= points[0].BarIndex || points[1].BarIndex >= barIndex)
                    continue;
                var slope = (points[1].Price - points[0].Price) / Math.Max(1.0, points[1].BarIndex - points[0].BarIndex);
                var projected = points[1].Price + slope * (barIndex - points[1].BarIndex);
                if (IsFiniteNumber(projected) && projected > 0)
                    candidates.Add(new ChartLevelCandidate { Price = projected, Weight = 3, Kind = "TL" });
            }
            return candidates;
        }

        private List<CanonicalMarketEvent> CollectCanonicalLevelReactionEvents(
            string symbolName,
            Symbol symbol,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int lookbackBars,
            bool includeRejection,
            bool includeBreakout)
        {
            var events = new List<CanonicalMarketEvent>();
            if ((!includeRejection && !includeBreakout) || symbol == null || sourceBars == null || sourceBars.Count < 5)
                return events;

            var candidates = CollectTimeFrameStructuralLevelCandidates(symbol, sourceBars, sourceTimeFrame);
            if (candidates.Count == 0)
                return events;

            var tolerance = Math.Max(symbol.PipSize * 2.0, 0.0000001);
            var startBar = Math.Max(2, sourceBars.Count - Math.Min(Math.Max(lookbackBars, 12), 40));

            for (var barIndex = startBar; barIndex < sourceBars.Count; barIndex++)
            {
                // Resolve the existing volume rule once per span and reuse it for every nearby
                // level on this bar. Multi-candle rejection uses the same averaged-volume path
                // as other multi-candle patterns; no per-level volume/history loop is added.
                var oneBarVolumeConfirmed = HasEventVolumeSurge(sourceBars, barIndex, 1);
                var twoBarVolumeConfirmed = includeRejection && HasEventVolumeSurge(sourceBars, barIndex, 2);
                var threeBarVolumeConfirmed = includeRejection && HasEventVolumeSurge(sourceBars, barIndex, 3);
                if (!oneBarVolumeConfirmed && !twoBarVolumeConfirmed && !threeBarVolumeConfirmed)
                    continue;

                var openV = sourceBars.OpenPrices[barIndex];
                var highV = sourceBars.HighPrices[barIndex];
                var lowV = sourceBars.LowPrices[barIndex];
                var closeV = sourceBars.ClosePrices[barIndex];
                var prevClose = sourceBars.ClosePrices[barIndex - 1];
                var prevOpen = sourceBars.OpenPrices[barIndex - 1];
                var barTime = sourceBars.OpenTimes[barIndex];
                var span = Math.Max(highV - lowV, tolerance);
                var sharedDetections = GetDetectedSharedRulePatternSet(sourceBars, sourceTimeFrame, barIndex);
                var nearbyLevels = candidates
                    .Concat(CollectTrendlineLevelCandidatesAtBar(sourceBars, sourceTimeFrame, barIndex))
                    .OrderByDescending(x => x.Weight)
                    .ThenBy(x => Math.Abs(x.Price - closeV))
                    .Take(14)
                    .ToList();

                foreach (var level in nearbyLevels)
                {
                    var levelPrice = level.Price;

                    if (includeRejection)
                    {
                        int bullishRejectionSpan;
                        var bullishReject = TryMatchBullishLevelRejection(
                            sourceBars,
                            barIndex,
                            levelPrice,
                            tolerance,
                            span,
                            sharedDetections,
                            prevOpen,
                            prevClose,
                            out bullishRejectionSpan);
                        var bullishVolumeConfirmed = bullishRejectionSpan == 1
                            ? oneBarVolumeConfirmed
                            : bullishRejectionSpan == 2
                                ? twoBarVolumeConfirmed
                                : bullishRejectionSpan == 3 && threeBarVolumeConfirmed;
                        if (bullishReject && bullishVolumeConfirmed)
                        {
                            events.Add(BuildCanonicalMarketEvent(
                                symbolName,
                                sourceTimeFrame,
                                CanonicalEventType.Rejection,
                                true,
                                CanonicalEventReason.KeyLevelRejection,
                                CanonicalEventAction.Buy,
                                barTime,
                                levelPrice,
                                2 + Math.Min(level.Weight, 2),
                                68 + Math.Min(level.Weight * 2, 8),
                                level.ZoneLow,
                                level.ZoneHigh,
                                level.Kind));
                        }

                        int bearishRejectionSpan;
                        var bearishReject = TryMatchBearishLevelRejection(
                            sourceBars,
                            barIndex,
                            levelPrice,
                            tolerance,
                            span,
                            sharedDetections,
                            prevOpen,
                            prevClose,
                            out bearishRejectionSpan);
                        var bearishVolumeConfirmed = bearishRejectionSpan == 1
                            ? oneBarVolumeConfirmed
                            : bearishRejectionSpan == 2
                                ? twoBarVolumeConfirmed
                                : bearishRejectionSpan == 3 && threeBarVolumeConfirmed;
                        if (bearishReject && bearishVolumeConfirmed)
                        {
                            events.Add(BuildCanonicalMarketEvent(
                                symbolName,
                                sourceTimeFrame,
                                CanonicalEventType.Rejection,
                                false,
                                CanonicalEventReason.KeyLevelRejection,
                                CanonicalEventAction.Sell,
                                barTime,
                                levelPrice,
                                2 + Math.Min(level.Weight, 2),
                                68 + Math.Min(level.Weight * 2, 8),
                                level.ZoneLow,
                                level.ZoneHigh,
                                level.Kind));
                        }
                    }

                    if (includeBreakout)
                    {
                        if (!oneBarVolumeConfirmed)
                            continue;
                        var bullishBreakout = IsStrictBullishLevelBreakout(
                            sourceBars,
                            barIndex,
                            levelPrice,
                            tolerance,
                            span,
                            sharedDetections,
                            prevOpen,
                            prevClose);
                        if (bullishBreakout)
                        {
                            events.Add(BuildCanonicalMarketEvent(
                                symbolName,
                                sourceTimeFrame,
                                CanonicalEventType.Breakout,
                                true,
                                CanonicalEventReason.StructureBreak,
                                CanonicalEventAction.Buy,
                                barTime,
                                levelPrice,
                                3 + Math.Min(level.Weight, 2),
                                72 + Math.Min(level.Weight * 2, 8),
                                level.ZoneLow,
                                level.ZoneHigh,
                                level.Kind));
                        }

                        var bearishBreakout = IsStrictBearishLevelBreakout(
                            sourceBars,
                            barIndex,
                            levelPrice,
                            tolerance,
                            span,
                            sharedDetections,
                            prevOpen,
                            prevClose);
                        if (bearishBreakout)
                        {
                            events.Add(BuildCanonicalMarketEvent(
                                symbolName,
                                sourceTimeFrame,
                                CanonicalEventType.Breakout,
                                false,
                                CanonicalEventReason.StructureBreak,
                                CanonicalEventAction.Sell,
                                barTime,
                                levelPrice,
                                3 + Math.Min(level.Weight, 2),
                                72 + Math.Min(level.Weight * 2, 8),
                                level.ZoneLow,
                                level.ZoneHigh,
                                level.Kind));
                        }
                    }
                }
            }

            return events;
        }

        private bool TryMatchBullishLevelRejection(
            Bars sourceBars, int barIndex, double levelPrice, double tolerance, double span,
            HashSet<string> sharedDetections, double prevOpen, double prevClose, out int patternSpan)
        {
            patternSpan = 0;
            if (sourceBars == null || barIndex <= 0 || barIndex >= sourceBars.Count)
                return false;
            var patternConfirmed =
                sharedDetections.Contains("bullish_pin_bar") ||
                sharedDetections.Contains("bullish_hammer") ||
                sharedDetections.Contains("bullish_inverted_hammer") ||
                sharedDetections.Contains("bullish_engulfing") ||
                sharedDetections.Contains("bullish_harami") ||
                sharedDetections.Contains("bullish_morning_star") ||
                sharedDetections.Contains("bullish_piercing_line");
            if (_structureEngine.IsStrictLevelRejection(
                sourceBars.OpenPrices[barIndex], sourceBars.HighPrices[barIndex], sourceBars.LowPrices[barIndex], sourceBars.ClosePrices[barIndex],
                prevOpen, prevClose, levelPrice, tolerance, span, true, patternConfirmed, GetRejectionWickDominanceRatio()))
            {
                patternSpan = 1;
                return true;
            }

            return TryMatchMultiCandleLevelRejection(sourceBars, barIndex, levelPrice, tolerance, true, out patternSpan);
        }

        private bool TryMatchBearishLevelRejection(
            Bars sourceBars, int barIndex, double levelPrice, double tolerance, double span,
            HashSet<string> sharedDetections, double prevOpen, double prevClose, out int patternSpan)
        {
            patternSpan = 0;
            if (sourceBars == null || barIndex <= 0 || barIndex >= sourceBars.Count)
                return false;
            var patternConfirmed =
                sharedDetections.Contains("bearish_pin_bar") ||
                sharedDetections.Contains("shooting_star") ||
                sharedDetections.Contains("hanging_man") ||
                sharedDetections.Contains("bearish_engulfing") ||
                sharedDetections.Contains("bearish_harami") ||
                sharedDetections.Contains("bearish_evening_star") ||
                sharedDetections.Contains("bearish_dark_cloud_cover");
            if (_structureEngine.IsStrictLevelRejection(
                sourceBars.OpenPrices[barIndex], sourceBars.HighPrices[barIndex], sourceBars.LowPrices[barIndex], sourceBars.ClosePrices[barIndex],
                prevOpen, prevClose, levelPrice, tolerance, span, false, patternConfirmed, GetRejectionWickDominanceRatio()))
            {
                patternSpan = 1;
                return true;
            }

            return TryMatchMultiCandleLevelRejection(sourceBars, barIndex, levelPrice, tolerance, false, out patternSpan);
        }

        private bool TryMatchMultiCandleLevelRejection(
            Bars sourceBars,
            int confirmationIndex,
            double levelPrice,
            double tolerance,
            bool bullish,
            out int patternSpan)
        {
            patternSpan = 0;
            if (sourceBars == null || confirmationIndex < 2 || confirmationIndex >= sourceBars.Count)
                return false;

            var probeIndex = confirmationIndex - 1;
            if (_structureEngine.IsMultiCandleLevelRejection(
                sourceBars.ClosePrices[probeIndex - 1],
                sourceBars.OpenPrices[probeIndex], sourceBars.HighPrices[probeIndex], sourceBars.LowPrices[probeIndex], sourceBars.ClosePrices[probeIndex],
                false, 0.0,
                sourceBars.OpenPrices[confirmationIndex], sourceBars.HighPrices[confirmationIndex], sourceBars.LowPrices[confirmationIndex], sourceBars.ClosePrices[confirmationIndex],
                levelPrice, tolerance, bullish))
            {
                patternSpan = 2;
                return true;
            }

            if (confirmationIndex < 3)
                return false;

            probeIndex = confirmationIndex - 2;
            if (!_structureEngine.IsMultiCandleLevelRejection(
                sourceBars.ClosePrices[probeIndex - 1],
                sourceBars.OpenPrices[probeIndex], sourceBars.HighPrices[probeIndex], sourceBars.LowPrices[probeIndex], sourceBars.ClosePrices[probeIndex],
                true, sourceBars.ClosePrices[confirmationIndex - 1],
                sourceBars.OpenPrices[confirmationIndex], sourceBars.HighPrices[confirmationIndex], sourceBars.LowPrices[confirmationIndex], sourceBars.ClosePrices[confirmationIndex],
                levelPrice, tolerance, bullish))
                return false;

            patternSpan = 3;
            return true;
        }

        private double GetRejectionWickDominanceRatio()
        {
            switch (RejectionWickDominance)
            {
                case RejectionWickDominanceMode._0_5:
                    return 0.5;
                case RejectionWickDominanceMode._1:
                    return 1.0;
                case RejectionWickDominanceMode._1_5:
                    return 1.5;
                case RejectionWickDominanceMode._2:
                    return 2.0;
                case RejectionWickDominanceMode.No:
                default:
                    return 0.0;
            }
        }

        private bool IsStrictBullishLevelBreakout(
            Bars sourceBars, int barIndex, double levelPrice, double tolerance, double span,
            HashSet<string> sharedDetections, double prevOpen, double prevClose)
        {
            if (sourceBars == null || barIndex <= 0 || barIndex >= sourceBars.Count)
                return false;
            var patternConfirmed =
                IsBigDirectionalCandle(sourceBars, barIndex, true) ||
                sharedDetections.Contains("bullish_engulfing") ||
                sharedDetections.Contains("bullish_three_white_soldiers") ||
                sharedDetections.Contains("bullish_morning_star");
            return _structureEngine.IsStrictLevelBreakout(
                sourceBars.OpenPrices[barIndex], sourceBars.HighPrices[barIndex], sourceBars.LowPrices[barIndex], sourceBars.ClosePrices[barIndex],
                prevOpen, prevClose, levelPrice, tolerance, span, true,
                IsStrongDirectionalCandle(sourceBars, barIndex, true), patternConfirmed);
        }

        private bool IsStrictBearishLevelBreakout(
            Bars sourceBars, int barIndex, double levelPrice, double tolerance, double span,
            HashSet<string> sharedDetections, double prevOpen, double prevClose)
        {
            if (sourceBars == null || barIndex <= 0 || barIndex >= sourceBars.Count)
                return false;
            var patternConfirmed =
                IsBigDirectionalCandle(sourceBars, barIndex, false) ||
                sharedDetections.Contains("bearish_engulfing") ||
                sharedDetections.Contains("bearish_three_black_crows") ||
                sharedDetections.Contains("bearish_evening_star");
            return _structureEngine.IsStrictLevelBreakout(
                sourceBars.OpenPrices[barIndex], sourceBars.HighPrices[barIndex], sourceBars.LowPrices[barIndex], sourceBars.ClosePrices[barIndex],
                prevOpen, prevClose, levelPrice, tolerance, span, false,
                IsStrongDirectionalCandle(sourceBars, barIndex, false), patternConfirmed);
        }


        private double ComputeEmaAtIndex(Bars sourceBars, int period, int index)
        {
            return CTraderTechnicalEngine.ComputeEmaAtIndex(sourceBars, period, index);
        }

        private double ComputeRollingVwapAtIndex(Bars sourceBars, int length, int index)
        {
            return CTraderTechnicalEngine.ComputeRollingVwap(sourceBars, length, index);
        }

        private double ComputeMedianRange(Bars sourceBars, int index, int lookback)
        {
            return CTraderTechnicalEngine.ComputeMedianRange(sourceBars, index, lookback);
        }

        private CanonicalMarketEvent? FindLatestDirectionalSeedEvent(List<CanonicalMarketEvent> seedEvents, DateTime barTime)
        {
            if (seedEvents == null || seedEvents.Count == 0)
                return null;

            foreach (var evt in seedEvents
                .Where(e =>
                    e.BarTime <= barTime &&
                    (e.EventType == CanonicalEventType.Choch ||
                     e.EventType == CanonicalEventType.Bos ||
                     e.EventType == CanonicalEventType.SweepReclaim ||
                     e.EventType == CanonicalEventType.Rejection ||
                     e.EventType == CanonicalEventType.Breakout))
                .OrderByDescending(e => e.BarTime)
                .ThenByDescending(e => e.Score))
            {
                return evt;
            }

            return null;
        }

        private bool HasDirectionalEventOnBar(List<CanonicalMarketEvent> events, DateTime barTime, bool isBullish, params CanonicalEventType[] types)
        {
            if (events == null || types == null || types.Length == 0)
                return false;

            return events.Any(e =>
                e.BarTime == barTime &&
                e.IsBullish == isBullish &&
                types.Contains(e.EventType));
        }

        private List<CanonicalMarketEvent> CollectCanonicalPhaseEvents(
            string symbolName,
            Symbol symbol,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            List<CanonicalMarketEvent> seedEvents,
            int lookbackBars,
            bool includePullback,
            bool includeContinuation,
            bool includeImpulse)
        {
            var events = new List<CanonicalMarketEvent>();
            if ((!includePullback && !includeContinuation && !includeImpulse) ||
                symbol == null || sourceBars == null || sourceBars.Count < 25)
                return events;

            var tolerance = Math.Max(symbol.PipSize * 2.0, 0.0000001);
            var startBar = Math.Max(20, sourceBars.Count - Math.Min(Math.Max(lookbackBars, 20), 60));

            for (var barIndex = startBar; barIndex < sourceBars.Count; barIndex++)
            {
                if (!HasEventVolumeSurge(sourceBars, barIndex))
                    continue;

                var barTime = sourceBars.OpenTimes[barIndex];
                var latestSeed = FindLatestDirectionalSeedEvent(seedEvents, barTime);
                if (!latestSeed.HasValue)
                    continue;

                var seed = latestSeed.Value;
                var openV = sourceBars.OpenPrices[barIndex];
                var highV = sourceBars.HighPrices[barIndex];
                var lowV = sourceBars.LowPrices[barIndex];
                var closeV = sourceBars.ClosePrices[barIndex];
                var prevClose = sourceBars.ClosePrices[Math.Max(0, barIndex - 1)];
                var needsEma = includePullback || includeContinuation;
                var ema20 = needsEma ? ComputeEmaAtIndex(sourceBars, 20, barIndex) : double.NaN;
                var ema20Prev = needsEma ? ComputeEmaAtIndex(sourceBars, 20, Math.Max(0, barIndex - 1)) : double.NaN;
                var vwap20 = includeContinuation ? ComputeRollingVwapAtIndex(sourceBars, 20, barIndex) : double.NaN;
                var vwap20Prev = includeContinuation ? ComputeRollingVwapAtIndex(sourceBars, 20, Math.Max(0, barIndex - 1)) : double.NaN;
                var range = Math.Max(highV - lowV, tolerance);
                var body = Math.Abs(closeV - openV);
                var medianRange = includeImpulse ? ComputeMedianRange(sourceBars, barIndex, 8) : 0.0;
                var displacement = includeImpulse && range > 0 && body / range >= 0.6 && medianRange > 0 && range >= medianRange * 1.1;
                var isBullishBias = seed.IsBullish;

                var bullishPullback = includePullback && isBullishBias &&
                    !double.IsNaN(ema20) &&
                    !double.IsNaN(ema20Prev) &&
                    prevClose > ema20Prev &&
                    lowV <= ema20 + tolerance &&
                    closeV >= ema20;
                if (bullishPullback)
                {
                    events.Add(BuildCanonicalMarketEvent(
                        symbolName,
                        sourceTimeFrame,
                        CanonicalEventType.Pullback,
                        true,
                        CanonicalEventReason.EmaReclaim,
                        CanonicalEventAction.Wait,
                        barTime,
                        ema20,
                        2,
                        66));
                }

                var bearishPullback = includePullback && !isBullishBias &&
                    !double.IsNaN(ema20) &&
                    !double.IsNaN(ema20Prev) &&
                    prevClose < ema20Prev &&
                    highV >= ema20 - tolerance &&
                    closeV <= ema20;
                if (bearishPullback)
                {
                    events.Add(BuildCanonicalMarketEvent(
                        symbolName,
                        sourceTimeFrame,
                        CanonicalEventType.Pullback,
                        false,
                        CanonicalEventReason.EmaReclaim,
                        CanonicalEventAction.Wait,
                        barTime,
                        ema20,
                        2,
                        66));
                }

                var bullishContinuation = includeContinuation && isBullishBias &&
                    !double.IsNaN(ema20) &&
                    !double.IsNaN(vwap20) &&
                    !double.IsNaN(ema20Prev) &&
                    !double.IsNaN(vwap20Prev) &&
                    prevClose <= Math.Max(ema20Prev, vwap20Prev) + tolerance &&
                    closeV > ema20 &&
                    closeV > vwap20;
                if (bullishContinuation)
                {
                    events.Add(BuildCanonicalMarketEvent(
                        symbolName,
                        sourceTimeFrame,
                        CanonicalEventType.Continuation,
                        true,
                        CanonicalEventReason.VwapReclaim,
                        CanonicalEventAction.Buy,
                        barTime,
                        closeV,
                        3,
                        72));
                }

                var bearishContinuation = includeContinuation && !isBullishBias &&
                    !double.IsNaN(ema20) &&
                    !double.IsNaN(vwap20) &&
                    !double.IsNaN(ema20Prev) &&
                    !double.IsNaN(vwap20Prev) &&
                    prevClose >= Math.Min(ema20Prev, vwap20Prev) - tolerance &&
                    closeV < ema20 &&
                    closeV < vwap20;
                if (bearishContinuation)
                {
                    events.Add(BuildCanonicalMarketEvent(
                        symbolName,
                        sourceTimeFrame,
                        CanonicalEventType.Continuation,
                        false,
                        CanonicalEventReason.VwapReclaim,
                        CanonicalEventAction.Sell,
                        barTime,
                        closeV,
                        3,
                        72));
                }

                var bullishImpulse = includeImpulse && isBullishBias &&
                    displacement &&
                    HasDirectionalEventOnBar(seedEvents, barTime, true, CanonicalEventType.Bos, CanonicalEventType.Breakout);
                if (bullishImpulse)
                {
                    events.Add(BuildCanonicalMarketEvent(
                        symbolName,
                        sourceTimeFrame,
                        CanonicalEventType.Impulse,
                        true,
                        CanonicalEventReason.MomentumShift,
                        CanonicalEventAction.Buy,
                        barTime,
                        closeV,
                        4,
                        78));
                }

                var bearishImpulse = includeImpulse && !isBullishBias &&
                    displacement &&
                    HasDirectionalEventOnBar(seedEvents, barTime, false, CanonicalEventType.Bos, CanonicalEventType.Breakout);
                if (bearishImpulse)
                {
                    events.Add(BuildCanonicalMarketEvent(
                        symbolName,
                        sourceTimeFrame,
                        CanonicalEventType.Impulse,
                        false,
                        CanonicalEventReason.MomentumShift,
                        CanonicalEventAction.Sell,
                        barTime,
                        closeV,
                        4,
                        78));
                }
            }

            return events;
        }

        private List<CanonicalMarketEvent> GetCanonicalEventsForSymbolTimeFrame(string symbolName, TimeFrame timeFrame, int maxEvents = 3)
        {
            var empty = new List<CanonicalMarketEvent>();
            if (string.IsNullOrWhiteSpace(symbolName))
                return empty;

            var anyStructureEventEnabled =
                _toggleChochDetections ||
                _toggleBosDetections ||
                _toggleSweepDetections ||
                _toggleRejectionDetections ||
                _toggleBreakoutDetections ||
                _togglePullbackDetections ||
                _toggleContinuationDetections ||
                _toggleImpulseDetections;
            if (!anyStructureEventEnabled)
                return empty;

            var normalizedSymbol = symbolName.Trim().ToUpperInvariant();
            var cacheKey = BuildDashboardEventCacheKey(normalizedSymbol, timeFrame);
            TimedCacheEntry<List<CanonicalMarketEvent>> cached;
            if (_dashboardEventCache.TryGetValue(cacheKey, out cached) &&
                cached != null &&
                cached.Value != null &&
                (DateTime.UtcNow - cached.CreatedAtUtc) <= TimeSpan.FromSeconds(3))
            {
                LogPerfStep("CanonicalEventsCacheHit", 25, string.Format(CultureInfo.InvariantCulture, "{0} {1} -> {2}", normalizedSymbol, GetMiniChartLabel(timeFrame), cached.Value.Count));
                return cached.Value.Take(Math.Max(1, maxEvents)).ToList();
            }

            try
            {
                var started = Stopwatch.StartNew();
                var symbol = ResolveLoadedSymbol(normalizedSymbol);
                if (symbol == null)
                    return empty;

                var bars = GetBarsForCurrentMasterTimer(timeFrame, normalizedSymbol);
                if (bars == null || bars.Count < 20)
                    return empty;

                var latestClosedIndex = bars.Count - 2;
                if (latestClosedIndex < 0)
                    return empty;

                var coverageStartIndex = Math.Max(0, latestClosedIndex - 180);
                var latestClosedUnix = ToUnixSecondsSafe(bars.OpenTimes[latestClosedIndex]);
                var usePersistedCache = AreAllCanonicalStructureEventsEnabled();
                var persisted = usePersistedCache
                    ? LoadPersistedCanonicalEventCache(normalizedSymbol, timeFrame)
                    : null;
                if (usePersistedCache && HasCanonicalEventCacheCoverage(persisted, bars, coverageStartIndex, latestClosedIndex))
                {
                    var persistedEvents = DeduplicateCanonicalEvents(
                        persisted.Events.Where(evt =>
                        {
                            var eventUnix = ToUnixSecondsSafe(evt.BarTime);
                            return eventUnix >= ToUnixSecondsSafe(bars.OpenTimes[coverageStartIndex]) && eventUnix <= latestClosedUnix;
                        }));
                    _dashboardEventCache[cacheKey] = new TimedCacheEntry<List<CanonicalMarketEvent>>
                    {
                        CreatedAtUtc = DateTime.UtcNow,
                        Value = persistedEvents
                    };
                    LogPerfStep("CanonicalEventsDiskCacheHit", 20, string.Format(CultureInfo.InvariantCulture, "{0} {1} -> {2}", normalizedSymbol, GetMiniChartLabel(timeFrame), persistedEvents.Count));
                    return persistedEvents.Take(Math.Max(1, maxEvents)).ToList();
                }

                var canonical = new List<CanonicalMarketEvent>();
                if (_toggleChochDetections || _toggleBosDetections)
                {
                    var structureStarted = Stopwatch.StartNew();
                    canonical.AddRange(
                        CollectStructureEvents(bars, timeFrame, 180)
                            .Where(evt => evt.IsChoch ? _toggleChochDetections : _toggleBosDetections)
                            .Select(evt => MapStructureEventToCanonical(normalizedSymbol, evt)));
                    LogSlowChartStep("CanonicalEvents.Structure", structureStarted, string.Format(CultureInfo.InvariantCulture, "{0} {1} -> {2}", normalizedSymbol, GetMiniChartLabel(timeFrame), canonical.Count));
                }

                if (_toggleSweepDetections)
                {
                    var sweepStarted = Stopwatch.StartNew();
                    canonical.AddRange(CollectCanonicalSweepReclaimEvents(normalizedSymbol, symbol, bars, timeFrame, 180));
                    LogSlowChartStep("CanonicalEvents.Sweep", sweepStarted, string.Format(CultureInfo.InvariantCulture, "{0} {1} -> {2}", normalizedSymbol, GetMiniChartLabel(timeFrame), canonical.Count));
                }

                if (_toggleRejectionDetections || _toggleBreakoutDetections)
                {
                    var reactionStarted = Stopwatch.StartNew();
                    canonical.AddRange(CollectCanonicalLevelReactionEvents(
                        normalizedSymbol,
                        symbol,
                        bars,
                        timeFrame,
                        180,
                        _toggleRejectionDetections,
                        _toggleBreakoutDetections));
                    LogSlowChartStep("CanonicalEvents.LevelReaction", reactionStarted, string.Format(CultureInfo.InvariantCulture, "{0} {1} -> {2}", normalizedSymbol, GetMiniChartLabel(timeFrame), canonical.Count));
                }

                if (_togglePullbackDetections || _toggleContinuationDetections || _toggleImpulseDetections)
                {
                    var phaseStarted = Stopwatch.StartNew();
                    canonical.AddRange(CollectCanonicalPhaseEvents(
                        normalizedSymbol,
                        symbol,
                        bars,
                        timeFrame,
                        canonical.ToList(),
                        180,
                        _togglePullbackDetections,
                        _toggleContinuationDetections,
                        _toggleImpulseDetections));
                    LogSlowChartStep("CanonicalEvents.Phase", phaseStarted, string.Format(CultureInfo.InvariantCulture, "{0} {1} -> {2}", normalizedSymbol, GetMiniChartLabel(timeFrame), canonical.Count));
                }

                var normalizeStarted = Stopwatch.StartNew();
                canonical = canonical
                    .Where(evt => IsCanonicalStructureEventEnabled(evt.EventType) && ToUnixSecondsSafe(evt.BarTime) <= latestClosedUnix)
                    .ToList();
                canonical = DeduplicateCanonicalEvents(canonical);
                LogSlowChartStep("CanonicalEvents.Normalize", normalizeStarted, string.Format(CultureInfo.InvariantCulture, "{0} {1} -> {2}", normalizedSymbol, GetMiniChartLabel(timeFrame), canonical.Count));

                if (usePersistedCache)
                {
                    MergeCanonicalEventCacheCoverage(persisted, bars, coverageStartIndex, latestClosedIndex, canonical.Where(evt =>
                    {
                        var eventUnix = ToUnixSecondsSafe(evt.BarTime);
                        return eventUnix >= ToUnixSecondsSafe(bars.OpenTimes[coverageStartIndex]) && eventUnix <= latestClosedUnix;
                    }));
                    PruneCanonicalEventCache(persisted, bars, latestClosedIndex);
                    StorePersistedCanonicalEventCache(normalizedSymbol, timeFrame, persisted);
                }

                _dashboardEventCache[cacheKey] = new TimedCacheEntry<List<CanonicalMarketEvent>>
                {
                    CreatedAtUtc = DateTime.UtcNow,
                    Value = canonical
                };
                LogSlowChartStep("CanonicalEvents.Total", started, string.Format(CultureInfo.InvariantCulture, "{0} {1} -> {2}", normalizedSymbol, GetMiniChartLabel(timeFrame), canonical.Count));
                return canonical.Take(Math.Max(1, maxEvents)).ToList();
            }
            catch
            {
                return empty;
            }
        }

        private string FormatCanonicalEventReasonShort(CanonicalEventReason reason)
        {
            switch (reason)
            {
                case CanonicalEventReason.StructureReclaim:
                    return "recl";
                case CanonicalEventReason.StructureBreak:
                    return "brk";
                case CanonicalEventReason.LiquiditySweep:
                    return "liq";
                case CanonicalEventReason.KeyLevelRejection:
                    return "rej";
                case CanonicalEventReason.EmaReclaim:
                    return "ema";
                case CanonicalEventReason.VwapReclaim:
                    return "vwap";
                case CanonicalEventReason.BiasAlignment:
                    return "bias";
                case CanonicalEventReason.MomentumShift:
                    return "mom";
                default:
                    return "na";
            }
        }

        private string FormatDashboardEventCompact(CanonicalMarketEvent? evt)
        {
            if (!evt.HasValue)
                return "-";
            return BuildCanonicalMarketEventName(evt.Value);
        }

        private Color GetCanonicalEventColor(CanonicalMarketEvent? evt)
        {
            if (!evt.HasValue)
                return Color.LightGray;
            return GetTimeFrameStructureColor(evt.Value.SourceTimeFrame);
        }

        private int DrawKeyLevelsOnChart(int objectIndex)
        {
            try
            {
                objectIndex = DrawPreviousPeriodLevels(objectIndex, TimeFrame.Hour, "h1", GetTimeFrameStructureColor(TimeFrame.Hour));
                objectIndex = DrawPreviousPeriodLevels(objectIndex, TimeFrame.Hour4, "h4", GetTimeFrameStructureColor(TimeFrame.Hour4));
                objectIndex = DrawPreviousPeriodLevels(objectIndex, TimeFrame.Daily, "d1", GetTimeFrameStructureColor(TimeFrame.Daily));
                objectIndex = DrawSwingAndSrLevels(objectIndex);
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Key levels failed: {0}", ex.Message);
            }

            return objectIndex;
        }

        private int DrawScoredPriceZones(int objectIndex)
        {
            if (Bars == null || Bars.Count < 20 || Symbol == null)
                return objectIndex;

            var zones = DetectScoredPriceZones(Bars, Symbol, ResolveWorkingLookbackBars(Bars, Chart != null ? Chart.TimeFrame : TimeFrame.Minute), Chart != null ? Chart.TimeFrame : TimeFrame.Minute);
            if (zones.Count == 0)
                return objectIndex;

            var currentPrice = Symbol.Bid > 0 ? Symbol.Bid : (Symbol.Ask > 0 ? Symbol.Ask : 0);
            if (currentPrice <= 0)
                return objectIndex;

            // SMC role flip: a zone price has broken through changes role — a supply zone now
            // below price is demand (support), a demand zone now above price is supply (resistance).
            var resolved = new List<ScoredPriceZone>();
            foreach (var zone in zones)
            {
                if (zone.High < currentPrice)
                    resolved.Add(WithZoneKind(zone, ScoredPriceZoneKind.Demand));
                else if (zone.Low > currentPrice)
                    resolved.Add(WithZoneKind(zone, ScoredPriceZoneKind.Supply));
            }

            // Only the 2 nearest zones per side: DEMAND (support) below price, SPLY (resistance) above.
            var shown = resolved
                .Where(zone => zone.High > zone.Low)
                .OrderByDescending(zone => zone.High)
                .Take(2)
                .Concat(resolved
                    .Where(zone => zone.High > zone.Low)
                    .OrderBy(zone => zone.Low)
                    .Take(2))
                .ToList();
            if (shown.Count == 0)
                return objectIndex;

            var currentEndTime = GetCurrentChartEndTime();
            foreach (var zone in shown)
            {
                var color = GetTimeFrameStructureColor(Chart != null ? Chart.TimeFrame : TimeFrame.Minute);
                var fillColor = WithAlpha(color, 18);
                var endTime = zone.VisitCount > 1
                    ? ResolveBufferedArtifactEndTime(Bars, Chart != null ? Chart.TimeFrame : TimeFrame.Minute, zone.LastTouchBarIndex, currentEndTime)
                    : currentEndTime;

                var rect = Chart.DrawRectangle("PZ_" + objectIndex.ToString(CultureInfo.InvariantCulture), zone.StartTime, zone.High, endTime, zone.Low, fillColor);
                TrySetPropertyValue(rect, "IsFilled", true);
                TrySetPropertyValue(rect, "Color", fillColor);
                TrySetPropertyValue(rect, "BorderColor", WithAlpha(color, 80));
                TrySetPropertyValue(rect, "Thickness", 1);
                TrySetEnumPropertyValue(rect, "LineStyle", "Dots");
                TrySetChartObjectBackground(rect);

                // Label at the right edge (current time), same position as the FVG/OB zone labels.
                var label = zone.Kind == ScoredPriceZoneKind.Supply ? "SPLY" : "DEM";
                DrawArtifactZoneLabel("PZ", objectIndex, (zone.High + zone.Low) * 0.5, color, label, endTime, currentEndTime, GetNormalChartLabelFontSize());

                objectIndex++;
            }

            return objectIndex;
        }

        private ScoredPriceZone WithZoneKind(ScoredPriceZone zone, ScoredPriceZoneKind kind)
        {
            zone.Kind = kind;
            return zone;
        }

        private bool ShouldShowLowerTimeframeSessionContext()
        {
            var chartTimeFrame = Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
            var chartTfMinutes = TimeFrameToMinutes(chartTimeFrame);
            return chartTfMinutes > 0 && chartTfMinutes <= 15;
        }

        private int DrawPreviousSessionLevels(int objectIndex)
        {
            var prevDate = GetReferenceNow().Date.AddDays(-1);
            objectIndex = DrawSessionHighLow(objectIndex, "London", prevDate, GetSessionAccentColor("London"));
            objectIndex = DrawSessionHighLow(objectIndex, "NY", prevDate, GetSessionAccentColor("NY"));
            objectIndex = DrawSessionHighLow(objectIndex, "Asia", prevDate, GetSessionAccentColor("Asia"));
            return objectIndex;
        }

        private int DrawSessionHighLow(int objectIndex, string label, DateTime date, Color color)
        {
            DateTime startUtc;
            DateTime endUtc;
            if (!TryGetSessionUtcRange(label, date, out startUtc, out endUtc))
                return objectIndex;

            double high;
            double low;
            DateTime highTime;
            DateTime lowTime;
            if (!TryGetRangeHighLow(Bars, startUtc, endUtc, out high, out low, out highTime, out lowTime))
                return objectIndex;

            objectIndex = DrawHorizontalGuide(objectIndex, label, highTime, high, color, true);
            objectIndex = DrawHorizontalGuide(objectIndex, label, lowTime, low, color, false);
            return objectIndex;
        }

        private int DrawPreviousPeriodLevels(int objectIndex, TimeFrame timeFrame, string labelPrefix, Color color)
        {
            try
            {
                if (Chart != null && !ShouldProjectPreviousBarLevel(timeFrame, Chart.TimeFrame))
                    return objectIndex;

                var sourceBars = GetBarsForCurrentMasterTimer(timeFrame, Chart.SymbolName);
                if (sourceBars == null || sourceBars.Count < 1)
                    return objectIndex;

                int idx;
                if (!TryGetPreviousCompletedPeriodBarIndex(sourceBars, timeFrame, out idx))
                    return objectIndex;
                var periodEnd = idx + 1 < sourceBars.Count
                    ? sourceBars.OpenTimes[idx + 1]
                    : sourceBars.OpenTimes[idx].AddMinutes(Math.Max(1, TimeFrameToMinutes(timeFrame)));
                objectIndex = DrawPreviousPeriodLevelWithExtension(objectIndex, labelPrefix + ".p.h", sourceBars.OpenTimes[idx], periodEnd, sourceBars.HighPrices[idx], color, timeFrame);
                objectIndex = DrawPreviousPeriodLevelWithExtension(objectIndex, labelPrefix + ".p.l", sourceBars.OpenTimes[idx], periodEnd, sourceBars.LowPrices[idx], color, timeFrame);
            }
            catch
            {
            }
            return objectIndex;
        }

        private int DrawPreviousPeriodLevelWithExtension(
            int objectIndex,
            string label,
            DateTime periodStart,
            DateTime periodEnd,
            double price,
            Color baseColor,
            TimeFrame sourceTimeFrame)
        {
            if (Chart == null || periodStart == DateTime.MinValue || !IsFiniteNumber(price))
                return objectIndex;
            if (periodEnd <= periodStart)
                periodEnd = periodStart.AddMinutes(Math.Max(1, TimeFrameToMinutes(sourceTimeFrame)));

            var id = objectIndex.ToString(CultureInfo.InvariantCulture);
            var completedColor = WithAlpha(baseColor, 100);
            var completed = Chart.DrawTrendLine("KEY_DONE_" + id, periodStart, price, periodEnd, price, completedColor);
            TrySetPropertyValue(completed, "Thickness", 1);
            TrySetEnumPropertyValue(completed, "LineStyle", "Solid");

            var currentEnd = GetCurrentChartEndTime();
            if (currentEnd > periodEnd)
            {
                var projectionColor = WithAlpha(baseColor, 30);
                var projection = Chart.DrawTrendLine("KEY_PROJ_" + id, periodEnd, price, currentEnd, price, projectionColor);
                TrySetPropertyValue(projection, "Thickness", 1);
                TrySetEnumPropertyValue(projection, "LineStyle", "Dots");
                if (!string.IsNullOrWhiteSpace(label))
                    DrawRightEdgeZoneLabel("KEY", objectIndex, price, projectionColor, label, GetNormalChartLabelFontSize(), sourceTimeFrame);
            }

            return objectIndex + 1;
        }

        private int DrawSwingAndSrLevels(int objectIndex)
        {
            var resistance = double.MinValue;
            var support = double.MaxValue;
            var recentHigh = double.MinValue;
            var recentLow = double.MaxValue;
            var resistanceTime = DateTime.MinValue;
            var supportTime = DateTime.MinValue;
            var recentHighTime = DateTime.MinValue;
            var recentLowTime = DateTime.MinValue;

            var start = ResolveWorkingStartIndex(Bars, 2, 2, Chart != null ? Chart.TimeFrame : TimeFrame.Minute);
            for (var i = start; i < Bars.Count - 2; i++)
            {
                var high = Bars.HighPrices[i];
                var low = Bars.LowPrices[i];
                if (high > resistance)
                {
                    resistance = high;
                    resistanceTime = Bars.OpenTimes[i];
                }
                if (low < support)
                {
                    support = low;
                    supportTime = Bars.OpenTimes[i];
                }

                if (Bars.HighPrices[i] > Bars.HighPrices[i - 1] && Bars.HighPrices[i] > Bars.HighPrices[i - 2] &&
                    Bars.HighPrices[i] > Bars.HighPrices[i + 1] && Bars.HighPrices[i] > Bars.HighPrices[i + 2])
                {
                    recentHigh = high;
                    recentHighTime = Bars.OpenTimes[i];
                }
                if (Bars.LowPrices[i] < Bars.LowPrices[i - 1] && Bars.LowPrices[i] < Bars.LowPrices[i - 2] &&
                    Bars.LowPrices[i] < Bars.LowPrices[i + 1] && Bars.LowPrices[i] < Bars.LowPrices[i + 2])
                {
                    recentLow = low;
                    recentLowTime = Bars.OpenTimes[i];
                }
            }

            var structureColor = GetTimeFrameStructureColor(Chart != null ? Chart.TimeFrame : TimeFrame.Minute);
            var structureTimeFrame = Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
            if (recentHigh > double.MinValue)
                objectIndex = DrawHorizontalGuide(objectIndex, "Swing High", recentHighTime, recentHigh, structureColor, true, structureTimeFrame);
            if (recentLow < double.MaxValue)
                objectIndex = DrawHorizontalGuide(objectIndex, "Swing Low", recentLowTime, recentLow, structureColor, true, structureTimeFrame);
            if (resistance > double.MinValue)
                objectIndex = DrawHorizontalGuide(objectIndex, "Range High", resistanceTime, resistance, structureColor, true, structureTimeFrame);
            if (support < double.MaxValue)
                objectIndex = DrawHorizontalGuide(objectIndex, "Range Low", supportTime, support, structureColor, true, structureTimeFrame);

            return objectIndex;
        }

        private List<ScoredPriceZone> DetectScoredPriceZones(Bars sourceBars, Symbol symbol, int lookbackBars, TimeFrame sourceTimeFrame = null)
        {
            var zones = new List<ScoredPriceZone>();
            if (sourceBars == null || symbol == null || sourceBars.Count < 20 || symbol.PipSize <= 0)
                return zones;

            var lastClosedIndex = Math.Max(1, sourceBars.Count - 2);
            sourceTimeFrame = sourceTimeFrame ?? (Chart != null ? Chart.TimeFrame : TimeFrame.Minute);
            var cacheKey = "zones|" + BuildDashboardEventCacheKey(symbol.Name, sourceTimeFrame);
            var lastClosedBarTimeUnix = ToUnixSecondsSafe(sourceBars.OpenTimes[lastClosedIndex]);
            PersistedScoredZoneCache cachedZones;
            if (!_persistedScoredZoneCache.TryGetValue(cacheKey, out cachedZones))
                cachedZones = LoadPersistedScoredZoneCache(symbol.Name, sourceTimeFrame, lastClosedIndex);
            if (_persistedScoredZoneCache.TryGetValue(cacheKey, out cachedZones) &&
                cachedZones != null &&
                cachedZones.LastClosedBarTimeUnix == lastClosedBarTimeUnix &&
                cachedZones.LookbackBars == lookbackBars)
            {
                return cachedZones.Zones != null ? new List<ScoredPriceZone>(cachedZones.Zones) : zones;
            }
            var startIndex = Math.Max(5, lastClosedIndex - Math.Max(lookbackBars, 20) + 1);
            var windowBars = lastClosedIndex - startIndex + 1;
            if (windowBars < 12)
                return zones;

            var atrPips = ResolveAtrPips(symbol, sourceBars, 14);
            var atrPrice = atrPips > 0 ? atrPips * symbol.PipSize : symbol.PipSize * 20;
            var binSize = Math.Max(symbol.PipSize * 8.0, atrPrice * 0.20);

            var minPrice = double.MaxValue;
            var maxPrice = double.MinValue;
            for (var i = startIndex; i <= lastClosedIndex; i++)
            {
                minPrice = Math.Min(minPrice, sourceBars.LowPrices[i]);
                maxPrice = Math.Max(maxPrice, sourceBars.HighPrices[i]);
            }

            if (!(maxPrice > minPrice))
                return zones;

            var binCount = Math.Max(3, (int)Math.Ceiling((maxPrice - minPrice) / binSize) + 1);
            if (binCount > 80)
            {
                binSize = (maxPrice - minPrice) / 80.0;
                binCount = 80;
            }

            var closeHits = new int[binCount];
            var lowTouches = new int[binCount];
            var highTouches = new int[binCount];
            var bullishRejections = new int[binCount];
            var bearishRejections = new int[binCount];
            var swingLowHits = new int[binCount];
            var swingHighHits = new int[binCount];

            Func<double, int> toBinIndex = price =>
            {
                if (!(price > 0) || !(binSize > 0))
                    return 0;
                var rawIndex = (int)Math.Floor((price - minPrice) / binSize);
                if (rawIndex < 0) rawIndex = 0;
                if (rawIndex >= binCount) rawIndex = binCount - 1;
                return rawIndex;
            };

            for (var i = startIndex; i <= lastClosedIndex; i++)
            {
                var open = sourceBars.OpenPrices[i];
                var high = sourceBars.HighPrices[i];
                var low = sourceBars.LowPrices[i];
                var close = sourceBars.ClosePrices[i];
                var body = Math.Abs(close - open);
                var lowerWick = Math.Max(0.0, Math.Min(open, close) - low);
                var upperWick = Math.Max(0.0, high - Math.Max(open, close));
                var closeIndex = toBinIndex(close);
                var lowIndex = toBinIndex(low);
                var highIndex = toBinIndex(high);

                closeHits[closeIndex] += 3;
                lowTouches[lowIndex] += 1;
                highTouches[highIndex] += 1;

                if (close > open && lowerWick > body * 1.2 && lowerWick > upperWick)
                {
                    bullishRejections[lowIndex] += 3;
                    var bounce = 0.0;
                    for (var j = i + 1; j <= Math.Min(lastClosedIndex, i + 3); j++)
                        bounce = Math.Max(bounce, sourceBars.ClosePrices[j] - low);
                    if (bounce >= atrPrice * 0.5)
                        bullishRejections[lowIndex] += 2;
                }

                if (close < open && upperWick > body * 1.2 && upperWick > lowerWick)
                {
                    bearishRejections[highIndex] += 3;
                    var drop = 0.0;
                    for (var j = i + 1; j <= Math.Min(lastClosedIndex, i + 3); j++)
                        drop = Math.Max(drop, high - sourceBars.ClosePrices[j]);
                    if (drop >= atrPrice * 0.5)
                        bearishRejections[highIndex] += 2;
                }
            }

            foreach (var swing in CollectConfirmedSwings(sourceBars, Math.Max(lookbackBars, 80)))
            {
                if (swing.BarIndex < startIndex || swing.BarIndex > lastClosedIndex)
                    continue;

                var swingIndex = toBinIndex(swing.Price);
                if (swing.IsHigh)
                    swingHighHits[swingIndex] += 3;
                else
                    swingLowHits[swingIndex] += 3;
            }

            var sidewayIndex = -1;
            var sidewayScore = 0;
            for (var i = 0; i < binCount; i++)
            {
                var score = closeHits[i];
                if (i > 0) score += closeHits[i - 1] / 2;
                if (i + 1 < binCount) score += closeHits[i + 1] / 2;
                if (score > sidewayScore)
                {
                    sidewayScore = score;
                    sidewayIndex = i;
                }
            }

            var totalRangePips = (maxPrice - minPrice) / symbol.PipSize;
            if (sidewayIndex >= 0 &&
                sidewayScore >= Math.Max(10, windowBars / 4) &&
                totalRangePips <= Math.Max(atrPips * 12.0, 30.0))
            {
                zones.Add(BuildScoredPriceZone(sourceBars, startIndex, lastClosedIndex, sidewayIndex, binSize, minPrice, "SWZ", ScoredPriceZoneKind.Sideways, sidewayScore));
            }

            var minZoneScore = Math.Max(8, windowBars / 5);
            var lowerSearchLimit = Math.Max(1, (int)Math.Ceiling(binCount * 0.60));
            var demandBins = SelectTopZoneBins(binCount, 3, 0, lowerSearchLimit, minZoneScore, i => (lowTouches[i] * 2) + bullishRejections[i] + swingLowHits[i] + (closeHits[i] / 2));
            foreach (var binIndex in demandBins)
            {
                zones.Add(BuildScoredPriceZone(
                    sourceBars, startIndex, lastClosedIndex, binIndex, binSize, minPrice,
                    "DEM", ScoredPriceZoneKind.Demand,
                    (lowTouches[binIndex] * 2) + bullishRejections[binIndex] + swingLowHits[binIndex] + (closeHits[binIndex] / 2)));
            }

            // Demand scans the lower 60% of the range, supply the upper 40%; disjoint so a bin
            // can never be both demand and supply.
            var upperSearchStart = Math.Min(binCount - 1, Math.Max(lowerSearchLimit, (int)Math.Floor(binCount * 0.40)));
            var supplyBins = SelectTopZoneBins(binCount, 3, upperSearchStart, binCount, minZoneScore, i => (highTouches[i] * 2) + bearishRejections[i] + swingHighHits[i] + (closeHits[i] / 2));
            foreach (var binIndex in supplyBins)
            {
                zones.Add(BuildScoredPriceZone(
                    sourceBars, startIndex, lastClosedIndex, binIndex, binSize, minPrice,
                    "SPLY", ScoredPriceZoneKind.Supply,
                    (highTouches[binIndex] * 2) + bearishRejections[binIndex] + swingHighHits[binIndex] + (closeHits[binIndex] / 2)));
            }

            var result = zones
                .Where(zone => zone.High > zone.Low && zone.Score > 0)
                .OrderByDescending(zone => zone.Score)
                .ToList();
            _persistedScoredZoneCache[cacheKey] = new PersistedScoredZoneCache
            {
                LastClosedBarTimeUnix = lastClosedBarTimeUnix,
                LookbackBars = lookbackBars,
                Zones = new List<ScoredPriceZone>(result)
            };
            MarkAnalysisCacheDirty("zones", symbol.Name, sourceTimeFrame);
            return result;
        }

        // Picks up to maxZones non-adjacent bins with the best scores above minScore, so the
        // same level is not double-counted across two neighboring bins.
        private List<int> SelectTopZoneBins(int binCount, int maxZones, int fromBin, int toBinExclusive, double minScore, Func<int, int> scoreOf)
        {
            var selected = new List<int>();
            var ordered = Enumerable.Range(Math.Max(0, fromBin), Math.Max(0, Math.Min(binCount, toBinExclusive) - Math.Max(0, fromBin)))
                .Select(binIndex => new { Bin = binIndex, Score = scoreOf(binIndex) })
                .Where(item => item.Score >= minScore)
                .OrderByDescending(item => item.Score)
                .ThenBy(item => item.Bin)
                .ToList();
            foreach (var item in ordered)
            {
                if (selected.Count >= maxZones)
                    break;
                if (selected.Any(existing => Math.Abs(existing - item.Bin) <= 1))
                    continue;
                selected.Add(item.Bin);
            }
            return selected;
        }

        private ScoredPriceZone BuildScoredPriceZone(Bars sourceBars, int startIndex, int lastClosedIndex, int binIndex, double binSize, double minPrice, string label, ScoredPriceZoneKind kind, int score)
        {
            var low = minPrice + (binIndex * binSize);
            var high = low + binSize;

            // Anchor the zone to the bars that actually traded inside it: start at the first
            // touch, end at the last touch, instead of spanning the whole lookback window.
            var firstTouch = -1;
            var lastTouch = -1;
            var visitCount = 0;
            var insideVisit = false;
            for (var i = startIndex; i <= lastClosedIndex; i++)
            {
                var touches = kind == ScoredPriceZoneKind.Supply
                    ? sourceBars.HighPrices[i] >= low && sourceBars.HighPrices[i] <= high
                    : kind == ScoredPriceZoneKind.Demand
                        ? sourceBars.LowPrices[i] >= low && sourceBars.LowPrices[i] <= high
                        : sourceBars.ClosePrices[i] >= low && sourceBars.ClosePrices[i] <= high;
                if (!touches)
                {
                    insideVisit = false;
                    continue;
                }
                if (!insideVisit)
                    visitCount++;
                insideVisit = true;
                if (firstTouch < 0)
                    firstTouch = i;
                lastTouch = i;
            }

            return new ScoredPriceZone
            {
                Kind = kind,
                Label = label,
                Low = low,
                High = high,
                Score = score,
                StartTime = sourceBars.OpenTimes[firstTouch >= 0 ? firstTouch : Math.Max(0, startIndex)],
                LastTouchBarIndex = lastTouch,
                VisitCount = visitCount
            };
        }

