        private struct SharedIndicatorSnapshotCacheKey : IEquatable<SharedIndicatorSnapshotCacheKey>
        {
            private readonly Bars _sourceBars;
            private readonly int _barIndex;
            private readonly long _barOpenTimeTicks;
            private readonly EmaIndicatorConfig _ema;
            private readonly VwapIndicatorConfig _vwap;
            private readonly BollingerIndicatorConfig _bollinger;
            private readonly RsiIndicatorConfig _rsi;
            private readonly StochasticIndicatorConfig _stochastic;
            private readonly MacdIndicatorConfig _macd;

            public SharedIndicatorSnapshotCacheKey(
                Bars sourceBars,
                int barIndex,
                DateTime barOpenTime,
                EmaIndicatorConfig ema,
                VwapIndicatorConfig vwap,
                BollingerIndicatorConfig bollinger,
                RsiIndicatorConfig rsi,
                StochasticIndicatorConfig stochastic,
                MacdIndicatorConfig macd)
            {
                _sourceBars = sourceBars;
                _barIndex = barIndex;
                _barOpenTimeTicks = barOpenTime.Ticks;
                _ema = ema;
                _vwap = vwap;
                _bollinger = bollinger;
                _rsi = rsi;
                _stochastic = stochastic;
                _macd = macd;
            }

            public bool Equals(SharedIndicatorSnapshotCacheKey other)
            {
                return ReferenceEquals(_sourceBars, other._sourceBars)
                    && _barIndex == other._barIndex
                    && _barOpenTimeTicks == other._barOpenTimeTicks
                    && _ema.PriceCrossPeriod == other._ema.PriceCrossPeriod
                    && _ema.FastPeriod == other._ema.FastPeriod
                    && _ema.MidPeriod == other._ema.MidPeriod
                    && _ema.SlowPeriod == other._ema.SlowPeriod
                    && _vwap.Length == other._vwap.Length
                    && _bollinger.Period == other._bollinger.Period
                    && _bollinger.StdDevMultiplier.Equals(other._bollinger.StdDevMultiplier)
                    && _rsi.Period == other._rsi.Period
                    && _rsi.Midline.Equals(other._rsi.Midline)
                    && _rsi.Oversold.Equals(other._rsi.Oversold)
                    && _rsi.Overbought.Equals(other._rsi.Overbought)
                    && _stochastic.KPeriod == other._stochastic.KPeriod
                    && _stochastic.DPeriod == other._stochastic.DPeriod
                    && _stochastic.OversoldLevel == other._stochastic.OversoldLevel
                    && _stochastic.OverboughtLevel == other._stochastic.OverboughtLevel
                    && _macd.FastPeriod == other._macd.FastPeriod
                    && _macd.SlowPeriod == other._macd.SlowPeriod
                    && _macd.SignalPeriod == other._macd.SignalPeriod;
            }

            public override bool Equals(object obj)
            {
                return obj is SharedIndicatorSnapshotCacheKey && Equals((SharedIndicatorSnapshotCacheKey)obj);
            }

            public override int GetHashCode()
            {
                unchecked
                {
                    var hash = 17;
                    hash = (hash * 31) + System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(_sourceBars);
                    hash = (hash * 31) + _barIndex;
                    hash = (hash * 31) + _barOpenTimeTicks.GetHashCode();
                    hash = (hash * 31) + _ema.PriceCrossPeriod;
