                    hash = (hash * 31) + _vwap.Length;
                    hash = (hash * 31) + _bollinger.Period;
                    hash = (hash * 31) + _bollinger.StdDevMultiplier.GetHashCode();
                    hash = (hash * 31) + _rsi.Period;
                    hash = (hash * 31) + _rsi.Midline.GetHashCode();
                    hash = (hash * 31) + _rsi.Oversold.GetHashCode();
                    hash = (hash * 31) + _rsi.Overbought.GetHashCode();
                    hash = (hash * 31) + _stochastic.KPeriod;
                    hash = (hash * 31) + _stochastic.DPeriod;
                    hash = (hash * 31) + _stochastic.OversoldLevel;
                    hash = (hash * 31) + _stochastic.OverboughtLevel;
                    hash = (hash * 31) + _macd.FastPeriod;
                    hash = (hash * 31) + _macd.SlowPeriod;
                    hash = (hash * 31) + _macd.SignalPeriod;
                    return hash;
                }
