        private int DrawLiquidityLevelsOnChart(int objectIndex)
        {
            if (Bars == null || Bars.Count < 12)
                return objectIndex;

            try
            {
                var levels = CollectLiquidityLevels();
                if (levels.Count == 0)
                    return objectIndex;

                var currentEndTime = GetCurrentChartEndTime();
                var maxLevels = Math.Min(10, levels.Count);
                var labeled = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var level in levels
                    .OrderByDescending(x => x.Time)
                    .Take(maxLevels))
                {
                    var levelBars = GetBarsForCurrentMasterTimer(level.SourceTimeFrame, Chart.SymbolName);
                    var levelEndTime = ResolveLevelArtifactEndTime(levelBars, level.SourceTimeFrame, level.Time, level.Price, level.IsHigh, currentEndTime);
                    var line = Chart.DrawTrendLine("LIQ_" + objectIndex.ToString(CultureInfo.InvariantCulture), level.Time, level.Price, levelEndTime, level.Price, WithAlpha(level.Color, 80));
                    TrySetPropertyValue(line, "Thickness", 1);
                    TrySetEnumPropertyValue(line, "LineStyle", "Dots");

                    if (ShouldDrawLiquidityLabel(level) && labeled.Add(level.Label))
                    {
                        var yPad = Math.Max(Symbol.PipSize * 10.0, 0.0000001);
                        var textY = level.IsHigh ? level.Price + yPad : level.Price - yPad;
                        var text = Chart.DrawText("LIQ_TXT_" + objectIndex.ToString(CultureInfo.InvariantCulture), level.Label, level.Time, textY, level.Color);
                        TryStyleChartText(text, GetNormalChartLabelFontSize(), "Courier New", false);
                    }
                    objectIndex++;
                }
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Liquidity levels failed: {0}", ex.Message);
            }

            return objectIndex;
        }

        private DateTime ResolveLevelArtifactEndTime(Bars sourceBars, TimeFrame sourceTimeFrame, DateTime originTime, double price, bool isHigh, DateTime chartEndTime)
        {
            var originIndex = ResolveSourceBarIndex(sourceBars, originTime);
            if (originIndex < 0)
                return chartEndTime;

            var tolerance = Math.Max(Symbol != null ? Symbol.PipSize * 2.0 : 0.0, 0.0000001);
            var lastClosedBarIndex = ResolveStructureLastClosedBarIndex(sourceBars);
            var visitCount = 0;
            var lastTouchBarIndex = -1;
            var insideVisit = false;
            for (var i = originIndex + 1; i <= lastClosedBarIndex; i++)
            {
                var touches = sourceBars.HighPrices[i] >= price - tolerance && sourceBars.LowPrices[i] <= price + tolerance;
                if (touches)
                {
                    if (!insideVisit)
                        visitCount++;
                    insideVisit = true;
                    lastTouchBarIndex = i;
                }
                else
                {
                    insideVisit = false;
                }

                var taken = isHigh
                    ? sourceBars.ClosePrices[i] > price + tolerance
                    : sourceBars.ClosePrices[i] < price - tolerance;
                if (taken)
                    return ResolveBufferedArtifactEndTime(sourceBars, sourceTimeFrame, i, chartEndTime);
            }

            return visitCount > 1
                ? ResolveBufferedArtifactEndTime(sourceBars, sourceTimeFrame, lastTouchBarIndex, chartEndTime)
                : chartEndTime;
        }

        private bool ShouldDrawLiquidityLabel(LiquidityLevel level)
        {
            if (string.IsNullOrWhiteSpace(level.Label))
                return false;

            if (_toggleKeyLevels)
            {
                var label = level.Label.Trim();
                if (label.Equals("London", StringComparison.OrdinalIgnoreCase) ||
                    label.Equals("NY", StringComparison.OrdinalIgnoreCase) ||
                    label.Equals("Asia", StringComparison.OrdinalIgnoreCase) ||
                    label.Equals("h4", StringComparison.OrdinalIgnoreCase) ||
                    label.Equals("d1", StringComparison.OrdinalIgnoreCase) ||
                    label.Equals("4H", StringComparison.OrdinalIgnoreCase) ||
                    label.Equals("1D", StringComparison.OrdinalIgnoreCase))
                {
                    return false;
                }
            }

            return true;
        }

        private int DrawStrategyMarkersOnChart(int objectIndex)
        {
            if (!ShouldDrawChartMarkers() || Chart == null || Bars == null || _strategyChartMarkers.Count == 0)
                return objectIndex;

            var chartSymbolName = Chart.SymbolName ?? "";
            var chartStartTime = Bars.OpenTimes[0];
            var chartEndTime = GetCurrentChartEndTime();
            var visibleMarkers = _strategyChartMarkers
                .Where(marker => string.Equals(marker.SymbolName, chartSymbolName, StringComparison.OrdinalIgnoreCase))
                .Where(marker => marker.Time >= chartStartTime.AddDays(-2) && marker.Time <= chartEndTime.AddMinutes(5))
                .OrderBy(marker => marker.Time)
                .TakeLast(80)
                .ToList();

            foreach (var marker in visibleMarkers)
            {
                var isTrigger = marker.Kind == StrategyMarkerKind.Trigger;
                var isEntry = marker.Kind == StrategyMarkerKind.Entry;
                var iconColor = isTrigger || isEntry
                    ? (marker.TradeType == TradeType.Buy ? Color.LimeGreen : Color.OrangeRed)
                    : (marker.IsWinning ? Color.LimeGreen : Color.OrangeRed);
                var iconType = marker.TradeType == TradeType.Buy ? ChartIconType.UpArrow : ChartIconType.DownArrow;
                var anchorPrice = ResolveStrategyMarkerAnchorPrice(marker);
                var textY = marker.TradeType == TradeType.Buy
                    ? anchorPrice - Math.Max(Symbol.PipSize * 6.0, 0.0000001)
                    : anchorPrice + Math.Max(Symbol.PipSize * 6.0, 0.0000001);

                if (isTrigger)
                {
                    var triggerIcon = Chart.DrawText(
                        "STRAT_TRIGGER_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                        marker.TradeType == TradeType.Buy ? "▲" : "▼",
                        marker.Time,
                        anchorPrice,
                        iconColor);
                    TryStyleChartText(triggerIcon, GetChartMarkerFontSize() + 1, "Courier New", true);
                    TrySetPropertyValue(triggerIcon, "ZIndex", 15);
                    objectIndex++;
                    continue;
                }

                var icon = Chart.DrawIcon(
                    "STRAT_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                    iconType,
                    marker.Time,
                    anchorPrice,
                    iconColor);
                TrySetPropertyValue(icon, "Thickness", isTrigger ? 2 : 1);

                var text = Chart.DrawText(
                    "STRAT_TXT_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                    FormatStrategyMarkerText(marker),
                    marker.Time,
                    textY,
                    iconColor);
                TryStyleChartText(text, GetChartMarkerFontSize(), "Courier New", true);
                objectIndex++;
            }

            return objectIndex;
        }

        private string GetClosedTradeVisualStateStamp()
        {
            if (ClosedTradesVisuals == ClosedTradeVisualMode.No || Chart == null || History == null)
                return "off";

            var chartSymbolName = Chart.SymbolName ?? "";
            if (string.IsNullOrWhiteSpace(chartSymbolName))
                return "nosymbol";

            var matching = History
                .Where(deal => deal != null && string.Equals(deal.SymbolName, chartSymbolName, StringComparison.OrdinalIgnoreCase))
                .Where(deal => HistoricalTradeMatchesChartTimeFrame(deal, Chart.TimeFrame))
                .Where(MatchesClosedTradeVisualFilter)
                .ToList();
            if (matching.Count == 0)
                return "0";

            var lastClosedTicks = matching
                .Select(deal => ReadDateTimeMember(deal, "ClosingTime", "CloseTime", "Time"))
                .Where(time => time != DateTime.MinValue)
                .Select(time => time.Ticks)
                .DefaultIfEmpty(0)
                .Max();
            return matching.Count.ToString(CultureInfo.InvariantCulture) + ":" + lastClosedTicks.ToString(CultureInfo.InvariantCulture);
        }

        private IEnumerable<string> GetChartTimeFrameTokens(TimeFrame timeFrame)
        {
            var normalized = NormalizeTradeTfLabel(GetMiniChartLabel(timeFrame));
            if (!string.IsNullOrWhiteSpace(normalized))
                yield return normalized.ToLowerInvariant();

            switch ((normalized ?? "").ToLowerInvariant())
            {
                case "m1":
                    yield return "1m";
                    break;
                case "m5":
                    yield return "5m";
                    break;
                case "m15":
                    yield return "15m";
                    break;
                case "m30":
                    yield return "30m";
                    break;
                case "h1":
                    yield return "1h";
                    break;
                case "h4":
                    yield return "4h";
                    break;
                case "d1":
                    yield return "1d";
                    break;
            }
        }

        private bool HistoricalTradeMatchesChartTimeFrame(HistoricalTrade deal, TimeFrame chartTimeFrame)
        {
            if (deal == null || chartTimeFrame == null)
                return false;

            var label = Convert.ToString(deal.Label, CultureInfo.InvariantCulture) ?? "";
            var comment = Convert.ToString(deal.Comment, CultureInfo.InvariantCulture) ?? "";
            var haystack = (label + "|" + comment).ToLowerInvariant();
            if (string.IsNullOrWhiteSpace(haystack))
                return false;

            foreach (var token in GetChartTimeFrameTokens(chartTimeFrame))
            {
                if (!string.IsNullOrWhiteSpace(token) && haystack.Contains(token))
                    return true;
            }

            return false;
        }

        private bool MatchesClosedTradeVisualFilter(HistoricalTrade deal)
        {
            if (deal == null)
                return false;

            switch (ClosedTradesVisuals)
            {
                case ClosedTradeVisualMode.No:
                    return false;
                case ClosedTradeVisualMode.All:
                    return true;
                case ClosedTradeVisualMode.Buy:
                    return deal.TradeType == TradeType.Buy;
                case ClosedTradeVisualMode.Sell:
                    return deal.TradeType == TradeType.Sell;
                case ClosedTradeVisualMode.Win:
                    return !double.IsNaN(deal.NetProfit) && deal.NetProfit > 0;
                case ClosedTradeVisualMode.Lose:
                    return !double.IsNaN(deal.NetProfit) && deal.NetProfit < 0;
                default:
                    var strategyToken = ClosedTradesVisuals.ToString().ToLowerInvariant();
                    var label = Convert.ToString(deal.Label, CultureInfo.InvariantCulture) ?? "";
                    var comment = Convert.ToString(deal.Comment, CultureInfo.InvariantCulture) ?? "";
                    var haystack = (label + "|" + comment).ToLowerInvariant();
                    return haystack.Contains(strategyToken);
            }
        }

        private int DrawClosedTradesOnChart(int objectIndex)
        {
            if (!ShouldDrawChartMarkers() || ClosedTradesVisuals == ClosedTradeVisualMode.No || Chart == null || Bars == null || History == null)
                return objectIndex;

            var chartSymbolName = Chart.SymbolName ?? "";
            if (string.IsNullOrWhiteSpace(chartSymbolName))
                return objectIndex;
            var chartSymbol = ResolveLoadedSymbol(chartSymbolName) ?? Symbol;

            var chartStartTime = Bars.OpenTimes[0];
            var chartEndTime = GetCurrentChartEndTime();
            var chartTfMinutes = Math.Max(1, TimeFrameToMinutes(Chart.TimeFrame));
            var visibleClosedTrades = History
                .Where(deal => deal != null && string.Equals(deal.SymbolName, chartSymbolName, StringComparison.OrdinalIgnoreCase))
                .Where(deal => HistoricalTradeMatchesChartTimeFrame(deal, Chart.TimeFrame))
                .Where(MatchesClosedTradeVisualFilter)
                .Select(deal => new
                {
                    Deal = deal,
                    CloseTime = ReadDateTimeMember(deal, "ClosingTime", "CloseTime", "Time"),
                    ClosePrice = ReadDoubleMember(deal, "ClosingPrice", "ClosePrice", "ExitPrice")
                })
                .Where(item => item.CloseTime != DateTime.MinValue)
                .Where(item => item.CloseTime >= chartStartTime.AddMinutes(-chartTfMinutes) && item.CloseTime <= chartEndTime.AddMinutes(chartTfMinutes))
                .OrderBy(item => item.CloseTime)
                .TakeLast(120)
                .ToList();
            var drawnTriggerKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            foreach (var item in visibleClosedTrades)
            {
                var closePrice = item.ClosePrice;
                if (!(closePrice > 0))
                    closePrice = ReadDoubleMember(item.Deal, "EntryPrice", "OpeningPrice");
                if (!(closePrice > 0))
                    continue;

                var isBuy = item.Deal.TradeType == TradeType.Buy;
                var netProfit = double.IsNaN(item.Deal.NetProfit) ? 0 : item.Deal.NetProfit;
                var iconColor = netProfit >= 0 ? Color.LimeGreen : Color.OrangeRed;
                var iconText = isBuy ? "▲" : "▼";
                var pad = Math.Max(chartSymbol != null ? chartSymbol.PipSize * 5.0 : 0.0000001, 0.0000001);
                DateTime triggerBarTime;
                string triggerEventLabel;
                if (TryParseStrategyTriggerAudit(item.Deal.Label, item.Deal.Comment, item.Deal.SymbolName, out triggerBarTime, out triggerEventLabel))
                {
                    var triggerKey = string.Format(
                        CultureInfo.InvariantCulture,
                        "{0}|{1}|{2}",
                        triggerBarTime.Ticks,
                        isBuy ? "B" : "S",
                        triggerEventLabel);
                    var triggerIndex = ResolveSourceBarIndex(Bars, triggerBarTime);
                    if (drawnTriggerKeys.Add(triggerKey) && IsValidBarIndex(Bars, triggerIndex))
                    {
                        var triggerPrice = isBuy ? Bars.LowPrices[triggerIndex] - pad : Bars.HighPrices[triggerIndex] + pad;
                        var trigger = Chart.DrawText(
                            "TRADE_TRIGGER_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                            isBuy ? "▲" : "▼",
                            Bars.OpenTimes[triggerIndex],
                            triggerPrice,
                            isBuy ? Color.LimeGreen : Color.OrangeRed);
                        TryStyleChartText(trigger, GetChartMarkerFontSize(), "Courier New", true);
                    }
                }
                var anchorPrice = isBuy ? closePrice - pad : closePrice + pad;
                var marker = Chart.DrawText(
                    "TRADEH_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                    iconText,
                    item.CloseTime,
                    anchorPrice,
                    iconColor);
                TryStyleChartText(marker, GetChartMarkerFontSize(), "Courier New", true);

                var labelText = FormatClosedTradeMarkerText(item.Deal);
                if (!string.IsNullOrWhiteSpace(labelText))
                {
                    var textY = isBuy ? anchorPrice - (pad * 1.25) : anchorPrice + (pad * 1.25);
                    var label = Chart.DrawText(
                        "TRADEH_TXT_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                        labelText,
                        item.CloseTime,
                        textY,
                        iconColor);
                    TryStyleChartText(label, GetChartMarkerFontSize(), "Courier New", true);
                }
                objectIndex++;
            }

            return objectIndex;
        }

        private bool TryParseStrategyTriggerAudit(string comment, out DateTime triggerBarTime, out string eventLabel)
        {
            triggerBarTime = DateTime.MinValue;
            eventLabel = "";
            if (string.IsNullOrWhiteSpace(comment))
                return false;

            var parts = comment.Split('|');
            if (parts.Length < 3 || string.IsNullOrWhiteSpace(parts[0]))
                return false;
            var triggerPart = parts.FirstOrDefault(part => part.StartsWith("tr:", StringComparison.OrdinalIgnoreCase));
            if (string.IsNullOrWhiteSpace(triggerPart) || triggerPart.Length <= 3)
                return false;

            DateTime parsed;
            if (!DateTime.TryParseExact(
                triggerPart.Substring(3),
                "yyMMddHHmm",
                CultureInfo.InvariantCulture,
                DateTimeStyles.None,
                out parsed))
                return false;

            triggerBarTime = DateTime.SpecifyKind(parsed, DateTimeKind.Unspecified);
            eventLabel = parts[0].Trim();
            return !string.IsNullOrWhiteSpace(eventLabel);
        }

        private bool TryParseStrategyTriggerAudit(string label, string comment, string symbolName, out DateTime triggerBarTime, out string eventLabel)
        {
            if (TryParseStrategyTriggerAudit(comment, out triggerBarTime, out eventLabel))
                return true;

            triggerBarTime = DateTime.MinValue;
            eventLabel = "";
            if (string.IsNullOrWhiteSpace(label) || string.IsNullOrWhiteSpace(comment) || string.IsNullOrWhiteSpace(symbolName))
                return false;

            var labelParts = label.Split(new[] { '.' }, StringSplitOptions.RemoveEmptyEntries);
            var chainSid = labelParts.Length > 1 ? labelParts[labelParts.Length - 1].Trim() : "";
            var commentParts = comment.Split('|');
            eventLabel = commentParts.Length > 0 ? commentParts[0].Trim() : "";
            if (chainSid.Length != 4 || string.IsNullOrWhiteSpace(eventLabel))
                return false;

            var primaryEvent = eventLabel.Split(new[] { '+' }, StringSplitOptions.RemoveEmptyEntries).FirstOrDefault() ?? "";
            var dotIndex = primaryEvent.IndexOf('.');
            TimeFrame sourceTimeFrame;
            if (dotIndex <= 0 || !TryParseTimeFrameToken(primaryEvent.Substring(0, dotIndex), out sourceTimeFrame))
                return false;

            Bars sourceBars;
            try { sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, symbolName); }
            catch { sourceBars = null; }
            if (sourceBars == null || sourceBars.Count < 2)
                return false;

            var firstIndex = Math.Max(0, sourceBars.Count - 1002);
            for (var index = sourceBars.Count - 2; index >= firstIndex; index--)
            {
                var candidateTime = sourceBars.OpenTimes[index];
                if (!string.Equals(BuildStrategyChainSid(symbolName, sourceTimeFrame, candidateTime), chainSid, StringComparison.OrdinalIgnoreCase))
                    continue;
                triggerBarTime = candidateTime;
                return true;
            }

            eventLabel = "";
            return false;
        }

        private string BuildStrategyOrderLabel(string strategyId, string chainSid = "")
        {
            var baseLabel = string.IsNullOrWhiteSpace(strategyId) ? "strategy" : strategyId.Trim();
            var token = string.IsNullOrWhiteSpace(chainSid) ? "" : chainSid.Trim();
            return string.IsNullOrWhiteSpace(token) ? baseLabel : baseLabel + "." + token;
        }

        private string FormatClosedTradeMarkerText(HistoricalTrade deal)
        {
            if (deal == null)
                return "";

            var entryPrice = ReadDoubleMember(deal, "EntryPrice", "OpeningPrice");
            var closePrice = ReadDoubleMember(deal, "ClosingPrice", "ClosePrice", "ExitPrice");
            var stopLoss = ReadDoubleMember(deal, "StopLoss", "StopLossPrice", "Sl");
            if (entryPrice > 0 && closePrice > 0 && stopLoss > 0)
            {
                var riskDistance = Math.Abs(entryPrice - stopLoss);
                if (riskDistance > 0)
                {
                    var rewardDistance = Math.Abs(closePrice - entryPrice);
                    var rr = rewardDistance / riskDistance;
                    if (!double.IsNaN(rr) && !double.IsInfinity(rr))
                    {
                        var signedRr = (double.IsNaN(deal.NetProfit) ? 0 : deal.NetProfit) >= 0 ? rr : -rr;
                        return signedRr >= 0
                            ? "R+" + signedRr.ToString("0.0", CultureInfo.InvariantCulture)
                            : "R" + signedRr.ToString("0.0", CultureInfo.InvariantCulture);
                    }
                }
            }

            var pnl = double.IsNaN(deal.NetProfit) ? 0 : deal.NetProfit;
            return pnl >= 0
                ? "+" + pnl.ToString("0.##", CultureInfo.InvariantCulture)
                : pnl.ToString("0.##", CultureInfo.InvariantCulture);
        }

        private int DrawSweepDetectionsOnChart(int objectIndex, StructureEventFollowUpFilter followUpFilter)
        {
            if (!ShouldDrawChartMarkers() || Bars == null || Bars.Count < 12)
                return objectIndex;

            try
            {
                var markerLimit = GetChartEventsPerTypeLimit();
                if (markerLimit == 0)
                    return objectIndex;

                var candidates = CollectSweepCandidates();
                if (candidates.Count == 0)
                    return objectIndex;

                var bullishColor = Color.FromArgb(190, 0x26, 0xA6, 0x9A);
                var bearishColor = Color.FromArgb(190, 0xEF, 0x53, 0x50);
                var currentEndTime = GetCurrentChartEndTime();
                var shownBull = 0;
                var shownBear = 0;
                var maxPerSide = markerLimit < 0 ? int.MaxValue : markerLimit;

                for (var barIndex = Bars.Count - 1; barIndex >= ResolveWorkingStartIndex(Bars, 5, 1, Chart != null ? Chart.TimeFrame : TimeFrame.Minute); barIndex--)
                {
                    foreach (var candidate in candidates)
                    {
                        if (Bars.OpenTimes[barIndex] <= candidate.Time)
                            continue;

                        SweepMatch match;
                        if (!TryMatchSweepPattern(barIndex, candidate, out match))
                            continue;

                        var isBullishSweep = !candidate.IsHigh;
                        if (isBullishSweep && shownBull >= maxPerSide)
                            continue;
                        if (!isBullishSweep && shownBear >= maxPerSide)
                            continue;

                        if (!IsHigherTimeframeEnabled(candidate.SourceTimeFrame))
                            continue;

                        var color = candidate.Color;
                        var anchorBarIndex = match.ReclaimBarIndex >= 0 ? match.ReclaimBarIndex : barIndex;
                        int markerBarIndex;
                        string labelSuffix;
                        if (!TryResolveStructureVisualFollowUp(Bars, anchorBarIndex, isBullishSweep, followUpFilter, out markerBarIndex, out labelSuffix))
                            continue;

                        var sweepBoxColor = isBullishSweep ? Color.FromArgb(255, 34, 139, 34) : Color.FromArgb(255, 239, 68, 68);
                        DrawPatternRangeBox("SWEEP_BOX_" + objectIndex.ToString(CultureInfo.InvariantCulture), Bars, Chart.TimeFrame, markerBarIndex, 1, sweepBoxColor, 8, 60);

                        var pad = Math.Max(Symbol.PipSize * 8.0, (Bars.HighPrices[markerBarIndex] - Bars.LowPrices[markerBarIndex]) * 0.12);
                    var textY = isBullishSweep ? candidate.Price - pad : candidate.Price + pad;
                    var line = Chart.DrawTrendLine("SWEEP_" + objectIndex.ToString(CultureInfo.InvariantCulture), Bars.OpenTimes[anchorBarIndex], candidate.Price, currentEndTime, candidate.Price, WithAlpha(color, 70));
                    TrySetPropertyValue(line, "LineStyle", LineStyle.Dots);
                    TrySetPropertyValue(line, "Thickness", 1);
                        var text = Chart.DrawText("SWEEP_TXT_" + objectIndex.ToString(CultureInfo.InvariantCulture), BuildChartEventDisplayLabel(candidate.SourceTimeFrame, "swp" + labelSuffix, isBullishSweep), Bars.OpenTimes[markerBarIndex], textY, color);
                        TryStyleChartText(text, GetNormalChartLabelFontSize(), "Courier New", true);
                        objectIndex++;

                        if (isBullishSweep)
                            shownBull++;
                        else
                            shownBear++;
                    }

                    if (shownBull >= maxPerSide && shownBear >= maxPerSide)
                        break;
                }
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Sweep detection failed: {0}", ex.Message);
            }

            return objectIndex;
        }

        private List<SweepCandidate> CollectSweepCandidates()
        {
            return CollectLiquidityLevels()
                .Select(level => new SweepCandidate
                {
                    Label = level.Label,
                    Price = level.Price,
                    IsHigh = level.IsHigh,
                    Time = level.Time,
                    SourceTimeFrame = level.SourceTimeFrame,
                    Color = level.Color
                })
                .ToList();
        }

        private List<LiquidityLevel> CollectLiquidityLevels()
        {
            var levels = new List<LiquidityLevel>();
            var prevDate = GetReferenceNow().Date.AddDays(-1);

            var chartStructureColor = GetTimeFrameStructureColor(Chart != null ? Chart.TimeFrame : TimeFrame.Minute);
            AddSessionLiquidityLevels(levels, "London", prevDate, chartStructureColor);
            AddSessionLiquidityLevels(levels, "NY", prevDate, chartStructureColor);
            AddSessionLiquidityLevels(levels, "Asia", prevDate, chartStructureColor);

            AddPreviousPeriodLiquidityLevels(levels, "h4", TimeFrame.Hour4, GetTimeFrameStructureColor(TimeFrame.Hour4));
            AddPreviousPeriodLiquidityLevels(levels, "d1", TimeFrame.Daily, GetTimeFrameStructureColor(TimeFrame.Daily));
            AddPreviousPeriodLiquidityLevels(levels, "w1", TimeFrame.Weekly, GetTimeFrameStructureColor(TimeFrame.Weekly));
            AddRecentSwingLiquidityLevels(levels);
            return levels;
        }

        private void AddSessionLiquidityLevels(List<LiquidityLevel> levels, string label, DateTime date, Color color)
        {
            DateTime startUtc;
            DateTime endUtc;
            if (!TryGetSessionUtcRange(label, date, out startUtc, out endUtc))
                return;

            double high;
            double low;
            DateTime highTime;
            DateTime lowTime;
            if (!TryGetRangeHighLow(Bars, startUtc, endUtc, out high, out low, out highTime, out lowTime))
                return;

            AddLiquidityLevel(levels, label, high, true, highTime, color, Chart != null ? Chart.TimeFrame : TimeFrame.Minute);
            AddLiquidityLevel(levels, label, low, false, lowTime, color, Chart != null ? Chart.TimeFrame : TimeFrame.Minute);
        }

        private void AddPreviousPeriodLiquidityLevels(List<LiquidityLevel> levels, string label, TimeFrame timeFrame, Color color)
        {
            try
            {
                if (Chart != null && !ShouldProjectPreviousBarLevel(timeFrame, Chart.TimeFrame))
                    return;

                var sourceBars = GetBarsForCurrentMasterTimer(timeFrame, Chart.SymbolName);
                if (sourceBars == null || sourceBars.Count < 1)
                    return;

                int idx;
                if (!TryGetPreviousCompletedPeriodBarIndex(sourceBars, timeFrame, out idx))
                    return;
                AddLiquidityLevel(levels, label, sourceBars.HighPrices[idx], true, sourceBars.OpenTimes[idx], color, timeFrame);
                AddLiquidityLevel(levels, label, sourceBars.LowPrices[idx], false, sourceBars.OpenTimes[idx], color, timeFrame);
            }
            catch
            {
            }
        }

        private bool TryGetPreviousCompletedPeriodBarIndex(Bars sourceBars, TimeFrame timeFrame, out int index)
        {
            index = -1;
            if (sourceBars == null || sourceBars.Count < 2)
                return false;

            // Anchor to the chart's last (current/forming) LTF bar rather than Server.Time, so
            // the resolved HTF bar always matches what is actually visible on the chart. The
            // "previous completed" HTF candle is the one just before the HTF candle that
            // contains the chart's last bar.
            var referenceTime = NormalizeBotTimeToUtc(
                Bars != null && Bars.Count > 0
                    ? Bars.OpenTimes[Bars.Count - 1]
                    : Server.Time);
            var lastIndex = sourceBars.Count - 1;
            for (var i = 0; i < lastIndex; i++)
            {
                var barStart = sourceBars.OpenTimes[i];
                var nextBarStart = sourceBars.OpenTimes[i + 1];
                if (referenceTime >= barStart && referenceTime < nextBarStart)
                {
                    if (i <= 0)
                        return false;

                    index = i - 1;
                    return index >= 0;
                }
            }

            if (referenceTime >= sourceBars.OpenTimes[lastIndex])
            {
                index = Math.Max(0, lastIndex - 1);
                return index >= 0;
            }

            return false;
        }

        private void AddRecentSwingLiquidityLevels(List<LiquidityLevel> levels)
        {
            foreach (var swing in CollectConfirmedSwings(ResolveWorkingSwingLookbackBars(Bars, Chart != null ? Chart.TimeFrame : TimeFrame.Minute)).TakeLast(8))
            {
                AddLiquidityLevel(levels, swing.IsHigh ? "BSL" : "SSL", swing.Price, swing.IsHigh, swing.Time, GetTimeFrameStructureColor(Chart != null ? Chart.TimeFrame : TimeFrame.Minute), Chart != null ? Chart.TimeFrame : TimeFrame.Minute);
            }
        }

        private void AddLiquidityLevel(List<LiquidityLevel> levels, string label, double price, bool isHigh, DateTime time, Color color, TimeFrame sourceTimeFrame)
        {
            if (price <= 0 || time == DateTime.MinValue)
                return;

            var tolerance = Math.Max(Symbol.PipSize * 2.0, 0.0000001);
            if (levels.Any(level => level.IsHigh == isHigh && Math.Abs(level.Price - price) <= tolerance))
                return;

            levels.Add(new LiquidityLevel
            {
                Label = label ?? "",
                Price = price,
                IsHigh = isHigh,
                Time = time,
                Color = color,
                SourceTimeFrame = sourceTimeFrame
            });
        }

        private List<SwingPoint> CollectConfirmedSwings(int lookbackBars)
        {
            return CollectConfirmedSwings(Bars, lookbackBars);
        }

        private int DrawStructureBreakDetectionsOnChart(int objectIndex, bool drawChoch, StructureEventFollowUpFilter followUpFilter)
        {
            if (!ShouldDrawChartMarkers() || Bars == null || Bars.Count < 20)
                return objectIndex;

            try
            {
                var markerLimit = GetChartEventsPerTypeLimit();
                if (markerLimit == 0)
                    return objectIndex;

                var matchingEvents = CollectStructureEvents()
                    .Where(evt => evt.IsChoch == drawChoch)
                    .OrderByDescending(evt => evt.Time)
                    .ToList();
                if (matchingEvents.Count == 0)
                    return objectIndex;

                var shown = 0;
                foreach (var evt in matchingEvents)
                {
                    if (!IsHigherTimeframeEnabled(evt.SourceTimeFrame))
                        continue;

                    int markerBarIndex;
                    string labelSuffix;
                    if (!TryResolveStructureVisualFollowUp(Bars, evt.BarIndex, evt.IsBullish, followUpFilter, out markerBarIndex, out labelSuffix))
                        continue;

                    var baseColor = GetTimeFrameStructureColor(evt.SourceTimeFrame);
                    var color = evt.IsChoch ? WithAlpha(baseColor, 230) : baseColor;
                    var prefix = evt.IsChoch ? "CHOCH_" : "BOS_";
                    var textPrefix = evt.IsChoch ? "CHOCH_TXT_" : "BOS_TXT_";
                    var line = Chart.DrawTrendLine(prefix + objectIndex.ToString(CultureInfo.InvariantCulture), evt.Time, evt.Price, GetCurrentChartEndTime(), evt.Price, WithAlpha(color, 88));
                    TrySetPropertyValue(line, "Thickness", 1);
                    TrySetEnumPropertyValue(line, "LineStyle", evt.IsChoch ? "Dots" : "Lines");

                    var structureBoxColor = evt.IsBullish ? Color.FromArgb(255, 34, 139, 34) : Color.FromArgb(255, 239, 68, 68);
                    DrawPatternRangeBox(prefix + "BOX_" + objectIndex.ToString(CultureInfo.InvariantCulture), Bars, Chart.TimeFrame, markerBarIndex, 1, structureBoxColor, 8, 60);

                    var yPad = Math.Max(Symbol.PipSize * 12.0, 0.0000001);
                    var textY = evt.IsBullish ? evt.Price + yPad : evt.Price - yPad;
                    var text = Chart.DrawText(textPrefix + objectIndex.ToString(CultureInfo.InvariantCulture), BuildChartEventDisplayLabel(evt.SourceTimeFrame, evt.Label + labelSuffix, evt.IsBullish), Bars.OpenTimes[markerBarIndex], textY, color);
                    TryStyleChartText(text, ResolveChartMarkerFontSize(evt.SourceTimeFrame), "Courier New", true);
                    objectIndex++;
                    shown++;
                    if (markerLimit > 0 && shown >= markerLimit)
                        break;
                }
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Structure break failed: {0}", ex.Message);
            }

            return objectIndex;
        }

        private int DrawCanonicalEventsOnChart(int objectIndex, CanonicalEventType eventType, StructureEventFollowUpFilter followUpFilter)
        {
            if (!ShouldDrawChartMarkers() || Chart == null || Bars == null || Bars.Count < 20 || Symbol == null)
                return objectIndex;
            if (ChartObjectsOverBudget())
                return objectIndex;

            try
            {
                var markerLimit = GetChartEventsPerTypeLimit();
                if (markerLimit == 0)
                    return objectIndex;

                var symbolName = Chart != null && !string.IsNullOrWhiteSpace(Chart.SymbolName)
                    ? Chart.SymbolName
                    : Symbol.Name;
                var chartTimeFrame = Chart.TimeFrame;
                var chartTfMinutes = Math.Max(1, TimeFrameToMinutes(chartTimeFrame));
                var uniqueFrames = new List<TimeFrame> { chartTimeFrame };
                uniqueFrames.AddRange(
                    GetEnabledAutoHigherTimeframes(chartTimeFrame)
                        .Where(tf => TimeFrameToMinutes(tf) > chartTfMinutes));
                uniqueFrames = uniqueFrames
                    .Distinct()
                    .OrderBy(tf => TimeFrameToMinutes(tf))
                    .ToList();
                if (uniqueFrames.Count == 0)
                    return objectIndex;

                var drawnKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                string prefix;
                switch (eventType)
                {
                    case CanonicalEventType.Rejection:
                        prefix = "RJ";
                        break;
                    case CanonicalEventType.Breakout:
                        prefix = "BR";
                        break;
                    case CanonicalEventType.Pullback:
                        prefix = "PB";
                        break;
                    case CanonicalEventType.Continuation:
                        prefix = "CT";
                        break;
                    case CanonicalEventType.Impulse:
                        prefix = "IM";
                        break;
                    default:
                        return objectIndex;
                }

                for (var frameIndex = 0; frameIndex < uniqueFrames.Count; frameIndex++)
                {
                    var sourceTimeFrame = uniqueFrames[frameIndex];
                    Bars sourceBars = null;
                    try
                    {
                        sourceBars = sourceTimeFrame == Chart.TimeFrame ? Bars : GetBarsForCurrentMasterTimer(sourceTimeFrame, symbolName);
                    }
                    catch
                    {
                        sourceBars = null;
                    }

                    var matchingEvents = GetCanonicalEventsForSymbolTimeFrame(symbolName, sourceTimeFrame, 24)
                        .Where(evt => evt.EventType == eventType)
                        .OrderByDescending(evt => evt.BarTime)
                        .ThenByDescending(evt => evt.Score)
                        .ToList();
                    if (matchingEvents.Count == 0)
                        continue;

                    var shown = 0;
                    foreach (var evt in matchingEvents)
                    {
                        var chartBarIndex = FindBarIndexForMarkerTime(evt.BarTime);
                        var sourceBarIndex = ResolveSourceBarIndex(sourceBars, evt.BarTime);
                        if (sourceBarIndex < 0 && followUpFilter != StructureEventFollowUpFilter.Any)
                            continue;

                        int markerSourceBarIndex;
                        string labelSuffix;
                        if (!TryResolveStructureVisualFollowUp(sourceBars, sourceBarIndex, evt.IsBullish, followUpFilter, out markerSourceBarIndex, out labelSuffix))
                            continue;

                        var markerTime = followUpFilter == StructureEventFollowUpFilter.Any
                            ? evt.BarTime
                            : sourceBars.OpenTimes[markerSourceBarIndex];
                        var markerChartBarIndex = followUpFilter == StructureEventFollowUpFilter.Any
                            ? chartBarIndex
                            : FindBarIndexForMarkerTime(markerTime);
                        var visualLabel = BuildChartEventDisplayLabel(evt, labelSuffix);
                        var dedupeKey = string.Format(
                            CultureInfo.InvariantCulture,
                            "{0}:{1}:{2}:{3}",
                            markerChartBarIndex,
                            visualLabel,
                            evt.IsBullish ? "B" : "S",
                            GetMiniChartLabel(sourceTimeFrame));
                        if (!drawnKeys.Add(dedupeKey))
                            continue;

                        var baseColor = GetTimeFrameStructureColor(sourceTimeFrame);
                        var directionalColor = GetDirectionalEventColor(evt.IsBullish);
                        var markerColor = eventType == CanonicalEventType.Rejection ? directionalColor : baseColor;
                        if (eventType == CanonicalEventType.Rejection || eventType == CanonicalEventType.Breakout)
                        {
                            var eventEndTime = ResolveSourceBarEndTime(sourceBars, evt.BarTime, sourceTimeFrame);
                            var eventLine = Chart.DrawTrendLine(
                                prefix + "_LVL_" + GetMiniChartLabel(sourceTimeFrame) + "_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                                evt.BarTime,
                                evt.PriceRef,
                                eventEndTime,
                                evt.PriceRef,
                                WithAlpha(baseColor, eventType == CanonicalEventType.Breakout ? 132 : 118));
                            TrySetPropertyValue(eventLine, "Thickness", 1);
                            TrySetEnumPropertyValue(eventLine, "LineStyle", "Dots");
                            TrySetPropertyValue(eventLine, "ZIndex", 5);

                        }
                        var anchorPrice = evt.PriceRef;
                        var eventBarRange = Symbol.PipSize * 8.0;
                        if (sourceBars != null && markerSourceBarIndex >= 0 && markerSourceBarIndex < sourceBars.Count)
                        {
                            var eventBoxColor = directionalColor;
                            DrawPatternRangeBox(
                                prefix + "_" + GetMiniChartLabel(sourceTimeFrame) + "_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                                sourceBars,
                                sourceTimeFrame,
                                markerSourceBarIndex,
                                1,
                                eventBoxColor,
                                8,
                                60);
                            anchorPrice = evt.IsBullish
                                ? sourceBars.LowPrices[markerSourceBarIndex]
                                : sourceBars.HighPrices[markerSourceBarIndex];
                            eventBarRange = Math.Max(sourceBars.HighPrices[markerSourceBarIndex] - sourceBars.LowPrices[markerSourceBarIndex], Symbol.PipSize * 8.0);
                        }
                        var textY = ResolveDirectionalLabelPrice(evt.IsBullish, anchorPrice, eventBarRange, frameIndex);
                        var barMidTime = markerTime.AddMinutes(Math.Max(0.65, TimeFrameToMinutes(sourceTimeFrame) * 0.68));
                        var icon = Chart.DrawText(
                            prefix + "_ICON_" + GetMiniChartLabel(sourceTimeFrame) + "_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                            GetDirectionalArrowIcon(evt.IsBullish),
                            barMidTime,
                            anchorPrice,
                            markerColor);
                        TryStyleChartText(icon, ResolveChartMarkerFontSize(sourceTimeFrame) + 1, "Courier New", true);
                        TrySetPropertyValue(icon, "ZIndex", 12);

                        var text = Chart.DrawText(
                            prefix + "_TXT_" + GetMiniChartLabel(sourceTimeFrame) + "_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                            " " + visualLabel.Trim(),
                            barMidTime.AddMinutes(Math.Max(0.015, TimeFrameToMinutes(sourceTimeFrame) * 0.015)),
                            textY,
                            markerColor);
                        TryStyleChartText(text, ResolveChartMarkerFontSize(sourceTimeFrame), "Courier New", true);
                        TrySetPropertyValue(text, "ZIndex", 12);
                        objectIndex++;
                        shown++;
                        if (markerLimit > 0 && shown >= markerLimit)
                            break;
                    }
                }
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Canonical event draw failed ({0}): {1}", eventType, ex.Message);
            }

            return objectIndex;
        }

        private int DrawDirectionalCandlePatternsOnChart(int objectIndex)
        {
            if (DisableCandlePatternRenderingForIsolation)
                return objectIndex;

            if (!ShouldDrawChartMarkers() || Chart == null || Bars == null || Bars.Count < 8 || Symbol == null)
                return objectIndex;
            if (ChartObjectsOverBudget())
                return objectIndex;

            if (GetChartEventsPerTypeLimit() == 0)
                return objectIndex;

            try
            {
                var chartTf = Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
                var uniqueFrames = new List<TimeFrame> { chartTf };

                var aggregatedMarkers = new List<DirectionalPatternMarkerAggregate>();
                var patternDefinitions = BuildEnabledCandlePatternDefinitions();
                foreach (var sourceTimeFrame in uniqueFrames)
                {
                    Bars sourceBars = sourceTimeFrame == chartTf ? Bars : null;
                    if (sourceBars == null)
                    {
                        try
                        {
                            sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, Chart.SymbolName);
                        }
                        catch
                        {
                            sourceBars = null;
                        }
                    }

                    if (sourceBars == null || sourceBars.Count < 8)
                        continue;
                    if (patternDefinitions.Count == 0)
                        continue;

                    CollectRecentDirectionalCandlePatternMarkersOptimized(
                        aggregatedMarkers,
                        sourceBars,
                        sourceTimeFrame,
                        patternDefinitions,
                        -1,
                        Chart != null ? Chart.SymbolName : (Symbol != null ? Symbol.Name : ""));
                }

                var drawnConfluenceKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var marker in aggregatedMarkers
                    .OrderBy(item => TimeFrameToMinutes(item.SourceTimeFrame))
                    .ThenBy(item => item.BarIndex)
                    .ThenBy(item => item.IsNeutral ? 2 : item.IsBullish ? 0 : 1))
                {
                    objectIndex = DrawCandleConfluenceMatches(objectIndex, marker, drawnConfluenceKeys);
                    objectIndex = marker.IsNeutral
                        ? DrawNeutralPatternMarker(objectIndex, marker.SourceBars, marker.SourceTimeFrame, marker.BarIndex, marker.PatternSpan, FormatCandleMarkerChartLabel(marker))
                        : DrawDirectionalPatternMarker(
                            objectIndex,
                            marker.SourceBars,
                            marker.SourceTimeFrame,
                            marker.BarIndex,
                            marker.IsBullish,
                            marker.SlotIndex,
                            marker.PatternSpan,
                            marker.HighlightPatternRange,
                            FormatCandleMarkerChartLabel(marker));
                }
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Candle patterns failed: {0}", ex.Message);
            }

            return objectIndex;
        }

        private int DrawCandleConfluenceMatches(int objectIndex, DirectionalPatternMarkerAggregate marker, HashSet<string> drawnKeys)
        {
            if (Chart == null || marker == null || marker.SourceBars == null || marker.ConfluenceMatches == null || marker.ConfluenceMatches.Count == 0)
                return objectIndex;

            var patternIndex = marker.PatternBarIndex >= 0 ? marker.PatternBarIndex : marker.BarIndex;
            if (!IsValidBarIndex(marker.SourceBars, patternIndex))
                return objectIndex;

            var startTime = marker.SourceBars.OpenTimes[patternIndex];
            var endTime = GetCurrentChartEndTime();
            if (endTime <= startTime)
                endTime = startTime.AddMinutes(Math.Max(1, TimeFrameToMinutes(marker.SourceTimeFrame)));
            var tolerance = Math.Max(Symbol != null ? Symbol.PipSize * 0.5 : 0.0, 0.0000001);

            foreach (var match in marker.ConfluenceMatches)
            {
                if (match == null || !IsValidCandleConfluenceTimeFrame(marker.SourceTimeFrame, match.SourceTimeFrame) ||
                    !IsFiniteNumber(match.Low) || !IsFiniteNumber(match.High))
                    continue;
                var key = string.Format(CultureInfo.InvariantCulture, "{0}|{1}|{2:F8}|{3:F8}", match.Kind, match.SourceTimeFrame, match.Low, match.High);
                if (drawnKeys != null && !drawnKeys.Add(key))
                    continue;

                var color = GetTimeFrameStructureColor(match.SourceTimeFrame);
                var label = string.Format(CultureInfo.InvariantCulture, "{0}.{1}", GetArtifactDisplayTimeFrameLabel(match.SourceTimeFrame), GetCanonicalLevelOperand(match.Kind));
                var matchBars = GetBarsForCurrentMasterTimer(match.SourceTimeFrame, Chart.SymbolName);
                var matchEndTime = ResolveMatchedArtifactEndTime(matchBars, match.SourceTimeFrame, startTime, match.Low, match.High, marker.IsBullish, endTime);
                if (match.High - match.Low > tolerance)
                {
                    var zone = Chart.DrawRectangle("CANDLE_CFL_ZONE_" + objectIndex.ToString(CultureInfo.InvariantCulture), startTime, match.High, matchEndTime, match.Low, WithAlpha(color, 24));
                    TrySetPropertyValue(zone, "BorderColor", WithAlpha(color, 120));
                    TrySetPropertyValue(zone, "ZIndex", 1);
                    DrawArtifactZoneLabel("CANDLE_CFL", objectIndex, (match.Low + match.High) * 0.5, color, label, matchEndTime, endTime, GetNormalChartLabelFontSize(), match.SourceTimeFrame);
                }
                else
                {
                    var line = Chart.DrawTrendLine("CANDLE_CFL_LINE_" + objectIndex.ToString(CultureInfo.InvariantCulture), startTime, match.Low, matchEndTime, match.Low, WithAlpha(color, 140));
                    TrySetPropertyValue(line, "Thickness", 1);
                    TrySetEnumPropertyValue(line, "LineStyle", "Dots");
                    DrawArtifactZoneLabel("CANDLE_CFL", objectIndex, match.Low, color, label, matchEndTime, endTime, GetNormalChartLabelFontSize(), match.SourceTimeFrame);
                }
                objectIndex++;
            }

            return objectIndex;
        }

        private DateTime ResolveMatchedArtifactEndTime(Bars sourceBars, TimeFrame sourceTimeFrame, DateTime firstRelevantTime, double zoneLow, double zoneHigh, bool bullishReaction, DateTime chartEndTime)
        {
            var startIndex = ResolveSourceBarIndex(sourceBars, firstRelevantTime);
            if (startIndex < 0)
                return chartEndTime;

            var low = Math.Min(zoneLow, zoneHigh);
            var high = Math.Max(zoneLow, zoneHigh);
            var lastClosedBarIndex = ResolveStructureLastClosedBarIndex(sourceBars);
            var visitCount = 0;
            var lastTouchBarIndex = -1;
            var insideVisit = false;
            for (var i = startIndex; i <= lastClosedBarIndex; i++)
            {
                var touches = sourceBars.HighPrices[i] >= low && sourceBars.LowPrices[i] <= high;
                if (touches)
                {
                    if (!insideVisit)
                        visitCount++;
                    insideVisit = true;
                    lastTouchBarIndex = i;
                }
                else
                {
                    insideVisit = false;
                }

                var taken = bullishReaction
                    ? sourceBars.ClosePrices[i] < low
                    : sourceBars.ClosePrices[i] > high;
                if (taken)
                    return ResolveBufferedArtifactEndTime(sourceBars, sourceTimeFrame, i, chartEndTime);
            }

            return visitCount > 1
                ? ResolveBufferedArtifactEndTime(sourceBars, sourceTimeFrame, lastTouchBarIndex, chartEndTime)
                : chartEndTime;
        }

        private List<CandlePatternDefinition> BuildEnabledCandlePatternDefinitions()
        {
            var definitions = new List<CandlePatternDefinition>();

            if (_togglePinBarPatterns && !SkipPinBarForIsolation)
            {
                definitions.Add(new CandlePatternDefinition { ShortLabel = "PIN", IsBullish = true, PatternSpan = 1, NativeMatch = MatchBullishPinBar, FollowUpFilter = _pinBarPatternFollowUpFilter });
                definitions.Add(new CandlePatternDefinition { ShortLabel = "PIN", IsBullish = false, PatternSpan = 1, NativeMatch = MatchBearishPinBar, FollowUpFilter = _pinBarPatternFollowUpFilter });
            }
            if (RestorePinBarOnlyForIsolation)
                return definitions;

            if (_toggleEngulfingPatterns && !SkipEngulfingForIsolation)
            {
                definitions.Add(new CandlePatternDefinition { ShortLabel = "ENG", IsBullish = true, PatternSpan = 2, NativeMatch = MatchBullishEngulfingAtIndex, FollowUpFilter = _engulfingPatternFollowUpFilter });
                definitions.Add(new CandlePatternDefinition { ShortLabel = "ENG", IsBullish = false, PatternSpan = 2, NativeMatch = MatchBearishEngulfingAtIndex, FollowUpFilter = _engulfingPatternFollowUpFilter });
            }
            if (RestoreEngulfingOnlyForIsolation)
                return definitions;

            if (_toggleBigCandlePatterns && !SkipBigCandleForIsolation)
            {
                definitions.Add(new CandlePatternDefinition { ShortLabel = "BIG", IsBullish = true, PatternSpan = 1, NativeMatch = MatchBullishBigCandle, FollowUpFilter = _bigCandlePatternFollowUpFilter });
                definitions.Add(new CandlePatternDefinition { ShortLabel = "BIG", IsBullish = false, PatternSpan = 1, NativeMatch = MatchBearishBigCandle, FollowUpFilter = _bigCandlePatternFollowUpFilter });
            }
            if (RestoreBigCandleOnlyForIsolation)
                return definitions;

            if (_toggleMorningStarPatterns && !SkipMorningStarForIsolation)
                definitions.Add(new CandlePatternDefinition { ShortLabel = "MOR", IsBullish = true, PatternSpan = 3, SharedPatternType = "bullish_morning_star", FollowUpFilter = _morningStarPatternFollowUpFilter });
            if (RestoreMorningStarOnlyForIsolation)
                return definitions;
            if (_toggleEveningStarPatterns && !SkipEveningStarForIsolation)
                definitions.Add(new CandlePatternDefinition { ShortLabel = "EVE", IsBullish = false, PatternSpan = 3, SharedPatternType = "bearish_evening_star", FollowUpFilter = _eveningStarPatternFollowUpFilter });
            if (RestoreEveningStarOnlyForIsolation)
                return definitions;
            if (_toggleHammerPatterns)
                definitions.Add(new CandlePatternDefinition { ShortLabel = "HAM", IsBullish = true, PatternSpan = 1, SharedPatternType = "bullish_hammer", FollowUpFilter = _hammerPatternFollowUpFilter });
            if (RestoreHammerOnlyForIsolation)
                return definitions;
            if (_toggleHangingManPatterns)
                definitions.Add(new CandlePatternDefinition { ShortLabel = "HGM", IsBullish = false, PatternSpan = 1, SharedPatternType = "hanging_man", FollowUpFilter = _hangingManPatternFollowUpFilter });
            if (RestoreHangingManOnlyForIsolation)
                return definitions;
            if (_toggleShootingStarPatterns)
                definitions.Add(new CandlePatternDefinition { ShortLabel = "SST", IsBullish = false, PatternSpan = 1, SharedPatternType = "shooting_star", FollowUpFilter = _shootingStarPatternFollowUpFilter });
            if (_toggleInvertedHammerPatterns)
                definitions.Add(new CandlePatternDefinition { ShortLabel = "IHM", IsBullish = true, PatternSpan = 1, SharedPatternType = "bullish_inverted_hammer", FollowUpFilter = _invertedHammerPatternFollowUpFilter });
            if (_togglePiercingLinePatterns)
                definitions.Add(new CandlePatternDefinition { ShortLabel = "PRC", IsBullish = true, PatternSpan = 2, SharedPatternType = "bullish_piercing_line", FollowUpFilter = _piercingLinePatternFollowUpFilter });
            if (_toggleDarkCloudCoverPatterns)
                definitions.Add(new CandlePatternDefinition { ShortLabel = "DCC", IsBullish = false, PatternSpan = 2, SharedPatternType = "bearish_dark_cloud_cover", FollowUpFilter = _darkCloudCoverPatternFollowUpFilter });
            if (_toggleThreeWhiteSoldiersPatterns)
                definitions.Add(new CandlePatternDefinition { ShortLabel = "3WS", IsBullish = true, PatternSpan = 3, SharedPatternType = "bullish_three_white_soldiers", FollowUpFilter = _threeWhiteSoldiersPatternFollowUpFilter });
            if (_toggleThreeBlackCrowsPatterns)
                definitions.Add(new CandlePatternDefinition { ShortLabel = "3BC", IsBullish = false, PatternSpan = 3, SharedPatternType = "bearish_three_black_crows", FollowUpFilter = _threeBlackCrowsPatternFollowUpFilter });
            if (_toggleHaramiPatterns)
            {
                definitions.Add(new CandlePatternDefinition { ShortLabel = "HAR", IsBullish = true, PatternSpan = 2, SharedPatternType = "bullish_harami", FollowUpFilter = _haramiPatternFollowUpFilter });
                definitions.Add(new CandlePatternDefinition { ShortLabel = "HAR", IsBullish = false, PatternSpan = 2, SharedPatternType = "bearish_harami", FollowUpFilter = _haramiPatternFollowUpFilter });
            }

            return definitions;
        }

        private void CollectRecentDirectionalCandlePatternMarkersOptimized(
            List<DirectionalPatternMarkerAggregate> aggregates,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            List<CandlePatternDefinition> patternDefinitions,
            int minimumBarIndex = -1,
            string symbolName = null)
        {
            if (aggregates == null || sourceBars == null || patternDefinitions == null || patternDefinitions.Count == 0)
                return;

            var matchCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            var maxMarkersPerType = GetCollectorMarkerLimit();
            var slotIndexes = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            for (var i = 0; i < patternDefinitions.Count; i++)
            {
                var key = GetCandlePatternDefinitionKey(patternDefinitions[i]);
                if (!slotIndexes.ContainsKey(key))
                    slotIndexes[key] = i;
            }

            var sharedPatternCache = new Dictionary<int, HashSet<string>>();
            var startIndex = ResolveWorkingStartIndex(sourceBars, 2, 2, sourceTimeFrame);
            if (minimumBarIndex >= 0)
                startIndex = Math.Max(startIndex, minimumBarIndex);

            var cacheSymbol = !string.IsNullOrWhiteSpace(symbolName)
                ? symbolName.Trim().ToUpperInvariant()
                : Chart != null ? Chart.SymbolName : Symbol != null ? Symbol.Name : "";
            var rawCache = LoadPersistedCandlePatternCache(cacheSymbol, sourceTimeFrame);
            var definitionSignature = BuildCandlePatternDefinitionSignature(patternDefinitions);
            if (!string.Equals(rawCache.DefinitionSignature, definitionSignature, StringComparison.Ordinal))
            {
                rawCache.DefinitionSignature = definitionSignature;
                rawCache.ComputedBarTimesUnix.Clear();
                rawCache.Matches.Clear();
            }

            var lastClosedIndex = sourceBars.Count - 2;
            var refreshStart = Math.Max(startIndex, lastClosedIndex - AnalysisCacheOverlapBars + 1);
            var refreshTimes = new HashSet<long>();
            for (var index = refreshStart; index <= lastClosedIndex; index++)
                refreshTimes.Add(ToUnixSecondsSafe(sourceBars.OpenTimes[index]));
            rawCache.ComputedBarTimesUnix.ExceptWith(refreshTimes);
            rawCache.Matches.RemoveAll(match => match == null || refreshTimes.Contains(match.BarTimeUnix));

            var cachedMatches = rawCache.Matches
                .Where(match => match != null && !string.IsNullOrWhiteSpace(match.DefinitionKey))
                .GroupBy(match => match.BarTimeUnix)
                .ToDictionary(group => group.Key, group => new HashSet<string>(group.Select(match => match.DefinitionKey), StringComparer.OrdinalIgnoreCase));
            for (var barIndex = sourceBars.Count - 2; barIndex >= startIndex; barIndex--)
            {
                HashSet<string> sharedDetections = null;
                var barTimeUnix = ToUnixSecondsSafe(sourceBars.OpenTimes[barIndex]);
                var useCachedGeometry = barIndex < refreshStart && rawCache.ComputedBarTimesUnix.Contains(barTimeUnix);
                for (var i = 0; i < patternDefinitions.Count; i++)
                {
                    var definition = patternDefinitions[i];
                    var key = GetCandlePatternDefinitionKey(definition);
                    int existingCount;
                    if (matchCounts.TryGetValue(key, out existingCount) && existingCount >= maxMarkersPerType)
                        continue;

                    var matched = useCachedGeometry && cachedMatches.ContainsKey(barTimeUnix) && cachedMatches[barTimeUnix].Contains(key);
                    if (!useCachedGeometry && definition.NativeMatch != null)
                    {
                        matched = definition.NativeMatch(sourceBars, barIndex);
                    }
                    else if (!useCachedGeometry && !string.IsNullOrWhiteSpace(definition.SharedPatternType))
                    {
                        if (sharedDetections == null)
                            sharedDetections = GetDetectedSharedRulePatternSetCached(sourceBars, sourceTimeFrame, barIndex, sharedPatternCache);
                        matched = sharedDetections.Contains(definition.SharedPatternType);
                    }

                    if (!useCachedGeometry && matched)
                        rawCache.Matches.Add(new PersistedCandlePatternMatch { BarTimeUnix = barTimeUnix, DefinitionKey = key });

                    if (!matched)
                        continue;

                    if (!HasEventVolumeSurge(sourceBars, barIndex, definition.PatternSpan))
                        continue;

                    List<CandleConfluenceMatch> confluenceMatches;
                    if (!ShouldKeepCandlePatternInline(sourceBars, sourceTimeFrame, barIndex, definition.IsBullish, out confluenceMatches))
                        continue;

                    if (!HasDirectionalReversalWick(sourceBars, barIndex, definition.IsBullish))
                        continue;

                    int markerBarIndex;
                    string labelSuffix;
                    if (!TryResolveCandlePatternVisualFollowUp(sourceBars, barIndex, definition.IsBullish, definition.FollowUpFilter, out markerBarIndex, out labelSuffix))
                        continue;

                    AddDirectionalPatternAggregate(
                        aggregates,
                        sourceBars,
                        sourceTimeFrame,
                        markerBarIndex,
                        definition.IsBullish,
                        slotIndexes[key],
                        definition.ShortLabel + labelSuffix,
                        definition.PatternSpan,
                        true,
                        barIndex,
                        confluenceMatches);
                    matchCounts[key] = existingCount + 1;
                }

                CollectNeutralCandlePatternMarkers(
                    aggregates,
                    sourceBars,
                    sourceTimeFrame,
                    barIndex,
                    patternDefinitions,
                    sharedDetections ?? GetDetectedSharedRulePatternSetCached(sourceBars, sourceTimeFrame, barIndex, sharedPatternCache),
                    matchCounts,
                    maxMarkersPerType);

                if (slotIndexes.Keys.All(key => matchCounts.ContainsKey(key) && matchCounts[key] >= maxMarkersPerType))
                    break;

                if (!useCachedGeometry && barTimeUnix > 0)
                    rawCache.ComputedBarTimesUnix.Add(barTimeUnix);
            }

            var oldestAllowed = ToUnixSecondsSafe(sourceBars.OpenTimes[Math.Max(0, lastClosedIndex - CanonicalEventCacheMaxBars + 1)]);
            rawCache.ComputedBarTimesUnix.RemoveWhere(value => value > 0 && value < oldestAllowed);
            rawCache.Matches.RemoveAll(match => match == null || (match.BarTimeUnix > 0 && match.BarTimeUnix < oldestAllowed));
            MarkAnalysisCacheDirty("patterns", cacheSymbol, sourceTimeFrame);
        }

        private void CollectNeutralCandlePatternMarkers(
            List<DirectionalPatternMarkerAggregate> aggregates,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int barIndex,
            List<CandlePatternDefinition> patternDefinitions,
            HashSet<string> sharedDetections,
            Dictionary<string, int> matchCounts,
            int maxMarkersPerType)
        {
            if (aggregates == null || sourceBars == null || patternDefinitions == null || sharedDetections == null || matchCounts == null)
                return;

            foreach (var group in patternDefinitions
                .Where(item => item != null && !string.IsNullOrWhiteSpace(item.SharedPatternType))
                .GroupBy(item => item.ShortLabel, StringComparer.OrdinalIgnoreCase))
            {
                var definitions = group.ToList();
                if (definitions.Count == 0 || definitions.Any(item => item.FollowUpFilter != StructureEventFollowUpFilter.Any))
                    continue;

                int haramiPatternSpan;
                bool haramiIsBullish;
                if (NormalizeEventLabelPriorityKey(group.Key) == "HAR" &&
                    TryMatchNeutralCandlePatternGeometry(sourceBars, barIndex, group.Key, out haramiPatternSpan) &&
                    TryResolveHaramiSecondCandleDirection(
                        sourceBars,
                        barIndex,
                        patternDefinitions,
                        sharedDetections,
                        out haramiIsBullish))
                {
                    var haramiCountKey = group.Key + (haramiIsBullish ? ":BULL" : ":BEAR");
                    int haramiExistingCount;
                    matchCounts.TryGetValue(haramiCountKey, out haramiExistingCount);
                    if (haramiExistingCount >= maxMarkersPerType || !HasEventVolumeSurge(sourceBars, barIndex, haramiPatternSpan))
                        continue;

                    List<CandleConfluenceMatch> directionalMatches;
                    if (!ShouldKeepCandlePatternInline(sourceBars, sourceTimeFrame, barIndex, haramiIsBullish, out directionalMatches))
                        continue;

                    var haramiDefinition = definitions[0];
                    var slot = patternDefinitions.IndexOf(haramiDefinition);
                    AddDirectionalPatternAggregate(
                        aggregates,
                        sourceBars,
                        sourceTimeFrame,
                        barIndex,
                        haramiIsBullish,
                        slot >= 0 ? slot : 0,
                        group.Key,
                        haramiPatternSpan,
                        true,
                        barIndex,
                        directionalMatches);
                    matchCounts[haramiCountKey] = haramiExistingCount + 1;
                    continue;
                }

                if (definitions.Any(item => sharedDetections.Contains(item.SharedPatternType)))
                    continue;

                int patternSpan;
                if (!TryMatchNeutralCandlePatternGeometry(sourceBars, barIndex, group.Key, out patternSpan))
                    continue;

                var countKey = group.Key + ":NEUTRAL";
                int existingCount;
                matchCounts.TryGetValue(countKey, out existingCount);
                if (existingCount >= maxMarkersPerType || !HasEventVolumeSurge(sourceBars, barIndex, patternSpan))
                    continue;

                var range = Range(sourceBars, barIndex);
                if (!(range > 0) || Math.Max(UpperWick(sourceBars, barIndex), LowerWick(sourceBars, barIndex)) / range < 0.30)
                    continue;

                List<CandleConfluenceMatch> bullishMatches;
                List<CandleConfluenceMatch> bearishMatches;
                var bullishConfluence = ShouldKeepCandlePatternInline(sourceBars, sourceTimeFrame, barIndex, true, out bullishMatches);
                var bearishConfluence = ShouldKeepCandlePatternInline(sourceBars, sourceTimeFrame, barIndex, false, out bearishMatches);
                if (!bullishConfluence && !bearishConfluence)
                    continue;

                var firstDefinition = definitions[0];
                var neutralSlot = patternDefinitions.IndexOf(firstDefinition);
                AddDirectionalPatternAggregate(
                    aggregates,
                    sourceBars,
                    sourceTimeFrame,
                    barIndex,
                    false,
                    neutralSlot >= 0 ? neutralSlot : 0,
                    group.Key,
                    patternSpan,
                    true,
                    barIndex,
                    bullishConfluence ? bullishMatches : bearishMatches,
                    true);
                matchCounts[countKey] = existingCount + 1;
            }
        }

        private bool TryResolveHaramiSecondCandleDirection(
            Bars sourceBars,
            int index,
            List<CandlePatternDefinition> patternDefinitions,
            HashSet<string> sharedDetections,
            out bool isBullish)
        {
            isBullish = false;
            if (!IsValidBarIndex(sourceBars, index) || !IsValidBarIndex(sourceBars, index - 1))
                return false;

            // A directional pattern on Harami's second candle owns the Harami direction.
            // Ignore HAR itself to avoid circular direction resolution. If enabled patterns
            // conflict, fall through to the established mother-candle/trend logic below.
            var secondPatternBullish = false;
            var secondPatternBearish = false;
            foreach (var definition in patternDefinitions ?? new List<CandlePatternDefinition>())
            {
                if (definition == null || NormalizeEventLabelPriorityKey(definition.ShortLabel) == "HAR")
                    continue;

                var matches = definition.NativeMatch != null
                    ? definition.NativeMatch(sourceBars, index)
                    : !string.IsNullOrWhiteSpace(definition.SharedPatternType) &&
                      sharedDetections != null &&
                      sharedDetections.Contains(definition.SharedPatternType);
                if (!matches)
                    continue;

                if (definition.IsBullish)
                    secondPatternBullish = true;
                else
                    secondPatternBearish = true;
            }

            if (secondPatternBullish != secondPatternBearish)
            {
                isBullish = secondPatternBullish;
                return true;
            }

            return CTraderCandlePatternEngine.TryResolveHaramiDirection(
                Open(sourceBars, index),
                Close(sourceBars, index),
                Open(sourceBars, index - 1),
                Close(sourceBars, index - 1),
                InferCandlePriorPressure(sourceBars, index - 2, 4),
                out isBullish);
        }

        private string InferCandlePriorPressure(Bars sourceBars, int endIndex, int lookback)
        {
            if (sourceBars == null || endIndex < 1 || endIndex >= sourceBars.Count)
                return "neutral";

            var startIndex = Math.Max(0, endIndex - Math.Max(2, lookback) + 1);
            var firstClose = Close(sourceBars, startIndex);
            var lastClose = Close(sourceBars, endIndex);
            var bullishCount = 0;
            var bearishCount = 0;
            for (var i = startIndex; i <= endIndex; i++)
            {
                if (Close(sourceBars, i) > Open(sourceBars, i))
                    bullishCount++;
                else if (Close(sourceBars, i) < Open(sourceBars, i))
                    bearishCount++;
            }

            return CTraderCandlePatternEngine.ResolvePriorPressure(firstClose, lastClose, bullishCount, bearishCount, endIndex - startIndex + 1);
        }

        private bool TryMatchNeutralCandlePatternGeometry(Bars sourceBars, int index, string shortLabel, out int patternSpan)
        {
            var current = BuildCandleStats(sourceBars, index);
            var previous = BuildCandleStats(sourceBars, index - 1);
            var previous2 = BuildCandleStats(sourceBars, index - 2);
            return CTraderCandlePatternEngine.TryMatchNeutralPattern(
                NormalizeEventLabelPriorityKey(shortLabel), current, previous, previous2, out patternSpan);
        }

        private CTraderCandleStats BuildCandleStats(Bars sourceBars, int index)
        {
            if (!IsValidBarIndex(sourceBars, index))
                return null;
            return CTraderCandlePatternEngine.BuildStats(
                Open(sourceBars, index), High(sourceBars, index), Low(sourceBars, index), Close(sourceBars, index));
        }

        private bool TryResolveCandlePatternVisualFollowUp(
            Bars sourceBars,
            int patternIndex,
            bool bullish,
            StructureEventFollowUpFilter filter,
            out int markerIndex,
            out string labelSuffix)
        {
            return TryResolveStructureVisualFollowUp(sourceBars, patternIndex, bullish, filter, out markerIndex, out labelSuffix);
        }

        private string GetCandlePatternDefinitionKey(CandlePatternDefinition definition)
        {
            return string.Format(
                CultureInfo.InvariantCulture,
                "{0}:{1}:{2}:{3}",
                definition != null ? (definition.ShortLabel ?? "") : "",
                definition != null && definition.IsBullish ? "B" : "S",
                definition != null ? (definition.SharedPatternType ?? (definition.NativeMatch != null ? definition.NativeMatch.Method.Name : "")) : "",
                definition != null ? Convert.ToString(definition.FollowUpFilter, CultureInfo.InvariantCulture) : "");
        }

        private bool ShouldKeepCandlePatternInline(
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int barIndex,
            bool isBullish,
            out List<CandleConfluenceMatch> matches,
            string symbolNameOverride = null,
            Symbol symbolOverride = null)
        {
            matches = new List<CandleConfluenceMatch>();
            if (CandleConfluenceWith == CandleConfluenceMode.None)
                return true;

            var confluenceSymbol = symbolOverride ?? Symbol;
            if (sourceBars == null || confluenceSymbol == null || barIndex < 0 || barIndex >= sourceBars.Count)
                return false;

            var symbolName = !string.IsNullOrWhiteSpace(symbolNameOverride)
                ? symbolNameOverride
                : !string.IsNullOrWhiteSpace(Chart != null ? Chart.SymbolName : "")
                ? Chart.SymbolName
                : Symbol.Name;
            if (string.IsNullOrWhiteSpace(symbolName))
                return false;

            var barHigh = sourceBars.HighPrices[barIndex];
            var barLow = sourceBars.LowPrices[barIndex];
            var anchorPrice = isBullish ? barLow : barHigh;
            var barSpan = Math.Max(barHigh - barLow, confluenceSymbol.PipSize * 4.0);
            var priceTolerance = Math.Max(confluenceSymbol.PipSize * 6.0, barSpan * 0.25);
            var requireTouch = CandleConfluenceWith == CandleConfluenceMode.All_touch;
            var includeAll = CandleConfluenceWith == CandleConfluenceMode.All_near || requireTouch;
            var chartProfile = GetChartTradeProfileRaw(ReadChartTradeTypeComboSelection());
            var patternEndTime = barIndex + 1 < sourceBars.Count
                ? sourceBars.OpenTimes[barIndex + 1]
                : sourceBars.OpenTimes[barIndex].AddMinutes(Math.Max(1, TimeFrameToMinutes(sourceTimeFrame)));

            var confluenceTimeFrames = new List<TimeFrame> { sourceTimeFrame };
            confluenceTimeFrames.AddRange(GetChartTradeStructureTimeFrames(chartProfile));
            var sourceMinutes = Math.Max(1, TimeFrameToMinutes(sourceTimeFrame));
            foreach (var structureTimeFrame in confluenceTimeFrames
                .Where(value => value != null)
                .Where(value => TimeFrameToMinutes(value) >= sourceMinutes)
                .Distinct())
            {
                try
                {
                    var structureBars = GetBarsForCurrentMasterTimer(structureTimeFrame, symbolName);
                    if (structureBars == null || structureBars.Count < 5)
                        continue;
                    var structureEndIndex = ResolveLastClosedBarIndexAtOrBefore(structureBars, patternEndTime);
                    if (structureEndIndex < 2)
                        continue;

                    if (includeAll || CandleConfluenceWith == CandleConfluenceMode.Kl_KeyLevels)
                    {
                        int previousIndex;
                        if (ShouldProjectPreviousBarLevel(structureTimeFrame, sourceTimeFrame) &&
                            TryGetPreviousCompletedPeriodBarIndex(structureBars, structureTimeFrame, out previousIndex))
                        {
                            AddCandleLevelConfluenceMatch(matches, "Bar High", structureTimeFrame, structureBars.HighPrices[previousIndex], barLow, barHigh, anchorPrice, priceTolerance, requireTouch);
                            AddCandleLevelConfluenceMatch(matches, "Bar Low", structureTimeFrame, structureBars.LowPrices[previousIndex], barLow, barHigh, anchorPrice, priceTolerance, requireTouch);
                        }

                        var start = ResolveWorkingStartIndex(structureBars, 2, 2, structureTimeFrame);
                        var resistance = double.MinValue;
                        var support = double.MaxValue;
                        for (var i = start; i < structureBars.Count - 2; i++)
                        {
                            resistance = Math.Max(resistance, structureBars.HighPrices[i]);
                            support = Math.Min(support, structureBars.LowPrices[i]);
                        }
                        AddCandleLevelConfluenceMatch(matches, "Range High", structureTimeFrame, resistance, barLow, barHigh, anchorPrice, priceTolerance, requireTouch);
                        AddCandleLevelConfluenceMatch(matches, "Range Low", structureTimeFrame, support, barLow, barHigh, anchorPrice, priceTolerance, requireTouch);
                        foreach (var swing in CollectConfirmedSwings(structureBars, ResolveWorkingSwingLookbackBars(structureBars, structureTimeFrame)).TakeLast(10))
                            AddCandleLevelConfluenceMatch(matches, swing.IsHigh ? "Swing High" : "Swing Low", structureTimeFrame, swing.Price, barLow, barHigh, anchorPrice, priceTolerance, requireTouch);
                    }

                    if (includeAll || CandleConfluenceWith == CandleConfluenceMode.Ob_OrderBlock)
                        CollectCandleOrderBlockConfluenceMatches(matches, structureBars, structureTimeFrame, structureEndIndex, isBullish, barLow, barHigh, anchorPrice, priceTolerance, requireTouch);

                    if (includeAll || CandleConfluenceWith == CandleConfluenceMode.Fvg_FairValueGap)
                        CollectCandleFvgConfluenceMatches(matches, structureBars, structureTimeFrame, structureEndIndex, isBullish, barLow, barHigh, anchorPrice, priceTolerance, requireTouch);

                    if (includeAll || CandleConfluenceWith == CandleConfluenceMode.Sup_Support)
                    {
                        var start = ResolveWorkingStartIndex(structureBars, 2, 2, structureTimeFrame);
                        var support = double.MaxValue;
                        for (var i = start; i < structureBars.Count - 2; i++)
                            support = Math.Min(support, structureBars.LowPrices[i]);
                        AddCandleLevelConfluenceMatch(matches, "Support", structureTimeFrame, support, barLow, barHigh, anchorPrice, priceTolerance, requireTouch);
                    }

                    if (includeAll || CandleConfluenceWith == CandleConfluenceMode.Dem_Demand)
                    {
                        foreach (var zone in DetectScoredPriceZones(structureBars, confluenceSymbol, ResolveWorkingLookbackBars(structureBars, structureTimeFrame), structureTimeFrame))
                        {
                            var resolved = zone;
                            if (resolved.High < sourceBars.ClosePrices[barIndex])
                                resolved = WithZoneKind(resolved, ScoredPriceZoneKind.Demand);
                            else if (resolved.Low > sourceBars.ClosePrices[barIndex])
                                resolved = WithZoneKind(resolved, ScoredPriceZoneKind.Supply);
                            else
                                continue;

                            // All modes follow the rejection direction: bullish candles reject
                            // demand below, while bearish candles reject supply above. The explicit
                            // Demand mode remains demand-only as its parameter name promises.
                            var expectedKind = includeAll && !isBullish
                                ? ScoredPriceZoneKind.Supply
                                : ScoredPriceZoneKind.Demand;
                            if (resolved.Kind != expectedKind)
                                continue;
                            AddCandleZoneConfluenceMatch(
                                matches,
                                expectedKind == ScoredPriceZoneKind.Supply ? "Supply" : "Demand",
                                structureTimeFrame,
                                resolved.Low,
                                resolved.High,
                                barLow,
                                barHigh,
                                anchorPrice,
                                priceTolerance,
                                requireTouch);
                        }
                    }

                    if (includeAll || CandleConfluenceWith == CandleConfluenceMode.Eqhl_EqualHighLow)
                    {
                        var equalLevelTolerance = Math.Max(Symbol.PipSize * 2.0, 0.0000001);
                        foreach (var pattern in DetectSwingLevelPatterns(structureBars, equalLevelTolerance)
                            .Where(value => value.Type == SwingLevelPatternType.EqualHighs || value.Type == SwingLevelPatternType.EqualLows))
                        {
                            var levelKind = pattern.Type == SwingLevelPatternType.EqualHighs ? "EQH" : "EQL";
                            AddCandleLevelConfluenceMatch(matches, levelKind, structureTimeFrame, pattern.Level, barLow, barHigh, anchorPrice, priceTolerance, requireTouch);
                        }
                    }
                }
                catch
                {
                }
            }

            // High-side references describe bearish rejection; low-side references
            // describe bullish rejection. Never attach the opposite side merely
            // because the candle is near that price.
            matches = matches
                .Where(item => IsDirectionalCandleLevelConfluence(item, isBullish))
                .ToList();
            var bestMatch = SelectBestCandleConfluenceMatch(matches, barLow, barHigh, anchorPrice);
            matches.Clear();
            if (bestMatch != null)
                matches.Add(bestMatch);

            return bestMatch != null;
        }

        private bool IsDirectionalCandleLevelConfluence(CandleConfluenceMatch match, bool isBullish)
        {
            if (match == null)
                return false;
            var kind = (match.Kind ?? "").Trim().ToUpperInvariant();
            if (isBullish)
                return kind != "KEY HIGH" && kind != "BAR HIGH" && kind != "RANGE HIGH" && kind != "SWING HIGH" && kind != "RESISTANCE" && kind != "EQH";
            return kind != "KEY LOW" && kind != "BAR LOW" && kind != "RANGE LOW" && kind != "SWING LOW" && kind != "SUPPORT" && kind != "EQL";
        }

        private int ResolveLastClosedBarIndexAtOrBefore(Bars sourceBars, DateTime cutoffTime)
        {
            if (sourceBars == null || sourceBars.Count < 2 || cutoffTime == DateTime.MinValue)
                return -1;

            for (var i = sourceBars.Count - 2; i >= 0; i--)
            {
                if (sourceBars.OpenTimes[i + 1] <= cutoffTime)
                    return i;
            }
            return -1;
        }

        private CandleConfluenceMatch SelectBestCandleConfluenceMatch(
            List<CandleConfluenceMatch> matches,
            double barLow,
            double barHigh,
            double anchorPrice)
        {
            if (matches == null || matches.Count == 0)
                return null;

            return matches
                .Where(item => item != null && IsFiniteNumber(item.Low) && IsFiniteNumber(item.High))
                .OrderByDescending(item => barHigh >= item.Low && barLow <= item.High)
                .ThenByDescending(item => GetCandleConfluenceImportance(item.Kind))
                .ThenByDescending(item => TimeFrameToMinutes(item.SourceTimeFrame))
                .ThenBy(item => GetDistanceToPriceRange(anchorPrice, item.Low, item.High))
                .FirstOrDefault();
        }

        private static int GetCandleConfluenceImportance(string kind)
        {
            switch ((kind ?? "").Trim().ToUpperInvariant())
            {
                case "KEY HIGH":
                case "KEY LOW":
                case "BAR HIGH":
                case "BAR LOW":
                    return 600;
                case "RESISTANCE":
                case "SUPPORT":
                case "RANGE HIGH":
                case "RANGE LOW":
                    return 500;
                case "OB":
                case "DEMAND":
                case "SUPPLY":
                    return 400;
                case "FVG":
                    return 300;
                case "EQH":
                case "EQL":
                    return 200;
                case "SWING":
                case "SWING HIGH":
                case "SWING LOW":
                    return 100;
                default:
                    return 0;
            }
        }

        private static double GetDistanceToPriceRange(double price, double rangeLow, double rangeHigh)
        {
            var low = Math.Min(rangeLow, rangeHigh);
            var high = Math.Max(rangeLow, rangeHigh);
            if (price < low)
                return low - price;
            if (price > high)
                return price - high;
            return 0.0;
        }

        private void CollectCandleFvgConfluenceMatches(
            List<CandleConfluenceMatch> matches,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int snapshotEndIndex,
            bool isBullish,
            double barLow,
            double barHigh,
            double anchorPrice,
            double tolerance,
            bool requireTouch)
        {
            if (sourceBars == null)
                return;
            var zones = BuildStructureSnapshotV2(sourceBars, 80, snapshotEndIndex).Zones
                .Where(value => (value.Type == StructureZoneTypeV2.Fvg || value.Type == StructureZoneTypeV2.InverseFvg) &&
                                value.State != StructureZoneStateV2.Invalidated &&
                                value.IsBullish == isBullish)
                .OrderByDescending(value => value.ConfirmationBarIndex);
            foreach (var zone in zones)
            {
                AddCandleZoneConfluenceMatch(matches, "FVG", sourceTimeFrame, zone.Low, zone.High, barLow, barHigh, anchorPrice, tolerance, requireTouch);
            }
        }

        private void CollectCandleOrderBlockConfluenceMatches(
            List<CandleConfluenceMatch> matches,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int snapshotEndIndex,
            bool isBullish,
            double barLow,
            double barHigh,
            double anchorPrice,
            double tolerance,
            bool requireTouch)
        {
            if (sourceBars == null)
                return;
            var zones = BuildStructureSnapshotV2(sourceBars, 80, snapshotEndIndex).Zones
                .Where(value => (value.Type == StructureZoneTypeV2.OrderBlock || value.Type == StructureZoneTypeV2.BreakerBlock) &&
                                value.State != StructureZoneStateV2.Invalidated &&
                                value.IsBullish == isBullish)
                .OrderByDescending(value => value.ConfirmationBarIndex);
            foreach (var zone in zones)
            {
                AddCandleZoneConfluenceMatch(matches, "OB", sourceTimeFrame, zone.Low, zone.High, barLow, barHigh, anchorPrice, tolerance, requireTouch);
            }
        }

        private void AddCandleLevelConfluenceMatch(
            List<CandleConfluenceMatch> matches,
            string kind,
            TimeFrame sourceTimeFrame,
            double price,
            double barLow,
            double barHigh,
            double anchorPrice,
            double tolerance,
            bool requireTouch)
        {
            if (matches == null || !IsFiniteNumber(price) || price <= 0)
                return;

            var matched = requireTouch
                ? price >= barLow && price <= barHigh
                : Math.Abs(price - anchorPrice) <= tolerance;
            if (!matched)
                return;

            var duplicateTolerance = Math.Max(tolerance * 0.02, 0.0000001);
            if (matches.Any(item => item != null && item.SourceTimeFrame == sourceTimeFrame && string.Equals(item.Kind, kind, StringComparison.OrdinalIgnoreCase) && Math.Abs(item.Low - price) <= duplicateTolerance))
                return;
            matches.Add(new CandleConfluenceMatch { Kind = kind, SourceTimeFrame = sourceTimeFrame, Low = price, High = price });
        }

        private void AddCandleZoneConfluenceMatch(
            List<CandleConfluenceMatch> matches,
            string kind,
            TimeFrame sourceTimeFrame,
            double zoneLow,
            double zoneHigh,
            double barLow,
            double barHigh,
            double anchorPrice,
            double tolerance,
            bool requireTouch)
        {
            if (matches == null || !IsFiniteNumber(zoneLow) || !IsFiniteNumber(zoneHigh) || zoneHigh <= zoneLow)
                return;

            var matched = requireTouch
                ? barHigh >= zoneLow && barLow <= zoneHigh
                : anchorPrice >= zoneLow - tolerance && anchorPrice <= zoneHigh + tolerance;
            if (!matched)
                return;
            if (matches.Any(item => item != null && item.SourceTimeFrame == sourceTimeFrame && string.Equals(item.Kind, kind, StringComparison.OrdinalIgnoreCase) && Math.Abs(item.Low - zoneLow) <= 0.0000001 && Math.Abs(item.High - zoneHigh) <= 0.0000001))
                return;
            matches.Add(new CandleConfluenceMatch { Kind = kind, SourceTimeFrame = sourceTimeFrame, Low = zoneLow, High = zoneHigh });
        }

        private bool HasDirectionalReversalWick(Bars sourceBars, int barIndex, bool isBullish)
        {
            if (!IsValidBarIndex(sourceBars, barIndex))
                return false;
            return CTraderCandlePatternEngine.HasDirectionalReversalWick(
                Open(sourceBars, barIndex), High(sourceBars, barIndex), Low(sourceBars, barIndex), Close(sourceBars, barIndex),
                isBullish, 0.30);
        }

        private bool IsCandleNearKeyLevelConfluence(string symbolName, string chartProfile, double anchorPrice, double barClose, double priceTolerance)
        {
            foreach (var sourceTimeFrame in GetChartTradeStructureTimeFrames(chartProfile))
            {
                try
                {
                    var sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, symbolName);
                    if (sourceBars == null || sourceBars.Count < 5)
                        continue;

                    int previousIndex;
                    if (ShouldProjectPreviousBarLevel(sourceTimeFrame, Chart != null ? Chart.TimeFrame : TimeFrame.Minute) &&
                        TryGetPreviousCompletedPeriodBarIndex(sourceBars, sourceTimeFrame, out previousIndex))
                    {
                        if (IsPriceNearEither(sourceBars.HighPrices[previousIndex], anchorPrice, barClose, priceTolerance) ||
                            IsPriceNearEither(sourceBars.LowPrices[previousIndex], anchorPrice, barClose, priceTolerance))
                            return true;
                    }

                    var start = ResolveWorkingStartIndex(sourceBars, 2, 2, sourceTimeFrame);
                    var resistance = double.MinValue;
                    var support = double.MaxValue;
                    for (var i = start; i < sourceBars.Count - 2; i++)
                    {
                        resistance = Math.Max(resistance, sourceBars.HighPrices[i]);
                        support = Math.Min(support, sourceBars.LowPrices[i]);
                    }

                    if (resistance > double.MinValue && IsPriceNearEither(resistance, anchorPrice, barClose, priceTolerance))
                        return true;
                    if (support < double.MaxValue && IsPriceNearEither(support, anchorPrice, barClose, priceTolerance))
                        return true;

                    foreach (var swing in CollectConfirmedSwings(sourceBars, ResolveWorkingSwingLookbackBars(sourceBars, sourceTimeFrame)).TakeLast(10))
                    {
                        if (IsPriceNearEither(swing.Price, anchorPrice, barClose, priceTolerance))
                            return true;
                    }
                }
                catch
                {
                }
            }

            return false;
        }

        private bool IsCandleNearOrderBlockConfluence(string symbolName, string chartProfile, double anchorPrice, double barClose, double priceTolerance)
        {
            foreach (var sourceTimeFrame in GetChartTradeStructureTimeFrames(chartProfile))
            {
                try
                {
                    var sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, symbolName);
                    if (sourceBars == null || sourceBars.Count < 5)
                        continue;

                    var obLevels = new List<double>();
                    AddOrderBlockLevelCandidates(obLevels, sourceBars, Math.Max(Symbol.PipSize * 2.0, 0.0000001));
                    if (obLevels.Any(level => IsPriceNearEither(level, anchorPrice, barClose, priceTolerance)))
                        return true;
                }
                catch
                {
                }
            }

            return false;
        }

        private bool IsCandleNearFvgConfluence(string symbolName, string chartProfile, double anchorPrice, double barClose, double priceTolerance)
        {
            foreach (var sourceTimeFrame in GetChartTradeStructureTimeFrames(chartProfile))
            {
                try
                {
                    var sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, symbolName);
                    if (sourceBars == null || sourceBars.Count < 5)
                        continue;

                    var fvgLevels = new List<double>();
                    AddFvgLevelCandidates(fvgLevels, sourceBars, Math.Max(Symbol.PipSize * 2.0, 0.0000001));
                    if (fvgLevels.Any(level => IsPriceNearEither(level, anchorPrice, barClose, priceTolerance)))
                        return true;
                }
                catch
                {
                }
            }

            return false;
        }

        private bool IsCandleNearSupportConfluence(string symbolName, string chartProfile, double anchorPrice, double barClose, double priceTolerance)
        {
            foreach (var sourceTimeFrame in GetChartTradeStructureTimeFrames(chartProfile))
            {
                try
                {
                    var sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, symbolName);
                    if (sourceBars == null || sourceBars.Count < 5)
                        continue;

                    var start = ResolveWorkingStartIndex(sourceBars, 2, 2, sourceTimeFrame);
                    var support = double.MaxValue;
                    for (var i = start; i < sourceBars.Count - 2; i++)
                        support = Math.Min(support, sourceBars.LowPrices[i]);

                    if (support < double.MaxValue && IsPriceNearEither(support, anchorPrice, barClose, priceTolerance))
                        return true;
                }
                catch
                {
                }
            }

            return false;
        }

        private bool IsCandleNearDemandConfluence(string symbolName, string chartProfile, DateTime barTime, double anchorPrice, double barClose, double priceTolerance)
        {
            foreach (var sourceTimeFrame in GetChartTradeStructureTimeFrames(chartProfile))
            {
                try
                {
                    var sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, symbolName);
                    if (sourceBars == null || sourceBars.Count < 20)
                        continue;

                    var currentPrice = barClose > 0 ? barClose : anchorPrice;
                    foreach (var zone in DetectScoredPriceZones(sourceBars, Symbol, ResolveWorkingLookbackBars(sourceBars, sourceTimeFrame), sourceTimeFrame))
                    {
                        var resolved = zone;
                        if (resolved.High < currentPrice)
                            resolved = WithZoneKind(resolved, ScoredPriceZoneKind.Demand);
                        else if (resolved.Low > currentPrice)
                            resolved = WithZoneKind(resolved, ScoredPriceZoneKind.Supply);
                        else
                            continue;

                        if (resolved.Kind != ScoredPriceZoneKind.Demand)
                            continue;

                        var mid = (resolved.Low + resolved.High) * 0.5;
                        if (IsPriceNearEither(mid, anchorPrice, barClose, Math.Max(priceTolerance, (resolved.High - resolved.Low) * 0.75)) ||
                            IsPriceNearEither(resolved.Low, anchorPrice, barClose, priceTolerance) ||
                            IsPriceNearEither(resolved.High, anchorPrice, barClose, priceTolerance))
                            return true;
                    }
                }
                catch
                {
                }
            }

            return false;
        }

        private bool IsCandleNearEqhlConfluence(string symbolName, string chartProfile, double anchorPrice, double barClose, double priceTolerance)
        {
            foreach (var sourceTimeFrame in GetChartTradeStructureTimeFrames(chartProfile))
            {
                try
                {
                    var sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, symbolName);
                    if (sourceBars == null || sourceBars.Count < 5)
                        continue;

                    var eqhlLevels = new List<double>();
                    AddEqualHighLowCandidates(eqhlLevels, sourceBars, Math.Max(Symbol.PipSize * 2.0, 0.0000001));
                    if (eqhlLevels.Any(level => IsPriceNearEither(level, anchorPrice, barClose, priceTolerance)))
                        return true;
                }
                catch
                {
                }
            }

            return false;
        }

        private bool IsPriceNearEither(double levelPrice, double anchorPrice, double closePrice, double tolerance)
        {
            if (levelPrice <= 0 || tolerance <= 0)
                return false;

            return Math.Abs(levelPrice - anchorPrice) <= tolerance ||
                   Math.Abs(levelPrice - closePrice) <= tolerance;
        }

        private HashSet<string> GetDetectedSharedRulePatternSetCached(
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int index,
            Dictionary<int, HashSet<string>> cache)
        {
            if (cache == null)
                return new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            HashSet<string> detected;
            if (cache.TryGetValue(index, out detected))
                return detected;

            detected = GetDetectedSharedRulePatternSet(sourceBars, sourceTimeFrame, index);
            cache[index] = detected;
            return detected;
        }

        private HashSet<string> GetDetectedSharedRulePatternSet(Bars sourceBars, TimeFrame sourceTimeFrame, int index)
        {
            if (sourceBars == null || index <= 0 || index >= sourceBars.Count)
                return new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            var cacheClosedBar = index < sourceBars.Count - 1;
            var cacheKey = default(SharedPatternDetectionCacheKey);
            if (cacheClosedBar)
            {
                cacheKey = new SharedPatternDetectionCacheKey(sourceBars, index, sourceBars.OpenTimes[index]);
                HashSet<string> cached;
                if (_sharedPatternDetectionCache.TryGetValue(cacheKey, out cached))
                    return cached;
            }

            try
            {
                var context = BuildSharedRuleContext(sourceBars, index, Symbol, sourceTimeFrame, null);
                var detected = DetectSharedRulePatterns(context) ?? new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                if (cacheClosedBar)
                    CTraderCacheEngine.StoreBoundedFifo(
                        _sharedPatternDetectionCache,
                        _sharedPatternDetectionCacheOrder,
                        cacheKey,
                        detected,
                        SharedPatternDetectionCacheMaxEntries,
                        true);
                return detected;
            }
            catch
            {
                return new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            }
        }

        private int DrawDirectionalIndicatorEventsOnChart(int objectIndex)
        {
            if (DisableTechnicalVisualRenderingForIsolation)
                return objectIndex;

            if (!ShouldDrawChartMarkers() || Chart == null || Bars == null || Bars.Count < 16 || Symbol == null)
                return objectIndex;
            if (ChartObjectsOverBudget())
                return objectIndex;

            if (GetChartEventsPerTypeLimit() == 0)
                return objectIndex;

            try
            {
                var chartTf = Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
                var uniqueFrames = new List<TimeFrame> { chartTf };

                var aggregatedMarkers = new List<DirectionalPatternMarkerAggregate>();
                foreach (var sourceTimeFrame in uniqueFrames)
                {
                    Bars sourceBars = sourceTimeFrame == chartTf ? Bars : null;
                    if (sourceBars == null)
                    {
                        try
                        {
                            sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, Chart.SymbolName);
                        }
                        catch
                        {
                            sourceBars = null;
                        }
                    }

                    if (sourceBars == null || sourceBars.Count < 16)
                        continue;

                    CollectOptimizedDirectionalIndicatorMarkers(aggregatedMarkers, sourceBars, sourceTimeFrame);
                }

                foreach (var marker in aggregatedMarkers
                    .OrderBy(item => TimeFrameToMinutes(item.SourceTimeFrame))
                    .ThenBy(item => item.BarIndex)
                    .ThenBy(item => item.IsBullish ? 0 : 1))
                {
                    objectIndex = DrawDirectionalPatternMarker(
                        objectIndex,
                        marker.SourceBars,
                        marker.SourceTimeFrame,
                        marker.BarIndex,
                        marker.IsBullish,
                        marker.SlotIndex,
                        marker.PatternSpan,
                        marker.HighlightPatternRange,
                        FormatAggregatedCanonicalEventName(marker.SourceTimeFrame, marker.Labels, marker.IsBullish),
                        "TECH");
                }
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Indicator events failed: {0}", ex.Message);
            }

            return objectIndex;
        }

        private sealed class IndicatorEventDefinition
        {
            public string ShortLabel;
            public bool IsBullish;
            public int SlotIndex;
            public Func<Bars, int, SharedIndicatorSnapshot, SharedIndicatorSnapshot, bool> Match;
        }

        private void CollectOptimizedDirectionalIndicatorMarkers(
            List<DirectionalPatternMarkerAggregate> aggregates,
            Bars sourceBars,
            TimeFrame sourceTimeFrame)
        {
            if (aggregates == null || sourceBars == null || sourceBars.Count < 16)
                return;

            var definitions = BuildIndicatorEventDefinitions();
            if (definitions.Count == 0)
                return;

            var maxMarkersPerType = GetCollectorMarkerLimit();
            var startIndex = ResolveWorkingStartIndex(sourceBars, 2, 2, sourceTimeFrame);
            var scanCache = BuildIndicatorEventScanCache(sourceBars, startIndex - 1, GetIndicatorSnapshotRequirements());
            var matchCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

            for (var barIndex = sourceBars.Count - 2; barIndex >= startIndex; barIndex--)
            {
                var currentSnapshot = GetSharedIndicatorSnapshotCached(sourceBars, barIndex, scanCache);
                var previousSnapshot = GetSharedIndicatorSnapshotCached(sourceBars, barIndex - 1, scanCache);

                foreach (var definition in definitions)
                {
                    int existingCount;
                    if (matchCounts.TryGetValue(definition.ShortLabel, out existingCount) && existingCount >= maxMarkersPerType)
                        continue;

                    if (definition.Match == null || !definition.Match(sourceBars, barIndex, previousSnapshot, currentSnapshot))
                        continue;

                    AddDirectionalPatternAggregate(
                        aggregates,
                        sourceBars,
                        sourceTimeFrame,
                        barIndex,
                        definition.IsBullish,
                        definition.SlotIndex,
                        definition.ShortLabel);

                    matchCounts[definition.ShortLabel] = existingCount + 1;
                }

                if (definitions.All(definition =>
                {
                    int count;
                    return matchCounts.TryGetValue(definition.ShortLabel, out count) && count >= maxMarkersPerType;
                }))
                    break;
            }
        }

        private IndicatorEventScanCache BuildIndicatorEventScanCache(Bars sourceBars, int startIndex, IndicatorSnapshotRequirements requirements)
        {
            if (sourceBars == null || sourceBars.Count == 0)
            {
                return new IndicatorEventScanCache
                {
                    StartIndex = 0,
                    Snapshots = new SharedIndicatorSnapshot[0]
                };
            }

            var safeStartIndex = Math.Max(0, startIndex);
            var lastClosedBarIndex = sourceBars.Count - 2;
            if (lastClosedBarIndex < 0)
            {
                return new IndicatorEventScanCache
                {
                    StartIndex = safeStartIndex,
                    Snapshots = new SharedIndicatorSnapshot[sourceBars.Count]
                };
            }

            var settingsKey = BuildChartCacheKey(
                (int)requirements,
                _resolvedEmaEventConfig.PriceCrossPeriod,
                _resolvedEmaEventConfig.FastPeriod,
                _resolvedEmaEventConfig.MidPeriod,
                _resolvedEmaEventConfig.SlowPeriod,
                _resolvedVwapEventConfig.Length,
                _resolvedBollingerEventConfig.Period,
                _resolvedBollingerEventConfig.StdDevMultiplier,
                _resolvedRsiEventConfig.Period,
                _resolvedRsiEventConfig.Midline,
                _resolvedRsiEventConfig.Oversold,
                _resolvedRsiEventConfig.Overbought,
                _resolvedStochasticEventConfig.KPeriod,
                _resolvedStochasticEventConfig.DPeriod,
                _resolvedStochasticEventConfig.OversoldLevel,
                _resolvedStochasticEventConfig.OverboughtLevel,
                _resolvedMacdEventConfig.FastPeriod,
                _resolvedMacdEventConfig.SlowPeriod,
                _resolvedMacdEventConfig.SignalPeriod);
            var cacheKey = new IndicatorEventScanCacheKey(
                sourceBars,
                lastClosedBarIndex,
                sourceBars.OpenTimes[lastClosedBarIndex],
                settingsKey);

            IndicatorEventScanCache cached;
            if (_indicatorEventScanCache.TryGetValue(cacheKey, out cached) &&
                cached != null &&
                cached.Snapshots != null &&
                cached.StartIndex <= safeStartIndex)
            {
                return cached;
            }

            var cache = new IndicatorEventScanCache
            {
                StartIndex = safeStartIndex,
                Snapshots = new SharedIndicatorSnapshot[sourceBars.Count]
            };
            var precomputed = BuildIndicatorEventPrecomputedSeries(sourceBars, requirements);
            for (var i = safeStartIndex; i <= lastClosedBarIndex; i++)
                cache.Snapshots[i] = BuildIndicatorEventSnapshot(sourceBars, i, requirements, precomputed);

            CTraderCacheEngine.StoreBoundedFifo(
                _indicatorEventScanCache,
                _indicatorEventScanCacheOrder,
                cacheKey,
                cache,
                IndicatorEventScanCacheMaxEntries);
            return cache;
        }

        private IndicatorEventPrecomputedSeries BuildIndicatorEventPrecomputedSeries(Bars sourceBars, IndicatorSnapshotRequirements requirements)
        {
            var series = new IndicatorEventPrecomputedSeries();
            if ((requirements & IndicatorSnapshotRequirements.EmaPrice) != 0)
                series.EmaPrice = BuildExponentialMovingAverageSeries(sourceBars, _resolvedEmaEventConfig.PriceCrossPeriod);
            if ((requirements & IndicatorSnapshotRequirements.EmaFast) != 0)
                series.EmaFast = BuildExponentialMovingAverageSeries(sourceBars, _resolvedEmaEventConfig.FastPeriod);
            if ((requirements & IndicatorSnapshotRequirements.EmaMid) != 0)
                series.EmaMid = BuildExponentialMovingAverageSeries(sourceBars, _resolvedEmaEventConfig.MidPeriod);
            if ((requirements & IndicatorSnapshotRequirements.EmaSlow) != 0)
                series.EmaSlow = BuildExponentialMovingAverageSeries(sourceBars, _resolvedEmaEventConfig.SlowPeriod);
            if ((requirements & IndicatorSnapshotRequirements.VwapMain) != 0)
                series.VwapMain = BuildRollingVwapSeries(sourceBars, _resolvedVwapEventConfig.Length);
            if ((requirements & (IndicatorSnapshotRequirements.BbMid | IndicatorSnapshotRequirements.BbUpper | IndicatorSnapshotRequirements.BbLower)) != 0)
            {
                BuildBollingerSeries(
                    sourceBars,
                    _resolvedBollingerEventConfig.Period,
                    _resolvedBollingerEventConfig.StdDevMultiplier,
                    out series.BbMid,
                    out series.BbUpper,
                    out series.BbLower);
            }
            if ((requirements & IndicatorSnapshotRequirements.RsiMain) != 0)
                series.RsiMain = BuildRelativeStrengthIndexSeries(sourceBars, _resolvedRsiEventConfig.Period);
            if ((requirements & (IndicatorSnapshotRequirements.StochK | IndicatorSnapshotRequirements.StochD)) != 0)
            {
                BuildStochasticSeries(
                    sourceBars,
                    _resolvedStochasticEventConfig.KPeriod,
                    _resolvedStochasticEventConfig.DPeriod,
                    out series.StochK,
                    out series.StochD);
            }
            if ((requirements & (IndicatorSnapshotRequirements.MacdLine | IndicatorSnapshotRequirements.MacdSignal | IndicatorSnapshotRequirements.MacdHistogram)) != 0)
            {
                BuildMacdSeries(
                    sourceBars,
                    _resolvedMacdEventConfig.FastPeriod,
                    _resolvedMacdEventConfig.SlowPeriod,
                    _resolvedMacdEventConfig.SignalPeriod,
                    out series.MacdLine,
                    out series.MacdSignal);
            }
            return series;
        }

        private IndicatorSnapshotRequirements GetIndicatorSnapshotRequirements()
        {
            var requirements = IndicatorSnapshotRequirements.None;

            if (_toggleEmaEvents)
                requirements |= IndicatorSnapshotRequirements.EmaPrice |
                                IndicatorSnapshotRequirements.EmaFast |
                                IndicatorSnapshotRequirements.EmaMid |
                                IndicatorSnapshotRequirements.EmaSlow;

            if (_toggleVwapEvents)
                requirements |= IndicatorSnapshotRequirements.VwapMain;

            if (_toggleBollingerEvents)
                requirements |= IndicatorSnapshotRequirements.BbMid |
                                IndicatorSnapshotRequirements.BbUpper |
                                IndicatorSnapshotRequirements.BbLower;

            if (_toggleRsiEvents)
                requirements |= IndicatorSnapshotRequirements.RsiMain;

            if (_toggleStochasticEvents)
                requirements |= IndicatorSnapshotRequirements.StochK |
                                IndicatorSnapshotRequirements.StochD;

            if (_toggleMacdEvents)
                requirements |= IndicatorSnapshotRequirements.MacdLine |
                                IndicatorSnapshotRequirements.MacdSignal |
                                IndicatorSnapshotRequirements.MacdHistogram;

            return requirements;
        }

        private List<IndicatorEventDefinition> BuildIndicatorEventDefinitions()
        {
            var definitions = new List<IndicatorEventDefinition>();
            var slotIndex = 0;
            var emaConfig = _resolvedEmaEventConfig;
            var rsiConfig = _resolvedRsiEventConfig;
            var stochConfig = _resolvedStochasticEventConfig;

            if (_toggleEmaEvents)
            {
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "pxe", IsBullish = true, SlotIndex = slotIndex++, Match = (bars, index, previous, current) => MatchBullishPriceCrossesEmaSnapshot(bars, index, previous, current) });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "pxe", IsBullish = false, SlotIndex = slotIndex++, Match = (bars, index, previous, current) => MatchBearishPriceCrossesEmaSnapshot(bars, index, previous, current) });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "emx", IsBullish = true, SlotIndex = slotIndex++, Match = (bars, index, previous, current) => MatchBullishEmaFastMidCrossSnapshot(bars, index, previous, current) });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "emx", IsBullish = false, SlotIndex = slotIndex++, Match = (bars, index, previous, current) => MatchBearishEmaFastMidCrossSnapshot(bars, index, previous, current) });
                if (emaConfig.SlowPeriod > 0 && emaConfig.SlowPeriod != emaConfig.MidPeriod)
                {
                    definitions.Add(new IndicatorEventDefinition { ShortLabel = "emt", IsBullish = true, SlotIndex = slotIndex++, Match = (bars, index, previous, current) => MatchBullishEmaMidSlowCrossSnapshot(bars, index, previous, current) });
                    definitions.Add(new IndicatorEventDefinition { ShortLabel = "emt", IsBullish = false, SlotIndex = slotIndex++, Match = (bars, index, previous, current) => MatchBearishEmaMidSlowCrossSnapshot(bars, index, previous, current) });
                }
            }

            if (_toggleVwapEvents)
            {
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "vwx", IsBullish = true, SlotIndex = slotIndex++, Match = MatchBullishPriceCrossesVwapSnapshot });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "vwx", IsBullish = false, SlotIndex = slotIndex++, Match = MatchBearishPriceCrossesVwapSnapshot });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "vwr", IsBullish = true, SlotIndex = slotIndex++, Match = MatchBullishVwapRejectionSnapshot });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "vwr", IsBullish = false, SlotIndex = slotIndex++, Match = MatchBearishVwapRejectionSnapshot });
            }

            if (_toggleBollingerEvents)
            {
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "bbx", IsBullish = true, SlotIndex = slotIndex++, Match = MatchBullishPriceCrossesBollingerMidSnapshot });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "bbx", IsBullish = false, SlotIndex = slotIndex++, Match = MatchBearishPriceCrossesBollingerMidSnapshot });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "bbr", IsBullish = true, SlotIndex = slotIndex++, Match = MatchBullishBollingerRejectionSnapshot });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "bbr", IsBullish = false, SlotIndex = slotIndex++, Match = MatchBearishBollingerRejectionSnapshot });
            }

            if (_toggleRsiEvents)
            {
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "r50", IsBullish = true, SlotIndex = slotIndex++, Match = (bars, index, previous, current) => MatchBullishRsiCrossSnapshot(bars, index, previous, current, rsiConfig.Midline) });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "r50", IsBullish = false, SlotIndex = slotIndex++, Match = (bars, index, previous, current) => MatchBearishRsiCrossSnapshot(bars, index, previous, current, rsiConfig.Midline) });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "ros", IsBullish = true, SlotIndex = slotIndex++, Match = (bars, index, previous, current) => MatchBullishRsiOversoldSnapshot(bars, index, previous, current, rsiConfig.Oversold) });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "rob", IsBullish = false, SlotIndex = slotIndex++, Match = (bars, index, previous, current) => MatchBearishRsiOverboughtSnapshot(bars, index, previous, current, rsiConfig.Overbought) });
            }

            if (_toggleStochasticEvents)
            {
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "stx", IsBullish = true, SlotIndex = slotIndex++, Match = (bars, index, previous, current) => MatchBullishStochasticCrossSnapshot(bars, index, previous, current) });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "stx", IsBullish = false, SlotIndex = slotIndex++, Match = (bars, index, previous, current) => MatchBearishStochasticCrossSnapshot(bars, index, previous, current) });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "sto", IsBullish = true, SlotIndex = slotIndex++, Match = (bars, index, previous, current) => MatchBullishStochasticExitOversoldSnapshot(bars, index, previous, current, stochConfig.OversoldLevel) });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "sto", IsBullish = false, SlotIndex = slotIndex++, Match = (bars, index, previous, current) => MatchBearishStochasticExitOverboughtSnapshot(bars, index, previous, current, stochConfig.OverboughtLevel) });
            }

            if (_toggleMacdEvents)
            {
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "mdx", IsBullish = true, SlotIndex = slotIndex++, Match = MatchBullishMacdCrossSnapshot });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "mdx", IsBullish = false, SlotIndex = slotIndex++, Match = MatchBearishMacdCrossSnapshot });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "md0", IsBullish = true, SlotIndex = slotIndex++, Match = MatchBullishMacdZeroCrossSnapshot });
                definitions.Add(new IndicatorEventDefinition { ShortLabel = "md0", IsBullish = false, SlotIndex = slotIndex++, Match = MatchBearishMacdZeroCrossSnapshot });
            }

            return definitions;
        }

        private SharedIndicatorSnapshot GetSharedIndicatorSnapshotCached(
            Bars sourceBars,
            int barIndex,
            IndicatorEventScanCache cache)
        {
            if (sourceBars == null || barIndex < 0 || barIndex >= sourceBars.Count)
                return new SharedIndicatorSnapshot();

            if (cache == null || cache.Snapshots == null || barIndex >= cache.Snapshots.Length)
                return BuildSharedIndicatorSnapshot(sourceBars, barIndex);

            var snapshot = cache.Snapshots[barIndex];
            return snapshot ?? BuildSharedIndicatorSnapshot(sourceBars, barIndex);
        }

        private int DrawIndicatorOverlaysOnChart(int objectIndex)
        {
            if (DisableTechnicalVisualRenderingForIsolation)
                return objectIndex;

            if (Chart == null || Bars == null || Bars.Count < 24)
                return objectIndex;

            try
            {
                if (_toggleEmaOverlay && !NativeEmaOverlayActive())
                {
                    var emaColor = Color.FromArgb(255, 56, 189, 248);
                    var emaFastValues = BuildExponentialMovingAverageSeries(Bars, _resolvedEmaOverlayConfig.FastPeriod);
                    var emaMidValues = BuildExponentialMovingAverageSeries(Bars, _resolvedEmaOverlayConfig.MidPeriod);
                    objectIndex = DrawIndicatorSeriesLine(objectIndex, "EMA20_", index => emaFastValues[index], emaColor, 1, "Dots", 180);
                    objectIndex = DrawIndicatorSeriesLine(objectIndex, "EMA50_", index => emaMidValues[index], emaColor, 1, "Dots", 180);
                    if (_resolvedEmaOverlayConfig.SlowPeriod > 0 && _resolvedEmaOverlayConfig.SlowPeriod != _resolvedEmaOverlayConfig.MidPeriod)
                    {
                        var emaSlowValues = BuildExponentialMovingAverageSeries(Bars, _resolvedEmaOverlayConfig.SlowPeriod);
                        objectIndex = DrawIndicatorSeriesLine(objectIndex, "EMA200_", index => emaSlowValues[index], emaColor, 1, "Dots", 220, GetEmaOverlayPairLabel(), 9, 1);
                    }
                    else
                        DrawRightEdgeIndicatorLabel("EMA200_", objectIndex, emaMidValues[Bars.Count - 1], emaColor, GetEmaOverlayPairLabel(), 9, 1);
                }

                if (_toggleVwapOverlay && !NativeVwapOverlayActive())
                {
                    var vwapColor = Color.FromArgb(255, 250, 204, 21);
                    objectIndex = DrawIndicatorSeriesLine(objectIndex, "VWAP20_", index => ComputeRollingVwapAtIndex(Bars, _resolvedVwapOverlayConfig.Length, index), vwapColor, 1, "Dots", 180, GetVwapOverlayPairLabel(), 9, 0);
                }

                if (_toggleBollingerOverlay && !NativeBollingerOverlayActive())
                {
                    var bollingerColor = Color.FromArgb(255, 244, 114, 182);
                    objectIndex = DrawIndicatorSeriesLine(objectIndex, "BBMID_", index => ComputeSimpleMovingAverage(Bars, index, _resolvedBollingerOverlayConfig.Period), bollingerColor, 1, "Dots", 180, GetBollingerOverlayPairLabel(), 9, -1);
                    objectIndex = DrawIndicatorSeriesLine(objectIndex, "BBUP_", index => ComputeBollingerUpper(Bars, index, _resolvedBollingerOverlayConfig.Period, _resolvedBollingerOverlayConfig.StdDevMultiplier), bollingerColor, 1, "Dots", 180);
                    objectIndex = DrawIndicatorSeriesLine(objectIndex, "BBDN_", index => ComputeBollingerLower(Bars, index, _resolvedBollingerOverlayConfig.Period, _resolvedBollingerOverlayConfig.StdDevMultiplier), bollingerColor, 1, "Dots", 180);
                }

                if (_toggleIchimokuOverlay && !NativeIchimokuOverlayActive())
                {
                    objectIndex = RenderIchimokuOverlay(objectIndex, 180);
                }
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Indicator overlays failed: {0}", ex.Message);
            }

            return objectIndex;
        }

        private int DrawIndicatorSeriesLine(int objectIndex, string prefix, Func<int, double> valueSelector, Color color, int thickness, string lineStyle, int lookbackBars, string labelText = null, int labelFontSize = 9, int labelSlot = 0)
        {
            if (Chart == null || Bars == null || valueSelector == null || Bars.Count < 2)
                return objectIndex;

            var start = Math.Max(1, Bars.Count - Math.Max(lookbackBars, 10));
            var lastValidIndex = -1;
            var lastValidValue = double.NaN;
            var lastIndex = Bars.Count - 1;
            var indexSpan = Math.Max(1, lastIndex - start);
            var sampleStep = Math.Max(1, (int)Math.Ceiling(indexSpan / (double)MaxIndicatorSegmentsPerSeries));
            var previousIndex = start;
            var previousValue = valueSelector(previousIndex);
            for (var i = Math.Min(lastIndex, start + sampleStep); i <= lastIndex; i = Math.Min(lastIndex, i + sampleStep))
            {
                if (ChartObjectsOverBudget())
                    break;

                var currentValue = valueSelector(i);
                if (!IsFiniteNumber(previousValue) || !IsFiniteNumber(currentValue))
                {
                    previousIndex = i;
                    previousValue = currentValue;
                    if (i == lastIndex)
                        break;
                    continue;
                }

                var line = Chart.DrawTrendLine(
                    prefix + objectIndex.ToString(CultureInfo.InvariantCulture),
                    Bars.OpenTimes[previousIndex],
                    previousValue,
                    Bars.OpenTimes[i],
                    currentValue,
                    WithAlpha(color, 180));
                TrySetPropertyValue(line, "Thickness", 1);
                TrySetEnumPropertyValue(line, "LineStyle", lineStyle);
                TrySetPropertyValue(line, "ZIndex", 2);
                lastValidIndex = i;
                lastValidValue = currentValue;
                objectIndex++;
                previousIndex = i;
                previousValue = currentValue;
                if (i == lastIndex)
                    break;
            }

            if (!string.IsNullOrWhiteSpace(labelText) && lastValidIndex >= start && IsFiniteNumber(lastValidValue))
            {
                var labelTime = GetRightEdgeLabelColumnTime(null);
                var recentHigh = Bars.HighPrices.Skip(start).Take(Bars.Count - start).DefaultIfEmpty(lastValidValue).Max();
                var recentLow = Bars.LowPrices.Skip(start).Take(Bars.Count - start).DefaultIfEmpty(lastValidValue).Min();
                var recentRange = Math.Max(0.0, recentHigh - recentLow);
                var verticalStep = Math.Max(Symbol != null ? Symbol.PipSize * 30.0 : 0.0, recentRange * 0.035);
                var familyOffset = verticalStep * labelSlot;
                var displayLabel = BuildIndicatorValueLabel(labelText, lastValidValue);

                var label = Chart.DrawText(
                    prefix + "LBL_MAIN",
                    " " + displayLabel,
                    labelTime,
                    lastValidValue + familyOffset,
                    color);
                TryStyleChartText(label, labelFontSize, "Courier New", true);
                TrySetPropertyValue(label, "ZIndex", 3);
            }

            return objectIndex;
        }

        private int RenderIchimokuOverlay(int objectIndex, int lookbackBars)
        {
            if (Chart == null || Bars == null || Bars.Count < Math.Max(lookbackBars / 2, _resolvedIchimokuOverlayConfig.SpanBPeriod + 2))
                return objectIndex;

            var requestedStart = Math.Max(1, Bars.Count - Math.Max(lookbackBars, _resolvedIchimokuOverlayConfig.SpanBPeriod + 20));
            var start = Math.Max(requestedStart, Bars.Count - MaxIndicatorSegmentsPerSeries - 1);
            var bullishCloudColor = Color.FromArgb(255, 34, 197, 94);
            var bearishCloudColor = Color.FromArgb(255, 239, 68, 68);
            var lineColor = Color.FromArgb(255, 125, 211, 252);
            var baseColor = Color.FromArgb(255, 96, 165, 250);

            for (var i = start; i < Bars.Count; i++)
            {
                if (ChartObjectsOverBudget())
                    break;

                var conversion = ComputeIchimokuConversionLine(Bars, i, _resolvedIchimokuOverlayConfig);
                var baseLine = ComputeIchimokuBaseLine(Bars, i, _resolvedIchimokuOverlayConfig);
                var spanA = ComputeIchimokuSpanA(Bars, i, _resolvedIchimokuOverlayConfig);
                var spanB = ComputeIchimokuSpanB(Bars, i, _resolvedIchimokuOverlayConfig);

                if (i > start)
                {
                    var prevConversion = ComputeIchimokuConversionLine(Bars, i - 1, _resolvedIchimokuOverlayConfig);
                    var prevBaseLine = ComputeIchimokuBaseLine(Bars, i - 1, _resolvedIchimokuOverlayConfig);
                    var prevSpanA = ComputeIchimokuSpanA(Bars, i - 1, _resolvedIchimokuOverlayConfig);
                    var prevSpanB = ComputeIchimokuSpanB(Bars, i - 1, _resolvedIchimokuOverlayConfig);

                    if (IsFiniteNumber(prevConversion) && IsFiniteNumber(conversion))
                        objectIndex = DrawIndicatorSegment(objectIndex, "ICHI_TENKAN_", i, prevConversion, conversion, WithAlpha(lineColor, 180), 1, "Dots");

                    if (IsFiniteNumber(prevBaseLine) && IsFiniteNumber(baseLine))
                        objectIndex = DrawIndicatorSegment(objectIndex, "ICHI_KIJUN_", i, prevBaseLine, baseLine, WithAlpha(baseColor, 210), 1, "Dots");

                    if (IsFiniteNumber(prevSpanA) && IsFiniteNumber(spanA))
                        objectIndex = DrawIndicatorSegment(objectIndex, "ICHI_SPANA_", i, prevSpanA, spanA, WithAlpha(lineColor, 96), 1, "Dots");

                    if (IsFiniteNumber(prevSpanB) && IsFiniteNumber(spanB))
                        objectIndex = DrawIndicatorSegment(objectIndex, "ICHI_SPANB_", i, prevSpanB, spanB, WithAlpha(baseColor, 96), 1, "Dots");

                    if (IsFiniteNumber(prevSpanA) && IsFiniteNumber(prevSpanB) && IsFiniteNumber(spanA) && IsFiniteNumber(spanB))
                    {
                        var upper = Math.Max(Math.Max(prevSpanA, prevSpanB), Math.Max(spanA, spanB));
                        var lower = Math.Min(Math.Min(prevSpanA, prevSpanB), Math.Min(spanA, spanB));
                        var cloudColor = spanA >= spanB ? bullishCloudColor : bearishCloudColor;
                        var cloud = Chart.DrawRectangle(
                            "ICHI_CLOUD_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                            Bars.OpenTimes[i - 1],
                            upper,
                            Bars.OpenTimes[i],
                            lower,
                            WithAlpha(cloudColor, 22));
                        TrySetPropertyValue(cloud, "BorderColor", WithAlpha(cloudColor, 0));
                        TrySetPropertyValue(cloud, "ZIndex", 1);
                        objectIndex++;
                    }
                }
            }

            var kijunValue = ComputeIchimokuBaseLine(Bars, Bars.Count - 1, _resolvedIchimokuOverlayConfig);
            DrawRightEdgeIndicatorLabel("ICHI_KIJUN_", objectIndex, kijunValue, baseColor, GetIchimokuOverlayPairLabel(), 9, 2);
            return objectIndex;
        }

        private int DrawIndicatorSegment(int objectIndex, string prefix, int index, double previousValue, double currentValue, Color color, int thickness, string lineStyle)
        {
            return CTraderChartEngine.DrawIndicatorSegment(
                Chart, Bars, objectIndex, prefix, index, previousValue, currentValue,
                color, thickness, lineStyle);
        }

        private void DrawRightEdgeIndicatorLabel(string prefix, int objectIndex, double value, Color color, string labelText, int labelFontSize = 9, int labelSlot = 0)
        {
            if (Chart == null || Bars == null || Bars.Count < 2 || string.IsNullOrWhiteSpace(labelText) || !IsFiniteNumber(value))
                return;

            var labelTime = GetRightEdgeLabelColumnTime(null);
            var start = Math.Max(1, Bars.Count - 180);
            var recentHigh = Bars.HighPrices.Skip(start).Take(Bars.Count - start).DefaultIfEmpty(value).Max();
            var recentLow = Bars.LowPrices.Skip(start).Take(Bars.Count - start).DefaultIfEmpty(value).Min();
            var recentRange = Math.Max(0.0, recentHigh - recentLow);
            var verticalStep = Math.Max(Symbol != null ? Symbol.PipSize * 30.0 : 0.0, recentRange * 0.035);
            var familyOffset = verticalStep * labelSlot;
            var displayLabel = BuildIndicatorValueLabel(labelText, value);

            var label = Chart.DrawText(
                prefix + "LBL_MAIN",
                " " + displayLabel,
                labelTime,
                value + familyOffset,
                color);
            TryStyleChartText(label, labelFontSize, "Courier New", true);
            TrySetPropertyValue(label, "ZIndex", 3);
        }

        private string GetArtifactDisplayTimeFrameLabel(TimeFrame timeFrame)
        {
            var normalized = NormalizeTradeTfLabel(GetMiniChartLabel(timeFrame)).ToLowerInvariant();
            return string.IsNullOrWhiteSpace(normalized) ? "" : normalized;
        }

        private string NormalizeDisplayTimeFramePrefix(string value)
        {
            return CTraderChartEngine.NormalizeDisplayTimeFramePrefix(value);
        }

        private string NormalizeArtifactDisplayLabel(string labelText, TimeFrame sourceTimeFrame = null)
        {
            var tfLabel = sourceTimeFrame != null ? GetArtifactDisplayTimeFrameLabel(sourceTimeFrame) : "";
            return CTraderChartEngine.NormalizeArtifactDisplayLabel(labelText, tfLabel);
        }

        private DateTime GetRightEdgeLabelColumnTime(TimeFrame sourceTimeFrame)
        {
            var chartTimeFrame = Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
            var chartTfMinutes = Math.Max(1, TimeFrameToMinutes(chartTimeFrame));
            var sourceTfMinutes = sourceTimeFrame != null ? TimeFrameToMinutes(sourceTimeFrame) : chartTfMinutes;
            var isHigherTimeFrame = sourceTfMinutes > chartTfMinutes;
            var columnBars = isHigherTimeFrame ? HtfLabelColumnBars : CurrentTfLabelColumnBars;
            return GetCurrentChartEndTime().AddMinutes(chartTfMinutes * columnBars);
        }

        private void DrawRightEdgeZoneLabel(string prefix, int objectIndex, double value, Color color, string labelText, int labelFontSize = 9, TimeFrame sourceTimeFrame = null)
        {
            labelText = NormalizeArtifactDisplayLabel(labelText, sourceTimeFrame);
            if (Chart == null || Bars == null || Bars.Count < 2 || string.IsNullOrWhiteSpace(labelText) || !IsFiniteNumber(value))
                return;

            var labelTime = GetRightEdgeLabelColumnTime(sourceTimeFrame);
            // cTrader anchors DrawText text vertically centered on (time, y), so the text's fixed
            // pixel height reads as a different price distance at every zoom level and the label
            // appears to drift away from the level line. Anchor half a text-height BELOW the level
            // price instead: the text then hangs from the line and stays attached at any price scale.
            var labelY = value + ResolveChartTextHalfHeightPriceOffset(labelFontSize);
            var label = Chart.DrawText(
                prefix + "_TXT_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                " " + labelText.Trim(),
                labelTime,
                labelY,
                color);
            TryStyleChartText(label, labelFontSize, "Courier New", true);
            TrySetPropertyValue(label, "ZIndex", 4);
        }

        private void DrawArtifactZoneLabel(string prefix, int objectIndex, double value, Color color, string labelText, DateTime artifactEndTime, DateTime chartEndTime, int labelFontSize = 9, TimeFrame sourceTimeFrame = null)
        {
            if (artifactEndTime >= chartEndTime)
            {
                DrawRightEdgeZoneLabel(prefix, objectIndex, value, color, labelText, labelFontSize, sourceTimeFrame);
                return;
            }

            labelText = NormalizeArtifactDisplayLabel(labelText, sourceTimeFrame);
            if (Chart == null || string.IsNullOrWhiteSpace(labelText) || !IsFiniteNumber(value) || artifactEndTime == DateTime.MinValue)
                return;

            var label = Chart.DrawText(
                prefix + "_TXT_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                " " + labelText.Trim(),
                artifactEndTime,
                value + ResolveChartTextHalfHeightPriceOffset(labelFontSize),
                color);
            TryStyleChartText(label, labelFontSize, "Courier New", true);
            TrySetPropertyValue(label, "ZIndex", 4);
        }

        // Converts half the text's pixel height into price units using the chart's current visible
        // price scale, so text stays glued to its anchor line under zoom in/out. Returns 0 when the
        // chart does not expose the scale (falls back to anchoring exactly on the level price).
        private double ResolveChartTextHalfHeightPriceOffset(int labelFontSize)
        {
            try
            {
                if (Chart == null) return 0.0;
                var heightObj = TryGetPropertyValue(Chart, "Height");
                var topYObj = TryGetPropertyValue(Chart, "TopY");
                var bottomYObj = TryGetPropertyValue(Chart, "BottomY");
                if (heightObj == null || topYObj == null || bottomYObj == null)
                {
                    if (!_chartScaleDiagLogged)
                    {
                        _chartScaleDiagLogged = true;
                        SafePrint("[Visuals] Chart scale unavailable Height={0} TopY={1} BottomY={2} -> label offset fallback 0", heightObj ?? "<null>", topYObj ?? "<null>", bottomYObj ?? "<null>");
                    }
                    return 0.0;
                }
                var height = Convert.ToDouble(heightObj, CultureInfo.InvariantCulture);
                var topY = Convert.ToDouble(topYObj, CultureInfo.InvariantCulture);
                var bottomY = Convert.ToDouble(bottomYObj, CultureInfo.InvariantCulture);
                if (height <= 0 || !(topY > bottomY))
                {
                    if (!_chartScaleDiagLogged)
                    {
                        _chartScaleDiagLogged = true;
                        SafePrint("[Visuals] Chart scale invalid Height={0} TopY={1} BottomY={2}", height, topY, bottomY);
                    }
                    return 0.0;
                }
                var pricePerPixel = (topY - bottomY) / height;
                var halfTextHeightPx = Math.Max(4.0, labelFontSize * 0.7);
                var offset = halfTextHeightPx * pricePerPixel;
                if (!_chartScaleDiagLogged)
                {
                    _chartScaleDiagLogged = true;
                    SafePrint("[Visuals] Chart scale OK Height={0:F1}px TopY={1} BottomY={2} -> pricePerPixel={3:G6} labelOffset={4:G6}", height, topY, bottomY, pricePerPixel, offset);
                }
                return offset;
            }
            catch
            {
                return 0.0;
            }
        }

        private string BuildIndicatorValueLabel(string labelText, double value)
        {
            var cleanLabel = string.IsNullOrWhiteSpace(labelText) ? "" : labelText.Trim();
            return cleanLabel;
        }

        private string FormatIndicatorPriceLabelValue(double value)
        {
            if (!IsFiniteNumber(value))
                return "";

            var digits = Symbol != null ? Math.Max(0, Symbol.Digits) : 5;
            return Math.Round(value, digits).ToString("F" + digits.ToString(CultureInfo.InvariantCulture), CultureInfo.InvariantCulture);
        }

        private void CollectRecentDirectionalPatternMarkers(
            List<DirectionalPatternMarkerAggregate> aggregates,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            string shortLabel,
            Func<Bars, int, bool> bullishMatch,
            Func<Bars, int, bool> bearishMatch,
            int slotIndex)
        {
            if (aggregates == null || sourceBars == null || Symbol == null || bullishMatch == null || bearishMatch == null)
                return;

            var drawn = 0;
            var maxMarkers = GetCollectorMarkerLimit();
            var startIndex = ResolveWorkingStartIndex(sourceBars, 2, 2, sourceTimeFrame);
            for (var barIndex = sourceBars.Count - 2; barIndex >= startIndex; barIndex--)
            {
                if (!HasEventVolumeSurge(sourceBars, barIndex))
                    continue;

                if (bullishMatch(sourceBars, barIndex))
                {
                    AddDirectionalPatternAggregate(aggregates, sourceBars, sourceTimeFrame, barIndex, true, slotIndex, shortLabel);
                    drawn++;
                }

                if (drawn >= maxMarkers)
                    break;

                if (bearishMatch(sourceBars, barIndex))
                {
                    AddDirectionalPatternAggregate(aggregates, sourceBars, sourceTimeFrame, barIndex, false, slotIndex, shortLabel);
                    drawn++;
                }

                if (drawn >= maxMarkers)
                    break;
            }
        }

        private void AddDirectionalPatternAggregate(
            List<DirectionalPatternMarkerAggregate> aggregates,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int barIndex,
            bool isBullish,
            int slotIndex,
            string shortLabel,
            int patternSpan = 1,
            bool highlightPatternRange = false,
            int patternBarIndex = -1,
            List<CandleConfluenceMatch> confluenceMatches = null,
            bool isNeutral = false)
        {
            if (aggregates == null || sourceBars == null || string.IsNullOrWhiteSpace(shortLabel))
                return;

            // Collapse ALL markers on the same bar + direction into ONE aggregate, so only a
            // single surrounding box / icon / label is drawn per bar (the label shows how
            // many patterns were merged). This avoids overlapping boxes when several candle
            // patterns fire on the same bar.
            var existing = aggregates.FirstOrDefault(item =>
                item.SourceTimeFrame == sourceTimeFrame &&
                item.BarIndex == barIndex &&
                item.IsNeutral == isNeutral &&
                item.IsBullish == isBullish);

            if (existing == null)
            {
                existing = new DirectionalPatternMarkerAggregate
                {
                    SourceBars = sourceBars,
                    SourceTimeFrame = sourceTimeFrame,
                    BarIndex = barIndex,
                    PatternBarIndex = patternBarIndex >= 0 ? patternBarIndex : barIndex,
                    IsBullish = isBullish,
                    IsNeutral = isNeutral,
                    SlotIndex = slotIndex,
                    PatternSpan = Math.Max(1, patternSpan),
                    HighlightPatternRange = highlightPatternRange
                };
                aggregates.Add(existing);
            }

            existing.SlotIndex = Math.Min(existing.SlotIndex, slotIndex);
            existing.PatternSpan = Math.Max(existing.PatternSpan, Math.Max(1, patternSpan));
            existing.HighlightPatternRange = existing.HighlightPatternRange || highlightPatternRange;
            if (patternBarIndex >= 0)
                existing.PatternBarIndex = patternBarIndex;
            if (!existing.Labels.Contains(shortLabel, StringComparer.OrdinalIgnoreCase))
                existing.Labels.Add(shortLabel);
            if (confluenceMatches != null)
            {
                foreach (var match in confluenceMatches)
                {
                    if (match == null)
                        continue;
                    if (!existing.ConfluenceMatches.Any(item =>
                        item != null &&
                        string.Equals(item.Kind, match.Kind, StringComparison.OrdinalIgnoreCase) &&
                        item.SourceTimeFrame == match.SourceTimeFrame &&
                        Math.Abs(item.Low - match.Low) <= 0.0000001 &&
                        Math.Abs(item.High - match.High) <= 0.0000001))
                        existing.ConfluenceMatches.Add(match);
                }
            }
        }

        // Collapse many same-bar markers into "major + extras" (e.g. "ema.x +6").
        private string FormatAggregatedMarkerLabel(List<string> labels)
        {
            if (labels == null || labels.Count == 0)
                return "";
            if (labels.Count == 1)
                return FormatEventLabelForDisplay(labels[0]);

            var representative = labels
                .Select((label, index) => new { Label = label, Index = index, Score = GetEventLabelPriorityScore(label) })
                .OrderByDescending(item => item.Score)
                .ThenBy(item => item.Index)
                .First();
            return FormatEventLabelForDisplay(representative.Label) + " +" + (labels.Count - 1).ToString(CultureInfo.InvariantCulture);
        }

        private string FormatAggregatedCanonicalEventName(TimeFrame timeFrame, List<string> labels, bool isBullish)
        {
            if (labels == null || labels.Count == 0)
                return BuildCanonicalEventName(timeFrame, "event", isBullish);
            var representative = labels
                .Select((label, index) => new { Label = label, Index = index, Score = GetEventLabelPriorityScore(label) })
                .OrderByDescending(item => item.Score)
                .ThenBy(item => item.Index)
                .First();
            return BuildCanonicalEventName(timeFrame, representative.Label, isBullish) +
                (labels.Count > 1 ? " +" + (labels.Count - 1).ToString(CultureInfo.InvariantCulture) : "");
        }

        private string FormatCandleMarkerCanonicalEventName(DirectionalPatternMarkerAggregate marker)
        {
            if (marker == null)
                return "event.?";
            if (marker.IsNeutral)
            {
                var neutralRepresentative = marker.Labels
                    .Select((label, index) => new { Label = label, Index = index, Score = GetEventLabelPriorityScore(label) })
                    .OrderByDescending(item => item.Score)
                    .ThenBy(item => item.Index)
                    .FirstOrDefault();
                var neutralPattern = GetCanonicalCandlePatternOperand(neutralRepresentative != null ? neutralRepresentative.Label : "event");
                var neutralCount = marker.Labels.Count > 1 ? " +" + (marker.Labels.Count - 1).ToString(CultureInfo.InvariantCulture) : "";
                return GetMiniChartLabel(marker.SourceTimeFrame) + "." + neutralPattern + "." + neutralCount;
            }

            var representative = marker.Labels
                .Select((label, index) => new { Label = label, Index = index, Score = GetEventLabelPriorityScore(label) })
                .OrderByDescending(item => item.Score)
                .ThenBy(item => item.Index)
                .FirstOrDefault();
            var label = representative != null ? representative.Label ?? "" : "";
            var canonicalName = FormatCanonicalCandlePatternEventName(
                marker.SourceTimeFrame,
                label,
                marker.IsBullish,
                marker.ConfluenceMatches);
            return canonicalName + (marker.Labels.Count > 1 ? " +" + (marker.Labels.Count - 1).ToString(CultureInfo.InvariantCulture) : "");
        }

        // Keep broker comments, logs, and candle marker labels canonical. Candle labels need
        // the full chain (for example "m1.pin↑.r.h1.p.h") so the trigger and reacted level are
        // visible together.
        private string FormatCandleMarkerChartLabel(DirectionalPatternMarkerAggregate marker)
        {
            return FormatCandleMarkerCanonicalEventName(marker);
        }

        private string FormatCanonicalCandlePatternEventName(
            TimeFrame timeFrame,
            string label,
            bool isBullish,
            IEnumerable<CandleConfluenceMatch> confluenceMatches)
        {
            var fallback = BuildCanonicalEventName(timeFrame, label, isBullish);
            var match = (confluenceMatches ?? Enumerable.Empty<CandleConfluenceMatch>())
                .FirstOrDefault(item => item != null && IsValidCandleConfluenceTimeFrame(timeFrame, item.SourceTimeFrame));
            if (match == null)
                return fallback;

            var pattern = GetCanonicalCandlePatternOperand(label);
            var target = GetCanonicalLevelOperand(match.Kind);
            var targetTimeFrame = GetArtifactDisplayTimeFrameLabel(match.SourceTimeFrame);
            var targetLabel = string.IsNullOrWhiteSpace(targetTimeFrame)
                ? target
                : targetTimeFrame + "." + target;
            return GetMiniChartLabel(timeFrame) + "." + pattern + (isBullish ? "↑" : "↓") + ".r." + targetLabel;
        }

        private string GetCanonicalCandlePatternOperand(string label)
        {
            switch (NormalizeEventLabelPriorityKey(label))
            {
                case "MOR": return "mor";
                case "EVE": return "eve";
                case "3WS":
                case "TWS": return "tws";
                case "3BC":
                case "TBC": return "tbc";
                case "ENG": return "eng";
                case "DCC": return "dcc";
                case "PRC": return "prc";
                case "PIN": return "pin";
                case "HAM": return "ham";
                case "SST": return "sst";
                case "IHM": return "ihm";
                case "HGM": return "hgm";
                case "BIG": return "big";
                case "HAR": return "har";
                default:
                    return FormatEventLabelForDisplay(label)
                        .Replace(".c", "")
                        .Replace(".r", "")
                        .Replace(".", "")
                        .Replace(" ", "")
                        .ToLowerInvariant();
            }
        }

        private string GetCanonicalLevelOperand(string kind)
        {
            switch ((kind ?? "").Trim().ToUpperInvariant())
            {
                case "SUPPLY": return "sply";
                case "DEMAND": return "dem";
                case "KEY HIGH":
                case "BAR HIGH":
                    return "p.h";
                case "KEY LOW":
                case "BAR LOW":
                    return "p.l";
                case "RANGE HIGH":
                case "RESISTANCE":
                    return "rng.h";
                case "RANGE LOW":
                case "SUPPORT":
                    return "rng.l";
                case "SWING HIGH":
                    return "sw.h";
                case "SWING LOW":
                    return "sw.l";
                case "SWING": return "sw";
                case "EQH": return "eqh";
                case "EQL": return "eql";
                case "OB": return "ob";
                case "FVG": return "fvg";
                default: return "lvl";
            }
        }

        private string FormatEventLabelForDisplay(string label)
        {
            if (string.IsNullOrWhiteSpace(label))
                return "";

            var trimmed = label.Trim();
            var suffix = "";
            if (trimmed.EndsWith(".c", StringComparison.OrdinalIgnoreCase) || trimmed.EndsWith("_c", StringComparison.OrdinalIgnoreCase))
            {
                suffix = ".c";
                trimmed = trimmed.Substring(0, trimmed.Length - 2);
            }
            else if (trimmed.EndsWith(".r", StringComparison.OrdinalIgnoreCase) || trimmed.EndsWith("_r", StringComparison.OrdinalIgnoreCase))
            {
                suffix = ".r";
                trimmed = trimmed.Substring(0, trimmed.Length - 2);
            }

            var key = NormalizeEventLabelPriorityKey(trimmed);
            string display;
            switch (key)
            {
                case "CHOCH": display = "choch"; break;
                case "BOS": display = "bos"; break;
                case "SR":
                case "SWP":
                case "SWEEP": display = "swp"; break;
                case "BR": display = "br"; break;
                case "RJ": display = "rj"; break;
                case "RJTL": display = "rj.tl"; break;
                case "RJOB": display = "rj.ob"; break;
                case "RJFVG": display = "rj.fvg"; break;
                case "RJSD": display = "rj.sd"; break;
                case "BRTL": display = "br.tl"; break;
                case "BROB": display = "br.ob"; break;
                case "BRFVG": display = "br.fvg"; break;
                case "BRSD": display = "br.sd"; break;
                case "IM": display = "mom"; break;
                case "PB": display = "pb.ema"; break;
                case "CT": display = "ct.vwap"; break;
                case "DIV": display = "div.rsi"; break;

                case "MOR": display = "mor"; break;
                case "EVE": display = "eve"; break;
                case "3WS":
                case "TWS": display = "tws"; break;
                case "3BC":
                case "TBC": display = "tbc"; break;
                case "ENG": display = "eng"; break;
                case "DCC": display = "dcc"; break;
                case "PRC": display = "prc"; break;
                case "PIN": display = "pin"; break;
                case "HAM": display = "ham"; break;
                case "SST": display = "sst"; break;
                case "IHM": display = "ihm"; break;
                case "HGM": display = "hgm"; break;
                case "BIG": display = "big"; break;
                case "HAR": display = "har"; break;

                case "PXE": display = "x>ema" + Math.Max(1, _resolvedEmaEventConfig.PriceCrossPeriod); break;
                case "EMX": display = "ema" + Math.Max(1, _resolvedEmaEventConfig.FastPeriod) + ".x>ema" + Math.Max(1, _resolvedEmaEventConfig.MidPeriod); break;
                case "EMT": display = "ema" + Math.Max(1, _resolvedEmaEventConfig.MidPeriod) + ".x>ema" + Math.Max(1, _resolvedEmaEventConfig.SlowPeriod); break;
                case "VWX": display = "x>vwap"; break;
                case "VWR": display = "vwap.r"; break;
                case "BBX": display = "x>bbm"; break;
                case "BBR": display = "bb.r"; break;
                case "R50": display = "rsi" + Math.Max(1, _resolvedRsiEventConfig.Period) + ".x>50"; break;
                case "ROS": display = "rsi" + Math.Max(1, _resolvedRsiEventConfig.Period) + ".x>" + Math.Round(_resolvedRsiEventConfig.Oversold).ToString(CultureInfo.InvariantCulture); break;
                case "ROB": display = "rsi" + Math.Max(1, _resolvedRsiEventConfig.Period) + ".x<" + Math.Round(_resolvedRsiEventConfig.Overbought).ToString(CultureInfo.InvariantCulture); break;
                case "STX": display = "stochk" + Math.Max(1, _resolvedStochasticEventConfig.KPeriod) + ".x>stochd" + Math.Max(1, _resolvedStochasticEventConfig.DPeriod); break;
                case "STO": display = "stoch" + Math.Max(1, _resolvedStochasticEventConfig.KPeriod) + ".x>ext"; break;
                case "MDX": display = "macd.x>sig"; break;
                case "MD0": display = "macd.x>0"; break;
                default: display = trimmed.ToLowerInvariant(); break;
            }

            if (!string.IsNullOrEmpty(suffix) && display.EndsWith(suffix, StringComparison.OrdinalIgnoreCase))
                return display;

            return display + suffix;
        }

        private string BuildCanonicalEventName(TimeFrame timeFrame, string rawLabel, bool isBullish)
        {
            var tf = GetMiniChartLabel(timeFrame);
            if (string.IsNullOrWhiteSpace(rawLabel))
                return tf + (isBullish ? "↑" : "↓");

            var parts = rawLabel
                .Split(new[] { '+' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(value => BuildCanonicalEventNamePart(tf, value, isBullish))
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            return parts.Count > 0 ? string.Join("+", parts) : tf + (isBullish ? "↑" : "↓");
        }

        private string CompactCanonicalPriceOperand(string tf, string value)
        {
            var compact = (value ?? "").Trim().ToLowerInvariant();
            var pricePrefix = tf.ToLowerInvariant() + ".p.";
            if (compact.StartsWith(pricePrefix, StringComparison.Ordinal))
                compact = tf.ToLowerInvariant() + "." + compact.Substring(pricePrefix.Length);
            compact = compact.Replace(".x>.", ".x>").Replace(".x<.", ".x<");
            if (compact == tf.ToLowerInvariant() + ".event↑" || compact == tf.ToLowerInvariant() + ".p↑")
                return tf.ToLowerInvariant() + "↑";
            if (compact == tf.ToLowerInvariant() + ".event↓" || compact == tf.ToLowerInvariant() + ".p↓")
                return tf.ToLowerInvariant() + "↓";
            return compact;
        }

        private string BuildCanonicalEventNamePart(string tf, string rawLabel, bool isBullish)
        {
            var raw = string.IsNullOrWhiteSpace(rawLabel) ? "event" : rawLabel.Trim();
            if (raw.StartsWith(tf + ".", StringComparison.OrdinalIgnoreCase))
                return CompactCanonicalPriceOperand(tf, raw);

            var followUp = "";
            if (raw.EndsWith(".c", StringComparison.OrdinalIgnoreCase) || raw.EndsWith("_c", StringComparison.OrdinalIgnoreCase))
            {
                followUp = ".c";
                raw = raw.Substring(0, raw.Length - 2);
            }
            else if (raw.EndsWith(".r", StringComparison.OrdinalIgnoreCase) || raw.EndsWith("_r", StringComparison.OrdinalIgnoreCase))
            {
                followUp = ".r";
                raw = raw.Substring(0, raw.Length - 2);
            }

            var key = NormalizeEventLabelPriorityKey(raw);
            var cross = isBullish ? "x>" : "x<";
            var arrow = isBullish ? "↑" : "↓";
            var ema = _resolvedEmaEventConfig;
            var rsi = _resolvedRsiEventConfig;
            var stoch = _resolvedStochasticEventConfig;
            string expression;
            switch (key)
            {
                case "PXE": expression = cross + "ema" + Math.Max(1, ema.PriceCrossPeriod); break;
                case "EMX": expression = "ema" + Math.Max(1, ema.FastPeriod) + "." + cross + "ema" + Math.Max(1, ema.MidPeriod); break;
                case "EMT": expression = "ema" + Math.Max(1, ema.MidPeriod) + "." + cross + "ema" + Math.Max(1, ema.SlowPeriod); break;
                case "VWX": expression = cross + "vwap"; break;
                case "VWR": expression = "vwap.r" + arrow; break;
                case "BBX": expression = cross + "bbm"; break;
                case "BBR": expression = "bb.r" + arrow; break;
                case "R50": expression = "rsi" + Math.Max(1, rsi.Period) + "." + cross + "50"; break;
                case "ROS": expression = "rsi" + Math.Max(1, rsi.Period) + ".x>" + Math.Round(rsi.Oversold).ToString(CultureInfo.InvariantCulture); break;
                case "ROB": expression = "rsi" + Math.Max(1, rsi.Period) + ".x<" + Math.Round(rsi.Overbought).ToString(CultureInfo.InvariantCulture); break;
                case "STX": expression = "stochk" + Math.Max(1, stoch.KPeriod) + "." + cross + "stochd" + Math.Max(1, stoch.DPeriod); break;
                case "STO": expression = "stoch" + Math.Max(1, stoch.KPeriod) + "." + cross + (isBullish ? stoch.OversoldLevel : stoch.OverboughtLevel).ToString(CultureInfo.InvariantCulture); break;
                case "MDX": expression = "macd." + cross + "sig"; break;
                case "MD0": expression = "macd." + cross + "0"; break;
                case "CHOCH": expression = "choch" + arrow; break;
                case "BOS": expression = "bos" + arrow; break;
                case "SR":
                case "SWP":
                case "SWEEP": expression = "swp" + arrow; break;
                case "RJ": expression = "rj" + arrow; break;
                case "BR": expression = "br" + arrow; break;
                case "RJTL": expression = "rj.tl" + arrow; break;
                case "RJOB": expression = "rj.ob" + arrow; break;
                case "RJFVG": expression = "rj.fvg" + arrow; break;
                case "RJSD": expression = "rj.sd" + arrow; break;
                case "BRTL": expression = "br.tl" + arrow; break;
                case "BROB": expression = "br.ob" + arrow; break;
                case "BRFVG": expression = "br.fvg" + arrow; break;
                case "BRSD": expression = "br.sd" + arrow; break;
                case "PB": expression = "pb.ema" + arrow; break;
                case "CT": expression = "ct.vwap" + arrow; break;
                case "IM": expression = "mom" + arrow; break;
                case "DIV": expression = "div.rsi" + Math.Max(1, rsi.Period) + arrow; break;
                case "FVG": expression = "fvg.r" + arrow; break;
                case "OB": expression = "ob.r" + arrow; break;
                case "MOR": expression = "mor" + arrow; break;
                case "EVE": expression = "eve" + arrow; break;
                case "3WS":
                case "TWS": expression = "tws" + arrow; break;
                case "3BC":
                case "TBC": expression = "tbc" + arrow; break;
                case "ENG": expression = "eng" + arrow; break;
                case "DCC": expression = "dcc" + arrow; break;
                case "PRC": expression = "prc" + arrow; break;
                case "PIN": expression = "pin" + arrow; break;
                case "HAM": expression = "ham" + arrow; break;
                case "SST": expression = "sst" + arrow; break;
                case "IHM": expression = "ihm" + arrow; break;
                case "HGM": expression = "hgm" + arrow; break;
                case "BIG": expression = "big" + arrow; break;
                case "HAR": expression = "har" + arrow; break;
                default:
                    expression = string.Equals(raw, "event", StringComparison.OrdinalIgnoreCase)
                        ? arrow
                        : raw.Trim().ToLowerInvariant().Replace(' ', '.') + arrow;
                    break;
            }
            return tf + (expression == arrow ? "" : ".") + expression + followUp;
        }

        private string BuildCanonicalMarketEventName(CanonicalMarketEvent evt, string followUpSuffix = "")
        {
            var raw = GetCanonicalEventTypeShortLabel(evt.EventType) + (followUpSuffix ?? "");
            var name = BuildCanonicalEventName(evt.SourceTimeFrame, raw, evt.IsBullish);
            if ((evt.EventType == CanonicalEventType.Rejection || evt.EventType == CanonicalEventType.Breakout) &&
                !string.IsNullOrWhiteSpace(evt.LevelKind))
            {
                var operand = evt.LevelKind.Trim().ToLowerInvariant();
                name = evt.EventType == CanonicalEventType.Rejection
                    ? name.Replace(".rj", ".rj." + operand)
                    : name.Replace(".br", ".br." + operand);
            }
            else if (evt.EventType == CanonicalEventType.Rejection && evt.ZoneHigh > evt.ZoneLow && evt.ZoneLow > 0)
                name = name.Replace(".rj", ".rj.zone");
            return name;
        }

        // Chart-display only variant: drop the "tf." prefix when the event belongs to the
        // current chart timeframe (e.g. "h1.choch↓" -> "choch↓"). HTF events shown on an LTF
        // chart keep their prefix. Event ids, in-memory state, files and trade comments are
        // untouched and keep the original prefixed label.
        private string BuildChartEventDisplayLabel(TimeFrame sourceTimeFrame, string rawLabel, bool isBullish)
        {
            var name = BuildCanonicalEventName(sourceTimeFrame, rawLabel, isBullish);
            return StripChartEventTfPrefix(name, sourceTimeFrame);
        }

        private string BuildChartEventDisplayLabel(CanonicalMarketEvent evt, string followUpSuffix = "")
        {
            var name = BuildCanonicalMarketEventName(evt, followUpSuffix);
            return StripChartEventTfPrefix(name, evt.SourceTimeFrame);
        }

        private string StripChartEventTfPrefix(string name, TimeFrame sourceTimeFrame)
        {
            if (Chart == null || string.IsNullOrEmpty(name))
                return name;
            if (sourceTimeFrame != Chart.TimeFrame)
                return name;

            var tfPrefix = GetMiniChartLabel(sourceTimeFrame);
            if (string.IsNullOrEmpty(tfPrefix))
                return name;

            var parts = name.Split(new[] { '+' }, StringSplitOptions.RemoveEmptyEntries);
            var stripped = parts
                .Select(part =>
                {
                    if (part.StartsWith(tfPrefix + ".", StringComparison.OrdinalIgnoreCase))
                        return part.Substring(tfPrefix.Length + 1);
                    // Bare "h1↑"/"h1↓" (no trailing dot) collapses to the arrow only.
                    if (part.Length == tfPrefix.Length + 1 &&
                        part.StartsWith(tfPrefix, StringComparison.OrdinalIgnoreCase) &&
                        (part.EndsWith("↑", StringComparison.Ordinal) || part.EndsWith("↓", StringComparison.Ordinal)))
                        return part.Substring(tfPrefix.Length);
                    return part;
                })
                .ToList();
            return string.Join("+", stripped);
        }

        private int GetEventLabelPriorityScore(string label)
        {
            return CTraderChartEngine.GetEventLabelPriorityScore(label);
        }

        private string NormalizeEventLabelPriorityKey(string label)
        {
