        private List<StructureEvent> CollectStructureEvents()
        {
            return CollectStructureEvents(Bars, Chart != null ? Chart.TimeFrame : TimeFrame.Minute, 180);
        }

        private List<StructureEvent> CollectStructureEvents(Bars sourceBars, TimeFrame sourceTimeFrame, int lookbackBars, int endIndex = -1)
        {
            var events = new List<StructureEvent>();
            if (sourceBars == null)
                return events;

            var structureEvents = BuildStructureSnapshotV2(sourceBars, lookbackBars, endIndex).Events;
            foreach (var value in structureEvents)
            {
                if (value.Type == StructureEventTypeV2.Sweep)
                    continue;
                if (!HasEventVolumeSurge(sourceBars, value.ConfirmationBarIndex))
                    continue;

                var isChoch = value.Type == StructureEventTypeV2.Choch;
                events.Add(new StructureEvent
                {
                    Label = isChoch ? "CHOCH" : "BOS",
                    BarIndex = value.ConfirmationBarIndex,
                    Time = sourceBars.OpenTimes[value.ConfirmationBarIndex],
                    Price = value.ReferencePrice,
                    IsBullish = value.IsBullish,
                    IsChoch = isChoch,
                    SourceTimeFrame = sourceTimeFrame
                });
            }

            return events.OrderBy(value => value.BarIndex).ToList();
        }

        private bool TryMatchSweepPattern(int reclaimBarIndex, SweepCandidate candidate, out SweepMatch match)
        {
            match = new SweepMatch
            {
                IsValid = false,
                SweepBarIndex = -1,
                ReclaimBarIndex = -1
            };

            if (Bars == null || reclaimBarIndex < 1 || reclaimBarIndex >= Bars.Count)
                return false;

            var sweepBarIndex = reclaimBarIndex - 1;
            var pipSize = Symbol != null && Symbol.PipSize > 0 ? Symbol.PipSize : 0.0000001;
            var result = _structureEngine.MatchSweepPattern(
                reclaimBarIndex,
                Bars.OpenPrices[reclaimBarIndex],
                Bars.HighPrices[reclaimBarIndex],
                Bars.LowPrices[reclaimBarIndex],
                Bars.ClosePrices[reclaimBarIndex],
                Bars.OpenTimes[sweepBarIndex],
                Bars.HighPrices[sweepBarIndex],
                Bars.LowPrices[sweepBarIndex],
                Bars.ClosePrices[sweepBarIndex],
                candidate.Time,
                candidate.Price,
                candidate.IsHigh,
                pipSize);
            if (result.IsValid)
            {
                match = new SweepMatch
                {
                    IsValid = true,
                    SweepBarIndex = result.SweepBarIndex,
                    ReclaimBarIndex = result.ReclaimBarIndex
                };
                return true;
            }

            return false;
        }

        private bool TryGetRangeHighLow(Bars sourceBars, DateTime start, DateTime end, out double high, out double low, out DateTime highTime, out DateTime lowTime)
        {
            high = double.MinValue;
            low = double.MaxValue;
            highTime = DateTime.MinValue;
            lowTime = DateTime.MinValue;
            if (sourceBars == null || sourceBars.Count == 0)
                return false;

            for (var i = 0; i < sourceBars.Count; i++)
            {
                var openTime = sourceBars.OpenTimes[i];
                if (openTime < start || openTime >= end)
                    continue;
                if (sourceBars.HighPrices[i] > high)
                {
                    high = sourceBars.HighPrices[i];
                    highTime = openTime;
                }
                if (sourceBars.LowPrices[i] < low)
                {
                    low = sourceBars.LowPrices[i];
                    lowTime = openTime;
                }
            }

            return high > double.MinValue && low < double.MaxValue && highTime != DateTime.MinValue && lowTime != DateTime.MinValue;
        }

        private int DrawHorizontalGuide(int objectIndex, string label, DateTime startTime, double price, Color color, bool drawLabel = true, TimeFrame sourceTimeFrame = null, string lineStyle = "Solid")
        {
            if (startTime == DateTime.MinValue)
                startTime = GetCurrentChartEndTime();
            var endTime = GetCurrentChartEndTime();
            if (endTime <= startTime)
                endTime = startTime.AddMinutes(1);

            var line = Chart.DrawTrendLine("KEY_" + objectIndex.ToString(CultureInfo.InvariantCulture), startTime, price, endTime, price, color);
            TrySetPropertyValue(line, "Thickness", 1);
            TrySetEnumPropertyValue(line, "LineStyle", lineStyle);

            if (drawLabel && !string.IsNullOrWhiteSpace(label))
                DrawRightEdgeZoneLabel("KEY", objectIndex, price, color, label, GetNormalChartLabelFontSize(), sourceTimeFrame);
            objectIndex++;
            return objectIndex;
        }

        private int DrawConfiguredKillerZones(int objectIndex)
        {
            if (!ShouldShowLowerTimeframeSessionContext())
                return objectIndex;

            var today = GetReferenceNow().Date;
            var days = DefaultKillerZoneDays;
            for (var dayOffset = 0; dayOffset < days; dayOffset++)
            {
                var date = today.AddDays(-dayOffset);
                switch (DrawKillerZones)
                {
                    case KillerZoneVisualMode.No:
                        return objectIndex;
                    case KillerZoneVisualMode.Asia_KZ:
                        objectIndex = DrawSessionContextBox(objectIndex, "Asia", date, false, "Asia");
                        break;
                    case KillerZoneVisualMode.Asia_Session:
                        objectIndex = DrawSessionContextBox(objectIndex, "Asia", date, true, "Asia");
                        break;
                    case KillerZoneVisualMode.LD_KZ:
                        objectIndex = DrawSessionContextBox(objectIndex, "London", date, false, "LD");
                        break;
                    case KillerZoneVisualMode.LD_Session:
                        objectIndex = DrawSessionContextBox(objectIndex, "London", date, true, "LD");
                        break;
                    case KillerZoneVisualMode.NY_KZ:
                        objectIndex = DrawSessionContextBox(objectIndex, "NewYork", date, false, "NY");
                        break;
                    case KillerZoneVisualMode.NY_Session:
                        objectIndex = DrawSessionContextBox(objectIndex, "NewYork", date, true, "NY");
                        break;
                    case KillerZoneVisualMode.All_KZs:
                        objectIndex = DrawSessionContextBox(objectIndex, "Asia", date, false, "Asia");
                        objectIndex = DrawSessionContextBox(objectIndex, "London", date, false, "LD");
                        objectIndex = DrawSessionContextBox(objectIndex, "NewYork", date, false, "NY");
                        break;
                    case KillerZoneVisualMode.All_Sessions:
                    default:
                        objectIndex = DrawSessionContextBox(objectIndex, "Asia", date, true, "Asia");
                        objectIndex = DrawSessionContextBox(objectIndex, "London", date, true, "LD");
                        objectIndex = DrawSessionContextBox(objectIndex, "NewYork", date, true, "NY");
                        break;
                }
            }
            return objectIndex;
        }

        private int DrawSessionContextBox(int objectIndex, string sessionName, DateTime date, bool useFullSession, string displayLabel)
        {
            DateTime startUtc;
            DateTime endUtc;
            if (!TryGetContextUtcRange(sessionName, date, useFullSession, out startUtc, out endUtc))
                return objectIndex;

            double high;
            double low;
            DateTime highTime;
            DateTime lowTime;
            if (!TryGetRangeHighLow(Bars, startUtc, endUtc, out high, out low, out highTime, out lowTime))
            {
                // Session window has no bars yet (future session today): still draw the box so
                // the whole day's sessions are visible ahead of time. Anchor it to the last price.
                if (Bars == null || Bars.Count == 0)
                    return objectIndex;
                var lastIndex = Bars.Count - 1;
                var anchor = Bars.ClosePrices[lastIndex];
                var buffer = Math.Max(Symbol.PipSize * 20.0, Math.Abs(anchor) * 0.0005);
                high = anchor + buffer;
                low = anchor - buffer;
            }
            if (high <= low)
                return objectIndex;

            // Session and KZ ranges use their session accent (Asia cyan, London green,
            // New York amber) at a readable opacity. The old 100/255 alpha made even a
            // completed range look blurred against a dark chart.
            var kzColor = GetSessionAccentColor(sessionName);
            var nowUtc = NormalizeBotTimeToUtc(Server.Time);
            var isCompleted = endUtc <= nowUtc;
            var projectionEndUtc = endUtc;
            var hasProjection = isCompleted &&
                TryGetKillerZoneProjectionEnd(sessionName, date, useFullSession, endUtc, out projectionEndUtc);
            var isFuture = startUtc > nowUtc;
            var isCurrent = !isFuture && !isCompleted;
            var isNearCurrent = isCompleted && hasProjection && projectionEndUtc >= nowUtc;
            var temporalAlpha = isFuture ? 90 : isCurrent ? 235 : isNearCurrent ? 220 : 200;
            var temporalColor = WithAlpha(kzColor, temporalAlpha);
            var lineEndUtc = isCompleted
                ? endUtc
                : (nowUtc < startUtc ? endUtc : nowUtc);
            var style = isCompleted ? "Solid" : "Dots";
            var id = objectIndex.ToString(CultureInfo.InvariantCulture);
            var topLine = Chart.DrawTrendLine("KZ_TOP_" + (isCompleted ? "DONE_" : "LIVE_") + id, startUtc, high, lineEndUtc, high, temporalColor);
            TrySetPropertyValue(topLine, "Thickness", 1);
            TrySetEnumPropertyValue(topLine, "LineStyle", style);
            TrySetChartObjectBackground(topLine);

            var bottomLine = Chart.DrawTrendLine("KZ_BOT_" + (isCompleted ? "DONE_" : "LIVE_") + id, startUtc, low, lineEndUtc, low, temporalColor);
            TrySetPropertyValue(bottomLine, "Thickness", 1);
            TrySetEnumPropertyValue(bottomLine, "LineStyle", style);
            TrySetChartObjectBackground(bottomLine);

            // Mark the exact first and last bar of every session/KZ range. These edges are
            // deliberately faint so they define the time window without obscuring candles.
            var boundaryColor = WithAlpha(kzColor, 40);
            // cTrader can discard a bounded trend line whose two X coordinates are exactly
            // identical. A sub-pixel time offset keeps the edge visually vertical while giving
            // the renderer a non-zero segment to paint.
            var boundaryRenderOffset = TimeSpan.FromSeconds(Math.Max(1.0, TimeFrameToMinutes(Chart.TimeFrame) * 0.5));
            var startBoundary = Chart.DrawTrendLine("KZ_START_" + id, startUtc, high, startUtc.Add(boundaryRenderOffset), low, boundaryColor);
            TrySetPropertyValue(startBoundary, "Thickness", 1);
            TrySetPropertyValue(startBoundary, "Color", boundaryColor);
            TrySetEnumPropertyValue(startBoundary, "LineStyle", "Dots");
            TrySetPropertyValue(startBoundary, "ZIndex", 6);
            var endBoundary = Chart.DrawTrendLine("KZ_END_" + id, endUtc, high, endUtc.Add(boundaryRenderOffset), low, boundaryColor);
            TrySetPropertyValue(endBoundary, "Thickness", 1);
            TrySetPropertyValue(endBoundary, "Color", boundaryColor);
            TrySetEnumPropertyValue(endBoundary, "LineStyle", "Dots");
            TrySetPropertyValue(endBoundary, "ZIndex", 6);

            // A completed range becomes a faint projected reference until the next session
            // finishes: Asia -> London, London -> New York, New York -> next Asia.
            if (hasProjection)
            {
                var projectionColor = WithAlpha(kzColor, 30);
                var topProjection = Chart.DrawTrendLine("KZ_TOP_PROJ_" + id, endUtc, high, projectionEndUtc, high, projectionColor);
                TrySetPropertyValue(topProjection, "Thickness", 1);
                TrySetEnumPropertyValue(topProjection, "LineStyle", "Dots");
                TrySetChartObjectBackground(topProjection);
                var bottomProjection = Chart.DrawTrendLine("KZ_BOT_PROJ_" + id, endUtc, low, projectionEndUtc, low, projectionColor);
                TrySetPropertyValue(bottomProjection, "Thickness", 1);
                TrySetEnumPropertyValue(bottomProjection, "LineStyle", "Dots");
                TrySetChartObjectBackground(bottomProjection);
            }

            var textX = startUtc;
            var topTextY = high + (Math.Max(high - low, Symbol.PipSize * 20) * 0.08);
            var sessionLabel = string.IsNullOrWhiteSpace(displayLabel) ? "SESSION" : displayLabel.Trim().ToUpperInvariant();
            var text = Chart.DrawText("KZ_TXT_" + objectIndex.ToString(CultureInfo.InvariantCulture), sessionLabel, textX, topTextY, temporalColor);
            TryStyleChartText(text, GetNormalChartLabelFontSize(), "Courier New", true);
            return objectIndex + 1;
        }

        private int DrawTrendlinesOnChart(int objectIndex)
        {
            if (Chart == null || Bars == null || Bars.Count < 20 || Symbol == null)
                return objectIndex;

            try
            {
                var frames = new List<TimeFrame> { Chart.TimeFrame };
                if (DrawHigherTimeframeTrendlines)
                    frames.AddRange(GetAutoHigherTimeframes(Chart.TimeFrame).Take(2));
                foreach (var timeFrame in frames.Where(frame => frame != null).Distinct())
                {
                    var sourceBars = timeFrame == Chart.TimeFrame ? Bars : GetBarsForCurrentMasterTimer(timeFrame, Chart.SymbolName);
                    objectIndex = DrawTrendlineSet(objectIndex, sourceBars, timeFrame);
                }
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Trendline failed: {0}", ex.Message);
            }

            return objectIndex;
        }

        private int DrawTrendlineSet(int objectIndex, Bars sourceBars, TimeFrame sourceTimeFrame)
        {
            if (sourceBars == null || sourceBars.Count < 20)
                return objectIndex;
            var swings = CollectConfirmedSwings(sourceBars, ResolveWorkingSwingLookbackBars(sourceBars, sourceTimeFrame));
            var highs = swings.Where(swing => swing.IsHigh).TakeLast(8).ToList();
            var lows = swings.Where(swing => !swing.IsHigh).TakeLast(8).ToList();
            var label = GetMiniChartLabel(sourceTimeFrame);
            var color = WithAlpha(GetTimeFrameStructureColor(sourceTimeFrame), 170);
            if (highs.Count >= 2)
            {
                objectIndex = DrawSwingTrendline(objectIndex, highs[highs.Count - 2], highs[highs.Count - 1], color, label + ".r.TL");
                if (highs.Count >= 4)
                    objectIndex = DrawSwingTrendline(objectIndex, highs[0], highs[highs.Count - 1], color, label + ".r.TL");
            }
            if (lows.Count >= 2)
            {
                objectIndex = DrawSwingTrendline(objectIndex, lows[lows.Count - 2], lows[lows.Count - 1], color, label + ".r.TL");
                if (lows.Count >= 4)
                    objectIndex = DrawSwingTrendline(objectIndex, lows[0], lows[lows.Count - 1], color, label + ".r.TL");
            }
            if (DrawSidewaysTrendRanges)
                objectIndex = DrawSidewaysTrendRange(objectIndex, sourceBars, sourceTimeFrame, highs, lows);
            return objectIndex;
        }

        private int DrawSidewaysTrendRange(int objectIndex, Bars sourceBars, TimeFrame sourceTimeFrame, List<SwingPoint> highs, List<SwingPoint> lows)
        {
            if (highs.Count < 3 || lows.Count < 3)
                return objectIndex;
            var recentHighs = highs.TakeLast(3).ToList();
            var recentLows = lows.TakeLast(3).ToList();
            var top = recentHighs.Average(swing => swing.Price);
            var bottom = recentLows.Average(swing => swing.Price);
            var fullHigh = sourceBars.HighPrices.Skip(Math.Max(0, sourceBars.Count - 120)).Max();
            var fullLow = sourceBars.LowPrices.Skip(Math.Max(0, sourceBars.Count - 120)).Min();
            var spread = Math.Max(Symbol.PipSize * 8, fullHigh - fullLow);
            var highDrift = recentHighs.Max(swing => swing.Price) - recentHighs.Min(swing => swing.Price);
            var lowDrift = recentLows.Max(swing => swing.Price) - recentLows.Min(swing => swing.Price);
            if (top <= bottom || highDrift > spread * 0.12 || lowDrift > spread * 0.12)
                return objectIndex;
            var start = new[] { recentHighs[0].Time, recentLows[0].Time }.Min();
            var end = GetCurrentChartEndTime();
            // A sideways range is structure, not an official S/D, OB, or FVG zone. Draw only
            // its faint dotted boundaries so boxes remain reserved for official zones.
            var color = WithAlpha(GetTimeFrameStructureColor(sourceTimeFrame), 30);
            var topLine = Chart.DrawTrendLine("TLR_TOP_" + objectIndex.ToString(CultureInfo.InvariantCulture), start, top, end, top, color);
            TrySetPropertyValue(topLine, "Thickness", 1);
            TrySetEnumPropertyValue(topLine, "LineStyle", "Dots");
            var bottomLine = Chart.DrawTrendLine("TLR_BOT_" + objectIndex.ToString(CultureInfo.InvariantCulture), start, bottom, end, bottom, color);
            TrySetPropertyValue(bottomLine, "Thickness", 1);
            TrySetEnumPropertyValue(bottomLine, "LineStyle", "Dots");
            var text = Chart.DrawText("TLR_TXT_" + objectIndex.ToString(CultureInfo.InvariantCulture), GetMiniChartLabel(sourceTimeFrame) + " RANGE", start, top, color);
            TryStyleChartText(text, GetChartMarkerFontSize(), "Courier New", true);
            return objectIndex + 1;
        }

        private int DrawSwingTrendline(int objectIndex, SwingPoint first, SwingPoint second, Color color, string label)
        {
            if (Chart == null || second.Time <= first.Time)
                return objectIndex;

            var minutes = Math.Max(1.0, (second.Time - first.Time).TotalMinutes);
            var slopePerMinute = (second.Price - first.Price) / minutes;
            var currentEndTime = GetCurrentChartEndTime();
            var projectedPrice = second.Price + (slopePerMinute * Math.Max(0.0, (currentEndTime - second.Time).TotalMinutes));

            var line = Chart.DrawTrendLine(
                "TL_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                first.Time,
                first.Price,
                currentEndTime,
                projectedPrice,
                color);
            TrySetPropertyValue(line, "Thickness", 1);
            TrySetEnumPropertyValue(line, "LineStyle", "Dots");
            TrySetPropertyValue(line, "ZIndex", 1);

            var text = Chart.DrawText(
                "TL_TXT_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                label,
                second.Time,
                second.Price,
                color);
            TryStyleChartText(text, GetChartMarkerFontSize(), "Courier New", true);
            TrySetPropertyValue(text, "ZIndex", 2);
            return objectIndex + 1;
        }

        private bool TrySelectVisibleSwingTrendline(List<SwingPoint> swings, bool isHighTrendline, out SwingPoint first, out SwingPoint second)
        {
            first = default(SwingPoint);
            second = default(SwingPoint);
            if (swings == null || swings.Count < 2 || Bars == null || Symbol == null)
                return false;

            var ordered = swings
                .Where(swing => swing.BarIndex >= 0)
                .OrderBy(swing => swing.BarIndex)
                .ToList();
            if (ordered.Count < 2)
                return false;

            var candidates = new List<Tuple<SwingPoint, SwingPoint, double>>();
            for (var i = 0; i < ordered.Count; i++)
            {
                for (var j = i + 1; j < ordered.Count; j++)
                {
                    var older = ordered[i];
                    var newer = ordered[j];
                    if (newer.BarIndex <= older.BarIndex)
                        continue;

                    if (newer.BarIndex - older.BarIndex < 4)
                        continue;

                    if (!IsSwingTrendlineStillValid(older, newer, isHighTrendline))
                        continue;

                    var extremityScore = isHighTrendline ? older.Price : -older.Price;
                    var spanScore = (newer.BarIndex - older.BarIndex) * 0.01;
                    var touchScore = CountSwingTrendlineTouches(older, newer, isHighTrendline) * 50.0;
                    var score = extremityScore + spanScore + touchScore;
                    candidates.Add(Tuple.Create(older, newer, score));
                }
            }

            if (candidates.Count > 0)
            {
                Tuple<SwingPoint, SwingPoint, double> best;
                if (isHighTrendline)
                {
                    best = candidates
                        .OrderByDescending(candidate => candidate.Item1.Price)
                        .ThenByDescending(candidate => candidate.Item3)
                        .First();
                }
                else
                {
                    best = candidates
                        .OrderBy(candidate => candidate.Item1.Price)
                        .ThenByDescending(candidate => candidate.Item3)
                        .First();
                }

                first = best.Item1;
                second = best.Item2;
                return true;
            }

            // Fallback: if no clean visible line exists, at least connect the two latest
            // confirmed highs/lows so the user still gets a usable directional guide.
            first = ordered[ordered.Count - 2];
            second = ordered[ordered.Count - 1];
            return second.BarIndex > first.BarIndex;
        }

        private bool IsSwingTrendlineStillValid(SwingPoint first, SwingPoint second, bool isHighTrendline)
        {
            if (Bars == null || second.BarIndex <= first.BarIndex)
                return false;

            var slopePerBar = (second.Price - first.Price) / Math.Max(1.0, second.BarIndex - first.BarIndex);
            var endIndex = Math.Min(second.BarIndex + 5, Bars.Count - 1);
            var tolerance = GetTrendlineTolerance();

            for (var barIndex = first.BarIndex; barIndex <= endIndex; barIndex++)
            {
                var linePrice = first.Price + (slopePerBar * (barIndex - first.BarIndex));
                if (isHighTrendline)
                {
                    if (Bars.HighPrices[barIndex] > linePrice + tolerance)
                        return false;
                }
                else
                {
                    if (Bars.LowPrices[barIndex] < linePrice - tolerance)
                        return false;
                }
            }

            return true;
        }

        private int CountSwingTrendlineTouches(SwingPoint first, SwingPoint second, bool isHighTrendline, double toleranceMultiplier = 0.2)
        {
            if (Bars == null || second.BarIndex <= first.BarIndex)
                return 0;

            var slopePerBar = (second.Price - first.Price) / Math.Max(1.0, second.BarIndex - first.BarIndex);
            var tolerance = GetTrendlineTolerance() * Math.Max(0.01, toleranceMultiplier);
            var touches = 0;

            for (var barIndex = first.BarIndex; barIndex <= second.BarIndex && barIndex < Bars.Count; barIndex++)
            {
                var linePrice = first.Price + (slopePerBar * (barIndex - first.BarIndex));
                var price = isHighTrendline ? Bars.HighPrices[barIndex] : Bars.LowPrices[barIndex];
                if (Math.Abs(price - linePrice) <= tolerance)
                    touches++;
            }

            return touches;
        }

        private double GetTrendlineTolerance()
        {
            if (Bars == null || Bars.Count == 0 || Symbol == null)
                return 0;

            var latestRange = Math.Max(Bars.HighPrices[Bars.Count - 1] - Bars.LowPrices[Bars.Count - 1], 0);
            return Math.Max(Symbol.PipSize * 2.0, latestRange * 0.15);
        }

        private int DrawDivergenceOnChart(int objectIndex)
        {
            if (Chart == null || Bars == null || Bars.Count < 40 || Symbol == null)
                return objectIndex;

            try
            {
                var frames = new List<TimeFrame> { Chart.TimeFrame };
                if (DrawHigherTimeframeDivergence)
                    frames.AddRange(GetAutoHigherTimeframes(Chart.TimeFrame).Take(2));
                foreach (var timeFrame in frames.Where(frame => frame != null).Distinct())
                {
                    var sourceBars = timeFrame == Chart.TimeFrame ? Bars : GetBarsForCurrentMasterTimer(timeFrame, Chart.SymbolName);
                    objectIndex = DrawDivergenceForBars(objectIndex, sourceBars, timeFrame);
                }
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] Divergence failed: {0}", ex.Message);
            }

            return objectIndex;
        }

        private int DrawDivergenceForBars(int objectIndex, Bars sourceBars, TimeFrame sourceTimeFrame)
        {
            if (sourceBars == null || sourceBars.Count < 40)
                return objectIndex;
            try
            {
                var swings = CollectConfirmedSwings(sourceBars, 220);
                if (swings.Count < 6)
                    return objectIndex;

                var rsiConfig = ResolveRsiIndicatorConfig(DrawRsiMode == RsiVisualMode.Off ? RsiVisualMode.Auto : DrawRsiMode);
                var recentLows = swings.Where(swing => !swing.IsHigh).TakeLast(8).ToList();
                var recentHighs = swings.Where(swing => swing.IsHigh).TakeLast(8).ToList();
                var color = WithAlpha(GetTimeFrameStructureColor(sourceTimeFrame), 180);

                for (var i = recentLows.Count - 1; i >= 1; i--)
                {
                    var left = recentLows[i - 1];
                    var right = recentLows[i];
                    var leftRsi = ComputeRelativeStrengthIndex(sourceBars, left.BarIndex, rsiConfig.Period);
                    var rightRsi = ComputeRelativeStrengthIndex(sourceBars, right.BarIndex, rsiConfig.Period);
                    if (right.Price < left.Price && rightRsi > leftRsi && IsFiniteNumber(leftRsi) && IsFiniteNumber(rightRsi))
                    {
                        objectIndex = DrawDivergencePair(objectIndex, sourceBars, sourceTimeFrame, left, right, true, color, GetMiniChartLabel(sourceTimeFrame) + " DIV");
                        break;
                    }
                }

                for (var i = recentHighs.Count - 1; i >= 1; i--)
                {
                    var left = recentHighs[i - 1];
                    var right = recentHighs[i];
                    var leftRsi = ComputeRelativeStrengthIndex(sourceBars, left.BarIndex, rsiConfig.Period);
                    var rightRsi = ComputeRelativeStrengthIndex(sourceBars, right.BarIndex, rsiConfig.Period);
                    if (right.Price > left.Price && rightRsi < leftRsi && IsFiniteNumber(leftRsi) && IsFiniteNumber(rightRsi))
                    {
                        objectIndex = DrawDivergencePair(objectIndex, sourceBars, sourceTimeFrame, left, right, false, color, GetMiniChartLabel(sourceTimeFrame) + " DIV");
                        break;
                    }
                }
            }
            catch (Exception ex)
            {
                SafePrint("[Visuals] {0} divergence failed: {1}", GetMiniChartLabel(sourceTimeFrame), ex.Message);
            }

            return objectIndex;
        }

        private int DrawDivergencePair(int objectIndex, Bars sourceBars, TimeFrame sourceTimeFrame, SwingPoint first, SwingPoint second, bool bullish, Color color, string label)
        {
            if (Chart == null)
                return objectIndex;

            var line = Chart.DrawTrendLine(
                "DIV_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                first.Time,
                first.Price,
                second.Time,
                second.Price,
                color);
            TrySetPropertyValue(line, "Thickness", 1);
            TrySetEnumPropertyValue(line, "LineStyle", "Solid");
            TrySetPropertyValue(line, "ZIndex", 2);

            var eventBoxColor = bullish ? Color.FromArgb(255, 34, 139, 34) : Color.FromArgb(255, 239, 68, 68);
            // A swing is confirmed two candles after its pivot; that confirmation candle is
            // the executable DIV event, so box and label it rather than implying look-ahead.
            var confirmationIndex = Math.Min(sourceBars.Count - 2, second.BarIndex + 2);
            DrawPatternRangeBox("DIV_BOX_" + objectIndex.ToString(CultureInfo.InvariantCulture), sourceBars, sourceTimeFrame, confirmationIndex, 1, eventBoxColor, 8, 60);
            var confirmationTime = sourceBars.OpenTimes[confirmationIndex];
            var confirmationAnchor = bullish ? sourceBars.LowPrices[confirmationIndex] : sourceBars.HighPrices[confirmationIndex];
            var confirmationRange = Math.Max(sourceBars.HighPrices[confirmationIndex] - sourceBars.LowPrices[confirmationIndex], Symbol.PipSize * 8.0);

            // Divergence is an event (usable as a trade trigger): draw the directional icon at
            // the swing point + a labeled marker, not just a plain label.
            var icon = Chart.DrawText(
                "DIV_ICON_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                GetDirectionalMarkerIcon(bullish),
                confirmationTime,
                confirmationAnchor,
                color);
            TryStyleChartText(icon, GetChartMarkerFontSize(), "Courier New", true);
            TrySetPropertyValue(icon, "ZIndex", 3);

            var textY = ResolveDirectionalLabelPrice(bullish, confirmationAnchor, confirmationRange, 0);
            var text = Chart.DrawText(
                "DIV_TXT_" + objectIndex.ToString(CultureInfo.InvariantCulture),
                label + (bullish ? " B" : " S"),
                confirmationTime,
                textY,
                color);
            TryStyleChartText(text, GetChartMarkerFontSize(), "Courier New", true);
            TrySetPropertyValue(text, "ZIndex", 3);
            return objectIndex + 1;
        }

        private int DrawRecentFvgZones(Bars sourceBars, TimeFrame sourceTimeFrame, string objectPrefix, int objectIndex, DateTime endTime)
        {
            var maxZones = Math.Max(1, ResolveZoneMaxCount(ZoneMaxCount));
            if (sourceBars == null || sourceBars.Count < 3) return objectIndex;
            var lookbackBars = ResolveZoneLookbackBars(ZoneLookback);
            var zoneColor = Color.FromArgb(51, 72, 72, 72);
            var snapshot = BuildStructureSnapshotV2(sourceBars, lookbackBars > 0 ? lookbackBars : sourceBars.Count);
            var zones = snapshot.Zones
                .Where(value => value.Type == StructureZoneTypeV2.Fvg || value.Type == StructureZoneTypeV2.InverseFvg)
                .Where(value => ZoneRevisit != ZoneRevisitMode.Skip || value.State == StructureZoneStateV2.Active)
                .OrderByDescending(value => value.ConfirmationBarIndex)
                .Take(maxZones)
                .ToList();
            foreach (var zone in zones)
            {
                var zoneEndTime = ResolveStructureZoneEndTime(sourceBars, sourceTimeFrame, zone, endTime);
                var rect = Chart.DrawRectangle(objectPrefix + objectIndex.ToString(CultureInfo.InvariantCulture), sourceBars.OpenTimes[zone.OriginBarIndex], zone.High, zoneEndTime, zone.Low, zoneColor);
                TrySetPropertyValue(rect, "IsFilled", true);
                TrySetPropertyValue(rect, "Color", zoneColor);
                TrySetPropertyValue(rect, "BorderColor", Color.FromArgb(0, zoneColor.R, zoneColor.G, zoneColor.B));
                TrySetPropertyValue(rect, "Thickness", 0);
                TrySetChartObjectBackground(rect);
                var zoneLabel = zone.Type == StructureZoneTypeV2.InverseFvg ? "iFVG" : "FVG";
                DrawArtifactZoneLabel(objectPrefix + "ZONE", objectIndex, (zone.High + zone.Low) * 0.5, Color.FromArgb(153, 110, 110, 110), string.Format(CultureInfo.InvariantCulture, "{0}{1}", objectPrefix.StartsWith("HTF_", StringComparison.OrdinalIgnoreCase) ? GetMiniChartLabel(sourceTimeFrame) + "." : "", zoneLabel.ToLowerInvariant()), zoneEndTime, endTime, GetNormalChartLabelFontSize(), sourceTimeFrame);
                objectIndex++;
            }
            return objectIndex;
        }

        private int DrawRecentOrderBlocks(Bars sourceBars, TimeFrame sourceTimeFrame, string objectPrefix, int objectIndex, DateTime endTime)
        {
            var maxBlocks = Math.Max(1, ResolveZoneMaxCount(ZoneMaxCount));
            if (sourceBars == null || sourceBars.Count < 4) return objectIndex;
            var lookbackBars = ResolveZoneLookbackBars(ZoneLookback);
            var zoneColor = Color.FromArgb(51, 72, 72, 72);
            var snapshot = BuildStructureSnapshotV2(sourceBars, lookbackBars > 0 ? lookbackBars : sourceBars.Count);
            var zones = snapshot.Zones
                .Where(value => value.Type == StructureZoneTypeV2.OrderBlock || value.Type == StructureZoneTypeV2.BreakerBlock)
                .Where(value => ZoneRevisit != ZoneRevisitMode.Skip || value.State == StructureZoneStateV2.Active)
                .OrderByDescending(value => value.ConfirmationBarIndex)
                .Take(maxBlocks)
                .ToList();
            foreach (var zone in zones)
            {
                var zoneEndTime = ResolveStructureZoneEndTime(sourceBars, sourceTimeFrame, zone, endTime);
                DrawOrderBlockRectangle(sourceBars, objectPrefix + objectIndex.ToString(CultureInfo.InvariantCulture), zone.OriginBarIndex, zoneEndTime, zoneColor);
                var zoneLabel = zone.Type == StructureZoneTypeV2.BreakerBlock ? "BB" : "OB";
                DrawArtifactZoneLabel(objectPrefix + "ZONE", objectIndex, (zone.High + zone.Low) * 0.5, Color.FromArgb(153, 110, 110, 110), string.Format(CultureInfo.InvariantCulture, "{0}{1}", objectPrefix.StartsWith("HTF_", StringComparison.OrdinalIgnoreCase) ? GetMiniChartLabel(sourceTimeFrame) + "." : "", zoneLabel.ToLowerInvariant()), zoneEndTime, endTime, GetNormalChartLabelFontSize(), sourceTimeFrame);
                objectIndex++;
            }
            return objectIndex;
        }

        private bool IsZoneTouched(Bars sourceBars, int fromBarIndex, double zoneLow, double zoneHigh)
        {
            if (sourceBars == null || sourceBars.Count == 0) return false;
            var low = Math.Min(zoneLow, zoneHigh);
            var high = Math.Max(zoneLow, zoneHigh);
            var lastClosedBarIndex = ResolveStructureLastClosedBarIndex(sourceBars);
            for (var i = Math.Max(0, fromBarIndex); i <= lastClosedBarIndex; i++)
            {
                if (sourceBars.HighPrices[i] >= low && sourceBars.LowPrices[i] <= high)
                    return true;
            }
            return false;
        }

        private DateTime ResolveStructureZoneEndTime(Bars sourceBars, TimeFrame sourceTimeFrame, StructureZoneV2 zone, DateTime chartEndTime)
        {
            if (sourceBars == null || sourceBars.Count == 0)
                return chartEndTime;

            var lifecycleBarIndex = -1;
            if (zone.State == StructureZoneStateV2.Invalidated)
            {
                lifecycleBarIndex = Math.Max(zone.TouchBarIndex, zone.InvalidationBarIndex);
            }
            else
            {
                int visitCount;
                int lastTouchBarIndex;
                CountZoneVisits(sourceBars, zone.ConfirmationBarIndex + 1, zone.Low, zone.High, out visitCount, out lastTouchBarIndex);
                if (visitCount > 1)
                    lifecycleBarIndex = lastTouchBarIndex;
            }

            return lifecycleBarIndex >= 0
                ? ResolveBufferedArtifactEndTime(sourceBars, sourceTimeFrame, lifecycleBarIndex, chartEndTime)
                : chartEndTime;
        }

        private void CountZoneVisits(Bars sourceBars, int fromBarIndex, double zoneLow, double zoneHigh, out int visitCount, out int lastTouchBarIndex)
        {
            visitCount = 0;
            lastTouchBarIndex = -1;
            if (sourceBars == null || sourceBars.Count == 0)
                return;

            var low = Math.Min(zoneLow, zoneHigh);
            var high = Math.Max(zoneLow, zoneHigh);
            var lastClosedBarIndex = ResolveStructureLastClosedBarIndex(sourceBars);
            var insideVisit = false;
            for (var i = Math.Max(0, fromBarIndex); i <= lastClosedBarIndex; i++)
            {
                var touches = sourceBars.HighPrices[i] >= low && sourceBars.LowPrices[i] <= high;
                if (!touches)
                {
                    insideVisit = false;
                    continue;
                }

                if (!insideVisit)
                    visitCount++;
                insideVisit = true;
                lastTouchBarIndex = i;
            }
        }

        private DateTime ResolveBufferedArtifactEndTime(Bars sourceBars, TimeFrame sourceTimeFrame, int lifecycleBarIndex, DateTime chartEndTime)
        {
            if (sourceBars == null || sourceBars.Count == 0 || lifecycleBarIndex < 0)
                return chartEndTime;

            var safeIndex = Math.Min(sourceBars.Count - 1, lifecycleBarIndex);
            var bufferedIndex = safeIndex + 3;
            var bufferedTime = bufferedIndex < sourceBars.Count
                ? sourceBars.OpenTimes[bufferedIndex]
                : sourceBars.OpenTimes[safeIndex].AddMinutes(Math.Max(1, TimeFrameToMinutes(sourceTimeFrame)) * 3.0);
            return chartEndTime > DateTime.MinValue && bufferedTime > chartEndTime ? chartEndTime : bufferedTime;
        }

        private DateTime ResolveSourceBarEndTime(Bars sourceBars, DateTime barTime, TimeFrame sourceTimeFrame)
        {
            if (sourceBars != null && sourceBars.Count > 1)
            {
                for (var i = 0; i < sourceBars.Count - 1; i++)
                {
                    if (sourceBars.OpenTimes[i] == barTime)
                        return sourceBars.OpenTimes[i + 1];
                }
            }

            return barTime.AddMinutes(Math.Max(1, TimeFrameToMinutes(sourceTimeFrame)));
        }

        private int ResolveSourceBarIndex(Bars sourceBars, DateTime barTime)
        {
            if (sourceBars == null || sourceBars.Count == 0 || barTime == DateTime.MinValue)
                return -1;

            for (var i = sourceBars.Count - 1; i >= 0; i--)
            {
                if (sourceBars.OpenTimes[i] == barTime)
                    return i;
            }

            for (var i = sourceBars.Count - 1; i >= 0; i--)
            {
                if (sourceBars.OpenTimes[i] <= barTime)
                    return i;
            }

            return -1;
        }

        private bool IsOrderBlockTouched(Bars sourceBars, int fromBarIndex, int obBarIndex)
        {
            var obHigh = sourceBars.HighPrices[obBarIndex];
            var obLow = sourceBars.LowPrices[obBarIndex];
            return IsZoneTouched(sourceBars, fromBarIndex, obLow, obHigh);
        }

        private void DrawOrderBlockRectangle(Bars sourceBars, string objectName, int barIndex, DateTime endTime, Color color)
        {
            var high = sourceBars.HighPrices[barIndex];
            var low = sourceBars.LowPrices[barIndex];
            var rect = Chart.DrawRectangle(objectName, sourceBars.OpenTimes[barIndex], high, endTime, low, color);
            TrySetPropertyValue(rect, "IsFilled", true);
            TrySetPropertyValue(rect, "Thickness", 0);
            TrySetPropertyValue(rect, "Color", color);
            TrySetPropertyValue(rect, "BorderColor", Color.FromArgb(0, color.R, color.G, color.B));
            TrySetChartObjectBackground(rect);
        }

        private string DetectSymbolTradeAvailabilityReason(Symbol symbol)
        {
            if (symbol == null) return "SYMBOL_NULL";

            try
            {
                bool boolState;
                if (TryReadBoolMember(symbol, "IsTradingEnabled", out boolState) && !boolState)
                    return "SYMBOL_TRADING_DISABLED";
                if (TryReadBoolMember(symbol, "IsTradable", out boolState) && !boolState)
                    return "SYMBOL_NOT_TRADABLE";
            }
            catch
            {
            }

            try
            {
                var tradingMode = TryGetPropertyValue(symbol, "TradingMode");
                var tradingModeText = tradingMode != null ? Convert.ToString(tradingMode, CultureInfo.InvariantCulture).Trim().ToUpperInvariant() : "";
                if (!string.IsNullOrWhiteSpace(tradingModeText))
                {
                    if (tradingModeText.Contains("DISABLED")) return "SYMBOL_TRADING_DISABLED";
                    if (tradingModeText.Contains("CLOSEONLY")) return "SYMBOL_CLOSE_ONLY";
                }
            }
            catch
            {
            }

            try
            {
                var marketHours = TryGetPropertyValue(symbol, "MarketHours");
                if (marketHours != null)
                {
                    bool isOpen;
                    if (TryReadBoolMember(marketHours, "IsOpened", out isOpen) && !isOpen)
                        return "MARKET_CLOSED";
                    if (TryReadBoolMember(marketHours, "IsOpen", out isOpen) && !isOpen)
                        return "MARKET_CLOSED";
                }
            }
            catch
            {
            }

            if (!HasUsableQuotes(symbol)) return "NO_QUOTES";
            return "";
        }

        private string BuildSubmitContext(
            Symbol symbol,
            string action,
            string orderType,
            double entry,
            double executionPrice,
            double sl,
            double tp,
            double volumeUnits,
            double requestedRiskMoney,
            double finalRiskMoney)
        {
            var symbolName = symbol != null ? symbol.Name : "UNKNOWN";
            var bid = symbol != null && !double.IsNaN(symbol.Bid) ? symbol.Bid : 0;
            var ask = symbol != null && !double.IsNaN(symbol.Ask) ? symbol.Ask : 0;
            var spread = symbol != null && !double.IsNaN(symbol.Spread) ? symbol.Spread : 0;
            var minVol = symbol != null && !double.IsNaN(symbol.VolumeInUnitsMin) ? symbol.VolumeInUnitsMin : 0;
            var stepVol = symbol != null && !double.IsNaN(symbol.VolumeInUnitsStep) ? symbol.VolumeInUnitsStep : 0;
            var lots = 0.0;
            var estimatedMargin = 0.0;
            var marginBudget = 0.0;
            try
            {
                if (symbol != null && volumeUnits > 0)
                {
                    lots = symbol.VolumeInUnitsToQuantity(volumeUnits);
                    estimatedMargin = symbol.GetEstimatedMargin(action == "BUY" ? TradeType.Buy : TradeType.Sell, volumeUnits);
                }
            }
            catch
            {
                lots = 0;
                estimatedMargin = 0;
            }
            marginBudget = Account != null ? Math.Max(0, Account.FreeMargin) : 0;

            var tradableReason = DetectSymbolTradeAvailabilityReason(symbol);
            var tradableState = string.IsNullOrWhiteSpace(tradableReason) ? "OK" : tradableReason;
            return string.Format(
                CultureInfo.InvariantCulture,
                "symbol={0}; side={1}; type={2}; bid={3:F5}; ask={4:F5}; spread={5:F2}; entry={6:F5}; exec={7:F5}; sl={8:F5}; tp={9:F5}; volume_units={10:F2}; lots={11:F4}; min_vol={12:F2}; step_vol={13:F2}; requested_risk={14:F2}; final_risk={15:F2}; free_margin={16:F2}; margin_budget={17:F2}; estimated_margin={18:F2}; tradable={19}",
                symbolName,
                action,
                orderType,
                bid,
                ask,
                spread,
                entry,
                executionPrice,
                sl,
                tp,
                volumeUnits,
                lots,
                minVol,
                stepVol,
                requestedRiskMoney,
                finalRiskMoney,
                Account != null ? Account.FreeMargin : 0,
                marginBudget,
                estimatedMargin,
                tradableState
            );
        }

        private string DescribeTradeAvailabilityReason(string reason, string symbolName)
        {
            var resolvedSymbol = string.IsNullOrWhiteSpace(symbolName) ? "symbol" : symbolName.Trim();
            switch ((reason ?? "").Trim().ToUpperInvariant())
            {
                case "MARKET_CLOSED":
                    return resolvedSymbol + " market is closed";
                case "NO_QUOTES":
                    return resolvedSymbol + " has no live quotes";
                case "SYMBOL_TRADING_DISABLED":
                    return resolvedSymbol + " trading is disabled";
                case "SYMBOL_CLOSE_ONLY":
                    return resolvedSymbol + " is close-only right now";
                case "SYMBOL_NOT_TRADABLE":
                    return resolvedSymbol + " is not tradable right now";
                case "SYMBOL_NULL":
                    return "No tradable symbol is loaded";
                default:
                    return string.IsNullOrWhiteSpace(reason) ? resolvedSymbol + " is not tradable right now" : reason;
            }
        }

