        private double EstimateOpenPositionRiskAmount(Position position)
        {
            if (position == null || !position.StopLoss.HasValue) return 0;
            var symbol = ResolveLoadedSymbol(position.SymbolName);
            if (symbol == null) return 0;
            return EstimateRiskAmount(symbol, position.TradeType, position.EntryPrice, position.StopLoss.Value, position.VolumeInUnits);
        }

        private double EstimatePendingOrderRiskAmount(PendingOrder order)
        {
            if (order == null || !order.StopLoss.HasValue) return 0;
            var symbol = ResolveLoadedSymbol(order.SymbolName);
            if (symbol == null) return 0;
            return EstimateRiskAmount(symbol, order.TradeType, order.TargetPrice, order.StopLoss.Value, order.VolumeInUnits);
        }

        private double EstimateOpenPositionSlOutcomeAmount(Position position)
        {
            if (position == null || !position.StopLoss.HasValue) return 0;
            var symbol = ResolveLoadedSymbol(position.SymbolName);
            if (symbol == null) return 0;
            var signedPriceDistance = position.StopLoss.Value - position.EntryPrice;
            if (position.TradeType == TradeType.Sell) signedPriceDistance = -signedPriceDistance;
            return EstimatePnlFromPriceDistance(symbol, signedPriceDistance, position.VolumeInUnits);
        }

        private double EstimateOpenPositionTpAmount(Position position)
        {
            if (position == null || !position.TakeProfit.HasValue) return 0;
            var symbol = ResolveLoadedSymbol(position.SymbolName);
            if (symbol == null) return 0;
            var signedPriceDistance = position.TakeProfit.Value - position.EntryPrice;
            if (position.TradeType == TradeType.Sell) signedPriceDistance = -signedPriceDistance;
            return Math.Max(0, EstimatePnlFromPriceDistance(symbol, signedPriceDistance, position.VolumeInUnits));
        }

        private double EstimatePendingOrderTpAmount(PendingOrder order)
        {
            if (order == null || !order.TakeProfit.HasValue) return 0;
            var symbol = ResolveLoadedSymbol(order.SymbolName);
            if (symbol == null) return 0;
            var signedPriceDistance = order.TakeProfit.Value - order.TargetPrice;
            if (order.TradeType == TradeType.Sell) signedPriceDistance = -signedPriceDistance;
            return Math.Max(0, EstimatePnlFromPriceDistance(symbol, signedPriceDistance, order.VolumeInUnits));
        }

        private void InvalidateDailyClosedRiskCache()
        {
            _dailyClosedRiskCacheDayStartUtc = DateTime.MinValue;
            _dailyClosedRiskCacheHistoryCount = -1;
        }

        private void ApplyDailyClosedRiskSnapshot(RiskGateState state, DateTime dayStartUtc)
        {
            if (state == null)
                return;

            var historyCount = History != null ? History.Count : 0;
            if (_dailyClosedRiskCacheDayStartUtc != dayStartUtc ||
                _dailyClosedRiskCacheHistoryCount != historyCount)
            {
                var closedPnl = 0.0;
                var closedWinAmount = 0.0;
                var closedLoseAmount = 0.0;
                if (History != null)
                {
                    foreach (var deal in History)
                    {
                        if (deal == null || ToUtcSafe(deal.ClosingTime) < dayStartUtc)
                            continue;

                        var netProfit = double.IsNaN(deal.NetProfit) ? 0 : deal.NetProfit;
                        closedPnl += netProfit;
                        closedWinAmount += Math.Max(0, netProfit);
                        closedLoseAmount += Math.Max(0, -netProfit);
                    }
                }

                _dailyClosedRiskCacheDayStartUtc = dayStartUtc;
                _dailyClosedRiskCacheHistoryCount = historyCount;
                _dailyClosedRiskCachePnl = closedPnl;
                _dailyClosedRiskCacheWinAmount = closedWinAmount;
                _dailyClosedRiskCacheLoseAmount = closedLoseAmount;
            }

            state.DailyClosedPnl = _dailyClosedRiskCachePnl;
            state.ClosedTodayWinAmount = _dailyClosedRiskCacheWinAmount;
            state.ClosedTodayLoseAmount = _dailyClosedRiskCacheLoseAmount;
        }

        private RiskGateState BuildRiskGateState(double candidateRiskAmount, bool useLiveAccountState = false)
        {
            RefreshRiskAnchors();

            var positions = useLiveAccountState
                ? (Positions != null ? Positions.ToList() : new List<Position>())
                : GetCurrentPositionsSnapshot();
            var pendingOrders = useLiveAccountState
                ? (PendingOrders != null ? PendingOrders.ToList() : new List<PendingOrder>())
                : GetCurrentPendingOrdersSnapshot();
            var state = new RiskGateState();
            state.OpenPositionsCount = positions.Count;
            state.PendingOrdersCount = pendingOrders.Count;
            state.UsedMarginAmount = Account != null && !double.IsNaN(Account.Margin) ? Math.Max(0, Account.Margin) : 0;
            foreach (var position in positions)
            {
                if (position == null)
                    continue;

                var netProfit = double.IsNaN(position.NetProfit) ? 0 : position.NetProfit;
                var openRiskAmount = EstimateOpenPositionRiskAmount(position);
                state.ExistingOpenRiskAmount += openRiskAmount;
                state.MaxSingleOpenRiskAmount = Math.Max(state.MaxSingleOpenRiskAmount, openRiskAmount);
                state.DailyFloatingPnl += netProfit;
                state.CurrentWinAmount += Math.Max(0, netProfit);
                state.CurrentLoseAmount += Math.Max(0, -netProfit);
                state.PossibleWinAmount += EstimateOpenPositionTpAmount(position);
                state.PossibleLoseAmount += openRiskAmount;
                state.PossibleSlOutcomeAmount += EstimateOpenPositionSlOutcomeAmount(position);
            }
            foreach (var order in pendingOrders)
            {
                if (order == null)
                    continue;

                var pendingRiskAmount = EstimatePendingOrderRiskAmount(order);
                state.ExistingOpenRiskAmount += pendingRiskAmount;
                state.MaxSingleOpenRiskAmount = Math.Max(state.MaxSingleOpenRiskAmount, pendingRiskAmount);
                state.PossibleWinAmount += EstimatePendingOrderTpAmount(order);
                state.PossibleLoseAmount += pendingRiskAmount;
            }
            state.CandidateRiskAmount = Math.Max(0, candidateRiskAmount);
            state.TotalOpenRiskAmount = state.ExistingOpenRiskAmount + state.CandidateRiskAmount;
            state.AccountBalance = Account != null ? Math.Max(0, Account.Balance) : 0;
            state.CurrentEquity = Account != null ? Math.Max(0, Account.Equity) : 0;
            state.UsedMarginPercent = state.CurrentEquity > 0
                ? (state.UsedMarginAmount / state.CurrentEquity) * 100.0
                : 0;
            state.MaxSingleOpenRiskPercent = state.AccountBalance > 0
                ? (state.MaxSingleOpenRiskAmount / state.AccountBalance) * 100.0
                : 0;
            state.TotalOpenRiskPercent = state.AccountBalance > 0
                ? (state.TotalOpenRiskAmount / state.AccountBalance) * 100.0
                : 0;

            var utcNow = DateTime.UtcNow;
            var ftmoDayStartUtc = GetFtmoDayStartUtc(utcNow);
            ApplyDailyClosedRiskSnapshot(state, ftmoDayStartUtc);
            state.DailyClosedNetLossAmount = state.ClosedTodayLoseAmount - state.ClosedTodayWinAmount;
            state.DailyTotalPnl = state.DailyClosedPnl + state.DailyFloatingPnl;
            state.DailyNetWinAmount = Math.Max(0, state.DailyTotalPnl);
            state.DailyNetLossAmount = Math.Max(0, -state.DailyTotalPnl);
            state.DailyNetWinPercent = _initialAccountBalance > 0
                ? (state.DailyNetWinAmount / _initialAccountBalance) * 100.0
                : 0;
            state.DailyNetLossPercent = _initialAccountBalance > 0
                ? (state.DailyNetLossAmount / _initialAccountBalance) * 100.0
                : 0;
            var derivedDayStartBalance = Math.Max(0, state.AccountBalance - state.DailyClosedPnl);
            var derivedDayStartEquity = Math.Max(0, state.CurrentEquity - state.DailyTotalPnl);
            if (_ftmoDayStartUtc == DateTime.MinValue || ftmoDayStartUtc > _ftmoDayStartUtc)
            {
                _ftmoDayStartUtc = ftmoDayStartUtc;
                _ftmoDayStartBalance = derivedDayStartBalance;
                _ftmoDayStartEquity = state.CurrentEquity;
                if (_ftmoHighestDayStartBalance <= 0)
                    _ftmoHighestDayStartBalance = Math.Max(_initialAccountBalance, _ftmoDayStartBalance);
                else if (_ftmoDayStartBalance > _ftmoHighestDayStartBalance)
                    _ftmoHighestDayStartBalance = _ftmoDayStartBalance;
            }
            else if (_ftmoDayStartBalance <= 0)
            {
                _ftmoDayStartBalance = derivedDayStartBalance;
            }
            else if (_ftmoDayStartEquity <= 0)
            {
                _ftmoDayStartEquity = derivedDayStartEquity;
            }

            var dailyLossReference = ResolveDailyLossReferenceAmount(_ftmoDayStartBalance, _ftmoDayStartEquity);
            state.DailyLossAmount = Math.Max(0, dailyLossReference - state.CurrentEquity);
            state.DailyLossPercent = _initialAccountBalance > 0
                ? (state.DailyLossAmount / _initialAccountBalance) * 100.0
                : 0;

            var effectiveMaxEquityDrawdownPercent = GetEffectiveMaxEquityDrawdownPercent();
            var drawdownLimitAmount = GetPercentAmountFromInitialBalance(effectiveMaxEquityDrawdownPercent);
            double drawdownReference;
            switch (GetRiskDrawdownMode())
            {
                case RiskDrawdownMode.EndOfDayTrailingBalance:
                    drawdownReference = Math.Max(_initialAccountBalance, _ftmoHighestDayStartBalance);
                    break;
                case RiskDrawdownMode.BalanceTrailingCapAtInitial:
                    drawdownReference = drawdownLimitAmount > 0
                        ? Math.Min(_initialAccountBalance + drawdownLimitAmount, _peakBalanceSeen)
                        : _initialAccountBalance;
                    break;
                default:
                    drawdownReference = _initialAccountBalance;
                    break;
            }
            state.PeakEquitySeen = drawdownReference;
            state.EquityDrawdownAmount = Math.Max(0, drawdownReference - state.CurrentEquity);
            state.EquityDrawdownPercent = _initialAccountBalance > 0
                ? (state.EquityDrawdownAmount / _initialAccountBalance) * 100.0
                : 0;
            return state;
        }

        private bool TryGetDailyPnlLimitBreach(RiskGateState state, out string reason)
        {
            if (state == null)
                state = BuildRiskGateState(0);
            var dailyLimitBalance = _ftmoDayStartBalance > 0
                ? _ftmoDayStartBalance
                : (_initialAccountBalance > 0 ? _initialAccountBalance : state.AccountBalance);
            var maxDailyWinAmount = ResolveRiskLimitPresetAmount(MaxDailyWinPreset, dailyLimitBalance);
            var configuredMaxDailyLossAmount = ResolveRiskLimitPresetAmount(MaxDailyLossPreset, dailyLimitBalance);
            return CTraderRiskPolicyEngine.TryGetDailyPnlLimitBreach(
                state,
                maxDailyWinAmount,
                configuredMaxDailyLossAmount,
                GetEffectiveMaxDailyLossPercent(),
                _ftmoDayStartBalance,
                out reason);
        }

        private bool TryGetDailyPnlLimitBreach(out string reason)
        {
            return TryGetDailyPnlLimitBreach(BuildRiskGateState(0), out reason);
        }

        private bool TryPassRiskFirewall(
            Symbol symbol,
            string action,
            string orderTypeStr,
            double entry,
            double executionPrice,
            double sl,
            double tp,
            double volumeUnits,
            double requestedRiskMoney,
            double finalRiskMoney,
            bool isManualTrade,
            out string rejectReason)
        {
            rejectReason = "";
            var effectiveMaxTotalOpenRiskPercent = GetEffectiveMaxTotalOpenRiskPercent();
            var effectiveMaxSameSymbolDirectionRiskPercent = GetEffectiveMaxSameSymbolDirectionRiskPercent();
            var effectiveMaxEquityDrawdownPercent = GetEffectiveMaxEquityDrawdownPercent();
            var tradeType = action == "BUY" ? TradeType.Buy : TradeType.Sell;
            var submitReferencePrice = (orderTypeStr == "market" || entry <= 0) ? executionPrice : entry;
            var candidateRiskAmount = EstimateRiskAmount(symbol, tradeType, submitReferencePrice, sl, volumeUnits);
            var state = BuildRiskGateState(candidateRiskAmount, true);
            if (!CTraderRiskPolicyEngine.TryPassPerTradeRisk(
                state,
                requestedRiskMoney,
                finalRiskMoney,
                submitReferencePrice,
                sl,
                out rejectReason))
                return false;

            if (effectiveMaxSameSymbolDirectionRiskPercent > 0 && symbol != null)
            {
                var sameDirectionRiskAmount = EstimateDirectionalRiskAmount(symbol.Name, tradeType) + state.CandidateRiskAmount;
                if (!CTraderRiskPolicyEngine.TryPassSameDirectionRisk(
                    state,
                    sameDirectionRiskAmount,
                    effectiveMaxSameSymbolDirectionRiskPercent,
                    symbol.Name,
                    action,
                    out rejectReason))
                    return false;
            }

            if (symbol != null)
            {
                string newsRejectReason;
                if (TryGetNewsGateRejectReason(symbol.Name, SelectedRiskTemplate, out newsRejectReason))
                {
                    rejectReason = newsRejectReason;
                    return false;
                }
            }

            string overnightRejectReason;
            if (TryGetOvernightGateRejectReason(SelectedRiskTemplate, isManualTrade, out overnightRejectReason))
            {
                rejectReason = overnightRejectReason;
                return false;
            }

            string weekendRejectReason;
            if (TryGetWeekendGateRejectReason(SelectedRiskTemplate, isManualTrade, out weekendRejectReason))
            {
                rejectReason = weekendRejectReason;
                return false;
            }

            if (!CTraderRiskPolicyEngine.TryPassTotalOpenRisk(state, effectiveMaxTotalOpenRiskPercent, out rejectReason))
                return false;

            if (TryGetDailyPnlLimitBreach(state, out rejectReason))
                return false;

            if (!CTraderRiskPolicyEngine.TryPassEquityDrawdown(state, effectiveMaxEquityDrawdownPercent, out rejectReason))
                return false;

            return true;
        }

        private bool IsStrictPropRiskTemplate()
        {
            return SelectedRiskTemplate != RiskTemplate.Custom;
        }

        private bool TryGetBacktestRiskStopReason(out string reason)
        {
            reason = "";
            if (!IsBacktestingRuntime() || !IsStrictPropRiskTemplate())
                return false;

            var state = BuildRiskGateState(0);
            var effectiveMaxEquityDrawdownPercent = GetEffectiveMaxEquityDrawdownPercent();

            string dailyPnlLimitReason;
            if (TryGetDailyPnlLimitBreach(state, out dailyPnlLimitReason))
            {
                reason = dailyPnlLimitReason;
                return true;
            }

            if (effectiveMaxEquityDrawdownPercent > 0 && state.EquityDrawdownPercent >= effectiveMaxEquityDrawdownPercent)
            {
                reason = string.Format(
                    CultureInfo.InvariantCulture,
                    "prop_drawdown_breach {0:F2}>={1:F2}",
                    state.EquityDrawdownPercent,
                    effectiveMaxEquityDrawdownPercent);
                return true;
            }

            return false;
        }

        private void StopBacktestForPropRuleBreach(string context, string symbolName, string reason)
        {
            if (!IsBacktestingRuntime())
            {
                SafePrint(
                    "[Live][Gate] Reject {0} {1} {2}",
                    string.IsNullOrWhiteSpace(context) ? "ENTRY" : context.Trim(),
                    string.IsNullOrWhiteSpace(symbolName) ? "" : symbolName.Trim().ToUpperInvariant(),
                    string.IsNullOrWhiteSpace(reason) ? "prop_rule_breach" : reason.Trim());
                return;
            }

            if (_backtestRiskStopTriggered)
                return;

            _backtestRiskStopTriggered = true;
            _backtestRiskStopReason = string.Format(
                CultureInfo.InvariantCulture,
                "{0} {1} {2}",
                string.IsNullOrWhiteSpace(context) ? "BACKTEST" : context.Trim(),
                string.IsNullOrWhiteSpace(symbolName) ? "" : symbolName.Trim().ToUpperInvariant(),
                string.IsNullOrWhiteSpace(reason) ? "prop_rule_breach" : reason.Trim()).Trim();

            SafePrint("[Backtest][STOP] {0}", _backtestRiskStopReason);
            try { RefreshDebugPanelNow(); } catch { }
            RequestBotStop("backtest_prop_rule_breach: " + _backtestRiskStopReason);
        }

        private bool EnforceDailyPnlLimitIfNeeded(string context)
        {
            try
            {
                var state = BuildRiskGateState(0);
                string reason;
                if (!TryGetDailyPnlLimitBreach(state, out reason))
                {
                    if (_dailyPnlLimitBreachActive && _dailyPnlLimitBreachDayStartUtc != DateTime.MinValue && _ftmoDayStartUtc > _dailyPnlLimitBreachDayStartUtc)
                    {
                        _dailyPnlLimitBreachActive = false;
                        _dailyPnlLimitBreachDayStartUtc = DateTime.MinValue;
                        _dailyPnlLimitBreachReason = "";
                    }
                    return false;
                }

                var firstBreachOnThisDay = !_dailyPnlLimitBreachActive || _dailyPnlLimitBreachDayStartUtc != _ftmoDayStartUtc || !string.Equals(_dailyPnlLimitBreachReason, reason, StringComparison.Ordinal);
                _dailyPnlLimitBreachActive = true;
                _dailyPnlLimitBreachDayStartUtc = _ftmoDayStartUtc;
                _dailyPnlLimitBreachReason = reason;

                var canceledOrders = 0;
                var failedOrders = 0;
                foreach (var order in GetCurrentPendingOrdersSnapshot())
                {
                    if (order == null)
                        continue;

                    var result = CancelPendingOrder(order);
                    if (result.IsSuccessful) canceledOrders++;
                    else
                    {
                        failedOrders++;
                        SafePrint("[DailyLimit] Cancel failed order #{0}: {1}", order.Id, result.Error);
                    }
                }

                var closedPositions = 0;
                var failedPositions = 0;
                foreach (var position in GetCurrentPositionsSnapshot())
                {
                    if (position == null)
                        continue;

                    var result = ClosePosition(position);
                    if (result.IsSuccessful) closedPositions++;
                    else
                    {
                        failedPositions++;
                        SafePrint("[DailyLimit] Close failed {0} #{1}: {2}", position.SymbolName, position.Id, result.Error);
                    }
                }

                if (firstBreachOnThisDay || canceledOrders > 0 || closedPositions > 0 || failedOrders > 0 || failedPositions > 0)
                {
                    SafePrint(
                        "[DailyLimit] {0} {1}; canceled_orders={2}; closed_positions={3}; failed_orders={4}; failed_positions={5}",
                        string.IsNullOrWhiteSpace(context) ? "STATE" : context.Trim(),
                        reason,
                        canceledOrders,
                        closedPositions,
                        failedOrders,
                        failedPositions);
                    try { RefreshDebugPanelNow(false); } catch { }
                }

                if (IsBacktestingRuntime())
                    StopBacktestForPropRuleBreach(context, Symbol != null ? Symbol.Name : "", reason);

                return true;
            }
            catch (Exception ex)
            {
                SafePrint("[DailyLimit] Enforcement failed: {0}", ex.Message);
                return false;
            }
        }

        private void RequestBotStop(string reason)
        {
            _lastStopReason = string.IsNullOrWhiteSpace(reason) ? "requested_without_reason" : reason.Trim();
            SafePrint("[BotStop] Requesting stop: {0}", _lastStopReason);
            Stop();
        }

        private bool TryPassAbsoluteBrokerRiskGate(
            Symbol symbol,
            string action,
            string orderTypeStr,
            double entry,
            double executionPrice,
            double sl,
            double volumeUnits,
            double finalRiskMoney,
            out double brokerRiskAmount,
            out string rejectReason)
        {
            brokerRiskAmount = 0;
            rejectReason = "";

            if (symbol == null)
            {
                rejectReason = "symbol_missing";
                return false;
            }

            if (!(finalRiskMoney > 0))
                return true;

            var submitReferencePrice = (orderTypeStr == "market" || entry <= 0) ? executionPrice : entry;
            if (!(submitReferencePrice > 0) || !(sl > 0) || !(volumeUnits > 0))
            {
                rejectReason = string.Format(
                    CultureInfo.InvariantCulture,
                    "absolute_risk_gate_invalid_input ref={0:F5}; sl={1:F5}; volume={2:F2}",
                    submitReferencePrice,
                    sl,
                    volumeUnits
                );
                return false;
            }

            brokerRiskAmount = EstimateRiskAmount(symbol, action == "BUY" ? TradeType.Buy : TradeType.Sell, submitReferencePrice, sl, volumeUnits);
            // Permit only a small broker-volume rounding tolerance, never a 20% risk-cap bypass.
            var allowedWithBuffer = finalRiskMoney + Math.Max(0.01, finalRiskMoney * 0.005);
            if (brokerRiskAmount > allowedWithBuffer)
            {
                rejectReason = string.Format(
                    CultureInfo.InvariantCulture,
                    "absolute_risk_gate {0:F2}>{1:F2} (cap={2:F2}); ref={3:F5}; sl={4:F5}; volume={5:F2}",
                    brokerRiskAmount,
                    allowedWithBuffer,
                    finalRiskMoney,
                    submitReferencePrice,
                    sl,
                    volumeUnits
                );
                return false;
            }

            return true;
        }

        private bool TryPassSharedCreationGate(
            Symbol symbol,
            string action,
            string orderTypeStr,
            double entry,
            double executionPrice,
            double sl,
            double tp,
            double requestedVolumeUnits,
            double requestedRiskMoney,
            double finalRiskMoney,
            out double approvedSl,
            out double approvedTp,
            out double approvedVolumeUnits,
            out double approvedRiskMoney,
            out double marginEstimate,
            out double marginBudget,
            out string rejectReason)
        {
            return TryPassSharedCreationGate(
                symbol,
                action,
                orderTypeStr,
                entry,
                executionPrice,
                sl,
                tp,
                requestedVolumeUnits,
                requestedRiskMoney,
                finalRiskMoney,
                false,
                out approvedSl,
                out approvedTp,
                out approvedVolumeUnits,
                out approvedRiskMoney,
                out marginEstimate,
                out marginBudget,
                out rejectReason);
        }

        private bool TryPassSharedCreationGate(
            Symbol symbol,
            string action,
            string orderTypeStr,
            double entry,
            double executionPrice,
            double sl,
            double tp,
            double requestedVolumeUnits,
            double requestedRiskMoney,
            double finalRiskMoney,
            bool isManualTrade,
            out double approvedSl,
            out double approvedTp,
            out double approvedVolumeUnits,
            out double approvedRiskMoney,
            out double marginEstimate,
            out double marginBudget,
            out string rejectReason)
        {
            approvedSl = sl;
            approvedTp = tp;
            approvedVolumeUnits = 0;
            approvedRiskMoney = 0;
            marginEstimate = 0;
            marginBudget = 0;
            rejectReason = "";

            if (symbol == null)
            {
                rejectReason = "symbol_missing";
                return false;
            }

            if (sl <= 0)
            {
                rejectReason = "missing_stop_loss";
                return false;
            }

            var submitReferencePrice = (orderTypeStr == "market" || entry <= 0) ? executionPrice : entry;
            if (symbol.PipSize > 0)
            {
                var minStopPips = ResolveMinStopPips(symbol);
                var adjustProtection = String.Equals(OnSlTpError, "Adjust", StringComparison.OrdinalIgnoreCase);
                if (approvedSl > 0)
                {
                    var slDistPips = Math.Abs(submitReferencePrice - approvedSl) / symbol.PipSize;
                    if (slDistPips < minStopPips)
                    {
                        if (!adjustProtection)
                        {
                            rejectReason = string.Format(
                                CultureInfo.InvariantCulture,
                                "rule=MinStopPips violated; sl_too_close {0:F1}<{1:F1}; ref={2:F5}; sl={3:F5}; fix=widen_SL_or_set_OnSlTpError=Adjust",
                                slDistPips,
                                minStopPips,
                                submitReferencePrice,
                                approvedSl
                            );
                            return false;
                        }

                        approvedSl = action == "SELL"
                            ? submitReferencePrice + minStopPips * symbol.PipSize
                            : submitReferencePrice - minStopPips * symbol.PipSize;
                        approvedSl = NormalizePriceToSymbol(symbol, approvedSl);
                    }
                }

                if (approvedTp > 0)
                {
                    var tpDistPips = Math.Abs(approvedTp - submitReferencePrice) / symbol.PipSize;
                    if (tpDistPips < minStopPips)
                    {
                        if (!adjustProtection)
                        {
                            rejectReason = string.Format(
                                CultureInfo.InvariantCulture,
                                "rule=MinStopPips violated; tp_too_close {0:F1}<{1:F1}; ref={2:F5}; tp={3:F5}; fix=widen_TP_or_set_OnSlTpError=Adjust",
                                tpDistPips,
                                minStopPips,
                                submitReferencePrice,
                                approvedTp
                            );
                            return false;
                        }

                        approvedTp = action == "SELL"
                            ? submitReferencePrice - minStopPips * symbol.PipSize
                            : submitReferencePrice + minStopPips * symbol.PipSize;
                        approvedTp = NormalizePriceToSymbol(symbol, approvedTp);
                    }
                }
            }

            string protectionRejectReason;
            if (!TryValidateProtectionPrices(symbol, action, submitReferencePrice, approvedSl, approvedTp, out protectionRejectReason))
            {
                rejectReason = protectionRejectReason;
                return false;
            }

            approvedVolumeUnits = symbol.NormalizeVolumeInUnits(requestedVolumeUnits, RoundingMode.Down);
            if (approvedVolumeUnits < symbol.VolumeInUnitsMin)
            {
                rejectReason = string.Format(
                    CultureInfo.InvariantCulture,
                    "volume_below_min requested={0:F2} normalized={1:F2} min={2:F2}",
                    requestedVolumeUnits,
                    approvedVolumeUnits,
                    symbol.VolumeInUnitsMin
                );
                return false;
            }

            double riskFittedVolumeUnits;
            double riskFittedRiskMoney;
            string riskFitNote;
            var tradeType = action == "BUY" ? TradeType.Buy : TradeType.Sell;
            if (!TryFitVolumeToRiskCap(symbol, tradeType, submitReferencePrice, approvedSl, approvedVolumeUnits, finalRiskMoney, out riskFittedVolumeUnits, out riskFittedRiskMoney, out riskFitNote))
            {
                rejectReason = riskFitNote;
                return false;
            }
            approvedVolumeUnits = riskFittedVolumeUnits;
            approvedRiskMoney = riskFittedRiskMoney;

            double affordableVolumeUnits;
            string marginNote;
            if (!TryFitVolumeToFreeMargin(symbol, tradeType, approvedVolumeUnits, out affordableVolumeUnits, out marginEstimate, out marginBudget, out marginNote))
            {
                rejectReason = marginNote;
                return false;
            }
            approvedVolumeUnits = affordableVolumeUnits;
            approvedRiskMoney = EstimateRiskAmount(symbol, tradeType, submitReferencePrice, approvedSl, approvedVolumeUnits);

            double absoluteBrokerRiskAmount;
            string absoluteBrokerRiskRejectReason;
            if (!TryPassAbsoluteBrokerRiskGate(
                symbol,
                action,
                orderTypeStr,
                entry,
                executionPrice,
                approvedSl,
                approvedVolumeUnits,
                finalRiskMoney,
                out absoluteBrokerRiskAmount,
                out absoluteBrokerRiskRejectReason))
            {
                rejectReason = absoluteBrokerRiskRejectReason;
                return false;
            }
            approvedRiskMoney = absoluteBrokerRiskAmount;

            string riskFirewallReason;
            if (!TryPassRiskFirewall(
                symbol,
                action,
                orderTypeStr,
                entry,
                executionPrice,
                approvedSl,
                approvedTp,
                approvedVolumeUnits,
                requestedRiskMoney,
                finalRiskMoney,
                isManualTrade,
                out riskFirewallReason))
            {
                rejectReason = riskFirewallReason;
                return false;
            }

            if (approvedVolumeUnits < symbol.VolumeInUnitsMin)
            {
                rejectReason = string.Format(
                    CultureInfo.InvariantCulture,
                    "volume_below_min_after_gate approved={0:F2} min={1:F2}",
                    approvedVolumeUnits,
                    symbol.VolumeInUnitsMin
                );
                return false;
            }

            return true;
        }

        private bool TryValidateProtectionPrices(
            Symbol symbol,
            string action,
            double referencePrice,
            double sl,
            double tp,
            out string reason
        )
        {
            return CTraderStrategyEngine.TryValidatePrices(symbol, action, referencePrice, sl, tp, out reason);
        }

        private bool TryResolveBrokerSymbol(string rawSymbol, out string symbolName)
        {
            symbolName = "";
            var sym = string.IsNullOrWhiteSpace(rawSymbol) ? "" : rawSymbol.Trim();
            if (string.IsNullOrEmpty(sym)) return false;

            try
            {
                string cached;
                if (_symbolResolveCache.TryGetValue(sym, out cached) && !string.IsNullOrWhiteSpace(cached))
                {
                    symbolName = cached;
                    return true;
                }
                if (_notFoundSymbols.Contains(sym)) return false;

                var compact = sym.Replace("/", "").Replace("-", "").Replace("_", "").ToUpperInvariant();
                foreach (var loaded in Symbols)
                {
                    var loadedName = loaded != null ? loaded.ToString() : "";
                    if (string.IsNullOrWhiteSpace(loadedName)) continue;

                    if (string.Equals(loadedName, sym, StringComparison.OrdinalIgnoreCase))
                    {
                        symbolName = loadedName;
                        _symbolResolveCache[sym] = symbolName;
                        return true;
                    }

                    var loadedCompact = loadedName.Replace("/", "").Replace("-", "").Replace("_", "").ToUpperInvariant();
                    if (loadedCompact == compact)
                    {
                        symbolName = loadedName;
                        _symbolResolveCache[sym] = symbolName;
                        return true;
                    }
                }
            }
            catch { }

            _notFoundSymbols.Add(sym);
            return false;
        }

        private bool IsErrorStatus(string status)
        {
            return CTraderSyncEngine.IsErrorAckStatus(status);
        }

        private bool ShouldEmitLog(string level, string message)
        {
            if (string.IsNullOrWhiteSpace(LogFilter)) return true;

            var haystack = ((level ?? "") + " " + (message ?? "")).ToUpperInvariant();
            var hasIncludeToken = false;
            foreach (var rawToken in LogFilter.Split(','))
            {
                var token = (rawToken ?? "").Trim();
                if (token.Length == 0) continue;

                // Tokens prefixed with '!' are exclusions: any match suppresses the line even
                // when an include token also matches (e.g. "Error,!Error.expected").
                var isExclusion = token.StartsWith("!", StringComparison.Ordinal);
                var normalizedToken = (isExclusion ? token.Substring(1) : token).Trim().ToUpperInvariant();
                if (normalizedToken.Length == 0) continue;

                if (isExclusion)
                {
                    if (haystack.Contains(normalizedToken)) return false;
                    continue;
                }

                hasIncludeToken = true;
                if (haystack.Contains(normalizedToken)) return true;
            }
            // Only exclusions present (or empty tokens): emit everything not excluded.
            return !hasIncludeToken;
        }

        private bool ShouldRaisePopupAlert(string level, string message)
        {
            if (!EnablePopupAlerts) return false;

            var text = string.IsNullOrWhiteSpace(message) ? "" : message.Trim();
            if (string.IsNullOrWhiteSpace(text)) return false;

            var isErrorLevel = string.Equals((level ?? "").Trim(), "ERROR", StringComparison.OrdinalIgnoreCase);
            var isTradeRelevant =
                text.IndexOf("[ChartTrade]", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("[Reject]", StringComparison.OrdinalIgnoreCase) >= 0 ||
                text.IndexOf("[CreateFailed]", StringComparison.OrdinalIgnoreCase) >= 0;
            if (!isErrorLevel || !isTradeRelevant) return false;

            var now = DateTime.UtcNow;
            if (string.Equals(_lastPopupAlertMessage, text, StringComparison.Ordinal) && (now - _lastPopupAlertAt).TotalSeconds < 3)
                return false;

            _lastPopupAlertMessage = text;
            _lastPopupAlertAt = now;
            return true;
        }

        private void TryShowPopupAlert(string level, string message)
        {
            if (!ShouldRaisePopupAlert(level, message)) return;

            try
            {
                Notifications.ShowPopup("42Trade Alert", message, PopupNotificationState.Error);
                if (EnableAlertSound)
                    Notifications.PlaySound(SoundType.NegativeNotification);
            }
            catch
            {
            }
        }

        private void LogValidationBlock(string message)
        {
            SafeLog("WARN", "[Validate] {0}", message);
        }

        // Prints an INFO line that is still subject to the Log Filter: lines that do not match
        // any filter token are suppressed (and counted) exactly like SafeLog output, so a filter
        // like "Error,Reject" hides these too. Keep it only for messages that would otherwise
        // be interesting even with a tight filter (e.g. settings persistence).
        private void PrintBypassLogFilter(string format, params object[] args)
        {
            var message = (args != null && args.Length > 0)
                ? string.Format(CultureInfo.InvariantCulture, format, args)
                : format;
            if (!ShouldEmitLog("INFO", message))
            {
                _suppressedLogCount++;
                return;
            }

            _lastPanelMessage = message;
            _lastPanelMessageIsError = false;
            _lastPanelMessageColor = Color.White;
            BeginInvokeOnMainThread(() => Print(message));
        }

        private void PrintAlways(string format, params object[] args)
        {
            var message = (args != null && args.Length > 0)
                ? string.Format(CultureInfo.InvariantCulture, format, args)
                : format;

            _lastPanelMessage = message;
            _lastPanelMessageIsError =
                message.IndexOf("[Error]", StringComparison.OrdinalIgnoreCase) >= 0 ||
                message.IndexOf(" failed", StringComparison.OrdinalIgnoreCase) >= 0 ||
                message.IndexOf(" rejected", StringComparison.OrdinalIgnoreCase) >= 0 ||
                message.IndexOf(" blocked", StringComparison.OrdinalIgnoreCase) >= 0;
            _lastPanelMessageColor = _lastPanelMessageIsError ? Color.Red : Color.White;
            BeginInvokeOnMainThread(() => Print(message));
        }

        private void SafeLog(string level, string format, params object[] args)
        {
            var message = (args != null && args.Length > 0)
                ? string.Format(CultureInfo.InvariantCulture, format, args)
                : format;
            var suppressBacktestInfo =
                IsBacktestingRuntime() &&
                string.Equals((level ?? "").Trim(), "INFO", StringComparison.OrdinalIgnoreCase) &&
                !string.IsNullOrWhiteSpace(message) &&
                (message.StartsWith("[Backtest] Skip", StringComparison.OrdinalIgnoreCase) ||
                 message.StartsWith("[Backtest] Signal", StringComparison.OrdinalIgnoreCase) ||
                 message.StartsWith("[Backtest] price_action_event_detector_v1", StringComparison.OrdinalIgnoreCase) ||
                 message.StartsWith("[Backtest] follow_trend", StringComparison.OrdinalIgnoreCase));
            if (suppressBacktestInfo)
                return;

            TryShowPopupAlert(level, message);
            if (!ShouldEmitLog(level, message))
            {
                _suppressedLogCount++;
                return;
            }

            _lastPanelMessage = message;
            _lastPanelMessageIsError =
                string.Equals((level ?? "").Trim(), "ERROR", StringComparison.OrdinalIgnoreCase) ||
                message.IndexOf("[Error]", StringComparison.OrdinalIgnoreCase) >= 0 ||
                message.IndexOf(" failed", StringComparison.OrdinalIgnoreCase) >= 0 ||
                message.IndexOf(" rejected", StringComparison.OrdinalIgnoreCase) >= 0;
            _lastPanelMessageColor = _lastPanelMessageIsError
                ? Color.Red
                : (message.IndexOf("TRADELOG|", StringComparison.OrdinalIgnoreCase) >= 0 && message.IndexOf("status=SUCCEEDED", StringComparison.OrdinalIgnoreCase) >= 0
                    ? Color.LimeGreen
                    : Color.White);
            // cTrader's Print() has no log levels, so tag error lines in the text itself — this
            // is what shows up as the log "category" in the cTrader log tab.
            var printMessage = string.Equals((level ?? "").Trim(), "ERROR", StringComparison.OrdinalIgnoreCase)
                ? "[Error] " + message
                : message;
            BeginInvokeOnMainThread(() => Print(printMessage));
        }

        private string ToStructuredLogField(string value)
        {
            var normalized = string.IsNullOrWhiteSpace(value) ? "" : value.Trim();
            normalized = normalized.Replace("|", "/").Replace("\r", " ").Replace("\n", " ");
            return normalized;
        }

        private string ToStructuredLogNumber(double value, int decimals)
        {
            if (double.IsNaN(value) || double.IsInfinity(value))
                return "";

            var safeDecimals = Math.Max(0, Math.Min(8, decimals));
            return value.ToString("F" + safeDecimals.ToString(CultureInfo.InvariantCulture), CultureInfo.InvariantCulture);
        }

        private void LogStructuredTradeEvent(
            string scope,
            string status,
            string symbol,
            string side,
            string orderType,
            double lots,
            double entryPrice,
            double stopLoss,
            double takeProfit,
            string ticket,
            string note = "")
        {
            var level = string.Equals(status, "FAILED", StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(status, "REJECTED", StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(status, "ERROR", StringComparison.OrdinalIgnoreCase)
                ? "ERROR"
                : "INFO";

            SafeLog(
                level,
                "TRADELOG|scope={0}|status={1}|symbol={2}|side={3}|type={4}|lots={5}|entry={6}|sl={7}|tp={8}|ticket={9}|note={10}",
                ToStructuredLogField(scope),
                ToStructuredLogField(status),
                ToStructuredLogField(symbol),
                ToStructuredLogField(side),
                ToStructuredLogField(orderType),
                ToStructuredLogNumber(lots, 4),
                ToStructuredLogNumber(entryPrice, 5),
                ToStructuredLogNumber(stopLoss, 5),
                ToStructuredLogNumber(takeProfit, 5),
                ToStructuredLogField(ticket),
                ToStructuredLogField(note));
        }

        private void SafePrint(string format, params object[] args)
        {
            SafeLog("INFO", format, args);
        }

        // Temporary diagnostics: mirrors key lifecycle events to a file so startup/timer/sync
        // state can be inspected without the cTrader terminal log.
        private static readonly string DebugLogPath = "/tmp/42trade-bridge-debug.log";
        private void WriteBridgeDebugLog(string message)
        {
            if (!EnableBridgeDebugFileLogging)
                return;

            try
            {
                System.IO.File.AppendAllText(
                    DebugLogPath,
                    DateTime.UtcNow.ToString("HH:mm:ss.fff", CultureInfo.InvariantCulture) + " " + message + Environment.NewLine);
            }
            catch
            {
            }
        }

        private bool Is42TradeServerSyncEnabled()
        {
            return EnableSync == YesNoMode.Yes;
        }

        private int GetEffectiveMasterTimerSeconds()
        {
            return Math.Max(MinimumMasterTimerSeconds, MasterTimerSeconds);
        }

        private bool ShouldUseLocalRuntime()
        {
            return !Is42TradeServerSyncEnabled() || IsApiOfflineCooldownActive(DateTime.Now);
        }

        private bool IsBarsPersistenceEnabled()
        {
            return EnableBarsSave == YesNoMode.Yes;
        }

        private string GetLocalRuntimeBridgePath()
        {
            return Path.Combine(GetBaseServerRootPath(), "src", "mt5-bridge", "clients", "LocalRuntimeBridge.js");
        }

        private string QuoteProcessArgument(string value)
        {
            var raw = value ?? "";
            return "\"" + raw.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";
        }

        private string ResolveNodeExecutable()
        {
            var candidates = new[]
            {
                "/opt/homebrew/bin/node",
                "/usr/local/bin/node",
                "/usr/bin/node"
            };
            foreach (var candidate in candidates)
            {
                try
                {
                    if (System.IO.File.Exists(candidate))
                        return candidate;
                }
                catch
                {
                }
            }
            return "node";
        }

        private string RunLocalRuntime(Dictionary<string, object> payload)
        {
            var bridgePath = GetLocalRuntimeBridgePath();
            if (!System.IO.File.Exists(bridgePath))
                throw new FileNotFoundException("Local runtime bridge not found", bridgePath);

            var info = new ProcessStartInfo
            {
                FileName = ResolveNodeExecutable(),
                Arguments = QuoteProcessArgument(bridgePath) + " -",
                UseShellExecute = false,
                CreateNoWindow = true,
                RedirectStandardInput = true,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
            };
            var projectRoot = GetBaseServerRootPath();
            if (Directory.Exists(projectRoot))
                info.WorkingDirectory = projectRoot;
            using (var process = Process.Start(info))
            {
                if (process == null) throw new InvalidOperationException("Unable to start node local runtime");
                var outputTask = process.StandardOutput.ReadToEndAsync();
                var errorTask = process.StandardError.ReadToEndAsync();
                process.StandardInput.Write(SerializeJsonValue(payload));
                process.StandardInput.Close();
                if (!process.WaitForExit(Math.Max(5000, SyncTimeoutSeconds * 1000)))
                {
                    try { process.Kill(); } catch { }
                    throw new TimeoutException("Local runtime timed out");
                }
                var output = outputTask.GetAwaiter().GetResult();
                var error = errorTask.GetAwaiter().GetResult();
                if (process.ExitCode != 0)
                    throw new Exception(string.IsNullOrWhiteSpace(error) ? "Local runtime failed" : error.Trim());
                if (!string.IsNullOrWhiteSpace(error))
                    SafePrint("[LocalIO] {0}", error.Trim());
                return output.Trim();
            }
        }

        private Task<string> RunLocalRuntimeAsync(Dictionary<string, object> payload)
        {
            return Task.Run(() => RunLocalRuntime(payload));
        }

        private string LocalRuntimeUserId()
        {
            return string.IsNullOrWhiteSpace(LocalUserId) ? DefaultBacktestUserId : LocalUserId.Trim();
        }

        private bool AreChartVisualsEnabled()
        {
            return EnableChartVisuals == YesNoMode.Yes;
        }

        private void RunOnMainThread(Action fn)
        {
            BeginInvokeOnMainThread(() =>
            {
                try { fn(); }
                catch (Exception ex) { SafePrint("[MainThread] {0}", ex.Message); }
            });
        }

        private Task<T> RunOnMainThreadAsync<T>(Func<T> fn)
        {
            var tcs = new TaskCompletionSource<T>();
            BeginInvokeOnMainThread(() =>
            {
                try { tcs.SetResult(fn()); }
                catch (Exception ex) { tcs.SetException(ex); }
            });
            return tcs.Task;
        }

        protected override void OnStart()
        {
            ValidateStructureEngineV2Contracts();
            ValidateStrategyEngineContracts();
            ValidateExecutionEngineContracts();
            ValidateSyncEngineContracts();
            ValidateChartEngineContracts();
            _startedAtUtc = DateTime.UtcNow;
            _startupWarmupUntilUtc = _startedAtUtc.AddSeconds(12);
            _startupWarmupAnnounced = false;
            _lastStopReason = "running";
            if (DisableBridgeRuntimeForIsolation)
            {
                try
                {
                    Chart.DrawStaticText(
                        "Bridge_Isolation_Status",
                        "[Bridge] Isolation build active",
                        VerticalAlignment.Top,
                        HorizontalAlignment.Left,
                        Color.Yellow);
                }
                catch
                {
                }
                PrintBypassLogFilter("[Bridge] Isolation build active: OnStart early return");
                return;
            }
            Positions.Closed += OnStrategyPositionClosed;
            // Clean slate: sweep every object this bot can draw before (re)drawing. If the
            // previous session ended uncleanly (force stop, cTrader restart), stale markers,
            // zones and grids from an older build would otherwise linger on the chart.
            try { RemoveChartVisualObjects(); } catch (Exception ex) { SafePrint("[Visuals] Startup object sweep failed: {0}", ex.Message); }
            LoadCustomUiSettings();
            if (!DisableOnStartExtrasForIsolation)
                StartBacktestExportSession();
            if (Is42TradeServerSyncEnabled() &&
                !string.IsNullOrWhiteSpace(ServerBaseUrl) &&
                ServerBaseUrl.IndexOf("localhost", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                ServerBaseUrl = Regex.Replace(
                    ServerBaseUrl,
                    "localhost",
                    "127.0.0.1",
                    RegexOptions.IgnoreCase
                );
                SafePrint("[Bridge] Normalized ServerBaseUrl to {0}", ServerBaseUrl);
            }
            _serverStatus = Is42TradeServerSyncEnabled() ? "BOOTING" : "OFF";
            _apiStatus = Is42TradeServerSyncEnabled() ? "BOOTING" : "OFF";
            _pollStatus = Is42TradeServerSyncEnabled() ? "IDLE" : "OFF";
            _syncStatus = Is42TradeServerSyncEnabled() ? "IDLE" : "OFF";
            WriteBridgeDebugLog("OnStart: statuses set");
            RefreshRiskAnchors();
            _toggleKillerZones = DrawKillerZones != KillerZoneVisualMode.No;
            _toggleLiquidityLevels = DrawLiquidityLevels;
            _toggleSweepDetections = ResolveStructureEventToggle(DrawSweepDetections, out _sweepEventFollowUpFilter);
            _toggleBosDetections = ResolveStructureEventToggle(DrawBosDetections, out _bosEventFollowUpFilter);
            _toggleChochDetections = ResolveStructureEventToggle(DrawChochDetections, out _chochEventFollowUpFilter);
            _toggleRejectionDetections = ResolveStructureEventToggle(DrawRejectionDetections, out _rejectionEventFollowUpFilter);
            _toggleBreakoutDetections = ResolveStructureEventToggle(DrawBreakoutDetections, out _breakoutEventFollowUpFilter);
            _togglePullbackDetections = ResolveStructureEventToggle(DrawPullbackDetections, out _pullbackEventFollowUpFilter);
            _toggleContinuationDetections = ResolveStructureEventToggle(DrawContinuationDetections, out _continuationEventFollowUpFilter);
            _toggleImpulseDetections = ResolveStructureEventToggle(DrawImpulseDetections, out _impulseEventFollowUpFilter);
            _toggleTrendlines = DrawTrendlines;
            _toggleDivergence = DrawDivergence;
            _resolvedEmaOverlayConfig = ResolveEmaIndicatorConfig(DrawEmaOverlay, false);
            _resolvedVwapOverlayConfig = ResolveVwapIndicatorConfig(DrawVwapOverlay);
            _resolvedBollingerOverlayConfig = ResolveBollingerIndicatorConfig(DrawBollingerOverlay);
            _resolvedIchimokuOverlayConfig = ResolveIchimokuIndicatorConfig(DrawIchimokuOverlay);
            _resolvedEmaEventConfig = ResolveEmaIndicatorConfig(DrawEmaOverlay, true);
            _resolvedVwapEventConfig = ResolveVwapIndicatorConfig(DrawVwapOverlay);
