            _toggleThreeWhiteSoldiersPatterns = ResolveCandlePatternToggle(DrawThreeWhiteSoldiersPatterns, out _threeWhiteSoldiersPatternFollowUpFilter);
            _toggleThreeBlackCrowsPatterns = ResolveCandlePatternToggle(DrawThreeBlackCrowsPatterns, out _threeBlackCrowsPatternFollowUpFilter);
            _toggleHaramiPatterns = ResolveCandlePatternToggle(DrawHaramiPatterns, out _haramiPatternFollowUpFilter);
            _toggleFvgZones = DrawFvgZones;
            _toggleOrderBlocks = DrawOrderBlocks;
            _toggleHigherTimeframeZones = DrawHigherTimeframeZones;
            _toggleKeyLevels = DrawKeyLevels;
            _toggleSupplyDemand = DrawSupplyDemand;
            ApplyCustomUiSettingsOverrides();
            LoadWaitConfirmQueueLocal();
            ApplyChartDisplayPreferences();
            ApplyVisualGroupCombos();
            SafePrint(
                "[Mini] HTF mode={0} miniChart={1} background={2} auto1={3} auto2={4}",
                DrawHtfMiniChartMode,
                ShouldDrawHtfMiniChart(),
                ShouldDrawHtfBackground(),
                DrawAutoHtf1,
                DrawAutoHtf2);
            var isBacktesting = IsBacktestingRuntime();
            var effectiveMaxRiskPercent = GetEffectiveMaxRiskPercent();
            var effectiveMaxDailyLossPercent = GetEffectiveMaxDailyLossPercent();
            var effectiveMaxTotalOpenRiskPercent = GetEffectiveMaxTotalOpenRiskPercent();
            var effectiveMaxEquityDrawdownPercent = GetEffectiveMaxEquityDrawdownPercent();
            int interval = GetEffectiveMasterTimerSeconds();
            WriteBridgeDebugLog("OnStart: before Timer.Start interval=" + interval.ToString(CultureInfo.InvariantCulture));
            if (!DisableTimerStartupForIsolation && (!isBacktesting || ShouldRunStrategiesOnMasterTimer()))
            {
                Timer.Start(TimeSpan.FromSeconds(interval));
                WriteBridgeDebugLog("OnStart: Timer.Start called");
                _lastTimerTickSeen = DateTime.Now;
                if (!DisableWatchdogStartupForIsolation)
                    StartMasterWatchdog(interval);
            }
            if (!isBacktesting)
            {
                _chartUiBootstrapped = DisableCustomChartUiForIsolation;
            }
            if (!DisableChartPanelBootstrapForIsolation && !DisableCustomChartUiForIsolation)
            {
                WriteBridgeDebugLog("OnStart: chart controls start");
                try
                {
                    BuildChartButtonPanel();
                    _chartUiBootstrapped = true;
                }
                catch (Exception ex)
                {
                    SafePrint("[Visuals] Chart controls unavailable: {0}", ex.Message);
                }
                WriteBridgeDebugLog("OnStart: chart controls complete");
            }
            if (!isBacktesting && AreChartVisualsEnabled())
            {
                // Queue after OnStart returns so cTrader can finish attaching the robot first,
                // then render all chart objects and native indicators immediately instead of
                // waiting for warmup + two indicator ticks + the old tick-8 gate.
                BeginInvokeOnMainThread(() =>
                {
                    try
                    {
                        _forceChartVisualsRefresh = true;
                        DrawChartVisualOverlays();
                        _chartIndicatorInitializationPhase = 2;
                    }
                    catch (Exception ex)
                    {
                        SafePrint("[Visuals] Initial full refresh failed: {0}", ex.Message);
                    }
                });
            }
            SafePrint("[Bridge] Started. MasterTimer={0}s Ver={1}", interval, BuildVersion);
            SafePrint(
                "[RiskTpl] Active={0} Effective: MaxRisk={1}% MaxOpenRisk={2}% MaxDayLoss={3}% MaxDD={4}%",
                SelectedRiskTemplate,
                FormatDashboardPercent(effectiveMaxRiskPercent),
                FormatDashboardPercent(effectiveMaxTotalOpenRiskPercent),
                FormatDashboardPercent(effectiveMaxDailyLossPercent),
                FormatDashboardPercent(effectiveMaxEquityDrawdownPercent));
            SafePrint(
                "[Bars] persistence={0}; route when enabled={1}",
                IsBarsPersistenceEnabled() ? "enabled" : "disabled",
                Is42TradeServerSyncEnabled() ? "42trade API /api/broker/bars" : "local Parquet bridge");
            if (!isBacktesting && AreChartVisualsEnabled())
            {
                // Render as soon as OnStart releases the chart UI instead of waiting for the
                // warm-up/indicator timer phases to finish.
                _forceChartVisualsRefresh = true;
                RunOnMainThread(DrawChartVisualOverlays);
            }
            WriteBridgeDebugLog("OnStart: complete");
        }

