        private bool ShouldEmitTransientErrorLog()
        {
            var now = DateTime.Now;
            if (_errorStreakStartedAt == DateTime.MinValue)
                _errorStreakStartedAt = now;

            var streakSeconds = (now - _errorStreakStartedAt).TotalSeconds;
            var thresholdReached =
                _consecutiveErrors >= TransientErrorLogThresholdCount ||
                streakSeconds >= TransientErrorLogThresholdSeconds;

            if (!thresholdReached) return false;

            if (
                _lastTransientErrorLogTime != DateTime.MinValue &&
                (now - _lastTransientErrorLogTime).TotalSeconds < TransientErrorLogThresholdSeconds
            )
                return false;

            _lastTransientErrorLogTime = now;
            _errorStreakWasLogged = true;
            return true;
        }

        private void ResetTransientErrorTracking(string recoveryMessage)
        {
            var shouldLogRecovery = _consecutiveErrors > 0 && _errorStreakWasLogged;
            _consecutiveErrors = 0;
            _lastErrorClearTime = DateTime.Now;
            _errorStreakStartedAt = DateTime.MinValue;
            _lastTransientErrorLogTime = DateTime.MinValue;
            _errorStreakWasLogged = false;

            if (shouldLogRecovery)
                SafePrint(recoveryMessage);
        }

        private void StartMasterWatchdog(int intervalSec)
        {
            if (IsBacktestingRuntime() && !ShouldRunStrategiesOnMasterTimer())
                return;

            _watchdogCts = new CancellationTokenSource();
            var ct = _watchdogCts.Token;
            Task.Run(async () =>
            {
                while (!ct.IsCancellationRequested)
                {
                    try
                    {
                        await Task.Delay(TimeSpan.FromSeconds(Math.Max(2, intervalSec * 2)), ct);
                        if (ct.IsCancellationRequested) break;
                        var now = DateTime.Now;
                        var staleSec = Math.Max(5, intervalSec * 5);
                        if (_lastTimerTickSeen == DateTime.MinValue || (now - _lastTimerTickSeen).TotalSeconds >= staleSec)
                        {
                            if (Interlocked.CompareExchange(ref _watchdogKickQueued, 1, 0) == 0)
                            {
                                SafePrint("[Watchdog] Master timer stale {0}s - scheduling one recovery tick", (int)(now - _lastTimerTickSeen).TotalSeconds);
                                BeginInvokeOnMainThread(() =>
                                {
                                    try { OnTimer(); }
                                    finally { Interlocked.Exchange(ref _watchdogKickQueued, 0); }
                                });
                            }
                        }
                    }
                    catch (TaskCanceledException) { break; }
                    catch (Exception ex) { SafePrint("[Watchdog] Error: {0}", ex.Message); }
                }
            }, ct);
        }

        protected override void OnTick()
        {
            if (DisableBridgeRuntimeForIsolation)
                return;

            EnsureAutoProtectedPositions();

            if (IsStartupWarmupActive())
                return;

            if (ShouldStrategyEngineRun() && ShouldRunStrategiesOnTickEvent())
            {
                if (TryRunBacktestStrategy())
                    MarkStrategySchedulerSlotProcessed();
            }
        }

        protected override void OnBar()
        {
            if (DisableBridgeRuntimeForIsolation)
                return;

            if (IsStartupWarmupActive())
                return;

            if (ShouldRunStrategiesOnBarEvent())
                TryRunBacktestStrategy();
        }

        protected override void OnBarClosed()
        {
            if (DisableBridgeRuntimeForIsolation)
                return;

            if (IsStartupWarmupActive())
                return;

            if (ShouldStrategyEngineRun() && ShouldRunStrategiesOnBarClosedEvent())
                TryRunBacktestStrategy();

            // The master-timer visual path is intentionally disabled in backtests. Refresh the
            // lightweight all-symbol summary here instead, after the closed-bar trade update.
            if (IsBacktestingRuntime() && AreChartVisualsEnabled())
                RefreshChartSummaryPanel(BuildPanelRiskGateStateSafe());
        }

        private bool ShouldUseNativeTrailingAutoProtect()
        {
            return CTraderExecutionEngine.UsesNativeTrailing(SelectedStrategyExitMode);
        }

        private bool ShouldUseNativeBreakEvenAutoProtect()
        {
            return CTraderExecutionEngine.UsesNativeBreakEven(SelectedStrategyExitMode);
        }

        private bool ShouldReverseStoppedStrategyPosition()
        {
            return CTraderExecutionEngine.ReversesStoppedPosition(SelectedStrategyExitMode);
        }

        private void EnsureAutoProtectedPositions()
        {
            if (!ShouldUseNativeTrailingAutoProtect() && !ShouldUseNativeBreakEvenAutoProtect())
                return;
            if (Positions == null || Positions.Count == 0)
                return;

            foreach (var pos in Positions)
            {
                if (pos == null || !IsStrategyManagedExposure(pos.Label, pos.Comment))
                    continue;

                var symbol = ResolveLoadedSymbol(pos.SymbolName);
                if (symbol == null)
                    continue;

                var currentPrice = (pos.TradeType == TradeType.Buy) ? symbol.Bid : symbol.Ask;
                if (!IsFiniteNumber(currentPrice) || currentPrice <= 0)
                    continue;

                if (!pos.StopLoss.HasValue || pos.StopLoss.Value <= 0)
                    goto Partials;

                TryApplySelectedExitModeForPosition(pos);

                Partials:
                var sid = pos.Comment;
                if (!string.IsNullOrEmpty(sid) && _tradePartials.ContainsKey(sid))
                {
                    var partials = _tradePartials[sid];
                    for (int i = 0; i < partials.Count; i++)
                    {
                        var p = partials[i];
                        string pKey = pos.Id + "_" + i;
                        if (_executedPartials.Contains(pKey)) continue;

                        bool hit = (pos.TradeType == TradeType.Buy) ? (currentPrice >= p.Price) : (currentPrice <= p.Price);
                        if (!hit) continue;  // price not reached yet, retry next tick

                        double volToClose = CTraderExecutionEngine.ResolveNormalizedPartialCloseVolume(
                            symbol, pos.VolumeInUnits, p.SizePct);

                        // Only close if we can meet minimum volume; skip permanently if too small
                        if (volToClose >= symbol.VolumeInUnitsMin)
                        {
                            // Cap at current remaining size (never exceed position volume)
                            if (volToClose > pos.VolumeInUnits)
                                volToClose = pos.VolumeInUnits;

                            // Re-check min volume after capping
                            if (volToClose >= symbol.VolumeInUnitsMin)
                            {
                                var res = ClosePosition(pos, volToClose);
                                if (res.IsSuccessful)
                                {
                                    _executedPartials.Add(pKey);
                                    var ticketKey = pos.Id.ToString();
                                    if (_partialClosedVolumes.ContainsKey(ticketKey))
                                        _partialClosedVolumes[ticketKey] += volToClose;
                                    else
                                        _partialClosedVolumes[ticketKey] = volToClose;
                                    SafePrint("[Partial] Closed {0} units ({1}%) for {2} at {3}", volToClose, p.SizePct, pos.Id, p.Price);
                                    // Immediate ack partial close to VPS
                                    if (!string.IsNullOrEmpty(sid))
                                        SafeAck(sid, "", "PARTIAL_CLOSE", pos.Id.ToString(), "", 0);
                                }
                                else
                                {
                                    SafePrint("[Partial] Close failed for {0}: {1}", pos.Id, res.Error);
                                }
                            }
                            else
                            {
                                _executedPartials.Add(pKey);
                                SafePrint("[Partial] Skipped {0} idx {1} (post-cap too small: {2} < min {3})", pos.Id, i, volToClose, symbol.VolumeInUnitsMin);
                            }
                        }
                        else
                        {
                            _executedPartials.Add(pKey);
                            SafePrint("[Partial] Skipped {0} idx {1} (chunk too small: {2} < min {3})", pos.Id, i, volToClose, symbol.VolumeInUnitsMin);
                        }
                    }
                }
            }
        }

        private void TryApplySelectedExitModeForPosition(Position position)
        {
            if (position == null)
                return;

            if (!IsStrategyManagedExposure(position.Label, position.Comment))
                return;

            if (!position.StopLoss.HasValue || position.StopLoss.Value <= 0)
                return;

            if (ShouldUseNativeTrailingAutoProtect())
            {
                if (position.HasTrailingStop)
                    return;

                try
                {
                    var result = position.ModifyTrailingStop(true);
                    if (result != null && result.IsSuccessful)
                        SafePrint("[AutoProtect] TrailingStop enabled for {0} #{1}", position.SymbolName, position.Id);
                }
                catch (Exception ex)
                {
                    SafePrint("[AutoProtect] TrailingStop enable FAILED for {0} #{1}: {2}", position.SymbolName, position.Id, ex.Message);
                }
                return;
            }

            if (!ShouldUseNativeBreakEvenAutoProtect())
                return;

            var symbol = ResolveLoadedSymbol(position.SymbolName);
            if (symbol == null || symbol.PipSize <= 0)
                return;

            var triggerPips = CTraderExecutionEngine.ResolveBreakEvenTriggerPips(
                position.EntryPrice, position.StopLoss.Value, symbol.PipSize);
            try
            {
                TradeResult result;
                if (!TryModifyStopLossBreakEvenCompat(position, triggerPips, out result))
                    return;
                if (result != null && result.IsSuccessful)
                    SafePrint("[AutoProtect] BreakEven enabled at {0:F1} pips for {1} #{2}", triggerPips, position.SymbolName, position.Id);
            }
            catch (Exception ex)
            {
                SafePrint("[AutoProtect] BreakEven enable FAILED for {0} #{1}: {2}", position.SymbolName, position.Id, ex.Message);
            }
        }

        private bool TryModifyStopLossBreakEvenCompat(Position position, double triggerPips, out TradeResult result)
        {
            result = null;
            if (position == null)
                return false;

            try
            {
                var positionType = position.GetType();
                var assembly = positionType.Assembly;
                var breakEvenType = assembly.GetType("cAlgo.API.StopLossBreakEven", false);
                if (breakEvenType == null)
                {
                    foreach (var loadedAssembly in AppDomain.CurrentDomain.GetAssemblies())
                    {
                        breakEvenType = loadedAssembly.GetType("cAlgo.API.StopLossBreakEven", false);
                        if (breakEvenType != null)
                            break;
                    }
                }
                if (breakEvenType == null)
                {
                    if (!_breakEvenApiUnavailableLogged)
                    {
                        _breakEvenApiUnavailableLogged = true;
                        SafePrint("[AutoProtect] BreakEven API unavailable in this cTrader runtime; skipping native BreakEven.");
                    }
                    return false;
                }

                var breakEven = Activator.CreateInstance(breakEvenType, triggerPips, 0);
                var method = positionType.GetMethod(
                    "ModifyStopLossBreakEven",
                    BindingFlags.Instance | BindingFlags.Public,
                    null,
                    new[] { breakEvenType },
                    null);
                if (method == null)
                {
                    if (!_breakEvenApiUnavailableLogged)
                    {
                        _breakEvenApiUnavailableLogged = true;
                        SafePrint("[AutoProtect] BreakEven method unavailable in this cTrader runtime; skipping native BreakEven.");
                    }
                    return false;
                }

                result = method.Invoke(position, new[] { breakEven }) as TradeResult;
                return result != null;
            }
            catch (Exception ex)
            {
                SafePrint("[AutoProtect] BreakEven compatibility call failed: {0}", ex.Message);
                return false;
            }
        }

        private void OnStrategyPositionClosed(PositionClosedEventArgs args)
        {
            InvalidateDailyClosedRiskCache();
            if (!ShouldReverseStoppedStrategyPosition() ||
                args == null ||
                args.Reason != PositionCloseReason.StopLoss ||
                args.Position == null)
                return;

            var closedPosition = args.Position;
            if (!IsStrategyManagedExposure(closedPosition.Label, closedPosition.Comment))
                return;

            var closedComment = closedPosition.Comment ?? "";
            var closedLabel = closedPosition.Label ?? "";
            if (closedComment.IndexOf("|rev:1", StringComparison.OrdinalIgnoreCase) >= 0 ||
                closedLabel.EndsWith(":REV", StringComparison.OrdinalIgnoreCase))
                return;

            var symbol = ResolveLoadedSymbol(closedPosition.SymbolName);
            if (symbol == null || symbol.PipSize <= 0 || !closedPosition.StopLoss.HasValue)
            {
                SafePrint("[ExitMode] Reverse skipped for #{0}: symbol or original SL unavailable", closedPosition.Id);
                return;
            }

            CTraderExecutionReversePlan reversePlan;
            if (!CTraderExecutionEngine.TryBuildReversePlan(
                    symbol,
                    closedPosition.TradeType,
                    closedPosition.EntryPrice,
                    closedPosition.StopLoss.Value,
                    symbol.Bid,
                    symbol.Ask,
                    StrategyRewardRisk,
                    out reversePlan))
            {
                if (string.Equals(reversePlan.Error, "invalid_original_risk_distance", StringComparison.Ordinal))
                    SafePrint("[ExitMode] Reverse skipped for #{0}: invalid original risk distance", closedPosition.Id);
                return;
            }

            var reverseTradeType = reversePlan.TradeType;
            var action = reversePlan.Action;
            var executionPrice = reversePlan.EntryPrice;
            var requestedSl = reversePlan.StopLoss;
            var requestedTp = reversePlan.TakeProfit;

            var requestedRiskMoney = EstimateRiskAmount(
                symbol,
                reverseTradeType,
                executionPrice,
                requestedSl,
                closedPosition.VolumeInUnits);
            if (!(requestedRiskMoney > 0))
            {
                SafePrint("[ExitMode] Reverse skipped for #{0}: risk could not be calculated", closedPosition.Id);
                return;
            }

            double approvedSl;
            double approvedTp;
            double approvedVolumeUnits;
            double approvedRiskMoney;
            double marginEstimate;
            double marginBudget;
            string rejectReason;
            if (!TryPassSharedCreationGate(
                symbol,
                action,
                "market",
                0,
                executionPrice,
                requestedSl,
                requestedTp,
                closedPosition.VolumeInUnits,
                requestedRiskMoney,
                requestedRiskMoney,
                out approvedSl,
                out approvedTp,
                out approvedVolumeUnits,
                out approvedRiskMoney,
                out marginEstimate,
                out marginBudget,
                out rejectReason))
            {
                SafePrint("[ExitMode] Reverse rejected for #{0}: {1}", closedPosition.Id, rejectReason);
                return;
            }

            var slPips = CTraderExecutionEngine.ResolveDistancePips(symbol, executionPrice, approvedSl).GetValueOrDefault();
            var tpPips = CTraderExecutionEngine.ResolveDistancePips(symbol, executionPrice, approvedTp).GetValueOrDefault();
            var reverseLabel = string.IsNullOrWhiteSpace(closedLabel) ? "strategy:REV" : closedLabel + ":REV";
            var reverseComment = closedComment + "|rev:1";
            var result = ExecuteMarketOrder(
                reverseTradeType,
                symbol.Name,
                approvedVolumeUnits,
                reverseLabel,
                slPips,
                tpPips,
                reverseComment);
            if (result == null || !result.IsSuccessful || result.Position == null)
            {
                SafePrint(
                    "[ExitMode] Reverse submit failed for #{0}: {1}",
                    closedPosition.Id,
                    result != null ? Convert.ToString(result.Error, CultureInfo.InvariantCulture) : "null_result");
                return;
            }

            var finalApprovedSl = approvedSl;
            var finalApprovedTp = approvedTp;
            ReanchorProtectionToFilledEntry(
                symbol,
                action,
                executionPrice,
                result.Position.EntryPrice,
                ref finalApprovedSl,
                ref finalApprovedTp);
            string protectionError;
            if (!TryEnsureStrategyPositionProtection(
                result.Position,
                symbol,
                action,
                finalApprovedSl,
                finalApprovedTp,
                out protectionError))
            {
                var closeResult = ClosePosition(result.Position);
                SafePrint(
                    "[ExitMode] Reverse #{0} closed after protection failure: {1}; close={2}",
                    result.Position.Id,
                    protectionError,
                    closeResult != null && closeResult.IsSuccessful ? "ok" : "failed");
                return;
            }

            SafePrint(
                "[ExitMode] Reversed stopped position #{0} into #{1} {2} {3}; risk={4:F2}",
                closedPosition.Id,
                result.Position.Id,
                action,
                symbol.Name,
                approvedRiskMoney);
        }

        private void BeginMasterTimerAccountSnapshotScope()
        {
            _masterTimerPositionsSnapshot = null;
            _masterTimerPendingOrdersSnapshot = null;
            _masterTimerActiveSymbolsSnapshot = null;
            _masterTimerAccountSnapshotActive = true;
        }

        private void ClearMasterTimerAccountSnapshotScope()
        {
            _masterTimerAccountSnapshotActive = false;
            _masterTimerPositionsSnapshot = null;
            _masterTimerPendingOrdersSnapshot = null;
            _masterTimerActiveSymbolsSnapshot = null;
        }

        private void BeginMasterTimerBarsCacheScope()
        {
            _cacheEngine.BeginMasterTimerScope(Thread.CurrentThread.ManagedThreadId);
        }

        private void ClearMasterTimerBarsCacheScope()
        {
            _cacheEngine.EndMasterTimerScope();
        }

        private Bars GetBarsForCurrentMasterTimer(TimeFrame timeFrame, string symbolName)
        {
            // Avoid a redundant MarketData request for the current chart. This keeps local
            // visuals available when the broker has supplied the chart but has not listed the
            // symbol in its global symbol collection. Chart.TryChangeTimeFrameAndSymbol can
            // change the visible symbol without changing the robot's Bars/ Symbol context, so
            // only reuse Bars when the requested symbol also matches the attached robot symbol.
            if (Bars != null && Chart != null && timeFrame == Chart.TimeFrame &&
                Symbol != null &&
                string.Equals(NormalizeSymbolAlias(symbolName), NormalizeSymbolAlias(Chart.SymbolName), StringComparison.OrdinalIgnoreCase) &&
                string.Equals(NormalizeSymbolAlias(symbolName), NormalizeSymbolAlias(Symbol.Name), StringComparison.OrdinalIgnoreCase))
                return Bars;

            string brokerSymbol;
            if (!TryResolveBrokerSymbol(symbolName, out brokerSymbol))
                return null;

            return _cacheEngine.GetOrLoadMasterTimerBars(
                Thread.CurrentThread.ManagedThreadId,
                brokerSymbol,
                timeFrame,
                () => MarketData.GetBars(timeFrame, brokerSymbol));
        }

        // The visible chart can be switched to another symbol while the cBot remains attached
        // to its original Symbol/Bars. All chart geometry must therefore use bars belonging to
        // Chart.SymbolName instead of assuming the robot Bars collection owns the visible axis.
        private Bars GetCurrentChartVisualBars()
        {
            if (Chart == null)
                return Bars;

            var chartSymbolName = Chart.SymbolName;
            if (string.IsNullOrWhiteSpace(chartSymbolName))
                return Bars;

            try
            {
                return GetBarsForCurrentMasterTimer(Chart.TimeFrame, chartSymbolName);
            }
            catch
            {
                return null;
            }
        }

        private List<Position> GetCurrentPositionsSnapshot()
        {
            if (!_masterTimerAccountSnapshotActive)
                return Positions != null ? Positions.ToList() : new List<Position>();

            if (_masterTimerPositionsSnapshot == null)
                _masterTimerPositionsSnapshot = Positions != null ? Positions.ToList() : new List<Position>();
            return _masterTimerPositionsSnapshot;
        }

        private List<PendingOrder> GetCurrentPendingOrdersSnapshot()
        {
            if (!_masterTimerAccountSnapshotActive)
                return PendingOrders != null ? PendingOrders.ToList() : new List<PendingOrder>();

            if (_masterTimerPendingOrdersSnapshot == null)
                _masterTimerPendingOrdersSnapshot = PendingOrders != null ? PendingOrders.ToList() : new List<PendingOrder>();
            return _masterTimerPendingOrdersSnapshot;
        }

        protected override void OnTimer()
        {
            if (DisableBridgeRuntimeForIsolation)
                return;

            if (Interlocked.CompareExchange(ref _masterTimerActive, 1, 0) != 0)
            {
                Interlocked.Increment(ref _masterTimerSkippedTicks);
                return;
            }

            var timerStopwatch = Stopwatch.StartNew();
            try
            {
                BeginMasterTimerBarsCacheScope();
                _lastTimerTickSeen = DateTime.Now;
                _masterTickCount++;
                _masterTimerTick = DateTime.Now;
                if (_masterTickCount <= 3 || _masterTickCount % 60 == 0)
                    WriteBridgeDebugLog("OnTimer tick=" + _masterTickCount.ToString(CultureInfo.InvariantCulture));
                MasterTimerTick();
            }
            catch (Exception ex)
            {
                WriteBridgeDebugLog("OnTimer EXCEPTION: " + ex.Message);
                SafePrint("[Timer] ERROR: {0}: {1}", ex.GetType().Name, ex.Message);
            }
            finally
            {
                ClearMasterTimerBarsCacheScope();
                ClearMasterTimerAccountSnapshotScope();
                timerStopwatch.Stop();
                _lastMasterTimerDurationMs = timerStopwatch.ElapsedMilliseconds;
                _masterTimerDurationsMs.Enqueue(_lastMasterTimerDurationMs);
                while (_masterTimerDurationsMs.Count > 120)
                    _masterTimerDurationsMs.Dequeue();
                if (_lastMasterTimerDurationMs >= 100)
                    SafePrint("[Perf] MasterTimer: {0}ms tick={1}", _lastMasterTimerDurationMs, _masterTickCount);
                Interlocked.Exchange(ref _masterTimerActive, 0);
            }
        }

        protected override void OnException(Exception exception)
        {
            _lastStopReason = exception == null
                ? "unhandled_exception"
                : "unhandled_" + exception.GetType().Name;
            SafePrint("[Unhandled] {0}", BuildExceptionDetail(exception));
        }

        private bool IsBacktestingRuntime()
        {
            var cachedState = Volatile.Read(ref _backtestingRuntimeState);
            if (cachedState >= 0)
                return cachedState == 1;

            var isBacktesting = false;
            try
            {
                var runningMode = TryGetPropertyValue(this, "RunningMode");
                var runningModeText = runningMode != null
                    ? Convert.ToString(runningMode, CultureInfo.InvariantCulture) ?? ""
                    : "";
                if (runningModeText.IndexOf("BACKTEST", StringComparison.OrdinalIgnoreCase) >= 0 ||
                    runningModeText.IndexOf("OPTIM", StringComparison.OrdinalIgnoreCase) >= 0)
                    isBacktesting = true;
            }
            catch
            {
            }

            if (!isBacktesting)
            {
                try
                {
                    var raw = TryGetPropertyValue(this, "IsBacktesting");
                    if (raw is bool directBool)
                        isBacktesting = directBool;
                    else if (raw != null)
                        isBacktesting = Convert.ToBoolean(raw, CultureInfo.InvariantCulture);
                }
                catch
                {
                }
            }

            Volatile.Write(ref _backtestingRuntimeState, isBacktesting ? 1 : 0);
            return isBacktesting;
        }

