        private bool TryGetBacktestStrategyBars(string symbolName, out Symbol symbol, out Bars sourceBars, out int signalIndex, out int previousIndex)
        {
            return TryGetBacktestStrategyBars(symbolName, Chart != null ? Chart.TimeFrame : TimeFrame.Minute, out symbol, out sourceBars, out signalIndex, out previousIndex);
        }

        private int GetStrategySignalBarIndex(Bars sourceBars)
        {
            if (sourceBars == null)
                return -1;

            return sourceBars.Count - 2;
        }

        private bool TryGetBacktestStrategyBars(string symbolName, TimeFrame sourceTimeFrame, out Symbol symbol, out Bars sourceBars, out int signalIndex, out int previousIndex)
        {
            symbol = ResolveLoadedSymbol(symbolName);
            sourceBars = null;
            signalIndex = -1;
            previousIndex = -1;

            if (symbol == null || string.IsNullOrWhiteSpace(symbolName))
                return false;

            try
            {
                sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, symbolName);
                if (sourceBars == null || sourceBars.Count < 8)
                    return false;

                signalIndex = GetStrategySignalBarIndex(sourceBars);
                previousIndex = signalIndex - 1;
                return signalIndex >= 2 && previousIndex >= 1;
            }
            catch
            {
                return false;
            }
        }

        private bool ShouldRunLiveStrategyForNewClosedBar(BacktestStrategyMode mode, string strategySymbolName, TimeFrame strategyTimeFrame)
        {
            if (IsBacktestingRuntime())
                return true;

            Symbol strategySymbol;
            Bars strategyBars;
            int signalIndex;
            int previousIndex;
            if (!TryGetBacktestStrategyBars(strategySymbolName, strategyTimeFrame, out strategySymbol, out strategyBars, out signalIndex, out previousIndex))
            {
                LogStrategyInfoOnce(
                    GetBacktestStrategyModeDisplayName(mode),
                    string.IsNullOrWhiteSpace(strategySymbolName) ? "UNKNOWN" : strategySymbolName,
                    string.Format(CultureInfo.InvariantCulture, "bars unavailable on {0}", GetMiniChartLabel(strategyTimeFrame)));
                return false;
            }

            if (strategyBars == null || signalIndex < 0 || signalIndex >= strategyBars.Count)
                return false;

            var barTime = strategyBars.OpenTimes[signalIndex];
            var liveBarKey = string.Format(
                CultureInfo.InvariantCulture,
                "{0}|{1}|{2}",
                mode,
                string.IsNullOrWhiteSpace(strategySymbolName) ? "" : strategySymbolName.Trim().ToUpperInvariant(),
                strategyTimeFrame);
            long lastTicks;
            if (_liveStrategyLastProcessedBarTicks.TryGetValue(liveBarKey, out lastTicks) && lastTicks == barTime.Ticks)
                return false;

            return true;
        }

        private void MarkLiveStrategyBarProcessed(BacktestStrategyMode mode, string strategySymbolName, TimeFrame strategyTimeFrame)
        {
            if (IsBacktestingRuntime())
                return;

            Symbol strategySymbol;
            Bars strategyBars;
            int signalIndex;
            int previousIndex;
            if (!TryGetBacktestStrategyBars(strategySymbolName, strategyTimeFrame, out strategySymbol, out strategyBars, out signalIndex, out previousIndex) ||
                strategyBars == null || signalIndex < 0 || signalIndex >= strategyBars.Count)
                return;

            var liveBarKey = string.Format(
                CultureInfo.InvariantCulture,
                "{0}|{1}|{2}",
                mode,
                string.IsNullOrWhiteSpace(strategySymbolName) ? "" : strategySymbolName.Trim().ToUpperInvariant(),
                strategyTimeFrame);
            _liveStrategyLastProcessedBarTicks[liveBarKey] = strategyBars.OpenTimes[signalIndex].Ticks;
        }

        private bool ShouldProcessStrategyTargetForNewClosedBar(string symbolName, TimeFrame timeFrame)
        {
            if (IsBacktestingRuntime())
            {
                // Backtests use the same once-per-closed-bar gate as live mode. The timer's
                // one-minute heartbeat can therefore update Scan without reopening a trade.
                Bars backtestBars;
                try { backtestBars = GetBarsForCurrentMasterTimer(timeFrame, symbolName); }
                catch { backtestBars = null; }
                if (backtestBars == null || backtestBars.Count < 3)
                {
                    LogStrategyTargetScan(DateTime.UtcNow, symbolName, timeFrame, DateTime.MinValue, DateTime.MinValue, "bars_unavailable");
                    return false;
                }

                var backtestClosedIndex = backtestBars.Count - 2;
                var backtestBarOpen = backtestBars.OpenTimes[backtestClosedIndex];
                var backtestBarTicks = backtestBarOpen.Ticks;
                var backtestKey = string.Format(
                    CultureInfo.InvariantCulture,
                    "{0}|{1}",
                    string.IsNullOrWhiteSpace(symbolName) ? "" : symbolName.Trim().ToUpperInvariant(),
                    timeFrame);
                long previousBacktestTicks;
                if (_strategyTargetLastProcessedBarTicks.TryGetValue(backtestKey, out previousBacktestTicks) && previousBacktestTicks == backtestBarTicks)
                {
                    LogStrategyTargetScan(
                        DateTime.UtcNow,
                        symbolName,
                        timeFrame,
                        backtestBarOpen,
                        ResolveSourceBarEndTime(backtestBars, backtestBarOpen, timeFrame),
                        "same_bar");
                    return false;
                }
                LogStrategyTargetScan(
                    DateTime.UtcNow,
                    symbolName,
                    timeFrame,
                    backtestBarOpen,
                    ResolveSourceBarEndTime(backtestBars, backtestBarOpen, timeFrame),
                    "process_backtest");
                return true;
            }

            Bars bars;
            try { bars = GetBarsForCurrentMasterTimer(timeFrame, symbolName); }
            catch { bars = null; }
            if (bars == null || bars.Count < 3)
            {
                LogStrategyTargetScan(DateTime.UtcNow, symbolName, timeFrame, DateTime.MinValue, DateTime.MinValue, "bars_unavailable");
                return false;
            }

            var latestClosedIndex = bars.Count - 2;
            var barTicks = bars.OpenTimes[latestClosedIndex].Ticks;
            var barOpenTime = bars.OpenTimes[latestClosedIndex];
            var closedAt = ResolveSourceBarEndTime(bars, barOpenTime, timeFrame);
            // Scheduler diagnostics and startup freshness use wall-clock UTC, never Server.Time.
            // Server.Time follows the latest market tick and can freeze over a weekend.
            var detectedAt = DateTime.UtcNow;
            var key = string.Format(
                CultureInfo.InvariantCulture,
                "{0}|{1}",
                string.IsNullOrWhiteSpace(symbolName) ? "" : symbolName.Trim().ToUpperInvariant(),
                timeFrame);
            long previousTicks;
            if (_strategyTargetLastProcessedBarTicks.TryGetValue(key, out previousTicks) && previousTicks == barTicks)
            {
                LogStrategyTargetScan(detectedAt, symbolName, timeFrame, barOpenTime, closedAt, "same_bar");
                return false;
            }

            if (previousTicks == 0)
            {
                var ageSeconds = (detectedAt - closedAt).TotalSeconds;
                var freshnessSeconds = Math.Max(120, Math.Max(StrategyScanSeconds * 2, GetEffectiveMasterTimerSeconds() * 3));
                if (ageSeconds > freshnessSeconds)
                {
                    SafePrint(
                        "[Strategy] Seeded stale startup bar without detection: {0} {1} close={2:yyyy-MM-dd HH:mm:ss} age={3:0}s freshness={4}s",
                        symbolName,
                        GetTimeFrameShortLabel(timeFrame),
                        closedAt,
                        ageSeconds,
                        freshnessSeconds);
                    LogStrategyTargetScan(detectedAt, symbolName, timeFrame, barOpenTime, closedAt, "stale_startup");
                    // This is an intentional startup skip, not an evaluation failure.
                    // Record it so the same historical bar is not retried every scheduler slot.
                    _strategyTargetLastProcessedBarTicks[key] = barTicks;
                    return false;
                }
            }
            LogStrategyTargetScan(detectedAt, symbolName, timeFrame, barOpenTime, closedAt, "process");
            return true;
        }

        private void LogStrategyTargetScan(DateTime checkedAt, string symbolName, TimeFrame timeFrame, DateTime barOpenTime, DateTime closedAt, string status)
        {
            var normalizedSymbol = string.IsNullOrWhiteSpace(symbolName) ? "?" : symbolName.Trim().ToUpperInvariant();
            var timeFrameLabel = GetTimeFrameShortLabel(timeFrame);
            var rowKey = normalizedSymbol + "|" + timeFrameLabel;
            _lastStrategyScanDashboardAt = checkedAt;
            _strategyScanDashboardRows[rowKey] = new StrategyScanRow
            {
                SymbolName = normalizedSymbol,
                TimeFrame = timeFrame,
                BarOpenTime = barOpenTime,
                BarClosedTime = closedAt,
                Status = status ?? ""
            };
        }

        // MarketData timestamps are UTC because the robot runs in UTC. Convert that fixed
        // instant for display only; never derive an offset from the stale Server.Time clock.
        private DateTime GetStrategyScanDisplayTime(DateTime rawTime)
        {
            if (rawTime == DateTime.MinValue)
                return rawTime;
            return TimeZoneInfo.ConvertTimeFromUtc(NormalizeBotTimeToUtc(rawTime), TimeZoneInfo.Local);
        }

        private List<string> BuildStrategyScanSummaryLines()
        {
            return _strategyScanDashboardRows.Values
                .GroupBy(row => row.SymbolName ?? "?")
                .OrderBy(group => group.Key, StringComparer.OrdinalIgnoreCase)
                .Select(group => group.Key + " " + string.Join(" ", group
                    .OrderBy(row => TimeFrameToMinutes(row.TimeFrame))
                    .Select(row => GetTimeFrameShortLabel(row.TimeFrame) + "." +
                        (row.BarClosedTime == DateTime.MinValue
                            ? "-"
                            : GetStrategyScanDisplayTime(row.BarClosedTime).ToString("HHmm", CultureInfo.InvariantCulture)))))
                .ToList();
        }

        private void LogStrategyScanSummary()
        {
            var lines = BuildStrategyScanSummaryLines();
            if (lines.Count == 0)
                return;
            SafePrint(
                "[StrategyScan] {0:HH:mm:ss} local | {1}",
                GetStrategyScanDisplayTime(_lastStrategyScanDashboardAt),
                string.Join(" | ", lines));
        }

        private string BuildStrategyScanDashboardText()
        {
            if (!IsBacktestingRuntime() && !EnableLiveStrategyTrading)
                return "disabled (Enable CBot Auto trade=No)";

            var staleAfterSeconds = Math.Max(15, Math.Max(StrategyScanSeconds * 2, GetEffectiveMasterTimerSeconds() * 3));
            if (!IsBacktestingRuntime() && _lastTimerTickSeen != DateTime.MinValue)
            {
                var timerAgeSeconds = Math.Max(0, (DateTime.Now - _lastTimerTickSeen).TotalSeconds);
                if (timerAgeSeconds > staleAfterSeconds)
                    return string.Format(CultureInfo.InvariantCulture, "stale timer={0:0}s", timerAgeSeconds);
            }
            if (!IsBacktestingRuntime() && _lastStrategyEngineScanUtc != DateTime.MinValue)
            {
                var engineAgeSeconds = Math.Max(0, (DateTime.UtcNow - _lastStrategyEngineScanUtc).TotalSeconds);
                if (engineAgeSeconds > staleAfterSeconds)
                    return string.Format(CultureInfo.InvariantCulture, "stale engine={0:0}s", engineAgeSeconds);
            }

            if (_lastStrategyScanDashboardAt == DateTime.MinValue || _strategyScanDashboardRows.Count == 0)
                return "waiting";

            const int maxSymbols = 3;
            var rows = BuildStrategyScanSummaryLines();
            var suffix = rows.Count > maxSymbols
                ? string.Format(CultureInfo.InvariantCulture, "\n      +{0}", rows.Count - maxSymbols)
                : "";
            return string.Format(
                CultureInfo.InvariantCulture,
                "{0:HH:mm:ss} local\n      {1}{2}",
                GetStrategyScanDisplayTime(_lastStrategyScanDashboardAt),
                string.Join("\n      ", rows.Take(maxSymbols)),
                suffix);
        }

        private string BuildMasterTimerDashboardText()
        {
            if (_lastTimerTickSeen == DateTime.MinValue)
                return "waiting";
            var ageSeconds = Math.Max(0, (DateTime.Now - _lastTimerTickSeen).TotalSeconds);
            var staleAfterSeconds = Math.Max(15, Math.Max(StrategyScanSeconds * 2, GetEffectiveMasterTimerSeconds() * 3));
            var samples = _masterTimerDurationsMs.OrderBy(value => value).ToArray();
            var p95Index = samples.Length == 0 ? 0 : Math.Min(samples.Length - 1, (int)Math.Ceiling(samples.Length * 0.95) - 1);
            var p95Milliseconds = samples.Length == 0 ? 0 : samples[p95Index];
            return string.Format(
                CultureInfo.InvariantCulture,
                "{0:HH:mm:ss} local age={1:0}s last={2}ms p95={3}ms skip={4}{5}",
                _lastTimerTickSeen,
                ageSeconds,
                _lastMasterTimerDurationMs,
                p95Milliseconds,
                Interlocked.Read(ref _masterTimerSkippedTicks),
                ageSeconds > staleAfterSeconds ? " STALE" : " OK");
        }

        private void MarkStrategyTargetBarProcessed(string symbolName, TimeFrame timeFrame)
        {
            Bars bars;
            try { bars = GetBarsForCurrentMasterTimer(timeFrame, symbolName); }
            catch { bars = null; }
            if (bars == null || bars.Count < 3)
                return;

            var key = string.Format(
                CultureInfo.InvariantCulture,
                "{0}|{1}",
                string.IsNullOrWhiteSpace(symbolName) ? "" : symbolName.Trim().ToUpperInvariant(),
                timeFrame);
            _strategyTargetLastProcessedBarTicks[key] = bars.OpenTimes[bars.Count - 2].Ticks;
        }

        private double ComputeSimpleMovingAverage(Bars sourceBars, int endIndex, int period)
        {
            return CTraderTechnicalEngine.ComputeSimpleMovingAverage(sourceBars, endIndex, period);
        }

        private double ComputeExponentialMovingAverage(Bars sourceBars, int endIndex, int period)
        {
            return CTraderTechnicalEngine.ComputeExponentialMovingAverage(sourceBars, endIndex, period);
        }

        private double[] BuildExponentialMovingAverageSeries(Bars sourceBars, int period)
        {
            var count = sourceBars != null ? sourceBars.Count : 0;
            var values = new double[count];
            for (var i = 0; i < count; i++)
                values[i] = double.NaN;
            if (sourceBars == null || period <= 0 || count < period)
                return values;

            double ema = 0;
            for (var i = 0; i < period; i++)
                ema += sourceBars.ClosePrices[i];
            ema /= period;
            values[period - 1] = ema;

            var multiplier = 2.0 / (period + 1.0);
            for (var i = period; i < count; i++)
            {
                ema = ((sourceBars.ClosePrices[i] - ema) * multiplier) + ema;
                values[i] = ema;
            }
            return values;
        }

        private double[] BuildRollingVwapSeries(Bars sourceBars, int length)
        {
            var count = sourceBars != null ? sourceBars.Count : 0;
            var values = new double[count];
            var priceVolumes = new double[count];
            var volumes = new double[count];
            for (var i = 0; i < count; i++)
                values[i] = double.NaN;
            if (sourceBars == null || length <= 0)
                return values;

            double sumPriceVolume = 0;
            double sumVolume = 0;
            for (var i = 0; i < count; i++)
            {
                var typical = (sourceBars.HighPrices[i] + sourceBars.LowPrices[i] + sourceBars.ClosePrices[i]) / 3.0;
                var volume = 1.0;
                try
                {
                    var tickVolume = Convert.ToDouble(sourceBars.TickVolumes[i], CultureInfo.InvariantCulture);
                    if (!double.IsNaN(tickVolume) && tickVolume > 0)
                        volume = tickVolume;
                }
                catch
                {
                }

                volumes[i] = volume;
                priceVolumes[i] = typical * volume;
                if (length == 1)
                {
                    values[i] = priceVolumes[i] / volume;
                    continue;
                }
                sumVolume += volume;
                sumPriceVolume += priceVolumes[i];
                if (i >= length)
                {
                    sumVolume -= volumes[i - length];
                    sumPriceVolume -= priceVolumes[i - length];
                }

                values[i] = sumVolume > 0 ? sumPriceVolume / sumVolume : double.NaN;
            }
            return values;
        }

        private void BuildBollingerSeries(
            Bars sourceBars,
            int period,
            double stddevMultiplier,
            out double[] midValues,
            out double[] upperValues,
            out double[] lowerValues)
        {
            var count = sourceBars != null ? sourceBars.Count : 0;
            midValues = new double[count];
            upperValues = new double[count];
            lowerValues = new double[count];
            for (var i = 0; i < count; i++)
            {
                midValues[i] = double.NaN;
                upperValues[i] = double.NaN;
                lowerValues[i] = double.NaN;
            }
            if (sourceBars == null || period <= 0)
                return;

            double sum = 0;
            double sumDeviations = 0;
            double sumSquaredDeviations = 0;
            var anchor = count > 0 && IsFiniteNumber(sourceBars.ClosePrices[0])
                ? sourceBars.ClosePrices[0]
                : 0;
            var invalidCount = 0;
            for (var i = 0; i < count; i++)
            {
                var close = sourceBars.ClosePrices[i];
                if (IsFiniteNumber(close))
                {
                    var deviation = close - anchor;
                    sum += close;
                    sumDeviations += deviation;
                    sumSquaredDeviations += deviation * deviation;
                }
                else
                {
                    invalidCount++;
                }

                if (i >= period)
                {
                    var expiredClose = sourceBars.ClosePrices[i - period];
                    if (IsFiniteNumber(expiredClose))
                    {
                        var expiredDeviation = expiredClose - anchor;
                        sum -= expiredClose;
                        sumDeviations -= expiredDeviation;
                        sumSquaredDeviations -= expiredDeviation * expiredDeviation;
                    }
                    else
                    {
                        invalidCount--;
                    }
                }

                if (i < period - 1 || invalidCount > 0)
                    continue;

                var mean = sum / period;
                var meanDeviation = sumDeviations / period;
                var variance = period == 1
                    ? 0
                    : (sumSquaredDeviations / period) - (meanDeviation * meanDeviation);
                if (variance < 0)
                    variance = 0;
                var stddev = Math.Sqrt(variance);
                midValues[i] = mean;
                upperValues[i] = mean + (stddev * stddevMultiplier);
                lowerValues[i] = mean - (stddev * stddevMultiplier);
            }
        }

        private void BuildStochasticSeries(
            Bars sourceBars,
            int period,
            int smoothPeriod,
            out double[] kValues,
            out double[] dValues)
        {
            var count = sourceBars != null ? sourceBars.Count : 0;
            kValues = new double[count];
            dValues = new double[count];
            for (var i = 0; i < count; i++)
            {
                kValues[i] = double.NaN;
                dValues[i] = double.NaN;
            }
            if (sourceBars == null || period <= 0 || smoothPeriod <= 0)
                return;

            var highDeque = new int[count];
            var lowDeque = new int[count];
            var highHead = 0;
            var highTail = 0;
            var lowHead = 0;
            var lowTail = 0;
            for (var i = 0; i < count; i++)
            {
                var windowStart = i - period + 1;
                while (highHead < highTail && highDeque[highHead] < windowStart)
                    highHead++;
                while (lowHead < lowTail && lowDeque[lowHead] < windowStart)
                    lowHead++;

                var high = sourceBars.HighPrices[i];
                while (highHead < highTail && sourceBars.HighPrices[highDeque[highTail - 1]] <= high)
                    highTail--;
                highDeque[highTail++] = i;

                var low = sourceBars.LowPrices[i];
                while (lowHead < lowTail && sourceBars.LowPrices[lowDeque[lowTail - 1]] >= low)
                    lowTail--;
                lowDeque[lowTail++] = i;

                if (i < period - 1)
                    continue;

                var highestHigh = sourceBars.HighPrices[highDeque[highHead]];
                var lowestLow = sourceBars.LowPrices[lowDeque[lowHead]];
                var range = highestHigh - lowestLow;
                kValues[i] = !IsFiniteNumber(range) || range <= 0
                    ? 50.0
                    : ((sourceBars.ClosePrices[i] - lowestLow) / range) * 100.0;

                if (i < period + smoothPeriod - 2)
                    continue;

                double smoothedSum = 0;
                var valid = true;
                for (var offset = 0; offset < smoothPeriod; offset++)
                {
                    var raw = kValues[i - offset];
                    if (!IsFiniteNumber(raw))
                    {
                        valid = false;
                        break;
                    }
                    smoothedSum += raw;
                }
                if (valid)
                    dValues[i] = smoothedSum / smoothPeriod;
            }
        }

        private double[] BuildRelativeStrengthIndexSeries(Bars sourceBars, int period)
        {
            var count = sourceBars != null ? sourceBars.Count : 0;
            var values = new double[count];
            for (var i = 0; i < count; i++)
                values[i] = double.NaN;
            if (sourceBars == null || period <= 0 || count <= period + 1)
                return values;

            double gain = 0;
            double loss = 0;
            for (var i = 1; i <= period; i++)
            {
                var delta = sourceBars.ClosePrices[i] - sourceBars.ClosePrices[i - 1];
                if (delta >= 0)
                    gain += delta;
                else
                    loss -= delta;
            }

            var averageGain = gain / period;
            var averageLoss = loss / period;
            for (var i = period + 1; i < count; i++)
            {
                var delta = sourceBars.ClosePrices[i] - sourceBars.ClosePrices[i - 1];
                var currentGain = delta > 0 ? delta : 0;
                var currentLoss = delta < 0 ? -delta : 0;
                averageGain = ((averageGain * (period - 1)) + currentGain) / period;
                averageLoss = ((averageLoss * (period - 1)) + currentLoss) / period;
                if (averageLoss <= 0)
                    values[i] = averageGain <= 0 ? 50.0 : 100.0;
                else
                {
                    var rs = averageGain / averageLoss;
                    values[i] = 100.0 - (100.0 / (1.0 + rs));
                }
            }
            return values;
        }

        private void BuildMacdSeries(
            Bars sourceBars,
            int fastPeriod,
            int slowPeriod,
            int signalPeriod,
            out double[] macdValues,
            out double[] signalValues)
        {
            var count = sourceBars != null ? sourceBars.Count : 0;
            macdValues = new double[count];
            signalValues = new double[count];
            for (var i = 0; i < count; i++)
            {
                macdValues[i] = double.NaN;
                signalValues[i] = double.NaN;
            }
            if (sourceBars == null || fastPeriod <= 0 || slowPeriod <= 0 || signalPeriod <= 0)
                return;

            double fastSeedSum = 0;
            double slowSeedSum = 0;
            double fastEma = double.NaN;
            double slowEma = double.NaN;
            var fastMultiplier = 2.0 / (fastPeriod + 1.0);
            var slowMultiplier = 2.0 / (slowPeriod + 1.0);
            var signalMultiplier = 2.0 / (signalPeriod + 1.0);
            double signalSeedSum = 0;
            double signalLine = double.NaN;
            var macdCount = 0;

            for (var i = 0; i < count; i++)
            {
                var close = sourceBars.ClosePrices[i];
                if (i < fastPeriod)
                    fastSeedSum += close;
                if (i == fastPeriod - 1)
                    fastEma = fastSeedSum / fastPeriod;
                else if (i >= fastPeriod)
                    fastEma = ((close - fastEma) * fastMultiplier) + fastEma;

                if (i < slowPeriod)
                    slowSeedSum += close;
                if (i == slowPeriod - 1)
                    slowEma = slowSeedSum / slowPeriod;
                else if (i >= slowPeriod)
                    slowEma = ((close - slowEma) * slowMultiplier) + slowEma;

                if (!IsFiniteNumber(fastEma) || !IsFiniteNumber(slowEma))
                    continue;

                var macdLine = fastEma - slowEma;
                macdCount++;
                if (macdCount <= signalPeriod)
                {
                    signalSeedSum += macdLine;
                    if (macdCount == signalPeriod)
                        signalLine = signalSeedSum / signalPeriod;
                }
                else
                {
                    signalLine = ((macdLine - signalLine) * signalMultiplier) + signalLine;
                }

                if (i >= slowPeriod + signalPeriod && macdCount >= signalPeriod + 1 && IsFiniteNumber(signalLine))
                {
                    macdValues[i] = macdLine;
                    signalValues[i] = signalLine;
                }
            }
        }

