        private bool TryComputeMacdValues(Bars sourceBars, int endIndex, int fastPeriod, int slowPeriod, int signalPeriod, out double macdLine, out double signalLine)
        {
            macdLine = double.NaN;
            signalLine = double.NaN;
            if (sourceBars == null || fastPeriod <= 0 || slowPeriod <= 0 || signalPeriod <= 0 || endIndex < slowPeriod + signalPeriod)
                return false;

            double fastSeedSum = 0;
            double slowSeedSum = 0;
            double fastEma = double.NaN;
            double slowEma = double.NaN;
            var fastMultiplier = 2.0 / (fastPeriod + 1.0);
            var slowMultiplier = 2.0 / (slowPeriod + 1.0);
            var signalMultiplier = 2.0 / (signalPeriod + 1.0);
            double signalSeedSum = 0;
            var macdCount = 0;

            for (var i = 0; i <= endIndex; i++)
            {
                var close = sourceBars.ClosePrices[i];
                if (i < fastPeriod)
                    fastSeedSum += close;
                if (i == fastPeriod - 1)
                    fastEma = fastSeedSum / fastPeriod;
                else if (i >= fastPeriod)
                    fastEma = ((close - fastEma) * fastMultiplier) + fastEma;

                if (i < slowPeriod)
                    slowSeedSum += close;
                if (i == slowPeriod - 1)
                    slowEma = slowSeedSum / slowPeriod;
                else if (i >= slowPeriod)
                    slowEma = ((close - slowEma) * slowMultiplier) + slowEma;

                if (!IsFiniteNumber(fastEma) || !IsFiniteNumber(slowEma))
                    continue;

                macdLine = fastEma - slowEma;
                macdCount++;
                if (macdCount <= signalPeriod)
                {
                    signalSeedSum += macdLine;
                    if (macdCount == signalPeriod)
                        signalLine = signalSeedSum / signalPeriod;
                }
                else
                {
                    signalLine = ((macdLine - signalLine) * signalMultiplier) + signalLine;
                }
            }

            return macdCount >= signalPeriod + 1 && IsFiniteNumber(macdLine) && IsFiniteNumber(signalLine);
        }

        private bool HasBullishBiasForStrategy(string symbolName)
        {
            var bias = GetSymbolTrendBias(symbolName);
            return bias.Item1 >= 2 || bias.Item2 >= 2 || (bias.Item1 + bias.Item2 + bias.Item3) > 0;
        }

        private bool HasBearishBiasForStrategy(string symbolName)
        {
            var bias = GetSymbolTrendBias(symbolName);
            return bias.Item1 <= -2 || bias.Item2 <= -2 || (bias.Item1 + bias.Item2 + bias.Item3) < 0;
        }

        private bool IsValidBarIndex(Bars sourceBars, int index)
        {
            return sourceBars != null && index >= 0 && index < sourceBars.Count;
        }

        private double Open(Bars sourceBars, int index)
        {
            return IsValidBarIndex(sourceBars, index) ? sourceBars.OpenPrices[index] : double.NaN;
        }

        private double High(Bars sourceBars, int index)
        {
            return IsValidBarIndex(sourceBars, index) ? sourceBars.HighPrices[index] : double.NaN;
        }

        private double Low(Bars sourceBars, int index)
        {
            return IsValidBarIndex(sourceBars, index) ? sourceBars.LowPrices[index] : double.NaN;
        }

        private double Close(Bars sourceBars, int index)
        {
            return IsValidBarIndex(sourceBars, index) ? sourceBars.ClosePrices[index] : double.NaN;
        }

        private double Body(Bars sourceBars, int index)
        {
            return IsValidBarIndex(sourceBars, index)
                ? Math.Abs(Close(sourceBars, index) - Open(sourceBars, index))
                : double.NaN;
        }

        private double Range(Bars sourceBars, int index)
        {
            return IsValidBarIndex(sourceBars, index)
                ? High(sourceBars, index) - Low(sourceBars, index)
                : double.NaN;
        }

        private double UpperWick(Bars sourceBars, int index)
        {
            return IsValidBarIndex(sourceBars, index)
                ? High(sourceBars, index) - Math.Max(Open(sourceBars, index), Close(sourceBars, index))
                : double.NaN;
        }

        private double LowerWick(Bars sourceBars, int index)
        {
            return IsValidBarIndex(sourceBars, index)
                ? Math.Min(Open(sourceBars, index), Close(sourceBars, index)) - Low(sourceBars, index)
                : double.NaN;
        }

        private bool IsBullish(Bars sourceBars, int index)
        {
            return IsValidBarIndex(sourceBars, index) && Close(sourceBars, index) > Open(sourceBars, index);
        }

        private bool IsBearish(Bars sourceBars, int index)
        {
            return IsValidBarIndex(sourceBars, index) && Close(sourceBars, index) < Open(sourceBars, index);
        }

        private double BodyRatio(Bars sourceBars, int index)
        {
            var range = Range(sourceBars, index);
            if (!IsFiniteNumber(range) || range <= 0)
                return 0;
            var body = Body(sourceBars, index);
            return IsFiniteNumber(body) ? body / range : 0;
        }

        private bool IsBullishPinBar(Bars sourceBars, int index)
        {
            if (!IsValidBarIndex(sourceBars, index))
                return false;

            var open = Open(sourceBars, index);
            var close = Close(sourceBars, index);
            var high = High(sourceBars, index);
            var low = Low(sourceBars, index);
            return IsStrictBullishPinBar(open, high, low, close);
        }

        private bool IsBearishPinBar(Bars sourceBars, int index)
        {
            if (!IsValidBarIndex(sourceBars, index))
                return false;

            var open = Open(sourceBars, index);
            var close = Close(sourceBars, index);
            var high = High(sourceBars, index);
            var low = Low(sourceBars, index);
            return IsStrictBearishPinBar(open, high, low, close);
        }

        private bool IsBullishEngulfing(Bars sourceBars, int previousIndex, int currentIndex)
        {
            if (!IsValidBarIndex(sourceBars, previousIndex) || !IsValidBarIndex(sourceBars, currentIndex))
                return false;

            var previousOpen = Open(sourceBars, previousIndex);
            var previousClose = Close(sourceBars, previousIndex);
            var currentOpen = Open(sourceBars, currentIndex);
            var currentClose = Close(sourceBars, currentIndex);
            var previousHigh = High(sourceBars, previousIndex);
            var previousLow = Low(sourceBars, previousIndex);
            var currentHigh = High(sourceBars, currentIndex);
            var currentLow = Low(sourceBars, currentIndex);
            return IsStrictBullishEngulfing(previousOpen, previousHigh, previousLow, previousClose, currentOpen, currentHigh, currentLow, currentClose);
        }

        private bool IsBearishEngulfing(Bars sourceBars, int previousIndex, int currentIndex)
        {
            if (!IsValidBarIndex(sourceBars, previousIndex) || !IsValidBarIndex(sourceBars, currentIndex))
                return false;

            var previousOpen = Open(sourceBars, previousIndex);
            var previousClose = Close(sourceBars, previousIndex);
            var currentOpen = Open(sourceBars, currentIndex);
            var currentClose = Close(sourceBars, currentIndex);
            var previousHigh = High(sourceBars, previousIndex);
            var previousLow = Low(sourceBars, previousIndex);
            var currentHigh = High(sourceBars, currentIndex);
            var currentLow = Low(sourceBars, currentIndex);
            return IsStrictBearishEngulfing(previousOpen, previousHigh, previousLow, previousClose, currentOpen, currentHigh, currentLow, currentClose);
        }

        private bool IsStrictBullishPinBar(double open, double high, double low, double close)
        {
            return CTraderCandlePatternEngine.IsBullishPinBar(open, high, low, close);
        }

        private bool IsStrictBearishPinBar(double open, double high, double low, double close)
        {
            return CTraderCandlePatternEngine.IsBearishPinBar(open, high, low, close);
        }

        private bool IsStrictBullishEngulfing(double previousOpen, double previousHigh, double previousLow, double previousClose, double currentOpen, double currentHigh, double currentLow, double currentClose)
        {
            return CTraderCandlePatternEngine.IsBullishEngulfing(previousOpen, previousHigh, previousLow, previousClose, currentOpen, currentHigh, currentLow, currentClose);
        }

        private bool IsStrictBearishEngulfing(double previousOpen, double previousHigh, double previousLow, double previousClose, double currentOpen, double currentHigh, double currentLow, double currentClose)
        {
            return CTraderCandlePatternEngine.IsBearishEngulfing(previousOpen, previousHigh, previousLow, previousClose, currentOpen, currentHigh, currentLow, currentClose);
        }

        private bool IsStrongDirectionalCandle(Bars sourceBars, int index, bool bullish)
        {
            if (!IsValidBarIndex(sourceBars, index))
                return false;

            var openV = Open(sourceBars, index);
            var highV = High(sourceBars, index);
            var lowV = Low(sourceBars, index);
            var closeV = Close(sourceBars, index);
            var minimumRange = Math.Max(Symbol != null ? Symbol.PipSize : 0.0000001, 0.0000001);
            return CTraderCandlePatternEngine.IsStrongDirectionalCandle(
                openV, highV, lowV, closeV, bullish, minimumRange, 0.55, 0.30);
        }

        private bool IsDirectionalCandleSequence(Bars sourceBars, int endIndex, bool bullish, int candlesNum)
        {
            if (sourceBars == null || candlesNum <= 0 || endIndex < candlesNum - 1 || endIndex >= sourceBars.Count)
                return false;

            var startIndex = endIndex - candlesNum + 1;
            for (var index = startIndex; index <= endIndex; index++)
            {
                if (!CTraderCandlePatternEngine.IsDirectional(Open(sourceBars, index), Close(sourceBars, index), bullish))
                    return false;
            }

            return true;
        }

        private bool IsBigDirectionalCandle(Bars sourceBars, int index, bool bullish)
        {
            if (sourceBars == null || index < 0 || index >= sourceBars.Count || Symbol == null)
                return false;

            var open = sourceBars.OpenPrices[index];
            var close = sourceBars.ClosePrices[index];
            var high = sourceBars.HighPrices[index];
            var low = sourceBars.LowPrices[index];
            var tolerance = Math.Max(Symbol.PipSize * 0.5, 0.0000001);
            return CTraderCandlePatternEngine.IsBigDirectionalCandle(
                open, high, low, close, bullish, FollowTrendBigCandleBodyPercentMin, tolerance);
        }

        private bool TryGetRecentDirectionalEvent(string symbolName, IEnumerable<TimeFrame> timeFrames, bool bullish, out CanonicalMarketEvent selectedEvent, params CanonicalEventType[] eventTypes)
        {
            selectedEvent = default(CanonicalMarketEvent);
            if (string.IsNullOrWhiteSpace(symbolName) || timeFrames == null || eventTypes == null || eventTypes.Length == 0)
                return false;

            var typeSet = new HashSet<CanonicalEventType>(eventTypes);
            var frameSet = new HashSet<TimeFrame>(timeFrames.Distinct());
            var candidates = GetTradeTriggerSequence(symbolName)
                .Where(item => item.HasCanonicalEvent && !item.IsDirectionless && item.IsBullish == bullish)
                .Where(item => frameSet.Contains(item.SourceTimeFrame))
                .Where(item => typeSet.Contains(item.CanonicalEvent.EventType))
                .Select(item => item.CanonicalEvent)
                .ToList();

            var latest = candidates
                .OrderByDescending(evt => evt.BarTime)
                .ThenByDescending(evt => evt.Score)
                .FirstOrDefault();
            if (latest.BarTime == DateTime.MinValue)
                return false;

            selectedEvent = latest;
            return true;
        }

        private bool TryBuildSuggestedLevelsPlan(Symbol symbol, string symbolName, TradeType tradeType, double entryPrice, int slRank, int tpRank, string profileRaw, out ChartTradePlan plan)
        {
            plan = new ChartTradePlan { IsValid = false, StructureTfLabel = GetChartTradeStructureTfLabel(profileRaw) };
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || !IsFiniteNumber(entryPrice) || entryPrice <= 0)
                return false;

            var stopCandidates = GetRankedChartStructuralLevels(symbol, symbolName, tradeType == TradeType.Buy, entryPrice, profileRaw);
            var targetCandidates = GetRankedChartStructuralLevels(symbol, symbolName, tradeType != TradeType.Buy, entryPrice, profileRaw);
            if (stopCandidates.Count == 0 || targetCandidates.Count == 0)
                return false;

            var stopIndex = Math.Max(0, Math.Min(stopCandidates.Count - 1, Math.Max(0, slRank - 1)));
            var targetIndex = Math.Max(0, Math.Min(targetCandidates.Count - 1, Math.Max(0, tpRank - 1)));
            var adjusted = ApplyChartProtectionBiasAndRisk(symbol, tradeType, entryPrice, stopCandidates[stopIndex].Price, targetCandidates[targetIndex].Price);
            if (adjusted == null)
                return false;

            var risk = Math.Abs(entryPrice - adjusted.Item1);
            var reward = Math.Abs(adjusted.Item2 - entryPrice);
            if (risk <= 0 || reward <= 0)
                return false;

            plan = new ChartTradePlan
            {
                IsValid = true,
                EntryLabel = string.Format(CultureInfo.InvariantCulture, "rank{0}/rank{1}", stopIndex + 1, targetIndex + 1),
                StructureTfLabel = GetChartTradeStructureTfLabel(profileRaw),
                Entry = NormalizePriceToSymbol(symbol, entryPrice),
                StopLoss = NormalizePriceToSymbol(symbol, adjusted.Item1),
                TakeProfit = NormalizePriceToSymbol(symbol, adjusted.Item2),
                RewardRisk = reward / risk
            };
            return true;
        }

        private string GetStrategyRuntimeTag()
        {
            return IsBacktestingRuntime() ? "Backtest" : "Live";
        }

        private void LogStrategyInfoOnce(string strategyId, string symbolName, string message)
        {
            var barTime = Bars != null && Bars.Count > 0 ? Bars.OpenTimes[Math.Max(0, Bars.Count - 1)] : Server.Time;
            var eventKey = string.Format(CultureInfo.InvariantCulture, "INFO|{0}|{1}|{2}|{3}|{4}", GetStrategyRuntimeTag(), strategyId, symbolName.ToUpperInvariant(), message, barTime.Ticks);
            if (_backtestStrategyHandledEventKeys.Contains(eventKey))
                return;

            SafePrint("[{0}] {1} {2}: {3}", GetStrategyRuntimeTag(), strategyId, symbolName, message);
            _backtestStrategyHandledEventKeys.Add(eventKey);
        }

        private void LogStrategySkip(string strategyId, string symbolName, string message)
        {
            // REJECT-level messages may be hidden by cTrader's active log filter. A strategy
            // gate is normal runtime information, so make it visible in the standard log.
            SafePrint(
                "[{0}] Reject {1} {2}: {3}",
                GetStrategyRuntimeTag(),
                strategyId,
                symbolName,
                string.IsNullOrWhiteSpace(message) ? "unspecified strategy gate" : message);
        }

        private void LogStrategyReject(string strategyId, string symbolName, string message)
        {
            SafePrint("[{0}] Reject {1} {2}: {3}", GetStrategyRuntimeTag(), strategyId, symbolName, message);
        }

        private bool IsStrategyManagedExposure(string label, string comment)
        {
            var normalizedLabel = string.IsNullOrWhiteSpace(label) ? "" : label.Trim();
            var normalizedComment = string.IsNullOrWhiteSpace(comment) ? "" : comment.Trim();

            return normalizedComment.StartsWith("bot_", StringComparison.OrdinalIgnoreCase) ||
                   normalizedComment.IndexOf("|rs:", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   normalizedComment.IndexOf("|ltf:", StringComparison.OrdinalIgnoreCase) >= 0 ||
                   normalizedLabel.EndsWith("_bot", StringComparison.OrdinalIgnoreCase) ||
                   normalizedLabel.StartsWith("BT_", StringComparison.OrdinalIgnoreCase) ||
                   normalizedComment.StartsWith("live_", StringComparison.OrdinalIgnoreCase) ||
                   normalizedComment.StartsWith("backtest_", StringComparison.OrdinalIgnoreCase);
        }

        private void TrackStrategyPositionMarkers()
        {
            if (Positions == null)
                return;

            var nowUtc = DateTime.UtcNow;
            if (_lastStrategyPositionMarkerReconcileUtc != DateTime.MinValue &&
                (nowUtc - _lastStrategyPositionMarkerReconcileUtc).TotalSeconds < 5)
                return;
            _lastStrategyPositionMarkerReconcileUtc = nowUtc;

            var currentIds = new HashSet<long>();
            foreach (var position in Positions)
            {
                if (position == null || !IsStrategyManagedExposure(position.Label, position.Comment))
                    continue;

                currentIds.Add(position.Id);

                if (_trackedStrategyPositions.ContainsKey(position.Id))
                    continue;

                var entryTime = ReadDateTimeMember(position, "EntryTime", "OpeningTime", "OpenTime");
                if (entryTime == DateTime.MinValue)
                    entryTime = Server.Time;

                _trackedStrategyPositions[position.Id] = new StrategyPositionSnapshot
                {
                    PositionId = position.Id,
                    SymbolName = position.SymbolName,
                    TradeType = position.TradeType,
                    EntryPrice = position.EntryPrice,
                    EntryTime = entryTime,
                    Label = position.Label,
                    Comment = position.Comment
                };

                DateTime triggerBarTime;
                string triggerEventLabel;
                if (TryParseStrategyTriggerAudit(position.Label, position.Comment, position.SymbolName, out triggerBarTime, out triggerEventLabel))
                {
                    AddStrategyChartMarker(new StrategyChartMarker
                    {
                        PositionId = -Math.Abs(position.Id),
                        SymbolName = position.SymbolName,
                        TradeType = position.TradeType,
                        Kind = StrategyMarkerKind.Trigger,
                        Time = triggerBarTime,
                        Price = position.EntryPrice,
                        Pnl = 0,
                        IsWinning = false,
                        Text = triggerEventLabel
                    });
                }

                AddStrategyChartMarker(new StrategyChartMarker
                {
                    PositionId = position.Id,
                    SymbolName = position.SymbolName,
                    TradeType = position.TradeType,
                    Kind = StrategyMarkerKind.Entry,
                    Time = entryTime,
                    Price = position.EntryPrice,
                    Pnl = 0,
                    IsWinning = false,
                    Text = position.TradeType == TradeType.Buy ? "B" : "S"
                });
            }

            var closedIds = _trackedStrategyPositions.Keys.Where(id => !currentIds.Contains(id)).ToList();
            foreach (var closedId in closedIds)
            {
                var snapshot = _trackedStrategyPositions[closedId];
                var historyDeal = History != null
                    ? History
                        .Where(deal => deal != null && deal.PositionId == closedId)
                        .OrderByDescending(deal => ReadDateTimeMember(deal, "ClosingTime", "CloseTime", "Time"))
                        .FirstOrDefault()
                    : null;

                var exitTime = historyDeal != null
                    ? ReadDateTimeMember(historyDeal, "ClosingTime", "CloseTime", "Time")
                    : Server.Time;
                if (exitTime == DateTime.MinValue)
                    exitTime = Server.Time;

                var exitPrice = historyDeal != null
                    ? ReadDoubleMember(historyDeal, "ClosingPrice", "ClosePrice", "ExitPrice")
                    : snapshot.EntryPrice;
                if (!(exitPrice > 0))
                    exitPrice = snapshot.EntryPrice;

                var pnl = historyDeal != null && !double.IsNaN(historyDeal.NetProfit)
                    ? historyDeal.NetProfit
                    : 0;

                AddStrategyChartMarker(new StrategyChartMarker
                {
                    PositionId = snapshot.PositionId,
                    SymbolName = snapshot.SymbolName,
                    TradeType = snapshot.TradeType,
                    Kind = StrategyMarkerKind.Exit,
                    Time = exitTime,
                    Price = exitPrice,
                    Pnl = pnl,
                    IsWinning = pnl >= 0,
                    Text = string.Format(CultureInfo.InvariantCulture, "{0}{1}", pnl >= 0 ? "+" : "", pnl.ToString("F0", CultureInfo.InvariantCulture))
                });

                _trackedStrategyPositions.Remove(closedId);
            }
        }

        private void AddStrategyChartMarker(StrategyChartMarker marker)
        {
            if (marker.Time == DateTime.MinValue || string.IsNullOrWhiteSpace(marker.SymbolName))
                return;

            var duplicateExists = _strategyChartMarkers.Any(existing =>
                existing.PositionId == marker.PositionId &&
                existing.Kind == marker.Kind &&
                existing.TradeType == marker.TradeType &&
                string.Equals(existing.SymbolName, marker.SymbolName, StringComparison.OrdinalIgnoreCase) &&
                Math.Abs((existing.Time - marker.Time).TotalSeconds) < 1);
            if (duplicateExists)
                return;

            _strategyChartMarkers.Add(marker);
            if (_strategyChartMarkers.Count > 200)
                _strategyChartMarkers.RemoveRange(0, _strategyChartMarkers.Count - 200);
        }

        private int CountStrategyManagedOpenPositions()
        {
            if (Positions == null)
                return 0;

            return Positions.Count(p =>
                p != null &&
                IsStrategyManagedExposure(p.Label, p.Comment));
        }

        private int CountStrategyManagedPendingOrders()
        {
            if (PendingOrders == null)
                return 0;

            return PendingOrders.Count(order =>
                order != null &&
                IsStrategyManagedExposure(order.Label, order.Comment));
        }

        private int CountStrategyManagedExposures()
        {
            return CountStrategyManagedOpenPositions() + CountStrategyManagedPendingOrders();
        }

        private void EnforceLiveStrategyProtectionSafety()
        {
            if (IsBacktestingRuntime() || !EnableLiveStrategyTrading)
                return;

            foreach (var position in GetCurrentPositionsSnapshot())
            {
                if (position == null)
                    continue;
                if (!IsStrategyManagedExposure(position.Label, position.Comment))
                    continue;

                var hasStopLoss = position.StopLoss.HasValue && position.StopLoss.Value > 0;
                if (hasStopLoss)
                    continue;

                SafeLog(
                    "ERROR",
                    "[Live][Safety] Closing unprotected strategy position #{0} {1} {2} label={3} comment={4}",
                    position.Id,
                    position.SymbolName,
                    position.TradeType,
                    position.Label,
                    position.Comment);

                var closeResult = ClosePosition(position);
                if (closeResult != null && closeResult.IsSuccessful)
                {
                    var positionSymbol = ResolveLoadedSymbol(position.SymbolName);
                    var positionLots = positionSymbol != null ? positionSymbol.VolumeInUnitsToQuantity(position.VolumeInUnits) : 0;
                    LogStructuredTradeEvent(
                        "live",
                        "FAILED",
                        position.SymbolName,
                        position.TradeType == TradeType.Buy ? "BUY" : "SELL",
                        "MARKET",
                        positionLots,
                        position.EntryPrice,
                        0,
                        position.TakeProfit ?? 0,
                        position.Id.ToString(CultureInfo.InvariantCulture),
                        "safety_close_unprotected_position");
                }
                else
                {
                    SafeLog(
                        "ERROR",
                        "[Live][Safety] Close failed for unprotected strategy position #{0}: {1}",
                        position.Id,
                        closeResult != null ? Convert.ToString(closeResult.Error, CultureInfo.InvariantCulture) : "null_result");
                }
            }
        }

        private int CountStrategyManagedIdeaExposures(string symbolName, TradeType tradeType)
        {
            if (string.IsNullOrWhiteSpace(symbolName))
                return 0;

            var normalizedSymbol = symbolName.Trim();
            var positionCount = Positions == null
                ? 0
                : Positions.Count(position =>
                    position != null &&
                    string.Equals(position.SymbolName, normalizedSymbol, StringComparison.OrdinalIgnoreCase) &&
                    position.TradeType == tradeType &&
                    IsStrategyManagedExposure(position.Label, position.Comment));
            var pendingCount = PendingOrders == null
                ? 0
                : PendingOrders.Count(order =>
                    order != null &&
                    string.Equals(order.SymbolName, normalizedSymbol, StringComparison.OrdinalIgnoreCase) &&
                    order.TradeType == tradeType &&
                    IsStrategyManagedExposure(order.Label, order.Comment));
            return positionCount + pendingCount;
        }

        private bool TryPassStrategyPositionCaps(string symbolName, TradeType tradeType, out string rejectReason)
        {
            rejectReason = "";

            var maxIdea = Math.Max(0, MaxPositionsPerIdea);
            if (maxIdea > 0)
            {
                var existingIdeaExposures = CountStrategyManagedIdeaExposures(symbolName, tradeType);
                if (existingIdeaExposures >= maxIdea)
                {
                    rejectReason = string.Format(
                        CultureInfo.InvariantCulture,
                        "max_pos_per_idea {0}>={1}; symbol={2}; side={3}",
                        existingIdeaExposures,
                        maxIdea,
                        string.IsNullOrWhiteSpace(symbolName) ? "" : symbolName.Trim().ToUpperInvariant(),
                        tradeType == TradeType.Buy ? "BUY" : "SELL");
                    return false;
                }
            }

            var maxTotal = Math.Max(0, MaxPositionsTotal);
            if (maxTotal > 0)
            {
                var existingTotalExposures = CountStrategyManagedExposures();
                if (existingTotalExposures >= maxTotal)
                {
                    rejectReason = string.Format(
                        CultureInfo.InvariantCulture,
                        "max_pos_total {0}>={1}",
                        existingTotalExposures,
                        maxTotal);
                    return false;
                }
            }

            return true;
        }

        private IEnumerable<TimeFrame> GetBacktestStrategyHigherTimeFrames(TimeFrame baseTimeFrame)
        {
            return GetEnabledAutoHigherTimeframes(baseTimeFrame)
                .Distinct()
                .OrderBy(tf => TimeFrameToMinutes(tf))
                .ToList();
        }

        private IEnumerable<TimeFrame> GetBacktestStrategyCurrentTimeFrame(TimeFrame baseTimeFrame)
        {
            if (baseTimeFrame == null)
                return new List<TimeFrame>();

            return new List<TimeFrame> { baseTimeFrame };
        }

        private bool IsEligibleBacktestStrategyEventType(CanonicalEventType eventType)
        {
            return eventType == CanonicalEventType.Choch ||
                   eventType == CanonicalEventType.Bos ||
                   eventType == CanonicalEventType.SweepReclaim ||
                   eventType == CanonicalEventType.Rejection ||
                   eventType == CanonicalEventType.Breakout ||
                   eventType == CanonicalEventType.Continuation ||
                   eventType == CanonicalEventType.Impulse;
        }

        private bool IsRecentBacktestStrategyEvent(string symbolName, CanonicalMarketEvent evt)
        {
            try
            {
                var bars = MarketData.GetBars(evt.SourceTimeFrame, symbolName);
                if (bars == null || bars.Count < 3)
                    return false;
                var thresholdTime = bars.OpenTimes[Math.Max(0, bars.Count - 3)];
                return evt.BarTime >= thresholdTime;
            }
            catch
            {
                return false;
            }
        }

        private bool TryGetLatestBacktestStrategyEvent(string symbolName, TimeFrame baseTimeFrame, out CanonicalMarketEvent selectedEvent)
        {
            selectedEvent = default(CanonicalMarketEvent);
            if (string.IsNullOrWhiteSpace(symbolName))
                return false;

            var frameSet = new HashSet<TimeFrame>(GetBacktestStrategyHigherTimeFrames(baseTimeFrame));
            var candidates = GetTradeTriggerSequence(symbolName, baseTimeFrame)
                .Where(item => item.HasCanonicalEvent && frameSet.Contains(item.SourceTimeFrame))
                .Select(item => item.CanonicalEvent)
                .Where(evt => IsEligibleBacktestStrategyEventType(evt.EventType))
                .ToList();

            var latest = candidates
                .OrderByDescending(evt => evt.BarTime)
                .ThenByDescending(evt => evt.Score)
                .FirstOrDefault();
            if (latest.BarTime == DateTime.MinValue)
                return false;

            selectedEvent = latest;
            return true;
        }

        private bool TryGetLatestBacktestStrategyEventForTimeFrames(string symbolName, IEnumerable<TimeFrame> timeFrames, out CanonicalMarketEvent selectedEvent)
        {
            selectedEvent = default(CanonicalMarketEvent);
            if (string.IsNullOrWhiteSpace(symbolName) || timeFrames == null)
                return false;

            var frameSet = new HashSet<TimeFrame>(timeFrames.Distinct());
            var candidates = GetTradeTriggerSequence(symbolName)
                .Where(item => item.HasCanonicalEvent && frameSet.Contains(item.SourceTimeFrame))
                .Select(item => item.CanonicalEvent)
                .Where(evt => IsEligibleBacktestStrategyEventType(evt.EventType))
                .ToList();

            var latest = candidates
                .OrderByDescending(evt => evt.BarTime)
                .ThenByDescending(evt => evt.Score)
                .FirstOrDefault();
            if (latest.BarTime == DateTime.MinValue)
                return false;

            selectedEvent = latest;
            return true;
        }

        private bool TryGetLatestBacktestStrategyEventByTypes(string symbolName, IEnumerable<TimeFrame> timeFrames, out CanonicalMarketEvent selectedEvent, params CanonicalEventType[] eventTypes)
        {
            selectedEvent = default(CanonicalMarketEvent);
            if (string.IsNullOrWhiteSpace(symbolName) || timeFrames == null || eventTypes == null || eventTypes.Length == 0)
                return false;

            var typeSet = new HashSet<CanonicalEventType>(eventTypes);
            var frameSet = new HashSet<TimeFrame>(timeFrames.Distinct());
            var candidates = GetTradeTriggerSequence(symbolName)
                .Where(item => item.HasCanonicalEvent && frameSet.Contains(item.SourceTimeFrame))
                .Select(item => item.CanonicalEvent)
                .Where(evt => typeSet.Contains(evt.EventType))
                .ToList();

            var latest = candidates
                .OrderByDescending(evt => evt.BarTime)
                .ThenByDescending(evt => evt.Score)
                .FirstOrDefault();
            if (latest.BarTime == DateTime.MinValue)
                return false;

            selectedEvent = latest;
            return true;
        }

        private bool TryGetLatestClosedCanonicalBarTime(string symbolName, TimeFrame timeFrame, out DateTime barTime)
        {
            barTime = DateTime.MinValue;
            if (string.IsNullOrWhiteSpace(symbolName))
                return false;

            try
            {
                var bars = GetBarsForCurrentMasterTimer(timeFrame, symbolName);
                if (bars == null || bars.Count < 2)
                    return false;

                var latestClosedIndex = bars.Count - 2;
                if (latestClosedIndex < 0 || latestClosedIndex >= bars.Count)
                    return false;

                barTime = bars.OpenTimes[latestClosedIndex];
                return barTime != DateTime.MinValue;
            }
            catch
            {
                return false;
            }
        }

