        private bool IsSameDirectionCandle(Bars sourceBars, int index, bool bullish)
        {
            if (sourceBars == null || index < 0 || index >= sourceBars.Count)
                return false;

            return CTraderCandlePatternEngine.IsDirectional(
                sourceBars.OpenPrices[index], sourceBars.ClosePrices[index], bullish);
        }

        private bool HasDirectionalFollowThrough(Bars sourceBars, int eventIndex, int confirmationIndex, bool bullish)
        {
            if (sourceBars == null || eventIndex < 0 || confirmationIndex < 0 || eventIndex >= sourceBars.Count || confirmationIndex >= sourceBars.Count)
                return false;

            return CTraderCandlePatternEngine.HasDirectionalFollowThrough(
                sourceBars.HighPrices[eventIndex], sourceBars.LowPrices[eventIndex], sourceBars.ClosePrices[eventIndex],
                sourceBars.OpenPrices[confirmationIndex], sourceBars.HighPrices[confirmationIndex], sourceBars.LowPrices[confirmationIndex], sourceBars.ClosePrices[confirmationIndex],
                bullish, Math.Max(Symbol != null ? Symbol.PipSize : 0.0000001, 0.0000001), 0.35, 0.25);
        }

        private bool HasDirectionalRejection(Bars sourceBars, int eventIndex, int rejectionIndex, bool bullish)
        {
            if (sourceBars == null || eventIndex < 0 || rejectionIndex < 0 || eventIndex >= sourceBars.Count || rejectionIndex >= sourceBars.Count)
                return false;

            if (IsBigDirectionalCandle(sourceBars, rejectionIndex, !bullish))
                return true;

            var prevOpen = sourceBars.OpenPrices[eventIndex];
            var prevHigh = sourceBars.HighPrices[eventIndex];
            var prevLow = sourceBars.LowPrices[eventIndex];
            var prevClose = sourceBars.ClosePrices[eventIndex];
            var open = sourceBars.OpenPrices[rejectionIndex];
            var high = sourceBars.HighPrices[rejectionIndex];
            var low = sourceBars.LowPrices[rejectionIndex];
            var close = sourceBars.ClosePrices[rejectionIndex];
            return CTraderCandlePatternEngine.HasDirectionalRejection(
                prevOpen, prevHigh, prevLow, prevClose, open, high, low, close,
                bullish, Math.Max(Symbol != null ? Symbol.PipSize : 0.0000001, 0.0000001), 0.50);
        }

        private bool TryResolveStructureVisualFollowUp(
            Bars sourceBars,
            int eventIndex,
            bool bullish,
            StructureEventFollowUpFilter filter,
            out int markerIndex,
            out string labelSuffix)
        {
            markerIndex = eventIndex;
            labelSuffix = "";
            if (filter == StructureEventFollowUpFilter.Any)
                return true;

            if (sourceBars == null || eventIndex < 0)
                return false;

            var nextIndex = eventIndex + 1;
            var latestClosedIndex = sourceBars.Count - 2;
            if (nextIndex < 0 || nextIndex > latestClosedIndex)
                return false;

            if (filter == StructureEventFollowUpFilter.Continue)
            {
                if (!HasDirectionalFollowThrough(sourceBars, eventIndex, nextIndex, bullish))
                    return false;
                markerIndex = nextIndex;
                labelSuffix = ".c";
                return true;
            }

            if (!HasDirectionalRejection(sourceBars, eventIndex, nextIndex, bullish))
                return false;
            markerIndex = nextIndex;
            labelSuffix = ".r";
            return true;
        }

        private bool TryEvaluateStrategyCustomFollowUpEventOption(
            StrategyCustomEventOption option,
            string symbolName,
            Bars sourceBars,
            TimeFrame strategyTimeFrame,
            int latestClosedIndex,
            List<CanonicalMarketEvent> recentCanonicalEvents,
            Dictionary<DateTime, List<CanonicalMarketEvent>> canonicalEventsByBarTime,
            out bool matchesBullish,
            out bool matchesBearish,
            out bool matchesDirectionless,
            out string shortLabel)
        {
            matchesBullish = false;
            matchesBearish = false;
            matchesDirectionless = false;
            shortLabel = "";

            StrategyCustomEventOption baseOption;
            StrategyEventFollowUpOutcome outcome;
            if (!TryMapStrategyFollowUpEventOption(option, out baseOption, out outcome))
                return false;

            if (sourceBars == null || latestClosedIndex < 2 || latestClosedIndex >= sourceBars.Count)
                return false;

            var eventIndex = latestClosedIndex - 1;
            if (eventIndex < 1)
                return false;

            var previousSnapshot = BuildSharedIndicatorSnapshot(sourceBars, eventIndex - 1);
            var currentSnapshot = BuildSharedIndicatorSnapshot(sourceBars, eventIndex);
            var sharedPatterns = GetDetectedSharedRulePatternSet(sourceBars, strategyTimeFrame, eventIndex);
            var eventBarTime = sourceBars.OpenTimes[eventIndex];
            List<CanonicalMarketEvent> eventsOnEventBar;
            if (canonicalEventsByBarTime != null)
            {
                if (!canonicalEventsByBarTime.TryGetValue(eventBarTime, out eventsOnEventBar))
                    eventsOnEventBar = new List<CanonicalMarketEvent>();
            }
            else
            {
                eventsOnEventBar = (recentCanonicalEvents ?? new List<CanonicalMarketEvent>())
                    .Where(evt => evt.BarTime == eventBarTime)
                    .OrderByDescending(evt => evt.Score)
                    .ToList();
            }

            bool baseBullish;
            bool baseBearish;
            bool baseDirectionless;
            string baseShortLabel;
            if (!TryEvaluateStrategyCustomEventOptionCore(
                baseOption,
                symbolName,
                sourceBars,
                strategyTimeFrame,
                eventIndex,
                previousSnapshot,
                currentSnapshot,
                sharedPatterns,
                recentCanonicalEvents,
                eventsOnEventBar,
                out baseBullish,
                out baseBearish,
                out baseDirectionless,
                out baseShortLabel))
                return false;

            if (baseDirectionless || (!baseBullish && !baseBearish))
                return false;

            matchesBullish = baseBullish &&
                (outcome == StrategyEventFollowUpOutcome.Continue
                    ? HasDirectionalFollowThrough(sourceBars, eventIndex, latestClosedIndex, true)
                    : HasDirectionalRejection(sourceBars, eventIndex, latestClosedIndex, true));
            matchesBearish = baseBearish &&
                (outcome == StrategyEventFollowUpOutcome.Continue
                    ? HasDirectionalFollowThrough(sourceBars, eventIndex, latestClosedIndex, false)
                    : HasDirectionalRejection(sourceBars, eventIndex, latestClosedIndex, false));

            shortLabel = FormatEventLabelForDisplay((string.IsNullOrWhiteSpace(baseShortLabel) ? "EVT" : baseShortLabel) +
                (outcome == StrategyEventFollowUpOutcome.Continue ? ".c" : ".r"));
            return matchesBullish || matchesBearish;
        }

        private bool TryEvaluateStrategyCustomEventOption(
            StrategyCustomEventOption option,
            string symbolName,
            Bars sourceBars,
            TimeFrame strategyTimeFrame,
            int latestClosedIndex,
            SharedIndicatorSnapshot previousSnapshot,
            SharedIndicatorSnapshot currentSnapshot,
            HashSet<string> sharedPatterns,
            List<CanonicalMarketEvent> recentCanonicalEvents,
            List<CanonicalMarketEvent> eventsOnBar,
            out bool matchesBullish,
            out bool matchesBearish,
            out bool matchesDirectionless,
            out string shortLabel)
        {
            return TryEvaluateStrategyCustomEventOption(
                option,
                symbolName,
                sourceBars,
                strategyTimeFrame,
                latestClosedIndex,
                previousSnapshot,
                currentSnapshot,
                sharedPatterns,
                recentCanonicalEvents,
                eventsOnBar,
                null,
                out matchesBullish,
                out matchesBearish,
                out matchesDirectionless,
                out shortLabel);
        }

        private bool TryEvaluateStrategyCustomEventOption(
            StrategyCustomEventOption option,
            string symbolName,
            Bars sourceBars,
            TimeFrame strategyTimeFrame,
            int latestClosedIndex,
            SharedIndicatorSnapshot previousSnapshot,
            SharedIndicatorSnapshot currentSnapshot,
            HashSet<string> sharedPatterns,
            List<CanonicalMarketEvent> recentCanonicalEvents,
            List<CanonicalMarketEvent> eventsOnBar,
            Dictionary<DateTime, List<CanonicalMarketEvent>> canonicalEventsByBarTime,
            out bool matchesBullish,
            out bool matchesBearish,
            out bool matchesDirectionless,
            out string shortLabel)
        {
            if (TryMapStrategyFollowUpEventOption(option, out _, out _))
            {
                return TryEvaluateStrategyCustomFollowUpEventOption(
                    option,
                    symbolName,
                    sourceBars,
                    strategyTimeFrame,
                    latestClosedIndex,
                    recentCanonicalEvents,
                    canonicalEventsByBarTime,
                    out matchesBullish,
                    out matchesBearish,
                    out matchesDirectionless,
                    out shortLabel);
            }

            return TryEvaluateStrategyCustomEventOptionCore(
                option,
                symbolName,
                sourceBars,
                strategyTimeFrame,
                latestClosedIndex,
                previousSnapshot,
                currentSnapshot,
                sharedPatterns,
                recentCanonicalEvents,
                eventsOnBar,
                out matchesBullish,
                out matchesBearish,
                out matchesDirectionless,
                out shortLabel);
        }

        private bool TryEvaluateStrategyCustomEventOptionCore(
            StrategyCustomEventOption option,
            string symbolName,
            Bars sourceBars,
            TimeFrame strategyTimeFrame,
            int latestClosedIndex,
            SharedIndicatorSnapshot previousSnapshot,
            SharedIndicatorSnapshot currentSnapshot,
            HashSet<string> sharedPatterns,
            List<CanonicalMarketEvent> recentCanonicalEvents,
            List<CanonicalMarketEvent> eventsOnBar,
            out bool matchesBullish,
            out bool matchesBearish,
            out bool matchesDirectionless,
            out string shortLabel)
        {
            matchesBullish = false;
            matchesBearish = false;
            matchesDirectionless = false;
            shortLabel = "";

            CanonicalEventType canonicalType;
            if (TryMapStrategyCustomCanonicalEventOption(option, out canonicalType, out shortLabel))
            {
                matchesBullish = (eventsOnBar ?? new List<CanonicalMarketEvent>()).Any(evt => evt.EventType == canonicalType && evt.IsBullish);
                matchesBearish = (eventsOnBar ?? new List<CanonicalMarketEvent>()).Any(evt => evt.EventType == canonicalType && !evt.IsBullish);
                return true;
            }

            string artifactKind;
            if (TryMapStrategyArtifactReactionEventOption(option, out canonicalType, out artifactKind, out shortLabel))
            {
                matchesBullish = (eventsOnBar ?? new List<CanonicalMarketEvent>()).Any(evt =>
                    evt.EventType == canonicalType && evt.IsBullish &&
                    string.Equals(evt.LevelKind, artifactKind, StringComparison.OrdinalIgnoreCase));
                matchesBearish = (eventsOnBar ?? new List<CanonicalMarketEvent>()).Any(evt =>
                    evt.EventType == canonicalType && !evt.IsBullish &&
                    string.Equals(evt.LevelKind, artifactKind, StringComparison.OrdinalIgnoreCase));
                return true;
            }

            // Any Structure Event = OR of all structure events (CHOCH/BOS/SR/RJ/BR/PB/CT/IM).
            // It is a selector, not a real event: resolve down to the actual event(s) on the bar
            // so the label describes the real structure event that fired.
            if (option == StrategyCustomEventOption.__AnyStructureEvent)
            {
                shortLabel = "";
                var barEvents = eventsOnBar ?? new List<CanonicalMarketEvent>();
                var matchedBullish = barEvents
                    .Where(evt => IsStructureEventType(evt.EventType) && evt.IsBullish)
                    .OrderByDescending(evt => evt.Score)
                    .FirstOrDefault();
                var matchedBearish = barEvents
                    .Where(evt => IsStructureEventType(evt.EventType) && !evt.IsBullish)
                    .OrderByDescending(evt => evt.Score)
                    .FirstOrDefault();
                matchesBullish = matchedBullish.EventKey != null;
                matchesBearish = matchedBearish.EventKey != null;
                if (!matchesBullish && !matchesBearish)
                    return false;
                var resolvedLabels = new List<string>();
                if (matchesBullish)
                    resolvedLabels.Add(GetCanonicalEventTypeShortLabel(matchedBullish.EventType));
                if (matchesBearish && (!matchesBullish || matchedBearish.EventType != matchedBullish.EventType))
                    resolvedLabels.Add(GetCanonicalEventTypeShortLabel(matchedBearish.EventType));
                shortLabel = string.Join("+", resolvedLabels.Distinct());
                if (string.IsNullOrWhiteSpace(shortLabel))
                    shortLabel = "SME";
                return true;
            }

            if (sourceBars == null || latestClosedIndex < 1 || latestClosedIndex >= sourceBars.Count)
                return false;

            var index = latestClosedIndex;
            if (option == StrategyCustomEventOption.__AnyTechnicalEvent)
            {
                var technicalOptions = new[]
                {
                    StrategyCustomEventOption.Pxe_PriceEmaCross,
                    StrategyCustomEventOption.Emx_EmaFastMidCross,
                    StrategyCustomEventOption.Emt_EmaMidSlowCross,
                    StrategyCustomEventOption.Vwx_PriceVwapCross,
                    StrategyCustomEventOption.Vwr_VwapRejection,
                    StrategyCustomEventOption.Bbx_BollingerMidCross,
                    StrategyCustomEventOption.Bbr_BollingerBandReject,
                    StrategyCustomEventOption.R50_RsiMidlineCross,
                    StrategyCustomEventOption.Ros_RsiExitOversold,
                    StrategyCustomEventOption.Rob_RsiExitOverbought,
                    StrategyCustomEventOption.Stx_StochCross,
                    StrategyCustomEventOption.Sto_StochExitExtreme,
                    StrategyCustomEventOption.Mdx_MacdSignalCross,
                    StrategyCustomEventOption.Md0_MacdZeroCross,
                    StrategyCustomEventOption.Div_Divergence
                };
                var bullishLabels = new List<string>();
                var bearishLabels = new List<string>();
                foreach (var technicalOption in technicalOptions)
                {
                    bool technicalBullish;
                    bool technicalBearish;
                    bool technicalDirectionless;
                    string technicalLabel;
                    if (!TryEvaluateStrategyCustomEventOptionCore(
                        technicalOption,
                        symbolName,
                        sourceBars,
                        strategyTimeFrame,
                        latestClosedIndex,
                        previousSnapshot,
                        currentSnapshot,
                        sharedPatterns,
                        recentCanonicalEvents,
                        eventsOnBar,
                        out technicalBullish,
                        out technicalBearish,
                        out technicalDirectionless,
                        out technicalLabel))
                        continue;

                    if (technicalBullish)
                        bullishLabels.Add(technicalLabel);
                    if (technicalBearish)
                        bearishLabels.Add(technicalLabel);
                }

                matchesBullish = bullishLabels.Count > 0;
                matchesBearish = bearishLabels.Count > 0;
                if (!matchesBullish && !matchesBearish)
                    return false;
                shortLabel = string.Join("+", bullishLabels.Concat(bearishLabels).Where(label => !string.IsNullOrWhiteSpace(label)).Distinct());
                return true;
            }

            switch (option)
            {
                case StrategyCustomEventOption.Pxe_PriceEmaCross:
                    shortLabel = "pxe";
                    matchesBullish = MatchBullishPriceCrossesEmaSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    matchesBearish = MatchBearishPriceCrossesEmaSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    return true;
                case StrategyCustomEventOption.Emx_EmaFastMidCross:
                    shortLabel = "emx";
                    matchesBullish = MatchBullishEmaFastMidCrossSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    matchesBearish = MatchBearishEmaFastMidCrossSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    return true;
                case StrategyCustomEventOption.Emt_EmaMidSlowCross:
                    shortLabel = "emt";
                    matchesBullish = MatchBullishEmaMidSlowCrossSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    matchesBearish = MatchBearishEmaMidSlowCrossSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    return true;
                case StrategyCustomEventOption.Vwx_PriceVwapCross:
                    shortLabel = "vwx";
                    matchesBullish = MatchBullishPriceCrossesVwapSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    matchesBearish = MatchBearishPriceCrossesVwapSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    return true;
                case StrategyCustomEventOption.Vwr_VwapRejection:
                    shortLabel = "vwr";
                    matchesBullish = MatchBullishVwapRejectionSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    matchesBearish = MatchBearishVwapRejectionSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    return true;
                case StrategyCustomEventOption.Bbx_BollingerMidCross:
                    shortLabel = "bbx";
                    matchesBullish = MatchBullishPriceCrossesBollingerMidSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    matchesBearish = MatchBearishPriceCrossesBollingerMidSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    return true;
                case StrategyCustomEventOption.Bbr_BollingerBandReject:
                    shortLabel = "bbr";
                    matchesBullish = MatchBullishBollingerRejectionSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    matchesBearish = MatchBearishBollingerRejectionSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    return true;
                case StrategyCustomEventOption.R50_RsiMidlineCross:
                    shortLabel = "r50";
                    matchesBullish = MatchBullishRsiCrossSnapshot(sourceBars, index, previousSnapshot, currentSnapshot, _resolvedRsiEventConfig.Midline);
                    matchesBearish = MatchBearishRsiCrossSnapshot(sourceBars, index, previousSnapshot, currentSnapshot, _resolvedRsiEventConfig.Midline);
                    return true;
                case StrategyCustomEventOption.Ros_RsiExitOversold:
                    shortLabel = "ros";
                    matchesBullish = MatchBullishRsiOversoldSnapshot(sourceBars, index, previousSnapshot, currentSnapshot, _resolvedRsiEventConfig.Oversold);
                    return true;
                case StrategyCustomEventOption.Rob_RsiExitOverbought:
                    shortLabel = "rob";
                    matchesBearish = MatchBearishRsiOverboughtSnapshot(sourceBars, index, previousSnapshot, currentSnapshot, _resolvedRsiEventConfig.Overbought);
                    return true;
                case StrategyCustomEventOption.Stx_StochCross:
                    shortLabel = "stx";
                    matchesBullish = MatchBullishStochasticCrossSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    matchesBearish = MatchBearishStochasticCrossSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    return true;
                case StrategyCustomEventOption.Sto_StochExitExtreme:
                    shortLabel = "sto";
                    matchesBullish = MatchBullishStochasticExitOversoldSnapshot(sourceBars, index, previousSnapshot, currentSnapshot, _resolvedStochasticEventConfig.OversoldLevel);
                    matchesBearish = MatchBearishStochasticExitOverboughtSnapshot(sourceBars, index, previousSnapshot, currentSnapshot, _resolvedStochasticEventConfig.OverboughtLevel);
                    return true;
                case StrategyCustomEventOption.Mdx_MacdSignalCross:
                    shortLabel = "mdx";
                    matchesBullish = MatchBullishMacdCrossSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    matchesBearish = MatchBearishMacdCrossSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    return true;
                case StrategyCustomEventOption.Md0_MacdZeroCross:
                    shortLabel = "md0";
                    matchesBullish = MatchBullishMacdZeroCrossSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    matchesBearish = MatchBearishMacdZeroCrossSnapshot(sourceBars, index, previousSnapshot, currentSnapshot);
                    return true;
                case StrategyCustomEventOption.Pin_PinBar:
                    shortLabel = "PIN";
                    matchesBullish = MatchBullishPinBar(sourceBars, index);
                    matchesBearish = MatchBearishPinBar(sourceBars, index);
                    return true;
                case StrategyCustomEventOption.Eng_Engulfing:
                    shortLabel = "ENG";
                    matchesBullish = MatchBullishEngulfingAtIndex(sourceBars, index);
                    matchesBearish = MatchBearishEngulfingAtIndex(sourceBars, index);
                    return true;
                case StrategyCustomEventOption.Big_BigCandle:
                    shortLabel = "BIG";
                    matchesBullish = MatchBullishBigCandle(sourceBars, index);
                    matchesBearish = MatchBearishBigCandle(sourceBars, index);
                    return true;
                case StrategyCustomEventOption.Mor_MorningStar:
                    shortLabel = "MOR";
                    matchesBullish = sharedPatterns.Contains("bullish_morning_star");
                    return true;
                case StrategyCustomEventOption.Eve_EveningStar:
                    shortLabel = "EVE";
                    matchesBearish = sharedPatterns.Contains("bearish_evening_star");
                    return true;
                case StrategyCustomEventOption.Ham_Hammer:
                    shortLabel = "HAM";
                    matchesBullish = sharedPatterns.Contains("bullish_hammer");
                    return true;
                case StrategyCustomEventOption.Hgm_HangingMan:
                    shortLabel = "HGM";
                    matchesBearish = sharedPatterns.Contains("hanging_man");
                    return true;
                case StrategyCustomEventOption.Sst_ShootingStar:
                    shortLabel = "SST";
                    matchesBearish = sharedPatterns.Contains("shooting_star");
                    return true;
                case StrategyCustomEventOption.Ihm_InvertedHammer:
                    shortLabel = "IHM";
                    matchesBullish = sharedPatterns.Contains("bullish_inverted_hammer");
                    return true;
                case StrategyCustomEventOption.Prc_PiercingLine:
                    shortLabel = "PRC";
                    matchesBullish = sharedPatterns.Contains("bullish_piercing_line");
                    return true;
                case StrategyCustomEventOption.Dcc_DarkCloudCover:
                    shortLabel = "DCC";
                    matchesBearish = sharedPatterns.Contains("bearish_dark_cloud_cover");
                    return true;
                case StrategyCustomEventOption.Tws_ThreeWhiteSoldiers:
                    shortLabel = "3WS";
                    matchesBullish = sharedPatterns.Contains("bullish_three_white_soldiers");
                    return true;
                case StrategyCustomEventOption.Tbc_ThreeBlackCrows:
                    shortLabel = "3BC";
                    matchesBearish = sharedPatterns.Contains("bearish_three_black_crows");
                    return true;
                case StrategyCustomEventOption.Har_Harami:
                    shortLabel = "HAR";
                    matchesBullish = sharedPatterns.Contains("bullish_harami");
                    matchesBearish = sharedPatterns.Contains("bearish_harami");
                    return true;
                case StrategyCustomEventOption.__AnyCandlePattern:
                {
                    // Any Candle Pattern = OR of all candle patterns; resolve down to the real
                    // pattern code(s) so the label describes the actual pattern that fired.
                    shortLabel = "";
                    var bullishCodes = new List<string>();
                    var bearishCodes = new List<string>();
                    if (MatchBullishPinBar(sourceBars, index)) bullishCodes.Add("PIN");
                    if (MatchBearishPinBar(sourceBars, index)) bearishCodes.Add("PIN");
                    if (MatchBullishEngulfingAtIndex(sourceBars, index)) bullishCodes.Add("ENG");
                    if (MatchBearishEngulfingAtIndex(sourceBars, index)) bearishCodes.Add("ENG");
                    if (MatchBullishBigCandle(sourceBars, index)) bullishCodes.Add("BIG");
                    if (MatchBearishBigCandle(sourceBars, index)) bearishCodes.Add("BIG");
                    if (sharedPatterns.Contains("bullish_morning_star")) bullishCodes.Add("MOR");
                    if (sharedPatterns.Contains("bearish_evening_star")) bearishCodes.Add("EVE");
                    if (sharedPatterns.Contains("bullish_hammer")) bullishCodes.Add("HAM");
                    if (sharedPatterns.Contains("hanging_man")) bearishCodes.Add("HGM");
                    if (sharedPatterns.Contains("shooting_star")) bearishCodes.Add("SST");
                    if (sharedPatterns.Contains("bullish_inverted_hammer")) bullishCodes.Add("IHM");
                    if (sharedPatterns.Contains("bullish_piercing_line")) bullishCodes.Add("PRC");
                    if (sharedPatterns.Contains("bearish_dark_cloud_cover")) bearishCodes.Add("DCC");
                    if (sharedPatterns.Contains("bullish_three_white_soldiers")) bullishCodes.Add("3WS");
                    if (sharedPatterns.Contains("bearish_three_black_crows")) bearishCodes.Add("3BC");
                    if (sharedPatterns.Contains("bullish_harami")) bullishCodes.Add("HAR");
                    if (sharedPatterns.Contains("bearish_harami")) bearishCodes.Add("HAR");
                    matchesBullish = bullishCodes.Count > 0;
                    matchesBearish = bearishCodes.Count > 0;
                    if (!matchesBullish && !matchesBearish)
                        return false;
                    shortLabel = string.Join("+", bullishCodes.Concat(bearishCodes).Distinct());
                    return true;
                }
                case StrategyCustomEventOption.Div_Divergence:
                    shortLabel = "DIV";
                    bool divBullish;
                    bool divBearish;
                    if (TryDetectDivergenceAtIndex(sourceBars, index, out divBullish, out divBearish))
                    {
                        matchesBullish = divBullish;
                        matchesBearish = divBearish;
                        return true;
                    }
                    return false;
                default:
                    return false;
            }
        }

        private bool IsStructureEventType(CanonicalEventType eventType)
        {
            switch (eventType)
            {
                case CanonicalEventType.Choch:
                case CanonicalEventType.Bos:
                case CanonicalEventType.SweepReclaim:
                case CanonicalEventType.Rejection:
                case CanonicalEventType.Breakout:
                case CanonicalEventType.Pullback:
                case CanonicalEventType.Continuation:
                case CanonicalEventType.Impulse:
                    return true;
                default:
                    return false;
            }
        }

        private string GetCanonicalEventTypeShortLabel(CanonicalEventType eventType)
        {
            switch (eventType)
            {
                case CanonicalEventType.Choch:
                    return "CHOCH";
                case CanonicalEventType.Bos:
                    return "BOS";
                case CanonicalEventType.SweepReclaim:
                    return "SR";
                case CanonicalEventType.Rejection:
                    return "RJ";
                case CanonicalEventType.Breakout:
                    return "BR";
                case CanonicalEventType.Pullback:
                    return "PB";
                case CanonicalEventType.Continuation:
                    return "CT";
                case CanonicalEventType.Impulse:
                    return "IM";
                default:
                    return "EVT";
            }
        }

        // Divergence-as-event: same RSI swing logic as the chart divergence draw, evaluated on
        // the strategy timeframe's latest closed bar. Bullish = lower low + higher RSI;
        // bearish = higher high + lower RSI.
        private bool TryDetectDivergenceAtIndex(Bars sourceBars, int confirmationIndex, out bool bullishDiv, out bool bearishDiv)
        {
            bullishDiv = false;
            bearishDiv = false;
            if (sourceBars == null || sourceBars.Count < 40 || confirmationIndex < 3 || confirmationIndex >= sourceBars.Count)
                return false;
            try
            {
                const int swingStrength = 2;
                var swings = CollectConfirmedSwings(sourceBars, 220, confirmationIndex);
                if (swings == null || swings.Count < 6)
                    return false;

                var rsiConfig = ResolveRsiIndicatorConfig(DrawRsiMode == RsiVisualMode.Off ? RsiVisualMode.Auto : DrawRsiMode);
                var recentLows = swings.Where(swing => !swing.IsHigh).TakeLast(8).ToList();
                var recentHighs = swings.Where(swing => swing.IsHigh).TakeLast(8).ToList();

                for (var i = recentLows.Count - 1; i >= 1; i--)
                {
                    var left = recentLows[i - 1];
                    var right = recentLows[i];
                    if (right.BarIndex + swingStrength != confirmationIndex)
                        continue;
                    var leftRsi = ComputeRelativeStrengthIndex(sourceBars, left.BarIndex, rsiConfig.Period);
                    var rightRsi = ComputeRelativeStrengthIndex(sourceBars, right.BarIndex, rsiConfig.Period);
                    if (right.Price < left.Price && rightRsi > leftRsi && IsFiniteNumber(leftRsi) && IsFiniteNumber(rightRsi))
                    {
                        bullishDiv = true;
                        break;
                    }
                }

                for (var i = recentHighs.Count - 1; i >= 1; i--)
                {
                    var left = recentHighs[i - 1];
                    var right = recentHighs[i];
                    if (right.BarIndex + swingStrength != confirmationIndex)
                        continue;
                    var leftRsi = ComputeRelativeStrengthIndex(sourceBars, left.BarIndex, rsiConfig.Period);
                    var rightRsi = ComputeRelativeStrengthIndex(sourceBars, right.BarIndex, rsiConfig.Period);
                    if (right.Price > left.Price && rightRsi < leftRsi && IsFiniteNumber(leftRsi) && IsFiniteNumber(rightRsi))
                    {
                        bearishDiv = true;
                        break;
                    }
                }

                return bullishDiv || bearishDiv;
            }
            catch
            {
                return false;
            }
        }

        private bool TryGetCanonicalEventsOnLatestClosedBar(string symbolName, TimeFrame timeFrame, out DateTime latestClosedBarTime, out List<CanonicalMarketEvent> eventsOnBar)
        {
            latestClosedBarTime = DateTime.MinValue;
            eventsOnBar = new List<CanonicalMarketEvent>();
            if (string.IsNullOrWhiteSpace(symbolName))
                return false;

            if (!TryGetLatestClosedCanonicalBarTime(symbolName, timeFrame, out latestClosedBarTime))
                return false;

            var closedBarTime = latestClosedBarTime;

            eventsOnBar = GetCanonicalEventsForSymbolTimeFrame(symbolName, timeFrame, 24)
                .Where(evt => evt.BarTime == closedBarTime)
                .OrderByDescending(evt => evt.Score)
                .ToList();
            return true;
        }

        private bool TryResolveStrategyCustomEventBundle(
            string symbolName,
            TimeFrame strategyTimeFrame,
            TradeType? preferredTradeType,
            out TradeType resolvedTradeType,
            out DateTime signalTime,
            out string sourceLabel,
            out string note,
            out double eventSlDistance)
        {
            resolvedTradeType = TradeType.Buy;
            signalTime = DateTime.MinValue;
            sourceLabel = "";
            note = "";
            eventSlDistance = 0;

            var selectedOptions = GetSelectedStrategyCustomEventOptions();
            var selectedRules = GetSelectedStrategyCustomRuleOptions();
            if (selectedOptions.Count == 0 && selectedRules.Count == 0)
                return preferredTradeType.HasValue;

            Bars sourceBars = null;
            try
            {
                sourceBars = MarketData.GetBars(strategyTimeFrame, symbolName);
            }
            catch
            {
                sourceBars = null;
            }
            if (sourceBars == null || sourceBars.Count < 3)
                return false;

            var latestClosedIndex = sourceBars.Count - 2;
            if (latestClosedIndex < 1 || latestClosedIndex >= sourceBars.Count)
                return false;

            if (!string.IsNullOrWhiteSpace(SharedStrategyConfigIds))
            {
                return TryResolveSharedConfigStrategy(
                    symbolName,
                    strategyTimeFrame,
                    sourceBars,
                    latestClosedIndex,
                    preferredTradeType,
                    out resolvedTradeType,
                    out signalTime,
                    out sourceLabel,
                    out note,
                    out eventSlDistance);
            }

            var previousSnapshot = BuildSharedIndicatorSnapshot(sourceBars, latestClosedIndex - 1);
            var currentSnapshot = BuildSharedIndicatorSnapshot(sourceBars, latestClosedIndex);

            // Rules are always ANDed (the event AND/OR mode does not apply to rules) and the
            // whole rule set must pass for the signal to be valid. Rules never set direction.
            if (selectedOptions.Count == 0)
            {
                if (!preferredTradeType.HasValue)
                    return false;

                var preferredBullish = preferredTradeType.Value == TradeType.Buy;
                var rulesLabel = BuildSelectedRulesLabel(symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, previousSnapshot, currentSnapshot, preferredBullish);
                if (!TryPassSelectedStrategyCustomRules(symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, previousSnapshot, currentSnapshot, preferredBullish))
                    return false;

                resolvedTradeType = preferredTradeType.Value;
                signalTime = sourceBars.OpenTimes[latestClosedIndex];
                sourceLabel = "";
                note = string.IsNullOrWhiteSpace(rulesLabel)
                    ? "[custom_rules=pass]"
                    : "[custom_rules=pass;rules=" + rulesLabel + "]";
                eventSlDistance = 0;
                return true;
            }

            // Do not use the cross-timeframe display sequence here. That sequence used to
            // discard a fresh main-TF signal when an older higher-TF event had the opposite
            // direction. Trigger selection belongs to the strategy timeframe; LTF/HTF
            // agreement belongs to the separately selected confluence rules.
            var primaryTriggerSequence = CollectTradeTriggerCandidates(symbolName, strategyTimeFrame)
                .Where(trigger => trigger.BarTime == sourceBars.OpenTimes[latestClosedIndex])
                .ToList();
            var optionStates = BuildSelectedTriggerOptionStates(selectedOptions, primaryTriggerSequence);
            var requiredEventCount = selectedOptions.Count;

            if (optionStates.Count == 0)
                return false;

            Func<bool, Tuple<bool, int, int, string>> evaluateDirection = bullish =>
            {
                var matchedLabels = new List<string>();
                var matchedScore = 0;
                var matchedCount = 0;

                foreach (var selection in optionStates)
                {
                    var directionalMatch = bullish ? selection.Item3 : selection.Item4;
                    var directionlessMatch = selection.Item5;
                    if (directionalMatch || directionlessMatch)
                    {
                        matchedLabels.Add(selection.Item2);
                        matchedScore += directionalMatch ? 1 : 0;
                        matchedCount++;
                    }
                }

                var passed = SelectedStrategyCustomEventsMode == StrategyCustomEventsMode.AND
                    ? matchedCount == requiredEventCount
                    : matchedCount > 0;
                return Tuple.Create(passed, matchedScore, matchedCount, string.Join("+", matchedLabels));
            };

            if (preferredTradeType.HasValue)
            {
                var preferredBullish = preferredTradeType.Value == TradeType.Buy;
                var rulesLabel = BuildSelectedRulesLabel(symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, previousSnapshot, currentSnapshot, preferredBullish);
                if (!TryPassSelectedStrategyCustomRules(symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, previousSnapshot, currentSnapshot, preferredBullish))
                    return false;
                var preferredResult = evaluateDirection(preferredBullish);
                if (!preferredResult.Item1)
                    return false;

                resolvedTradeType = preferredTradeType.Value;
                TradeTriggerEvent primaryTrigger;
                if (!TryResolvePrimaryTradeTrigger(primaryTriggerSequence, selectedOptions, preferredBullish, out primaryTrigger))
                    return false;
                sourceLabel = primaryTrigger.Name;
                signalTime = primaryTrigger.BarTime;
                note = string.Format(
                    CultureInfo.InvariantCulture,
                    "[custom_events={0}:{1}{2}]",
                    SelectedStrategyCustomEventsMode,
                    sourceLabel,
                    string.IsNullOrWhiteSpace(rulesLabel) ? "" : ";rules=" + rulesLabel);
                eventSlDistance = primaryTrigger.StopDistance;
                return true;
            }

            var bullishResult = evaluateDirection(true);
            var bearishResult = evaluateDirection(false);
            var bullishRulesPass = TryPassSelectedStrategyCustomRules(symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, previousSnapshot, currentSnapshot, true);
            var bearishRulesPass = TryPassSelectedStrategyCustomRules(symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, previousSnapshot, currentSnapshot, false);
            var bullishRulesLabel = bullishRulesPass
                ? BuildSelectedRulesLabel(symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, previousSnapshot, currentSnapshot, true)
                : "";
            var bearishRulesLabel = bearishRulesPass
                ? BuildSelectedRulesLabel(symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, previousSnapshot, currentSnapshot, false)
                : "";
            if (!bullishRulesPass)
                bullishResult = Tuple.Create(false, bullishResult.Item2, bullishResult.Item3, bullishResult.Item4);
            if (!bearishRulesPass)
                bearishResult = Tuple.Create(false, bearishResult.Item2, bearishResult.Item3, bearishResult.Item4);
            if (!bullishResult.Item1 && !bearishResult.Item1)
                return false;

            if (bullishResult.Item1 && bearishResult.Item1)
            {
                // A trigger bar can contain conflicting patterns (for example pin↑ and eng↓).
                // Choose the stronger event first so the displayed representative and the trade
                // source agree; confluence only breaks an equal-strength tie.
                TradeTriggerEvent bullishPrimary;
                TradeTriggerEvent bearishPrimary;
                var hasBullishPrimary = TryResolvePrimaryTradeTrigger(primaryTriggerSequence, selectedOptions, true, out bullishPrimary);
                var hasBearishPrimary = TryResolvePrimaryTradeTrigger(primaryTriggerSequence, selectedOptions, false, out bearishPrimary);
                if (!hasBullishPrimary || !hasBearishPrimary)
                    return false;
                if (bullishPrimary.Priority > bearishPrimary.Priority)
                    bearishResult = Tuple.Create(false, bearishResult.Item2, bearishResult.Item3, bearishResult.Item4);
                else if (bearishPrimary.Priority > bullishPrimary.Priority)
                    bullishResult = Tuple.Create(false, bullishResult.Item2, bullishResult.Item3, bullishResult.Item4);
                else
                {
                    var bullishConfidence = CalculateStrategyConfluenceScore(symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, currentSnapshot, true);
                    var bearishConfidence = CalculateStrategyConfluenceScore(symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, currentSnapshot, false);
                    if (bullishConfidence.Score == bearishConfidence.Score)
                        return false;
                    if (bullishConfidence.Score > bearishConfidence.Score)
                        bearishResult = Tuple.Create(false, bearishResult.Item2, bearishResult.Item3, bearishResult.Item4);
                    else
                        bullishResult = Tuple.Create(false, bullishResult.Item2, bullishResult.Item3, bullishResult.Item4);
                }
            }

            if (bullishResult.Item1)
            {
                resolvedTradeType = TradeType.Buy;
            }
            else
            {
                resolvedTradeType = TradeType.Sell;
            }

            var resolvedBullish = resolvedTradeType == TradeType.Buy;
            TradeTriggerEvent resolvedPrimaryTrigger;
            if (!TryResolvePrimaryTradeTrigger(primaryTriggerSequence, selectedOptions, resolvedBullish, out resolvedPrimaryTrigger))
                return false;
            sourceLabel = resolvedPrimaryTrigger.Name;
            signalTime = resolvedPrimaryTrigger.BarTime;
            var resolvedRulesLabel = resolvedBullish ? bullishRulesLabel : bearishRulesLabel;
            note = string.Format(
                CultureInfo.InvariantCulture,
                "[custom_events={0}:{1}{2}]",
                SelectedStrategyCustomEventsMode,
                sourceLabel,
                string.IsNullOrWhiteSpace(resolvedRulesLabel) ? "" : ";rules=" + resolvedRulesLabel);
            eventSlDistance = resolvedPrimaryTrigger.StopDistance;
            return true;
        }

        private bool TryResolvePrimaryTradeTrigger(
            IEnumerable<TradeTriggerEvent> triggerSequence,
            IEnumerable<StrategyCustomEventOption> selectedOptions,
            bool bullish,
            out TradeTriggerEvent primaryTrigger)
        {
            primaryTrigger = default(TradeTriggerEvent);
            var selections = (selectedOptions ?? Enumerable.Empty<StrategyCustomEventOption>()).ToList();
            primaryTrigger = (triggerSequence ?? Enumerable.Empty<TradeTriggerEvent>())
                .Where(trigger => selections.Any(option => TradeTriggerMatchesSelectedOption(trigger, option)))
                .Where(trigger => trigger.IsDirectionless || trigger.IsBullish == bullish)
                .OrderByDescending(trigger => !trigger.IsDirectionless)
                .ThenByDescending(trigger => trigger.Priority)
                .ThenByDescending(trigger => trigger.HasCanonicalEvent ? trigger.CanonicalEvent.Score : 0)
                .FirstOrDefault();
            return !string.IsNullOrWhiteSpace(primaryTrigger.Name);
        }

        private List<Tuple<StrategyCustomEventOption, string, bool, bool, bool>> BuildSelectedTriggerOptionStates(
            IEnumerable<StrategyCustomEventOption> selectedOptions,
            List<TradeTriggerEvent> triggerSequence)
        {
            var states = new List<Tuple<StrategyCustomEventOption, string, bool, bool, bool>>();
            foreach (var option in selectedOptions ?? Enumerable.Empty<StrategyCustomEventOption>())
            {
                var matches = (triggerSequence ?? new List<TradeTriggerEvent>())
                    .Where(trigger => TradeTriggerMatchesSelectedOption(trigger, option))
                    .ToList();
                if (matches.Count == 0)
                    continue;

                var labels = matches
                    .Select(trigger => trigger.Name)
                    .Where(label => !string.IsNullOrWhiteSpace(label))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToList();
                states.Add(Tuple.Create(
                    option,
                    string.Join("+", labels),
                    matches.Any(trigger => !trigger.IsDirectionless && trigger.IsBullish),
                    matches.Any(trigger => !trigger.IsDirectionless && !trigger.IsBullish),
                    matches.Any(trigger => trigger.IsDirectionless)));
            }
            return states;
        }

        // Visuals intentionally retain historical detections. This audit only inspects the
        // latest closed strategy bar, which is the only bar eligible to open or queue a trade.
        private string BuildCustomTradeTriggerAudit(string symbolName, TimeFrame strategyTimeFrame)
        {
            var selected = GetSelectedStrategyCustomEventOptions();
            var selectedText = selected.Count == 0
                ? "none"
                : string.Join(",", selected.Select(option => option.ToString()));
            Bars sourceBars;
            try { sourceBars = GetBarsForCurrentMasterTimer(strategyTimeFrame, symbolName); }
            catch { sourceBars = null; }
            if (sourceBars == null || sourceBars.Count < 3)
                return string.Format(CultureInfo.InvariantCulture, "tf={0} selected=[{1}] bars=unavailable", GetTimeFrameShortLabel(strategyTimeFrame), selectedText);

            var latestClosedIndex = sourceBars.Count - 2;
            var barTime = sourceBars.OpenTimes[latestClosedIndex];
            var onClosedBar = CollectTradeTriggerCandidates(symbolName, strategyTimeFrame)
                .Where(trigger => trigger.BarTime == barTime)
                .ToList();
            var events = onClosedBar
                .Select(trigger => trigger.Name)
                .Where(name => !string.IsNullOrWhiteSpace(name))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(8)
                .ToList();
            var matching = onClosedBar
                .Where(trigger => selected.Any(option => TradeTriggerMatchesSelectedOption(trigger, option)))
                .Select(trigger => trigger.Name)
                .Where(name => !string.IsNullOrWhiteSpace(name))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(6)
                .ToList();
            return string.Format(
                CultureInfo.InvariantCulture,
                "tf={0} closed={1:yyyy-MM-dd HH:mm} selected=[{2}] events=[{3}] matched=[{4}]",
                GetTimeFrameShortLabel(strategyTimeFrame),
                barTime,
                selectedText,
                events.Count == 0 ? "none" : string.Join(",", events),
                matching.Count == 0 ? "none" : string.Join(",", matching));
        }

        private string BuildRecentCandlePatternTriggerAudit(string symbolName, TimeFrame strategyTimeFrame, int barsBack)
        {
            Bars sourceBars;
            try { sourceBars = GetBarsForCurrentMasterTimer(strategyTimeFrame, symbolName); }
            catch { sourceBars = null; }
            if (sourceBars == null || sourceBars.Count < 3)
                return "bars=unavailable";

            var latestClosedIndex = sourceBars.Count - 2;
            var firstIndex = Math.Max(1, latestClosedIndex - Math.Max(1, barsBack) + 1);
            var parts = new List<string>();
            for (var index = latestClosedIndex; index >= firstIndex; index--)
            {
                var labels = new List<string>();
                if (MatchBullishEngulfingAtIndex(sourceBars, index)) labels.Add("eng↑");
                if (MatchBearishEngulfingAtIndex(sourceBars, index)) labels.Add("eng↓");
                if (MatchBullishPinBar(sourceBars, index)) labels.Add("pin↑");
                if (MatchBearishPinBar(sourceBars, index)) labels.Add("pin↓");
                if (MatchBullishBigCandle(sourceBars, index)) labels.Add("big↑");
                if (MatchBearishBigCandle(sourceBars, index)) labels.Add("big↓");

                parts.Add(string.Format(
                    CultureInfo.InvariantCulture,
                    "{0:HH:mm}:{1}[o={2} h={3} l={4} c={5}]",
                    sourceBars.OpenTimes[index],
                    labels.Count == 0 ? "-" : string.Join("+", labels),
                    FormatPriceShort(sourceBars.OpenPrices[index]),
                    FormatPriceShort(sourceBars.HighPrices[index]),
                    FormatPriceShort(sourceBars.LowPrices[index]),
                    FormatPriceShort(sourceBars.ClosePrices[index])));
            }

            return parts.Count == 0 ? "none" : string.Join(" | ", parts);
        }

        private bool TradeTriggerMatchesSelectedOption(TradeTriggerEvent trigger, StrategyCustomEventOption selectedOption)
        {
            if (selectedOption == trigger.Option)
                return true;

            var selectedName = selectedOption.ToString();
            string family;
            if (selectedName.StartsWith("__AnyStructureEvent", StringComparison.Ordinal)) family = "structure";
            else if (selectedName.StartsWith("__AnyCandlePattern", StringComparison.Ordinal)) family = "candle";
            else if (selectedName.StartsWith("__AnyTechnicalEvent", StringComparison.Ordinal)) family = "technical";
            else return false;
            if (!string.Equals(trigger.Family, family, StringComparison.OrdinalIgnoreCase))
                return false;

            var selectedContinue = selectedName.EndsWith("_c", StringComparison.Ordinal);
            var selectedReverse = selectedName.EndsWith("_r", StringComparison.Ordinal);
            var triggerName = trigger.Option.ToString();
            var triggerContinue = triggerName.EndsWith("_c", StringComparison.Ordinal);
            var triggerReverse = triggerName.EndsWith("_r", StringComparison.Ordinal);
            return selectedContinue ? triggerContinue : selectedReverse ? triggerReverse : !triggerContinue && !triggerReverse;
        }

        private DateTime ResolveTradeTriggerSignalTime(IEnumerable<TradeTriggerEvent> triggerSequence, IEnumerable<StrategyCustomEventOption> selectedOptions, bool bullish)
        {
            var selections = (selectedOptions ?? Enumerable.Empty<StrategyCustomEventOption>()).ToList();
            return (triggerSequence ?? Enumerable.Empty<TradeTriggerEvent>())
                .Where(trigger => selections.Any(option => TradeTriggerMatchesSelectedOption(trigger, option)))
                .Where(trigger => trigger.IsDirectionless || trigger.IsBullish == bullish)
                .Select(trigger => trigger.BarTime)
                .DefaultIfEmpty(DateTime.MinValue)
                .Max();
        }

        private double ResolveTradeTriggerStopDistance(IEnumerable<TradeTriggerEvent> triggerSequence, IEnumerable<StrategyCustomEventOption> selectedOptions, bool bullish)
        {
            var selections = (selectedOptions ?? Enumerable.Empty<StrategyCustomEventOption>()).ToList();
            return (triggerSequence ?? Enumerable.Empty<TradeTriggerEvent>())
                .Where(trigger => selections.Any(option => TradeTriggerMatchesSelectedOption(trigger, option)))
                .Where(trigger => trigger.IsDirectionless || trigger.IsBullish == bullish)
                .Select(trigger => trigger.StopDistance)
                .DefaultIfEmpty(0)
                .Max();
        }

        // Default SL distance for a custom-trade signal = height of the related event.
        private double ResolveCustomEventBundleStopDistance(
            List<Tuple<StrategyCustomEventOption, string, bool, bool, bool>> optionStates,
            Bars sourceBars,
            int latestClosedIndex,
            List<CanonicalMarketEvent> recentCanonicalEvents,
            List<CanonicalMarketEvent> eventsOnBar,
            bool bullishDirection)
        {
            var best = 0.0;
            foreach (var selection in optionStates)
            {
                var directionalMatch = bullishDirection ? selection.Item3 : selection.Item4;
                var directionlessMatch = selection.Item5;
                if (!directionalMatch && !directionlessMatch)
                    continue;

                var distance = ResolveCustomEventStopDistance(selection.Item1, sourceBars, latestClosedIndex, recentCanonicalEvents, eventsOnBar, bullishDirection);
                if (distance > best)
                    best = distance;
            }
            return best;
        }

        private double ResolveCustomEventStopDistance(
            StrategyCustomEventOption option,
            Bars sourceBars,
            int latestClosedIndex,
            List<CanonicalMarketEvent> recentCanonicalEvents,
            List<CanonicalMarketEvent> eventsOnBar,
            bool bullishDirection)
        {
            if (sourceBars == null || latestClosedIndex < 0 || latestClosedIndex >= sourceBars.Count)
                return 0;

            StrategyCustomEventOption followUpBaseOption;
            StrategyEventFollowUpOutcome followUpOutcome;
            if (TryMapStrategyFollowUpEventOption(option, out followUpBaseOption, out followUpOutcome))
            {
                if (latestClosedIndex < 1)
                    return 0;

                var eventIndex = latestClosedIndex - 1;
                var eventBarTime = sourceBars.OpenTimes[eventIndex];
                var eventsOnEventBar = (recentCanonicalEvents ?? Enumerable.Empty<CanonicalMarketEvent>())
                    .Where(evt => evt.BarTime == eventBarTime)
                    .OrderByDescending(evt => evt.Score)
                    .ToList();
                var eventDistance = ResolveCustomEventStopDistance(followUpBaseOption, sourceBars, eventIndex, recentCanonicalEvents, eventsOnEventBar, bullishDirection);
                var outcomeRange = Math.Max(sourceBars.HighPrices[latestClosedIndex] - sourceBars.LowPrices[latestClosedIndex], 0);
                return Math.Max(eventDistance, outcomeRange);
            }

            // Candle pattern: SL = height of the pattern candle(s).
            var patternSpan = GetCustomEventPatternBarSpan(option);
            if (patternSpan > 0)
            {
                var start = Math.Max(0, latestClosedIndex - patternSpan + 1);
                var maxRange = 0.0;
                for (var i = start; i <= latestClosedIndex; i++)
                {
                    var range = sourceBars.HighPrices[i] - sourceBars.LowPrices[i];
                    if (range > maxRange)
                        maxRange = range;
                }
                return maxRange;
            }

            // Any Structure Event: SL = zone height of the best matching structure event on bar.
            if (option == StrategyCustomEventOption.__AnyStructureEvent)
            {
                var matched = (eventsOnBar ?? Enumerable.Empty<CanonicalMarketEvent>())
                    .Where(evt => IsStructureEventType(evt.EventType) && evt.IsBullish == bullishDirection)
                    .OrderByDescending(evt => evt.Score)
                    .FirstOrDefault();
                if (matched.EventKey == null)
                    return 0;
                if (matched.ZoneHigh > matched.ZoneLow && matched.ZoneLow > 0)
                    return matched.ZoneHigh - matched.ZoneLow;
                return Math.Max(sourceBars.HighPrices[latestClosedIndex] - sourceBars.LowPrices[latestClosedIndex], 0);
            }

            // Canonical events (RJ OB/FVG, SR, BR, ...): SL = zone height when known, else event bar range.
            CanonicalEventType canonicalType;
            string canonicalLabel;
            if (TryMapStrategyCustomCanonicalEventOption(option, out canonicalType, out canonicalLabel))
            {
                var matched = (eventsOnBar ?? Enumerable.Empty<CanonicalMarketEvent>())
                    .Where(evt => evt.EventType == canonicalType && evt.IsBullish == bullishDirection)
                    .OrderByDescending(evt => evt.Score)
                    .FirstOrDefault();
                if (matched.EventKey == null)
                    return 0;

                if (matched.ZoneHigh > matched.ZoneLow && matched.ZoneLow > 0)
                    return matched.ZoneHigh - matched.ZoneLow;

                for (var i = 0; i < sourceBars.Count; i++)
                {
                    if (sourceBars.OpenTimes[i] == matched.BarTime)
                        return Math.Max(sourceBars.HighPrices[i] - sourceBars.LowPrices[i], 0);
                }
                return Math.Max(sourceBars.HighPrices[latestClosedIndex] - sourceBars.LowPrices[latestClosedIndex], 0);
            }

            // Indicator crosses: the related candle is the signal candle.
            if (IsIndicatorCustomEventOption(option))
                return Math.Max(sourceBars.HighPrices[latestClosedIndex] - sourceBars.LowPrices[latestClosedIndex], 0);

            // Events without their own price geometry fall back to the structural SL.
            return 0;
        }

        private bool TryGetCustomEventPatternWindow(StrategyCustomEventOption option, int latestClosedIndex, out int startIndex, out int endIndex)
        {
            startIndex = -1;
            endIndex = -1;
            if (latestClosedIndex < 0)
                return false;

            StrategyCustomEventOption followUpBaseOption;
            StrategyEventFollowUpOutcome followUpOutcome;
            if (TryMapStrategyFollowUpEventOption(option, out followUpBaseOption, out followUpOutcome))
            {
                var baseSpan = GetCustomEventPatternBarSpan(followUpBaseOption);
                if (baseSpan <= 0 || latestClosedIndex < 1)
                    return false;

                endIndex = latestClosedIndex;
                startIndex = Math.Max(0, (latestClosedIndex - 1) - baseSpan + 1);
                return true;
            }

            var patternSpan = GetCustomEventPatternBarSpan(option);
            if (patternSpan <= 0)
                return false;

            endIndex = latestClosedIndex;
            startIndex = Math.Max(0, latestClosedIndex - patternSpan + 1);
            return true;
        }

        private int GetCustomEventPatternBarSpan(StrategyCustomEventOption option)
        {
            switch (option)
            {
                case StrategyCustomEventOption.Pin_PinBar:
                case StrategyCustomEventOption.Pin_PinBar_c:
                case StrategyCustomEventOption.Pin_PinBar_r:
                case StrategyCustomEventOption.Ham_Hammer:
                case StrategyCustomEventOption.Ham_Hammer_c:
                case StrategyCustomEventOption.Ham_Hammer_r:
                case StrategyCustomEventOption.Hgm_HangingMan:
                case StrategyCustomEventOption.Hgm_HangingMan_c:
                case StrategyCustomEventOption.Hgm_HangingMan_r:
                case StrategyCustomEventOption.Sst_ShootingStar:
                case StrategyCustomEventOption.Sst_ShootingStar_c:
                case StrategyCustomEventOption.Sst_ShootingStar_r:
                case StrategyCustomEventOption.Ihm_InvertedHammer:
                case StrategyCustomEventOption.Ihm_InvertedHammer_c:
                case StrategyCustomEventOption.Ihm_InvertedHammer_r:
                case StrategyCustomEventOption.Big_BigCandle:
                case StrategyCustomEventOption.Big_BigCandle_c:
                case StrategyCustomEventOption.Big_BigCandle_r:
                    return 1;
                case StrategyCustomEventOption.Eng_Engulfing:
                case StrategyCustomEventOption.Eng_Engulfing_c:
                case StrategyCustomEventOption.Eng_Engulfing_r:
                case StrategyCustomEventOption.Prc_PiercingLine:
                case StrategyCustomEventOption.Prc_PiercingLine_c:
                case StrategyCustomEventOption.Prc_PiercingLine_r:
                case StrategyCustomEventOption.Dcc_DarkCloudCover:
                case StrategyCustomEventOption.Dcc_DarkCloudCover_c:
                case StrategyCustomEventOption.Dcc_DarkCloudCover_r:
                    return 2;
                case StrategyCustomEventOption.Mor_MorningStar:
                case StrategyCustomEventOption.Mor_MorningStar_c:
                case StrategyCustomEventOption.Mor_MorningStar_r:
                case StrategyCustomEventOption.Eve_EveningStar:
                case StrategyCustomEventOption.Eve_EveningStar_c:
                case StrategyCustomEventOption.Eve_EveningStar_r:
                case StrategyCustomEventOption.Tws_ThreeWhiteSoldiers:
                case StrategyCustomEventOption.Tws_ThreeWhiteSoldiers_c:
                case StrategyCustomEventOption.Tws_ThreeWhiteSoldiers_r:
                case StrategyCustomEventOption.Tbc_ThreeBlackCrows:
                case StrategyCustomEventOption.Tbc_ThreeBlackCrows_c:
                case StrategyCustomEventOption.Tbc_ThreeBlackCrows_r:
                case StrategyCustomEventOption.Har_Harami:
                case StrategyCustomEventOption.Har_Harami_c:
                case StrategyCustomEventOption.Har_Harami_r:
                case StrategyCustomEventOption.__AnyCandlePattern:
                case StrategyCustomEventOption.__AnyCandlePattern_c:
                case StrategyCustomEventOption.__AnyCandlePattern_r:
                    return 3;
                default:
                    return 0;
            }
        }

        private bool IsIndicatorCustomEventOption(StrategyCustomEventOption option)
        {
            switch (option)
            {
                case StrategyCustomEventOption.Pxe_PriceEmaCross:
                case StrategyCustomEventOption.Emx_EmaFastMidCross:
                case StrategyCustomEventOption.Emt_EmaMidSlowCross:
                case StrategyCustomEventOption.Vwx_PriceVwapCross:
                case StrategyCustomEventOption.Vwr_VwapRejection:
                case StrategyCustomEventOption.Bbx_BollingerMidCross:
                case StrategyCustomEventOption.Bbr_BollingerBandReject:
                case StrategyCustomEventOption.R50_RsiMidlineCross:
                case StrategyCustomEventOption.Ros_RsiExitOversold:
                case StrategyCustomEventOption.Rob_RsiExitOverbought:
                case StrategyCustomEventOption.Stx_StochCross:
                case StrategyCustomEventOption.Sto_StochExitExtreme:
                case StrategyCustomEventOption.Mdx_MacdSignalCross:
                case StrategyCustomEventOption.Md0_MacdZeroCross:
                case StrategyCustomEventOption.Div_Divergence:
                case StrategyCustomEventOption.__AnyTechnicalEvent:
                    return true;
                default:
                    return false;
            }
        }

        private bool TryApplyStrategyCustomEventGate(string symbolName, TimeFrame strategyTimeFrame, ref BacktestStrategySignal signal)
        {
            var selectedOptions = GetSelectedStrategyCustomEventOptions();
            var selectedRules = GetSelectedStrategyCustomRuleOptions();
            if (selectedOptions.Count == 0 && selectedRules.Count == 0)
                return signal.IsValid;

            TradeType resolvedTradeType;
            DateTime signalTime;
            string customLabel;
            string customNote;
            double customSlDistance;
            if (!TryResolveStrategyCustomEventBundle(symbolName, strategyTimeFrame, signal.TradeType, out resolvedTradeType, out signalTime, out customLabel, out customNote, out customSlDistance))
                return false;

            signal.SignalTime = signalTime;
            if (string.IsNullOrWhiteSpace(signal.SourceLabel))
                signal.SourceLabel = customLabel;
            else if (!string.IsNullOrWhiteSpace(customLabel))
                signal.SourceLabel = string.Format(CultureInfo.InvariantCulture, "{0}+{1}", signal.SourceLabel, customLabel);

            if (string.IsNullOrWhiteSpace(signal.Note))
                signal.Note = customNote;
            else if (!string.IsNullOrWhiteSpace(customNote))
                signal.Note = string.Format(CultureInfo.InvariantCulture, "{0} {1}", signal.Note, customNote);

            ApplyStrategyConfluenceSizing(symbolName, strategyTimeFrame, ref signal);
            return signal.IsValid;
        }

        private bool TryPassStrategyCustomEventGate(string symbolName, TimeFrame strategyTimeFrame, TradeType tradeType)
        {
            var selectedOptions = GetSelectedStrategyCustomEventOptions();
            var selectedRules = GetSelectedStrategyCustomRuleOptions();
            if (selectedOptions.Count == 0 && selectedRules.Count == 0)
                return true;

            TradeType resolvedTradeType;
            DateTime signalTime;
            string sourceLabel;
            string note;
            double gateSlDistance;
            return TryResolveStrategyCustomEventBundle(symbolName, strategyTimeFrame, tradeType, out resolvedTradeType, out signalTime, out sourceLabel, out note, out gateSlDistance);
        }

        // ---- Strategy custom RULES ----
        // A rule is a current, persisting condition (life = many candles), unlike an event which
        // is a candle-based trigger. Selected rules are always ANDed together and ANDed with the
        // event bundle: (Events AND/OR) AND (all Rules). Rules never decide the trade direction.
        private bool TryEvaluateStrategyCustomRuleOption(
            StrategyCustomRuleOption option,
            string symbolName,
            Bars sourceBars,
            TimeFrame strategyTimeFrame,
            int latestClosedIndex,
            SharedIndicatorSnapshot previousSnapshot,
            SharedIndicatorSnapshot currentSnapshot,
            bool? requireBullishDirection,
            out bool matches,
            out string shortLabel)
        {
            matches = false;
            shortLabel = "";
            if (option == StrategyCustomRuleOption.Off)
                return false;

            if (sourceBars == null || latestClosedIndex < 0 || latestClosedIndex >= sourceBars.Count)
                return false;

            var index = latestClosedIndex;
            switch (option)
            {
                case StrategyCustomRuleOption.__Bullish:
                    shortLabel = "BUY";
                    matches = requireBullishDirection.HasValue && requireBullishDirection.Value;
                    return true;
                case StrategyCustomRuleOption.__Bearish:
                    shortLabel = "SELL";
                    matches = requireBullishDirection.HasValue && !requireBullishDirection.Value;
                    return true;
                case StrategyCustomRuleOption.__Any_Bullish:
                    shortLabel = "any↑";
                    matches =
                        (IsFiniteNumber(currentSnapshot.EmaFast) && IsFiniteNumber(currentSnapshot.EmaSlow) && currentSnapshot.EmaFast > currentSnapshot.EmaSlow) ||
                        (IsFiniteNumber(currentSnapshot.EmaMid) && sourceBars.ClosePrices[index] > currentSnapshot.EmaMid) ||
                        (IsFiniteNumber(currentSnapshot.VwapMain) && sourceBars.ClosePrices[index] > currentSnapshot.VwapMain) ||
                        (IsFiniteNumber(currentSnapshot.BbMid) && sourceBars.ClosePrices[index] > currentSnapshot.BbMid) ||
                        (IsFiniteNumber(currentSnapshot.RsiMain) && currentSnapshot.RsiMain > 50.0) ||
                        GetStrategyLtfTrendBiasScore(symbolName, strategyTimeFrame) >= 2 ||
                        GetStrategyHtfTrendBiasScore(symbolName, strategyTimeFrame) >= 2;
                    return true;
                case StrategyCustomRuleOption.__Any_Bearish:
                    shortLabel = "any↓";
                    matches =
                        (IsFiniteNumber(currentSnapshot.EmaFast) && IsFiniteNumber(currentSnapshot.EmaSlow) && currentSnapshot.EmaFast < currentSnapshot.EmaSlow) ||
                        (IsFiniteNumber(currentSnapshot.EmaMid) && sourceBars.ClosePrices[index] < currentSnapshot.EmaMid) ||
                        (IsFiniteNumber(currentSnapshot.VwapMain) && sourceBars.ClosePrices[index] < currentSnapshot.VwapMain) ||
                        (IsFiniteNumber(currentSnapshot.BbMid) && sourceBars.ClosePrices[index] < currentSnapshot.BbMid) ||
                        (IsFiniteNumber(currentSnapshot.RsiMain) && currentSnapshot.RsiMain < 50.0) ||
                        GetStrategyLtfTrendBiasScore(symbolName, strategyTimeFrame) <= -2 ||
                        GetStrategyHtfTrendBiasScore(symbolName, strategyTimeFrame) <= -2;
                    return true;
                case StrategyCustomRuleOption.EMA_SmallAboveLong:
                    shortLabel = "ema" + Math.Max(1, _resolvedEmaEventConfig.FastPeriod) + ">ema" + Math.Max(1, _resolvedEmaEventConfig.SlowPeriod);
                    matches = IsFiniteNumber(currentSnapshot.EmaFast) && IsFiniteNumber(currentSnapshot.EmaSlow) && currentSnapshot.EmaFast > currentSnapshot.EmaSlow;
                    return true;
                case StrategyCustomRuleOption.EMA_SmallBelowLong:
                    shortLabel = "ema" + Math.Max(1, _resolvedEmaEventConfig.FastPeriod) + "<ema" + Math.Max(1, _resolvedEmaEventConfig.SlowPeriod);
                    matches = IsFiniteNumber(currentSnapshot.EmaFast) && IsFiniteNumber(currentSnapshot.EmaSlow) && currentSnapshot.EmaFast < currentSnapshot.EmaSlow;
                    return true;
                case StrategyCustomRuleOption.EMA_PriceAboveMid:
                    shortLabel = "p>ema" + Math.Max(1, _resolvedEmaEventConfig.MidPeriod);
                    matches = IsFiniteNumber(currentSnapshot.EmaMid) && sourceBars.ClosePrices[index] > currentSnapshot.EmaMid;
                    return true;
                case StrategyCustomRuleOption.EMA_PriceBelowMid:
                    shortLabel = "p<ema" + Math.Max(1, _resolvedEmaEventConfig.MidPeriod);
                    matches = IsFiniteNumber(currentSnapshot.EmaMid) && sourceBars.ClosePrices[index] < currentSnapshot.EmaMid;
                    return true;
                case StrategyCustomRuleOption.VWAP_PriceAbove:
                    shortLabel = "p>vwap";
                    matches = IsFiniteNumber(currentSnapshot.VwapMain) && sourceBars.ClosePrices[index] > currentSnapshot.VwapMain;
                    return true;
                case StrategyCustomRuleOption.VWAP_PriceBelow:
                    shortLabel = "p<vwap";
                    matches = IsFiniteNumber(currentSnapshot.VwapMain) && sourceBars.ClosePrices[index] < currentSnapshot.VwapMain;
                    return true;
                case StrategyCustomRuleOption.BB_PriceAboveMid:
                    shortLabel = "p>bbm";
                    matches = IsFiniteNumber(currentSnapshot.BbMid) && sourceBars.ClosePrices[index] > currentSnapshot.BbMid;
                    return true;
                case StrategyCustomRuleOption.BB_PriceBelowMid:
                    shortLabel = "p<bbm";
                    matches = IsFiniteNumber(currentSnapshot.BbMid) && sourceBars.ClosePrices[index] < currentSnapshot.BbMid;
                    return true;
                case StrategyCustomRuleOption.RSI_Above50:
                    shortLabel = "rsi" + Math.Max(1, _resolvedRsiEventConfig.Period) + ">50";
                    matches = IsFiniteNumber(currentSnapshot.RsiMain) && currentSnapshot.RsiMain > 50.0;
                    return true;
                case StrategyCustomRuleOption.RSI_Below50:
                    shortLabel = "rsi" + Math.Max(1, _resolvedRsiEventConfig.Period) + "<50";
                    matches = IsFiniteNumber(currentSnapshot.RsiMain) && currentSnapshot.RsiMain < 50.0;
                    return true;
                case StrategyCustomRuleOption.RSI_Oversold:
                    shortLabel = "rsi" + Math.Max(1, _resolvedRsiEventConfig.Period) + "<30";
                    matches = IsFiniteNumber(currentSnapshot.RsiMain) && currentSnapshot.RsiMain < 30.0;
                    return true;
                case StrategyCustomRuleOption.RSI_Overbought:
                    shortLabel = "rsi" + Math.Max(1, _resolvedRsiEventConfig.Period) + ">70";
                    matches = IsFiniteNumber(currentSnapshot.RsiMain) && currentSnapshot.RsiMain > 70.0;
                    return true;
                case StrategyCustomRuleOption.LTF_Bullish:
                    shortLabel = "ltf↑";
                    matches = GetStrategyLtfTrendBiasScore(symbolName, strategyTimeFrame) >= 2;
                    return true;
                case StrategyCustomRuleOption.LTF_Bearish:
                    shortLabel = "ltf↓";
                    matches = GetStrategyLtfTrendBiasScore(symbolName, strategyTimeFrame) <= -2;
                    return true;
                case StrategyCustomRuleOption.LTF_Sideways:
                    shortLabel = "ltf=";
                    var ltfStateScore = GetStrategyLtfTrendBiasScore(symbolName, strategyTimeFrame);
                    matches = ltfStateScore > -2 && ltfStateScore < 2;
                    return true;
                case StrategyCustomRuleOption.HTF_Bullish:
                    shortLabel = "htf↑";
                    matches = GetStrategyHtfTrendBiasScore(symbolName, strategyTimeFrame) >= 2;
                    return true;
                case StrategyCustomRuleOption.LTF_Confluence:
                    shortLabel = "ltf";
                    if (!requireBullishDirection.HasValue)
                    {
                        matches = false;
                        return true;
                    }
                    matches = requireBullishDirection.Value
                        ? GetStrategyLtfTrendBiasScore(symbolName, strategyTimeFrame) >= 2
                        : GetStrategyLtfTrendBiasScore(symbolName, strategyTimeFrame) <= -2;
                    return true;
                case StrategyCustomRuleOption.HTF_Confluence:
                    shortLabel = "htf";
                    if (!requireBullishDirection.HasValue)
                    {
                        matches = false;
                        return true;
                    }
                    matches = requireBullishDirection.Value
                        ? GetStrategyHtfTrendBiasScore(symbolName, strategyTimeFrame) >= 2
                        : GetStrategyHtfTrendBiasScore(symbolName, strategyTimeFrame) <= -2;
                    return true;
                case StrategyCustomRuleOption.H1_Confluence:
                    shortLabel = "h1";
                    matches = requireBullishDirection.HasValue && IsSpecificTimeFrameBiasAligned(symbolName, TimeFrame.Hour, requireBullishDirection.Value);
                    return true;
                case StrategyCustomRuleOption.H4_Confluence:
                    shortLabel = "h4";
                    matches = requireBullishDirection.HasValue && IsSpecificTimeFrameBiasAligned(symbolName, TimeFrame.Hour4, requireBullishDirection.Value);
                    return true;
                case StrategyCustomRuleOption.D1_Confluence:
                    shortLabel = "d1";
                    matches = requireBullishDirection.HasValue && IsSpecificTimeFrameBiasAligned(symbolName, TimeFrame.Daily, requireBullishDirection.Value);
                    return true;
                case StrategyCustomRuleOption.Bar_Confluence:
                    shortLabel = "bar";
                    if (!requireBullishDirection.HasValue)
                    {
                        matches = false;
                        return true;
                    }
                    bool signalBarIsBullish;
                    matches = TryGetSignalBarDirection(
                        sourceBars,
                        latestClosedIndex,
                        out signalBarIsBullish) &&
                        signalBarIsBullish == requireBullishDirection.Value;
                    return true;
                case StrategyCustomRuleOption.__AnyMomentum:
                    shortLabel = "mom";
                    if (!requireBullishDirection.HasValue)
                    {
                        matches = false;
                        return true;
                    }
                    bool momentumHasSignal;
                    string momentumState;
                    matches = TryEvaluateMomentumConfluence(
                        sourceBars,
                        latestClosedIndex,
                        currentSnapshot,
                        requireBullishDirection.Value,
                        out momentumHasSignal,
                        out momentumState);
                    return true;
                case StrategyCustomRuleOption.Ichimoku_Confluence:
                    shortLabel = "ichi";
                    if (!requireBullishDirection.HasValue)
                        return true;
                    bool ichimokuHasSignal;
                    string ichimokuState;
                    matches = TryEvaluateIchimokuConfluence(
                        sourceBars,
                        latestClosedIndex,
                        currentSnapshot,
                        requireBullishDirection.Value,
                        out ichimokuHasSignal,
                        out ichimokuState);
                    return true;
                case StrategyCustomRuleOption.Trend_Confluence:
                    shortLabel = "trend";
                    if (!requireBullishDirection.HasValue)
                    {
                        matches = false;
                        return true;
                    }
                    bool trendHasSignal;
                    string trendState;
                    matches = TryEvaluateTrendConfluence(
                        symbolName,
                        strategyTimeFrame,
                        requireBullishDirection.Value,
                        out trendHasSignal,
                        out trendState);
                    return true;
                case StrategyCustomRuleOption._LTF_HTF_Momentum:
                    shortLabel = "ltf.htf.mom";
                    if (!requireBullishDirection.HasValue)
                    {
                        matches = false;
                        return true;
                    }
                    bool ltfHtfMomentumHasSignal;
                    string ltfHtfMomentumState;
                    matches = TryEvaluateLtfHtfMomentumConfluence(
                        symbolName,
                        sourceBars,
                        strategyTimeFrame,
                        latestClosedIndex,
                        currentSnapshot,
                        requireBullishDirection.Value,
                        out ltfHtfMomentumHasSignal,
                        out ltfHtfMomentumState);
                    return true;
                case StrategyCustomRuleOption.__AnyPriceLocation:
                    shortLabel = "px";
                    if (!requireBullishDirection.HasValue)
                    {
                        matches = false;
                        return true;
                    }
                    bool priceHasSignal;
                    string priceState;
                    matches = TryEvaluatePriceLocationConfluence(
                        sourceBars,
                        latestClosedIndex,
                        currentSnapshot,
                        requireBullishDirection.Value,
                        out priceHasSignal,
                        out priceState);
                    return true;
                case StrategyCustomRuleOption.__AnyOscillator:
                    shortLabel = "osc";
                    if (!requireBullishDirection.HasValue)
                    {
                        matches = false;
                        return true;
                    }
                    bool oscillatorHasSignal;
                    string oscillatorState;
                    matches = TryEvaluateOscillatorConfluence(
                        currentSnapshot,
                        requireBullishDirection.Value,
                        out oscillatorHasSignal,
                        out oscillatorState);
                    return true;
                case StrategyCustomRuleOption.EMA_Confluence:
                    shortLabel = "ema" + Math.Max(1, _resolvedEmaEventConfig.FastPeriod) + "/ema" + Math.Max(1, _resolvedEmaEventConfig.SlowPeriod);
                    matches = requireBullishDirection.HasValue &&
                        IsFiniteNumber(currentSnapshot.EmaFast) &&
                        IsFiniteNumber(currentSnapshot.EmaSlow) &&
                        (requireBullishDirection.Value
                            ? currentSnapshot.EmaFast > currentSnapshot.EmaSlow
                            : currentSnapshot.EmaFast < currentSnapshot.EmaSlow);
                    return true;
                case StrategyCustomRuleOption.EMA_Price_Confluence:
                    shortLabel = "p/ema" + Math.Max(1, _resolvedEmaEventConfig.MidPeriod);
                    matches = requireBullishDirection.HasValue &&
                        IsFiniteNumber(currentSnapshot.EmaMid) &&
                        (requireBullishDirection.Value
                            ? sourceBars.ClosePrices[index] > currentSnapshot.EmaMid
                            : sourceBars.ClosePrices[index] < currentSnapshot.EmaMid);
                    return true;
                case StrategyCustomRuleOption.VWAP_Confluence:
                    shortLabel = "p/vwap";
                    matches = requireBullishDirection.HasValue &&
                        IsFiniteNumber(currentSnapshot.VwapMain) &&
                        (requireBullishDirection.Value
                            ? sourceBars.ClosePrices[index] > currentSnapshot.VwapMain
                            : sourceBars.ClosePrices[index] < currentSnapshot.VwapMain);
                    return true;
                case StrategyCustomRuleOption.Bollinger_Confluence:
                    shortLabel = "p/bbm";
                    matches = requireBullishDirection.HasValue &&
                        IsFiniteNumber(currentSnapshot.BbMid) &&
                        (requireBullishDirection.Value
                            ? sourceBars.ClosePrices[index] > currentSnapshot.BbMid
                            : sourceBars.ClosePrices[index] < currentSnapshot.BbMid);
                    return true;
                case StrategyCustomRuleOption.RSI_Confluence:
                    shortLabel = "rsi" + Math.Max(1, _resolvedRsiEventConfig.Period) + "/50";
                    matches = requireBullishDirection.HasValue &&
                        IsFiniteNumber(currentSnapshot.RsiMain) &&
                        (requireBullishDirection.Value
                            ? currentSnapshot.RsiMain > 50.0
                            : currentSnapshot.RsiMain < 50.0);
                    return true;
                case StrategyCustomRuleOption.RSI_Extreme_Confluence:
                    shortLabel = "rsi" + Math.Max(1, _resolvedRsiEventConfig.Period) + "/ext";
                    matches = requireBullishDirection.HasValue &&
                        IsFiniteNumber(currentSnapshot.RsiMain) &&
                        (requireBullishDirection.Value
                            ? currentSnapshot.RsiMain < 30.0
                            : currentSnapshot.RsiMain > 70.0);
                    return true;
                case StrategyCustomRuleOption.HTF_Bearish:
                    shortLabel = "htf↓";
                    matches = GetStrategyHtfTrendBiasScore(symbolName, strategyTimeFrame) <= -2;
                    return true;
                case StrategyCustomRuleOption.HTF_Sideways:
                    shortLabel = "htf=";
                    var htfStateScore = GetStrategyHtfTrendBiasScore(symbolName, strategyTimeFrame);
                    matches = htfStateScore > -2 && htfStateScore < 2;
                    return true;
                default:
                    return false;
            }
        }

        private bool TryPassSelectedStrategyCustomRules(string symbolName, Bars sourceBars, TimeFrame strategyTimeFrame, int latestClosedIndex, SharedIndicatorSnapshot previousSnapshot, SharedIndicatorSnapshot currentSnapshot, bool? requireBullishDirection = null)
        {
            foreach (var rule in GetSelectedStrategyCustomRuleOptions())
            {
                bool matches;
                string shortLabel;
                if (!TryEvaluateStrategyCustomRuleOption(rule, symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, previousSnapshot, currentSnapshot, requireBullishDirection, out matches, out shortLabel))
                    return false;
                if (!matches)
                    return false;
            }
            return true;
        }

        private bool IsStrategySoftConfluenceRule(StrategyCustomRuleOption option)
        {
            // "Soft" here only means the item also participates in confidence scoring.
            // Selected Confluence slots are still enforced by TryPassSelectedStrategyCustomRules.
            return option == StrategyCustomRuleOption.LTF_Confluence ||
                option == StrategyCustomRuleOption.HTF_Confluence ||
                option == StrategyCustomRuleOption.H1_Confluence ||
                option == StrategyCustomRuleOption.H4_Confluence ||
                option == StrategyCustomRuleOption.D1_Confluence ||
                option == StrategyCustomRuleOption.Bar_Confluence ||
                option == StrategyCustomRuleOption.__AnyMomentum ||
                option == StrategyCustomRuleOption.Ichimoku_Confluence ||
                option == StrategyCustomRuleOption.Trend_Confluence ||
                option == StrategyCustomRuleOption._LTF_HTF_Momentum ||
                option == StrategyCustomRuleOption.__AnyPriceLocation ||
                option == StrategyCustomRuleOption.__AnyOscillator ||
                option == StrategyCustomRuleOption.EMA_Confluence ||
                option == StrategyCustomRuleOption.EMA_Price_Confluence ||
                option == StrategyCustomRuleOption.VWAP_Confluence ||
                option == StrategyCustomRuleOption.Bollinger_Confluence ||
                option == StrategyCustomRuleOption.RSI_Confluence ||
                option == StrategyCustomRuleOption.RSI_Extreme_Confluence;
        }

        private string FormatStrategyConfluenceDirectionLabel(StrategyCustomRuleOption option, string label, bool bullish)
        {
            var compact = string.IsNullOrWhiteSpace(label) ? option.ToString() : label;
            return compact + (bullish ? "↑" : "↓");
        }

        private string FormatStrategyConfluenceAlignmentLabel(StrategyCustomRuleOption option, string label, bool aligned)
        {
            var compact = string.IsNullOrWhiteSpace(label) ? option.ToString() : label;
            return compact + (aligned ? "+" : "-");
        }

        private StrategyConfluenceScoreResult CalculateStrategyConfluenceScore(
            string symbolName,
            Bars sourceBars,
            TimeFrame strategyTimeFrame,
            int latestClosedIndex,
            SharedIndicatorSnapshot currentSnapshot,
            bool bullish)
        {
            var result = new StrategyConfluenceScoreResult
            {
                RewardRiskMultiplier = 1.0,
                VolumeMultiplier = 1.0,
                Detail = ""
            };
            var details = new List<string>();

            foreach (var rule in GetSelectedStrategyCustomRuleOptions().Where(IsStrategySoftConfluenceRule))
            {
                var componentScore = 0;
                var componentState = "neutral";
                switch (rule)
                {
                    case StrategyCustomRuleOption.LTF_Confluence:
                    {
                        var biasScore = GetStrategyLtfTrendBiasScore(symbolName, strategyTimeFrame);
                        componentScore = CTraderStrategyEngine.ResolveDirectionalConfluenceComponentScore(biasScore, bullish);
                        componentState = FormatStrategyBiasState(biasScore) + FormatSignedBias(biasScore);
                        break;
                    }
                    case StrategyCustomRuleOption.HTF_Confluence:
                    {
                        var biasScore = GetStrategyHtfTrendBiasScore(symbolName, strategyTimeFrame);
                        componentScore = CTraderStrategyEngine.ResolveDirectionalConfluenceComponentScore(biasScore, bullish);
                        componentState = FormatStrategyBiasState(biasScore) + FormatSignedBias(biasScore);
                        break;
                    }
                    case StrategyCustomRuleOption.H1_Confluence:
                    case StrategyCustomRuleOption.H4_Confluence:
                    case StrategyCustomRuleOption.D1_Confluence:
                    {
                        var biasScore = GetStrategySpecificTimeFrameBiasScore(symbolName, GetStrategyConfluenceTimeFrame(rule));
                        componentScore = CTraderStrategyEngine.ResolveDirectionalConfluenceComponentScore(biasScore, bullish);
                        componentState = FormatStrategyBiasState(biasScore) + FormatSignedBias(biasScore);
                        break;
                    }
                    case StrategyCustomRuleOption.Bar_Confluence:
                    {
                        bool signalBarIsBullish;
                        if (TryGetSignalBarDirection(sourceBars, latestClosedIndex, out signalBarIsBullish))
                        {
                            componentScore = signalBarIsBullish == bullish ? 1 : -1;
                            componentState = signalBarIsBullish ? "Bullish" : "Bearish";
                        }
                        else
                        {
                            componentState = "Doji/unavailable";
                        }
                        break;
                    }
                    case StrategyCustomRuleOption.__AnyMomentum:
                    {
                        bool hasSignal;
                        var aligned = TryEvaluateMomentumConfluence(sourceBars, latestClosedIndex, currentSnapshot, bullish, out hasSignal, out componentState);
                        componentScore = !hasSignal ? 0 : (aligned ? 1 : -1);
                        break;
                    }
                    case StrategyCustomRuleOption.Ichimoku_Confluence:
                    {
                        bool hasSignal;
                        var aligned = TryEvaluateIchimokuConfluence(sourceBars, latestClosedIndex, currentSnapshot, bullish, out hasSignal, out componentState);
                        componentScore = !hasSignal ? 0 : (aligned ? 1 : -1);
                        break;
                    }
                    case StrategyCustomRuleOption.Trend_Confluence:
                    {
                        bool hasSignal;
                        var aligned = TryEvaluateTrendConfluence(symbolName, strategyTimeFrame, bullish, out hasSignal, out componentState);
                        componentScore = !hasSignal ? 0 : (aligned ? 1 : -1);
                        break;
                    }
                    case StrategyCustomRuleOption._LTF_HTF_Momentum:
                    {
                        bool hasSignal;
                        var aligned = TryEvaluateLtfHtfMomentumConfluence(symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, currentSnapshot, bullish, out hasSignal, out componentState);
                        componentScore = !hasSignal ? 0 : (aligned ? 1 : -1);
                        break;
                    }
                    case StrategyCustomRuleOption.__AnyPriceLocation:
                    {
                        bool hasSignal;
                        var aligned = TryEvaluatePriceLocationConfluence(sourceBars, latestClosedIndex, currentSnapshot, bullish, out hasSignal, out componentState);
                        componentScore = !hasSignal ? 0 : (aligned ? 1 : -1);
                        break;
                    }
                    case StrategyCustomRuleOption.__AnyOscillator:
                    {
                        bool hasSignal;
                        var aligned = TryEvaluateOscillatorConfluence(currentSnapshot, bullish, out hasSignal, out componentState);
                        componentScore = !hasSignal ? 0 : (aligned ? 1 : -1);
                        break;
                    }
                    case StrategyCustomRuleOption.EMA_Confluence:
                    case StrategyCustomRuleOption.EMA_Price_Confluence:
                    case StrategyCustomRuleOption.VWAP_Confluence:
                    case StrategyCustomRuleOption.Bollinger_Confluence:
                    case StrategyCustomRuleOption.RSI_Confluence:
                    case StrategyCustomRuleOption.RSI_Extreme_Confluence:
                    {
                        bool aligned;
                        string label;
                        if (TryEvaluateStrategyCustomRuleOption(rule, symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, currentSnapshot, currentSnapshot, bullish, out aligned, out label))
                        {
                            componentScore = aligned ? 1 : -1;
                            componentState = DescribeStrategyCustomRuleRequirement(rule, symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, currentSnapshot, bullish);
                        }
                        else
                        {
                            componentScore = 0;
                            componentState = "unavailable";
                        }
                        break;
                    }
                }

                result.Score += componentScore;
                result.Count++;
                details.Add(string.Format(
                    CultureInfo.InvariantCulture,
                    "{0}:{1}({2})",
                    GetStrategyConfluenceRuleLabel(rule),
                    FormatSignedBias(componentScore),
                    componentState));
            }

            if (result.Count <= 0)
                return result;

            CTraderConfidenceEngine.ResolveMultipliers(
                result.Score,
                result.Count,
                ConfidenceRewardRiskLowMultiplier,
                ConfidenceRewardRiskHighMultiplier,
                ConfidenceVolumeLowMultiplier,
                ConfidenceVolumeHighMultiplier,
                out result.NormalizedScore,
                out result.RewardRiskMultiplier,
                out result.VolumeMultiplier);
            result.Detail = string.Join(",", details);
            return result;
        }

        private string GetStrategyConfluenceRuleLabel(StrategyCustomRuleOption option)
        {
            switch (option)
            {
                case StrategyCustomRuleOption.LTF_Confluence: return "LTF";
                case StrategyCustomRuleOption.HTF_Confluence: return "HTF";
                case StrategyCustomRuleOption.H1_Confluence: return "H1";
                case StrategyCustomRuleOption.H4_Confluence: return "H4";
                case StrategyCustomRuleOption.D1_Confluence: return "D1";
                case StrategyCustomRuleOption.Bar_Confluence: return "BAR";
                case StrategyCustomRuleOption.__AnyMomentum: return "MOM";
                case StrategyCustomRuleOption.Ichimoku_Confluence: return "ICHI";
                case StrategyCustomRuleOption.Trend_Confluence: return "TREND";
                case StrategyCustomRuleOption._LTF_HTF_Momentum: return "LHM";
                case StrategyCustomRuleOption.__AnyPriceLocation: return "PX";
                case StrategyCustomRuleOption.__AnyOscillator: return "OSC";
                case StrategyCustomRuleOption.EMA_Confluence: return "EMA";
                case StrategyCustomRuleOption.EMA_Price_Confluence: return "EMA_P";
                case StrategyCustomRuleOption.VWAP_Confluence: return "VWAP";
                case StrategyCustomRuleOption.Bollinger_Confluence: return "BB";
                case StrategyCustomRuleOption.RSI_Confluence: return "RSI";
                case StrategyCustomRuleOption.RSI_Extreme_Confluence: return "RSI_X";
                default: return option.ToString();
            }
        }

        private void ApplyStrategyConfluenceSizing(
            string symbolName,
            TimeFrame strategyTimeFrame,
            ref BacktestStrategySignal signal)
        {
            Bars sourceBars;
            try
            {
                sourceBars = MarketData.GetBars(strategyTimeFrame, symbolName);
            }
            catch
            {
                sourceBars = null;
            }
            if (sourceBars == null || sourceBars.Count < 3)
                return;

            var latestClosedIndex = sourceBars.Count - 2;
            var currentSnapshot = BuildSharedIndicatorSnapshot(sourceBars, latestClosedIndex);
            var score = CalculateStrategyConfluenceScore(
                symbolName,
                sourceBars,
                strategyTimeFrame,
                latestClosedIndex,
                currentSnapshot,
                signal.TradeType == TradeType.Buy);
            if (score.Count <= 0)
                return;

            signal.ConfluenceScore = score.Score;
            signal.ConfluenceCount = score.Count;
            signal.ConfluenceRewardRiskMultiplier = score.RewardRiskMultiplier;
            signal.ConfluenceVolumeMultiplier = score.VolumeMultiplier;
            signal.ConfluenceDetail = score.Detail;
            var confidenceNote = string.Format(
                CultureInfo.InvariantCulture,
                "[confidence={0}/{1};{2};rr={3:0.##};rrx={4:0.##};volx={5:0.##}]",
                FormatSignedBias(score.Score),
                score.Count,
                score.Detail,
                Math.Max(0.1, StrategyRewardRisk) * score.RewardRiskMultiplier,
                score.RewardRiskMultiplier,
                score.VolumeMultiplier);
            signal.Note = string.IsNullOrWhiteSpace(signal.Note)
                ? confidenceNote
                : signal.Note + " " + confidenceNote;
        }

        private string BuildSelectedRulesLabel(string symbolName, Bars sourceBars, TimeFrame strategyTimeFrame, int latestClosedIndex, SharedIndicatorSnapshot previousSnapshot, SharedIndicatorSnapshot currentSnapshot, bool? requireBullishDirection = null)
        {
            var labels = new List<string>();
            foreach (var rule in GetSelectedStrategyCustomRuleOptions())
            {
                bool matches;
                string shortLabel;
                if (TryEvaluateStrategyCustomRuleOption(rule, symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, previousSnapshot, currentSnapshot, requireBullishDirection, out matches, out shortLabel) && matches && !string.IsNullOrWhiteSpace(shortLabel))
                    labels.Add(shortLabel);
            }
            return labels.Count > 0 ? string.Join("+", labels) : "";
        }

        private bool TryGetCustomTradeRuleRejectReason(string symbolName, TimeFrame strategyTimeFrame, out string rejectReason)
        {
            rejectReason = "";
            var selectedOptions = GetSelectedStrategyCustomEventOptions();
            var ruleSlots = new[]
            {
                Tuple.Create(1, StrategyCustomRule1),
                Tuple.Create(2, StrategyCustomRule2),
                Tuple.Create(3, StrategyCustomRule3),
                Tuple.Create(4, StrategyCustomRule4),
                Tuple.Create(5, StrategyCustomRule5)
            }
            .Where(item => item.Item2 != StrategyCustomRuleOption.Off)
            .GroupBy(item => item.Item2)
            .Select(group => group.First())
            .ToList();

            if (selectedOptions.Count == 0 || ruleSlots.Count == 0 || !string.IsNullOrWhiteSpace(SharedStrategyConfigIds))
                return false;

            Bars sourceBars;
            try
            {
                sourceBars = MarketData.GetBars(strategyTimeFrame, symbolName);
            }
            catch
            {
                return false;
            }

            if (sourceBars == null || sourceBars.Count < 3)
                return false;

            var latestClosedIndex = sourceBars.Count - 2;
            if (latestClosedIndex < 1 || latestClosedIndex >= sourceBars.Count)
                return false;

            var recentCanonicalEvents = GetCanonicalEventsForSymbolTimeFrame(symbolName, strategyTimeFrame, 48)
                .OrderByDescending(evt => evt.BarTime)
                .ThenByDescending(evt => evt.Score)
                .ToList();
            DateTime signalTime;
            List<CanonicalMarketEvent> eventsOnBar;
            if (!TryGetCanonicalEventsOnLatestClosedBar(symbolName, strategyTimeFrame, out signalTime, out eventsOnBar))
                return false;

            var previousSnapshot = BuildSharedIndicatorSnapshot(sourceBars, latestClosedIndex - 1);
            var currentSnapshot = BuildSharedIndicatorSnapshot(sourceBars, latestClosedIndex);
            var sharedPatterns = GetDetectedSharedRulePatternSet(sourceBars, strategyTimeFrame, latestClosedIndex);
            var optionStates = new List<Tuple<StrategyCustomEventOption, string, bool, bool, bool>>();
            foreach (var option in selectedOptions)
            {
                bool matchesBullish;
                bool matchesBearish;
                bool matchesDirectionless;
                string shortLabel;
                if (TryEvaluateStrategyCustomEventOption(
                    option,
                    symbolName,
                    sourceBars,
                    strategyTimeFrame,
                    latestClosedIndex,
                    previousSnapshot,
                    currentSnapshot,
                    sharedPatterns,
                    recentCanonicalEvents,
                    eventsOnBar,
                    out matchesBullish,
                    out matchesBearish,
                    out matchesDirectionless,
                    out shortLabel))
                {
                    optionStates.Add(Tuple.Create(option, shortLabel, matchesBullish, matchesBearish, matchesDirectionless));
                }
            }

            if (optionStates.Count == 0)
                return false;

            Func<bool, Tuple<bool, string>> evaluateEvents = bullish =>
            {
                var matched = optionStates
                    .Where(state => (bullish ? state.Item3 : state.Item4) || state.Item5)
                    .ToList();
                var passed = SelectedStrategyCustomEventsMode == StrategyCustomEventsMode.AND
                    ? matched.Count == optionStates.Count
                    : matched.Count > 0;
                var labels = string.Join("+", matched
                    .Select(state => state.Item2)
                    .Where(label => !string.IsNullOrWhiteSpace(label))
                    .Distinct());
                return Tuple.Create(passed, labels);
            };

            var failures = new List<string>();
            foreach (var bullish in new[] { true, false })
            {
                var eventResult = evaluateEvents(bullish);
                if (!eventResult.Item1)
                    continue;

                foreach (var ruleSlot in ruleSlots)
                {
                    bool matches;
                    string shortLabel;
                    if (TryEvaluateStrategyCustomRuleOption(
                        ruleSlot.Item2,
                        symbolName,
                        sourceBars,
                        strategyTimeFrame,
                        latestClosedIndex,
                        previousSnapshot,
                        currentSnapshot,
                        bullish,
                        out matches,
                        out shortLabel) && matches)
                        continue;

                    failures.Add(string.Format(
                        CultureInfo.InvariantCulture,
                        "event={0}; eventSide={3}; eventBar={4:yyyy-MM-dd HH:mm} UTC; Rule{1} {2} failed; {5}; check={6}",
                        string.IsNullOrWhiteSpace(eventResult.Item2) ? "selected_event" : eventResult.Item2,
                        ruleSlot.Item1,
                        ruleSlot.Item2,
                        bullish ? "BUY" : "SELL",
                        signalTime.ToUniversalTime(),
                        BuildStrategyBiasDiagnostic(symbolName, strategyTimeFrame),
                        DescribeStrategyCustomRuleRequirement(ruleSlot.Item2, symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, currentSnapshot, bullish)));
                }
            }

            if (failures.Count == 0)
                return false;

            rejectReason = string.Join("; ", failures);
            return true;
        }

        private string BuildStrategyBiasDiagnostic(string symbolName, TimeFrame strategyTimeFrame)
        {
            var currentFrames = GetBacktestStrategyCurrentTimeFrame(strategyTimeFrame).ToList();
            var higherFrames = GetBacktestStrategyHigherTimeFrames(strategyTimeFrame).ToList();
            var ltfScore = AggregateStrategyTrendBiasScore(symbolName, currentFrames);
            var htfScore = AggregateStrategyTrendBiasScore(symbolName, higherFrames);
            return string.Format(
                CultureInfo.InvariantCulture,
                "checkTF={0}; LTF/currentTF={1}({2}); LTF detail=[{3}]; HTF={4}({5}); HTF detail=[{6}]",
                strategyTimeFrame != null ? GetMiniChartLabel(strategyTimeFrame) : "n/a",
                FormatStrategyBiasState(ltfScore),
                FormatSignedBias(ltfScore),
                FormatStrategyBiasFrameDetails(symbolName, currentFrames),
                FormatStrategyBiasState(htfScore),
                FormatSignedBias(htfScore),
                FormatStrategyBiasFrameDetails(symbolName, higherFrames));
        }

        private string FormatStrategyBiasFrameDetails(string symbolName, IEnumerable<TimeFrame> frames)
        {
            var details = new List<string>();
            if (frames != null)
            {
                foreach (var timeFrame in frames)
                {
                    if (timeFrame == null)
                        continue;
                    var score = GetSymbolTrendBiasForTimeFrame(symbolName, timeFrame);
                    details.Add(string.Format(
                        CultureInfo.InvariantCulture,
                        "{0}:{1}({2})",
                        GetMiniChartLabel(timeFrame),
                        FormatStrategyBiasState(score),
                        FormatSignedBias(score)));
                }
            }
            return details.Count > 0 ? string.Join(",", details) : "none";
        }

        private string FormatStrategyBiasState(int score)
        {
            if (score >= 2)
                return "Bullish";
            if (score <= -2)
                return "Bearish";
            return "Sideways";
        }

        private string DescribeStrategyCustomRuleRequirement(
            StrategyCustomRuleOption option,
            string symbolName,
            Bars sourceBars,
            TimeFrame strategyTimeFrame,
            int latestClosedIndex,
            SharedIndicatorSnapshot currentSnapshot,
            bool bullish)
        {
            var side = bullish ? "BUY" : "SELL";
            var close = sourceBars != null && latestClosedIndex >= 0 && latestClosedIndex < sourceBars.Count
                ? sourceBars.ClosePrices[latestClosedIndex]
                : double.NaN;
            switch (option)
            {
                case StrategyCustomRuleOption.HTF_Confluence:
                    return string.Format(CultureInfo.InvariantCulture, "HTF score={0}, required {1}", GetStrategyHtfTrendBiasScore(symbolName, strategyTimeFrame), bullish ? ">=2" : "<=-2");
                case StrategyCustomRuleOption.LTF_Confluence:
                    return string.Format(CultureInfo.InvariantCulture, "LTF score={0}, required {1}", GetStrategyLtfTrendBiasScore(symbolName, strategyTimeFrame), bullish ? ">=2" : "<=-2");
                case StrategyCustomRuleOption.H1_Confluence:
                case StrategyCustomRuleOption.H4_Confluence:
                case StrategyCustomRuleOption.D1_Confluence:
                    var exactTimeFrame = GetStrategyConfluenceTimeFrame(option);
                    return string.Format(
                        CultureInfo.InvariantCulture,
                        "{0} score={1}, required {2}",
                        GetMiniChartLabel(exactTimeFrame).ToUpperInvariant(),
                        GetStrategySpecificTimeFrameBiasScore(symbolName, exactTimeFrame),
                        bullish ? ">=2" : "<=-2");
                case StrategyCustomRuleOption.Bar_Confluence:
                    return DescribeSignalBarDirectionRequirement(sourceBars, latestClosedIndex, bullish);
                case StrategyCustomRuleOption.__AnyMomentum:
                    return DescribeMomentumConfluenceRequirement(sourceBars, latestClosedIndex, currentSnapshot, bullish);
                case StrategyCustomRuleOption.Trend_Confluence:
                    return DescribeTrendConfluenceRequirement(symbolName, strategyTimeFrame, bullish);
                case StrategyCustomRuleOption._LTF_HTF_Momentum:
                    return DescribeLtfHtfMomentumConfluenceRequirement(symbolName, sourceBars, strategyTimeFrame, latestClosedIndex, currentSnapshot, bullish);
                case StrategyCustomRuleOption.__AnyPriceLocation:
                    return DescribePriceLocationConfluenceRequirement(sourceBars, latestClosedIndex, currentSnapshot, bullish);
                case StrategyCustomRuleOption.__AnyOscillator:
                    return DescribeOscillatorConfluenceRequirement(currentSnapshot, bullish);
                case StrategyCustomRuleOption.EMA_Confluence:
                    return string.Format(CultureInfo.InvariantCulture, "EMA fast={0}, slow={1}, required fast {2} slow for {3}", FormatStrategyDiagnosticNumber(currentSnapshot.EmaFast), FormatStrategyDiagnosticNumber(currentSnapshot.EmaSlow), bullish ? ">" : "<", side);
                case StrategyCustomRuleOption.EMA_Price_Confluence:
                    return string.Format(CultureInfo.InvariantCulture, "close={0}, EMA mid={1}, required close {2} mid for {3}", FormatStrategyDiagnosticNumber(close), FormatStrategyDiagnosticNumber(currentSnapshot.EmaMid), bullish ? ">" : "<", side);
                case StrategyCustomRuleOption.VWAP_Confluence:
                    return string.Format(CultureInfo.InvariantCulture, "close={0}, VWAP={1}, required close {2} VWAP for {3}", FormatStrategyDiagnosticNumber(close), FormatStrategyDiagnosticNumber(currentSnapshot.VwapMain), bullish ? ">" : "<", side);
                case StrategyCustomRuleOption.Bollinger_Confluence:
                    return string.Format(CultureInfo.InvariantCulture, "close={0}, BB mid={1}, required close {2} BB mid for {3}", FormatStrategyDiagnosticNumber(close), FormatStrategyDiagnosticNumber(currentSnapshot.BbMid), bullish ? ">" : "<", side);
                case StrategyCustomRuleOption.RSI_Confluence:
                    return string.Format(CultureInfo.InvariantCulture, "RSI={0}, required {1}50 for {2}", FormatStrategyDiagnosticNumber(currentSnapshot.RsiMain), bullish ? ">" : "<", side);
                case StrategyCustomRuleOption.RSI_Extreme_Confluence:
                    return string.Format(CultureInfo.InvariantCulture, "RSI={0}, required {1} for {2}", FormatStrategyDiagnosticNumber(currentSnapshot.RsiMain), bullish ? "<30" : ">70", side);
                case StrategyCustomRuleOption.__Bullish:
                    return string.Format(CultureInfo.InvariantCulture, "direction lock BUY-only; current side={0}", side);
                case StrategyCustomRuleOption.__Bearish:
                    return string.Format(CultureInfo.InvariantCulture, "direction lock SELL-only; current side={0}", side);
                case StrategyCustomRuleOption.HTF_Bullish:
                    return string.Format(CultureInfo.InvariantCulture, "HTF score={0}, required >=2", GetStrategyHtfTrendBiasScore(symbolName, strategyTimeFrame));
                case StrategyCustomRuleOption.HTF_Bearish:
                    return string.Format(CultureInfo.InvariantCulture, "HTF score={0}, required <=-2", GetStrategyHtfTrendBiasScore(symbolName, strategyTimeFrame));
                case StrategyCustomRuleOption.HTF_Sideways:
                    return string.Format(CultureInfo.InvariantCulture, "HTF score={0}, required -2<score<2", GetStrategyHtfTrendBiasScore(symbolName, strategyTimeFrame));
                case StrategyCustomRuleOption.LTF_Bullish:
                    return string.Format(CultureInfo.InvariantCulture, "LTF score={0}, required >=2", GetStrategyLtfTrendBiasScore(symbolName, strategyTimeFrame));
                case StrategyCustomRuleOption.LTF_Bearish:
                    return string.Format(CultureInfo.InvariantCulture, "LTF score={0}, required <=-2", GetStrategyLtfTrendBiasScore(symbolName, strategyTimeFrame));
                case StrategyCustomRuleOption.LTF_Sideways:
                    return string.Format(CultureInfo.InvariantCulture, "LTF score={0}, required -2<score<2", GetStrategyLtfTrendBiasScore(symbolName, strategyTimeFrame));
                case StrategyCustomRuleOption.EMA_SmallAboveLong:
                case StrategyCustomRuleOption.EMA_SmallBelowLong:
                    return string.Format(CultureInfo.InvariantCulture, "EMA fast={0}, slow={1}, required fast {2} slow", FormatStrategyDiagnosticNumber(currentSnapshot.EmaFast), FormatStrategyDiagnosticNumber(currentSnapshot.EmaSlow), option == StrategyCustomRuleOption.EMA_SmallAboveLong ? ">" : "<");
                case StrategyCustomRuleOption.EMA_PriceAboveMid:
                case StrategyCustomRuleOption.EMA_PriceBelowMid:
                    return string.Format(CultureInfo.InvariantCulture, "close={0}, EMA mid={1}, required close {2} mid", FormatStrategyDiagnosticNumber(close), FormatStrategyDiagnosticNumber(currentSnapshot.EmaMid), option == StrategyCustomRuleOption.EMA_PriceAboveMid ? ">" : "<");
                case StrategyCustomRuleOption.VWAP_PriceAbove:
                case StrategyCustomRuleOption.VWAP_PriceBelow:
                    return string.Format(CultureInfo.InvariantCulture, "close={0}, VWAP={1}, required close {2} VWAP", FormatStrategyDiagnosticNumber(close), FormatStrategyDiagnosticNumber(currentSnapshot.VwapMain), option == StrategyCustomRuleOption.VWAP_PriceAbove ? ">" : "<");
                case StrategyCustomRuleOption.BB_PriceAboveMid:
                case StrategyCustomRuleOption.BB_PriceBelowMid:
                    return string.Format(CultureInfo.InvariantCulture, "close={0}, BB mid={1}, required close {2} BB mid", FormatStrategyDiagnosticNumber(close), FormatStrategyDiagnosticNumber(currentSnapshot.BbMid), option == StrategyCustomRuleOption.BB_PriceAboveMid ? ">" : "<");
                case StrategyCustomRuleOption.RSI_Above50:
                case StrategyCustomRuleOption.RSI_Below50:
                    return string.Format(CultureInfo.InvariantCulture, "RSI={0}, required {1}50", FormatStrategyDiagnosticNumber(currentSnapshot.RsiMain), option == StrategyCustomRuleOption.RSI_Above50 ? ">" : "<");
                case StrategyCustomRuleOption.RSI_Oversold:
                    return string.Format(CultureInfo.InvariantCulture, "RSI={0}, required <30", FormatStrategyDiagnosticNumber(currentSnapshot.RsiMain));
                case StrategyCustomRuleOption.RSI_Overbought:
                    return string.Format(CultureInfo.InvariantCulture, "RSI={0}, required >70", FormatStrategyDiagnosticNumber(currentSnapshot.RsiMain));
                case StrategyCustomRuleOption.__Any_Bullish:
                case StrategyCustomRuleOption.__Any_Bearish:
                    return string.Format(CultureInfo.InvariantCulture, "no grouped {0} state matched for {1}", option == StrategyCustomRuleOption.__Any_Bullish ? "bullish" : "bearish", side);
                default:
                    return "rule evaluated false";
            }
        }

        private string FormatStrategyDiagnosticNumber(double value)
        {
            return IsFiniteNumber(value) ? value.ToString("0.#####", CultureInfo.InvariantCulture) : "n/a";
        }

        private bool TryGetLargestBodyCandleDirection(
            Bars sourceBars,
            int latestClosedIndex,
            int candlesCount,
            out int largestBarIndex,
            out bool isBullish)
        {
            largestBarIndex = -1;
            isBullish = false;
            if (sourceBars == null || latestClosedIndex < 0 || latestClosedIndex >= sourceBars.Count)
                return false;

            var startIndex = Math.Max(0, latestClosedIndex - Math.Max(1, candlesCount) + 1);
            var largestBody = -1.0;
            for (var index = startIndex; index <= latestClosedIndex; index++)
            {
                var body = Math.Abs(sourceBars.ClosePrices[index] - sourceBars.OpenPrices[index]);
                if (body < largestBody)
                    continue;
                largestBody = body;
                largestBarIndex = index;
            }

            if (largestBarIndex < 0)
                return false;

            var open = sourceBars.OpenPrices[largestBarIndex];
            var close = sourceBars.ClosePrices[largestBarIndex];
            if (close == open)
                return false;

            isBullish = close > open;
            return true;
        }

        private string DescribeLargestBodyCandleRequirement(Bars sourceBars, int latestClosedIndex, bool bullish)
        {
            var candlesCount = Math.Max(1, FollowTrendCandlesCount);
            int largestBarIndex;
            bool isBullish;
            if (!TryGetLargestBodyCandleDirection(sourceBars, latestClosedIndex, candlesCount, out largestBarIndex, out isBullish))
            {
                return string.Format(
                    CultureInfo.InvariantCulture,
                    "largest body in last {0} closed candle(s) is missing/doji; required {1}",
                    candlesCount,
                    bullish ? "Bullish/green for BUY" : "Bearish/red for SELL");
            }

            var open = sourceBars.OpenPrices[largestBarIndex];
            var close = sourceBars.ClosePrices[largestBarIndex];
            var body = Math.Abs(close - open);
            var range = Math.Abs(sourceBars.HighPrices[largestBarIndex] - sourceBars.LowPrices[largestBarIndex]);
            return string.Format(
                CultureInfo.InvariantCulture,
                "largest body in last {0} closed candle(s): bar={1:yyyy-MM-dd HH:mm} UTC, direction={2}, open={3}, close={4}, body={5}, range={6}; required {7}",
                candlesCount,
                sourceBars.OpenTimes[largestBarIndex].ToUniversalTime(),
                isBullish ? "Bullish/green" : "Bearish/red",
                FormatStrategyDiagnosticNumber(open),
                FormatStrategyDiagnosticNumber(close),
                FormatStrategyDiagnosticNumber(body),
                FormatStrategyDiagnosticNumber(range),
                bullish ? "Bullish/green for BUY" : "Bearish/red for SELL");
        }

