        private bool TryEvaluateVwapTechnicalConfluence(
            Bars sourceBars,
            int latestClosedIndex,
            double vwap,
            bool bullish,
            out string zone,
            out double signedDistanceAtr)
        {
            zone = "unavailable";
            signedDistanceAtr = double.NaN;
            if (sourceBars == null || latestClosedIndex < 1 || latestClosedIndex >= sourceBars.Count || !IsFiniteNumber(vwap))
                return false;

            var atr = ComputeAverageTrueRangeAtIndex(sourceBars, latestClosedIndex, 14);
            if (!IsFiniteNumber(atr) || atr <= 0)
                return false;

            var close = sourceBars.ClosePrices[latestClosedIndex];
            signedDistanceAtr = (close - vwap) / atr;
            const double nearAtr = 0.5;
            const double veryFarAtr = 1.5;

            if (signedDistanceAtr > 0 && signedDistanceAtr <= nearAtr)
                zone = "above_near";
            else if (signedDistanceAtr >= veryFarAtr)
                zone = "above_very_far";
            else if (signedDistanceAtr > 0)
                zone = "above_middle";
            else if (signedDistanceAtr < 0 && signedDistanceAtr >= -nearAtr)
                zone = "below_near";
            else if (signedDistanceAtr <= -veryFarAtr)
                zone = "below_very_far";
            else if (signedDistanceAtr < 0)
                zone = "below_middle";
            else
                zone = "at_vwap";

            return bullish
                ? zone == "above_near" || zone == "below_very_far"
                : zone == "below_near" || zone == "above_very_far";
        }

        private bool TryEvaluateMomentumConfluence(
            Bars sourceBars,
            int latestClosedIndex,
            SharedIndicatorSnapshot currentSnapshot,
            bool bullish,
            out bool hasSignal,
            out string state)
        {
            hasSignal = false;
            state = "unavailable";
            if (sourceBars == null || latestClosedIndex < 0 || latestClosedIndex >= sourceBars.Count)
                return false;

            var close = sourceBars.ClosePrices[latestClosedIndex];
            var emaAvailable = IsFiniteNumber(currentSnapshot.EmaFast) && IsFiniteNumber(currentSnapshot.EmaSlow);
            var vwapAvailable = IsFiniteNumber(currentSnapshot.VwapMain) && IsFiniteNumber(close);
            var emaAligned = emaAvailable && (bullish
                ? currentSnapshot.EmaFast > currentSnapshot.EmaSlow
                : currentSnapshot.EmaFast < currentSnapshot.EmaSlow);
            var vwapAligned = vwapAvailable && (bullish
                ? close > currentSnapshot.VwapMain
                : close < currentSnapshot.VwapMain);

            hasSignal = emaAvailable || vwapAvailable;
            if (!hasSignal)
                return false;

            state = string.Format(
                CultureInfo.InvariantCulture,
                "ema{0}/vwap{1}",
                emaAvailable ? (emaAligned ? "+" : "-") : "?",
                vwapAvailable ? (vwapAligned ? "+" : "-") : "?");
            return emaAligned || vwapAligned;
        }

        private bool TryEvaluateTrendConfluence(
            string symbolName,
            TimeFrame strategyTimeFrame,
            bool bullish,
            out bool hasSignal,
            out string state)
        {
            var ltfScore = GetStrategyLtfTrendBiasScore(symbolName, strategyTimeFrame);
            var htfScore = GetStrategyHtfTrendBiasScore(symbolName, strategyTimeFrame);
            var ltfAligned = bullish ? ltfScore >= 2 : ltfScore <= -2;
            var htfAligned = bullish ? htfScore >= 2 : htfScore <= -2;
            hasSignal = Math.Abs(ltfScore) >= 2 || Math.Abs(htfScore) >= 2;
            state = string.Format(CultureInfo.InvariantCulture, "ltf{0}{1}/htf{2}{3}", ltfAligned ? "+" : "-", FormatSignedBias(ltfScore), htfAligned ? "+" : "-", FormatSignedBias(htfScore));
            return ltfAligned && htfAligned;
        }

        // Cloud position determines the primary regime.  A large distance from the cloud is
        // deliberately reported as "extended" but never reverses that regime: a counter-trend
        // trade still needs an independent reversal trigger (CHOCH/reclaim etc.).
        private bool TryEvaluateIchimokuConfluence(
            Bars sourceBars,
            int latestClosedIndex,
            SharedIndicatorSnapshot snapshot,
            bool bullish,
            out bool hasSignal,
            out string state)
        {
            hasSignal = false;
            state = "unavailable";
            if (sourceBars == null || latestClosedIndex < 0 || latestClosedIndex >= sourceBars.Count)
                return false;
            // Senkou spans are plotted 26 periods ahead.  Compare today's price to the cloud
            // that is visibly plotted today (calculated 26 completed bars ago), never to the
            // newly calculated cloud projected into the future.
            var cloudIndex = latestClosedIndex - 26;
            var config = _resolvedIchimokuOverlayConfig.ConversionPeriod > 0
                ? _resolvedIchimokuOverlayConfig
                : ResolveIchimokuIndicatorConfig(IchimokuVisualMode.Auto);
            var spanA = cloudIndex >= 0 ? ComputeIchimokuSpanA(sourceBars, cloudIndex, config) : double.NaN;
            var spanB = cloudIndex >= 0 ? ComputeIchimokuSpanB(sourceBars, cloudIndex, config) : double.NaN;
            if (!IsFiniteNumber(spanA) || !IsFiniteNumber(spanB) ||
                !IsFiniteNumber(snapshot.IchimokuConversion) || !IsFiniteNumber(snapshot.IchimokuBase))
                return false;

            var close = sourceBars.ClosePrices[latestClosedIndex];
            var top = Math.Max(spanA, spanB);
            var bottom = Math.Min(spanA, spanB);
            var cloudBullish = spanA > spanB;
            var above = close > top;
            var below = close < bottom;
            var inside = !above && !below;
            var atr = ComputeAverageTrueRangeAtIndex(sourceBars, latestClosedIndex, 14);
            var distanceAtr = IsFiniteNumber(atr) && atr > 0
                ? (above ? (close - top) : below ? (bottom - close) : 0) / atr
                : 0;
            var widthAtr = IsFiniteNumber(atr) && atr > 0 ? (top - bottom) / atr : 0;
            var extended = distanceAtr >= 1.5;
            var conversionAligned = bullish ? snapshot.IchimokuConversion >= snapshot.IchimokuBase : snapshot.IchimokuConversion <= snapshot.IchimokuBase;
            var cloudAligned = bullish ? cloudBullish : !cloudBullish;
            hasSignal = true;
            state = string.Format(CultureInfo.InvariantCulture,
                "{0};cloud{1};tk{2};dist={3:0.##}ATR;width={4:0.##}ATR{5}",
                inside ? "inside" : (above ? "above" : "below"),
                cloudAligned ? "+" : "-",
                conversionAligned ? "+" : "-",
                distanceAtr,
                widthAtr,
                extended ? ";extended" : "");
            return bullish ? above && cloudAligned && conversionAligned : below && cloudAligned && conversionAligned;
        }

        private bool TryEvaluateLtfHtfMomentumConfluence(
            string symbolName,
            Bars sourceBars,
            TimeFrame strategyTimeFrame,
            int latestClosedIndex,
            SharedIndicatorSnapshot currentSnapshot,
            bool bullish,
            out bool hasSignal,
            out string state)
        {
            bool trendHasSignal;
            string trendState;
            var trendAligned = TryEvaluateTrendConfluence(symbolName, strategyTimeFrame, bullish, out trendHasSignal, out trendState);
            bool momentumHasSignal;
            string momentumState;
            var momentumAligned = TryEvaluateMomentumConfluence(sourceBars, latestClosedIndex, currentSnapshot, bullish, out momentumHasSignal, out momentumState);
            hasSignal = trendHasSignal || momentumHasSignal;
            state = string.Format(CultureInfo.InvariantCulture, "{0}/{1}", trendState, momentumState);
            return trendAligned && momentumAligned;
        }

        private bool TryEvaluatePriceLocationConfluence(
            Bars sourceBars,
            int latestClosedIndex,
            SharedIndicatorSnapshot currentSnapshot,
            bool bullish,
            out bool hasSignal,
            out string state)
        {
            hasSignal = false;
            state = "unavailable";
            if (sourceBars == null || latestClosedIndex < 0 || latestClosedIndex >= sourceBars.Count)
                return false;

            var close = sourceBars.ClosePrices[latestClosedIndex];
            var emaAvailable = IsFiniteNumber(currentSnapshot.EmaMid);
            var vwapAvailable = IsFiniteNumber(currentSnapshot.VwapMain);
            var bbAvailable = IsFiniteNumber(currentSnapshot.BbMid);
            var emaAligned = emaAvailable && (bullish ? close > currentSnapshot.EmaMid : close < currentSnapshot.EmaMid);
            var vwapAligned = vwapAvailable && (bullish ? close > currentSnapshot.VwapMain : close < currentSnapshot.VwapMain);
            var bbAligned = bbAvailable && (bullish ? close > currentSnapshot.BbMid : close < currentSnapshot.BbMid);

            hasSignal = emaAvailable || vwapAvailable || bbAvailable;
            if (!hasSignal)
                return false;

            state = string.Format(
                CultureInfo.InvariantCulture,
                "ema{0}/vwap{1}/bb{2}",
                emaAvailable ? (emaAligned ? "+" : "-") : "?",
                vwapAvailable ? (vwapAligned ? "+" : "-") : "?",
                bbAvailable ? (bbAligned ? "+" : "-") : "?");
