        private bool TryParseStrategyCustomRuleOptionName(string rawValue, out StrategyCustomRuleOption option)
        {
            option = StrategyCustomRuleOption.Off;
            if (string.IsNullOrWhiteSpace(rawValue))
                return false;

            var normalized = rawValue.Trim();
            if (string.Equals(normalized, "__BullishState", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(normalized, "Bullish", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(normalized, "BuyOnly", StringComparison.OrdinalIgnoreCase))
                normalized = nameof(StrategyCustomRuleOption.__Bullish);
            else if (string.Equals(normalized, "__BearishState", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(normalized, "Bearish", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(normalized, "SellOnly", StringComparison.OrdinalIgnoreCase))
                normalized = nameof(StrategyCustomRuleOption.__Bearish);
            else if (string.Equals(normalized, "__AnyBullishState", StringComparison.OrdinalIgnoreCase))
                normalized = nameof(StrategyCustomRuleOption.__Any_Bullish);
            else if (string.Equals(normalized, "__AnyBearishState", StringComparison.OrdinalIgnoreCase))
                normalized = nameof(StrategyCustomRuleOption.__Any_Bearish);
            else if (string.Equals(normalized, "Technical_Confluence", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(normalized, "Momentum_Confluence", StringComparison.OrdinalIgnoreCase))
                normalized = nameof(StrategyCustomRuleOption.__AnyMomentum);
            else if (string.Equals(normalized, "LTF_Bias_Confluence", StringComparison.OrdinalIgnoreCase))
                normalized = nameof(StrategyCustomRuleOption.LTF_Confluence);
            else if (string.Equals(normalized, "HTF_Bias_Confluence", StringComparison.OrdinalIgnoreCase))
                normalized = nameof(StrategyCustomRuleOption.HTF_Confluence);

            return Enum.TryParse(normalized, true, out option);
        }

        private bool TryBuildCustomTradeSignal(string symbolName, TimeFrame strategyTimeFrame, out BacktestStrategySignal signal)
        {
            signal = default(BacktestStrategySignal);
            TradeType tradeType;
            DateTime signalTime;
            string sourceLabel;
            string note;
            double eventSlDistance;
            if (!TryResolveStrategyCustomEventBundle(symbolName, strategyTimeFrame, null, out tradeType, out signalTime, out sourceLabel, out note, out eventSlDistance))
                return false;

            CandlePatternSignalPlan candlePlan;
            var hasCandlePlan = TryBuildCustomCandlePatternSignalPlan(symbolName, strategyTimeFrame, tradeType, out candlePlan);

            signal = new BacktestStrategySignal
            {
                IsValid = true,
                StrategyId = "custom_trade",
                StrategyMode = BacktestStrategyMode.CustomTrade,
                SymbolName = symbolName,
                SourceLabel = sourceLabel,
                TradeType = tradeType,
                SourceTimeFrame = strategyTimeFrame,
                SignalTime = signalTime,
                PatternToEntryBars = 1,
                UseLimitOrder = false,
                EntryPrice = hasCandlePlan ? candlePlan.BaseEntryPrice : 0,
                SecondaryEntryPrice = hasCandlePlan ? candlePlan.SecondaryEntryPrice : 0,
                PreferredSplitEntries = hasCandlePlan ? candlePlan.PreferredSplitEntries : null,
                StopLoss = hasCandlePlan ? candlePlan.StopLoss : 0,
                TakeProfit = hasCandlePlan ? candlePlan.TakeProfit : 0,
                OriginalPatternLow = hasCandlePlan ? candlePlan.PatternLow : 0,
                OriginalPatternHigh = hasCandlePlan ? candlePlan.PatternHigh : 0,
                RelatedStopLevels = hasCandlePlan ? candlePlan.RelatedStopLevels : null,
                Note = hasCandlePlan
                    ? string.Format(
                        CultureInfo.InvariantCulture,
                        "{0}[pattern={1} bars={2}]",
                        note,
                        string.IsNullOrWhiteSpace(candlePlan.PatternLabel) ? "candle" : candlePlan.PatternLabel,
                        Math.Max(1, candlePlan.EndIndex - candlePlan.StartIndex + 1))
                    : note,
                EventSlDistance = eventSlDistance
            };
            InitializeWaitConfirmReference(symbolName, strategyTimeFrame, ref signal);
            ApplyStrategyConfluenceSizing(symbolName, strategyTimeFrame, ref signal);
            SafePrint(
                "[StrategyTrigger] CustomTrade NOW symbol={0} tf={1} side={2} label={3} signal={4:yyyy-MM-dd HH:mm} audit={5}",
                symbolName,
                GetTimeFrameShortLabel(strategyTimeFrame),
                signal.TradeType == TradeType.Buy ? "BUY" : "SELL",
                signal.SourceLabel,
                signal.SignalTime,
                BuildRecentCandlePatternTriggerAudit(symbolName, strategyTimeFrame, 4));
            return true;
        }

        private void InitializeWaitConfirmReference(
            string symbolName,
            TimeFrame strategyTimeFrame,
            ref BacktestStrategySignal signal)
        {
            Bars sourceBars;
            try { sourceBars = GetBarsForCurrentMasterTimer(strategyTimeFrame, symbolName); }
            catch { sourceBars = null; }
            var triggerIndex = ResolveSourceBarIndex(sourceBars, signal.SignalTime);
            if (!IsValidBarIndex(sourceBars, triggerIndex))
                return;

            var referenceEntry = sourceBars.ClosePrices[triggerIndex];
            var isBuy = signal.TradeType == TradeType.Buy;
            var invalidationCandidates = new List<double>();
            AddWaitConfirmInvalidationCandidate(invalidationCandidates, signal.StopLoss, referenceEntry, isBuy);
            AddWaitConfirmInvalidationCandidate(invalidationCandidates, isBuy ? signal.OriginalPatternLow : signal.OriginalPatternHigh, referenceEntry, isBuy);
            AddWaitConfirmInvalidationCandidate(invalidationCandidates, isBuy ? signal.RelatedZoneLow : signal.RelatedZoneHigh, referenceEntry, isBuy);
            foreach (var level in signal.RelatedStopLevels ?? new List<double>())
                AddWaitConfirmInvalidationCandidate(invalidationCandidates, level, referenceEntry, isBuy);

            var invalidation = invalidationCandidates
                .OrderBy(price => Math.Abs(referenceEntry - price))
                .FirstOrDefault();
            var triggerRange = Math.Max(0, sourceBars.HighPrices[triggerIndex] - sourceBars.LowPrices[triggerIndex]);
            if (!(invalidation > 0))
            {
                var fallbackDistance = Math.Max(signal.EventSlDistance, triggerRange);
                invalidation = fallbackDistance > 0
                    ? (isBuy ? referenceEntry - fallbackDistance : referenceEntry + fallbackDistance)
                    : 0;
            }

            signal.OriginalEntryReference = referenceEntry;
            signal.OriginalInvalidationPrice = invalidation;
            signal.OriginalRiskDistance = invalidation > 0
                ? Math.Abs(referenceEntry - invalidation)
                : Math.Max(signal.EventSlDistance, triggerRange);
        }

        private static void AddWaitConfirmInvalidationCandidate(
            List<double> candidates,
            double price,
            double referenceEntry,
            bool isBuy)
        {
            if (candidates == null || !(price > 0) || !(referenceEntry > 0))
                return;
            if (isBuy ? price >= referenceEntry : price <= referenceEntry)
                return;
            if (!candidates.Any(existing => Math.Abs(existing - price) <= 0.0000001))
                candidates.Add(price);
        }

        // Stateless Wait_confirm: on every newly closed source bar, travel backward to the
        // latest selected trigger and verify that this bar is its first valid confirmation.
        // No WAITING trade-entry object is required; only a successful add-on key is persisted.
        private bool TryBuildCustomWaitConfirmSignal(
            string symbolName,
            TimeFrame strategyTimeFrame,
            int tradeChainSlot,
            out BacktestStrategySignal signal)
        {
            signal = default(BacktestStrategySignal);
            if (ResolveStrategyTradeChainMode(tradeChainSlot) != StrategyTradeChainMode.Wait_confirm)
                return false;

            Bars sourceBars;
            try { sourceBars = GetBarsForCurrentMasterTimer(strategyTimeFrame, symbolName); }
            catch { sourceBars = null; }
            if (sourceBars == null || sourceBars.Count < 4)
                return false;

            var confirmationIndex = sourceBars.Count - 2;
            var confirmationOpen = sourceBars.OpenPrices[confirmationIndex];
            var confirmationClose = sourceBars.ClosePrices[confirmationIndex];
            if (confirmationClose == confirmationOpen)
                return false;

            var isBullish = confirmationClose > confirmationOpen;
            var selectedOptions = GetSelectedStrategyCustomEventOptions();
            if (selectedOptions.Count == 0)
                return false;

            var previousSnapshot = BuildSharedIndicatorSnapshot(sourceBars, Math.Max(0, confirmationIndex - 1));
            var currentSnapshot = BuildSharedIndicatorSnapshot(sourceBars, confirmationIndex);
            if (!TryPassSelectedStrategyCustomRules(
                symbolName,
                sourceBars,
                strategyTimeFrame,
                confirmationIndex,
                previousSnapshot,
                currentSnapshot,
                isBullish))
                return false;

            var maxBars = Math.Max(1, WaitConfirmMaxBars);
            var earliestIndex = Math.Max(1, confirmationIndex - maxBars);
            var earliestTime = sourceBars.OpenTimes[earliestIndex];
            var confirmationTime = sourceBars.OpenTimes[confirmationIndex];
            var priorTriggerCandidates = CollectTradeTriggerCandidates(symbolName, strategyTimeFrame)
                .Where(trigger => trigger.BarTime >= earliestTime && trigger.BarTime < confirmationTime)
                .Where(trigger => selectedOptions.Any(option => TradeTriggerMatchesSelectedOption(trigger, option)))
                .ToList();

            TradeTriggerEvent priorTrigger = default(TradeTriggerEvent);
            var priorStopDistance = 0.0;
            var priorPatternEndIndex = -1;
            foreach (var triggerBar in priorTriggerCandidates
                .GroupBy(trigger => trigger.BarTime)
                .OrderByDescending(group => group.Key))
            {
                var candidatesOnBar = triggerBar.ToList();
                var optionStates = BuildSelectedTriggerOptionStates(selectedOptions, candidatesOnBar);
                var matchedCount = optionStates.Count(state =>
                    (isBullish ? state.Item3 : state.Item4) || state.Item5);
                var triggerBundlePassed = SelectedStrategyCustomEventsMode == StrategyCustomEventsMode.AND
                    ? matchedCount == selectedOptions.Count
                    : matchedCount > 0;
                if (!triggerBundlePassed)
                    continue;

                TradeTriggerEvent candidateTrigger;
                if (!TryResolvePrimaryTradeTrigger(candidatesOnBar, selectedOptions, isBullish, out candidateTrigger))
                    continue;

                var candidateTriggerIndex = ResolveSourceBarIndex(sourceBars, candidateTrigger.BarTime);
                if (!IsValidBarIndex(sourceBars, candidateTriggerIndex))
                    continue;
                var candidatePatternEndIndex = candidateTriggerIndex;
                int candidatePatternStartIndex;
                int resolvedPatternEndIndex;
                if (TryGetCustomEventPatternWindow(candidateTrigger.Option, candidateTriggerIndex, out candidatePatternStartIndex, out resolvedPatternEndIndex))
                    candidatePatternEndIndex = Math.Min(resolvedPatternEndIndex, sourceBars.Count - 2);
                if (!CTraderStrategyEngine.IsFirstDirectionalBarAfter(
                    sourceBars,
                    candidatePatternEndIndex,
                    confirmationIndex,
                    isBullish))
                    continue;

                priorTrigger = candidateTrigger;
                priorPatternEndIndex = candidatePatternEndIndex;
                priorStopDistance = ResolveTradeTriggerStopDistance(candidatesOnBar, selectedOptions, isBullish);
                break;
            }

            if (string.IsNullOrWhiteSpace(priorTrigger.Name))
                return false;

            var priorTriggerIndex = ResolveSourceBarIndex(sourceBars, priorTrigger.BarTime);
            var originalPatternLow = 0.0;
            var originalPatternHigh = 0.0;
            var relatedStopLevels = new List<double>();
            int patternStartIndex;
            int patternEndIndex;
            if (TryGetCustomEventPatternWindow(priorTrigger.Option, priorTriggerIndex, out patternStartIndex, out patternEndIndex))
            {
                patternEndIndex = Math.Min(patternEndIndex, sourceBars.Count - 2);
                originalPatternLow = Enumerable.Range(patternStartIndex, patternEndIndex - patternStartIndex + 1)
                    .Select(index => sourceBars.LowPrices[index])
                    .Min();
                originalPatternHigh = Enumerable.Range(patternStartIndex, patternEndIndex - patternStartIndex + 1)
                    .Select(index => sourceBars.HighPrices[index])
                    .Max();
                relatedStopLevels.Add(originalPatternLow);
                relatedStopLevels.Add(originalPatternHigh);
            }
            if (priorTrigger.HasCanonicalEvent && priorTrigger.CanonicalEvent.ZoneHigh > priorTrigger.CanonicalEvent.ZoneLow)
            {
                relatedStopLevels.Add(priorTrigger.CanonicalEvent.ZoneLow);
                relatedStopLevels.Add(priorTrigger.CanonicalEvent.ZoneHigh);
            }

            var confirmationRange = Math.Max(
                0,
                sourceBars.HighPrices[confirmationIndex] - sourceBars.LowPrices[confirmationIndex]);
            signal = new BacktestStrategySignal
            {
                IsValid = true,
                StrategyId = "custom_trade",
                StrategyMode = BacktestStrategyMode.CustomTrade,
                SymbolName = symbolName,
                SourceLabel = priorTrigger.Name,
                TradeType = isBullish ? TradeType.Buy : TradeType.Sell,
                SourceTimeFrame = strategyTimeFrame,
                // Preserve the original trigger identity so the add-on finds its Now position.
                SignalTime = priorTrigger.BarTime,
                EntryConfirmationTime = confirmationTime,
                PatternToEntryBars = CTraderStrategyEngine.ResolvePatternToEntryBars(priorPatternEndIndex, confirmationIndex),
                TradeChainSlot = tradeChainSlot,
                UseLimitOrder = false,
                EntryPrice = confirmationClose,
                EventSlDistance = Math.Max(priorStopDistance, confirmationRange),
                OriginalPatternLow = originalPatternLow,
                OriginalPatternHigh = originalPatternHigh,
                RelatedZoneLow = priorTrigger.HasCanonicalEvent ? priorTrigger.CanonicalEvent.ZoneLow : 0,
                RelatedZoneHigh = priorTrigger.HasCanonicalEvent ? priorTrigger.CanonicalEvent.ZoneHigh : 0,
                RelatedStopLevels = relatedStopLevels,
                Note = string.Format(
                    CultureInfo.InvariantCulture,
                    "[wait_confirm trigger={0}@{1:yyyy-MM-dd HH:mm}; lookback={2}]",
                    priorTrigger.Name,
                    priorTrigger.BarTime,
                    maxBars)
            };
            InitializeWaitConfirmReference(symbolName, strategyTimeFrame, ref signal);

            CTraderWaitConfirmDecision decision;
            Bars evaluationBars;
            int evaluationTriggerIndex;
            if (!TryEvaluateWaitConfirm(
                    symbolName,
                    ref signal,
                    out decision,
                    out evaluationBars,
                    out evaluationTriggerIndex) ||
                decision == null ||
                decision.Kind != CTraderWaitConfirmDecisionKind.Confirm)
                return false;

            var evaluatedConfirmationIndex = evaluationTriggerIndex + decision.ConfirmationOffset;
            if (!IsValidBarIndex(evaluationBars, evaluatedConfirmationIndex) ||
                evaluationBars.OpenTimes[evaluatedConfirmationIndex].Ticks != confirmationTime.Ticks)
                return false;

            signal.WaitConfirmActionKey = BuildWaitConfirmTravelKey(symbolName, signal);
            if (_releasedEntryBarSignalKeys.Contains(signal.WaitConfirmActionKey))
                return false;

            ApplyStrategyConfluenceSizing(symbolName, strategyTimeFrame, ref signal);
            SafePrint(
                "[WaitConfirm] MATCHED symbol={0} tf={1} side={2} trigger={3}@{4:yyyy-MM-dd HH:mm} confirm={5:yyyy-MM-dd HH:mm} bars={6} slot=#{7} pullback={8} chase_r={9:0.###} risk_x={10:0.###}",
                symbolName,
                GetMiniChartLabel(strategyTimeFrame),
                signal.TradeType == TradeType.Buy ? "BUY" : "SELL",
                priorTrigger.Name,
                priorTrigger.BarTime,
                confirmationTime,
                signal.PatternToEntryBars,
                tradeChainSlot,
                decision.PullbackSeen,
                decision.ChaseR,
                decision.RiskMultiplier);
            return true;
        }

        private bool MarkerMatchesSelectedCandleOption(
            DirectionalPatternMarkerAggregate marker,
            IEnumerable<StrategyCustomEventOption> selectedOptions)
        {
            if (marker == null || marker.Labels == null || selectedOptions == null)
                return false;

            foreach (var option in selectedOptions)
            {
                var optionName = option.ToString();
                if (optionName.StartsWith("__AnyCandlePattern", StringComparison.Ordinal))
                    return true;

                var separatorIndex = optionName.IndexOf('_');
                if (separatorIndex <= 0)
                    continue;
                var patternOperand = optionName.Substring(0, separatorIndex).ToLowerInvariant();
                if (marker.Labels.Any(label => string.Equals(
                    GetCanonicalCandlePatternOperand(label),
                    patternOperand,
                    StringComparison.OrdinalIgnoreCase)))
                    return true;
            }

            return false;
        }

        private double GetCandleMarkerStopDistance(Bars sourceBars, DirectionalPatternMarkerAggregate marker)
        {
            if (sourceBars == null || marker == null)
                return 0;

            var startIndex = Math.Max(0, marker.PatternBarIndex - Math.Max(1, marker.PatternSpan) + 1);
            var endIndex = Math.Min(sourceBars.Count - 2, Math.Max(marker.PatternBarIndex, marker.BarIndex));
            var low = double.MaxValue;
            var high = double.MinValue;
            for (var index = startIndex; index <= endIndex; index++)
            {
                low = Math.Min(low, sourceBars.LowPrices[index]);
                high = Math.Max(high, sourceBars.HighPrices[index]);
            }
            return low < double.MaxValue && high > double.MinValue ? Math.Max(0, high - low) : 0;
        }

        private bool TryBuildCustomCandlePatternSignalPlan(string symbolName, TimeFrame strategyTimeFrame, TradeType tradeType, out CandlePatternSignalPlan plan)
        {
            plan = default(CandlePatternSignalPlan);
            if (string.IsNullOrWhiteSpace(symbolName))
                return false;

            Symbol symbol;
            Bars sourceBars;
            int signalIndex;
            int previousIndex;
            if (!TryGetBacktestStrategyBars(symbolName, strategyTimeFrame, out symbol, out sourceBars, out signalIndex, out previousIndex))
                return false;

            if (symbol == null || sourceBars == null || signalIndex < 1 || signalIndex >= sourceBars.Count)
                return false;

            var previousSnapshot = BuildSharedIndicatorSnapshot(sourceBars, Math.Max(0, signalIndex - 1));
            var currentSnapshot = BuildSharedIndicatorSnapshot(sourceBars, signalIndex);
            var sharedPatterns = GetDetectedSharedRulePatternSet(sourceBars, strategyTimeFrame, signalIndex);
            var recentCanonicalEvents = GetCanonicalEventsForSymbolTimeFrame(symbolName, strategyTimeFrame, 48)
                .OrderByDescending(evt => evt.BarTime)
                .ThenByDescending(evt => evt.Score)
                .ToList();
            var barTime = sourceBars.OpenTimes[signalIndex];
            var eventsOnBar = recentCanonicalEvents
                .Where(evt => evt.BarTime == barTime)
                .OrderByDescending(evt => evt.Score)
                .ToList();

            var matchedWindows = new List<Tuple<int, int, string>>();
            var relatedStopLevels = new List<double>();
            foreach (var option in GetSelectedStrategyCustomEventOptions())
            {
                bool matchesBullish;
                bool matchesBearish;
                bool matchesDirectionless;
                string shortLabel;
                if (!TryEvaluateStrategyCustomEventOption(
                    option,
                    symbolName,
                    sourceBars,
                    strategyTimeFrame,
                    signalIndex,
                    previousSnapshot,
                    currentSnapshot,
                    sharedPatterns,
                    recentCanonicalEvents,
                    eventsOnBar,
                    out matchesBullish,
                    out matchesBearish,
                    out matchesDirectionless,
                    out shortLabel))
                    continue;

                var directionMatches = tradeType == TradeType.Buy ? matchesBullish : matchesBearish;
                if (!directionMatches && !matchesDirectionless)
                    continue;

                int startIndex;
                int endIndex;
                if (!TryGetCustomEventPatternWindow(option, signalIndex, out startIndex, out endIndex))
                    continue;
                List<CandleConfluenceMatch> tradeConfluenceMatches;
                if (!ShouldKeepCandlePatternInline(sourceBars, strategyTimeFrame, endIndex, tradeType == TradeType.Buy, out tradeConfluenceMatches, symbolName, symbol))
                    continue;
                if (!HasDirectionalReversalWick(sourceBars, endIndex, tradeType == TradeType.Buy))
                    continue;

                foreach (var match in tradeConfluenceMatches ?? new List<CandleConfluenceMatch>())
                {
                    if (match == null || !IsFiniteNumber(match.Low) || !IsFiniteNumber(match.High))
                        continue;
                    var protectiveEdge = tradeType == TradeType.Buy ? Math.Min(match.Low, match.High) : Math.Max(match.Low, match.High);
                    var midpoint = (match.Low + match.High) * 0.5;
                    if (!relatedStopLevels.Contains(protectiveEdge))
                        relatedStopLevels.Add(protectiveEdge);
                    if (!relatedStopLevels.Contains(midpoint))
                        relatedStopLevels.Add(midpoint);
                }

                matchedWindows.Add(Tuple.Create(startIndex, endIndex, shortLabel));
            }

            if (matchedWindows.Count == 0)
                return false;

            var unionStart = matchedWindows.Min(window => window.Item1);
            var unionEnd = matchedWindows.Max(window => window.Item2);
            if (unionStart < 0 || unionEnd < unionStart || unionEnd >= sourceBars.Count)
                return false;

            var patternLow = double.MaxValue;
            var patternHigh = double.MinValue;
            for (var i = unionStart; i <= unionEnd; i++)
            {
                patternLow = Math.Min(patternLow, sourceBars.LowPrices[i]);
                patternHigh = Math.Max(patternHigh, sourceBars.HighPrices[i]);
            }

            var baseEntry = NormalizePriceToSymbol(symbol, sourceBars.ClosePrices[signalIndex]);
            if (!(baseEntry > 0) || !IsFiniteNumber(patternLow) || !IsFiniteNumber(patternHigh) || patternLow >= patternHigh)
                return false;

            var patternHeight = Math.Max(patternHigh - patternLow, symbol.PipSize);
            var stopBuffer = Math.Max(symbol.PipSize, patternHeight * 0.10);
            var stopLoss = ResolveCandlePatternSwingStopLossPrice(symbol, sourceBars, signalIndex, unionStart, unionEnd, tradeType, patternLow, patternHigh, stopBuffer);
            var riskDistance = tradeType == TradeType.Buy
                ? baseEntry - stopLoss
                : stopLoss - baseEntry;
            if (!(riskDistance > 0))
                return false;

            var rewardRisk = Math.Max(0.1, StrategyRewardRisk);
            var takeProfit = tradeType == TradeType.Buy
                ? NormalizePriceToSymbol(symbol, baseEntry + (riskDistance * rewardRisk))
                : NormalizePriceToSymbol(symbol, baseEntry - (riskDistance * rewardRisk));

            plan = new CandlePatternSignalPlan
            {
                IsValid = true,
                BaseEntryPrice = baseEntry,
                SecondaryEntryPrice = BuildCandlePatternRetracementEntry(symbol, tradeType, baseEntry, stopLoss, 0.25),
                PreferredSplitEntries = BuildCandlePatternRetracementEntries(symbol, tradeType, baseEntry, stopLoss),
                StopLoss = stopLoss,
                TakeProfit = takeProfit,
                PatternLow = patternLow,
                PatternHigh = patternHigh,
                RelatedStopLevels = relatedStopLevels,
                StartIndex = unionStart,
                EndIndex = unionEnd,
                PatternLabel = string.Join("+", matchedWindows.Select(window => window.Item3).Where(label => !string.IsNullOrWhiteSpace(label)).Distinct())
            };
            return true;
        }

        private double ResolveCandlePatternSwingStopLossPrice(Symbol symbol, Bars sourceBars, int signalIndex, int startIndex, int endIndex, TradeType tradeType, double patternLow, double patternHigh, double stopBuffer)
        {
            if (symbol == null || sourceBars == null)
                return 0;

            var tolerance = Math.Max(symbol.PipSize * 2.0, 0.0000001);
            var swings = CollectConfirmedSwings(sourceBars, Math.Max(120, (endIndex - startIndex) + 40), signalIndex);
            var fallbackSwingPrice = tradeType == TradeType.Buy ? patternLow : patternHigh;
            var swingPrice = CTraderStrategyEngine.SelectProtectiveSwing(
                swings.Select(swing => new CTraderStructureSwing
                {
                    Index = swing.BarIndex,
                    Price = swing.Price,
                    IsHigh = swing.IsHigh
                }),
                tradeType,
                endIndex,
                fallbackSwingPrice,
                tolerance);
            return tradeType == TradeType.Buy
                ? NormalizePriceToSymbol(symbol, swingPrice - stopBuffer)
                : NormalizePriceToSymbol(symbol, swingPrice + stopBuffer);
        }

        private double BuildCandlePatternRetracementEntry(Symbol symbol, TradeType tradeType, double baseEntry, double stopLoss, double retracementRatio)
        {
            return CTraderStrategyEngine.ResolveRetracementEntry(symbol, tradeType, baseEntry, stopLoss, retracementRatio);
        }

        private List<double> BuildCandlePatternRetracementEntries(Symbol symbol, TradeType tradeType, double baseEntry, double stopLoss)
        {
            return CTraderStrategyEngine.BuildRetracementEntries(symbol, tradeType, baseEntry, stopLoss, new[] { 0.25, 0.50, 0.75 });
        }

        private bool TryBuildEventDrivenStrategySignal(string symbolName, TimeFrame strategyTimeFrame, BacktestStrategyMode mode, out BacktestStrategySignal signal)
        {
            signal = default(BacktestStrategySignal);
            if (string.IsNullOrWhiteSpace(symbolName))
                return false;

            CanonicalMarketEvent triggerEvent;
            string strategyId;
            string sourceLabel;
            CanonicalEventType[] acceptedTypes;
            switch (mode)
            {
                case BacktestStrategyMode.Trend:
                    strategyId = "follow_trend";
                    sourceLabel = "CT";
                    acceptedTypes = new[] { CanonicalEventType.Continuation };
                    break;
                case BacktestStrategyMode.Impulse:
                    strategyId = "follow_trend_big_candle";
                    sourceLabel = "IM";
                    acceptedTypes = new[] { CanonicalEventType.Impulse };
                    break;
                default:
                    return false;
            }

            DateTime latestClosedBarTime;
            List<CanonicalMarketEvent> eventsOnBar;
            if (!TryGetCanonicalEventsOnLatestClosedBar(symbolName, strategyTimeFrame, out latestClosedBarTime, out eventsOnBar))
                return false;

            var exactBarCandidates = eventsOnBar
                .Where(evt => acceptedTypes.Contains(evt.EventType))
                .OrderByDescending(evt => evt.Score)
                .ToList();
            if (exactBarCandidates.Count == 0)
                return false;
            triggerEvent = exactBarCandidates[0];

            signal = new BacktestStrategySignal
            {
                IsValid = true,
                StrategyId = strategyId,
                StrategyMode = mode,
                SymbolName = symbolName,
                SourceLabel = sourceLabel,
                TradeType = triggerEvent.IsBullish ? TradeType.Buy : TradeType.Sell,
                SourceTimeFrame = triggerEvent.SourceTimeFrame,
                SignalTime = triggerEvent.BarTime,
                UseLimitOrder = false,
                EntryPrice = 0,
                StopLoss = 0,
                TakeProfit = 0,
                Note = string.Format(
                    CultureInfo.InvariantCulture,
                    "[event={0} reason={1} score={2}]",
                    triggerEvent.EventType,
                    FormatCanonicalEventReasonShort(triggerEvent.Reason),
                    triggerEvent.Score)
            };
            return true;
        }

        private bool TryGetBacktestBiasConfluence(string symbolName, bool wantBullish, out string reason)
        {
            reason = "";
            if (string.IsNullOrWhiteSpace(symbolName))
            {
                reason = "symbol_missing";
                return false;
            }

            var trendBias = GetSymbolTrendBias(symbolName);
            var dailyBias = trendBias.Item1;
            var h4Bias = trendBias.Item2;
            var wantsPositive = wantBullish;

            var dailyAligned = wantsPositive ? dailyBias >= 2 : dailyBias <= -2;
            var h4Aligned = wantsPositive ? h4Bias >= 2 : h4Bias <= -2;
            if (dailyAligned && h4Aligned)
                return true;

            reason = string.Format(
                CultureInfo.InvariantCulture,
                "bias_not_aligned d1={0} h4={1} expected={2}",
                dailyBias,
                h4Bias,
                wantBullish ? "bullish" : "bearish");
            return false;
        }

        private DateTime ResolveLatestClosedBarTime(string symbolName, TimeFrame timeFrame)
        {
            DateTime barTime;
            return TryGetLatestClosedCanonicalBarTime(symbolName, timeFrame, out barTime)
                ? barTime
                : DateTime.MinValue;
        }

        private void ExecuteBacktestStrategyMarketEntry(string symbolName, CanonicalMarketEvent strategyEvent, string strategyId, bool requireHtfBiasConfluence)
        {
            DateTime entryBarTime;
            if (!TryResolveStrategyEntryBar(
                symbolName,
                strategyEvent.SourceTimeFrame,
                strategyEvent.BarTime,
                strategyEvent.IsBullish ? TradeType.Buy : TradeType.Sell,
                StrategyEntryBarMode.First_bar_after_trigger,
                out entryBarTime))
                return;

            var strategyExecutionTime = ResolveSourceBarEndTime(null, strategyEvent.BarTime, strategyEvent.SourceTimeFrame);
            if (!ShouldAllowStrategySignalTime(strategyExecutionTime))
            {
                LogStrategySkip(strategyId, symbolName, GetStrategyTradingTimeBlockReason(strategyExecutionTime));
                return;
            }

            if (!HasStrategyBarVolumeSurge(symbolName, strategyEvent.SourceTimeFrame, strategyEvent.BarTime))
            {
                LogStrategySkip(strategyId, symbolName, "vol_surge_miss");
                return;
            }

            var eventKey = string.Format(
                CultureInfo.InvariantCulture,
                "{0}|{1}|{2}|{3}|{4}|{5}",
                strategyId,
                symbolName.ToUpperInvariant(),
                strategyEvent.SourceTimeFrame,
                strategyEvent.EventType,
                strategyEvent.IsBullish ? "B" : "S",
                strategyEvent.BarTime.Ticks);
            if (_backtestStrategyHandledEventKeys.Contains(eventKey))
                return;

            var finalGateSignal = new BacktestStrategySignal
            {
                IsValid = true,
                StrategyId = strategyId,
                SymbolName = symbolName,
                SourceLabel = BuildCanonicalMarketEventName(strategyEvent),
                TradeType = strategyEvent.IsBullish ? TradeType.Buy : TradeType.Sell,
                SourceTimeFrame = strategyEvent.SourceTimeFrame,
                SignalTime = strategyEvent.BarTime,
                EntryConfirmationTime = strategyEvent.BarTime
            };
            string finalConfluenceRejectReason;
            if (!TryPassFinalStrategyConfluenceGate(symbolName, finalGateSignal, out finalConfluenceRejectReason))
            {
                LogStrategyReject(strategyId, symbolName, finalConfluenceRejectReason);
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            if (requireHtfBiasConfluence)
            {
                string confluenceReason;
                if (!TryGetBacktestBiasConfluence(symbolName, strategyEvent.IsBullish, out confluenceReason))
                {
                    LogStrategySkip(strategyId, symbolName, confluenceReason);
                    _backtestStrategyHandledEventKeys.Add(eventKey);
                    return;
                }
            }

            var symbol = ResolveLoadedSymbol(symbolName);
            if (symbol == null)
                return;

            var tradeType = strategyEvent.IsBullish ? TradeType.Buy : TradeType.Sell;
            var action = strategyEvent.IsBullish ? "BUY" : "SELL";
            var canonicalEventName = BuildCanonicalMarketEventName(strategyEvent);

            string positionCapRejectReason;
            if (!TryPassStrategyPositionCaps(symbolName, tradeType, out positionCapRejectReason))
            {
                LogStrategyReject(strategyId, symbolName, positionCapRejectReason);
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            var executionPrice = tradeType == TradeType.Buy ? symbol.Ask : symbol.Bid;
            if (executionPrice <= 0)
                return;

            var profileRaw = GetChartTradeProfileRaw();
            var protection = BuildSharedChartProtectionPrices(symbol, symbolName, tradeType, executionPrice, ResolveChartFallbackStopPips(symbol), profileRaw);
            if (protection == null)
            {
                LogStrategySkip(strategyId, symbolName, "no valid SL/TP from structure");
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            var sl = protection.Item1;
            var tp = protection.Item2;
            string protectionReason;
            if (!TryValidateProtectionPrices(symbol, action, executionPrice, sl, tp, out protectionReason))
            {
                LogStrategySkip(strategyId, symbolName, protectionReason);
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            var finalRiskMoney = ResolveChartFinalRiskMoney(profileRaw);
            // n.Trades: 2..5 splits the entry into a market first leg plus
            // limit legs between the market price and SL. Total risk stays capped at
            // finalRiskMoney (split across the legs by weight). Auto/1 keep one order.
            var orderCountOverride = ResolveStrategyOrderCount();
            var pendingEntries = new List<double>();
            if (orderCountOverride > 1)
            {
                pendingEntries = BuildStrategyEqualSplitEntries(symbol, tradeType, executionPrice, sl, orderCountOverride)
                    .Skip(1)
                    .ToList();
            }
            var splitWeights = BuildChartSplitRiskWeights(1 + pendingEntries.Count, true);
            var hasSplitGroup = splitWeights.Length > 1;
            var marketRiskMoney = Math.Max(0, finalRiskMoney * splitWeights[0]);
            var volumeUnits = ResolveChartTradeVolumeForRisk(symbol, tradeType, executionPrice, sl, marketRiskMoney, symbolName);
            if (volumeUnits < symbol.VolumeInUnitsMin)
            {
                LogStrategySkip(strategyId, symbolName, "volume below minimum for risk cap");
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            double approvedSl;
            double approvedTp;
            double approvedVolumeUnits;
            double approvedRiskMoney;
            double marginEstimate;
            double marginBudget;
            string gateRejectReason;
                if (!TryPassSharedCreationGate(
                    symbol,
                    action,
                    "market",
                    0,
                    executionPrice,
                    sl,
                    tp,
                    volumeUnits,
                    marketRiskMoney,
                    marketRiskMoney,
                    false,
                    out approvedSl,
                    out approvedTp,
                    out approvedVolumeUnits,
                    out approvedRiskMoney,
                    out marginEstimate,
                out marginBudget,
                out gateRejectReason))
            {
                LogStrategyReject(strategyId, symbolName, gateRejectReason);
                if (IsStrictPropRiskTemplate())
                {
                    StopBacktestForPropRuleBreach("ENTRY", symbolName, gateRejectReason);
                    return;
                }
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            double? slPips = CTraderExecutionEngine.ResolveDistancePips(symbol, executionPrice, approvedSl);
            double? tpPips = symbol.PipSize > 0
                ? (double?)Math.Round(Math.Abs(approvedTp - executionPrice) / symbol.PipSize, 2)
                : null;
            if (!slPips.HasValue || slPips.Value <= 0)
            {
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            if (!ShouldStrategySubmitOrders())
            {
                SafePrint(
                    "[Strategy] Signal {0} {1} {2} from {3} {4} @ {5:F5} SL={6:F5} TP={7:F5} risk={8:F2}",
                    strategyId,
                    action,
                    symbolName,
                    GetMiniChartLabel(strategyEvent.SourceTimeFrame),
                    canonicalEventName,
                    executionPrice,
                    approvedSl,
                    approvedTp,
                    approvedRiskMoney);
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            // The compact chain id lets chart markers recover the original trigger bar after
            // restart without restoring the removed tr:* token to the visible broker comment.
            var label = BuildStrategyOrderLabel(
                strategyId,
                BuildStrategyChainSid(symbolName, strategyEvent.SourceTimeFrame, strategyEvent.BarTime));
            var firstOrderComment = BuildStrategyOrderComment(
                symbol,
                BuildStrategyTradeGroupKey(symbolName, new BacktestStrategySignal
                {
                    StrategyId = strategyId,
                    SymbolName = symbolName,
                    SourceTimeFrame = strategyEvent.SourceTimeFrame,
                    SignalTime = strategyEvent.BarTime
                }),
                1,
                symbolName,
                strategyEvent.SourceTimeFrame,
                canonicalEventName,
                executionPrice,
                approvedTp,
                approvedSl,
                FormatStrategyRiskLegComment(1, approvedRiskMoney, finalRiskMoney));
            var requestedLots = symbol.VolumeInUnitsToQuantity(approvedVolumeUnits);
            LogStructuredTradeEvent(
                "backtest",
                "SUBMIT",
                symbolName,
                action,
                "MARKET",
                requestedLots,
                executionPrice,
                approvedSl,
                approvedTp,
                "",
                strategyId + ":" + canonicalEventName);
            var result = ExecuteMarketOrder(tradeType, symbol.Name, approvedVolumeUnits, label, slPips, tpPips, firstOrderComment);
            if (result != null && result.IsSuccessful)
            {
                var finalApprovedSl = approvedSl;
                var finalApprovedTp = approvedTp;
                if (result.Position != null)
                {
                    ReanchorProtectionToFilledEntry(symbol, action, executionPrice, result.Position.EntryPrice, ref finalApprovedSl, ref finalApprovedTp);
                    string protectionError;
                    if (!TryEnsureStrategyPositionProtection(result.Position, symbol, action, finalApprovedSl, finalApprovedTp, out protectionError))
                    {
                        var closeProtectionResult = ClosePosition(result.Position);
                        var closeProtectionNote = closeProtectionResult != null && closeProtectionResult.IsSuccessful
                            ? "position_closed_after_protection_failure"
                            : "position_close_failed_after_protection_failure";
                        LogStructuredTradeEvent(
                            IsBacktestingRuntime() ? "backtest" : "live",
                            "FAILED",
                            symbolName,
                            action,
                            "MARKET",
                            requestedLots,
                            result.Position.EntryPrice,
                            finalApprovedSl,
                            finalApprovedTp,
                            result.Position.Id.ToString(CultureInfo.InvariantCulture),
                            protectionError + "; " + closeProtectionNote);
                        SafePrint("[Strategy] Entry failed {0} {1}: {2}; {3}", strategyId, symbolName, protectionError, closeProtectionNote);
                        _backtestStrategyHandledEventKeys.Add(eventKey);
                        return;
                    }
                }

                if (result.Position != null)
                {
                    var submittedSignal = new BacktestStrategySignal
                    {
                        IsValid = true,
                        StrategyId = strategyId,
                        SourceLabel = canonicalEventName,
                        TradeType = tradeType,
                        SourceTimeFrame = strategyEvent.SourceTimeFrame,
                        SignalTime = strategyEvent.BarTime,
                        UseLimitOrder = false,
                        EntryPrice = executionPrice,
                        StopLoss = finalApprovedSl,
                        TakeProfit = finalApprovedTp,
                        Note = ""
                    };
                    StoreBacktestExportTradeSnapshot(
                        result.Position.Id.ToString(CultureInfo.InvariantCulture),
                        submittedSignal,
                        approvedRiskMoney,
                        approvedVolumeUnits,
                        symbol.VolumeInUnitsToQuantity(approvedVolumeUnits));
                }
                LogStructuredTradeEvent(
                    IsBacktestingRuntime() ? "backtest" : "live",
                    "SUCCEEDED",
                    symbolName,
                    action,
                    "MARKET",
                    requestedLots,
                    result.Position != null ? result.Position.EntryPrice : executionPrice,
                    finalApprovedSl,
                    finalApprovedTp,
                    result.Position != null ? result.Position.Id.ToString(CultureInfo.InvariantCulture) : "",
                    strategyId + ":" + canonicalEventName);
                SafePrint(
                    "[Strategy] Entry {0} {1} {2} from {3} {4} vol={5:F2} risk={6:F2}",
                    strategyId,
                    action,
                    symbolName,
                    GetMiniChartLabel(strategyEvent.SourceTimeFrame),
                    canonicalEventName,
                    approvedVolumeUnits,
                    approvedRiskMoney);
                AddCustomTradeTriggerMarker(symbolName, finalGateSignal);
                _backtestStrategyHandledEventKeys.Add(eventKey);

                var pendingWeights = splitWeights.Skip(1).Take(pendingEntries.Count).ToArray();
                var affordablePending = new List<double>();
                var affordablePendingWeights = new List<double>();
                TryResolveAffordableSplitLegs(symbol, tradeType, pendingEntries, pendingWeights, sl, finalRiskMoney, affordablePending, affordablePendingWeights);

                var placedPendingCount = 0;
                for (var i = 0; i < affordablePending.Count && i < affordablePendingWeights.Count; i++)
                {
                    string splitPositionCapRejectReason;
                    if (!TryPassStrategyPositionCaps(symbolName, tradeType, out splitPositionCapRejectReason))
                    {
                        LogStrategyReject(strategyId, symbolName, splitPositionCapRejectReason);
                        break;
                    }

                    var splitNumber = i + 2;
                    var entry = affordablePending[i];
                    var sliceRiskMoney = finalRiskMoney > 0 ? Math.Max(0, finalRiskMoney * affordablePendingWeights[i]) : 0;
                    var pendingVolumeUnits = ResolveChartTradeVolumeForRisk(symbol, tradeType, entry, sl, sliceRiskMoney, symbolName);
                    if (pendingVolumeUnits < symbol.VolumeInUnitsMin)
                        continue;

                    double approvedPendingSl;
                    double approvedPendingTp;
                    double approvedPendingVolumeUnits;
                    double approvedPendingRiskMoney;
                    double approvedPendingMarginEstimate;
                    double approvedPendingMarginBudget;
                    string pendingGateRejectReason;
                    if (!TryPassSharedCreationGate(
                        symbol,
                        action,
                        "limit",
                        entry,
                        executionPrice,
                        sl,
                        tp,
                        pendingVolumeUnits,
                        sliceRiskMoney,
                        sliceRiskMoney,
                        false,
                        out approvedPendingSl,
                        out approvedPendingTp,
                        out approvedPendingVolumeUnits,
                        out approvedPendingRiskMoney,
                        out approvedPendingMarginEstimate,
                        out approvedPendingMarginBudget,
                        out pendingGateRejectReason))
                        continue;

                    if (approvedPendingVolumeUnits < symbol.VolumeInUnitsMin)
                        continue;

                    var limitSlPips = symbol.PipSize > 0 ? (double?)Math.Round(Math.Abs(entry - approvedPendingSl) / symbol.PipSize, 2) : null;
                    var limitTpPips = symbol.PipSize > 0 ? (double?)Math.Round(Math.Abs(approvedPendingTp - entry) / symbol.PipSize, 2) : null;
                    var pendingResult = PlaceLimitOrder(
                        tradeType,
                        symbol.Name,
                        approvedPendingVolumeUnits,
                        entry,
                        label,
                        limitSlPips,
                        limitTpPips,
                        (ProtectionType?)null,
                        null,
                        BuildStrategyOrderComment(
                            symbol,
                            BuildStrategyTradeGroupKey(symbolName, new BacktestStrategySignal
                            {
                                StrategyId = strategyId,
                                SymbolName = symbolName,
                                SourceTimeFrame = strategyEvent.SourceTimeFrame,
                                SignalTime = strategyEvent.BarTime
                            }),
                            splitNumber,
                            symbolName,
                            strategyEvent.SourceTimeFrame,
                            canonicalEventName,
                            entry,
                            approvedPendingTp,
                            approvedPendingSl,
                            FormatStrategyRiskLegComment(splitNumber, approvedPendingRiskMoney, finalRiskMoney)));
                    if (pendingResult == null || !pendingResult.IsSuccessful)
                        continue;

                    if (pendingResult.PendingOrder != null)
                    {
                        string modifyError;
                        if (!TryApplyPendingOrderProtection(pendingResult.PendingOrder, symbol, action, approvedPendingSl, approvedPendingTp, out modifyError))
                            continue;
                    }
                    placedPendingCount++;
                }

                if (placedPendingCount > 0)
                    SafePrint("[Strategy] Entry {0} {1} {2} placed {3} split limit leg(s) (n.Trades={4})", strategyId, action, symbolName, placedPendingCount, 1 + placedPendingCount);
            }
            else
            {
                LogStructuredTradeEvent(
                    IsBacktestingRuntime() ? "backtest" : "live",
                    "FAILED",
                    symbolName,
                    action,
                    "MARKET",
                    requestedLots,
                    executionPrice,
                    approvedSl,
                    approvedTp,
                    "",
                    result != null ? Convert.ToString(result.Error, CultureInfo.InvariantCulture) : "null_result");
                SafePrint("[Strategy] Entry failed {0} {1}: {2}", strategyId, symbolName, result != null ? Convert.ToString(result.Error, CultureInfo.InvariantCulture) : "null_result");
            }
        }

        private bool ApplySharedStrategyEntryType(Symbol symbol, string symbolName, BacktestStrategySignal signal, TradeType tradeType, double executionPrice, ref bool useLimitOrder, ref double entryPrice, ref double stopLoss, ref double takeProfit, out string rejectReason)
        {
            var currentEntry = entryPrice;
            var currentStopLoss = stopLoss;
            bool resolvedUseLimit;
            double resolvedEntry;
            var passed = CTraderStrategyEngine.TryApplyEntryType(
                symbol,
                SelectedStrategyEntryType,
                tradeType,
                executionPrice,
                currentEntry,
                currentStopLoss,
                () =>
                {
                    double specialEntry;
                    return TryResolveStrategySpecialEntryPrice(
                        symbol, symbolName, signal, tradeType, executionPrice,
                        currentEntry, currentStopLoss, out specialEntry)
                        ? (double?)specialEntry
                        : null;
                },
                out resolvedUseLimit,
                out resolvedEntry,
                out rejectReason);
            if (passed)
            {
                useLimitOrder = resolvedUseLimit;
                entryPrice = resolvedEntry;
            }
            return passed;
        }

        private bool TryResolveStrategySpecialEntryPrice(
            Symbol symbol,
            string symbolName,
            BacktestStrategySignal signal,
            TradeType tradeType,
            double executionPrice,
            double currentEntry,
            double stopLoss,
            out double entryPrice)
        {
            entryPrice = 0;
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || currentEntry <= 0 || stopLoss <= 0)
                return false;

            switch (SelectedStrategyEntryType)
            {
                case StrategyEntryType.candle_mid:
                    return TryResolveStrategyCandleEntryPrice(symbol, symbolName, signal, tradeType, executionPrice, true, out entryPrice);
                case StrategyEntryType.candle_retest:
                    return TryResolveStrategyCandleEntryPrice(symbol, symbolName, signal, tradeType, executionPrice, false, out entryPrice);
                case StrategyEntryType.ltf_Key_levels:
                case StrategyEntryType.reclaim_retest:
                    return TryResolveStrategyEntryFromLevels(symbol, symbolName, tradeType, executionPrice, stopLoss, GetStrategyLtfProtectionFrames(signal), out entryPrice);
                case StrategyEntryType.HTF_Key_levels:
                    return TryResolveStrategyEntryFromLevels(symbol, symbolName, tradeType, executionPrice, stopLoss, GetStrategyHtfProtectionFrames(signal), out entryPrice);
                case StrategyEntryType.fvg_mid:
                    return TryResolveStrategyZoneMidEntry(symbol, symbolName, signal, tradeType, executionPrice, stopLoss, true, out entryPrice);
                case StrategyEntryType.ob_mid:
                    return TryResolveStrategyZoneMidEntry(symbol, symbolName, signal, tradeType, executionPrice, stopLoss, false, out entryPrice);
                case StrategyEntryType.breakout_close:
                    return false;
                default:
                    return false;
            }
        }

        private bool TryResolveStrategyCandleEntryPrice(Symbol symbol, string symbolName, BacktestStrategySignal signal, TradeType tradeType, double executionPrice, bool midpoint, out double entryPrice)
        {
            entryPrice = 0;
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || signal.SourceTimeFrame == null || executionPrice <= 0)
                return false;

            Bars sourceBars;
            try { sourceBars = GetBarsForCurrentMasterTimer(signal.SourceTimeFrame, symbolName); }
            catch { sourceBars = null; }
            var sourceIndex = ResolveSourceBarIndex(sourceBars, signal.SignalTime);
            if (!IsValidBarIndex(sourceBars, sourceIndex))
                return false;

            return CTraderStrategyEngine.TryResolveCandleEntry(
                symbol, tradeType, executionPrice,
                sourceBars.OpenPrices[sourceIndex],
                sourceBars.HighPrices[sourceIndex],
                sourceBars.LowPrices[sourceIndex],
                midpoint,
                out entryPrice);
        }

        private bool TryResolveStrategyEntryFromLevels(Symbol symbol, string symbolName, TradeType tradeType, double executionPrice, double stopLoss, IEnumerable<TimeFrame> sourceTimeFrames, out double entryPrice)
        {
            entryPrice = 0;
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || executionPrice <= 0 || stopLoss <= 0 || sourceTimeFrames == null)
                return false;

            var levels = new List<ChartLevelCandidate>();
            foreach (var sourceTimeFrame in sourceTimeFrames.Where(tf => tf != null).Distinct())
            {
                try
                {
                    var sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, symbolName);
                    if (sourceBars == null || sourceBars.Count < 5)
                        continue;
                    levels.AddRange(CollectTimeFrameStructuralLevelCandidates(symbol, sourceBars, sourceTimeFrame));
                }
                catch
                {
                }
            }

            return CTraderStrategyEngine.TrySelectWeightedEntryLevel(
                symbol,
                levels.Select(level => new CTraderStrategyLevelCandidate { Price = level.Price, Weight = level.Weight }),
                tradeType,
                executionPrice,
                stopLoss,
                out entryPrice);
        }

        private bool TryResolveStrategyZoneMidEntry(Symbol symbol, string symbolName, BacktestStrategySignal signal, TradeType tradeType, double executionPrice, double stopLoss, bool useFvg, out double entryPrice)
        {
            entryPrice = 0;
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || executionPrice <= 0 || stopLoss <= 0)
                return false;

            var frames = GetStrategyLtfProtectionFrames(signal)
                .Concat(GetStrategyHtfProtectionFrames(signal))
                .Distinct()
                .ToList();
            var candidates = new List<double>();
            foreach (var sourceTimeFrame in frames)
            {
                try
                {
                    var sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, symbolName);
                    if (sourceBars == null || sourceBars.Count < 5)
                        continue;
                    foreach (var zone in BuildStructureSnapshotV2(sourceBars, ResolveWorkingLookbackBars(sourceBars, sourceTimeFrame)).Zones
                        .Where(zone => zone.State != StructureZoneStateV2.Invalidated)
                        .Where(zone => useFvg
                            ? zone.Type == StructureZoneTypeV2.Fvg || zone.Type == StructureZoneTypeV2.InverseFvg
                            : zone.Type == StructureZoneTypeV2.OrderBlock || zone.Type == StructureZoneTypeV2.BreakerBlock)
                        .OrderByDescending(zone => zone.ConfirmationBarIndex)
                        .Take(8))
                    {
                        candidates.Add((zone.Low + zone.High) * 0.5);
                    }
                }
                catch
                {
                }
            }

            return CTraderStrategyEngine.TrySelectEntryLevel(
                symbol, candidates, tradeType, executionPrice, stopLoss, out entryPrice);
        }

        private void EnforceMinimumStrategyRewardRisk(Symbol symbol, TradeType tradeType, double entryPrice, double stopLoss, ref double takeProfit)
        {
            takeProfit = CTraderStrategyEngine.EnforceMinimumRewardRisk(
                symbol, tradeType, entryPrice, stopLoss, takeProfit, StrategyRewardRisk);
        }

        private void ApplyStrategySignalRewardRisk(
            Symbol symbol,
            BacktestStrategySignal signal,
            double entryPrice,
            double stopLoss,
            ref double takeProfit)
        {
            if (SelectedStrategyTakeProfitMode == StrategyTakeProfitMode.No)
            {
                takeProfit = 0;
                return;
            }

            if (!IsStrategyTakeProfitRewardRiskMode())
                return;

            var targetRewardRisk = Math.Max(0.1, ResolveStrategyTakeProfitRewardRisk());
            var multiplier = signal.ConfluenceCount > 0 && signal.ConfluenceRewardRiskMultiplier > 0
                ? signal.ConfluenceRewardRiskMultiplier
                : 1.0;
            takeProfit = CTraderStrategyEngine.ResolveRewardRiskTarget(
                symbol, signal.TradeType, entryPrice, stopLoss, targetRewardRisk, multiplier);
        }

        private string BuildStrategyOrderComment(Symbol symbol, string sid, int legNumber, string symbolName, TimeFrame sourceTimeFrame, string eventName, double entryPrice = 0, double takeProfit = 0, double stopLoss = 0, string riskComment = "", string entryMode = "", bool isLimitOrder = false, int patternToEntryBars = 1, DateTime triggerBarTime = default(DateTime), string protectionComment = "")
        {
            if (sourceTimeFrame == null)
                return "";

            var sb = new StringBuilder();
            // Keep broker comments compact and readable in cTrader:
            // m5.pin.r.h|Now.1-1|l:rs31%(16.31$) 1r|cf:...
            // Internal chain matching lives in the order Label, not in a visible tr:* comment token.
            var eventLabel = string.IsNullOrWhiteSpace(eventName) ? "event" : eventName.Trim();
            eventLabel = eventLabel
                .Replace("↑", "")
                .Replace("↓", "")
                .Replace("!", "")
                .Trim();
            if (string.IsNullOrWhiteSpace(eventLabel))
                eventLabel = "event";
            sb.Append(eventLabel)
                .Append('|')
                .Append(CTraderStrategyEngine.FormatEntryModeLeg(entryMode, legNumber, patternToEntryBars));
            var routeDetails = new List<string>();
            if (!string.IsNullOrWhiteSpace(riskComment))
                routeDetails.Add(riskComment.Trim());
            var rewardRiskComment = BuildStrategyRewardRiskComment(entryPrice, takeProfit, stopLoss);
            if (!string.IsNullOrWhiteSpace(rewardRiskComment))
                routeDetails.Add(rewardRiskComment);
            if (routeDetails.Count > 0)
                sb.Append(isLimitOrder ? "|l:" : "|m:").Append(string.Join(" ", routeDetails));
            var confluenceRoute = BuildStrategyOrderConfluenceComment(symbolName, sourceTimeFrame, entryPrice, stopLoss);
            if (!string.IsNullOrWhiteSpace(confluenceRoute) && confluenceRoute != "-")
                sb.Append("|cf:").Append(confluenceRoute);
            sb.Append('|').Append(BuildStrategyOrderContextComment(symbolName, sourceTimeFrame, entryPrice, stopLoss));
            return sb.ToString();
        }

        private string BuildStrategyRewardRiskComment(double entryPrice, double takeProfit, double stopLoss)
        {
            if (!(entryPrice > 0) || !(takeProfit > 0) || !(stopLoss > 0))
                return "";

            var riskDistance = Math.Abs(entryPrice - stopLoss);
            var rewardDistance = Math.Abs(takeProfit - entryPrice);
            if (!(riskDistance > 0))
                return "";

            return (rewardDistance / riskDistance).ToString("0.##", CultureInfo.InvariantCulture) + "r";
        }

        private string GetStrategyOrderEntryModeComment(BacktestStrategySignal signal)
        {
            if (signal.TradeChainSlot < 1)
                return "Now";
            return ResolveStrategyTradeChainMode(signal.TradeChainSlot).ToString();
        }

        private string BuildStrategyProtectionSourceComment(BacktestStrategySignal signal, double stopLoss = 0, double takeProfit = 0)
        {
            var parts = new List<string>();
            var tpSource = FormatStrategyProtectionCommentCode(signal.TakeProfitSourceCode);
            var slSource = FormatStrategyProtectionCommentCode(signal.StopLossSourceCode);
            if (!string.IsNullOrWhiteSpace(tpSource))
                parts.Add(tpSource);
            if (!string.IsNullOrWhiteSpace(slSource))
                parts.Add(slSource);
            return string.Join("/", parts);
        }

        private string BuildFinalStrategyProtectionSourceComment(
            BacktestStrategySignal signal,
            Symbol symbol,
            double requestedStopLoss,
            double requestedTakeProfit,
            double approvedStopLoss,
            double approvedTakeProfit)
        {
            var finalSignal = signal;
            var tolerance = symbol != null && symbol.PipSize > 0
                ? Math.Max(symbol.PipSize * 0.05, 0.00000001)
                : 0.00000001;
            if (requestedStopLoss > 0 && approvedStopLoss > 0 && Math.Abs(requestedStopLoss - approvedStopLoss) > tolerance)
                finalSignal.StopLossSourceCode = "MS";
            if (requestedTakeProfit > 0 && approvedTakeProfit > 0 && Math.Abs(requestedTakeProfit - approvedTakeProfit) > tolerance)
                finalSignal.TakeProfitSourceCode = "MS";
            return BuildStrategyProtectionSourceComment(finalSignal, approvedStopLoss, approvedTakeProfit);
        }

        private string FormatStrategyProtectionCommentCode(string code)
        {
            var normalized = NormalizeStrategyProtectionSourceCode(code);
            switch (normalized)
            {
                case "CR5": return "5BAR";
                case "CR10": return "10BAR";
                case "CW": return "WICK";
                case "CW15": return "WICK15";
                case "CW2": return "WICK2";
                case "PT": return "PAT";
                case "MS": return "MIN";
                default: return normalized;
            }
        }

        private string NormalizeStrategyProtectionSourceCode(string code)
        {
            var value = string.IsNullOrWhiteSpace(code) ? "" : code.Trim().ToUpperInvariant();
            if (string.IsNullOrWhiteSpace(value))
                return "";
            value = Regex.Replace(value, "[^A-Z0-9]", "");
            return value.Length <= 4 ? value : value.Substring(0, 4);
        }

        private bool IsWaitConfirmAddOnSignal(BacktestStrategySignal signal)
        {
            return signal.TradeChainSlot > 1 &&
                ResolveStrategyTradeChainMode(signal.TradeChainSlot) == StrategyTradeChainMode.Wait_confirm &&
                signal.EntryConfirmationTime != DateTime.MinValue &&
                signal.EntryConfirmationTime != signal.SignalTime;
        }

        private string FormatStrategySignalMinuteToken(DateTime time)
        {
            return time == DateTime.MinValue
                ? "n/a"
                : time.ToString("yyMMddHHmm", CultureInfo.InvariantCulture);
        }

        private void LogWaitConfirmAddOnStage(BacktestStrategySignal signal, string symbolName, string stage, string detail = "")
        {
            var action = signal.TradeType == TradeType.Buy ? "BUY" : "SELL";
            var suffix = string.IsNullOrWhiteSpace(detail) ? "" : " " + detail.Trim();
            PrintAlways(
                "[Strategy] WaitConfirmAdd {0} {1} {2} {3} slot={4} tr={5} cf={6}{7}",
                string.IsNullOrWhiteSpace(stage) ? "INFO" : stage.Trim().ToUpperInvariant(),
                signal.StrategyId,
                action,
                symbolName,
                signal.TradeChainSlot,
                FormatStrategySignalMinuteToken(signal.SignalTime),
                FormatStrategySignalMinuteToken(signal.EntryConfirmationTime),
                suffix);
        }

        private string BuildStrategyTriggerCommentToken(DateTime triggerBarTime)
        {
            return triggerBarTime == DateTime.MinValue
                ? ""
                : "|tr:" + triggerBarTime.ToString("yyMMddHHmm", CultureInfo.InvariantCulture);
        }

        private string BuildStrategyChainSid(string symbolName, TimeFrame sourceTimeFrame, DateTime signalTime)
        {
            var effectiveTime = signalTime == DateTime.MinValue ? Server.Time : signalTime;
            var seed = string.Join(
                "|",
                string.IsNullOrWhiteSpace(symbolName) ? "SYM" : symbolName.Trim().ToUpperInvariant(),
                GetMiniChartLabel(sourceTimeFrame),
                effectiveTime.Ticks.ToString(CultureInfo.InvariantCulture),
                Account != null ? Account.Number.ToString(CultureInfo.InvariantCulture) : "0");
            return BuildStableBase62Token(seed, 4);
        }

        private bool IsNowTradeChainComment(string comment)
        {
            var value = comment ?? "";
            return value.IndexOf("|Now-", StringComparison.OrdinalIgnoreCase) >= 0 ||
                value.IndexOf("|Now.", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private Position FindMatchingNowStrategyPosition(string symbolName, BacktestStrategySignal signal)
        {
            if (string.IsNullOrWhiteSpace(symbolName) || signal.SignalTime == DateTime.MinValue)
                return null;

            var chainSid = BuildStrategyChainSid(symbolName, signal.SourceTimeFrame, signal.SignalTime);
            var expectedLabel = BuildStrategyOrderLabel(signal.StrategyId, chainSid);
            var legacyLabel = BuildStrategyOrderLabel(signal.StrategyId);
            var legacyTriggerToken = BuildStrategyTriggerCommentToken(signal.SignalTime);
            return Positions
                .Where(position => position != null &&
                    string.Equals(position.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase) &&
                    position.TradeType == signal.TradeType &&
                    IsNowTradeChainComment(position.Comment) &&
                    (string.Equals(position.Label ?? "", expectedLabel, StringComparison.OrdinalIgnoreCase) ||
                     (string.Equals(position.Label ?? "", legacyLabel, StringComparison.OrdinalIgnoreCase) &&
                      !string.IsNullOrWhiteSpace(legacyTriggerToken) &&
                      (position.Comment ?? "").IndexOf(legacyTriggerToken, StringComparison.OrdinalIgnoreCase) >= 0)))
                .OrderByDescending(position => position.Id)
                .FirstOrDefault();
        }

        private string FormatStrategyRiskLegComment(int legNumber, double approvedRiskMoney, double baseRiskMoney)
        {
            var percentage = baseRiskMoney > 0
                ? Math.Max(0, approvedRiskMoney) / baseRiskMoney * 100.0
                : 0.0;
            return string.Format(
                CultureInfo.InvariantCulture,
                "rs:{0:0}%({1:0.##}$)",
                percentage,
                Math.Max(0, approvedRiskMoney));
        }

        private string NormalizeStrategyEventName(TimeFrame sourceTimeFrame, string eventName, bool bullish)
        {
            var raw = string.IsNullOrWhiteSpace(eventName) ? "event" : eventName.Trim();
            var effectiveTimeFrame = sourceTimeFrame;
            var legacySeparator = raw.IndexOf('|');
            if (legacySeparator > 0)
            {
                TimeFrame parsedTimeFrame;
                if (TryParseTimeFrameToken(raw.Substring(0, legacySeparator), out parsedTimeFrame))
                    effectiveTimeFrame = parsedTimeFrame;
                raw = raw.Substring(legacySeparator + 1);
            }

            var normalized = new List<string>();
            foreach (var part in raw.Split(new[] { '+' }, StringSplitOptions.RemoveEmptyEntries))
            {
                var value = part.Trim();
                var dotIndex = value.IndexOf('.');
                TimeFrame parsedTimeFrame;
                if (dotIndex > 0 && TryParseTimeFrameToken(value.Substring(0, dotIndex), out parsedTimeFrame))
                    normalized.Add(value.ToLowerInvariant());
                else
                    normalized.Add(BuildCanonicalEventName(effectiveTimeFrame, value, bullish));
            }
            return normalized.Count > 0
                ? string.Join("+", normalized.Distinct(StringComparer.OrdinalIgnoreCase))
                : BuildCanonicalEventName(effectiveTimeFrame, "event", bullish);
        }

        private string BuildStrategyOrderConfluenceComment(string symbolName, TimeFrame sourceTimeFrame, double entryPrice, double stopLoss)
        {
            Bars sourceBars;
            try
            {
                sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, symbolName);
            }
            catch
            {
                sourceBars = null;
            }
            if (sourceBars == null || sourceBars.Count < 3)
                return "-";

            var latestClosedIndex = sourceBars.Count - 2;
            var previous = BuildSharedIndicatorSnapshot(sourceBars, latestClosedIndex - 1);
            var current = BuildSharedIndicatorSnapshot(sourceBars, latestClosedIndex);
            var bullish = entryPrice > 0 && stopLoss > 0 ? (bool?)(stopLoss < entryPrice) : null;
            var labels = new List<string>();
            foreach (var option in GetSelectedStrategyCustomRuleOptions())
            {
                bool matched;
                string evaluatedLabel;
                if (!TryEvaluateStrategyCustomRuleOption(
                    option,
                    symbolName,
                    sourceBars,
                    sourceTimeFrame,
                    latestClosedIndex,
                    previous,
                    current,
                    bullish,
                    out matched,
                    out evaluatedLabel))
                    continue;

                var compact = FormatStrategySelectedConfluenceCommentLabel(
                    option,
                    symbolName,
                    sourceBars,
                    sourceTimeFrame,
                    latestClosedIndex,
                    current,
                    bullish,
                    matched,
                    evaluatedLabel);
                if (!string.IsNullOrWhiteSpace(compact) && !labels.Contains(compact))
                    labels.Add(compact);
            }

            return labels.Count == 0 ? "-" : string.Join("+", labels);
        }

        private string FormatStrategySelectedConfluenceCommentLabel(
            StrategyCustomRuleOption option,
            string symbolName,
            Bars sourceBars,
            TimeFrame sourceTimeFrame,
            int latestClosedIndex,
            SharedIndicatorSnapshot current,
            bool? bullish,
            bool matched,
            string evaluatedLabel)
        {
            var close = sourceBars != null && latestClosedIndex >= 0 && latestClosedIndex < sourceBars.Count
                ? sourceBars.ClosePrices[latestClosedIndex]
                : double.NaN;

            switch (option)
            {
                case StrategyCustomRuleOption.LTF_Confluence:
                    return "LTF" + FormatStrategyCommentBiasArrow(GetStrategyLtfTrendBiasScore(symbolName, sourceTimeFrame));
                case StrategyCustomRuleOption.HTF_Confluence:
                    return "HTF" + FormatStrategyCommentBiasArrow(GetStrategyHtfTrendBiasScore(symbolName, sourceTimeFrame));
                case StrategyCustomRuleOption.H1_Confluence:
                    return "H1" + FormatStrategyCommentBiasArrow(GetStrategySpecificTimeFrameBiasScore(symbolName, TimeFrame.Hour));
                case StrategyCustomRuleOption.H4_Confluence:
                    return "H4" + FormatStrategyCommentBiasArrow(GetStrategySpecificTimeFrameBiasScore(symbolName, TimeFrame.Hour4));
                case StrategyCustomRuleOption.D1_Confluence:
                    return "D1" + FormatStrategyCommentBiasArrow(GetStrategySpecificTimeFrameBiasScore(symbolName, TimeFrame.Daily));
                case StrategyCustomRuleOption.Bar_Confluence:
                    return "BAR" + FormatStrategyCommentBarArrow(sourceBars, latestClosedIndex);
                case StrategyCustomRuleOption.__AnyMomentum:
                    return "MOM" + FormatStrategyCommentAlignment(matched, bullish);
                case StrategyCustomRuleOption.Trend_Confluence:
                    return "TRD" + FormatStrategyCommentAlignment(matched, bullish);
                case StrategyCustomRuleOption._LTF_HTF_Momentum:
                    return "LHM" + FormatStrategyCommentAlignment(matched, bullish);
                case StrategyCustomRuleOption.__AnyPriceLocation:
                    return "PX" + FormatStrategyCommentAlignment(matched, bullish);
                case StrategyCustomRuleOption.__AnyOscillator:
                    return "OSC" + FormatStrategyCommentAlignment(matched, bullish);
                case StrategyCustomRuleOption.EMA_Confluence:
                    return "EMA" + FormatStrategyCommentComparisonArrow(current.EmaFast, current.EmaSlow);
                case StrategyCustomRuleOption.EMA_Price_Confluence:
                    return FormatStrategyCommentComparison("P", close, "EMA", current.EmaMid);
                case StrategyCustomRuleOption.VWAP_Confluence:
                    return FormatStrategyCommentComparison("P", close, "VWAP", current.VwapMain);
                case StrategyCustomRuleOption.Bollinger_Confluence:
                    return FormatStrategyCommentComparison("P", close, "BB", current.BbMid);
                case StrategyCustomRuleOption.RSI_Confluence:
                    return FormatStrategyCommentComparison("RSI", current.RsiMain, "50", 50.0);
                case StrategyCustomRuleOption.RSI_Extreme_Confluence:
                    return FormatStrategyCommentRsiExtreme(current.RsiMain);
                case StrategyCustomRuleOption.__Bullish:
                    return "BUY";
                case StrategyCustomRuleOption.__Bearish:
                    return "SELL";
                case StrategyCustomRuleOption.__Any_Bullish:
                    return "ANY↑" + (matched ? "+" : "-");
                case StrategyCustomRuleOption.__Any_Bearish:
                    return "ANY↓" + (matched ? "+" : "-");
                case StrategyCustomRuleOption.EMA_SmallAboveLong:
                case StrategyCustomRuleOption.EMA_SmallBelowLong:
                    return "EMA" + FormatStrategyCommentComparisonArrow(current.EmaFast, current.EmaSlow);
                case StrategyCustomRuleOption.EMA_PriceAboveMid:
                case StrategyCustomRuleOption.EMA_PriceBelowMid:
                    return FormatStrategyCommentComparison("P", close, "EMA", current.EmaMid);
                case StrategyCustomRuleOption.VWAP_PriceAbove:
                case StrategyCustomRuleOption.VWAP_PriceBelow:
                    return FormatStrategyCommentComparison("P", close, "VWAP", current.VwapMain);
                case StrategyCustomRuleOption.BB_PriceAboveMid:
                case StrategyCustomRuleOption.BB_PriceBelowMid:
                    return FormatStrategyCommentComparison("P", close, "BB", current.BbMid);
                case StrategyCustomRuleOption.RSI_Above50:
                case StrategyCustomRuleOption.RSI_Below50:
                    return FormatStrategyCommentComparison("RSI", current.RsiMain, "50", 50.0);
                case StrategyCustomRuleOption.RSI_Oversold:
                case StrategyCustomRuleOption.RSI_Overbought:
                    return FormatStrategyCommentRsiExtreme(current.RsiMain);
                case StrategyCustomRuleOption.LTF_Bullish:
                case StrategyCustomRuleOption.LTF_Bearish:
                case StrategyCustomRuleOption.LTF_Sideways:
                    return "LTF" + FormatStrategyCommentBiasArrow(GetStrategyLtfTrendBiasScore(symbolName, sourceTimeFrame));
                case StrategyCustomRuleOption.HTF_Bullish:
                case StrategyCustomRuleOption.HTF_Bearish:
                case StrategyCustomRuleOption.HTF_Sideways:
                    return "HTF" + FormatStrategyCommentBiasArrow(GetStrategyHtfTrendBiasScore(symbolName, sourceTimeFrame));
                default:
                    return string.IsNullOrWhiteSpace(evaluatedLabel) ? option.ToString() : evaluatedLabel.Trim();
            }
        }

        private string FormatStrategyCommentAlignment(bool matched, bool? bullish)
        {
            return bullish.HasValue ? (matched ? "+" : "-") : "=";
        }

        private string FormatStrategyCommentBiasArrow(int score)
        {
            if (score >= 2) return "↑";
            if (score <= -2) return "↓";
            return "=";
        }

        private string FormatStrategyCommentComparisonArrow(double left, double right)
        {
            if (!IsFiniteNumber(left) || !IsFiniteNumber(right)) return "=";
            if (left > right) return "↑";
            if (left < right) return "↓";
            return "=";
        }

        private string FormatStrategyCommentComparison(string leftLabel, double leftValue, string rightLabel, double rightValue)
        {
            if (!IsFiniteNumber(leftValue) || !IsFiniteNumber(rightValue))
                return leftLabel + "=" + rightLabel;
            if (leftValue > rightValue)
                return leftLabel + ">" + rightLabel;
            if (leftValue < rightValue)
                return leftLabel + "<" + rightLabel;
            return leftLabel + "=" + rightLabel;
        }

        private string FormatStrategyCommentRsiExtreme(double rsi)
        {
            if (!IsFiniteNumber(rsi)) return "RSI=?";
            if (rsi < 30.0) return "RSI<30";
            if (rsi > 70.0) return "RSI>70";
            return "RSI30-70";
        }

        private string FormatStrategyCommentBarArrow(Bars sourceBars, int latestClosedIndex)
        {
            bool signalBarIsBullish;
            if (TryGetSignalBarDirection(sourceBars, latestClosedIndex, out signalBarIsBullish))
                return signalBarIsBullish ? "↑" : "↓";
            return "=";
        }

        private string BuildStrategyOrderContextComment(string symbolName, TimeFrame sourceTimeFrame, double entryPrice, double stopLoss)
        {
            var bullish = entryPrice > 0 && stopLoss > 0 ? (bool?)(stopLoss < entryPrice) : null;
            var direction = bullish.HasValue ? (bullish.Value ? "b" : "s") : "?";
            var ltfLabel = GetMiniChartLabel(sourceTimeFrame);
            var ltfBias = GetSymbolTrendBiasForTimeFrame(symbolName, sourceTimeFrame);
            var higherTimeFrames = GetBacktestStrategyHigherTimeFrames(sourceTimeFrame).ToList();
            var htfBias = AggregateStrategyTrendBiasScore(symbolName, higherTimeFrames);
            var primaryHtf = higherTimeFrames.FirstOrDefault();

            var ltfEvent = GetLatestStrategyCommentEvent(symbolName, new[] { sourceTimeFrame });
            var htfEvent = GetLatestStrategyCommentEvent(symbolName, higherTimeFrames);
            var htfTech = BuildStrategyCommentHtfTechnicalState(symbolName, primaryHtf);

            return string.Format(
                CultureInfo.InvariantCulture,
                "ltf:{0}.{1}|htf:{2}|bias:{3}{4}/htf{5}|evt:{6}/{7}",
                ltfLabel,
                direction,
                htfTech,
                ltfLabel,
                FormatSignedBias(ltfBias),
                FormatSignedBias(htfBias),
                ltfEvent,
                htfEvent);
        }

        private string BuildStrategyCommentHtfTechnicalState(string symbolName, TimeFrame timeFrame)
        {
            if (timeFrame == null || string.IsNullOrWhiteSpace(symbolName))
                return "-";
            try
            {
                var bars = GetBarsForCurrentMasterTimer(timeFrame, symbolName);
                var index = bars != null ? bars.Count - 2 : -1;
                if (bars == null || index < 0)
                    return GetMiniChartLabel(timeFrame) + ".-";
                var snapshot = BuildSharedIndicatorSnapshot(bars, index);
                var ema = GetStrategyCommentDirection(snapshot.EmaFast, snapshot.EmaSlow);
                var vwap = GetStrategyCommentDirection(bars.ClosePrices[index], snapshot.VwapMain);
                var rsi = GetStrategyCommentDirection(snapshot.RsiMain, 50.0);
                return string.Format(CultureInfo.InvariantCulture, "{0}.ema{1},vwap{2},rsi{3}", GetMiniChartLabel(timeFrame), ema, vwap, rsi);
            }
            catch
            {
                return GetMiniChartLabel(timeFrame) + ".-";
            }
        }

        private string GetStrategyCommentDirection(double left, double right)
        {
            if (!IsFiniteNumber(left) || !IsFiniteNumber(right)) return "=";
            if (left > right) return "↑";
            if (left < right) return "↓";
            return "=";
        }

        private string GetLatestStrategyCommentEvent(string symbolName, IEnumerable<TimeFrame> timeFrames)
        {
            if (timeFrames == null) return "-";
            var events = new List<CanonicalMarketEvent>();
            foreach (var timeFrame in timeFrames.Where(timeFrame => timeFrame != null).Distinct())
                events.AddRange(GetCanonicalEventsForSymbolTimeFrame(symbolName, timeFrame, 24));
            var latest = events
                .OrderByDescending(evt => evt.BarTime)
                .ThenByDescending(evt => evt.Score)
                .FirstOrDefault();
            return latest.BarTime == DateTime.MinValue ? "-" : BuildCanonicalMarketEventName(latest);
        }

        private string FormatSignedBias(int bias)
        {
            return bias > 0
                ? "+" + bias.ToString(CultureInfo.InvariantCulture)
                : bias.ToString(CultureInfo.InvariantCulture);
        }

        // Compact price for the order comment: at most 2 decimals ("0.##").
        private string FormatPriceShort(double price)
        {
            if (!IsFiniteNumber(price) || price <= 0)
                return "0";
            return price.ToString("0.##", CultureInfo.InvariantCulture);
        }

        private DateTime ResolveStrategyTradeGroupBarTime(string symbolName, BacktestStrategySignal signal)
        {
            if (signal.SourceTimeFrame != null && !string.IsNullOrWhiteSpace(symbolName) && signal.SignalTime != DateTime.MinValue)
            {
                try
                {
                    var sourceBars = GetBarsForCurrentMasterTimer(signal.SourceTimeFrame, symbolName);
                    var signalIndex = ResolveSourceBarIndex(sourceBars, signal.SignalTime);
                    if (IsValidBarIndex(sourceBars, signalIndex))
                        return sourceBars.OpenTimes[signalIndex];
                }
                catch
                {
                }
            }

            return signal.SignalTime;
        }

        private DateTime ResolveStrategySignalExecutionTime(string symbolName, BacktestStrategySignal signal)
        {
            var barTime = signal.EntryConfirmationTime != DateTime.MinValue
                ? signal.EntryConfirmationTime
                : signal.SignalTime;
            if (barTime == DateTime.MinValue || signal.SourceTimeFrame == null)
                return Server != null ? Server.Time : DateTime.UtcNow;

            try
            {
                var sourceBars = GetBarsForCurrentMasterTimer(signal.SourceTimeFrame, symbolName);
                return ResolveSourceBarEndTime(sourceBars, barTime, signal.SourceTimeFrame);
            }
            catch
            {
                return ResolveSourceBarEndTime(null, barTime, signal.SourceTimeFrame);
            }
        }

        private bool TryPassFinalStrategyConfluenceGate(string symbolName, BacktestStrategySignal signal, out string rejectReason)
        {
            rejectReason = "";
            var selectedRules = GetSelectedStrategyCustomRuleOptions();
            if (selectedRules.Count == 0)
                return true;
            if (string.IsNullOrWhiteSpace(symbolName) || signal.SourceTimeFrame == null)
            {
                rejectReason = "confluence_context_missing";
                return false;
            }

            Bars sourceBars;
            try { sourceBars = GetBarsForCurrentMasterTimer(signal.SourceTimeFrame, symbolName); }
            catch { sourceBars = null; }
            if (sourceBars == null || sourceBars.Count < 3)
            {
                rejectReason = "confluence_bars_missing";
                return false;
            }

            var confluenceTime = signal.EntryConfirmationTime != DateTime.MinValue
                ? signal.EntryConfirmationTime
                : signal.SignalTime;
            var confluenceIndex = ResolveSourceBarIndex(sourceBars, confluenceTime);
            if (!IsValidBarIndex(sourceBars, confluenceIndex) || confluenceIndex > sourceBars.Count - 2)
            {
                rejectReason = "confluence_bar_not_closed_or_missing";
                return false;
            }

            var previousSnapshot = BuildSharedIndicatorSnapshot(sourceBars, Math.Max(0, confluenceIndex - 1));
            var currentSnapshot = BuildSharedIndicatorSnapshot(sourceBars, confluenceIndex);
            var requireBullishDirection = signal.TradeType == TradeType.Buy;
            foreach (var rule in selectedRules)
            {
                bool matches;
                string shortLabel;
                if (!TryEvaluateStrategyCustomRuleOption(
                    rule,
                    symbolName,
                    sourceBars,
                    signal.SourceTimeFrame,
                    confluenceIndex,
                    previousSnapshot,
                    currentSnapshot,
                    requireBullishDirection,
                    out matches,
                    out shortLabel) || !matches)
                {
                    rejectReason = string.Format(
                        CultureInfo.InvariantCulture,
                        "confluence_failed rule={0}; {1}",
                        rule,
                        DescribeStrategyCustomRuleRequirement(
                            rule,
                            symbolName,
                            sourceBars,
                            signal.SourceTimeFrame,
                            confluenceIndex,
                            currentSnapshot,
                            requireBullishDirection));
                    return false;
                }
            }

            return true;
        }

        private bool IsStrategySignalTimeAlignedToSourceBar(string symbolName, BacktestStrategySignal signal)
        {
            if (string.IsNullOrWhiteSpace(symbolName) || signal.SourceTimeFrame == null || signal.SignalTime == DateTime.MinValue)
                return false;

            try
            {
                var sourceBars = GetBarsForCurrentMasterTimer(signal.SourceTimeFrame, symbolName);
                var signalIndex = ResolveSourceBarIndex(sourceBars, signal.SignalTime);
                return IsValidBarIndex(sourceBars, signalIndex) &&
                    sourceBars.OpenTimes[signalIndex].Ticks == signal.SignalTime.Ticks;
            }
            catch
            {
                return false;
            }
        }

        private string BuildStrategyTradeGroupKey(string symbolName, BacktestStrategySignal signal)
        {
            var groupBarTime = ResolveStrategyTradeGroupBarTime(symbolName, signal);
            return string.Format(
                CultureInfo.InvariantCulture,
                "GROUP|{0}|{1}|{2}|{3}|{4}",
                signal.StrategyId ?? "CUSTOM",
                string.IsNullOrWhiteSpace(symbolName) ? "" : symbolName.Trim().ToUpperInvariant(),
                signal.SourceTimeFrame,
                Math.Max(1, signal.TradeChainSlot),
                groupBarTime.Ticks);
        }

        private string BuildCompactStrategySid(string symbolName, TimeFrame sourceTimeFrame, DateTime signalTime, int tradeChainSlot)
        {
            var effectiveTime = signalTime == DateTime.MinValue ? Server.Time : signalTime;
            var seed = string.Join(
                "|",
                string.IsNullOrWhiteSpace(symbolName) ? "SYM" : symbolName.Trim().ToUpperInvariant(),
                GetMiniChartLabel(sourceTimeFrame),
                effectiveTime.Ticks.ToString(CultureInfo.InvariantCulture),
                Math.Max(1, tradeChainSlot).ToString(CultureInfo.InvariantCulture),
                Account != null ? Account.Number.ToString(CultureInfo.InvariantCulture) : "0");
            return BuildStableBase62Token(seed, 4);
        }

        private static string BuildStableBase62Token(string seed, int length)
        {
            const string alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
            var tokenLength = Math.Max(1, length);

            // FNV-1a is deterministic across cBot restarts, unlike string.GetHashCode().
            ulong hash = 14695981039346656037UL;
            foreach (var character in seed ?? "")
            {
                hash ^= character;
                hash *= 1099511628211UL;
            }

            var chars = new char[tokenLength];
            for (var i = tokenLength - 1; i >= 0; i--)
            {
                chars[i] = alphabet[(int)(hash % (ulong)alphabet.Length)];
                hash /= (ulong)alphabet.Length;
            }
            return new string(chars);
        }

        private string BuildEntryBarSignalKey(string symbolName, BacktestStrategySignal signal)
        {
            return string.Format(
                CultureInfo.InvariantCulture,
                "ENTRYBAR|{0}|{1}|{2}|{3}|{4}|{5}",
                signal.StrategyId ?? "CUSTOM",
                string.IsNullOrWhiteSpace(symbolName) ? "" : symbolName.Trim().ToUpperInvariant(),
                signal.SourceTimeFrame,
                signal.TradeType,
                Math.Max(1, signal.TradeChainSlot),
                signal.SignalTime.Ticks);
        }

        private string BuildWaitConfirmTravelKey(string symbolName, BacktestStrategySignal signal)
        {
            return string.Format(
                CultureInfo.InvariantCulture,
                "WAITDONE|{0}|{1}|{2}|{3}|{4}|{5}",
                signal.StrategyId ?? "CUSTOM",
                string.IsNullOrWhiteSpace(symbolName) ? "" : symbolName.Trim().ToUpperInvariant(),
                signal.SourceTimeFrame,
                signal.TradeType,
                Math.Max(1, signal.TradeChainSlot),
                signal.SignalTime.Ticks);
        }

        private static bool IsWaitConfirmTerminalKey(string value)
        {
            return !string.IsNullOrWhiteSpace(value) &&
                (value.StartsWith("ENTRYBAR|", StringComparison.OrdinalIgnoreCase) ||
                 value.StartsWith("WAITDONE|", StringComparison.OrdinalIgnoreCase));
        }

        private string SerializeStrategyQueueNumber(double value)
        {
            return IsFiniteNumber(value)
                ? value.ToString("R", CultureInfo.InvariantCulture)
                : "null";
        }

        private string SerializeStrategyQueueNumbers(IEnumerable<double> values)
        {
            return "[" + string.Join(",", (values ?? Enumerable.Empty<double>()).Where(IsFiniteNumber).Select(SerializeStrategyQueueNumber)) + "]";
        }

        // This robot is declared with TimeZone = UTC. Bars still arrive without a reliable
        // DateTimeKind, so queue matching retains their raw clock exactly and treats it as UTC.
        // 42trade can then render that one UTC instant in any selected display timezone.
        private DateTime NormalizeQueueBarClock(DateTime value)
        {
            return value == DateTime.MinValue
                ? DateTime.MinValue
                : DateTime.SpecifyKind(value, DateTimeKind.Unspecified);
        }

        private DateTime ConvertQueueBarClockToUtc(DateTime barClock)
        {
            if (barClock == DateTime.MinValue)
                return DateTime.MinValue;
            return NormalizeBotTimeToUtc(barClock);
        }

        private bool TryReadQueueTriggerBarClock(Dictionary<string, object> action, out DateTime triggerBarClock)
        {
            triggerBarClock = DateTime.MinValue;
            if (action == null)
                return false;

            var rawClock = ConvertToInvariantString(GetDictionaryValue(action, "trigger_bar_open_time"));
            DateTime parsed;
            if (!string.IsNullOrWhiteSpace(rawClock) &&
                DateTime.TryParse(rawClock, CultureInfo.InvariantCulture, DateTimeStyles.AllowWhiteSpaces, out parsed))
            {
                triggerBarClock = NormalizeQueueBarClock(parsed);
                return true;
            }

            // Legacy rows only have trigger_time. Their clock is also UTC because the robot
            // runs in UTC; remove the kind for exact Bars.OpenTimes tick matching.
            var legacy = ConvertToInvariantString(GetDictionaryValue(action, "trigger_time"));
            if (!DateTime.TryParse(legacy, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out parsed))
                return false;
            triggerBarClock = NormalizeQueueBarClock(parsed);
            return true;
        }

        private string BuildPendingStrategyQueueActionJson(string actionId, PendingStrategyEntry pending)
        {
            var signal = pending.Signal;
            var triggerBarClock = NormalizeQueueBarClock(signal.SignalTime);
            var triggerUtc = ConvertQueueBarClockToUtc(triggerBarClock);
            var detectedUtc = pending.DetectedAt == DateTime.MinValue
                ? DateTime.UtcNow
                : NormalizeBotTimeToUtc(pending.DetectedAt);
            return "{"
                + "\"action_id\":\"" + EscapeJson(actionId) + "\""
                + ",\"action_type\":\"trade.open\""
                + ",\"status\":\"WAITING\""
                + ",\"symbol\":\"" + EscapeJson(pending.SymbolName) + "\""
                + ",\"side\":\"" + (signal.TradeType == TradeType.Buy ? "BUY" : "SELL") + "\""
                + ",\"tf\":\"" + EscapeJson(GetTimeFrameShortLabel(signal.SourceTimeFrame)) + "\""
                + ",\"trigger_time\":\"" + triggerUtc.ToString("O", CultureInfo.InvariantCulture) + "\""
                + ",\"trigger_bar_open_time\":\"" + triggerBarClock.ToString("yyyy-MM-ddTHH:mm:ss.fffffff", CultureInfo.InvariantCulture) + "\""
                + ",\"trigger_bar_clock_timezone\":\"UTC\""
                + ",\"detected_at\":\"" + detectedUtc.ToString("O", CultureInfo.InvariantCulture) + "\""
                + ",\"trade_chain_slot\":" + Math.Max(1, signal.TradeChainSlot).ToString(CultureInfo.InvariantCulture)
                + ",\"trade_chain_mode\":\"" + (pending.EntryBarMode == StrategyEntryBarMode.First_bar_same_trend ? StrategyTradeChainMode.Wait_confirm.ToString() : StrategyTradeChainMode.Now.ToString()) + "\""
                + ",\"entry_bar_mode\":\"" + pending.EntryBarMode + "\""
                + ",\"pattern_to_entry_bars\":" + Math.Max(1, signal.PatternToEntryBars).ToString(CultureInfo.InvariantCulture)
                + ",\"original_entry_reference\":" + SerializeStrategyQueueNumber(signal.OriginalEntryReference)
                + ",\"original_risk_distance\":" + SerializeStrategyQueueNumber(signal.OriginalRiskDistance)
                + ",\"original_invalidation_price\":" + SerializeStrategyQueueNumber(signal.OriginalInvalidationPrice)
                + ",\"strategy_id\":\"" + EscapeJson(signal.StrategyId) + "\""
                + ",\"strategy_mode\":\"" + signal.StrategyMode + "\""
                + ",\"source_label\":\"" + EscapeJson(signal.SourceLabel) + "\""
                + ",\"require_htf_bias\":" + (pending.RequireHtfBiasConfluence ? "true" : "false")
                + ",\"use_limit_order\":" + (signal.UseLimitOrder ? "true" : "false")
                + ",\"entry\":" + SerializeStrategyQueueNumber(signal.EntryPrice)
                + ",\"secondary_entry\":" + SerializeStrategyQueueNumber(signal.SecondaryEntryPrice)
                + ",\"sl\":" + SerializeStrategyQueueNumber(signal.StopLoss)
                + ",\"tp\":" + SerializeStrategyQueueNumber(signal.TakeProfit)
                + ",\"sl_source\":\"" + EscapeJson(signal.StopLossSourceCode) + "\""
                + ",\"tp_source\":\"" + EscapeJson(signal.TakeProfitSourceCode) + "\""
                + ",\"pattern_low\":" + SerializeStrategyQueueNumber(signal.OriginalPatternLow)
                + ",\"pattern_high\":" + SerializeStrategyQueueNumber(signal.OriginalPatternHigh)
                + ",\"zone_low\":" + SerializeStrategyQueueNumber(signal.RelatedZoneLow)
                + ",\"zone_high\":" + SerializeStrategyQueueNumber(signal.RelatedZoneHigh)
                + ",\"event_sl_distance\":" + SerializeStrategyQueueNumber(signal.EventSlDistance)
                + ",\"split_entries\":" + SerializeStrategyQueueNumbers(signal.PreferredSplitEntries)
                + ",\"related_stop_levels\":" + SerializeStrategyQueueNumbers(signal.RelatedStopLevels)
                + ",\"note\":\"" + EscapeJson(signal.Note) + "\""
                + ",\"confluence_score\":" + signal.ConfluenceScore.ToString(CultureInfo.InvariantCulture)
                + ",\"confluence_count\":" + signal.ConfluenceCount.ToString(CultureInfo.InvariantCulture)
                + ",\"confluence_rr_multiplier\":" + SerializeStrategyQueueNumber(signal.ConfluenceRewardRiskMultiplier)
                + ",\"confluence_volume_multiplier\":" + SerializeStrategyQueueNumber(signal.ConfluenceVolumeMultiplier)
                + ",\"confluence_detail\":\"" + EscapeJson(signal.ConfluenceDetail) + "\""
                + "}";
        }

        private string GetWaitConfirmQueueFilePath()
        {
            var accountId = Account != null
                ? Account.Number.ToString(CultureInfo.InvariantCulture)
                : "unknown";
            return Path.Combine(
                GetBaseServerRootPath(),
                "data",
                "runtime",
                "ctrader",
                SafePathPart(accountId, "unknown"),
                WaitConfirmQueueFileName);
        }

        private string BuildWaitConfirmQueuePersistenceJson()
        {
            var actions = _pendingStrategyEntries
                .Where(item => !_releasedEntryBarSignalKeys.Contains(item.Key))
                .Select(item => BuildPendingStrategyQueueActionJson(item.Key, item.Value));
            var terminalIds = _releasedEntryBarSignalKeys
                // Version-1 ENTRYBAR terminals include confirmations consumed before broker
                // execution. Do not carry them into the stateless success-only journal.
                .Where(value => value.StartsWith("WAITDONE|", StringComparison.OrdinalIgnoreCase))
                .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                .Select(value => "\"" + EscapeJson(value) + "\"");
            return "{"
                + "\"version\":\"" + WaitConfirmQueueVersion + "\""
                + ",\"saved_at\":\"" + DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture) + "\""
                + ",\"queue_actions\":[" + string.Join(",", actions) + "]"
                + ",\"queue_terminal_action_ids\":[" + string.Join(",", terminalIds) + "]"
                + "}";
        }

        private void PersistWaitConfirmQueueLocal()
        {
            if (IsBacktestingRuntime())
                return;
            try
            {
                var filePath = GetWaitConfirmQueueFilePath();
                WriteAnalysisCacheFile(filePath, new[] { BuildWaitConfirmQueuePersistenceJson() });
            }
            catch (Exception ex)
            {
                SafePrint("[WaitConfirm] Local persistence failed: {0}", ex.Message);
            }
        }

        private void LoadWaitConfirmQueueLocal()
        {
            if (IsBacktestingRuntime())
                return;
            try
            {
                var filePath = GetWaitConfirmQueueFilePath();
                if (!System.IO.File.Exists(filePath))
                    return;
                var json = System.IO.File.ReadAllText(filePath);
                ProcessServerQueueActions(json, false, true);
                PersistWaitConfirmQueueLocal();
            }
            catch (Exception ex)
            {
                SafePrint("[WaitConfirm] Local restore failed: {0}", ex.Message);
            }
        }

        private string BuildStrategyQueueActionsSyncJson()
        {
            var actions = new List<string>();
            var included = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var item in _pendingStrategyEntries)
            {
                if (!_strategyQueueTerminalUpdates.ContainsKey(item.Key) && included.Add(item.Key))
                    actions.Add(BuildPendingStrategyQueueActionJson(item.Key, item.Value));
            }
            foreach (var watcher in BuildSharedPositionActionWatchers())
            {
                if (_strategyQueueTerminalUpdates.ContainsKey(watcher.Key) || !included.Add(watcher.Key))
                    continue;
                actions.Add(BuildPositionActionQueueJson(watcher));
            }
            foreach (var terminal in _strategyQueueTerminalUpdates)
            {
                actions.Add("{\"action_id\":\"" + EscapeJson(terminal.Key) + "\",\"status\":\"" + EscapeJson(terminal.Value) + "\"}");
            }
            return "[" + string.Join(",", actions) + "]";
        }

        private string BuildPositionActionQueueJson(SharedPositionActionWatcher watcher)
        {
            var position = watcher.Position;
            return "{"
                + "\"action_id\":\"" + EscapeJson(watcher.Key) + "\""
                + ",\"action_type\":\"position.close\""
                + ",\"status\":\"WAITING\""
                + ",\"symbol\":\"" + EscapeJson(position.SymbolName) + "\""
                + ",\"side\":\"" + (position.TradeType == TradeType.Buy ? "BUY" : "SELL") + "\""
                + ",\"tf\":\"" + EscapeJson(GetTimeFrameShortLabel(watcher.TimeFrame)) + "\""
                + ",\"trigger_time\":\"" + position.EntryTime.ToString("O", CultureInfo.InvariantCulture) + "\""
                + ",\"strategy_id\":\"" + EscapeJson(watcher.StrategyId) + "\""
                + ",\"source_label\":\"" + EscapeJson(watcher.DefinitionId) + "\""
                + ",\"position_id\":" + position.Id.ToString(CultureInfo.InvariantCulture)
                + ",\"entry\":" + SerializeStrategyQueueNumber(position.EntryPrice)
                + ",\"sl\":" + (position.StopLoss.HasValue ? SerializeStrategyQueueNumber(position.StopLoss.Value) : "null")
                + ",\"tp\":" + (position.TakeProfit.HasValue ? SerializeStrategyQueueNumber(position.TakeProfit.Value) : "null")
                + ",\"note\":\"" + EscapeJson(watcher.ActionName) + "\""
                + "}";
        }

        private List<double> ReadStrategyQueueNumberList(object raw)
        {
            var values = raw as List<object>;
            return values == null
                ? new List<double>()
                : values.Select(ToSharedRuleNumber).Where(IsFiniteNumber).ToList();
        }

        private void ProcessServerQueueActions(string json, bool reconcile = false, bool localSnapshot = false)
        {
            if (string.IsNullOrWhiteSpace(json) || json.IndexOf("\"queue_actions\"", StringComparison.OrdinalIgnoreCase) < 0)
                return;
            Dictionary<string, object> root;
            try { root = CTraderRuleEngine.ParseJson(json) as Dictionary<string, object>; }
            catch { root = null; }
            if (localSnapshot && root != null &&
                !string.Equals(ConvertToInvariantString(GetDictionaryValue(root, "version")), WaitConfirmQueueVersion, StringComparison.Ordinal))
            {
                SafePrint("[WaitConfirm] Ignored unsupported local queue version");
                return;
            }
            var actions = root != null ? GetDictionaryValue(root, "queue_actions") as List<object> : null;
            if (actions == null)
                return;
            if (!localSnapshot)
                _strategyQueueHydratedFromServer = true;
            var localStateChanged = false;

            var terminalIds = GetDictionaryValue(root, "queue_terminal_action_ids") as List<object>;
            if (terminalIds != null)
            {
                foreach (var rawTerminalId in terminalIds)
                {
                    var terminalId = ConvertToInvariantString(rawTerminalId);
                    if (string.IsNullOrWhiteSpace(terminalId))
                        continue;
                    if (_pendingStrategyEntries.Remove(terminalId))
                        localStateChanged = true;
                    if (IsWaitConfirmTerminalKey(terminalId) &&
                        _releasedEntryBarSignalKeys.Add(terminalId))
                        localStateChanged = true;
                    _suppressedPositionActionQueueKeys.Add(terminalId);
                }
            }

            var restored = 0;
            var updated = 0;
            var serverActionIds = new HashSet<string>(StringComparer.Ordinal);
            foreach (var rawAction in actions)
            {
                Dictionary<string, object> action;
                if (!TryGetRuleObject(rawAction, out action))
                    continue;
                var actionId = ConvertToInvariantString(GetDictionaryValue(action, "action_id"));
                var status = ConvertToInvariantString(GetDictionaryValue(action, "status"));
                if (string.IsNullOrWhiteSpace(actionId) || !string.Equals(status, "WAITING", StringComparison.OrdinalIgnoreCase))
                    continue;
                serverActionIds.Add(actionId);
                var actionType = ConvertToInvariantString(GetDictionaryValue(action, "action_type"));
                // Wait_confirm is evaluated statelessly from each newly closed bar. Migrate
                // legacy durable trade-entry waiters out of the shared queue; keeping them
                // would leave stale WAITING rows that can never own the new execution flow.
                if (string.Equals(actionType, "trade.open", StringComparison.OrdinalIgnoreCase))
                {
                    if (_pendingStrategyEntries.Remove(actionId))
                        localStateChanged = true;
                    _strategyQueueTerminalUpdates[actionId] = "CANCELLED";
                    _suppressedPositionActionQueueKeys.Add(actionId);
                    continue;
                }
                if (!string.IsNullOrWhiteSpace(actionType) && !string.Equals(actionType, "trade.open", StringComparison.OrdinalIgnoreCase))
                    continue;
                var alreadyPending = _pendingStrategyEntries.ContainsKey(actionId);
                if (alreadyPending || _releasedEntryBarSignalKeys.Contains(actionId) || _strategyQueueTerminalUpdates.ContainsKey(actionId))
                    continue;

                TimeFrame sourceTimeFrame;
                TradeType tradeType;
                BacktestStrategyMode strategyMode;
                DateTime signalTime;
                DateTime detectedAt;
                if (!TryParseTimeFrameToken(ConvertToInvariantString(GetDictionaryValue(action, "tf")), out sourceTimeFrame) ||
                    !Enum.TryParse(ConvertToInvariantString(GetDictionaryValue(action, "side")), true, out tradeType) ||
                    !TryReadQueueTriggerBarClock(action, out signalTime))
                {
                    _strategyQueueTerminalUpdates[actionId] = "CANCELLED";
                    _releasedEntryBarSignalKeys.Add(actionId);
                    SafePrint("[ActionQueue] Cancelled malformed action: action_id={0}", actionId);
                    continue;
                }
                if (!DateTime.TryParse(ConvertToInvariantString(GetDictionaryValue(action, "detected_at")), CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out detectedAt) &&
                    !DateTime.TryParse(ConvertToInvariantString(GetDictionaryValue(action, "created_at")), CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out detectedAt))
                    detectedAt = DateTime.UtcNow;
                else
                    detectedAt = NormalizeBotTimeToUtc(detectedAt);
                if (!Enum.TryParse(ConvertToInvariantString(GetDictionaryValue(action, "strategy_mode")), true, out strategyMode))
                    strategyMode = BacktestStrategyMode.CustomTrade;
                StrategyEntryBarMode entryBarMode;
                if (!Enum.TryParse(ConvertToInvariantString(GetDictionaryValue(action, "entry_bar_mode")), true, out entryBarMode))
                    entryBarMode = StrategyEntryBarMode.First_bar_after_trigger;
                var tradeChainSlot = (int)Math.Round(ToSharedRuleNumber(GetDictionaryValue(action, "trade_chain_slot")));
                if (tradeChainSlot < 1 || tradeChainSlot > 3)
                    tradeChainSlot = 1;

                var signal = new BacktestStrategySignal
                {
                    IsValid = true,
                    StrategyId = ConvertToInvariantString(GetDictionaryValue(action, "strategy_id")),
                    StrategyMode = strategyMode,
                    SymbolName = ConvertToInvariantString(GetDictionaryValue(action, "symbol")),
                    SourceLabel = ConvertToInvariantString(GetDictionaryValue(action, "source_label")),
                    TradeType = tradeType,
                    SourceTimeFrame = sourceTimeFrame,
                    SignalTime = signalTime,
                    PatternToEntryBars = Math.Max(1, (int)Math.Round(ToSharedRuleNumber(GetDictionaryValue(action, "pattern_to_entry_bars")))),
                    OriginalEntryReference = ToSharedRuleNumber(GetDictionaryValue(action, "original_entry_reference")),
                    OriginalRiskDistance = ToSharedRuleNumber(GetDictionaryValue(action, "original_risk_distance")),
                    OriginalInvalidationPrice = ToSharedRuleNumber(GetDictionaryValue(action, "original_invalidation_price")),
                    TradeChainSlot = tradeChainSlot,
                    UseLimitOrder = SharedRuleTruthy(GetDictionaryValue(action, "use_limit_order")),
                    EntryPrice = ToSharedRuleNumber(GetDictionaryValue(action, "entry")),
                    SecondaryEntryPrice = ToSharedRuleNumber(GetDictionaryValue(action, "secondary_entry")),
                    StopLoss = ToSharedRuleNumber(GetDictionaryValue(action, "sl")),
                    TakeProfit = ToSharedRuleNumber(GetDictionaryValue(action, "tp")),
                    StopLossSourceCode = ConvertToInvariantString(GetDictionaryValue(action, "sl_source")),
                    TakeProfitSourceCode = ConvertToInvariantString(GetDictionaryValue(action, "tp_source")),
                    OriginalPatternLow = ToSharedRuleNumber(GetDictionaryValue(action, "pattern_low")),
                    OriginalPatternHigh = ToSharedRuleNumber(GetDictionaryValue(action, "pattern_high")),
                    RelatedZoneLow = ToSharedRuleNumber(GetDictionaryValue(action, "zone_low")),
                    RelatedZoneHigh = ToSharedRuleNumber(GetDictionaryValue(action, "zone_high")),
                    EventSlDistance = ToSharedRuleNumber(GetDictionaryValue(action, "event_sl_distance")),
                    PreferredSplitEntries = ReadStrategyQueueNumberList(GetDictionaryValue(action, "split_entries")),
                    RelatedStopLevels = ReadStrategyQueueNumberList(GetDictionaryValue(action, "related_stop_levels")),
                    Note = ConvertToInvariantString(GetDictionaryValue(action, "note")),
                    ConfluenceScore = (int)Math.Round(ToSharedRuleNumber(GetDictionaryValue(action, "confluence_score"))),
                    ConfluenceCount = (int)Math.Round(ToSharedRuleNumber(GetDictionaryValue(action, "confluence_count"))),
                    ConfluenceRewardRiskMultiplier = ToSharedRuleNumber(GetDictionaryValue(action, "confluence_rr_multiplier")),
                    ConfluenceVolumeMultiplier = ToSharedRuleNumber(GetDictionaryValue(action, "confluence_volume_multiplier")),
                    ConfluenceDetail = ConvertToInvariantString(GetDictionaryValue(action, "confluence_detail"))
                };
                var symbolName = string.IsNullOrWhiteSpace(signal.SymbolName) ? Symbol.Name : signal.SymbolName;
                if (!(signal.OriginalEntryReference > 0) || !(signal.OriginalRiskDistance > 0) || !(signal.OriginalInvalidationPrice > 0))
                    InitializeWaitConfirmReference(symbolName, sourceTimeFrame, ref signal);
                if (!IsStrategySignalTimeAlignedToSourceBar(symbolName, signal))
                {
                    _strategyQueueTerminalUpdates[actionId] = "CANCELLED";
                    _releasedEntryBarSignalKeys.Add(actionId);
                    SafePrint(
                        "[ActionQueue] Cancelled invalid trigger: action_id={0}, symbol={1}, tf={2}, trigger={3:O}",
                        actionId,
                        symbolName,
                        GetMiniChartLabel(signal.SourceTimeFrame),
                        signal.SignalTime);
                    continue;
                }
                _pendingStrategyEntries[actionId] = new PendingStrategyEntry
                {
                    SymbolName = symbolName,
                    Signal = signal,
                    DetectedAt = detectedAt,
                    RequireHtfBiasConfluence = SharedRuleTruthy(GetDictionaryValue(action, "require_htf_bias")),
                    EntryBarMode = entryBarMode
                };
                localStateChanged = true;
                if (alreadyPending) updated++; else restored++;
            }
            // Local disk is authoritative. A temporary server omission must never delete a
            // valid Wait_confirm action and recreate the restart-loss bug this queue replaces.
            var removed = 0;
            if (restored > 0 || updated > 0 || removed > 0)
                SafePrint(
                    localSnapshot
                        ? "[WaitConfirm] Restored locally: restored={0}, updated={1}, removed={2}"
                        : "[ActionQueue] Synced from 42trade: restored={0}, updated={1}, removed={2}",
                    restored,
                    updated,
                    removed);
            var syncState = string.Format(
                CultureInfo.InvariantCulture,
                "hydrated={0}; server_waiting={1}; local_waiting={2}; terminal_updates={3}",
                _strategyQueueHydratedFromServer,
                actions.Count,
                _pendingStrategyEntries.Count,
                _strategyQueueTerminalUpdates.Count);
            if (!string.Equals(syncState, _lastStrategyQueueSyncState, StringComparison.Ordinal))
            {
                _lastStrategyQueueSyncState = syncState;
                SafePrint("[ActionQueue] Sync state: {0}", syncState);
            }
            if (!localSnapshot && localStateChanged)
                PersistWaitConfirmQueueLocal();
        }

        private bool TryResolveStrategyEntryBar(
            string symbolName,
            TimeFrame sourceTimeFrame,
            DateTime triggerTime,
            TradeType tradeType,
            StrategyEntryBarMode entryBarMode,
            out DateTime entryBarTime)
        {
            entryBarTime = DateTime.MinValue;
            if (entryBarMode == StrategyEntryBarMode.First_bar_after_trigger)
                return true;
            if (string.IsNullOrWhiteSpace(symbolName) || sourceTimeFrame == null || triggerTime == DateTime.MinValue)
                return false;

            Bars sourceBars;
            try
            {
                sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, symbolName);
            }
            catch
            {
                sourceBars = null;
            }
            if (sourceBars == null || sourceBars.Count < 3)
                return false;

            var triggerIndex = ResolveSourceBarIndex(sourceBars, triggerTime);
            var latestClosedIndex = sourceBars.Count - 2;
            if (triggerIndex < 0 || triggerIndex >= latestClosedIndex)
                return false;

            var wantsBullishBar = tradeType == TradeType.Buy;
            if (entryBarMode == StrategyEntryBarMode.First_bar_reverse_trend)
                wantsBullishBar = !wantsBullishBar;

            for (var index = triggerIndex + 1; index <= latestClosedIndex; index++)
            {
                var open = sourceBars.OpenPrices[index];
                var close = sourceBars.ClosePrices[index];
                if (close == open)
                    continue;
                if ((close > open) != wantsBullishBar)
                    continue;

                entryBarTime = sourceBars.OpenTimes[index];
                return true;
            }

            return false;
        }

        private bool IsStrategyEntryConfirmationFresh(string symbolName, TimeFrame sourceTimeFrame, DateTime entryBarTime)
        {
            if (IsBacktestingRuntime())
                return true;
            if (string.IsNullOrWhiteSpace(symbolName) || sourceTimeFrame == null || entryBarTime == DateTime.MinValue)
                return false;

            try
            {
                var sourceBars = GetBarsForCurrentMasterTimer(sourceTimeFrame, symbolName);
                if (sourceBars == null || sourceBars.Count < 3)
                    return false;
                var entryIndex = ResolveSourceBarIndex(sourceBars, entryBarTime);
                var latestClosedIndex = sourceBars.Count - 2;
                if (entryIndex != latestClosedIndex || sourceBars.OpenTimes[entryIndex].Ticks != entryBarTime.Ticks)
                    return false;

                // Do not compare a broker bar clock with Server.Time: that clock can be stale
                // until the chart receives a tick. Freshness is the deterministic bar distance
                // from the latest completed source bar instead.
                var barsBehindLatest = latestClosedIndex - entryIndex;
                var timeFrameSeconds = Math.Max(1, TimeFrameToMinutes(sourceTimeFrame)) * 60.0;
                var schedulerCoverageBars = (int)Math.Ceiling(Math.Max(5, StrategyScanSeconds) / timeFrameSeconds) + 1;
                var maxAcceptedLagBars = Math.Max(1, schedulerCoverageBars);
                return barsBehindLatest >= 0 && barsBehindLatest <= maxAcceptedLagBars;
            }
            catch
            {
                return false;
            }
        }

        private StrategyTradeChainMode ResolveStrategyTradeChainMode(int tradeChainSlot)
        {
            switch (tradeChainSlot)
            {
                case 1: return FirstTradeMode;
                case 2: return SecondTradeMode;
                case 3: return ThirdTradeMode;
                default: return StrategyTradeChainMode.No;
            }
        }

        private StrategyEntryBarMode ResolveStrategyTradeChainEntryBarMode(int tradeChainSlot)
        {
            return ResolveStrategyTradeChainMode(tradeChainSlot) == StrategyTradeChainMode.Wait_confirm
                ? StrategyEntryBarMode.First_bar_same_trend
                : StrategyEntryBarMode.First_bar_after_trigger;
        }

        private bool TryEvaluateWaitConfirm(
            string symbolName,
            ref BacktestStrategySignal signal,
            out CTraderWaitConfirmDecision decision,
            out Bars sourceBars,
            out int triggerIndex)
        {
            decision = null;
            sourceBars = null;
            triggerIndex = -1;
            try { sourceBars = GetBarsForCurrentMasterTimer(signal.SourceTimeFrame, symbolName); }
            catch { sourceBars = null; }
            if (sourceBars == null || sourceBars.Count < 3)
                return false;

            triggerIndex = ResolveSourceBarIndex(sourceBars, signal.SignalTime);
            var latestClosedIndex = sourceBars.Count - 2;
            if (!IsValidBarIndex(sourceBars, triggerIndex) || triggerIndex >= latestClosedIndex)
                return false;

            if (!(signal.OriginalEntryReference > 0) || !(signal.OriginalRiskDistance > 0) || !(signal.OriginalInvalidationPrice > 0))
                InitializeWaitConfirmReference(symbolName, signal.SourceTimeFrame, ref signal);

            var maxBars = Math.Max(1, WaitConfirmMaxBars);
            var evaluationEndIndex = Math.Min(latestClosedIndex, triggerIndex + maxBars + 1);
            var count = evaluationEndIndex - triggerIndex + 1;
            var opens = new double[count];
            var closes = new double[count];
            for (var offset = 0; offset < count; offset++)
            {
                opens[offset] = sourceBars.OpenPrices[triggerIndex + offset];
                closes[offset] = sourceBars.ClosePrices[triggerIndex + offset];
            }

            decision = _waitConfirmQueueEngine.Evaluate(
                opens,
                closes,
                signal.TradeType == TradeType.Buy,
                signal.OriginalEntryReference,
                signal.OriginalRiskDistance,
                signal.OriginalInvalidationPrice,
                maxBars,
                WaitConfirmRequirePullback == YesNoMode.Yes,
                WaitConfirmMaxChaseR,
                WaitConfirmMaxRiskMultiplier,
                WaitConfirmInvalidateOnClose == YesNoMode.Yes);
            return decision != null;
        }

        private bool TryResolveWaitConfirmEvaluationGapTerminal(
            string symbolName,
            BacktestStrategySignal signal,
            out CTraderWaitConfirmDecision decision)
        {
            decision = null;
            Bars sourceBars;
            try { sourceBars = GetBarsForCurrentMasterTimer(signal.SourceTimeFrame, symbolName); }
            catch { sourceBars = null; }
            if (sourceBars == null || sourceBars.Count < 3)
                return false;

            var latestClosedIndex = sourceBars.Count - 2;
            var triggerIndex = ResolveSourceBarIndex(sourceBars, signal.SignalTime);
            var maxBars = Math.Max(1, WaitConfirmMaxBars);
            if (IsValidBarIndex(sourceBars, triggerIndex))
            {
                var ageBars = latestClosedIndex - triggerIndex;
                if (ageBars > maxBars + 1)
                {
                    decision = new CTraderWaitConfirmDecision
                    {
                        Kind = CTraderWaitConfirmDecisionKind.Expire,
                        AgeBars = Math.Max(0, ageBars),
                        Reason = "max_bars_reached_unconfirmed"
                    };
                    return true;
                }
                return false;
            }

            var firstOpenTime = sourceBars.OpenTimes[0];
            var lastClosedTime = latestClosedIndex >= 0 ? sourceBars.OpenTimes[latestClosedIndex] : DateTime.MinValue;
            var timeFrameMinutes = Math.Max(1, TimeFrameToMinutes(signal.SourceTimeFrame));
            if (signal.SignalTime != DateTime.MinValue &&
                (signal.SignalTime < firstOpenTime || lastClosedTime >= signal.SignalTime.AddMinutes(timeFrameMinutes * (maxBars + 2))))
            {
                decision = new CTraderWaitConfirmDecision
                {
                    Kind = CTraderWaitConfirmDecisionKind.Expire,
                    AgeBars = maxBars,
                    Reason = "trigger_bar_unavailable"
                };
                return true;
            }

            return false;
        }

        private void FinalizeWaitConfirmQueueEntry(string key, string status)
        {
            _pendingStrategyEntries.Remove(key);
            _releasedEntryBarSignalKeys.Add(key);
            _strategyQueueTerminalUpdates[key] = status;
            // WAITDONE keys are written only after the broker volume mutation succeeds.
            // Legacy ENTRYBAR keys may still reach this method during migration cleanup.
            PersistWaitConfirmQueueLocal();
        }

        private bool TryValidateFinalWaitConfirmRisk(
            BacktestStrategySignal signal,
            double finalEntry,
            double finalStopLoss,
            out string reason)
        {
            reason = "";
            if (signal.EntryConfirmationTime == DateTime.MinValue || signal.EntryConfirmationTime == signal.SignalTime)
                return true;
            if (!(signal.OriginalEntryReference > 0) || !(signal.OriginalRiskDistance > 0) || !(finalEntry > 0) || !(finalStopLoss > 0))
            {
                reason = "wait_confirm_final_reference_invalid";
                return false;
            }

            var isBuy = signal.TradeType == TradeType.Buy;
            var decision = _waitConfirmQueueEngine.EvaluateFinalRisk(
                isBuy,
                signal.OriginalEntryReference,
                signal.OriginalRiskDistance,
                finalEntry,
                finalStopLoss,
                WaitConfirmMaxChaseR,
                WaitConfirmMaxRiskMultiplier);
            if (decision.Kind == CTraderWaitConfirmDecisionKind.Cancel)
            {
                reason = string.Format(
                    CultureInfo.InvariantCulture,
                    "wait_confirm_final_{0} chase_r={1:0.###}/{2:0.###} risk_x={3:0.###}/{4:0.###}",
                    decision.Reason,
                    decision.ChaseR,
                    WaitConfirmMaxChaseR,
                    decision.RiskMultiplier,
                    WaitConfirmMaxRiskMultiplier);
                return false;
            }
            return true;
        }

        private bool TryPassStrategyEntryBarGate(string symbolName, ref BacktestStrategySignal signal, bool requireHtfBiasConfluence)
        {
            // Stateless lookback already validated this closed confirmation bar. It must not
            // be re-enqueued by the legacy entry-bar gate.
            if (!string.IsNullOrWhiteSpace(signal.WaitConfirmActionKey) &&
                signal.EntryConfirmationTime != DateTime.MinValue &&
                signal.EntryConfirmationTime != signal.SignalTime)
                return true;

            // Signals explicitly stamped with their trigger bar as confirmation (Now) proceed
            // directly. Wait_confirm keeps the immutable original trigger in the pending queue.
            if (signal.EntryConfirmationTime != DateTime.MinValue && signal.EntryConfirmationTime == signal.SignalTime)
                return true;

            var key = BuildEntryBarSignalKey(symbolName, signal);
            PendingStrategyEntry existingPending;
            var entryBarMode = _pendingStrategyEntries.TryGetValue(key, out existingPending)
                ? existingPending.EntryBarMode
                : ResolveStrategyTradeChainEntryBarMode(signal.TradeChainSlot);
            if (existingPending != null)
                signal = existingPending.Signal;
            if (entryBarMode == StrategyEntryBarMode.First_bar_after_trigger)
            {
                signal.EntryConfirmationTime = signal.SignalTime;
                return true;
            }

            if (_releasedEntryBarSignalKeys.Contains(key))
                return false;

            CTraderWaitConfirmDecision decision;
            Bars sourceBars;
            int triggerIndex;
            var evaluated = TryEvaluateWaitConfirm(symbolName, ref signal, out decision, out sourceBars, out triggerIndex);
            if (!evaluated && existingPending != null && TryResolveWaitConfirmEvaluationGapTerminal(symbolName, signal, out decision))
                evaluated = true;
            if (!evaluated || decision.Kind == CTraderWaitConfirmDecisionKind.Waiting)
            {
                if (existingPending != null)
                    existingPending.Signal = signal;
                if (!_pendingStrategyEntries.ContainsKey(key))
                {
                    var detectedAt = DateTime.UtcNow;
                    _pendingStrategyEntries[key] = new PendingStrategyEntry
                    {
                        SymbolName = symbolName,
                        Signal = signal,
                        DetectedAt = detectedAt,
                        RequireHtfBiasConfluence = requireHtfBiasConfluence,
                        EntryBarMode = entryBarMode
                    };
                    PersistWaitConfirmQueueLocal();
                    SafePrint(
                        "[WaitConfirm] WAITING symbol={0} side={1} trigger={2:yyyy-MM-dd HH:mm} detected={3:yyyy-MM-dd HH:mm:ss} tf={4} max_bars={5} pullback={6} chase_max_r={7:0.##} risk_max_x={8:0.##}",
                        symbolName,
                        signal.TradeType,
                        signal.SignalTime,
                        detectedAt,
                        GetMiniChartLabel(signal.SourceTimeFrame),
                        WaitConfirmMaxBars,
                        WaitConfirmRequirePullback,
                        WaitConfirmMaxChaseR,
                        WaitConfirmMaxRiskMultiplier);
                }
                return false;
            }

            if (decision.Kind != CTraderWaitConfirmDecisionKind.Confirm)
            {
                var terminalStatus = decision.Kind == CTraderWaitConfirmDecisionKind.Expire ? "EXPIRED" : "CANCELLED";
                FinalizeWaitConfirmQueueEntry(key, terminalStatus);
                SafePrint(
                    "[WaitConfirm] {0} symbol={1} side={2} trigger={3:yyyy-MM-dd HH:mm} tf={4} age_bars={5} reason={6} pullback={7} chase_r={8:0.###}/{9:0.###} risk_x={10:0.###}/{11:0.###}",
                    terminalStatus,
                    symbolName,
                    signal.TradeType,
                    signal.SignalTime,
                    GetMiniChartLabel(signal.SourceTimeFrame),
                    decision.AgeBars,
                    decision.Reason,
                    decision.PullbackSeen,
                    decision.ChaseR,
                    WaitConfirmMaxChaseR,
                    decision.RiskMultiplier,
                    WaitConfirmMaxRiskMultiplier);
                return false;
            }

            var confirmationIndex = triggerIndex + decision.ConfirmationOffset;
            if (!IsValidBarIndex(sourceBars, confirmationIndex))
                return false;
            var entryBarTime = sourceBars.OpenTimes[confirmationIndex];
            FinalizeWaitConfirmQueueEntry(key, "RELEASED");
            signal.EntryConfirmationTime = entryBarTime;
            signal.EntryPrice = sourceBars.ClosePrices[confirmationIndex];
            signal.EventSlDistance = Math.Max(
                signal.EventSlDistance,
                Math.Max(0, sourceBars.HighPrices[confirmationIndex] - sourceBars.LowPrices[confirmationIndex]));
            signal.PatternToEntryBars = CTraderStrategyEngine.ResolvePatternToEntryBars(triggerIndex, confirmationIndex);
            ApplyStrategyConfluenceSizing(symbolName, signal.SourceTimeFrame, ref signal);
            SafePrint(
                "[WaitConfirm] RELEASED symbol={0} side={1} trigger={2:yyyy-MM-dd HH:mm} entry_bar={3:yyyy-MM-dd HH:mm} bars={4} pullback={5} chase_r={6:0.###} risk_x={7:0.###}",
                symbolName,
                signal.TradeType,
                signal.SignalTime,
                entryBarTime,
                signal.PatternToEntryBars,
                decision.PullbackSeen,
                decision.ChaseR,
                decision.RiskMultiplier);
            return true;
        }

        private void ProcessPendingStrategyEntries(string symbolName, TimeFrame sourceTimeFrame)
        {
            var pending = _pendingStrategyEntries
                // Each pending signal resolves against its own stored timeframe. Requiring it
                // to equal the execution target strands HTF signals queued from an LTF target.
                .Where(item => string.Equals(item.Value.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase))
                .Select(item => item.Value)
                .ToList();
            foreach (var item in pending)
                ExecuteBacktestStrategySignal(item.SymbolName, item.Signal, item.RequireHtfBiasConfluence);
        }

        private void ProcessAllPendingStrategyEntries()
        {
            var pending = _pendingStrategyEntries.Values.ToList();
            foreach (var item in pending)
                ExecuteBacktestStrategySignal(item.SymbolName, item.Signal, item.RequireHtfBiasConfluence);
        }

        private void RebuildConfirmedEntryProtection(
            Symbol symbol,
            string symbolName,
            BacktestStrategySignal signal,
            double entryPrice,
            ref double stopLoss,
            ref double takeProfit)
        {
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || signal.SourceTimeFrame == null || !(entryPrice > 0))
                return;

            Bars sourceBars;
            try
            {
                sourceBars = GetBarsForCurrentMasterTimer(signal.SourceTimeFrame, symbolName);
            }
            catch
            {
                sourceBars = null;
            }
            var confirmationIndex = ResolveSourceBarIndex(sourceBars, signal.EntryConfirmationTime);
            if (!IsValidBarIndex(sourceBars, confirmationIndex))
                return;

            var isBuy = signal.TradeType == TradeType.Buy;
            var candidates = new List<Tuple<string, double>>();
            AddConfirmedStopCandidate(candidates, "confirm", isBuy ? sourceBars.LowPrices[confirmationIndex] : sourceBars.HighPrices[confirmationIndex], entryPrice, isBuy);

            var contextStart = Math.Max(0, confirmationIndex - 10);
            var contextEnd = Math.Max(contextStart, confirmationIndex - 1);
            if (contextEnd >= contextStart)
            {
                var contextPrice = isBuy
                    ? sourceBars.LowPrices.Skip(contextStart).Take(contextEnd - contextStart + 1).Min()
                    : sourceBars.HighPrices.Skip(contextStart).Take(contextEnd - contextStart + 1).Max();
                AddConfirmedStopCandidate(candidates, "prev10", contextPrice, entryPrice, isBuy);
            }

            var patternPrice = isBuy ? signal.OriginalPatternLow : signal.OriginalPatternHigh;
            if (patternPrice > 0)
                AddConfirmedStopCandidate(candidates, "pattern", patternPrice, entryPrice, isBuy);
            else
                AddConfirmedStopCandidate(candidates, "original_sl", stopLoss, entryPrice, isBuy);

            foreach (var level in signal.RelatedStopLevels ?? new List<double>())
                AddConfirmedStopCandidate(candidates, "event_level", level, entryPrice, isBuy);

            if (signal.RelatedZoneHigh > signal.RelatedZoneLow && signal.RelatedZoneLow > 0)
            {
                AddConfirmedStopCandidate(candidates, "event_zone_mid", (signal.RelatedZoneLow + signal.RelatedZoneHigh) * 0.5, entryPrice, isBuy);
                AddConfirmedStopCandidate(candidates, "event_zone_edge", isBuy ? signal.RelatedZoneLow : signal.RelatedZoneHigh, entryPrice, isBuy);
            }

            var triggerIndex = ResolveSourceBarIndex(sourceBars, signal.SignalTime);
            var reactionLow = sourceBars.LowPrices[confirmationIndex];
            var reactionHigh = sourceBars.HighPrices[confirmationIndex];
            if (IsValidBarIndex(sourceBars, triggerIndex))
            {
                reactionLow = Math.Min(reactionLow, sourceBars.LowPrices[triggerIndex]);
                reactionHigh = Math.Max(reactionHigh, sourceBars.HighPrices[triggerIndex]);
            }
            var tolerance = Math.Max(symbol.PipSize * 2.0, 0.0000001);
            foreach (var level in CollectTimeFrameStructuralLevelCandidates(symbol, sourceBars, signal.SourceTimeFrame))
            {
                if (level.Price < reactionLow - tolerance || level.Price > reactionHigh + tolerance)
                    continue;
                AddConfirmedStopCandidate(candidates, "related_key", level.Price, entryPrice, isBuy);
                if (level.ZoneHigh > level.ZoneLow && level.ZoneLow > 0)
                {
                    AddConfirmedStopCandidate(candidates, "related_zone_mid", (level.ZoneLow + level.ZoneHigh) * 0.5, entryPrice, isBuy);
                    AddConfirmedStopCandidate(candidates, "related_zone_edge", isBuy ? level.ZoneLow : level.ZoneHigh, entryPrice, isBuy);
                }
            }

            if (candidates.Count == 0)
                return;

            var selected = isBuy
                ? candidates.OrderBy(item => item.Item2).First()
                : candidates.OrderByDescending(item => item.Item2).First();
            stopLoss = NormalizePriceToSymbol(symbol, selected.Item2);
            var riskDistance = Math.Abs(entryPrice - stopLoss);
            if (!(riskDistance > 0))
                return;

            var rewardRisk = Math.Max(0.1, StrategyRewardRisk);
            takeProfit = NormalizePriceToSymbol(
                symbol,
                isBuy ? entryPrice + riskDistance * rewardRisk : entryPrice - riskDistance * rewardRisk);
            SafePrint(
                "[Strategy] Confirmed SL: {0} {1} entry={2:F5} sl={3:F5} source={4} candidates=[{5}]",
                symbolName,
                signal.TradeType,
                entryPrice,
                stopLoss,
                selected.Item1,
                string.Join(",", candidates.Select(item => item.Item1 + ":" + FormatPriceShort(item.Item2))));
        }

        private static void AddConfirmedStopCandidate(List<Tuple<string, double>> candidates, string source, double price, double entryPrice, bool isBuy)
        {
            if (candidates == null || double.IsNaN(price) || double.IsInfinity(price) || !(price > 0) || !(entryPrice > 0))
                return;
            if (isBuy ? price >= entryPrice : price <= entryPrice)
                return;
            if (candidates.Any(item => Math.Abs(item.Item2 - price) <= 0.0000001))
                return;
            candidates.Add(Tuple.Create(source ?? "level", price));
        }

        private void ExecuteBacktestStrategySignal(string symbolName, BacktestStrategySignal signal, bool requireHtfBiasConfluence)
        {
            if (signal.TradeChainSlot > 0)
            {
                ExecuteBacktestStrategySignalStage(symbolName, signal, requireHtfBiasConfluence);
                return;
            }

            for (var tradeChainSlot = 1; tradeChainSlot <= 3; tradeChainSlot++)
            {
                var tradeChainMode = ResolveStrategyTradeChainMode(tradeChainSlot);
                // Wait_confirm is built independently from each newly closed bar by the
                // stateless lookback matcher below. Original events create Now legs only.
                if (tradeChainMode != StrategyTradeChainMode.Now)
                    continue;
                var stagedSignal = signal;
                stagedSignal.TradeChainSlot = tradeChainSlot;
                stagedSignal.PatternToEntryBars = 1;
                ExecuteBacktestStrategySignalStage(symbolName, stagedSignal, requireHtfBiasConfluence);
            }
        }

        private void ExecuteBacktestStrategySignalStage(string symbolName, BacktestStrategySignal signal, bool requireHtfBiasConfluence)
        {
            if (!string.IsNullOrWhiteSpace(signal.SymbolName))
                symbolName = signal.SymbolName;

            if (!signal.IsValid || string.IsNullOrWhiteSpace(symbolName))
                return;

            signal.SourceLabel = NormalizeStrategyEventName(
                signal.SourceTimeFrame,
                signal.SourceLabel,
                signal.TradeType == TradeType.Buy);

            if (!IsBacktestingRuntime() && !IsStrategySignalTimeAlignedToSourceBar(symbolName, signal))
            {
                LogStrategyReject(signal.StrategyId, symbolName, "trigger_not_exact_source_bar");
                return;
            }

            if (!TryPassStrategyEntryBarGate(symbolName, ref signal, requireHtfBiasConfluence))
                return;

            var waitConfirmAddOnReleased = IsWaitConfirmAddOnSignal(signal);
            if (waitConfirmAddOnReleased)
                LogWaitConfirmAddOnStage(signal, symbolName, "MATCHED", "final_gates=pending");

            string finalConfluenceRejectReason;
            if (!TryPassFinalStrategyConfluenceGate(symbolName, signal, out finalConfluenceRejectReason))
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=" + finalConfluenceRejectReason);
                LogStrategyReject(signal.StrategyId, symbolName, finalConfluenceRejectReason);
                return;
            }

            var strategyEntryTime = ResolveStrategySignalExecutionTime(symbolName, signal);
            if (!ShouldAllowStrategySignalTime(strategyEntryTime))
            {
                var blockReason = GetStrategyTradingTimeBlockReason(strategyEntryTime);
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=" + blockReason);
                LogStrategySkip(signal.StrategyId, symbolName, blockReason);
                return;
            }

            var volumeGateBarTime = signal.EntryConfirmationTime != DateTime.MinValue
                ? signal.EntryConfirmationTime
                : signal.SignalTime;
            if (!HasStrategyBarVolumeSurge(symbolName, signal.SourceTimeFrame, volumeGateBarTime))
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=vol_surge_miss");
                LogStrategySkip(signal.StrategyId, symbolName, "vol_surge_miss");
                return;
            }

            // One strategy idea per completed source-timeframe bar. Entry price and order type
            // can change while lower-timeframe host bars keep checking the same 4H idea; they
            // must not create another trade group.
            var eventKey = BuildStrategyTradeGroupKey(symbolName, signal);
            if (_backtestStrategyHandledEventKeys.Contains(eventKey))
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=duplicate_group");
                SafePrint("[Strategy] Duplicate group skipped: {0}", eventKey);
                return;
            }

            var wantBullish = signal.TradeType == TradeType.Buy;
            if (requireHtfBiasConfluence)
            {
                string confluenceReason;
                if (!TryGetBacktestBiasConfluence(symbolName, wantBullish, out confluenceReason))
                {
                    if (waitConfirmAddOnReleased)
                        LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=" + confluenceReason);
                    LogStrategySkip(signal.StrategyId, symbolName, confluenceReason);
                    _backtestStrategyHandledEventKeys.Add(eventKey);
                    return;
                }
            }

            string positionCapRejectReason;
            // Wait_confirm modifies its matching Now position; it does not create another
            // position and therefore must not be rejected by the new-position count cap.
            if (!waitConfirmAddOnReleased &&
                !TryPassStrategyPositionCaps(symbolName, signal.TradeType, out positionCapRejectReason))
            {
                LogStrategyReject(signal.StrategyId, symbolName, positionCapRejectReason);
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            var symbol = ResolveLoadedSymbol(symbolName);
            if (symbol == null)
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=symbol_not_loaded");
                return;
            }

            var action = signal.TradeType == TradeType.Buy ? "BUY" : "SELL";
            var executionPrice = signal.TradeType == TradeType.Buy ? symbol.Ask : symbol.Bid;
            if (!IsFiniteNumber(executionPrice) || executionPrice <= 0)
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=invalid_execution_price");
                return;
            }

            var tradableRejectReason = DetectSymbolTradeAvailabilityReason(symbol);
            if (!string.IsNullOrWhiteSpace(tradableRejectReason))
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=" + tradableRejectReason);
                LogStrategyReject(signal.StrategyId, symbolName, DescribeTradeAvailabilityReason(tradableRejectReason, symbolName));
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            var referencePrice = signal.EntryPrice > 0
                ? NormalizePriceToSymbol(symbol, signal.EntryPrice)
                : executionPrice;
            if (signal.UseLimitOrder)
            {
                if (signal.TradeType == TradeType.Buy && referencePrice >= executionPrice)
                {
                    if (waitConfirmAddOnReleased)
                        LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=buy_limit_not_below_market");
                    LogStrategyReject(signal.StrategyId, symbolName, "buy_limit_not_below_market");
                    _backtestStrategyHandledEventKeys.Add(eventKey);
                    return;
                }

                if (signal.TradeType == TradeType.Sell && referencePrice <= executionPrice)
                {
                    if (waitConfirmAddOnReleased)
                        LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=sell_limit_not_above_market");
                    LogStrategyReject(signal.StrategyId, symbolName, "sell_limit_not_above_market");
                    _backtestStrategyHandledEventKeys.Add(eventKey);
                    return;
                }
            }

            var profileRaw = GetStrategyProfileRaw(signal.StrategyMode, signal.SourceTimeFrame);
            var sl = signal.StopLoss;
            var tp = signal.TakeProfit;
            if (!(sl > 0) || !(tp > 0))
            {
                if (signal.EventSlDistance > 0)
                {
                    // Default SL = height of the related event (candle / OB / FVG zone), floored at the min stop distance.
                    var slDistance = Math.Max(signal.EventSlDistance, Math.Max(ResolveMinStopPips(symbol) * symbol.PipSize, symbol.PipSize * 2.0));
                    sl = signal.TradeType == TradeType.Buy
                        ? NormalizePriceToSymbol(symbol, referencePrice - slDistance)
                        : NormalizePriceToSymbol(symbol, referencePrice + slDistance);
                    var rewardRisk = Math.Max(0.1, StrategyRewardRisk);
                    tp = signal.TradeType == TradeType.Buy
                        ? NormalizePriceToSymbol(symbol, referencePrice + (slDistance * rewardRisk))
                        : NormalizePriceToSymbol(symbol, referencePrice - (slDistance * rewardRisk));
                }
                else
                {
                    var fallbackProtection = BuildSharedChartProtectionPrices(symbol, symbolName, signal.TradeType, referencePrice, ResolveChartFallbackStopPips(symbol), profileRaw);
                    if (fallbackProtection == null)
                    {
                        if (waitConfirmAddOnReleased)
                            LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=no valid SL/TP from structure");
                        LogStrategySkip(signal.StrategyId, symbolName, "no valid SL/TP from structure");
                        _backtestStrategyHandledEventKeys.Add(eventKey);
                        return;
                    }

                    sl = fallbackProtection.Item1;
                    tp = fallbackProtection.Item2;
                }
            }

            string stopLossSourceCode;
            string takeProfitSourceCode;
            ApplyStrategyProtectionModes(symbol, symbolName, signal, referencePrice, profileRaw, ref sl, ref tp, out stopLossSourceCode, out takeProfitSourceCode);
            signal.StopLossSourceCode = stopLossSourceCode;
            signal.TakeProfitSourceCode = takeProfitSourceCode;
            if (!(sl > 0))
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=missing_stop_loss");
                LogStrategySkip(signal.StrategyId, symbolName, "missing_stop_loss");
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            string protectionReason;
            if (!TryValidateProtectionPrices(symbol, action, referencePrice, sl, tp, out protectionReason))
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=" + protectionReason);
                LogStrategySkip(signal.StrategyId, symbolName, protectionReason);
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            var effectiveUseLimitOrder = signal.UseLimitOrder;
            var effectiveEntryPrice = referencePrice;
            string entryModeRejectReason;
            if (!ApplySharedStrategyEntryType(symbol, symbolName, signal, signal.TradeType, executionPrice, ref effectiveUseLimitOrder, ref effectiveEntryPrice, ref sl, ref tp, out entryModeRejectReason))
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=" + entryModeRejectReason);
                LogStrategyReject(signal.StrategyId, symbolName, entryModeRejectReason);
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }
            if (SelectedStrategyStopLossMode == StrategyStopLossMode.furthest_invalidation &&
                signal.EntryConfirmationTime != DateTime.MinValue &&
                signal.EntryConfirmationTime != signal.SignalTime)
                RebuildConfirmedEntryProtection(symbol, symbolName, signal, effectiveEntryPrice, ref sl, ref tp);
            ApplyStrategyProtectionModes(symbol, symbolName, signal, effectiveEntryPrice, profileRaw, ref sl, ref tp, out stopLossSourceCode, out takeProfitSourceCode);
            signal.StopLossSourceCode = stopLossSourceCode;
            signal.TakeProfitSourceCode = takeProfitSourceCode;
            ApplyStrategySignalRewardRisk(symbol, signal, effectiveEntryPrice, sl, ref tp);
            if (IsStrategyTakeProfitRewardRiskMode())
                signal.TakeProfitSourceCode = "RR";
            string waitConfirmRiskRejectReason;
            if (!TryValidateFinalWaitConfirmRisk(signal, effectiveEntryPrice, sl, out waitConfirmRiskRejectReason))
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=" + waitConfirmRiskRejectReason);
                LogStrategyReject(signal.StrategyId, symbolName, waitConfirmRiskRejectReason);
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }
            if (!(sl > 0))
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=missing_stop_loss");
                LogStrategySkip(signal.StrategyId, symbolName, "missing_stop_loss");
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }
            if (!(tp > 0) &&
                SelectedStrategyTakeProfitMode != StrategyTakeProfitMode.No &&
                SelectedStrategyTakeProfitMode != StrategyTakeProfitMode.trail_only)
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=take_profit_mode_unresolved mode=" + SelectedStrategyTakeProfitMode);
                LogStrategyReject(signal.StrategyId, symbolName, "take_profit_mode_unresolved mode=" + SelectedStrategyTakeProfitMode);
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            if (effectiveUseLimitOrder)
            {
                if (signal.TradeType == TradeType.Buy && effectiveEntryPrice >= executionPrice)
                {
                    if (waitConfirmAddOnReleased)
                        LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=buy_limit_not_below_market");
                    LogStrategyReject(signal.StrategyId, symbolName, "buy_limit_not_below_market");
                    _backtestStrategyHandledEventKeys.Add(eventKey);
                    return;
                }

                if (signal.TradeType == TradeType.Sell && effectiveEntryPrice <= executionPrice)
                {
                    if (waitConfirmAddOnReleased)
                        LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=sell_limit_not_above_market");
                    LogStrategyReject(signal.StrategyId, symbolName, "sell_limit_not_above_market");
                    _backtestStrategyHandledEventKeys.Add(eventKey);
                    return;
                }
            }

            if (!TryValidateProtectionPrices(symbol, action, effectiveEntryPrice, sl, tp, out protectionReason))
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=" + protectionReason);
                LogStrategySkip(signal.StrategyId, symbolName, protectionReason);
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            var configuredRiskPercent = Math.Max(0.0, GetEffectiveMaxRiskPercent());
            var baseRiskMoney = ResolveStrategyRiskMoney(signal.StrategyMode, profileRaw);
            var confidenceVolumeFactor = signal.ConfluenceCount > 0 && signal.ConfluenceVolumeMultiplier > 0
                ? Math.Max(0.05, Math.Min(1.0, signal.ConfluenceVolumeMultiplier))
                : 1.0;
            var finalRiskMoney = baseRiskMoney * confidenceVolumeFactor;
            // n.Trades: 2..5 splits the entry. For limit signals all legs are
            // limits (first at the signal entry, rest split towards the SL); for market signals
            // the first order is market and the rest are limits. The parent setup budget is
            // shared across enabled trade-chain slots and all of their split legs. Auto/1
            // still uses one leg per slot, but does not create a second full-risk budget.
            var orderCountOverride = ResolveStrategyOrderCount();
            var splitEntries = new List<double>();
            var splitWeights = new double[] { 1.0 };
            if (orderCountOverride > 1)
            {
                if (effectiveUseLimitOrder)
                {
                    splitEntries = BuildStrategyEqualSplitEntries(symbol, signal.TradeType, effectiveEntryPrice, sl, orderCountOverride);
                }
                else
                {
                    // The market order is the base leg. The remaining entries are a uniform
                    // ladder toward SL; old candle retracement suggestions do not override it.
                    splitEntries = BuildStrategyEqualSplitEntries(symbol, signal.TradeType, executionPrice, sl, orderCountOverride)
                        .Skip(1)
                        .ToList();
                }
                if (splitEntries.Count == 0 && !effectiveUseLimitOrder)
                {
                    SafePrint(
                        "[StrategySplit] no pending ladder entries: {0} {1} n.Trades={2} entry={3} sl={4}",
                        action,
                        symbolName,
                        orderCountOverride,
                        FormatPriceShort(executionPrice),
                        FormatPriceShort(sl));
                }
            }
            var legsPerSignal = effectiveUseLimitOrder
                ? Math.Max(1, splitEntries.Count)
                : Math.Max(1, 1 + splitEntries.Count);
            splitWeights = BuildStrategyChainRiskWeights(legsPerSignal, signal.TradeChainSlot);
            var hasSplitGroup = splitWeights.Length > 1;
            var firstLegRiskMoney = Math.Max(0, finalRiskMoney * splitWeights[0]);
            var volumeUnits = ResolveChartTradeVolumeForRisk(symbol, signal.TradeType, effectiveEntryPrice, sl, firstLegRiskMoney, symbolName);
            if (volumeUnits < symbol.VolumeInUnitsMin)
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=volume below minimum for risk cap");
                LogStrategySkip(signal.StrategyId, symbolName, "volume below minimum for risk cap");
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            double approvedSl;
            double approvedTp;
            double approvedVolumeUnits;
            double approvedRiskMoney;
            double marginEstimate;
            double marginBudget;
            string gateRejectReason;
            if (!TryPassSharedCreationGate(
                symbol,
                action,
                effectiveUseLimitOrder ? "limit" : "market",
                effectiveUseLimitOrder ? effectiveEntryPrice : 0,
                executionPrice,
                sl,
                tp,
                volumeUnits,
                firstLegRiskMoney,
                firstLegRiskMoney,
                false,
                out approvedSl,
                out approvedTp,
                out approvedVolumeUnits,
                out approvedRiskMoney,
                out marginEstimate,
                out marginBudget,
                out gateRejectReason))
            {
                if (waitConfirmAddOnReleased)
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=" + gateRejectReason);
                LogStrategyReject(signal.StrategyId, symbolName, gateRejectReason);
                if (IsStrictPropRiskTemplate())
                {
                    StopBacktestForPropRuleBreach("ENTRY", symbolName, gateRejectReason);
                    return;
                }
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            var firstLegFactor = splitWeights.Length > 0 ? splitWeights[0] : 1.0;
            var combinedRiskFactor = confidenceVolumeFactor * firstLegFactor;
            var stopDistancePips = symbol.PipSize > 0
                ? Math.Abs(effectiveEntryPrice - approvedSl) / symbol.PipSize
                : 0.0;
            var approvedLots = symbol.VolumeInUnitsToQuantity(approvedVolumeUnits);
            var effectiveRewardRisk = approvedTp > 0
                ? Math.Abs(approvedTp - effectiveEntryPrice) / Math.Max(0.0000001, Math.Abs(effectiveEntryPrice - approvedSl))
                : 0;
            var riskScoreText = signal.ConfluenceCount > 0
                ? FormatSignedBias(signal.ConfluenceScore) + "/" + signal.ConfluenceCount.ToString(CultureInfo.InvariantCulture)
                : "n/a";
            var riskComment = FormatStrategyRiskLegComment(1, approvedRiskMoney, baseRiskMoney);
            var protectionSourceComment = BuildFinalStrategyProtectionSourceComment(
                signal,
                symbol,
                sl,
                tp,
                approvedSl,
                approvedTp);
            // The Comment retains human-readable #1/#2 and SL/TP reasons; the Label carries the
            // compact chain id used for WaitConfirm add-on matching.
            var strategyChainSid = BuildStrategyChainSid(symbolName, signal.SourceTimeFrame, signal.SignalTime);
            var firstOrderLabel = BuildStrategyOrderLabel(signal.StrategyId, strategyChainSid);
            var firstOrderRiskComment = riskComment;
            var riskLogDetail = string.Format(
                CultureInfo.InvariantCulture,
                "risk_score={0};risk_pct={1:0.####};balance={2:0.##};base_risk={3:0.##};confidence_vol_x={4:0.###};split_x={5:0.###};risk_factor={6:0.###};leg_cap={7:0.##};sl_pips={8:0.##};sl_src={9};tp_src={10};requested_units={11:0.##};approved_units={12:0.##};approved_lots={13:0.####};approved_risk={14:0.##};rr={15:0.##};margin={16:0.##}/{17:0.##}",
                riskScoreText,
                configuredRiskPercent,
                Account != null ? Account.Balance : 0.0,
                baseRiskMoney,
                confidenceVolumeFactor,
                firstLegFactor,
                combinedRiskFactor,
                firstLegRiskMoney,
                stopDistancePips,
                NormalizeStrategyProtectionSourceCode(signal.StopLossSourceCode),
                NormalizeStrategyProtectionSourceCode(signal.TakeProfitSourceCode),
                volumeUnits,
                approvedVolumeUnits,
                approvedLots,
                approvedRiskMoney,
                effectiveRewardRisk,
                marginEstimate,
                marginBudget);
            _lastStrategyRiskDashboardText = string.Format(
                CultureInfo.InvariantCulture,
                "score={0} factor={1:0.###} (conf={2:0.###} split={3:0.###}) risk={4:0.##}/{5:0.##} SL={6:0.##}p vol={7:0.####}lot RR={8:0.##}",
                riskScoreText,
                combinedRiskFactor,
                confidenceVolumeFactor,
                firstLegFactor,
                approvedRiskMoney,
                baseRiskMoney,
                stopDistancePips,
                approvedLots,
                effectiveRewardRisk);
            SafePrint("[RiskSizing] {0} {1} {2}: {3}", signal.StrategyId, action, symbolName, riskLogDetail);

            if (!ShouldStrategySubmitOrders())
            {
                SafePrint(
                    "[Strategy] Signal {0} {1} {2} {3} event={4} @ {5:F5} SL={6:F5} TP={7:F5} risk={8:F2}{9}",
                    signal.StrategyId,
                    action,
                    effectiveUseLimitOrder ? "LIMIT" : "MARKET",
                    symbolName,
                    signal.SourceLabel,
                    effectiveEntryPrice,
                    approvedSl,
                    approvedTp,
                    approvedRiskMoney,
                    string.IsNullOrWhiteSpace(signal.Note) ? "" : " " + signal.Note);
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            if (waitConfirmAddOnReleased)
            {
                LogWaitConfirmAddOnStage(
                    signal,
                    symbolName,
                    "APPLY",
                    string.Format(
                        CultureInfo.InvariantCulture,
                        "entry={0} sl={1} tp={2} sl_src={3} tp_src={4} approved_units={5:0.##}",
                        FormatPriceShort(effectiveEntryPrice),
                        FormatPriceShort(approvedSl),
                        FormatPriceShort(approvedTp),
                        NormalizeStrategyProtectionSourceCode(signal.StopLossSourceCode),
                        NormalizeStrategyProtectionSourceCode(signal.TakeProfitSourceCode),
                        approvedVolumeUnits));
                var nowPosition = FindMatchingNowStrategyPosition(symbolName, signal);
                if (nowPosition == null)
                {
                    LogWaitConfirmAddOnStage(signal, symbolName, "MISSING_NOW", "reason=wait_confirm_now_position_missing");
                    LogStrategySkip(signal.StrategyId, symbolName, "wait_confirm_now_position_missing");
                    _backtestStrategyHandledEventKeys.Add(eventKey);
                    return;
                }

                string anchorProtectionError;
                if (!TryEnsureStrategyPositionProtection(nowPosition, symbol, action, approvedSl, approvedTp, out anchorProtectionError))
                {
                    LogWaitConfirmAddOnStage(signal, symbolName, "BLOCKED", "reason=wait_confirm_anchor_protection_failed: " + anchorProtectionError);
                    LogStrategyReject(signal.StrategyId, symbolName, "wait_confirm_anchor_protection_failed: " + anchorProtectionError);
                    _backtestStrategyHandledEventKeys.Add(eventKey);
                    return;
                }

                var requestedTotalVolumeUnits = nowPosition.VolumeInUnits + approvedVolumeUnits;
                if (!double.IsNaN(symbol.VolumeInUnitsMax) && symbol.VolumeInUnitsMax > 0)
                    requestedTotalVolumeUnits = Math.Min(requestedTotalVolumeUnits, symbol.VolumeInUnitsMax);
                var newTotalVolumeUnits = symbol.NormalizeVolumeInUnits(requestedTotalVolumeUnits, RoundingMode.Down);
                if (newTotalVolumeUnits <= nowPosition.VolumeInUnits)
                {
                    LogWaitConfirmAddOnStage(
                        signal,
                        symbolName,
                        "TOO_SMALL",
                        string.Format(
                            CultureInfo.InvariantCulture,
                            "reason=wait_confirm_add_volume_below_step current={0:0.##} requested_total={1:0.##} normalized_total={2:0.##}",
                            nowPosition.VolumeInUnits,
                            requestedTotalVolumeUnits,
                            newTotalVolumeUnits));
                    LogStrategySkip(signal.StrategyId, symbolName, "wait_confirm_add_volume_below_step");
                    _backtestStrategyHandledEventKeys.Add(eventKey);
                    return;
                }

                var addedVolumeUnits = newTotalVolumeUnits - nowPosition.VolumeInUnits;
                var addedLots = symbol.VolumeInUnitsToQuantity(addedVolumeUnits);
                LogStructuredTradeEvent(
                    IsBacktestingRuntime() ? "backtest" : "live",
                    "SUBMIT",
                    symbolName,
                    action,
                    "MARKET_ADD",
                    addedLots,
                    effectiveEntryPrice,
                    approvedSl,
                    approvedTp,
                    nowPosition.Id.ToString(CultureInfo.InvariantCulture),
                    signal.StrategyId + ":" + signal.SourceLabel + ";" + riskLogDetail);

                var addResult = ModifyPositionVolumeCompat(nowPosition, newTotalVolumeUnits);
                if (addResult != null && addResult.IsSuccessful)
                {
                    // The broker volume mutation is the irreversible success boundary. Persist
                    // idempotency only now—never when the confirmation is merely detected.
                    if (!string.IsNullOrWhiteSpace(signal.WaitConfirmActionKey))
                        FinalizeWaitConfirmQueueEntry(signal.WaitConfirmActionKey, "RELEASED");

                    var updatedPosition = addResult.Position ?? nowPosition;
                    string addonProtectionError;
                    if (!TryEnsureStrategyPositionProtection(updatedPosition, symbol, action, approvedSl, approvedTp, out addonProtectionError))
                    {
                        LogStructuredTradeEvent(
                            IsBacktestingRuntime() ? "backtest" : "live",
                            "FAILED",
                            symbolName,
                            action,
                            "MARKET_ADD",
                            addedLots,
                            updatedPosition.EntryPrice,
                            approvedSl,
                            approvedTp,
                            updatedPosition.Id.ToString(CultureInfo.InvariantCulture),
                            "wait_confirm_addon_protection_failed: " + addonProtectionError);
                        LogWaitConfirmAddOnStage(signal, symbolName, "FAILED", "reason=wait_confirm_addon_protection_failed: " + addonProtectionError);
                        SafePrint("[Strategy] WaitConfirm add-on protection failed {0} {1} #{2}: {3}", signal.StrategyId, symbolName, updatedPosition.Id, addonProtectionError);
                        _backtestStrategyHandledEventKeys.Add(eventKey);
                        return;
                    }

                    TryApplySelectedExitModeForPosition(updatedPosition);
                    LogStructuredTradeEvent(
                        IsBacktestingRuntime() ? "backtest" : "live",
                        "SUCCEEDED",
                        symbolName,
                        action,
                        "MARKET_ADD",
                        addedLots,
                        updatedPosition.EntryPrice,
                        approvedSl,
                        approvedTp,
                        updatedPosition.Id.ToString(CultureInfo.InvariantCulture),
                        signal.StrategyId + ":" + signal.SourceLabel + ";" + riskLogDetail);
                    SafePrint(
                        "[Strategy] WaitConfirm add-on {0} {1} {2} #{3} added={4:F2} total={5:F2} risk={6:F2} {7}",
                        signal.StrategyId,
                        action,
                        symbolName,
                        updatedPosition.Id,
                        addedVolumeUnits,
                        newTotalVolumeUnits,
                        approvedRiskMoney,
                        riskLogDetail);
                    LogWaitConfirmAddOnStage(
                        signal,
                        symbolName,
                        "OK",
                        string.Format(
                            CultureInfo.InvariantCulture,
                            "#{0} added={1:0.##} total={2:0.##} lots={3:0.####} risk={4:0.##}",
                            updatedPosition.Id,
                            addedVolumeUnits,
                            newTotalVolumeUnits,
                            addedLots,
                            approvedRiskMoney));
                    AddCustomTradeTriggerMarker(symbolName, signal);
                    _backtestStrategyHandledEventKeys.Add(eventKey);
                    return;
                }

                LogStructuredTradeEvent(
                    IsBacktestingRuntime() ? "backtest" : "live",
                    "FAILED",
                    symbolName,
                    action,
                    "MARKET_ADD",
                    addedLots,
                    effectiveEntryPrice,
                    approvedSl,
                    approvedTp,
                    nowPosition.Id.ToString(CultureInfo.InvariantCulture),
                    addResult != null ? Convert.ToString(addResult.Error, CultureInfo.InvariantCulture) : "null_result");
                LogWaitConfirmAddOnStage(signal, symbolName, "FAILED", "reason=" + (addResult != null ? Convert.ToString(addResult.Error, CultureInfo.InvariantCulture) : "null_result"));
                SafePrint("[Strategy] WaitConfirm add-on failed {0} {1} #{2}: {3}", signal.StrategyId, symbolName, nowPosition.Id, addResult != null ? Convert.ToString(addResult.Error, CultureInfo.InvariantCulture) : "null_result");
                _backtestStrategyHandledEventKeys.Add(eventKey);
                return;
            }

            var previousPositionIds = CaptureOpenPositionIds();
            TradeResult result = null;
            if (effectiveUseLimitOrder)
            {
                var slPips = CTraderExecutionEngine.ResolveDistancePips(symbol, effectiveEntryPrice, approvedSl).GetValueOrDefault();
                double? tpPips = CTraderExecutionEngine.ResolveDistancePips(symbol, effectiveEntryPrice, approvedTp);
                var requestedLots = symbol.VolumeInUnitsToQuantity(approvedVolumeUnits);
                LogStructuredTradeEvent(
                    IsBacktestingRuntime() ? "backtest" : "live",
                    "SUBMIT",
                    symbolName,
                    action,
                    "LIMIT",
                    requestedLots,
                    effectiveEntryPrice,
                    approvedSl,
                    approvedTp,
                    "",
                    signal.StrategyId + ":" + signal.SourceLabel + ";" + riskLogDetail);
                result = PlaceLimitOrder(
                    signal.TradeType,
                    symbol.Name,
                    approvedVolumeUnits,
                    effectiveEntryPrice,
                    firstOrderLabel,
                    (double?)slPips,
                    tpPips,
                    (ProtectionType?)null,
                    null,
                    BuildStrategyOrderComment(
                        symbol,
                        BuildCompactStrategySid(symbolName, signal.SourceTimeFrame, signal.SignalTime, signal.TradeChainSlot),
                        1,
                        symbolName,
                        signal.SourceTimeFrame,
                        signal.SourceLabel,
                        effectiveEntryPrice,
                        approvedTp,
                        approvedSl,
                        firstOrderRiskComment,
                        GetStrategyOrderEntryModeComment(signal),
                        true,
                        signal.PatternToEntryBars,
                        signal.SignalTime,
                        protectionSourceComment));

                if (result != null && result.IsSuccessful && result.PendingOrder != null)
                {
                    string modifyError;
                    if (!TryApplyPendingOrderProtection(result.PendingOrder, symbol, action, approvedSl, approvedTp, out modifyError))
                    {
                        SafePrint("[Strategy] Entry failed {0} {1}: {2}", signal.StrategyId, symbolName, modifyError);
                        return;
                    }
                }
            }
            else
            {
                var slPips = CTraderExecutionEngine.ResolveDistancePips(symbol, effectiveEntryPrice, approvedSl).GetValueOrDefault();
                double? tpPips = CTraderExecutionEngine.ResolveDistancePips(symbol, effectiveEntryPrice, approvedTp);
                var requestedLots = symbol.VolumeInUnitsToQuantity(approvedVolumeUnits);
                LogStructuredTradeEvent(
                    IsBacktestingRuntime() ? "backtest" : "live",
                    "SUBMIT",
                    symbolName,
                    action,
                    "MARKET",
                    requestedLots,
                    effectiveEntryPrice,
                    approvedSl,
                    approvedTp,
                    "",
                    signal.StrategyId + ":" + signal.SourceLabel + ";" + riskLogDetail);
                result = ExecuteMarketOrder(
                    signal.TradeType,
                    symbol.Name,
                    approvedVolumeUnits,
                    firstOrderLabel,
                    (double?)slPips,
                    tpPips,
                    BuildStrategyOrderComment(
                        symbol,
                        BuildCompactStrategySid(symbolName, signal.SourceTimeFrame, signal.SignalTime, signal.TradeChainSlot),
                        1,
                        symbolName,
                        signal.SourceTimeFrame,
                        signal.SourceLabel,
                        effectiveEntryPrice,
                        approvedTp,
                        approvedSl,
                        firstOrderRiskComment,
                        GetStrategyOrderEntryModeComment(signal),
                        false,
                        signal.PatternToEntryBars,
                        signal.SignalTime,
                        protectionSourceComment));
            }

            if (result != null && result.IsSuccessful)
            {
                var finalApprovedSl = approvedSl;
                var finalApprovedTp = approvedTp;
                if (result.Position != null)
                {
                    if (!effectiveUseLimitOrder)
                        ReanchorProtectionToFilledEntry(symbol, action, effectiveEntryPrice, result.Position.EntryPrice, ref finalApprovedSl, ref finalApprovedTp);
                    string protectionError;
                    if (!TryEnsureStrategyPositionProtection(result.Position, symbol, action, finalApprovedSl, finalApprovedTp, out protectionError))
                    {
                        var closeProtectionResult = ClosePosition(result.Position);
                        var closeProtectionNote = closeProtectionResult != null && closeProtectionResult.IsSuccessful
                            ? "position_closed_after_protection_failure"
                            : "position_close_failed_after_protection_failure";
                        LogStructuredTradeEvent(
                            IsBacktestingRuntime() ? "backtest" : "live",
                            "FAILED",
                            symbolName,
                            action,
                            effectiveUseLimitOrder ? "LIMIT" : "MARKET",
                            symbol.VolumeInUnitsToQuantity(approvedVolumeUnits),
                            result.Position.EntryPrice,
                            finalApprovedSl,
                            finalApprovedTp,
                            result.Position.Id.ToString(CultureInfo.InvariantCulture),
                            protectionError + "; " + closeProtectionNote);
                        SafePrint("[Strategy] Entry failed {0} {1}: {2}; {3}", signal.StrategyId, symbolName, protectionError, closeProtectionNote);
                        _backtestStrategyHandledEventKeys.Add(eventKey);
                        return;
                    }

                    TryApplySelectedExitModeForPosition(result.Position);
                }

                LogStructuredTradeEvent(
                    IsBacktestingRuntime() ? "backtest" : "live",
                    "SUCCEEDED",
                    symbolName,
                    action,
                    effectiveUseLimitOrder ? "LIMIT" : "MARKET",
                    symbol.VolumeInUnitsToQuantity(approvedVolumeUnits),
                    result.Position != null ? result.Position.EntryPrice : (result.PendingOrder != null ? result.PendingOrder.TargetPrice : effectiveEntryPrice),
                    finalApprovedSl,
                    finalApprovedTp,
                    result.Position != null ? result.Position.Id.ToString(CultureInfo.InvariantCulture) : (result.PendingOrder != null ? result.PendingOrder.Id.ToString(CultureInfo.InvariantCulture) : ""),
                    signal.StrategyId + ":" + signal.SourceLabel + ";" + riskLogDetail);
                SafePrint(
                    "[Strategy] Entry {0} {1} {2} {3} event={4} vol={5:F2} risk={6:F2} {7}{8}",
                    signal.StrategyId,
                    action,
                    effectiveUseLimitOrder ? "LIMIT" : "MARKET",
                    symbolName,
                    signal.SourceLabel,
                    approvedVolumeUnits,
                    approvedRiskMoney,
                    riskLogDetail,
                    string.IsNullOrWhiteSpace(signal.Note) ? "" : " " + signal.Note);
                AddCustomTradeTriggerMarker(symbolName, signal);
                _backtestStrategyHandledEventKeys.Add(eventKey);

                // Extra split legs: for limit signals the first order is splitEntries[0]
                // (the signal entry), for market signals the first order is the market;
                // the remaining entries become limit orders with their own risk slices.
                var extraStartIndex = effectiveUseLimitOrder ? 1 : 0;
                var extraEntries = splitEntries.Skip(extraStartIndex).ToList();
                var extraWeights = splitWeights.Skip(1).Take(extraEntries.Count).ToArray();
                var sharedExtraSl = finalApprovedSl > 0 ? finalApprovedSl : sl;
                var sharedExtraTp = finalApprovedTp > 0 ? finalApprovedTp : tp;
                var affordableExtra = new List<double>();
                var affordableExtraWeights = new List<double>();
                var hasAffordableExtra = TryResolveAffordableSplitLegs(symbol, signal.TradeType, extraEntries, extraWeights, sharedExtraSl, finalRiskMoney, affordableExtra, affordableExtraWeights);
                if (extraEntries.Count > 0 && !hasAffordableExtra)
                {
                    SafePrint(
                        "[StrategySplit] all pending ladder legs skipped as unaffordable: {0} {1} n.Trades={2} entries=[{3}] sl={4} risk={5:0.##}",
                        action,
                        symbolName,
                        orderCountOverride,
                        string.Join(",", extraEntries.Select(FormatPriceShort)),
                        FormatPriceShort(sharedExtraSl),
                        finalRiskMoney);
                }

                var extraPlacedCount = 0;
                for (var i = 0; i < affordableExtra.Count && i < affordableExtraWeights.Count; i++)
                {
                    string splitPositionCapRejectReason;
                    if (!TryPassStrategyPositionCaps(symbolName, signal.TradeType, out splitPositionCapRejectReason))
                    {
                        SafePrint("[StrategySplit] remaining legs blocked by trade cap: {0}", splitPositionCapRejectReason);
                        break;
                    }

                    var splitNumber = i + 2;
                    var extraEntry = affordableExtra[i];
                    var sliceRiskMoney = finalRiskMoney > 0 ? Math.Max(0, finalRiskMoney * affordableExtraWeights[i]) : 0;
                    var pendingVolumeUnits = ResolveChartTradeVolumeForRisk(symbol, signal.TradeType, extraEntry, sharedExtraSl, sliceRiskMoney, symbolName);
                    if (pendingVolumeUnits < symbol.VolumeInUnitsMin)
                    {
                        SafePrint(
                            "[StrategySplit] skipped split #{0}: volume below minimum entry={1} sl={2} risk={3:0.##} units={4:0.##}/{5:0.##}",
                            splitNumber,
                            FormatPriceShort(extraEntry),
                            FormatPriceShort(sharedExtraSl),
                            sliceRiskMoney,
                            pendingVolumeUnits,
                            symbol.VolumeInUnitsMin);
                        continue;
                    }

                    double approvedExtraSl;
                    double approvedExtraTp;
                    double approvedExtraVolumeUnits;
                    double approvedExtraRiskMoney;
                    double approvedExtraMarginEstimate;
                    double approvedExtraMarginBudget;
                    string extraGateRejectReason;
                    if (!TryPassSharedCreationGate(
                        symbol,
                        action,
                        "limit",
                        extraEntry,
                        executionPrice,
                        sharedExtraSl,
                        sharedExtraTp,
                        pendingVolumeUnits,
                        sliceRiskMoney,
                        sliceRiskMoney,
                        false,
                        out approvedExtraSl,
                        out approvedExtraTp,
                        out approvedExtraVolumeUnits,
                        out approvedExtraRiskMoney,
                        out approvedExtraMarginEstimate,
                        out approvedExtraMarginBudget,
                        out extraGateRejectReason))
                    {
                        SafePrint(
                            "[StrategySplit] skipped split #{0}: creation gate rejected entry={1} sl={2} tp={3} reason={4}",
                            splitNumber,
                            FormatPriceShort(extraEntry),
                            FormatPriceShort(sharedExtraSl),
                            FormatPriceShort(sharedExtraTp),
                            extraGateRejectReason);
                        continue;
                    }

                    if (approvedExtraVolumeUnits < symbol.VolumeInUnitsMin)
                    {
                        SafePrint(
                            "[StrategySplit] skipped split #{0}: approved volume below minimum entry={1} units={2:0.##}/{3:0.##}",
                            splitNumber,
                            FormatPriceShort(extraEntry),
                            approvedExtraVolumeUnits,
                            symbol.VolumeInUnitsMin);
                        continue;
                    }

                    var extraSlPips = symbol.PipSize > 0 ? (double?)Math.Round(Math.Abs(extraEntry - approvedExtraSl) / symbol.PipSize, 2) : null;
                    var extraTpPips = symbol.PipSize > 0 && approvedExtraTp > 0 ? (double?)Math.Round(Math.Abs(approvedExtraTp - extraEntry) / symbol.PipSize, 2) : null;
                    var extraLots = symbol.VolumeInUnitsToQuantity(approvedExtraVolumeUnits);
                    var extraRiskFactor = confidenceVolumeFactor * affordableExtraWeights[i];
                    var extraRiskComment = FormatStrategyRiskLegComment(splitNumber, approvedExtraRiskMoney, baseRiskMoney);
                    var extraProtectionSourceComment = BuildFinalStrategyProtectionSourceComment(
                        signal,
                        symbol,
                        sharedExtraSl,
                        sharedExtraTp,
                        approvedExtraSl,
                        approvedExtraTp);
                    SafePrint(
                        "[RiskSizing] {0} {1} {2} split={3}: risk_score={4};risk_factor={5:0.###};leg_cap={6:0.##};approved_units={7:0.##};approved_lots={8:0.####};approved_risk={9:0.##}",
                        signal.StrategyId,
                        action,
                        symbolName,
                        i + 2,
                        riskScoreText,
                        extraRiskFactor,
                        sliceRiskMoney,
                        approvedExtraVolumeUnits,
                        extraLots,
                        approvedExtraRiskMoney);
                    var extraResult = PlaceLimitOrder(
                        signal.TradeType,
                        symbol.Name,
                        approvedExtraVolumeUnits,
                        extraEntry,
                        firstOrderLabel,
                        extraSlPips,
                        extraTpPips,
                        (ProtectionType?)null,
                        null,
                        BuildStrategyOrderComment(
                            symbol,
                            BuildCompactStrategySid(symbolName, signal.SourceTimeFrame, signal.SignalTime, signal.TradeChainSlot),
                            splitNumber,
                            symbolName,
                            signal.SourceTimeFrame,
                            signal.SourceLabel,
                            extraEntry,
                            approvedExtraTp,
                            approvedExtraSl,
                            extraRiskComment,
                            GetStrategyOrderEntryModeComment(signal),
                            true,
                            signal.PatternToEntryBars,
                            signal.SignalTime,
                            extraProtectionSourceComment));
                    if (extraResult == null || !extraResult.IsSuccessful)
                    {
                        SafePrint(
                            "[StrategySplit] split #{0} limit order failed: entry={1} error={2}",
                            splitNumber,
                            FormatPriceShort(extraEntry),
                            extraResult != null ? Convert.ToString(extraResult.Error, CultureInfo.InvariantCulture) : "unknown");
                        continue;
                    }

                    if (extraResult.PendingOrder != null)
                    {
                        string modifyError;
                        if (!TryApplyPendingOrderProtection(extraResult.PendingOrder, symbol, action, approvedExtraSl, approvedExtraTp, out modifyError))
                        {
                            SafePrint(
                                "[StrategySplit] split #{0} protection failed: entry={1} reason={2}",
                                splitNumber,
                                FormatPriceShort(extraEntry),
                                modifyError);
                            continue;
                        }
                    }
                    extraPlacedCount++;
                }

                if (extraPlacedCount > 0)
                    SafePrint("[Strategy] Entry {0} {1} {2} placed {3} split limit leg(s) (n.Trades={4})", signal.StrategyId, action, symbolName, extraPlacedCount, 1 + extraPlacedCount);
            }
            else
            {
                var orphanPosition = FindPositionCreatedAfterSubmit(
                    previousPositionIds,
                    symbolName,
                    firstOrderLabel,
                    signal.TradeType);
                if (orphanPosition != null)
                {
                    string recoveryDetail;
                    var recovered = TryRecoverPositionAfterFailedSubmit(
                        orphanPosition,
                        symbol,
                        action,
                        effectiveEntryPrice,
                        approvedSl,
                        approvedTp,
                        out recoveryDetail);
                    SafePrint(
                        "[Strategy] Failed submit reconciliation {0} {1}: {2}",
                        signal.StrategyId,
                        symbolName,
                        recoveryDetail);
                    if (recovered)
                    {
                        AddCustomTradeTriggerMarker(symbolName, signal);
                        _backtestStrategyHandledEventKeys.Add(eventKey);
                        return;
                    }
                }
                LogStructuredTradeEvent(
                    IsBacktestingRuntime() ? "backtest" : "live",
                    "FAILED",
                    symbolName,
                    action,
                    effectiveUseLimitOrder ? "LIMIT" : "MARKET",
                    symbol.VolumeInUnitsToQuantity(approvedVolumeUnits),
                    effectiveEntryPrice,
                    approvedSl,
                    approvedTp,
                    "",
                    result != null ? Convert.ToString(result.Error, CultureInfo.InvariantCulture) : "null_result");
                SafePrint("[Strategy] Entry failed {0} {1}: {2}", signal.StrategyId, symbolName, result != null ? Convert.ToString(result.Error, CultureInfo.InvariantCulture) : "null_result");
            }
        }

        private bool TryEnsureStrategyPositionProtection(Position position, Symbol symbol, string action, double approvedSl, double approvedTp, out string errorText)
        {
            errorText = "";

            if (position == null)
            {
                errorText = "position_missing_after_fill";
                return false;
            }
            if (symbol == null || symbol.PipSize <= 0)
            {
                errorText = "position_protection_symbol_missing";
                return false;
            }
            if (!(approvedSl > 0))
            {
                errorText = "position_stop_loss_missing";
                return false;
            }

            var needsSl = true;
            var needsTp = approvedTp > 0;
            var normalizedSl = needsSl ? NormalizePriceToSymbol(symbol, approvedSl) : 0;
            var normalizedTp = needsTp ? NormalizePriceToSymbol(symbol, approvedTp) : 0;

            string validationReason;
            if (!TryValidateProtectionPrices(symbol, action, position.EntryPrice, normalizedSl, normalizedTp, out validationReason))
            {
                errorText = "post_fill_protection_rejected: " + validationReason;
                return false;
            }

            var currentSl = position.StopLoss;
            var currentTp = position.TakeProfit;
            var slCloseEnough = CTraderExecutionEngine.IsProtectionCloseEnough(
                currentSl, normalizedSl, needsSl, symbol.PipSize * 0.5);
            var tpCloseEnough = CTraderExecutionEngine.IsProtectionCloseEnough(
                currentTp, normalizedTp, needsTp, symbol.PipSize * 0.5);
            if (HasRequiredProtection(position, needsSl, needsTp) && slCloseEnough && tpCloseEnough)
                return true;

            var desiredSl = needsSl ? (double?)normalizedSl : position.StopLoss;
            var desiredTp = needsTp ? (double?)normalizedTp : position.TakeProfit;
            var modifyResult = ModifyPositionCompat(position, desiredSl, desiredTp);
            if (modifyResult != null && modifyResult.IsSuccessful)
            {
                SafePrint("[Strategy] Protection set SL={0} TP={1} for {2} #{3}", normalizedSl, normalizedTp, position.SymbolName, position.Id);
                return true;
            }

            currentSl = position.StopLoss;
            currentTp = position.TakeProfit;
            slCloseEnough = CTraderExecutionEngine.IsProtectionCloseEnough(
                currentSl, normalizedSl, needsSl, symbol.PipSize * 0.5);
            tpCloseEnough = CTraderExecutionEngine.IsProtectionCloseEnough(
                currentTp, normalizedTp, needsTp, symbol.PipSize * 0.5);
            if (HasRequiredProtection(position, needsSl, needsTp) && slCloseEnough && tpCloseEnough)
                return true;

            var slError = "";
            var tpError = "";
            var needsSlRefine = needsSl && !slCloseEnough;
            var needsTpRefine = needsTp && !tpCloseEnough;

            if (needsSlRefine)
            {
                var slOnlyResult = ModifyPositionCompat(position, normalizedSl, position.TakeProfit);
                currentSl = position.StopLoss;
                slCloseEnough = CTraderExecutionEngine.IsProtectionCloseEnough(
                    currentSl, normalizedSl, true, symbol.PipSize * 0.5);
                if (!(slOnlyResult != null && slOnlyResult.IsSuccessful) && !slCloseEnough)
                {
                    if (String.Equals(OnSlTpError, "Adjust", StringComparison.OrdinalIgnoreCase))
                    {
                        var adjustedSl = CTraderExecutionEngine.ResolveAdjustedProtectionPrice(
                            symbol, action, position.EntryPrice, true, MinStopPips);
                        var adjustedSlResult = ModifyPositionCompat(position, adjustedSl, position.TakeProfit);
                        currentSl = position.StopLoss;
                        slCloseEnough = CTraderExecutionEngine.IsProtectionCloseEnough(
                            currentSl, adjustedSl, true, symbol.PipSize * 0.5);
                        if (adjustedSlResult != null && adjustedSlResult.IsSuccessful || slCloseEnough)
                        {
                            normalizedSl = adjustedSl;
                        }
                        else
                        {
                            slError = "sl_rejected: " + (adjustedSlResult != null ? Convert.ToString(adjustedSlResult.Error, CultureInfo.InvariantCulture) : "null_result");
                        }
                    }
                    else
                    {
                        slError = "sl_rejected: " + (slOnlyResult != null ? Convert.ToString(slOnlyResult.Error, CultureInfo.InvariantCulture) : "null_result");
                    }
                }
            }

            if (needsTpRefine)
            {
                var currentTpForModify = position.TakeProfit;
                var tpOnlyResult = ModifyPositionCompat(position, position.StopLoss, normalizedTp);
                currentTp = position.TakeProfit;
                tpCloseEnough = CTraderExecutionEngine.IsProtectionCloseEnough(
                    currentTp, normalizedTp, true, symbol.PipSize * 0.5);
                if (!(tpOnlyResult != null && tpOnlyResult.IsSuccessful) && !tpCloseEnough)
                {
                    if (String.Equals(OnSlTpError, "Adjust", StringComparison.OrdinalIgnoreCase))
                    {
                        var adjustedTp = CTraderExecutionEngine.ResolveAdjustedProtectionPrice(
                            symbol, action, position.EntryPrice, false, MinStopPips);
                        var adjustedTpResult = ModifyPositionCompat(position, position.StopLoss, adjustedTp);
                        currentTp = position.TakeProfit;
                        tpCloseEnough = CTraderExecutionEngine.IsProtectionCloseEnough(
                            currentTp, adjustedTp, true, symbol.PipSize * 0.5);
                        if (adjustedTpResult != null && adjustedTpResult.IsSuccessful || tpCloseEnough)
                        {
                            normalizedTp = adjustedTp;
                        }
                        else
                        {
                            tpError = "tp_rejected: " + (adjustedTpResult != null ? Convert.ToString(adjustedTpResult.Error, CultureInfo.InvariantCulture) : "null_result");
                        }
                    }
                    else
                    {
                        tpError = "tp_rejected: " + (tpOnlyResult != null ? Convert.ToString(tpOnlyResult.Error, CultureInfo.InvariantCulture) : "null_result");
                    }
                }
            }

            if (HasRequiredProtection(position, needsSl, needsTp))
            {
                SafePrint("[Strategy] Protection set SL={0} TP={1} for {2} #{3}", normalizedSl, normalizedTp, position.SymbolName, position.Id);
                return true;
            }

            var errors = new List<string>();
            if (!string.IsNullOrWhiteSpace(slError)) errors.Add(slError);
            if (!string.IsNullOrWhiteSpace(tpError)) errors.Add(tpError);
            if (errors.Count == 0)
                errors.Add("sl_tp_rejected: " + (modifyResult != null ? Convert.ToString(modifyResult.Error, CultureInfo.InvariantCulture) : "null_result"));

            errorText = string.Format(
                CultureInfo.InvariantCulture,
                "{0} (SL={1} TP={2})",
                string.Join("; ", errors),
                normalizedSl,
                normalizedTp);
            return false;
        }

        private HashSet<long> CaptureOpenPositionIds()
        {
            return CTraderExecutionEngine.CapturePositionIds(Positions);
        }

        private Position FindPositionCreatedAfterSubmit(
            HashSet<long> previousPositionIds,
            string symbolName,
            string label,
            TradeType tradeType)
        {
            return CTraderExecutionEngine.FindPositionCreatedAfterSubmit(
                Positions, previousPositionIds, symbolName, label, tradeType);
        }

        private bool TryRecoverPositionAfterFailedSubmit(
            Position position,
            Symbol symbol,
            string action,
            double plannedEntry,
            double approvedSl,
            double approvedTp,
            out string detail)
        {
            detail = "";
            if (position == null)
            {
                detail = "no_position_created";
                return false;
            }

            var finalSl = approvedSl;
            var finalTp = approvedTp;
            ReanchorProtectionToFilledEntry(symbol, action, plannedEntry, position.EntryPrice, ref finalSl, ref finalTp);
            string protectionError;
            if (TryEnsureStrategyPositionProtection(position, symbol, action, finalSl, finalTp, out protectionError))
            {
                detail = string.Format(
                    CultureInfo.InvariantCulture,
                    "recovered_position={0} SL={1} TP={2}",
                    position.Id,
                    finalSl,
                    finalTp);
                return true;
            }

            var closeResult = ClosePosition(position);
            detail = string.Format(
                CultureInfo.InvariantCulture,
                "protection_failed={0}; close={1}",
                protectionError,
                closeResult != null && closeResult.IsSuccessful ? "ok" : "failed");
            return false;
        }

        private void ReanchorProtectionToFilledEntry(Symbol symbol, string action, double plannedEntry, double filledEntry, ref double sl, ref double tp)
        {
            CTraderExecutionEngine.ReanchorProtectionToFilledEntry(
                symbol, action, plannedEntry, filledEntry, ref sl, ref tp);
        }

        private bool TryBuildIndicatorStrategySignal(string symbolName, TimeFrame strategyTimeFrame, BacktestStrategyMode mode, out BacktestStrategySignal signal)
        {
            signal = default(BacktestStrategySignal);

            Symbol symbol;
            Bars sourceBars;
            int signalIndex;
            int previousIndex;
            if (!TryGetBacktestStrategyBars(symbolName, strategyTimeFrame, out symbol, out sourceBars, out signalIndex, out previousIndex))
                return false;

            var barTime = sourceBars.OpenTimes[signalIndex];
            var sourceTimeFrame = strategyTimeFrame;
            switch (mode)
            {
                case BacktestStrategyMode.Impulse:
                {
                    if (signalIndex < 1)
                        return false;
                    return CTraderStrategyEngine.TryBuildImpulseSignal(
                        symbol,
                        sourceBars.OpenPrices[signalIndex],
                        sourceBars.HighPrices[signalIndex],
                        sourceBars.LowPrices[signalIndex],
                        sourceBars.ClosePrices[signalIndex],
                        FollowTrendBigCandleBodyPercentMin,
                        Math.Max(symbol.PipSize * 0.5, 0.0000001),
                        StrategyRewardRisk,
                        sourceTimeFrame,
                        barTime,
                        out signal);
                }
                case BacktestStrategyMode.EmaCrossV1:
                {
                    var fastPrev = ComputeExponentialMovingAverage(sourceBars, previousIndex, 9);
                    var fastCurrent = ComputeExponentialMovingAverage(sourceBars, signalIndex, 9);
                    var slowPrev = ComputeExponentialMovingAverage(sourceBars, previousIndex, 21);
                    var slowCurrent = ComputeExponentialMovingAverage(sourceBars, signalIndex, 21);
                    TradeType direction;
                    if (CTraderStrategyEngine.TryResolveCrossDirection(fastPrev, fastCurrent, slowPrev, slowCurrent, out direction))
                        signal = CTraderStrategyEngine.CreateSignal("ema_cross_v1", BacktestStrategyMode.Off, "", GetMiniChartLabel(sourceTimeFrame) + (direction == TradeType.Buy ? ".ema9.x>ema21" : ".ema9.x<ema21"), direction, sourceTimeFrame, barTime);
                    return signal.IsValid;
                }
                case BacktestStrategyMode.SmaCrossV1:
                {
                    var fastPrev = ComputeSimpleMovingAverage(sourceBars, previousIndex, 20);
                    var fastCurrent = ComputeSimpleMovingAverage(sourceBars, signalIndex, 20);
                    var slowPrev = ComputeSimpleMovingAverage(sourceBars, previousIndex, 50);
                    var slowCurrent = ComputeSimpleMovingAverage(sourceBars, signalIndex, 50);
                    TradeType direction;
                    if (CTraderStrategyEngine.TryResolveCrossDirection(fastPrev, fastCurrent, slowPrev, slowCurrent, out direction))
                        signal = CTraderStrategyEngine.CreateSignal("sma_cross_v1", BacktestStrategyMode.Off, "", GetMiniChartLabel(sourceTimeFrame) + (direction == TradeType.Buy ? ".sma20.x>sma50" : ".sma20.x<sma50"), direction, sourceTimeFrame, barTime);
                    return signal.IsValid;
                }
                case BacktestStrategyMode.GoldenCrossV1:
                {
                    var fastPrev = ComputeSimpleMovingAverage(sourceBars, previousIndex, 50);
                    var fastCurrent = ComputeSimpleMovingAverage(sourceBars, signalIndex, 50);
                    var slowPrev = ComputeSimpleMovingAverage(sourceBars, previousIndex, 200);
                    var slowCurrent = ComputeSimpleMovingAverage(sourceBars, signalIndex, 200);
                    TradeType direction;
                    if (CTraderStrategyEngine.TryResolveCrossDirection(fastPrev, fastCurrent, slowPrev, slowCurrent, out direction))
                        signal = CTraderStrategyEngine.CreateSignal("golden_cross_v1", BacktestStrategyMode.Off, "", GetMiniChartLabel(sourceTimeFrame) + (direction == TradeType.Buy ? ".sma50.x>sma200" : ".sma50.x<sma200"), direction, sourceTimeFrame, barTime);
                    return signal.IsValid;
                }
                case BacktestStrategyMode.TripleEmaTrendV1:
                {
                    var fastPrev = ComputeExponentialMovingAverage(sourceBars, previousIndex, 8);
                    var fastCurrent = ComputeExponentialMovingAverage(sourceBars, signalIndex, 8);
                    var midPrev = ComputeExponentialMovingAverage(sourceBars, previousIndex, 21);
                    var midCurrent = ComputeExponentialMovingAverage(sourceBars, signalIndex, 21);
                    var slowCurrent = ComputeExponentialMovingAverage(sourceBars, signalIndex, 55);
                    TradeType direction;
                    if (CTraderStrategyEngine.TryResolveTripleTrendDirection(fastPrev, fastCurrent, midPrev, midCurrent, slowCurrent, out direction))
                        signal = CTraderStrategyEngine.CreateSignal("triple_ema_trend_v1", BacktestStrategyMode.Off, "", GetMiniChartLabel(sourceTimeFrame) + (direction == TradeType.Buy ? ".ema8.x>ema21" : ".ema8.x<ema21"), direction, sourceTimeFrame, barTime);
                    return signal.IsValid;
                }
                case BacktestStrategyMode.RsiReversionV1:
                {
                    var rsiPrev = ComputeRelativeStrengthIndex(sourceBars, previousIndex, 14);
                    var rsiCurrent = ComputeRelativeStrengthIndex(sourceBars, signalIndex, 14);
                    TradeType direction;
                    if (CTraderStrategyEngine.TryResolveThresholdReversionDirection(rsiPrev, rsiCurrent, 30, 70, out direction))
                        signal = CTraderStrategyEngine.CreateSignal("rsi_reversion_v1", BacktestStrategyMode.Off, "", GetMiniChartLabel(sourceTimeFrame) + (direction == TradeType.Buy ? ".rsi14.x>30" : ".rsi14.x<70"), direction, sourceTimeFrame, barTime);
                    return signal.IsValid;
                }
                case BacktestStrategyMode.BollingerReversionV1:
                {
                    var previousMid = ComputeSimpleMovingAverage(sourceBars, previousIndex, 20);
                    var currentMid = ComputeSimpleMovingAverage(sourceBars, signalIndex, 20);
                    var previousStd = ComputeRollingStandardDeviation(sourceBars, previousIndex, 20, previousMid);
                    var currentStd = ComputeRollingStandardDeviation(sourceBars, signalIndex, 20, currentMid);
                    var previousLower = previousMid - (previousStd * 2.0);
                    var previousUpper = previousMid + (previousStd * 2.0);
                    TradeType direction;
                    if (CTraderStrategyEngine.TryResolveBollingerReversionDirection(sourceBars.ClosePrices[previousIndex], sourceBars.ClosePrices[signalIndex], previousLower, previousUpper, currentMid, out direction))
                        signal = CTraderStrategyEngine.CreateSignal("bollinger_reversion_v1", BacktestStrategyMode.Off, "", GetMiniChartLabel(sourceTimeFrame) + (direction == TradeType.Buy ? ".x>bbm20" : ".x<bbm20"), direction, sourceTimeFrame, barTime);
                    return signal.IsValid;
                }
                case BacktestStrategyMode.StochReversalV1:
                {
                    var stochPrev = ComputeSmoothedStochasticK(sourceBars, previousIndex, 14, 3);
                    var stochCurrent = ComputeSmoothedStochasticK(sourceBars, signalIndex, 14, 3);
                    TradeType direction;
                    if (CTraderStrategyEngine.TryResolveThresholdReversionDirection(stochPrev, stochCurrent, 20, 80, out direction))
                        signal = CTraderStrategyEngine.CreateSignal("stoch_reversal_v1", BacktestStrategyMode.Off, "", GetMiniChartLabel(sourceTimeFrame) + (direction == TradeType.Buy ? ".stoch14.x>20" : ".stoch14.x<80"), direction, sourceTimeFrame, barTime);
                    return signal.IsValid;
                }
                case BacktestStrategyMode.MacdSignalV1:
                {
                    double macdPrev;
                    double signalPrev;
                    double macdCurrent;
                    double signalCurrent;
                    if (!TryComputeMacdValues(sourceBars, previousIndex, 12, 26, 9, out macdPrev, out signalPrev) ||
                        !TryComputeMacdValues(sourceBars, signalIndex, 12, 26, 9, out macdCurrent, out signalCurrent))
                        return false;
                    TradeType direction;
                    if (CTraderStrategyEngine.TryResolveCrossDirection(macdPrev, macdCurrent, signalPrev, signalCurrent, out direction))
                        signal = CTraderStrategyEngine.CreateSignal("macd_signal_v1", BacktestStrategyMode.Off, "", GetMiniChartLabel(sourceTimeFrame) + (direction == TradeType.Buy ? ".macd.x>sig" : ".macd.x<sig"), direction, sourceTimeFrame, barTime);
                    return signal.IsValid;
                }
                case BacktestStrategyMode.RocMomentumV1:
                {
                    var rocPrev = ComputeRateOfChange(sourceBars, previousIndex, 12);
                    var rocCurrent = ComputeRateOfChange(sourceBars, signalIndex, 12);
                    TradeType direction;
                    if (CTraderStrategyEngine.TryResolveCrossDirection(rocPrev, rocCurrent, 0, 0, out direction))
                        signal = CTraderStrategyEngine.CreateSignal("roc_momentum_v1", BacktestStrategyMode.Off, "", GetMiniChartLabel(sourceTimeFrame) + (direction == TradeType.Buy ? ".roc12.x>0" : ".roc12.x<0"), direction, sourceTimeFrame, barTime);
                    return signal.IsValid;
                }
                case BacktestStrategyMode.DonchianBreakoutV1:
                {
                    if (signalIndex < 21)
                        return false;
                    var channelHigh = double.MinValue;
                    var channelLow = double.MaxValue;
                    for (var i = signalIndex - 20; i <= signalIndex - 1; i++)
                    {
                        channelHigh = Math.Max(channelHigh, sourceBars.HighPrices[i]);
                        channelLow = Math.Min(channelLow, sourceBars.LowPrices[i]);
                    }

                    TradeType direction;
                    if (CTraderStrategyEngine.TryResolveDonchianBreakoutDirection(sourceBars.ClosePrices[signalIndex], channelHigh, channelLow, out direction))
                        signal = CTraderStrategyEngine.CreateSignal("donchian_breakout_v1", BacktestStrategyMode.Off, "", GetMiniChartLabel(sourceTimeFrame) + (direction == TradeType.Buy ? ".x>don20" : ".x<don20"), direction, sourceTimeFrame, barTime);
                    return signal.IsValid;
                }
                case BacktestStrategyMode.Trend:
                {
                    var candlesNum = Math.Max(1, FollowTrendCandlesCount);
                    var slCandleNum = Math.Max(1, FollowTrendSlCandleNum);
                    if (slCandleNum >= candlesNum)
                        slCandleNum = Math.Max(0, candlesNum - 1);

                    if (signalIndex < candlesNum - 1)
                        return false;

                    return CTraderStrategyEngine.TryBuildTrendSignal(
                        symbol,
                        symbolName,
                        sourceBars,
                        signalIndex,
                        candlesNum,
                        slCandleNum,
                        StrategyRewardRisk,
                        sourceTimeFrame,
                        barTime,
                        out signal);
                }
            }

            return false;
        }

        private bool TryBuildPriceActionTriggerSignal(string symbolName, TimeFrame strategyTimeFrame, string strategyId, bool useSuggestedLevels, int slRank, int tpRank, bool useLimitBodyMidEntry, out BacktestStrategySignal signal)
        {
            signal = default(BacktestStrategySignal);

            Symbol symbol;
            Bars sourceBars;
            int signalIndex;
            int previousIndex;
            if (!TryGetBacktestStrategyBars(symbolName, strategyTimeFrame, out symbol, out sourceBars, out signalIndex, out previousIndex))
                return false;

            var bullishPattern = IsBullishPinBar(sourceBars, signalIndex) || IsBullishEngulfing(sourceBars, previousIndex, signalIndex);
            var bearishPattern = IsBearishPinBar(sourceBars, signalIndex) || IsBearishEngulfing(sourceBars, previousIndex, signalIndex);
            CanonicalMarketEvent directionalEvent;
            var timeFrames = new[] { strategyTimeFrame };
            var bullishEvent = TryGetRecentDirectionalEvent(symbolName, timeFrames, true, out directionalEvent, CanonicalEventType.Bos, CanonicalEventType.Choch);
            var bearishEvent = TryGetRecentDirectionalEvent(symbolName, timeFrames, false, out directionalEvent, CanonicalEventType.Bos, CanonicalEventType.Choch);

            TradeType tradeType;
            if (!CTraderStrategyEngine.TryResolvePriceActionDirection(
                    HasBullishBiasForStrategy(symbolName),
                    HasBearishBiasForStrategy(symbolName),
                    bullishPattern || bullishEvent,
                    bearishPattern || bearishEvent,
                    out tradeType))
                return false;

            var entryPrice = tradeType == TradeType.Buy ? symbol.Ask : symbol.Bid;
            if (useLimitBodyMidEntry)
                entryPrice = NormalizePriceToSymbol(symbol, (Open(sourceBars, signalIndex) + Close(sourceBars, signalIndex)) * 0.5);

            var signalTime = sourceBars.OpenTimes[signalIndex];
            var profileRaw = GetChartTradeProfileRaw();
            var result = new BacktestStrategySignal
            {
                IsValid = true,
                StrategyId = strategyId,
                SourceLabel = useLimitBodyMidEntry ? "body_mid_limit" : "price_action",
                TradeType = tradeType,
                SourceTimeFrame = strategyTimeFrame,
                SignalTime = signalTime,
                UseLimitOrder = useLimitBodyMidEntry,
                EntryPrice = entryPrice
            };

            if (useSuggestedLevels)
            {
                ChartTradePlan plan;
                if (!TryBuildSuggestedLevelsPlan(symbol, symbolName, tradeType, entryPrice, slRank, tpRank, profileRaw, out plan) || !plan.IsValid)
                    return false;

                result.EntryPrice = plan.Entry;
                result.StopLoss = plan.StopLoss;
                result.TakeProfit = plan.TakeProfit;
                result.Note = string.Format(CultureInfo.InvariantCulture, "[{0}] RR={1:F2}", plan.EntryLabel, plan.RewardRisk);
            }

            signal = result;
            return true;
        }

        private bool TryBuildPriceActionFvgContextSignal(string symbolName, TimeFrame strategyTimeFrame, out BacktestStrategySignal signal)
        {
            signal = default(BacktestStrategySignal);

            Symbol symbol;
            Bars sourceBars;
            int signalIndex;
            int previousIndex;
            if (!TryGetBacktestStrategyBars(symbolName, strategyTimeFrame, out symbol, out sourceBars, out signalIndex, out previousIndex))
                return false;

            var bullishBias = HasBullishBiasForStrategy(symbolName);
            var bearishBias = HasBearishBiasForStrategy(symbolName);
            if (!bullishBias && !bearishBias)
                return false;

            var profileRaw = GetChartTradeProfileRaw();
            var entries = CollectChartEntryCandidates(symbol, symbolName, profileRaw)
                .Where(candidate => !string.IsNullOrWhiteSpace(candidate.Label) && candidate.Label.IndexOf("FVG", StringComparison.OrdinalIgnoreCase) >= 0)
                .OrderByDescending(candidate => candidate.Time)
                .Take(6)
                .ToList();
            if (entries.Count == 0)
                return false;

            var barLow = Low(sourceBars, signalIndex);
            var barHigh = High(sourceBars, signalIndex);
            var barClose = Close(sourceBars, signalIndex);
            foreach (var entryCandidate in entries)
            {
                var mid = NormalizePriceToSymbol(symbol, entryCandidate.Entry);
                TradeType tradeType;
                if (!CTraderStrategyEngine.TryResolveFvgContextDirection(
                        bullishBias, bearishBias, barLow, barHigh, barClose, mid, out tradeType))
                    continue;
                var isSell = tradeType == TradeType.Sell;
                var entryPrice = isSell ? symbol.Bid : symbol.Ask;
                var targetLevels = GetRankedChartStructuralLevels(symbol, symbolName, isSell, entryPrice, profileRaw);
                var adjusted = targetLevels.Count > 0
                    ? ApplyChartProtectionBiasAndRisk(
                        symbol,
                        tradeType,
                        entryPrice,
                        isSell ? entryCandidate.High : entryCandidate.Low,
                        targetLevels[0].Price)
                    : null;
                if (adjusted == null)
                    continue;

                signal = CTraderStrategyEngine.CreateSignal(
                    "price_action_fvg_context_v1",
                    BacktestStrategyMode.Off,
                    "",
                    entryCandidate.Label,
                    tradeType,
                    strategyTimeFrame,
                    sourceBars.OpenTimes[signalIndex]);
                signal.EntryPrice = entryPrice;
                signal.StopLoss = adjusted.Item1;
                signal.TakeProfit = adjusted.Item2;
                signal.Note = "[local_fvg_context]";
                return true;
            }

            return false;
        }

        private void ExecuteBacktestPriceActionEventDetectorStrategy(string symbolName, TimeFrame strategyTimeFrame)
        {
            CanonicalMarketEvent latestEvent;
            if (!TryGetLatestBacktestStrategyEventForTimeFrames(symbolName, new[] { strategyTimeFrame }, out latestEvent))
                return;

            LogStrategyInfoOnce(
                "price_action_event_detector_v1",
                symbolName,
                string.Format(
                    CultureInfo.InvariantCulture,
                    "detector event={0}",
                    BuildCanonicalMarketEventName(latestEvent)));
        }

        private bool TryRunBacktestStrategy()
        {
            try
            {
                var configuredStrategies = GetConfiguredStrategyModes().ToList();
                if (!ShouldStrategyEngineRun())
                    return true;
                if (EnforceDailyPnlLimitIfNeeded("STRATEGY"))
                    return true;
                _lastStrategyEngineScanUtc = DateTime.UtcNow;
                EnsureSharedConfigCatalogLoaded();
                ProcessSharedPositionRuleActions();
                if (configuredStrategies.Count == 0)
                    return true;
                var isBacktesting = IsBacktestingRuntime();
                if (isBacktesting && _backtestRiskStopTriggered)
                    return true;

                string backtestRiskStopReason;
                if (isBacktesting && TryGetBacktestRiskStopReason(out backtestRiskStopReason))
                {
                    StopBacktestForPropRuleBreach("STATE", Symbol != null ? Symbol.Name : "", backtestRiskStopReason);
                    return true;
                }

                var fallbackSymbolName = Chart != null && !string.IsNullOrWhiteSpace(Chart.SymbolName)
                    ? Chart.SymbolName.Trim()
                    : (Symbol != null ? Symbol.Name : "");
                var fallbackTimeFrame = Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
                var strategyTargets = ResolveStrategyExecutionTargets(fallbackSymbolName, fallbackTimeFrame).ToList();
                if (strategyTargets.Count == 0)
                {
                    LogStrategyInfoOnce("engine", string.IsNullOrWhiteSpace(fallbackSymbolName) ? "UNKNOWN" : fallbackSymbolName, "no resolved strategy targets from Symbols/Timeframes");
                    return true;
                }

                foreach (var target in strategyTargets)
                {
                    if (!ShouldProcessStrategyTargetForNewClosedBar(target.SymbolName, target.TimeFrame))
                        continue;

                    try
                    {
                    SafePrint(
                        "[StrategyProcess] start at={0:yyyy-MM-dd HH:mm:ss} symbol={1} tf={2} closed={3:yyyy-MM-dd HH:mm:ss}",
                        Server != null ? Server.Time : DateTime.UtcNow,
                        target.SymbolName,
                        GetTimeFrameShortLabel(target.TimeFrame),
                        ResolveLatestClosedBarTime(target.SymbolName, target.TimeFrame));
                    PreloadCanonicalEventsForStrategyTarget(target, configuredStrategies);

                    foreach (var strategyMode in configuredStrategies)
                    {
                        switch (strategyMode)
                        {
                            case BacktestStrategyMode.CustomTrade:
                            {
                                if (!ShouldRunLiveStrategyForNewClosedBar(strategyMode, target.SymbolName, target.TimeFrame))
                                    break;

                                BacktestStrategySignal customSignal;
                                if (TryBuildCustomTradeSignal(target.SymbolName, target.TimeFrame, out customSignal))
                                {
                                    ExecuteBacktestStrategySignal(target.SymbolName, customSignal, false);
                                }
                                else
                                {
                                    string ruleRejectReason;
                                    if (TryGetCustomTradeRuleRejectReason(target.SymbolName, target.TimeFrame, out ruleRejectReason))
                                        LogStrategySkip("custom_trade", target.SymbolName, ruleRejectReason);
                                    SafePrint(
                                        "[Strategy] Trigger audit {0}: {1}",
                                        target.SymbolName,
                                        BuildCustomTradeTriggerAudit(target.SymbolName, target.TimeFrame));
                                }
                                for (var tradeChainSlot = 1; tradeChainSlot <= 3; tradeChainSlot++)
                                {
                                    BacktestStrategySignal waitConfirmSignal;
                                    if (TryBuildCustomWaitConfirmSignal(
                                        target.SymbolName,
                                        target.TimeFrame,
                                        tradeChainSlot,
                                        out waitConfirmSignal))
                                        ExecuteBacktestStrategySignal(target.SymbolName, waitConfirmSignal, false);
                                }
                                MarkLiveStrategyBarProcessed(strategyMode, target.SymbolName, target.TimeFrame);
                                break;
                            }
                            case BacktestStrategyMode.HtfEventMarket:
                                ExecuteBacktestHtfEventMarketStrategy(target.SymbolName, target.TimeFrame);
                                break;
                            case BacktestStrategyMode.LtfEventMarket:
                                ExecuteBacktestLtfEventMarketStrategy(target.SymbolName, target.TimeFrame);
                                break;
                            case BacktestStrategyMode.EmaCrossV1:
                            case BacktestStrategyMode.SmaCrossV1:
                            case BacktestStrategyMode.GoldenCrossV1:
                            case BacktestStrategyMode.TripleEmaTrendV1:
                            case BacktestStrategyMode.RsiReversionV1:
                            case BacktestStrategyMode.BollingerReversionV1:
                            case BacktestStrategyMode.StochReversalV1:
                            case BacktestStrategyMode.MacdSignalV1:
                            case BacktestStrategyMode.RocMomentumV1:
                            case BacktestStrategyMode.DonchianBreakoutV1:
                            {
                                if (!ShouldRunLiveStrategyForNewClosedBar(strategyMode, target.SymbolName, target.TimeFrame))
                                    break;

                                BacktestStrategySignal indicatorSignal;
                                if (TryBuildIndicatorStrategySignal(target.SymbolName, target.TimeFrame, strategyMode, out indicatorSignal))
                                {
                                    if (TryApplyStrategyCustomEventGate(target.SymbolName, target.TimeFrame, ref indicatorSignal))
                                        ExecuteBacktestStrategySignal(target.SymbolName, indicatorSignal, false);
                                    else
                                        LogStrategyInfoOnce(indicatorSignal.StrategyId, target.SymbolName, "custom event gate miss on " + NormalizeTradeTfLabel(GetMiniChartLabel(target.TimeFrame)));
                                }
                                else if (strategyMode == BacktestStrategyMode.Trend)
                                {
                                    var followTrendTf = NormalizeTradeTfLabel(GetMiniChartLabel(target.TimeFrame));
                                    LogStrategyInfoOnce("follow_trend", target.SymbolName, string.Format(CultureInfo.InvariantCulture, "no signal on {0} N={1} SL#{2} RR={3:0.##}", followTrendTf, Math.Max(1, FollowTrendCandlesCount), Math.Max(1, FollowTrendSlCandleNum), Math.Max(0.1, StrategyRewardRisk)));
                                }
                                else if (strategyMode == BacktestStrategyMode.Impulse)
                                {
                                    var bigCandleTf = NormalizeTradeTfLabel(GetMiniChartLabel(target.TimeFrame));
                                    LogStrategyInfoOnce("follow_trend_big_candle", target.SymbolName, string.Format(CultureInfo.InvariantCulture, "no signal on {0} body>={1:0.#}% rr={2:0.##}", bigCandleTf, Math.Max(50.0, Math.Min(100.0, FollowTrendBigCandleBodyPercentMin)), Math.Max(0.1, StrategyRewardRisk)));
                                }
                                MarkLiveStrategyBarProcessed(strategyMode, target.SymbolName, target.TimeFrame);
                                break;
                            }
                            case BacktestStrategyMode.Trend:
                            case BacktestStrategyMode.Impulse:
                            {
                                if (!ShouldRunLiveStrategyForNewClosedBar(strategyMode, target.SymbolName, target.TimeFrame))
                                    break;

                                BacktestStrategySignal eventSignal;
                                if (TryBuildEventDrivenStrategySignal(target.SymbolName, target.TimeFrame, strategyMode, out eventSignal))
                                {
                                    if (TryApplyStrategyCustomEventGate(target.SymbolName, target.TimeFrame, ref eventSignal))
                                        ExecuteBacktestStrategySignal(target.SymbolName, eventSignal, false);
                                    else
                                        LogStrategyInfoOnce(eventSignal.StrategyId, target.SymbolName, "custom event gate miss on " + NormalizeTradeTfLabel(GetMiniChartLabel(target.TimeFrame)));
                                }
                                else if (strategyMode == BacktestStrategyMode.Trend)
                                {
                                    var trendTf = NormalizeTradeTfLabel(GetMiniChartLabel(target.TimeFrame));
                                    LogStrategyInfoOnce("follow_trend", target.SymbolName, string.Format(CultureInfo.InvariantCulture, "no CT trigger on {0}", trendTf));
                                }
                                else
                                {
                                    var impulseTf = NormalizeTradeTfLabel(GetMiniChartLabel(target.TimeFrame));
                                    LogStrategyInfoOnce("follow_trend_big_candle", target.SymbolName, string.Format(CultureInfo.InvariantCulture, "no IM trigger on {0}", impulseTf));
                                }
                                MarkLiveStrategyBarProcessed(strategyMode, target.SymbolName, target.TimeFrame);
                                break;
                            }
                            case BacktestStrategyMode.PriceActionV1:
                            {
                                BacktestStrategySignal signal;
                                if (TryBuildPriceActionTriggerSignal(target.SymbolName, target.TimeFrame, "price_action_v1", false, 1, 1, false, out signal))
                                {
                                    if (TryApplyStrategyCustomEventGate(target.SymbolName, target.TimeFrame, ref signal))
                                        ExecuteBacktestStrategySignal(target.SymbolName, signal, false);
                                    else
                                        LogStrategyInfoOnce(signal.StrategyId, target.SymbolName, "custom event gate miss on " + NormalizeTradeTfLabel(GetMiniChartLabel(target.TimeFrame)));
                                }
                                break;
                            }
                            case BacktestStrategyMode.PriceActionEventDetectorV1:
                                ExecuteBacktestPriceActionEventDetectorStrategy(target.SymbolName, target.TimeFrame);
                                break;
                            case BacktestStrategyMode.PriceActionFvgContextV1:
                            {
                                BacktestStrategySignal signal;
                                if (TryBuildPriceActionFvgContextSignal(target.SymbolName, target.TimeFrame, out signal))
                                {
                                    if (TryApplyStrategyCustomEventGate(target.SymbolName, target.TimeFrame, ref signal))
                                        ExecuteBacktestStrategySignal(target.SymbolName, signal, false);
                                    else
                                        LogStrategyInfoOnce(signal.StrategyId, target.SymbolName, "custom event gate miss on " + NormalizeTradeTfLabel(GetMiniChartLabel(target.TimeFrame)));
                                }
                                break;
                            }
                            case BacktestStrategyMode.ArtifactSuggestedLevelsV1:
                            {
                                BacktestStrategySignal signal;
                                if (TryBuildPriceActionTriggerSignal(target.SymbolName, target.TimeFrame, "artifact_suggested_levels_v1", true, 1, 1, false, out signal))
                                {
                                    if (TryApplyStrategyCustomEventGate(target.SymbolName, target.TimeFrame, ref signal))
                                        ExecuteBacktestStrategySignal(target.SymbolName, signal, false);
                                    else
                                        LogStrategyInfoOnce(signal.StrategyId, target.SymbolName, "custom event gate miss on " + NormalizeTradeTfLabel(GetMiniChartLabel(target.TimeFrame)));
                                }
                                break;
                            }
                            case BacktestStrategyMode.ArtifactSuggestedLevelsV2:
                            {
                                BacktestStrategySignal signal;
                                if (TryBuildPriceActionTriggerSignal(target.SymbolName, target.TimeFrame, "artifact_suggested_levels_v2", true, 2, 2, false, out signal))
                                {
                                    if (TryApplyStrategyCustomEventGate(target.SymbolName, target.TimeFrame, ref signal))
                                        ExecuteBacktestStrategySignal(target.SymbolName, signal, false);
                                    else
                                        LogStrategyInfoOnce(signal.StrategyId, target.SymbolName, "custom event gate miss on " + NormalizeTradeTfLabel(GetMiniChartLabel(target.TimeFrame)));
                                }
                                break;
                            }
                            case BacktestStrategyMode.ArtifactSuggestedLevelsV2LimitBodyMid:
                            {
                                BacktestStrategySignal signal;
                                if (TryBuildPriceActionTriggerSignal(target.SymbolName, target.TimeFrame, "artifact_suggested_levels_v2_limit_body_mid", true, 2, 2, true, out signal))
                                {
                                    if (TryApplyStrategyCustomEventGate(target.SymbolName, target.TimeFrame, ref signal))
                                        ExecuteBacktestStrategySignal(target.SymbolName, signal, false);
                                    else
                                        LogStrategyInfoOnce(signal.StrategyId, target.SymbolName, "custom event gate miss on " + NormalizeTradeTfLabel(GetMiniChartLabel(target.TimeFrame)));
                                }
                                break;
                            }
                            case BacktestStrategyMode.AiSnapshotContextV1:
                                LogStrategyInfoOnce("ai_snapshot_context_v1", target.SymbolName, "requires external ai.* context rows; not available in standalone cTrader runtime");
                                break;
                        }
                    }
                    }
                    catch (Exception ex)
                    {
                        SafePrint(
                            "[Strategy] Target evaluation failed; will retry: {0} {1} error={2}",
                            target.SymbolName,
                            GetTimeFrameShortLabel(target.TimeFrame),
                            ex.Message);
                        continue;
                    }

                    MarkStrategyTargetBarProcessed(target.SymbolName, target.TimeFrame);
                    SafePrint(
                        "[StrategyProcess] complete at={0:yyyy-MM-dd HH:mm:ss} symbol={1} tf={2}",
                        Server != null ? Server.Time : DateTime.UtcNow,
                        target.SymbolName,
                        GetTimeFrameShortLabel(target.TimeFrame));
                }
                LogStrategyScanSummary();
                return true;
            }
            catch (Exception ex)
            {
                SafePrint("[Strategy] Engine failed: {0}", ex.Message);
                return false;
            }
        }

        private void ExecuteBacktestHtfEventMarketStrategy(string symbolName, TimeFrame strategyTimeFrame)
        {
            CanonicalMarketEvent strategyEvent;
            var higherFrames = GetBacktestStrategyHigherTimeFrames(strategyTimeFrame).ToList();
            if (higherFrames.Count == 0)
            {
                LogStrategyInfoOnce("HTF_EVENT", symbolName, "no enabled higher timeframe above current chart timeframe");
                return;
            }

            if (!TryGetLatestBacktestStrategyEvent(symbolName, strategyTimeFrame, out strategyEvent))
            {
                LogStrategyInfoOnce("HTF_EVENT", symbolName, "no recent eligible HTF event");
                return;
            }

            if (!TryPassStrategyCustomEventGate(symbolName, strategyTimeFrame, strategyEvent.IsBullish ? TradeType.Buy : TradeType.Sell))
            {
                LogStrategyInfoOnce("HTF_EVENT", symbolName, "custom event gate miss on " + NormalizeTradeTfLabel(GetMiniChartLabel(strategyTimeFrame)));
                return;
            }

            ExecuteCanonicalEventStrategySignal(symbolName, strategyEvent, "HTF_EVENT", BacktestStrategyMode.HtfEventMarket, true);
        }

        private void ExecuteBacktestLtfEventMarketStrategy(string symbolName, TimeFrame strategyTimeFrame)
        {
            CanonicalMarketEvent strategyEvent;
            var lowerFrames = GetBacktestStrategyCurrentTimeFrame(strategyTimeFrame).ToList();
            if (!TryGetLatestBacktestStrategyEventForTimeFrames(symbolName, lowerFrames, out strategyEvent))
            {
                LogStrategyInfoOnce(
                    "LTF_EVENT",
                    symbolName,
                    "no recent eligible LTF event in " + string.Join(",", lowerFrames.Select(GetMiniChartLabel)));
                return;
            }

            if (!TryPassStrategyCustomEventGate(symbolName, strategyTimeFrame, strategyEvent.IsBullish ? TradeType.Buy : TradeType.Sell))
            {
                LogStrategyInfoOnce("LTF_EVENT", symbolName, "custom event gate miss on " + NormalizeTradeTfLabel(GetMiniChartLabel(strategyTimeFrame)));
                return;
            }

            ExecuteCanonicalEventStrategySignal(symbolName, strategyEvent, "LTF_EVENT", BacktestStrategyMode.LtfEventMarket, false);
        }

        private void ExecuteCanonicalEventStrategySignal(
            string symbolName,
            CanonicalMarketEvent strategyEvent,
            string strategyId,
            BacktestStrategyMode strategyMode,
            bool requireHtfBiasConfluence)
        {
            var signal = new BacktestStrategySignal
            {
                IsValid = true,
                StrategyId = strategyId,
                StrategyMode = strategyMode,
                SymbolName = symbolName,
                SourceLabel = BuildCanonicalMarketEventName(strategyEvent),
                TradeType = strategyEvent.IsBullish ? TradeType.Buy : TradeType.Sell,
                SourceTimeFrame = strategyEvent.SourceTimeFrame,
                SignalTime = strategyEvent.BarTime,
                UseLimitOrder = false,
                EntryPrice = 0,
                StopLoss = 0,
                TakeProfit = 0,
                RelatedZoneLow = strategyEvent.ZoneLow,
                RelatedZoneHigh = strategyEvent.ZoneHigh,
                EventSlDistance = strategyEvent.ZoneHigh > strategyEvent.ZoneLow
                    ? strategyEvent.ZoneHigh - strategyEvent.ZoneLow
                    : 0,
                Note = string.Format(
                    CultureInfo.InvariantCulture,
                    "[event={0} reason={1} score={2}]",
                    strategyEvent.EventType,
                    FormatCanonicalEventReasonShort(strategyEvent.Reason),
                    strategyEvent.Score)
            };
            ExecuteBacktestStrategySignal(symbolName, signal, requireHtfBiasConfluence);
        }

        private void MasterTimerTick()
        {
            if (DisableMasterTimerBodyForIsolation)
                return;

            var isBacktesting = IsBacktestingRuntime();
            TrackStartupWarmup();
            if (!isBacktesting)
            {
                CheckCanonicalCacheDayFlush();
                FlushAnalysisCachesHourly();
            }
            if (IsStartupWarmupActive())
            {
                WriteBridgeDebugLog("MasterTimerTick: warmup skip");
                return;
            }
            if (!isBacktesting && AreChartVisualsEnabled() && _chartIndicatorInitializationPhase < 2)
            {
                if (_chartIndicatorInitializationPhase == 0)
                {
                    WriteBridgeDebugLog("Visuals: indicators.oscillators start");
                    try { SyncChartOscillatorIndicators(); }
                    catch (Exception ex) { SafePrint("[Visuals] Deferred oscillator sync failed: {0}", ex.Message); }
                    WriteBridgeDebugLog("Visuals: indicators.oscillators complete");
                }
                else
                {
                    WriteBridgeDebugLog("Visuals: indicators.overlays start");
                    try { SyncChartTechnicalOverlays(); }
                    catch (Exception ex) { SafePrint("[Visuals] Deferred overlay sync failed: {0}", ex.Message); }
                    WriteBridgeDebugLog("Visuals: indicators.overlays complete");
                }
                _chartIndicatorInitializationPhase++;
                return;
            }
            if (!DisableCustomChartUiForIsolation && !DisableChartPanelBootstrapForIsolation && !isBacktesting && !_chartUiBootstrapped && _masterTickCount >= 5)
            {
                try
                {
                    BuildChartButtonPanel();
                    _chartUiBootstrapped = true;
                }
                catch (Exception ex)
                {
                    SafeLog("ERROR", "[Bridge] Chart UI bootstrap failed: {0}", ex.Message);
                }
            }
            if (EnableLiveStrategyTrading && !isBacktesting && _masterTickCount <= 2)
            {
                var timerSymbol = ResolveSharedStrategySymbol(
                    Chart != null ? Chart.SymbolName : (Symbol != null ? Symbol.Name : ""));
                LogStrategyInfoOnce(
                    "engine",
                    string.IsNullOrWhiteSpace(timerSymbol) ? "UNKNOWN" : timerSymbol,
                    string.Format(
                        CultureInfo.InvariantCulture,
                        "master timer active tick={0} interval={1}s",
                        _masterTickCount,
                        GetEffectiveMasterTimerSeconds()));
            }

            // Trading actions take priority over chart rendering. A slow visual refresh must
            // never delay processing a newly closed strategy bar or a queued future action.
            var dailyPnlLimitActive = EnforceDailyPnlLimitIfNeeded("TIMER");
            var strategySchedulerRan = false;
            if (!dailyPnlLimitActive && !DisableMasterTimerStrategyForIsolation && ShouldStrategyEngineRun() && ShouldRunStrategiesOnMasterTimer() && ShouldRunStrategySchedulerNow())
            {
                if (TryRunBacktestStrategy())
                {
                    MarkStrategySchedulerSlotProcessed();
                    strategySchedulerRan = true;
                }
            }

            BeginMasterTimerAccountSnapshotScope();

            var fullRefreshEveryTicks = Math.Max(1, (int)Math.Ceiling(5.0 / GetEffectiveMasterTimerSeconds()));
            // Chart controls are optional. A failed panel bootstrap must never suppress chart
            // overlays or the debug panel in normal runtime.
            var canRefreshChartVisuals = !DisableMasterTimerChartWorkForIsolation && !DisableCustomChartUiForIsolation && !isBacktesting;
            var includeVisualOverlays = !DisableChartPerTickRefreshForIsolation && canRefreshChartVisuals && _masterTickCount >= 1 && (_masterTickCount % fullRefreshEveryTicks) == 0;
            if (!DisableChartPerTickRefreshForIsolation && canRefreshChartVisuals)
                RefreshDebugPanelNow(includeVisualOverlays, true);
            else if (canRefreshChartVisuals)
                DrawLiteZoneOverlays();

            if (_masterTickCount % 60 == 0) CleanupOldEntries();

            if (!DisableMasterTimerNetworkForIsolation && Is42TradeServerSyncEnabled() && EnableLiveStrategyTrading)
                TriggerNewsGateRefreshIfNeeded();

            EnforceLiveStrategyProtectionSafety();
            if (!DisableChartPerTickRefreshForIsolation && canRefreshChartVisuals)
                TrackStrategyPositionMarkers();

            if (isBacktesting)
            {
                if (strategySchedulerRan && AreChartVisualsEnabled())
                    RefreshChartSummaryPanel(BuildPanelRiskGateStateSafe());
                return;
            }

            if (_consecutiveErrors > 0)
            {
                int bs = Math.Min(30, (int)Math.Pow(2, _consecutiveErrors - 1));
                if (bs > PollSeconds && _masterTickCount % Math.Max(1, bs / GetEffectiveMasterTimerSeconds()) != 0)
                    return;
            }

            if (DisableMasterTimerNetworkForIsolation)
                return;

            var accId = Account.UserId.ToString();
            var now = DateTime.Now;
            var apiOffline = Is42TradeServerSyncEnabled() && IsApiOfflineCooldownActive(now);
            if (ShouldUseLocalRuntime())
                apiOffline = false;
            // Local mode does not perform server polling, so it must not wait for
            // a server sync before publishing bars to the shared Parquet store.
            var ancillaryReady = ShouldUseLocalRuntime() || _successPolls > 0 || _syncCount > 0;

            if (ShouldUseLocalRuntime() && !_busySharedArtifactSync &&
                (_lastSharedArtifactSync == DateTime.MinValue ||
                 (now - _lastSharedArtifactSync).TotalSeconds >= 30))
            {
                var artifactSymbols = GetActiveSymbols();
                if (artifactSymbols.Count > 0)
                {
                    _busySharedArtifactSync = true;
                    _lastSharedArtifactSync = now;
                    var artifactAccountId = accId;
                    Task.Run(async () =>
                    {
                        try { await SyncSharedCanonicalArtifactsAsync(artifactAccountId, artifactSymbols); }
                        catch (Exception ex) { SafePrint("[LocalArtifacts] ERROR: {0}", ex.Message); }
                        finally { _busySharedArtifactSync = false; }
                    });
                }
            }

            // --- Sync / Pull first. Bars should not compete during startup or recovery. ---
            bool doSync = CTraderSyncEngine.IsDue(now, _lastSyncAttemptTime, SyncIntervalSeconds);
            bool doPoll = CTraderSyncEngine.IsDue(now, _lastPollAttemptTime, PollSeconds);
            if (!apiOffline && doSync && !_busySync)
            {
                WriteBridgeDebugLog("MasterTimerTick: sync start");
                _lastSyncAttemptTime = now;
                _busySync = true; _syncStatus = "SYNCING";
                _syncOnly = true;
                DoTimerWork();
                return;
            }
            if (doPoll && !_busyPull && !_busySync)
            {
                WriteBridgeDebugLog("MasterTimerTick: poll start");
                _lastPollAttemptTime = now;
                _busyPull = true; _pollStatus = "POLLING"; _pollCount++;
                Task.Run(async () => { try { await PollSignalsAsync(accId); } catch { } finally { _busyPull = false; } });
                if (!ancillaryReady) return;
            }

            // --- Bar push ---
            if (!apiOffline && ancillaryReady && IsBarsPersistenceEnabled() && !_busyPull && !_busySync && BarPushEnabled && !_busyBars && CTraderSyncEngine.IsDue(now, _lastBarTime, BarPushSeconds))
            {
                _busyBars = true; _barStatus = "PUSHING";
                var syms = GetActiveSymbols();
                if (syms.Count > 0)
                {
                    var bs = syms;
                    Task.Run(async () =>
                    {
                        try { await PushBarsAsync(accId, bs); }
                        catch (Exception ex) { _lastBarErr = ex.Message; _barStatus = "ERROR"; }
                        finally { _lastBarTime = DateTime.Now; _busyBars = false; }
                    });
                }
                else { _barStatus = "IDLE"; _lastBarTime = now; _busyBars = false; }
            }

            // --- Incremental bars ---
            if (!apiOffline && ancillaryReady && IsBarsPersistenceEnabled() && !_busyPull && !_busySync && !_busyBars && EnableIncrementalBars && !_busyIncSync && CTraderSyncEngine.IsDue(now, _lastIncrementalSync, IncrementalBarsSeconds))
            {
                _busyIncSync = true;
                var syms = GetActiveSymbols();
                if (syms.Count > 0)
                {
                    var iss = syms;
                    Task.Run(async () =>
                    {
                        try { await SyncBarsIncrementalAsync(accId, iss); }
                        catch (Exception ex) { _lastIncrementalErr = ex.Message; }
                        finally { _lastIncrementalSync = DateTime.Now; _busyIncSync = false; }
                    });
                }
                else { _lastIncrementalSync = now; _busyIncSync = false; }
            }

        }

        private List<string> GetActiveSymbols()
        {
            if (_masterTimerAccountSnapshotActive && _masterTimerActiveSymbolsSnapshot != null)
                return _masterTimerActiveSymbolsSnapshot;

            var syms = _trackedSymbols.Count > 0 ? new List<string>(_trackedSymbols) : new List<string>();
            if (syms.Count == 0)
            {
                foreach (var configured in Regex.Split(StrategySymbols ?? "", "[,;\\s]+"))
                    if (!string.IsNullOrWhiteSpace(configured) && !syms.Contains(configured.Trim(), StringComparer.OrdinalIgnoreCase))
                        syms.Add(configured.Trim());
                foreach (var pos in GetCurrentPositionsSnapshot())
                    if (!string.IsNullOrWhiteSpace(pos.SymbolName) && !IsChartAllSymbolsSelection(pos.SymbolName) && !syms.Contains(pos.SymbolName)) syms.Add(pos.SymbolName);
                foreach (var order in GetCurrentPendingOrdersSnapshot())
                    if (!string.IsNullOrWhiteSpace(order.SymbolName) && !IsChartAllSymbolsSelection(order.SymbolName) && !syms.Contains(order.SymbolName)) syms.Add(order.SymbolName);
                if (Symbol != null && !string.IsNullOrWhiteSpace(Symbol.Name) && !IsChartAllSymbolsSelection(Symbol.Name) && !syms.Contains(Symbol.Name)) syms.Add(Symbol.Name);
            }
            var activeSymbols = syms
                .Where(s => !string.IsNullOrWhiteSpace(s))
                .Where(s => !IsChartAllSymbolsSelection(s))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (_masterTimerAccountSnapshotActive)
                _masterTimerActiveSymbolsSnapshot = activeSymbols;
            return activeSymbols;
        }

        private string GetSharedArtifactTimeFrameLabel(TimeFrame timeFrame)
        {
            if (timeFrame == TimeFrame.Minute) return "1";
            if (timeFrame == TimeFrame.Minute5) return "5";
            if (timeFrame == TimeFrame.Minute15) return "15";
            if (timeFrame == TimeFrame.Hour) return "60";
            if (timeFrame == TimeFrame.Hour4) return "240";
            if (timeFrame == TimeFrame.Daily) return "1440";
            return NormalizeTradeTfLabel(timeFrame != null ? timeFrame.ToString() : "");
        }

        private List<Dictionary<string, object>> BuildSharedCanonicalArtifactItems(string symbolName, TimeFrame timeFrame)
        {
            var items = new List<Dictionary<string, object>>();
            var tf = GetSharedArtifactTimeFrameLabel(timeFrame);
            var sourceBars = MarketData.GetBars(timeFrame, symbolName);
            if (sourceBars != null && sourceBars.Count >= 20)
            {
                var structure = BuildStructureSnapshotV2(sourceBars, 180);
                foreach (var swing in structure.Swings)
                {
                    var swingTime = ToUnixSecondsSafe(swing.Time);
                    if (swingTime <= 0) continue;
                    var swingType = swing.IsHigh ? "swing_high" : "swing_low";
                    items.Add(new Dictionary<string, object>
                    {
                        { "id", string.Format(CultureInfo.InvariantCulture, "ctrader|swing|{0}|{1}|{2}", tf, swingType, swingTime) },
                        { "family", "swing" },
                        { "type", swingType },
                        { "subtype", swing.IsHigh ? "high" : "low" },
                        { "label", swing.IsHigh ? "SW" : "SW" },
                        { "timeframe", tf },
                        { "source", "ctrader" },
                        { "origin", "structure_snapshot" },
                        { "status", "active" },
                        { "price", swing.Price },
                        { "anchor_time", swingTime },
                        { "bar_start", swingTime }
                    });
                }

                // Publish the exact equal-high/equal-low references used by candle
                // confluence labels so shared charts can render the referenced level.
                var equalLevelTolerance = Math.Max(Symbol.PipSize * 2.0, 0.0000001);
                foreach (var pattern in DetectSwingLevelPatterns(sourceBars, equalLevelTolerance)
                    .Where(value => value.Type == SwingLevelPatternType.EqualHighs || value.Type == SwingLevelPatternType.EqualLows))
                {
                    var levelTimeA = pattern.IndexA >= 0 && pattern.IndexA < sourceBars.Count
                        ? ToUnixSecondsSafe(sourceBars.OpenTimes[pattern.IndexA])
                        : 0;
                    var levelTimeB = pattern.IndexB >= 0 && pattern.IndexB < sourceBars.Count
                        ? ToUnixSecondsSafe(sourceBars.OpenTimes[pattern.IndexB])
                        : 0;
                    if (levelTimeA <= 0 || levelTimeB <= 0 || !IsFiniteNumber(pattern.Level) || pattern.Level <= 0)
                        continue;
                    var levelType = pattern.Type == SwingLevelPatternType.EqualHighs ? "eqh" : "eql";
                    items.Add(new Dictionary<string, object>
                    {
                        { "id", string.Format(CultureInfo.InvariantCulture, "ctrader|level|{0}|{1}|{2}|{3:0.#####}", tf, levelType, levelTimeB, pattern.Level) },
                        { "family", "structure" },
                        { "type", levelType },
                        { "subtype", pattern.Type == SwingLevelPatternType.EqualHighs ? "high" : "low" },
                        { "label", levelType.ToUpperInvariant() },
                        { "timeframe", tf },
                        { "source", "ctrader" },
                        { "origin", "swing_level_patterns" },
                        { "status", "active" },
                        { "price", pattern.Level },
                        { "anchor_time", levelTimeB },
                        { "bar_start", levelTimeA },
                        { "bar_end", levelTimeB },
                        { "payload", new Dictionary<string, object>
                            {
                                { "first_swing_time", levelTimeA },
                                { "second_swing_time", levelTimeB },
                                { "level", pattern.Level }
                            }
                        }
                    });
                }

                foreach (var zone in structure.Zones)
                {
                    if (zone.State == StructureZoneStateV2.Invalidated || zone.Low >= zone.High)
                        continue;
                    if (zone.OriginBarIndex < 0 || zone.OriginBarIndex >= sourceBars.Count)
                        continue;
                    var originTime = ToUnixSecondsSafe(sourceBars.OpenTimes[zone.OriginBarIndex]);
                    var confirmationIndex = zone.ConfirmationBarIndex >= 0 && zone.ConfirmationBarIndex < sourceBars.Count
                        ? zone.ConfirmationBarIndex
                        : zone.OriginBarIndex;
                    var confirmationTime = ToUnixSecondsSafe(sourceBars.OpenTimes[confirmationIndex]);
                    if (originTime <= 0) continue;
                    var zoneType = zone.Type == StructureZoneTypeV2.InverseFvg
                        ? "ifvg"
                        : zone.Type == StructureZoneTypeV2.OrderBlock
                            ? "ob"
                            : zone.Type == StructureZoneTypeV2.BreakerBlock
                                ? "bb"
                                : "fvg";
                    var zoneLabel = zoneType == "ifvg" ? "IFVG" : zoneType.ToUpperInvariant();
                    items.Add(new Dictionary<string, object>
                    {
                        { "id", string.Format(CultureInfo.InvariantCulture, "ctrader|zone|{0}|{1}|{2}|{3}|{4}", tf, zoneType, originTime, zone.Low.ToString("0.#####", CultureInfo.InvariantCulture), zone.High.ToString("0.#####", CultureInfo.InvariantCulture)) },
                        { "family", "zone" },
                        { "type", zoneType },
                        { "subtype", zone.IsBullish ? "bullish" : "bearish" },
                        { "label", zoneLabel },
                        { "timeframe", tf },
                        { "source", "ctrader" },
                        { "origin", "structure_snapshot" },
                        { "status", zone.State == StructureZoneStateV2.Touched ? "touched" : "active" },
                        { "direction", zone.IsBullish ? "BUY" : "SELL" },
                        { "price_low", zone.Low },
                        { "price_high", zone.High },
                        { "bar_start", originTime },
                        { "bar_end", confirmationTime },
                        { "anchor_time", confirmationTime },
                        { "payload", new Dictionary<string, object>
                            {
                                { "origin_bar_time", originTime },
                                { "confirmation_bar_time", confirmationTime },
                                { "touch_bar_time", zone.TouchBarIndex >= 0 && zone.TouchBarIndex < sourceBars.Count ? ToUnixSecondsSafe(sourceBars.OpenTimes[zone.TouchBarIndex]) : (object)null },
                                { "invalidation_bar_time", zone.InvalidationBarIndex >= 0 && zone.InvalidationBarIndex < sourceBars.Count ? ToUnixSecondsSafe(sourceBars.OpenTimes[zone.InvalidationBarIndex]) : (object)null }
                            }
                        }
                    });
                }
            }

            if (sourceBars != null && sourceBars.Count >= 8)
            {
                var patternDefinitions = BuildEnabledCandlePatternDefinitions();
                var patternMarkers = new List<DirectionalPatternMarkerAggregate>();
                CollectRecentDirectionalCandlePatternMarkersOptimized(
                    patternMarkers,
                    sourceBars,
                    timeFrame,
                    patternDefinitions,
                    Math.Max(0, sourceBars.Count - 180),
                    symbolName);
                foreach (var marker in patternMarkers)
                {
                    var patternIndex = marker.PatternBarIndex >= 0 ? marker.PatternBarIndex : marker.BarIndex;
                    if (patternIndex < 0 || patternIndex >= sourceBars.Count) continue;
                    var patternTime = ToUnixSecondsSafe(sourceBars.OpenTimes[patternIndex]);
                    if (patternTime <= 0) continue;
                    var labels = marker.Labels != null && marker.Labels.Count > 0
                        ? marker.Labels.Distinct(StringComparer.OrdinalIgnoreCase)
                        : new[] { "PAT" };
                    foreach (var label in labels)
                    {
                        var patternType = GetSharedCandlePatternType(label, marker.IsBullish, marker.IsNeutral);
                        var patternPrice = marker.IsNeutral
                            ? (sourceBars.HighPrices[patternIndex] + sourceBars.LowPrices[patternIndex]) * 0.5
                            : marker.IsBullish ? sourceBars.LowPrices[patternIndex] : sourceBars.HighPrices[patternIndex];
                        var interaction = marker.ConfluenceMatches != null
                            ? marker.ConfluenceMatches.FirstOrDefault(match =>
                                match != null &&
                                IsValidCandleConfluenceTimeFrame(marker.SourceTimeFrame, match.SourceTimeFrame) &&
                                IsDirectionalCandleLevelConfluence(match, marker.IsBullish))
                            : null;
                        items.Add(new Dictionary<string, object>
                        {
                            { "id", string.Format(CultureInfo.InvariantCulture, "ctrader|pattern|{0}|{1}|{2}", tf, patternType, patternTime) },
                            { "family", "pattern" },
                            { "is_event", true },
                            { "type", patternType },
                            { "subtype", marker.IsNeutral ? "neutral" : marker.IsBullish ? "bullish" : "bearish" },
                            { "label", FormatCandleMarkerCanonicalEventName(marker) },
                            { "timeframe", tf },
                            { "source", "ctrader" },
                            { "origin", "candle_patterns" },
                            { "status", "active" },
                            { "direction", marker.IsNeutral ? "" : marker.IsBullish ? "BUY" : "SELL" },
                            { "price", patternPrice },
                            { "anchor_time", patternTime },
                            { "bar_start", patternTime },
                            { "payload", new Dictionary<string, object>
                                {
                                    { "short_label", label ?? "" },
                                    { "pattern_span", marker.PatternSpan },
                                    { "pattern_bar_time", patternTime },
                                    { "canonical_name", FormatCandleMarkerCanonicalEventName(marker) },
                                    { "interaction_kind", interaction != null ? interaction.Kind : "" },
                                    { "interaction_timeframe", interaction != null ? GetSharedArtifactTimeFrameLabel(interaction.SourceTimeFrame) : "" },
                                    { "interaction_low", interaction != null ? (object)interaction.Low : null },
                                    { "interaction_high", interaction != null ? (object)interaction.High : null },
                                    { "interaction_price", interaction != null ? (object)((interaction.Low + interaction.High) * 0.5) : null },
                                    { "interaction_bar_time", interaction != null ? patternTime : (object)null }
                                }
                            }
                        });
                    }
                }
            }

            foreach (var evt in GetCanonicalEventsForSymbolTimeFrame(symbolName, timeFrame, 256))
            {
                var eventTime = ToUnixSecondsSafe(evt.BarTime);
                if (eventTime <= 0) continue;
                var direction = evt.IsBullish ? "BUY" : "SELL";
                var eventType = evt.EventType.ToString().ToLowerInvariant();
                var id = string.IsNullOrWhiteSpace(evt.EventKey)
                    ? string.Format(CultureInfo.InvariantCulture, "{0}|{1}|{2}|{3}|{4}", symbolName, tf, eventType, eventTime, evt.PriceRef.ToString("0.#####", CultureInfo.InvariantCulture))
                    : evt.EventKey;
                items.Add(new Dictionary<string, object>
                {
                    { "id", id },
                    { "family", "event" },
                    { "is_event", true },
                    { "type", eventType },
                    { "subtype", evt.IsBullish ? "bullish" : "bearish" },
                    { "label", BuildCanonicalMarketEventName(evt) },
                    { "timeframe", tf },
                    { "source", "ctrader" },
                    { "origin", "canonical_events" },
                    { "status", "active" },
                    { "direction", direction },
                    { "price", evt.PriceRef },
                    { "price_low", evt.ZoneLow > 0 ? evt.ZoneLow : (object)null },
                    { "price_high", evt.ZoneHigh > 0 ? evt.ZoneHigh : (object)null },
                    { "bar_start", eventTime },
                    { "anchor_time", eventTime },
                    { "payload", new Dictionary<string, object>
                        {
                            { "event_key", evt.EventKey ?? "" },
                            { "reason", evt.Reason.ToString() },
                            { "action", evt.Action.ToString() },
                            { "score", evt.Score },
                            { "confidence", evt.Confidence },
                            { "zone_low", evt.ZoneLow },
                            { "zone_high", evt.ZoneHigh }
                        }
                    }
                });
            }
            return items;
        }

        private string GetSharedCandlePatternType(string shortLabel, bool isBullish, bool isNeutral)
        {
            var label = string.IsNullOrWhiteSpace(shortLabel) ? "PAT" : shortLabel.Trim().ToUpperInvariant();
            if (isNeutral) return "candle_pattern";
            switch (label)
            {
                case "PIN": return isBullish ? "bullish_pin_bar" : "bearish_pin_bar";
                case "ENG": return isBullish ? "bullish_engulfing" : "bearish_engulfing";
                case "BIG": return isBullish ? "bullish_big_candle" : "bearish_big_candle";
                case "MOR": return "bullish_morning_star";
                case "EVE": return "bearish_evening_star";
                case "HAM": return "bullish_hammer";
                case "HGM": return "hanging_man";
                case "SST": return "shooting_star";
                case "IHM": return "bullish_inverted_hammer";
                case "PRC": return "bullish_piercing_line";
                case "DCC": return "bearish_dark_cloud_cover";
                case "3WS": return "bullish_three_white_soldiers";
                case "3BC": return "bearish_three_black_crows";
                case "HAR": return isBullish ? "bullish_harami" : "bearish_harami";
                default: return (isBullish ? "bullish_" : "bearish_") + label.ToLowerInvariant();
            }
        }

        private async Task SyncSharedCanonicalArtifactsAsync(string accountId, List<string> symbols)
        {
            var timeFrames = new[]
            {
                TimeFrame.Minute,
                TimeFrame.Minute5,
                TimeFrame.Minute15,
                TimeFrame.Hour,
                TimeFrame.Hour4,
                TimeFrame.Daily
            };
            var artifactGroups = await RunOnMainThreadAsync(() =>
            {
                var groups = new List<Dictionary<string, object>>();
                foreach (var symbol in symbols ?? new List<string>())
                {
                    foreach (var timeFrame in timeFrames)
                    {
                        var items = BuildSharedCanonicalArtifactItems(symbol, timeFrame);
                        if (items.Count == 0) continue;
                        groups.Add(new Dictionary<string, object>
                        {
                            { "symbol", symbol },
                            { "tf", GetSharedArtifactTimeFrameLabel(timeFrame) },
                            { "items", items }
                        });
                    }
                }
                return groups;
            });
            if (artifactGroups == null || artifactGroups.Count == 0) return;

            var result = await RunLocalRuntimeAsync(new Dictionary<string, object>
            {
                { "operation", "artifacts_merge" },
                { "project_root", GetBaseServerRootPath() },
                { "user_id", LocalRuntimeUserId() },
                { "account_id", accountId },
                { "artifacts", artifactGroups }
            });
            SafePrint("[LocalArtifacts] load_merge groups={0} detail={1}", artifactGroups.Count, result);
        }

        // Reads prices on main thread (cTrader API not thread-safe)
        private List<Tuple<string, double, double>> ReadPricesOnMainThread(List<string> symbols)
        {
            var result = new List<Tuple<string, double, double>>();
            foreach (var sym in symbols)
            {
                try
                {
                    Symbol s;
                    if (!TryResolveQuotedSymbol(sym, out s)) continue;
                    double bid = double.IsNaN(s.Bid) ? 0 : s.Bid;
                    double ask = double.IsNaN(s.Ask) ? 0 : s.Ask;
                    result.Add(Tuple.Create(s.Name, bid, ask));
                }
                catch { }
            }
            return result;
        }

        private bool ShouldPushPricesNow(DateTime now)
        {
            return PricePushEnabled && (_lastPriceTime == DateTime.MinValue || (now - _lastPriceTime).TotalSeconds >= PricePushSeconds);
        }

        private void DoTimerWork()
        {
            try
            {
                if (IsBacktestingRuntime())
                    return;

                if (!_syncOnly)
                {
                    _pollCount++;
                    if (_pollCount <= 3) SafePrint("[Diag] OnTimer tick #" + _pollCount);
                    if (_pollCount % 10 == 0) CleanupOldEntries();
                }

                if (!_syncOnly && _consecutiveErrors > 0)
                {
                    int backoffSeconds = Math.Min(30, (int)Math.Pow(2, _consecutiveErrors - 1));
                    if (backoffSeconds > PollSeconds)
                    {
                        SafePrint("[Backoff] Skipping poll cycle for {0}s due to {1} consecutive errors", backoffSeconds, _consecutiveErrors);
                        return;
                    }
                }

                var accId = Account.UserId.ToString();

                if (!_syncOnly)
                {
                    // --- OHLC Bar push (every BarPushSeconds) ---
                    if (IsBarsPersistenceEnabled() && BarPushEnabled)
                    {
                        if (_lastBarTime == DateTime.MinValue ||
                            (DateTime.Now - _lastBarTime).TotalSeconds >= BarPushSeconds)
                        {
                            _barStatus = "PUSHING";
                            var syms = _trackedSymbols.Count > 0 ? _trackedSymbols : new List<string>();
                            if (syms.Count == 0)
                            {
                                foreach (var pos in Positions)
                                    if (!string.IsNullOrWhiteSpace(pos.SymbolName) && !syms.Contains(pos.SymbolName))
                                        syms.Add(pos.SymbolName);
                                foreach (var order in PendingOrders)
                                    if (!string.IsNullOrWhiteSpace(order.SymbolName) && !syms.Contains(order.SymbolName))
                                        syms.Add(order.SymbolName);
                                if (Symbol != null && !string.IsNullOrWhiteSpace(Symbol.Name) && !syms.Contains(Symbol.Name))
                                    syms.Add(Symbol.Name);
                            }
                            if (syms.Count > 0)
                                _ = Task.Run(async () =>
                                {
                                    try { await PushBarsAsync(accId, syms); }
                                    catch (Exception ex) { SafePrint("[Bars] Push failed: {0}", ex.Message); }
                                });
                            else
                            {
                                _barStatus = "IDLE";
                                _lastBarTime = DateTime.Now;
                            }
                        }
                    }

                    // --- Incremental bars sync (every IncrementalBarsSeconds) ---
                    if (IsBarsPersistenceEnabled() && EnableIncrementalBars)
                    {
                        if (CTraderSyncEngine.IsDue(DateTime.Now, _lastIncrementalSync, IncrementalBarsSeconds))
                        {
                            var incSyms = _trackedSymbols.Count > 0 ? _trackedSymbols : new List<string>();
                            if (incSyms.Count == 0)
                            {
                                foreach (var pos in Positions)
                                    if (!string.IsNullOrWhiteSpace(pos.SymbolName) && !incSyms.Contains(pos.SymbolName))
                                        incSyms.Add(pos.SymbolName);
                                if (Symbol != null && !string.IsNullOrWhiteSpace(Symbol.Name) && !incSyms.Contains(Symbol.Name))
                                    incSyms.Add(Symbol.Name);
                            }
                            if (incSyms.Count > 0)
                                Task.Run(async () => await SyncBarsIncrementalAsync(accId, incSyms));
                            _lastIncrementalSync = DateTime.Now;
                        }
                    }

                    // --- Sync: build payload + push to VPS (every SyncIntervalSeconds) ---
                    var now = DateTime.Now;
                    var doSync = CTraderSyncEngine.IsDue(now, _lastSyncTime, SyncIntervalSeconds);
                    // Always pull signals on PollSeconds cadence

                    string balance = null, equity = null, margin = null, brokerName = null;
                    List<string> posList = null, ordersList = null, closedList = null, metricsList = null;
                    HashSet<string> activeTicketIds = null;

                    if (doSync)
                    {
                        balance = Account.Balance.ToString(CultureInfo.InvariantCulture);
                        equity = Account.Equity.ToString(CultureInfo.InvariantCulture);
                        margin = Account.Margin.ToString(CultureInfo.InvariantCulture);
                        brokerName = Account.BrokerName;
                        posList = new List<string>();
                        activeTicketIds = new HashSet<string>(Positions.Select(p => p.Id.ToString()));

                        foreach (var pos in Positions)
                        {
                            var sid = ResolveSid(pos.Id.ToString(), pos.Comment).Replace("\"", "'");
                            var s = ResolveLoadedSymbol(pos.SymbolName);
                            double lotsVal = (s != null) ? s.VolumeInUnitsToQuantity(pos.VolumeInUnits) : (pos.VolumeInUnits / 100000.0);

                            double tpPnl = 0;
                            double slPnl = 0;
                            double distanceTp = 0;
                            double distanceSl = 0;
                            double spreadVal = 0;
                            if (s != null)
                            {
                                spreadVal = double.IsNaN(s.Spread) ? 0 : s.Spread;
                                if (pos.TakeProfit.HasValue)
                                {
                                    double pips = (pos.TakeProfit.Value - pos.EntryPrice) / s.PipSize;
                                    if (pos.TradeType == TradeType.Sell) pips = -pips;
                                    tpPnl = EstimatePnlFromPips(s, pips, pos.VolumeInUnits);
                                    distanceTp = Math.Abs(pips);
                                }
                                if (pos.StopLoss.HasValue)
                                {
                                    double pips = (pos.StopLoss.Value - pos.EntryPrice) / s.PipSize;
                                    if (pos.TradeType == TradeType.Sell) pips = -pips;
                                    slPnl = EstimatePnlFromPips(s, pips, pos.VolumeInUnits);
                                    distanceSl = Math.Abs(pips);
                                }
                            }
                            double balanceTp = tpPnl;
                            double balanceSl = slPnl;

                            var ticketKey = pos.Id.ToString();
                            double partialClosedVol = 0;
                            _partialClosedVolumes.TryGetValue(ticketKey, out partialClosedVol);
                            double remainingVol = double.IsNaN(pos.VolumeInUnits) ? 0 : pos.VolumeInUnits;
                            bool hasPartial = partialClosedVol > 0;

                            var syncSource = ResolveSyncedTradeSource(pos.Label, pos.Comment);
                            posList.Add("{\"sid\":\"" + sid + "\"" +
                                ",\"comment\":\"" + EscapeJson(pos.Comment) + "\"" +
                                ",\"source\":\"" + EscapeJson(syncSource) + "\"" +
                                ",\"ticket\":\"" + pos.Id + "\"" +
                                ",\"symbol\":\"" + pos.SymbolName + "\"" +
                                ",\"side\":\"" + pos.TradeType.ToString().ToUpper() + "\"" +
                                ",\"type\":\"MARKET\"" +
                                ",\"entry\":" + (double.IsNaN(pos.EntryPrice) ? 0 : pos.EntryPrice).ToString("F5", CultureInfo.InvariantCulture) +
                                ",\"sl\":" + (pos.StopLoss ?? 0).ToString("F5", CultureInfo.InvariantCulture) +
                                ",\"tp\":" + (pos.TakeProfit ?? 0).ToString("F5", CultureInfo.InvariantCulture) +
                                ",\"volume\":" + (double.IsNaN(pos.VolumeInUnits) ? 0 : pos.VolumeInUnits).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"lots\":" + (double.IsNaN(lotsVal) ? 0 : lotsVal).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"pnl\":" + (double.IsNaN(pos.NetProfit) ? 0 : pos.NetProfit).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"pips\":" + (double.IsNaN(pos.Pips) ? 0 : pos.Pips).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"commission\":" + (double.IsNaN(pos.Commissions) ? 0 : pos.Commissions).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"swap\":" + (double.IsNaN(pos.Swap) ? 0 : pos.Swap).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"margin\":" + (double.IsNaN(pos.Margin) ? 0 : pos.Margin).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"tp_pnl\":" + (double.IsNaN(tpPnl) ? 0 : tpPnl).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"sl_pnl\":" + (double.IsNaN(slPnl) ? 0 : slPnl).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"spread\":" + spreadVal.ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"distance_sl\":" + distanceSl.ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"distance_tp\":" + distanceTp.ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"balance_sl\":" + balanceSl.ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"balance_tp\":" + balanceTp.ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"label\":\"" + pos.Label + "\"" +
                                ",\"status\":\"OPEN\"" +
                                ",\"remaining_volume\":" + remainingVol.ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"closed_volume_partial\":" + partialClosedVol.ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"has_partial\":" + (hasPartial ? "true" : "false") + "}");
                        }

                        closedList = new List<string>();
                        var limit = DateTime.UtcNow.AddDays(-2);
                        // Filter before sorting: accounts can have a large complete history, but
                        // the broker sync only needs the newest two days and at most 20 deals.
                        var historicalDeals = History
                            .Where(d => d.ClosingTime >= limit)
                            .OrderByDescending(d => d.ClosingTime)
                            .Take(20)
                            .ToList();
                        foreach (var deal in historicalDeals)
                        {
                            if (_syncedClosedTickets.Contains(deal.PositionId.ToString())) continue;
                            var sid2 = ResolveSid(deal.PositionId.ToString(), deal.Comment).Replace("\"", "'");
                            string closeReason = "MANUAL_CLOSE";
                            var syncSourceClosed = ResolveSyncedTradeSource(deal.Label, deal.Comment);
                            closedList.Add("{\"sid\":\"" + sid2 + "\"" +
                                ",\"comment\":\"" + EscapeJson(deal.Comment) + "\"" +
                                ",\"source\":\"" + EscapeJson(syncSourceClosed) + "\"" +
                                ",\"ticket\":\"" + deal.PositionId + "\"" +
                                ",\"symbol\":\"" + deal.SymbolName + "\"" +
                                ",\"symbol_code\":\"" + deal.SymbolName + "\"" +
                                ",\"side\":\"" + deal.TradeType.ToString().ToUpper() + "\"" +
                                ",\"volume\":" + (double.IsNaN(deal.VolumeInUnits) ? 0 : deal.VolumeInUnits).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"pnl\":" + (double.IsNaN(deal.NetProfit) ? 0 : deal.NetProfit).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"pips\":0.0" +
                                ",\"commission\":" + (double.IsNaN(deal.Commissions) ? 0 : deal.Commissions).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"swap\":" + (double.IsNaN(deal.Swap) ? 0 : deal.Swap).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"status\":\"CLOSED\"" +
                                ",\"close_reason\":\"" + closeReason + "\"" +
                                ",\"closed_at\":\"" + deal.ClosingTime.ToString("O") + "\"" +
                                ",\"label\":\"" + deal.Label + "\"}");
                        }

                        ordersList = new List<string>();

                        foreach (var order in PendingOrders)
                        {
                            var sid3 = ResolveSid(order.Id.ToString(), order.Comment).Replace("\"", "'");
                            var s2 = ResolveLoadedSymbol(order.SymbolName);
                            double lotsVal2 = (s2 != null) ? s2.VolumeInUnitsToQuantity(order.VolumeInUnits) : (order.VolumeInUnits / 100000.0);
                            double pnlTp = 0, pnlSl = 0;
                            if (s2 != null)
                            {
                                if (order.TakeProfit.HasValue) { double pp = Math.Abs(order.TargetPrice - order.TakeProfit.Value) / s2.PipSize; pnlTp = EstimatePnlFromPips(s2, pp, order.VolumeInUnits); }
                                if (order.StopLoss.HasValue) { double pp = Math.Abs(order.TargetPrice - order.StopLoss.Value) / s2.PipSize; pnlSl = -EstimatePnlFromPips(s2, pp, order.VolumeInUnits); }
                            }
                            var syncSourceOrder = ResolveSyncedTradeSource(order.Label, order.Comment);
                            ordersList.Add("{\"sid\":\"" + sid3 + "\"" +
                                ",\"comment\":\"" + EscapeJson(order.Comment) + "\"" +
                                ",\"source\":\"" + EscapeJson(syncSourceOrder) + "\"" +
                                ",\"ticket\":\"" + order.Id + "\"" +
                                ",\"symbol\":\"" + order.SymbolName + "\"" +
                                ",\"side\":\"" + order.TradeType.ToString().ToUpper() + "\"" +
                                ",\"type\":\"" + order.OrderType.ToString().ToUpper() + "\"" +
                                ",\"target_price\":" + order.TargetPrice.ToString("F5", CultureInfo.InvariantCulture) +
                                ",\"entry\":" + order.TargetPrice.ToString("F5", CultureInfo.InvariantCulture) +
                                ",\"sl\":" + (order.StopLoss ?? 0).ToString("F5", CultureInfo.InvariantCulture) +
                                ",\"tp\":" + (order.TakeProfit ?? 0).ToString("F5", CultureInfo.InvariantCulture) +
                                ",\"volume\":" + (double.IsNaN(order.VolumeInUnits) ? 0 : order.VolumeInUnits).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"lots\":" + (double.IsNaN(lotsVal2) ? 0 : lotsVal2).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"label\":\"" + order.Label + "\"" +
                                ",\"status\":\"PENDING\"" +
                                ",\"margin\":0.0" +
                                ",\"pnl_tp\":" + pnlTp.ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"pnl_sl\":" + pnlSl.ToString("F2", CultureInfo.InvariantCulture) + "}");
                        }

                        var symbolsToSync = new HashSet<string>();
                        foreach (var activeSymbol in GetActiveSymbols())
                            if (!string.IsNullOrWhiteSpace(activeSymbol)) symbolsToSync.Add(activeSymbol);

                        metricsList = new List<string>();
                        foreach (var symbolName in symbolsToSync.Take(100))
                        {
                            var s3 = ResolveLoadedSymbol(symbolName);
                            if (s3 == null) continue;
                            metricsList.Add("{\"symbol\":\"" + s3.Name + "\"" +
                                ",\"pip_value\":" + (double.IsNaN(s3.PipValue) ? 0 : s3.PipValue).ToString("F5", CultureInfo.InvariantCulture) +
                                ",\"spread\":" + (double.IsNaN(s3.Spread) ? 0 : s3.Spread).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"min_vol\":" + (double.IsNaN(s3.VolumeInUnitsMin) ? 0 : s3.VolumeInUnitsMin).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"step_vol\":" + (double.IsNaN(s3.VolumeInUnitsStep) ? 0 : s3.VolumeInUnitsStep).ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"pip_size\":" + (double.IsNaN(s3.PipSize) ? 0 : s3.PipSize).ToString("F8", CultureInfo.InvariantCulture) +
                                ",\"min_stop_pips\":" + MinStopPips.ToString("F2", CultureInfo.InvariantCulture) +
                                ",\"min_stop_price_distance\":" + ((double.IsNaN(s3.PipSize) ? 0 : s3.PipSize) * MinStopPips).ToString("F8", CultureInfo.InvariantCulture) +
                                ",\"digits\":" + s3.Digits + "}");
                        }

                        // Show that a new cycle has started, but keep last successful stamps.
                        _pollStatus = _lastPollTime == DateTime.MinValue ? "POLLING" : _pollStatus;
                        _syncStatus = _lastSyncTime == DateTime.MinValue ? "SYNCING" : _syncStatus;
                    }
                    RefreshDebugPanelNow(false);

                    var bal = balance; var eq = equity; var mar = margin; var brk = brokerName;
                    var pl = posList; var ol = ordersList; var cl = closedList; var ml = metricsList;
                    var ati = activeTicketIds;
                    var syncSymbols = GetActiveSymbols();
                    var includePrices = ShouldPushPricesNow(DateTime.Now);
                    var priceData = includePrices ? ReadPricesOnMainThread(syncSymbols) : new List<Tuple<string, double, double>>();
                    if (includePrices && priceData.Count == 0)
                    {
                        _priceStatus = "IDLE";
                        _lastPriceErr = "No prices available";
                    }
                    var spd = priceData;
                    var ssl = syncSymbols;
                    var queueActionsJson = doSync && pl != null ? BuildStrategyQueueActionsSyncJson() : "[]";
                    var queueTerminalKeys = doSync && pl != null
                        ? _strategyQueueTerminalUpdates.Keys.ToList()
                        : new List<string>();
                    var queueSnapshotComplete = _strategyQueueHydratedFromServer;

                    Task.Run(async () =>
                    {
                        try
                        {
                            await PollSignalsAsync(accId);
                            if (doSync && pl != null)
                            {
                                double b, e, m;
                                if (!double.TryParse(bal, NumberStyles.Any, CultureInfo.InvariantCulture, out b)) b = 0;
                                if (!double.TryParse(eq, NumberStyles.Any, CultureInfo.InvariantCulture, out e)) e = 0;
                                if (!double.TryParse(mar, NumberStyles.Any, CultureInfo.InvariantCulture, out m)) m = 0;
                                await SyncWithVpsAsync(accId, b, e, m, brk, pl, ol, cl, ati, ml, spd, ssl, queueActionsJson, queueTerminalKeys, queueSnapshotComplete);
                            }
                        }
                        catch (Exception ex)
                        {
                            _lastSyncErr = FormatServerErrorForPanel(ex.Message);
                            _syncStatus = "ERROR";
                        }
                        finally
                        {
                            RefreshDebugPanelLite();
                        }
                    });
                }
                else
                {
                    // Sync-only: build full payload (positions + orders + closed + metrics)
                    BuildAndDispatchSync(accId);
                }
            }
            catch (Exception ex)
            {
                _serverStatus = "CLIENT_ERR";
                _apiStatus = "PREP_ERR";
                _pollStatus = "ERROR";
                _syncStatus = "ERROR";
                _lastPollErr = FormatServerErrorForPanel(ex.Message);
                _lastSyncErr = FormatServerErrorForPanel(ex.Message);
                RefreshDebugPanelNow(false);
            }
        }

        protected override void OnStop()
        {
            try { Positions.Closed -= OnStrategyPositionClosed; } catch { }
            try
            {
                var uptimeSeconds = _startedAtUtc == DateTime.MinValue
                    ? 0
                    : Math.Max(0, (int)Math.Round((DateTime.UtcNow - _startedAtUtc).TotalSeconds));
                SafePrint(
                    "[BotStop] OnStop reason={0} live={1} backtest={2} uptime_sec={3} symbol={4} tf={5}",
                    string.IsNullOrWhiteSpace(_lastStopReason) ? "external_or_unknown" : _lastStopReason,
                    EnableLiveStrategyTrading,
                    IsBacktestingRuntime(),
                    uptimeSeconds,
                    Chart != null ? Chart.SymbolName : (Symbol != null ? Symbol.Name : ""),
                    Chart != null ? Chart.TimeFrame.ToString() : "");
            }
            catch
            {
            }
            WaitForCustomUiSettingsPersistence();
            PersistWaitConfirmQueueLocal();
            if (DisableOnStopCleanupForIsolation)
            {
                try { _watchdogCts?.Cancel(); } catch { }
                try { _watchdogCts?.Dispose(); } catch { }
                try { Chart.RemoveObject("Bridge_Isolation_Status"); } catch { }
                try { RemoveManagedOscillatorIndicators(); } catch { }
                return;
            }
            try { FinalizeBacktestExportSession(); } catch { }
            try { FlushPersistedCanonicalEventCachesToDisk(true); } catch { }
            try { FlushAnalysisCachesHourly(true); } catch { }
            try { _watchdogCts?.Cancel(); } catch { }
            try { _watchdogCts?.Dispose(); } catch { }
            try { Chart.RemoveObject("Bridge_Isolation_Status"); } catch { }
            // Remove all bot-drawn chart objects so stopping leaves a clean chart instead of
            // stale markers/zones/grids from the last session.
            try { RemoveChartVisualObjects(); } catch { }
            try { if (_chartButtonPanel != null) Chart.RemoveControl(_chartButtonPanel); } catch { }
            try { if (_chartSummaryPanel != null) Chart.RemoveControl(_chartSummaryPanel); } catch { }
            try { RemoveManagedOscillatorIndicators(); } catch { }
        }

        private int FindBarIndexAtOrAfter(DateTime time)
        {
            if (Bars == null || Bars.Count == 0 || time == DateTime.MinValue)
                return -1;

            for (var i = 0; i < Bars.Count; i++)
            {
                if (Bars.OpenTimes[i] >= time)
                    return i;
            }

            return -1;
        }

        // Apply the dynamic zoom window: the right edge is anchored at today + tomorrow
        // (the HTF mini chart area) and extra days extend into the past, so the viewport
        // always fills with real bars instead of empty future space.
        private void ApplyZoomWindow(double days)
        {
            var anchorTime = GetCurrentChartEndTime();
            var todayStart = GetCurrentDayStartTime(anchorTime);
            DateTime startTime;
            DateTime endTime;
            if (days <= 1)
            {
                startTime = todayStart;
                endTime = todayStart.AddDays(1);
            }
            else
            {
                // Right edge = the HTF mini chart's right edge so the strip is always fully
                // framed (no cut, no dead space). Extra days extend the window to the left,
                // clamped so today's bars stay visible at the left edge.
                var chartTfMinutes = Math.Max(1, TimeFrameToMinutes(Chart != null ? Chart.TimeFrame : TimeFrame.Minute));
                endTime = anchorTime.AddMinutes(GetMiniChartTotalFutureBars(chartTfMinutes) * chartTfMinutes);
                startTime = endTime.AddDays(-days);
                if (startTime > todayStart)
                    startTime = todayStart;
            }

            ZoomChartToWindow(startTime, endTime - startTime);
        }

        // Zoom the platform chart so the viewport spans the given time window from the
        // window's first bar (left edge), including the future HTF mini-chart area:
        //   "-" → today + HTF mini chart (fills viewport width)
        //   "+" → this week + tomorrow (8 days).
        // The target zoom is computed ABSOLUTELY from a fixed calibration (captured when the
        // chart naturally fills the viewport), never relatively from the current zoom state -
        // otherwise clicking "+" then "-" leaves the old zoomed-out scale and shows empty days.
        private void ZoomChartToWindow(DateTime startTime, TimeSpan duration)
        {
            if (Chart == null || Bars == null || Bars.Count == 0)
                return;

            try
            {
                var chartTfMinutes = Math.Max(1, TimeFrameToMinutes(Chart != null ? Chart.TimeFrame : TimeFrame.Minute));
                var endTime = startTime + duration;
                var startIndex = FindBarIndexAtOrAfter(startTime);
                if (startIndex < 0)
                    startIndex = 0;

                // Target the number of chart-TF bar slots inside the requested window so the
                // viewport shows the full time span (including the future mini-chart area).
                var windowMinutes = Math.Max(1.0, (endTime - startTime).TotalMinutes);
                var targetBars = Math.Max(10, (int)Math.Round(windowMinutes / chartTfMinutes));

                var currentLevel = Math.Max(
                    ChartZoomPresetMinLevel,
                    Math.Min(ChartZoomPresetMaxLevel, Chart.ZoomLevel));

                // Lazy calibration on first use: the natural chart view fills the viewport
                // with bars, so MaxVisibleBars equals the true slot count at that level.
                if (_zoomCalibrationLevel <= 0)
                {
                    _zoomCalibrationLevel = currentLevel;
                    _zoomCalibrationVisibleBars = Math.Max(1, Chart.MaxVisibleBars);
                }

                // Absolute target: level × slots is constant, so the target depends only on
                // the fixed calibration and the requested window - NOT on the current zoom.
                var targetLevel = (int)Math.Round(_zoomCalibrationLevel * (_zoomCalibrationVisibleBars / targetBars));
                // ZoomLevel only accepts multiples of 5 within [5, 500].
                targetLevel = Math.Max(
                    ChartZoomPresetMinLevel,
                    Math.Min(ChartZoomPresetMaxLevel, ((targetLevel + 2) / 5) * 5));
                if (targetLevel != currentLevel)
                    Chart.ZoomLevel = targetLevel;

                Chart.ScrollXTo(startIndex);
            }
            catch (Exception ex)
            {
                SafePrint("[Chart] Zoom preset failed: {0}", ex.Message);
            }
        }

        private void BuildChartButtonPanel()
        {
            try
            {
                _isRebuildingChartPanel = true;
                if (_chartButtonPanel != null)
                {
                    try { Chart.RemoveControl(_chartButtonPanel); } catch { }
                }

                if (!AreChartVisualsEnabled())
                {
                    _chartButtonPanel = null;
                    return;
                }

                _chartButtonPanel = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    HorizontalAlignment = HorizontalAlignment.Left,
                    VerticalAlignment = VerticalAlignment.Bottom,
                    Margin = 6,
                    Opacity = 0.85
                };
                _chartSymbolsSignature = "";

                TryAddChartSymbolCombo(_chartButtonPanel);
                TryAddChartDirectionCombo(_chartButtonPanel);
                TryAddChartOrderCountCombo(_chartButtonPanel);

                var preferredToolbarSymbol = Chart != null && !string.IsNullOrWhiteSpace(Chart.SymbolName)
                    ? Chart.SymbolName
                    : _chartSelectedSymbol;
                var selectedToolbarSymbol = EnsureChartSelectedSymbol(preferredToolbarSymbol);
                var entryToolbarSymbol = GetEffectiveChartEntrySymbolSelection();
                var selectedDirection = ReadChartDirectionComboSelection();
                var isAllSymbolsSelected = IsChartAllSymbolsSelection(selectedToolbarSymbol);
                var hasConcreteEntrySymbol = !string.IsNullOrWhiteSpace(entryToolbarSymbol) && !IsChartAllSymbolsSelection(entryToolbarSymbol);
                var hasSelectedOpenPositions = SymbolHasOpenPositions(selectedToolbarSymbol, selectedDirection);
                var hasSelectedPendingOrders = SymbolHasPendingOrders(selectedToolbarSymbol, selectedDirection);
                var allowDirectionalManagement = !string.Equals(selectedDirection, "All", StringComparison.OrdinalIgnoreCase);
                Print(string.Format(CultureInfo.InvariantCulture, "[Click] Panel build: chart='{0}' selected='{1}' entry='{2}' addTrade={3} open={4} pending={5} dir='{6}'", preferredToolbarSymbol, selectedToolbarSymbol, entryToolbarSymbol, hasConcreteEntrySymbol, hasSelectedOpenPositions, hasSelectedPendingOrders, selectedDirection));

                if (hasConcreteEntrySymbol)
                {
                    var buyButton = BuildChartActionButton("B", Color.White, Color.ForestGreen, 28);
                    ApplyButtonTooltip(buyButton, "Buy market order using current chart trade settings");
                    buyButton.Click += _ => ExecuteChartQuickMarketOrder(TradeType.Buy);
                    _chartButtonPanel.AddChild(buyButton);

                    var sellButton = BuildChartActionButton("S", Color.White, Color.Firebrick, 28);
                    ApplyButtonTooltip(sellButton, "Sell market order using current chart trade settings");
                    sellButton.Click += _ => ExecuteChartQuickMarketOrder(TradeType.Sell);
                    _chartButtonPanel.AddChild(sellButton);

                    var buyLimitButton = BuildChartTintedFilledButton("B.l", Color.ForestGreen, 34);
                    ApplyButtonTooltip(buyLimitButton, "Place buy split limit ladder from structure/key-level logic");
                    buyLimitButton.Click += _ => ExecuteChartQuickPendingOrder(TradeType.Buy, false, true);
                    _chartButtonPanel.AddChild(buyLimitButton);

                    var sellLimitButton = BuildChartTintedFilledButton("S.l", Color.Firebrick, 34);
                    ApplyButtonTooltip(sellLimitButton, "Place sell split limit ladder from structure/key-level logic");
                    sellLimitButton.Click += _ => ExecuteChartQuickPendingOrder(TradeType.Sell, false, true);
                    _chartButtonPanel.AddChild(sellLimitButton);

                    var buyStopButton = BuildChartTintedFilledButton("B.s", Color.ForestGreen, 34);
                    ApplyButtonTooltip(buyStopButton, "Place buy stop order from structure/key-level logic");
                    buyStopButton.Click += _ => ExecuteChartQuickPendingOrder(TradeType.Buy, true, false);
                    _chartButtonPanel.AddChild(buyStopButton);

                    var sellStopButton = BuildChartTintedFilledButton("S.s", Color.Firebrick, 34);
                    ApplyButtonTooltip(sellStopButton, "Place sell stop order from structure/key-level logic");
                    sellStopButton.Click += _ => ExecuteChartQuickPendingOrder(TradeType.Sell, true, false);
                    _chartButtonPanel.AddChild(sellStopButton);
                }

                if (hasSelectedOpenPositions || hasSelectedPendingOrders)
                {
                    if (!isAllSymbolsSelected && allowDirectionalManagement && (hasSelectedOpenPositions || hasSelectedPendingOrders))
                    {
                        var slMinusButton = BuildChartOutlineButton("SL -", Color.OrangeRed, 36);
                        ApplyButtonTooltip(slMinusButton, "Move stop loss farther away");
                        slMinusButton.Click += _ => ShiftChartProtection(true, true);
                        _chartButtonPanel.AddChild(slMinusButton);

                        var slPlusButton = BuildChartOutlineButton("SL +", Color.SaddleBrown, 36);
                        ApplyButtonTooltip(slPlusButton, "Move stop loss closer");
                        slPlusButton.Click += _ => ShiftChartProtection(true, false);
                        _chartButtonPanel.AddChild(slPlusButton);

                        var clearSlButton = BuildChartOutlineButton("SLx", Color.Gray, 32);
                        ApplyButtonTooltip(clearSlButton, "Remove stop loss from selected positions and pending orders");
                        clearSlButton.Click += _ => ClearChartProtection(true);
                        _chartButtonPanel.AddChild(clearSlButton);

                        var tpMinusButton = BuildChartOutlineButton("TP -", Color.DeepSkyBlue, 36);
                        ApplyButtonTooltip(tpMinusButton, "Move take profit closer");
                        tpMinusButton.Click += _ => ShiftChartProtection(false, true);
                        _chartButtonPanel.AddChild(tpMinusButton);

                        var tpPlusButton = BuildChartOutlineButton("TP +", Color.MidnightBlue, 36);
                        ApplyButtonTooltip(tpPlusButton, "Move take profit farther away");
                        tpPlusButton.Click += _ => ShiftChartProtection(false, false);
                        _chartButtonPanel.AddChild(tpPlusButton);

                        var clearTpButton = BuildChartOutlineButton("TPx", Color.Gray, 32);
                        ApplyButtonTooltip(clearTpButton, "Remove take profit from selected positions and pending orders");
                        clearTpButton.Click += _ => ClearChartProtection(false);
                        _chartButtonPanel.AddChild(clearTpButton);

                        var syncButton = BuildChartOutlineButton("Sync", Color.SteelBlue, 40);
                        ApplyButtonTooltip(syncButton, "Sync SL and TP with current chart trade plan");
                        syncButton.Click += _ => SyncChartSymbolProtection();
                        _chartButtonPanel.AddChild(syncButton);
                    }

                    if (hasSelectedOpenPositions)
                    {
                        var closeThirtyButton = BuildChartOutlineButton("C.30%", Color.DarkKhaki, 44);
                        ApplyButtonTooltip(closeThirtyButton, "Close 30% of selected open positions");
                        closeThirtyButton.Click += _ => CloseChartSymbolPositions(30);
                        _chartButtonPanel.AddChild(closeThirtyButton);

                        var closeHalfButton = BuildChartOutlineButton("C.50%", Color.Goldenrod, 44);
                        ApplyButtonTooltip(closeHalfButton, "Close 50% of selected open positions");
                        closeHalfButton.Click += _ => CloseChartSymbolPositions(50);
                        _chartButtonPanel.AddChild(closeHalfButton);

                        var closeAllButton = BuildChartOutlineButton("C.all", Color.DarkRed, 42);
                        ApplyButtonTooltip(closeAllButton, "Close 100% of selected open positions");
                        closeAllButton.Click += _ => CloseChartSymbolPositions(100);
                        _chartButtonPanel.AddChild(closeAllButton);
                    }

                    if (hasSelectedPendingOrders)
                    {
                        var cancelOrdersButton = BuildChartOutlineButton("C.order", Color.IndianRed, 52);
                        ApplyButtonTooltip(cancelOrdersButton, "Cancel selected pending orders");
                        cancelOrdersButton.Click += _ => CancelChartSymbolPendingOrders();
                        _chartButtonPanel.AddChild(cancelOrdersButton);
                    }
                }

                var zoomInButton = BuildChartOutlineButton("-", Color.SteelBlue, 26);
                ApplyButtonTooltip(zoomInButton, "Zoom in: one day less per chart width");
                zoomInButton.Click += _ =>
                {
                    _zoomWindowDays = Math.Max(1, _zoomWindowDays - 1);
                    ApplyZoomWindow(_zoomWindowDays);
                };
                _chartButtonPanel.AddChild(zoomInButton);

                var zoomOutButton = BuildChartOutlineButton("+", Color.SteelBlue, 26);
                ApplyButtonTooltip(zoomOutButton, "Zoom out: one day more per chart width");
                zoomOutButton.Click += _ =>
                {
                    _zoomWindowDays = Math.Min(8, _zoomWindowDays + 1);
                    ApplyZoomWindow(_zoomWindowDays);
                };
                _chartButtonPanel.AddChild(zoomOutButton);

                var refreshButton = BuildChartOutlineButton("R", Color.SteelBlue, 26);
                ApplyButtonTooltip(refreshButton, "Recalculate and redraw all zones, artifacts, technicals, events, candles in the current view");
                refreshButton.Click += _ => ForceRefreshChartVisuals();
                _chartButtonPanel.AddChild(refreshButton);

                Chart.AddControl(_chartButtonPanel);
            }
            catch (Exception ex)
            {
                SafeLog("ERROR", "[Panel] Button panel failed: {0}", ex.Message);
            }
            finally
            {
                _isRebuildingChartPanel = false;
            }
        }

        private void RebuildChartButtonPanel()
        {
            try
            {
                BuildChartButtonPanel();
            }
            catch (Exception ex)
            {
                SafeLog("ERROR", "[Panel] Rebuild failed: {0}", ex.Message);
            }
        }

        private void RefreshChartToSelectedSymbol()
        {
            try
            {
                var symbolName = ReadChartSymbolComboSelection();
                if (string.IsNullOrWhiteSpace(symbolName)) return;
                if (IsChartAllSymbolsSelection(symbolName)) return;

                var timeFrame = Chart.TimeFrame;
                var changed = Chart.TryChangeTimeFrameAndSymbol(timeFrame, symbolName);
                if (!changed)
                    SafePrint("[Panel] Chart switch skipped for {0}", symbolName);
            }
            catch (Exception ex)
            {
                SafeLog("ERROR", "[Panel] Chart refresh failed: {0}", ex.Message);
            }
        }

