        private static Color GetSummaryMetricColor(double value, bool inverse = false)
        {
            var positiveColor = Color.LimeGreen;
            var negativeColor = Color.OrangeRed;
            var neutralColor = Color.LightGray;

            if (Math.Abs(value) <= 0.0000001)
                return neutralColor;

            if (inverse)
                return value > 0 ? negativeColor : positiveColor;

            return value > 0 ? positiveColor : negativeColor;
        }

        private static string FormatSummaryPair(double currentValue, double limitValue, string suffix = "%")
        {
            var currentText = FormatDashboardPercent(currentValue);
            var limitText = limitValue > 0 ? FormatDashboardPercent(limitValue) : "-";
            return string.Format(CultureInfo.InvariantCulture, "{0}{2}/{1}{2}", currentText, limitText, suffix);
        }

        private static string FormatSummaryMoney(double value)
        {
            if (double.IsNaN(value) || double.IsInfinity(value))
                return "-";

            if (Math.Abs(value) >= 1000)
                return Math.Round(value, 0, MidpointRounding.AwayFromZero).ToString("0", CultureInfo.InvariantCulture);

            return value.ToString("0.##", CultureInfo.InvariantCulture);
        }

        private StructureBias DetectStructureBias(Bars sourceBars, int lookbackBars)
        {
            var score = DetectStructureBiasScore(sourceBars, lookbackBars);
            if (score >= 2)
                return StructureBias.Bullish;
            if (score <= -2)
                return StructureBias.Bearish;

            return StructureBias.Neutral;
        }

        private int DetectStructureBiasScore(Bars sourceBars, int lookbackBars, int endIndex = -1)
        {
            var lastClosedBarIndex = ResolveStructureLastClosedBarIndex(sourceBars, endIndex);
            if (lastClosedBarIndex < 0)
                return 0;
            var swings = CollectConfirmedSwings(sourceBars, lookbackBars, endIndex);
            return _structureEngine.CalculateBiasScore(
                swings.Select(value => new FortyTwo.Trading.Analysis.SwingInfo
                {
                    Index = value.BarIndex,
                    Price = value.Price,
                    IsHigh = value.IsHigh,
                    TimeUtc = value.Time
                }),
                sourceBars.ClosePrices[lastClosedBarIndex]);
        }

        private bool TryDetectRecentSweepBiasScore(Bars sourceBars, TimeFrame sourceTimeFrame, int lookbackBars, out int biasScore, int endIndex = -1)
        {
            biasScore = 0;
            if (sourceBars == null || sourceBars.Count < 8)
                return false;

            var lastClosedBarIndex = ResolveStructureLastClosedBarIndex(sourceBars, endIndex);
            if (lastClosedBarIndex < 7)
                return false;
            var structureEvents = BuildStructureSnapshotV2(sourceBars, lookbackBars, endIndex).Events;
            var startBar = Math.Max(2, lastClosedBarIndex - 7);
            var latestSweep = structureEvents
                .Where(value => value.Type == StructureEventTypeV2.Sweep && value.ConfirmationBarIndex >= startBar)
                .OrderByDescending(value => value.ConfirmationBarIndex)
                .FirstOrDefault();
            if (latestSweep.ConfirmationBarIndex <= 0)
                return false;

            biasScore = latestSweep.IsBullish ? 2 : -2;
            return true;
        }

        private int DetectArtifactFirstBiasScore(Bars sourceBars, TimeFrame sourceTimeFrame, int lookbackBars, int endIndex = -1)
        {
            if (sourceBars == null || sourceBars.Count < 10)
                return 0;

            var latestEvent = CollectStructureEvents(sourceBars, sourceTimeFrame, lookbackBars, endIndex)
                .TakeLast(1)
                .FirstOrDefault();
            if (latestEvent.Time != DateTime.MinValue)
            {
                if (latestEvent.IsBullish)
                    return latestEvent.IsChoch ? 3 : 4;
                return latestEvent.IsChoch ? -3 : -4;
            }

            int sweepScore;
            if (TryDetectRecentSweepBiasScore(sourceBars, sourceTimeFrame, lookbackBars, out sweepScore, endIndex))
                return sweepScore;

            return DetectStructureBiasScore(sourceBars, lookbackBars, endIndex);
        }

        private string FormatStructureBiasShort(int biasScore)
        {
            // The chart-summary dashboard conveys direction with the score colour.
            // Keep the magnitude only so the compact cells do not repeat + / - signs.
            if (biasScore != 0) return Math.Abs(biasScore).ToString(CultureInfo.InvariantCulture);
            return "0";
        }

        private Color GetStructureBiasColor(int biasScore)
        {
            if (biasScore >= 3) return Color.LimeGreen;
            if (biasScore >= 2) return Color.FromArgb(255, 120, 255, 120);
            if (biasScore >= 1) return Color.FromArgb(255, 190, 240, 190);
            if (biasScore <= -3) return Color.IndianRed;
            if (biasScore <= -2) return Color.FromArgb(255, 255, 140, 140);
            if (biasScore <= -1) return Color.FromArgb(255, 255, 200, 200);
            return Color.LightGray;
        }

        private bool HasCounterTrendCandlePattern(Bars sourceBars, int biasScore)
        {
            if (sourceBars == null || sourceBars.Count < 4 || Math.Abs(biasScore) < 2)
                return false;

            var lastIndex = sourceBars.Count - 2;
            var prevIndex = sourceBars.Count - 3;
            if (lastIndex <= 0 || prevIndex < 0)
                return false;

            var openV = sourceBars.OpenPrices[lastIndex];
            var highV = sourceBars.HighPrices[lastIndex];
            var lowV = sourceBars.LowPrices[lastIndex];
            var closeV = sourceBars.ClosePrices[lastIndex];
            var prevOpen = sourceBars.OpenPrices[prevIndex];
            var prevClose = sourceBars.ClosePrices[prevIndex];
            var range = Math.Max(highV - lowV, Math.Max(Symbol != null ? Symbol.PipSize : 0.0000001, 0.0000001));
            var body = Math.Abs(closeV - openV);

            var strongBearish = closeV < openV && body / range >= 0.55 && closeV <= lowV + (range * 0.30);
            var strongBullish = closeV > openV && body / range >= 0.55 && closeV >= highV - (range * 0.30);
            var bearishEngulfing = closeV < openV && prevClose > prevOpen && openV >= prevClose && closeV <= prevOpen;
            var bullishEngulfing = closeV > openV && prevClose < prevOpen && openV <= prevClose && closeV >= prevOpen;

            if (biasScore >= 2)
                return strongBearish || bearishEngulfing;

            return strongBullish || bullishEngulfing;
        }

        private bool TryGetCounterTrendWarning(string symbolName, TimeFrame timeFrame, int biasScore, out string marker, out Color color)
        {
            marker = "";
            color = Color.LightGray;

            if (string.IsNullOrWhiteSpace(symbolName) || IsChartAllSymbolsSelection(symbolName) || Math.Abs(biasScore) < 2)
                return false;

            try
            {
                var normalizedSymbol = symbolName.Trim().ToUpperInvariant();
                var bars = MarketData.GetBars(timeFrame, normalizedSymbol);
                if (bars == null || bars.Count < 20)
                    return false;

                var recentThresholdIndex = Math.Max(0, bars.Count - 4);
                var recentThresholdTime = bars.OpenTimes[recentThresholdIndex];
                var expectsBullishCounter = biasScore <= -2;
                var pullbackMatchesBias = biasScore >= 2;
                var recentEvents = GetCanonicalEventsForSymbolTimeFrame(normalizedSymbol, timeFrame, 8)
                    .Where(evt => evt.BarTime >= recentThresholdTime)
                    .ToList();

                var hasPullbackPhase = recentEvents.Any(evt =>
                    evt.EventType == CanonicalEventType.Pullback &&
                    evt.IsBullish == pullbackMatchesBias);

                var hasCounterReversalEvent = recentEvents.Any(evt =>
                    evt.IsBullish == expectsBullishCounter &&
                    (evt.EventType == CanonicalEventType.Rejection ||
                     evt.EventType == CanonicalEventType.SweepReclaim ||
                     evt.EventType == CanonicalEventType.Choch ||
                     evt.EventType == CanonicalEventType.Breakout));

                var hasCounterCandlePattern = HasCounterTrendCandlePattern(bars, biasScore);
                if (!hasPullbackPhase && !hasCounterReversalEvent && !hasCounterCandlePattern)
                    return false;

                marker = expectsBullishCounter ? "↑" : "↓";
                color = hasCounterReversalEvent
                    ? (expectsBullishCounter ? Color.LimeGreen : Color.IndianRed)
                    : Color.Gold;
                return true;
            }
            catch
            {
                return false;
            }
        }

        private Tuple<int, int, int> GetSymbolTrendBias(string symbolName)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(symbolName) || IsChartAllSymbolsSelection(symbolName))
                    return Tuple.Create(0, 0, 0);

                var normalizedSymbol = symbolName.Trim().ToUpperInvariant();
                var baseTimeFrame = Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
                var cacheKey = BuildChartCacheKey(normalizedSymbol, GetMiniChartLabel(baseTimeFrame), "trend-bias");
                TimedCacheEntry<Tuple<int, int, int>> cached;
                if (_symbolTrendBiasCache.TryGetValue(cacheKey, out cached) &&
                    cached != null &&
                    cached.Value != null &&
                    (DateTime.UtcNow - cached.CreatedAtUtc) <= TimeSpan.FromSeconds(3))
                {
                    return cached.Value;
                }

                var started = Stopwatch.StartNew();
                var frames = new List<TimeFrame> { baseTimeFrame };
                frames.AddRange(GetAutoHigherTimeframes(baseTimeFrame));
                var uniqueFrames = frames
                    .Where(tf => tf != null)
                    .Distinct()
                    .Take(3)
                    .ToList();

                var scores = new List<int>();
                foreach (var timeFrame in uniqueFrames)
                {
                    var bars = MarketData.GetBars(timeFrame, symbolName);
                    var score = bars != null && bars.Count >= 10
                        ? DetectArtifactFirstBiasScore(bars, timeFrame, 180)
                        : 0;
                    scores.Add(score);
                }

                while (scores.Count < 3)
                    scores.Add(0);

                var result = Tuple.Create(scores[0], scores[1], scores[2]);
                _symbolTrendBiasCache[cacheKey] = new TimedCacheEntry<Tuple<int, int, int>>
                {
                    CreatedAtUtc = DateTime.UtcNow,
                    Value = result
                };
                LogSlowChartStep("GetSymbolTrendBias", started, string.Format(CultureInfo.InvariantCulture, "{0} {1} -> {2}/{3}/{4}", normalizedSymbol, GetMiniChartLabel(baseTimeFrame), result.Item1, result.Item2, result.Item3));
                return result;
            }
            catch
            {
                return Tuple.Create(0, 0, 0);
            }
        }

        private int GetSymbolTrendBiasForTimeFrame(string symbolName, TimeFrame timeFrame, int cacheSeconds = 3)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(symbolName) || IsChartAllSymbolsSelection(symbolName))
                    return 0;

                var normalizedSymbol = symbolName.Trim().ToUpperInvariant();
                var cacheKey = BuildChartCacheKey(normalizedSymbol, GetMiniChartLabel(timeFrame), "trend-bias-tf");
                TimedCacheEntry<int> cached;
                if (_symbolTrendBiasTimeFrameCache.TryGetValue(cacheKey, out cached) &&
                    cached != null &&
                    (DateTime.UtcNow - cached.CreatedAtUtc) <= TimeSpan.FromSeconds(Math.Max(1, cacheSeconds)))
                {
                    return cached.Value;
                }

                var started = Stopwatch.StartNew();
                var bars = MarketData.GetBars(timeFrame, normalizedSymbol);
                var score = bars != null && bars.Count >= 10
                    ? DetectArtifactFirstBiasScore(bars, timeFrame, 180)
                    : 0;
                _symbolTrendBiasTimeFrameCache[cacheKey] = new TimedCacheEntry<int>
                {
                    CreatedAtUtc = DateTime.UtcNow,
                    Value = score
                };
                LogSlowChartStep("GetSymbolTrendBiasForTimeFrame", started, string.Format(CultureInfo.InvariantCulture, "{0} {1} -> {2}", normalizedSymbol, GetMiniChartLabel(timeFrame), score));
                return score;
            }
            catch
            {
                return 0;
            }
        }

        private int GetStrategyLtfTrendBiasScore(string symbolName, TimeFrame strategyTimeFrame)
        {
            if (string.IsNullOrWhiteSpace(symbolName))
                return 0;

            var frames = GetBacktestStrategyCurrentTimeFrame(strategyTimeFrame).ToList();
            return AggregateStrategyTrendBiasScore(symbolName, frames);
        }

        private int GetStrategyHtfTrendBiasScore(string symbolName, TimeFrame strategyTimeFrame)
        {
            if (string.IsNullOrWhiteSpace(symbolName))
                return 0;

            var frames = GetBacktestStrategyHigherTimeFrames(strategyTimeFrame).ToList();
            return AggregateStrategyTrendBiasScore(symbolName, frames);
        }

        private TimeFrame GetStrategyConfluenceTimeFrame(StrategyCustomRuleOption option)
        {
            switch (option)
            {
                case StrategyCustomRuleOption.H1_Confluence:
                    return TimeFrame.Hour;
                case StrategyCustomRuleOption.H4_Confluence:
                    return TimeFrame.Hour4;
                case StrategyCustomRuleOption.D1_Confluence:
                    return TimeFrame.Daily;
                default:
                    return TimeFrame.Hour;
            }
        }

        private int GetStrategySpecificTimeFrameBiasScore(string symbolName, TimeFrame timeFrame)
        {
            if (string.IsNullOrWhiteSpace(symbolName) || timeFrame == null)
                return 0;
            return GetSymbolTrendBiasForTimeFrame(symbolName, timeFrame);
        }

        private bool IsSpecificTimeFrameBiasAligned(string symbolName, TimeFrame timeFrame, bool bullish)
        {
            var score = GetStrategySpecificTimeFrameBiasScore(symbolName, timeFrame);
            return bullish ? score >= 2 : score <= -2;
        }

        private int AggregateStrategyTrendBiasScore(string symbolName, IEnumerable<TimeFrame> frames)
        {
            var scores = new List<int>();
            foreach (var timeFrame in frames)
            {
                if (timeFrame == null)
                    continue;
                scores.Add(GetSymbolTrendBiasForTimeFrame(symbolName, timeFrame));
            }

            if (scores.Count == 0)
                return 0;

            // Majority of frames must agree with a meaningful bias (|score| >= 2).
            // Scores follow the existing convention: +/-3/4 BOS/CHOCH, +/-2 swing bias.
            var bullishCount = scores.Count(score => score >= 2);
            var bearishCount = scores.Count(score => score <= -2);
            var majorityThreshold = Math.Max(1, (int)Math.Ceiling(scores.Count / 2.0));

            if (bullishCount >= majorityThreshold && bullishCount > bearishCount)
                return 3;
            if (bearishCount >= majorityThreshold && bearishCount > bullishCount)
                return -3;

            var sum = scores.Sum();
            if (sum >= 2)
                return 2;
            if (sum <= -2)
                return -2;
            return 0;
        }

        private void LogPerfStep(string stepName, long elapsedMilliseconds, string detail = null, long minMilliseconds = 15)
        {
            if (elapsedMilliseconds < minMilliseconds)
                return;

            if (string.IsNullOrWhiteSpace(detail))
                SafePrint("[Perf] {0}: {1}ms", stepName, elapsedMilliseconds);
            else
                SafePrint("[Perf] {0}: {1}ms ({2})", stepName, elapsedMilliseconds, detail);
        }

        private void RefreshChartSummaryPanel(RiskGateState riskState)
        {
            if (!AreChartVisualsEnabled())
            {
                try { Chart.RemoveObject("Panel_SUMMARY"); } catch { }
                try
                {
                    if (_chartSummaryPanel != null)
                        Chart.RemoveControl(_chartSummaryPanel);
                }
                catch
                {
                }
                _chartSummaryPanel = null;
                _chartSummaryLayoutKey = "";
                _chartSummaryRenderKey = "";
                _chartSummaryRowControls.Clear();
                _chartSummaryAllRowControls = null;
                return;
            }

            try
            {
                var positions = GetCurrentPositionsSnapshot();
                var pendingOrders = GetCurrentPendingOrdersSnapshot();
                var dashboardSymbols = GetChartToolbarSymbols()
                    .Where(symbol => !IsChartAllSymbolsSelection(symbol))
                    .ToList();

                if (dashboardSymbols.Count == 0)
                {
                    if (_chartSummaryPanel != null)
                    {
                        try { Chart.RemoveControl(_chartSummaryPanel); } catch { }
                    }
                    _chartSummaryPanel = null;
                    _chartSummaryLayoutKey = "";
                    _chartSummaryRenderKey = "";
                    _chartSummaryRowControls.Clear();
                    _chartSummaryAllRowControls = null;
                    return;
                }

                var metricsBySymbol = new Dictionary<string, ChartSummaryMetricTotals>(StringComparer.OrdinalIgnoreCase);
                foreach (var symbolName in dashboardSymbols)
                {
                    if (!string.IsNullOrWhiteSpace(symbolName) && !metricsBySymbol.ContainsKey(symbolName.Trim()))
                        metricsBySymbol[symbolName.Trim()] = new ChartSummaryMetricTotals();
                }
                foreach (var position in positions)
                {
                    if (position == null || string.IsNullOrWhiteSpace(position.SymbolName))
                        continue;

                    ChartSummaryMetricTotals totals;
                    if (!metricsBySymbol.TryGetValue(position.SymbolName.Trim(), out totals))
                        continue;

                    var netProfit = double.IsNaN(position.NetProfit) ? 0 : position.NetProfit;
                    totals.CurrentWin += Math.Max(0, netProfit);
                    totals.CurrentLose += Math.Max(0, -netProfit);
                    totals.PossibleWin += EstimateOpenPositionTpAmount(position);
                    totals.PossibleSlOutcome += EstimateOpenPositionSlOutcomeAmount(position);
                }

                var allPendingOrdersPossibleWin = 0.0;
                var allPendingOrdersRisk = 0.0;
                foreach (var order in pendingOrders)
                {
                    if (order == null)
                        continue;

                    var possibleWin = EstimatePendingOrderTpAmount(order);
                    var risk = EstimatePendingOrderRiskAmount(order);
                    allPendingOrdersPossibleWin += possibleWin;
                    allPendingOrdersRisk += risk;

                    if (string.IsNullOrWhiteSpace(order.SymbolName))
                        continue;
                    ChartSummaryMetricTotals totals;
                    if (!metricsBySymbol.TryGetValue(order.SymbolName.Trim(), out totals))
                        continue;
                    totals.OrdersPossibleWin += possibleWin;
                    totals.OrdersRisk += risk;
                }

                var baseSummaryTimeFrame = Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
                var summaryTimeFrames = ResolveSharedStrategyTimeFrames(baseSummaryTimeFrame)
                    .Concat(new[] { baseSummaryTimeFrame, TimeFrame.Daily })
                    .Where(tf => tf != null)
                    .Distinct()
                    .OrderBy(tf => TimeFrameToMinutes(tf))
                    .Select(tf => new
                    {
                        Label = GetMiniChartLabel(tf),
                        Tf = tf,
                        Color = GetTimeFrameStructureColor(tf)
                    })
                    .ToList();
                const int symbolWidth = 64;
                const int tfWidth = 40;
                const int pnlWidth = 58;
                const int ordersWidth = 66;
                var rowStates = new List<ChartSummaryRowState>();
                foreach (var symbolName in dashboardSymbols)
                {
                    ChartSummaryMetricTotals totals;
                    if (!metricsBySymbol.TryGetValue(symbolName, out totals))
                        totals = new ChartSummaryMetricTotals();
                    var rowState = new ChartSummaryRowState
                    {
                        SymbolName = symbolName,
                        WinText = string.Format(CultureInfo.InvariantCulture, "{0} / {1}", FormatDashboardNumber(totals.CurrentWin), FormatDashboardNumber(totals.PossibleWin)),
                        LoseText = string.Format(CultureInfo.InvariantCulture, "{0} / {1}", FormatDashboardNumber(totals.CurrentLose), FormatDashboardNumber(Math.Abs(totals.PossibleSlOutcome))),
                        OrdersText = string.Format(CultureInfo.InvariantCulture, "{0} / {1}", FormatDashboardNumber(totals.OrdersPossibleWin), FormatDashboardNumber(Math.Abs(totals.OrdersRisk)))
                    };
                    foreach (var frame in summaryTimeFrames)
                    {
                        var biasScore = GetSymbolTrendBiasForTimeFrame(symbolName, frame.Tf, LiteRedrawMinIntervalSeconds);
                        string counterMarker;
                        Color counterColor;
                        var hasCounter = TryGetCounterTrendWarning(symbolName, frame.Tf, biasScore, out counterMarker, out counterColor);
                        var baseText = FormatStructureBiasShort(biasScore);
                        var baseColor = GetStructureBiasColor(biasScore);
                        rowState.Biases.Add(new ChartSummaryBiasState
                        {
                            BaseText = baseText,
                            BaseColor = baseColor,
                            WarningText = hasCounter ? counterMarker : "",
                            WarningColor = hasCounter ? counterColor : Color.LightGray
                        });
                    }
                    rowStates.Add(rowState);
                }

                var allRowState = new ChartSummaryRowState
                {
                    SymbolName = "ALL",
                    WinText = string.Format(CultureInfo.InvariantCulture, "{0} / {1}", FormatDashboardNumber(riskState.CurrentWinAmount), FormatDashboardNumber(riskState.PossibleWinAmount)),
                    LoseText = string.Format(CultureInfo.InvariantCulture, "{0} / {1}", FormatDashboardNumber(riskState.CurrentLoseAmount), FormatDashboardNumber(Math.Abs(riskState.PossibleSlOutcomeAmount))),
                    OrdersText = string.Format(CultureInfo.InvariantCulture, "{0} / {1}", FormatDashboardNumber(allPendingOrdersPossibleWin), FormatDashboardNumber(Math.Abs(allPendingOrdersRisk)))
                };
                foreach (var frame in summaryTimeFrames)
                {
                    allRowState.Biases.Add(new ChartSummaryBiasState
                    {
                        BaseText = "-",
                        BaseColor = Color.LightGray,
                        WarningText = "",
                        WarningColor = Color.LightGray
                    });
                }

                var layoutKeyBuilder = new StringBuilder();
                var renderKeyBuilder = new StringBuilder();
                foreach (var frame in summaryTimeFrames)
                {
                    AppendChartSummaryKeyPart(layoutKeyBuilder, frame.Label);
                    AppendChartSummaryKeyPart(layoutKeyBuilder, GetChartSummaryColorKey(frame.Color));
                }
                foreach (var rowState in rowStates.Concat(new[] { allRowState }))
                {
                    AppendChartSummaryKeyPart(layoutKeyBuilder, rowState.SymbolName);
                    AppendChartSummaryKeyPart(renderKeyBuilder, rowState.SymbolName);
                    foreach (var bias in rowState.Biases)
                    {
                        AppendChartSummaryKeyPart(layoutKeyBuilder, string.IsNullOrWhiteSpace(bias.WarningText) ? "0" : "1");
                        AppendChartSummaryKeyPart(renderKeyBuilder, bias.BaseText);
                        AppendChartSummaryKeyPart(renderKeyBuilder, GetChartSummaryColorKey(bias.BaseColor));
                        AppendChartSummaryKeyPart(renderKeyBuilder, bias.WarningText);
                        AppendChartSummaryKeyPart(renderKeyBuilder, GetChartSummaryColorKey(bias.WarningColor));
                    }
                    AppendChartSummaryKeyPart(renderKeyBuilder, rowState.WinText);
                    AppendChartSummaryKeyPart(renderKeyBuilder, rowState.LoseText);
                    AppendChartSummaryKeyPart(renderKeyBuilder, rowState.OrdersText);
                }

                var layoutKey = layoutKeyBuilder.ToString();
                var renderKey = renderKeyBuilder.ToString();
                var canUpdateExisting = _chartSummaryPanel != null &&
                    string.Equals(_chartSummaryLayoutKey, layoutKey, StringComparison.Ordinal) &&
                    _chartSummaryAllRowControls != null;
                if (canUpdateExisting && string.Equals(_chartSummaryRenderKey, renderKey, StringComparison.Ordinal))
                    return;

                if (canUpdateExisting)
                {
                    foreach (var rowState in rowStates)
                    {
                        ChartSummaryRowControls controls;
                        if (!_chartSummaryRowControls.TryGetValue(rowState.SymbolName, out controls) || controls.Biases.Count != rowState.Biases.Count)
                        {
                            canUpdateExisting = false;
                            break;
                        }

                        for (var i = 0; i < rowState.Biases.Count; i++)
                        {
                            var bias = rowState.Biases[i];
                            UpdateChartSummaryLabel(controls.Biases[i].BaseLabel, bias.BaseText, bias.BaseColor);
                            UpdateChartSummaryLabel(controls.Biases[i].WarningLabel, bias.WarningText, bias.WarningColor);
                        }
                        UpdateChartSummaryLabel(controls.WinLabel, rowState.WinText, Color.LimeGreen);
                        UpdateChartSummaryLabel(controls.LoseLabel, rowState.LoseText, Color.Red);
                        UpdateChartSummaryLabel(controls.OrdersLabel, rowState.OrdersText, Color.DeepSkyBlue);
                    }

                    if (canUpdateExisting && _chartSummaryAllRowControls.Biases.Count == allRowState.Biases.Count)
                    {
                        for (var i = 0; i < allRowState.Biases.Count; i++)
                            UpdateChartSummaryLabel(_chartSummaryAllRowControls.Biases[i].BaseLabel, allRowState.Biases[i].BaseText, allRowState.Biases[i].BaseColor);
                        UpdateChartSummaryLabel(_chartSummaryAllRowControls.WinLabel, allRowState.WinText, Color.LimeGreen);
                        UpdateChartSummaryLabel(_chartSummaryAllRowControls.LoseLabel, allRowState.LoseText, Color.Red);
                        UpdateChartSummaryLabel(_chartSummaryAllRowControls.OrdersLabel, allRowState.OrdersText, Color.DeepSkyBlue);
                        _chartSummaryRenderKey = renderKey;
                        return;
                    }
                }

                if (_chartSummaryPanel != null)
                {
                    try { Chart.RemoveControl(_chartSummaryPanel); } catch { }
                }
                _chartSummaryRowControls.Clear();
                _chartSummaryAllRowControls = null;
                _chartSummaryPanel = new StackPanel
                {
                    Orientation = Orientation.Vertical,
                    HorizontalAlignment = HorizontalAlignment.Left,
                    VerticalAlignment = VerticalAlignment.Top,
                    Margin = "6 18 0 0",
                    Opacity = 0.90
                };

                var headerRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = "0 0 0 1" };
                headerRow.AddChild(BuildChartSummaryLabel("", Color.White, symbolWidth, "Left"));
                foreach (var frame in summaryTimeFrames)
                    headerRow.AddChild(BuildChartSummaryLabel(frame.Label, frame.Color, tfWidth));
                headerRow.AddChild(BuildChartSummaryLabel("W", Color.Aqua, pnlWidth));
                headerRow.AddChild(BuildChartSummaryLabel("L", Color.Aqua, pnlWidth));
                headerRow.AddChild(BuildChartSummaryLabel("O", Color.Aqua, ordersWidth));
                _chartSummaryPanel.AddChild(headerRow);

                foreach (var rowState in rowStates)
                {
                    var controls = new ChartSummaryRowControls();
                    var row = new StackPanel { Orientation = Orientation.Horizontal, Margin = "0 0 0 1" };
                    row.AddChild(BuildChartSummaryLabel(rowState.SymbolName, Color.White, symbolWidth, "Left"));
                    foreach (var bias in rowState.Biases)
                    {
                        var biasControls = new ChartSummaryBiasControls();
                        row.AddChild(BuildChartSummaryBiasCell(bias.BaseText, bias.BaseColor, bias.WarningText, bias.WarningColor, tfWidth, biasControls));
                        controls.Biases.Add(biasControls);
                    }
                    controls.WinLabel = BuildChartSummaryLabel(rowState.WinText, Color.LimeGreen, pnlWidth);
                    controls.LoseLabel = BuildChartSummaryLabel(rowState.LoseText, Color.Red, pnlWidth);
                    controls.OrdersLabel = BuildChartSummaryLabel(rowState.OrdersText, Color.DeepSkyBlue, ordersWidth);
                    row.AddChild(controls.WinLabel);
                    row.AddChild(controls.LoseLabel);
                    row.AddChild(controls.OrdersLabel);
                    _chartSummaryPanel.AddChild(row);
                    _chartSummaryRowControls[rowState.SymbolName] = controls;
                }

                var allControls = new ChartSummaryRowControls();
                var allRow = new StackPanel { Orientation = Orientation.Horizontal, Margin = "0 0 0 1" };
                allRow.AddChild(BuildChartSummaryLabel(allRowState.SymbolName, Color.White, symbolWidth, "Left"));
                foreach (var bias in allRowState.Biases)
                {
                    var biasControls = new ChartSummaryBiasControls();
                    allRow.AddChild(BuildChartSummaryBiasCell(bias.BaseText, bias.BaseColor, bias.WarningText, bias.WarningColor, tfWidth, biasControls));
                    allControls.Biases.Add(biasControls);
                }
                allControls.WinLabel = BuildChartSummaryLabel(allRowState.WinText, Color.LimeGreen, pnlWidth);
                allControls.LoseLabel = BuildChartSummaryLabel(allRowState.LoseText, Color.Red, pnlWidth);
                allControls.OrdersLabel = BuildChartSummaryLabel(allRowState.OrdersText, Color.DeepSkyBlue, ordersWidth);
                allRow.AddChild(allControls.WinLabel);
                allRow.AddChild(allControls.LoseLabel);
                allRow.AddChild(allControls.OrdersLabel);
                _chartSummaryPanel.AddChild(allRow);
                _chartSummaryAllRowControls = allControls;

                Chart.AddControl(_chartSummaryPanel);
                _chartSummaryLayoutKey = layoutKey;
                _chartSummaryRenderKey = renderKey;
            }
            catch (Exception ex)
            {
                SafeLog("ERROR", "[Panel] Summary panel failed: {0}", ex.Message);
            }
        }

        private List<string> GetChartToolbarSymbols()
        {
            var symbols = new List<string>();

            symbols.AddRange(GetConfiguredStrategySymbolInputs());
            symbols.AddRange(
                GetCurrentPositionsSnapshot()
                    .Where(p => p != null && !string.IsNullOrWhiteSpace(p.SymbolName))
                    .Select(p => p.SymbolName.Trim()));
            symbols.AddRange(
                GetCurrentPendingOrdersSnapshot()
                    .Where(o => o != null && !string.IsNullOrWhiteSpace(o.SymbolName))
                    .Select(o => o.SymbolName.Trim()));

            var chartSymbolName = Chart != null && !string.IsNullOrWhiteSpace(Chart.SymbolName)
                ? Chart.SymbolName.Trim()
                : "";
            if (!string.IsNullOrWhiteSpace(chartSymbolName) && !symbols.Any(s => string.Equals(s, chartSymbolName, StringComparison.OrdinalIgnoreCase)))
                symbols.Add(chartSymbolName);

            var orderedSymbols = symbols
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(s => s, StringComparer.OrdinalIgnoreCase)
                .ToList();

            orderedSymbols.Insert(0, ChartAllSymbolsOption);
            return orderedSymbols;
        }

        private bool IsChartAllSymbolsSelection(string symbolName)
        {
            return string.Equals((symbolName ?? "").Trim(), ChartAllSymbolsOption, StringComparison.OrdinalIgnoreCase);
        }

        private string NormalizeChartDirectionSelection(string raw = null)
        {
            return CTraderChartEngine.NormalizeToolbarDirection(raw, _chartSelectedDirection);
        }

        private bool DirectionMatchesTradeType(string selectedDirection, TradeType tradeType)
        {
            return CTraderChartEngine.DirectionMatchesTradeType(selectedDirection, tradeType);
        }

        private bool SymbolHasOpenPositions(string symbolName, string selectedDirection = null)
        {
            return Positions != null &&
                !string.IsNullOrWhiteSpace(symbolName) &&
                Positions.Any(p =>
                    p != null &&
                    (IsChartAllSymbolsSelection(symbolName) || string.Equals(p.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase)) &&
                    DirectionMatchesTradeType(selectedDirection, p.TradeType));
        }

        private bool SymbolHasPendingOrders(string symbolName, string selectedDirection = null)
        {
            return PendingOrders != null &&
                !string.IsNullOrWhiteSpace(symbolName) &&
                PendingOrders.Any(o =>
                    o != null &&
                    (IsChartAllSymbolsSelection(symbolName) || string.Equals(o.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase)) &&
                    DirectionMatchesTradeType(selectedDirection, o.TradeType));
        }

        private List<Position> GetChartSelectedPositions(string symbolName, string selectedDirection = null)
        {
            return Positions != null
                ? Positions
                    .Where(p =>
                        p != null &&
                        (IsChartAllSymbolsSelection(symbolName) || string.Equals(p.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase)) &&
                        DirectionMatchesTradeType(selectedDirection, p.TradeType))
                    .ToList()
                : new List<Position>();
        }

        private List<PendingOrder> GetChartSelectedPendingOrders(string symbolName, string selectedDirection = null)
        {
            return PendingOrders != null
                ? PendingOrders
                    .Where(o =>
                        o != null &&
                        (IsChartAllSymbolsSelection(symbolName) || string.Equals(o.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase)) &&
                        DirectionMatchesTradeType(selectedDirection, o.TradeType))
                    .ToList()
                : new List<PendingOrder>();
        }

        private bool TryGetChartSelectedSymbol(out string symbolName, out Symbol symbol)
        {
            symbolName = ReadChartSymbolComboSelection();
            symbol = null;

            if (string.IsNullOrWhiteSpace(symbolName))
            {
                Print("[Click] symbol resolution -> no symbol selected");
                return false;
            }

            if (IsChartAllSymbolsSelection(symbolName))
            {
                Print("[Click] symbol resolution -> 'All' is management-only");
                return false;
            }

            symbol = ResolveLoadedSymbol(symbolName);
            if (symbol == null)
            {
                Print(string.Format(CultureInfo.InvariantCulture, "[Click] symbol resolution -> not loaded: {0}", symbolName));
                return false;
            }

            return true;
        }

        private string GetChartSymbolFallback()
        {
            if (Chart != null && !string.IsNullOrWhiteSpace(Chart.SymbolName))
                return Chart.SymbolName.Trim();
            if (Symbol != null && !string.IsNullOrWhiteSpace(Symbol.Name))
                return Symbol.Name.Trim();
            return "";
        }

        private string GetEffectiveChartEntrySymbolSelection()
        {
            var chartSymbol = GetChartSymbolFallback();
            if (!string.IsNullOrWhiteSpace(chartSymbol) && !IsChartAllSymbolsSelection(chartSymbol))
            {
                _chartSelectedSymbol = EnsureChartSelectedSymbol(chartSymbol);
                return _chartSelectedSymbol;
            }

            var symbolName = ReadChartSymbolComboSelection();
            if (!string.IsNullOrWhiteSpace(symbolName) && !IsChartAllSymbolsSelection(symbolName))
                return symbolName;

            return string.IsNullOrWhiteSpace(chartSymbol) ? symbolName : chartSymbol;
        }

        private string EnsureChartSelectedSymbol(string preferred = null)
        {
            var symbols = GetChartToolbarSymbols();
            var chartSymbolName = Chart != null && !string.IsNullOrWhiteSpace(Chart.SymbolName)
                ? Chart.SymbolName.Trim()
                : "";
            if (!string.IsNullOrWhiteSpace(preferred))
            {
                if (IsChartAllSymbolsSelection(preferred))
                {
                    _chartSelectedSymbol = ChartAllSymbolsOption;
                    return _chartSelectedSymbol;
                }

                var match = symbols.FirstOrDefault(s => string.Equals(s, preferred.Trim(), StringComparison.OrdinalIgnoreCase));
                if (!string.IsNullOrWhiteSpace(match))
                    _chartSelectedSymbol = match;
            }

            if (!string.IsNullOrWhiteSpace(_chartSelectedSymbol))
            {
                if (IsChartAllSymbolsSelection(_chartSelectedSymbol))
                {
                    _chartSelectedSymbol = ChartAllSymbolsOption;
                    return _chartSelectedSymbol;
                }

                var existing = symbols.FirstOrDefault(s => string.Equals(s, _chartSelectedSymbol, StringComparison.OrdinalIgnoreCase));
                if (!string.IsNullOrWhiteSpace(existing))
                {
                    _chartSelectedSymbol = existing;
                    return _chartSelectedSymbol;
                }
            }

            if (!string.IsNullOrWhiteSpace(chartSymbolName))
            {
                var chartMatch = symbols.FirstOrDefault(s => string.Equals(s, chartSymbolName, StringComparison.OrdinalIgnoreCase));
                if (!string.IsNullOrWhiteSpace(chartMatch))
                {
                    _chartSelectedSymbol = chartMatch;
                    return _chartSelectedSymbol;
                }
            }

            _chartSelectedSymbol = symbols.FirstOrDefault() ?? "";
            return _chartSelectedSymbol;
        }

        private void RefreshChartSymbolSelector()
        {
            try
            {
                var chartSymbolName = GetChartSymbolFallback();
                var selected = !string.IsNullOrWhiteSpace(chartSymbolName)
                    ? chartSymbolName
                    : ReadChartSymbolComboSelection();
                var symbols = GetChartToolbarSymbols();
                var signature = string.Join("|", symbols);
                var normalizedSelected = EnsureChartSelectedSymbol(selected);

                if (_chartSymbolCombo == null) return;
                if (signature != _chartSymbolsSignature)
                {
                    var items = TryGetPropertyValue(_chartSymbolCombo, "Items");
                    if (items != null) TryClearCollection(items);

                    foreach (var symbol in symbols)
                    {
                        if (!(items != null && TryAddToCollection(items, symbol)))
                            TryInvokeVoidMethod(_chartSymbolCombo, "AddItem", symbol);
                    }

                    _chartSymbolsSignature = signature;
                }

                TrySetPropertyValue(_chartSymbolCombo, "SelectedItem", normalizedSelected);
                TrySetPropertyValue(_chartSymbolCombo, "SelectedValue", normalizedSelected);
                TrySetPropertyValue(_chartSymbolCombo, "SelectedIndex", symbols.FindIndex(s => string.Equals(s, normalizedSelected, StringComparison.OrdinalIgnoreCase)));
            }
            catch (Exception ex)
            {
                SafeLog("ERROR", "[Panel] Symbol selector refresh failed: {0}", ex.Message);
            }
        }

        private bool TryAddChartDirectionCombo(StackPanel panel)
        {
            try
            {
                _chartDirectionCombo = null;
                var assembly = typeof(StackPanel).Assembly;
                var comboType = assembly.GetType("cAlgo.API.ComboBox") ?? assembly.GetType("cAlgo.API.Controls.ComboBox");
                if (comboType == null) return false;

                var combo = Activator.CreateInstance(comboType);
                TrySetPropertyValue(combo, "Margin", 3);
                TrySetPropertyValue(combo, "Width", 72);
                TrySetPropertyValue(combo, "MinWidth", 72);
                TrySetPropertyValue(combo, "MaxWidth", 84);
                TrySetPropertyValue(combo, "FontSize", 8);

                var items = TryGetPropertyValue(combo, "Items");
                foreach (var item in new[] { "All", "Buy", "Sell" })
                {
                    if (!(items != null && TryAddToCollection(items, item)))
                        TryInvokeVoidMethod(combo, "AddItem", item);
                }

                var normalizedDirection = NormalizeChartDirectionSelection();
                TrySetPropertyValue(combo, "SelectedItem", normalizedDirection);
                TrySetPropertyValue(combo, "SelectedValue", normalizedDirection);
                TrySetPropertyValue(combo, "SelectedIndex", normalizedDirection == "Buy" ? 1 : normalizedDirection == "Sell" ? 2 : 0);

                var changedEvent = comboType.GetEvent("SelectionChanged") ?? comboType.GetEvent("SelectedItemChanged");
                if (changedEvent != null)
                {
                    Action<object> handler = _ =>
                    {
                        var previousDirection = _chartSelectedDirection;
                        var selected = ReadChartDirectionComboSelection();
                        _chartSelectedDirection = NormalizeChartDirectionSelection(selected);
                        if (!_isRebuildingChartPanel && !string.Equals(previousDirection, _chartSelectedDirection, StringComparison.OrdinalIgnoreCase))
                        {
                            PersistCustomUiSettingsSnapshot();
                            RebuildChartButtonPanel();
                            RefreshDebugPanel();
                        }
                    };
                    try
                    {
                        var del = Delegate.CreateDelegate(changedEvent.EventHandlerType, handler.Target, handler.Method);
                        changedEvent.AddEventHandler(combo, del);
                    }
                    catch
                    {
                    }
                }

                if (!TryInvokeVoidMethod(panel, "AddChild", combo))
                    return false;

                _chartDirectionCombo = combo;
                return true;
            }
            catch (Exception ex)
            {
                SafeLog("ERROR", "[Panel] Direction combo unavailable: {0}", ex.Message);
                return false;
            }
        }

