        // Resolve the orders-per-click selection into a leg count: 0 = Auto (dynamic),
        // 1..5 = fixed number of orders per click.
        private int ResolveChartOrderCount()
        {
            return CTraderChartEngine.ResolveToolbarOrderCount(_chartSelectedOrderCount);
        }

        // Resolve the strategy n.Trades parameter into a leg count: 0 = Auto
        // (keeps the current single-order behavior), 1..5 = fixed number of orders.
        private int ResolveStrategyOrderCount()
        {
            switch (StrategyOrderCount)
            {
                case StrategyOrderCountMode._1: return 1;
                case StrategyOrderCountMode._2: return 2;
                case StrategyOrderCountMode._3: return 3;
                case StrategyOrderCountMode._4: return 4;
                case StrategyOrderCountMode._5: return 5;
                default: return 0;
            }
        }

        private List<int> ResolveEnabledStrategyTradeChainSlots(int tradeChainSlot)
        {
            // A non-chain signal (slot 0) keeps the full parent budget. Chain signals
            // share one budget across the enabled 1st/2nd/3rd trade slots.
            if (tradeChainSlot <= 0)
                return new List<int> { 1 };

            var slots = new List<int>();
            if (FirstTradeMode != StrategyTradeChainMode.No) slots.Add(1);
            if (SecondTradeMode != StrategyTradeChainMode.No) slots.Add(2);
            if (ThirdTradeMode != StrategyTradeChainMode.No) slots.Add(3);
            if (slots.Count == 0)
                slots.Add(Math.Max(1, tradeChainSlot));
            return slots;
        }

        private double[] BuildStrategyChainRiskWeights(int legsPerSignal, int tradeChainSlot)
        {
            return CTraderAllocationEngine.BuildChainRiskWeights(
                legsPerSignal,
                tradeChainSlot,
                ResolveEnabledStrategyTradeChainSlots(tradeChainSlot));
        }

