                symbol, signal.TradeType, entryPrice,
                signal.OriginalPatternLow, signal.OriginalPatternHigh, buffer, out stopLoss);
        }

        private bool TryResolveStrategyProtectiveSwingStopLoss(Symbol symbol, string symbolName, BacktestStrategySignal signal, double entryPrice, double buffer, out double stopLoss)
        {
            stopLoss = 0;
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || signal.SourceTimeFrame == null || entryPrice <= 0)
                return false;

            var patternEdge = signal.TradeType == TradeType.Buy ? signal.OriginalPatternLow : signal.OriginalPatternHigh;
            if (!(patternEdge > 0))
                return false;
            if (signal.TradeType == TradeType.Buy && patternEdge >= entryPrice)
                return false;
            if (signal.TradeType == TradeType.Sell && patternEdge <= entryPrice)
                return false;

            Bars sourceBars;
            try { sourceBars = MarketData.GetBars(signal.SourceTimeFrame, symbolName); }
            catch { sourceBars = null; }
            var signalIndex = ResolveSourceBarIndex(sourceBars, signal.SignalTime);
            if (!IsValidBarIndex(sourceBars, signalIndex))
                return false;

            var tolerance = Math.Max(symbol.PipSize * 2.0, 0.0000001);
            var swings = CollectConfirmedSwings(sourceBars, 160, signalIndex);
            var raw = CTraderStrategyEngine.SelectProtectiveSwing(
                swings.Select(swing => new CTraderStructureSwing
                {
                    Index = swing.BarIndex,
                    Price = swing.Price,
                    IsHigh = swing.IsHigh
                }),
                signal.TradeType,
                signalIndex,
                patternEdge,
                tolerance);
            if (signal.TradeType == TradeType.Buy && raw >= entryPrice)
                return false;
            if (signal.TradeType == TradeType.Sell && raw <= entryPrice)
                return false;

            stopLoss = NormalizePriceToSymbol(symbol, signal.TradeType == TradeType.Buy ? raw - buffer : raw + buffer);
            return stopLoss > 0;
        }

        private bool TryResolveStrategyFurthestInvalidationStopLoss(Symbol symbol, BacktestStrategySignal signal, double entryPrice, double buffer, out double stopLoss)
        {
            return CTraderStrategyEngine.TryResolveInvalidationStopLoss(
                symbol, signal.TradeType, entryPrice, signal.RelatedStopLevels,
                signal.RelatedZoneLow, signal.RelatedZoneHigh,
                signal.OriginalPatternLow, signal.OriginalPatternHigh,
                buffer, true, out stopLoss);
        }

        private bool TryResolveStrategyEventInvalidationStopLoss(Symbol symbol, BacktestStrategySignal signal, double entryPrice, double buffer, out double stopLoss)
        {
            return CTraderStrategyEngine.TryResolveInvalidationStopLoss(
                symbol, signal.TradeType, entryPrice, signal.RelatedStopLevels,
                signal.RelatedZoneLow, signal.RelatedZoneHigh,
                signal.OriginalPatternLow, signal.OriginalPatternHigh,
                buffer, false, out stopLoss);
        }

        private double ResolveStrategyAtrProtection(Symbol symbol, TradeType tradeType, double entryPrice, bool isStopLoss, double multiplier)
        {
            if (symbol == null || entryPrice <= 0 || symbol.PipSize <= 0)
                return 0;
            var atrPips = ResolveAtrPips(symbol, null, 14);
            var distance = Math.Max(ResolveMinStopPips(symbol), atrPips * Math.Max(0.1, multiplier)) * symbol.PipSize;
            return CTraderStrategyEngine.ResolveDistanceTarget(symbol, tradeType, entryPrice, isStopLoss, distance);
        }

        private bool TryResolveStrategySessionProtection(Symbol symbol, TradeType tradeType, double entryPrice, bool isStopLoss, out double price)
        {
            price = 0;
            if (symbol == null || entryPrice <= 0)
                return false;

            var tolerance = Math.Max(symbol.PipSize * 2.0, 0.0000001);
            var levels = new List<double>();
            AddSessionLiquidityLevelCandidates(levels, "Asia", tolerance);
            AddSessionLiquidityLevelCandidates(levels, "London", tolerance);
            AddSessionLiquidityLevelCandidates(levels, "NewYork", tolerance);
            return CTraderStrategyEngine.TrySelectDirectionalLevel(levels, tradeType, entryPrice, isStopLoss, out price);
        }

        private bool TryResolveStrategyLiquidityTakeProfit(Symbol symbol, string symbolName, TradeType tradeType, double entryPrice, string profileRaw, out double price)
        {
            price = 0;
            var levels = CollectChartLiquidityLevels(symbol, symbolName, profileRaw);
            return CTraderStrategyEngine.TrySelectDirectionalLevel(levels, tradeType, entryPrice, false, out price);
        }

        private bool TryResolveStrategyIndicatorTakeProfit(Symbol symbol, string symbolName, BacktestStrategySignal signal, double entryPrice, bool useVwap, out double takeProfit)
        {
            takeProfit = 0;
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || signal.SourceTimeFrame == null || entryPrice <= 0)
                return false;

            Bars sourceBars;
            try { sourceBars = MarketData.GetBars(signal.SourceTimeFrame, symbolName); }
            catch { sourceBars = null; }
            var sourceIndex = ResolveSourceBarIndex(sourceBars, signal.SignalTime);
            if (!IsValidBarIndex(sourceBars, sourceIndex))
                return false;

            var value = useVwap
                ? ComputeRollingVwapAtIndex(sourceBars, 20, sourceIndex)
                : ComputeEmaAtIndex(sourceBars, Math.Max(1, _resolvedEmaEventConfig.MidPeriod), sourceIndex);
            if (!IsFiniteNumber(value) || value <= 0)
                return false;

            if (signal.TradeType == TradeType.Buy && value <= entryPrice)
                return false;
            if (signal.TradeType == TradeType.Sell && value >= entryPrice)
                return false;

            takeProfit = NormalizePriceToSymbol(symbol, value);
            return takeProfit > 0;
        }

        private bool TryResolveStrategyZoneEdgeProtection(Symbol symbol, string symbolName, BacktestStrategySignal signal, double entryPrice, bool isStopLoss, bool useFvg, out double price)
        {
            price = 0;
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || entryPrice <= 0)
                return false;

            var candidates = new List<double>();
            var frames = GetStrategyLtfProtectionFrames(signal)
                .Concat(GetStrategyHtfProtectionFrames(signal))
                .Distinct()
                .ToList();
            foreach (var sourceTimeFrame in frames)
            {
                try
                {
                    var sourceBars = MarketData.GetBars(sourceTimeFrame, symbolName);
                    if (sourceBars == null || sourceBars.Count < 5)
                        continue;
                    foreach (var zone in BuildStructureSnapshotV2(sourceBars, ResolveWorkingLookbackBars(sourceBars, sourceTimeFrame)).Zones
                        .Where(zone => zone.State != StructureZoneStateV2.Invalidated)
                        .Where(zone => useFvg
                            ? zone.Type == StructureZoneTypeV2.Fvg || zone.Type == StructureZoneTypeV2.InverseFvg
                            : zone.Type == StructureZoneTypeV2.OrderBlock || zone.Type == StructureZoneTypeV2.BreakerBlock)
                        .OrderByDescending(zone => zone.ConfirmationBarIndex)
                        .Take(10))
                    {
                        candidates.Add(zone.Low);
                        candidates.Add(zone.High);
                    }
                }
                catch
                {
                }
            }

            return CTraderStrategyEngine.TrySelectDirectionalLevel(candidates, signal.TradeType, entryPrice, isStopLoss, out price);
        }

        private bool TryResolveStrategyKeyLevelProtection(
            Symbol symbol,
            string symbolName,
            TradeType tradeType,
            double entryPrice,
            bool isStopLoss,
            IEnumerable<TimeFrame> sourceTimeFrames,
            out double price)
        {
            price = 0;
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || entryPrice <= 0 || sourceTimeFrames == null)
                return false;

            var candidates = new List<ChartLevelCandidate>();
            foreach (var sourceTimeFrame in sourceTimeFrames.Where(tf => tf != null).Distinct())
            {
                try
                {
                    var sourceBars = MarketData.GetBars(sourceTimeFrame, symbolName);
                    if (sourceBars == null || sourceBars.Count < 5)
                        continue;
                    candidates.AddRange(CollectTimeFrameStructuralLevelCandidates(symbol, sourceBars, sourceTimeFrame));
                }
                catch
                {
                }
            }

            if (!CTraderStrategyEngine.TrySelectWeightedProtectionLevel(
                    candidates.Select(candidate => new CTraderStrategyLevelCandidate { Price = candidate.Price, Weight = candidate.Weight }),
                    tradeType,
                    entryPrice,
                    isStopLoss,
                    out price) ||
                !IsChartProtectionDistanceUsable(symbol, entryPrice, price))
                return false;
            return true;
        }

        private double ResolveChartTradeVolume(Symbol symbol, string symbolName)
        {
            if (symbol == null) return 0;

            var referenceVolume = Positions != null
                ? Positions
                    .Where(p => p != null && string.Equals(p.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase) && p.VolumeInUnits > 0)
                    .Select(p => p.VolumeInUnits)
                    .DefaultIfEmpty(symbol.VolumeInUnitsMin)
                    .Min()
                : symbol.VolumeInUnitsMin;

            if (double.IsNaN(referenceVolume) || referenceVolume <= 0)
                referenceVolume = symbol.VolumeInUnitsMin;

            return symbol.NormalizeVolumeInUnits(referenceVolume, RoundingMode.Down);
        }

        private double ResolveVolumeUnitsForRisk(Symbol symbol, TradeType tradeType, double entryPrice, double stopLossPrice, double maxRiskMoney)
        {
            if (symbol == null)
                return 0;

            var minVolume = !double.IsNaN(symbol.VolumeInUnitsMin) && symbol.VolumeInUnitsMin > 0
                ? symbol.VolumeInUnitsMin
                : 0;
            if (minVolume <= 0)
                return 0;

            if (entryPrice > 0 && stopLossPrice > 0 && maxRiskMoney > 0)
            {
                var stopLossPips = CalculateStopLossPips(symbol, entryPrice, stopLossPrice);
                if (!(stopLossPips > 0))
                    return 0;

                var riskAtMinVolume = EstimateRiskAmount(symbol, tradeType, entryPrice, stopLossPrice, minVolume);
                if (riskAtMinVolume > 0)
                {
                    if (riskAtMinVolume > maxRiskMoney)
                        return 0;

                    double rawVolume = 0;
                    try
                    {
                        rawVolume = symbol.VolumeForFixedRisk(maxRiskMoney, stopLossPips, RoundingMode.Down);
                    }
                    catch
                    {
                        rawVolume = minVolume * (maxRiskMoney / riskAtMinVolume);
                    }

                    var normalized = symbol.NormalizeVolumeInUnits(rawVolume, RoundingMode.Down);
                    if (normalized >= minVolume)
                        return normalized;

                    return minVolume;
                }

                return 0;
            }

            return 0;
        }

        private double ResolveChartTradeVolumeForRisk(Symbol symbol, TradeType tradeType, double entryPrice, double stopLossPrice, double maxRiskMoney, string symbolName)
        {
            var riskVolume = ResolveVolumeUnitsForRisk(symbol, tradeType, entryPrice, stopLossPrice, maxRiskMoney);
            if (maxRiskMoney > 0)
                return riskVolume;

            if (riskVolume > 0)
                return riskVolume;

            return ResolveChartTradeVolume(symbol, symbolName);
        }

        private double? FindClosestChartProtectionPrice(string symbolName, TradeType tradeType, bool isStopLoss, double referencePrice)
        {
            if (Positions == null || referencePrice <= 0) return null;

            var candidates = Positions
                .Where(p => p != null && string.Equals(p.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase))
                .Select(p => isStopLoss ? p.StopLoss : p.TakeProfit)
                .Where(v => v.HasValue && v.Value > 0)
                .Select(v => v.Value)
                .Distinct()
                .ToList();

            if (candidates.Count == 0) return null;

            IEnumerable<double> filtered;
            if (tradeType == TradeType.Buy)
                filtered = isStopLoss ? candidates.Where(v => v < referencePrice) : candidates.Where(v => v > referencePrice);
            else
                filtered = isStopLoss ? candidates.Where(v => v > referencePrice) : candidates.Where(v => v < referencePrice);

            var valid = filtered.ToList();
            if (valid.Count == 0) return null;

            return valid.OrderBy(v => Math.Abs(v - referencePrice)).FirstOrDefault();
        }

        private List<double> CollectChartExistingProtectionLevels(string symbolName)
        {
            var candidates = new List<double>();
            if (string.IsNullOrWhiteSpace(symbolName))
                return candidates;

            if (Positions != null)
            {
                candidates.AddRange(
                    Positions
                        .Where(p => p != null && string.Equals(p.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase))
                        .SelectMany(p => new[] { p.StopLoss, p.TakeProfit })
                        .Where(v => v.HasValue && v.Value > 0)
                        .Select(v => v.Value));
            }

            if (PendingOrders != null)
            {
                candidates.AddRange(
                    PendingOrders
                        .Where(o => o != null && string.Equals(o.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase))
                        .SelectMany(o => new[] { o.StopLoss, o.TakeProfit })
                        .Where(v => v.HasValue && v.Value > 0)
                        .Select(v => v.Value));
            }

            return candidates.Distinct().ToList();
        }

        private void AddDistinctChartLevel(List<double> candidates, double price, double tolerance)
        {
            if (candidates == null || price <= 0)
                return;

            if (candidates.Any(v => Math.Abs(v - price) <= tolerance))
                return;

            candidates.Add(price);
        }

        private void AddChartLevelCandidate(List<ChartLevelCandidate> candidates, double price, double tolerance, int weight = 1, string kind = "")
        {
            if (candidates == null || price <= 0 || weight <= 0)
                return;

            var normalizedKind = (kind ?? "").Trim().ToUpperInvariant();
            for (var i = 0; i < candidates.Count; i++)
            {
                if (Math.Abs(candidates[i].Price - price) <= tolerance &&
                    string.Equals((candidates[i].Kind ?? "").Trim(), normalizedKind, StringComparison.OrdinalIgnoreCase))
                {
                    var mergedWeight = candidates[i].Weight + weight;
                    var mergedPrice = ((candidates[i].Price * candidates[i].Weight) + (price * weight)) / Math.Max(1, mergedWeight);
                    candidates[i] = new ChartLevelCandidate
                    {
                        Price = mergedPrice,
                        Weight = mergedWeight,
                        Kind = normalizedKind
                    };
                    return;
                }
            }

            candidates.Add(new ChartLevelCandidate
            {
                Price = price,
                Weight = weight,
                Kind = normalizedKind
            });
        }

        private void AddChartLevelCandidatesFromRaw(List<ChartLevelCandidate> weightedCandidates, IEnumerable<double> rawLevels, double tolerance, int weight = 1)
        {
            if (weightedCandidates == null || rawLevels == null)
                return;

            foreach (var level in rawLevels)
                AddChartLevelCandidate(weightedCandidates, level, tolerance, weight);
        }

        private int ResolveStructureLastClosedBarIndex(Bars sourceBars, int endIndex = -1)
        {
            if (sourceBars == null || sourceBars.Count < 2)
                return -1;

            var latestClosed = sourceBars.Count - 2;
            return endIndex >= 0 ? Math.Min(endIndex, latestClosed) : latestClosed;
        }

        private static void ValidateStructureEngineV2Contracts()
        {
            var engine = new CTraderStructureEngine();
            var candles = new List<FortyTwo.Trading.Analysis.MarketCandle>();
            var highs = new[] { 1.0, 2.0, 5.0, 2.0, 1.0 };
            for (var i = 0; i < highs.Length; i++)
            {
                candles.Add(new FortyTwo.Trading.Analysis.MarketCandle
                {
                    Index = i,
                    OpenTimeUtc = new DateTime(2020, 1, 1).AddMinutes(i),
                    Open = highs[i] - 0.5,
                    High = highs[i],
                    Low = highs[i] - 1.0,
                    Close = highs[i] - 0.25
                });
            }
            var swings = engine.DetectSwings(candles, 4, new FortyTwo.Trading.Analysis.SwingAnalysisConfig { Strength = 2, LookbackBars = 10 });
            if (!swings.Any(value => value.IsHigh && value.Index == 2 && value.ConfirmationIndex == 4))
                throw new InvalidOperationException("MarketAnalysisService semantic contract failed.");

            var biasSwings = new[]
            {
                new FortyTwo.Trading.Analysis.SwingInfo { Index = 1, Price = 10.0, IsHigh = true },
                new FortyTwo.Trading.Analysis.SwingInfo { Index = 2, Price = 5.0, IsHigh = false },
                new FortyTwo.Trading.Analysis.SwingInfo { Index = 3, Price = 12.0, IsHigh = true },
                new FortyTwo.Trading.Analysis.SwingInfo { Index = 4, Price = 7.0, IsHigh = false }
            };
            if (engine.CalculateBiasScore(biasSwings, 11.0) != 3)
                throw new InvalidOperationException("Structure bias scoring contract failed.");
            if (!engine.IsSingleBarSweepReclaim(9.5, 13.0, 9.0, 9.8, 10.0, true, 0.0001))
                throw new InvalidOperationException("Single-bar sweep/reclaim contract failed.");
            if (!engine.IsTwoBarSweepReclaim(10.4, 9.0, 9.9, 10.0, 9.2, 9.8, 10.0, true, 0.0001))
                throw new InvalidOperationException("Two-bar sweep/reclaim contract failed.");
            var sweepMatch = engine.MatchSweepPattern(
                4,
                9.7, 10.0, 9.2, 9.8,
                new DateTime(2020, 1, 1, 0, 3, 0),
                10.4, 9.0, 9.9,
                new DateTime(2020, 1, 1, 0, 1, 0),
                10.0, true, 0.0001);
            if (!sweepMatch.IsValid || sweepMatch.SweepBarIndex != 3 || sweepMatch.ReclaimBarIndex != 4)
                throw new InvalidOperationException("Sweep-pattern selection contract failed.");
            if (!engine.IsStrictLevelRejection(9.5, 11.0, 9.0, 10.8, 10.5, 9.5, 10.0, 0.1, 1.0, true, true))
                throw new InvalidOperationException("Strict bullish level-rejection contract failed.");
            if (!engine.IsStrictLevelRejection(10.5, 11.0, 9.0, 9.2, 9.5, 10.5, 10.0, 0.1, 1.0, false, true))
                throw new InvalidOperationException("Strict bearish level-rejection contract failed.");
            if (!engine.IsMultiCandleLevelRejection(
                10.4,
                10.3, 10.4, 9.5, 9.8,
                false, 0.0,
                9.8, 10.8, 9.7, 10.6,
                10.0, 0.1, true))
                throw new InvalidOperationException("Two-candle bullish level-rejection contract failed.");
            if (!engine.IsMultiCandleLevelRejection(
                9.6,
                9.7, 10.5, 9.6, 10.2,
                true, 10.1,
                10.2, 10.3, 9.2, 9.4,
                10.0, 0.1, false))
                throw new InvalidOperationException("Three-candle bearish level-rejection contract failed.");
            if (engine.IsMultiCandleLevelRejection(
                10.4,
                10.3, 10.4, 9.5, 9.8,
                true, 10.3,
                10.3, 10.8, 10.1, 10.6,
                10.0, 0.1, true))
                throw new InvalidOperationException("Multi-candle rejection must confirm on the first recovered close.");
            if (!engine.IsStrictLevelBreakout(9.9, 11.5, 9.95, 11.0, 9.8, 9.9, 10.0, 0.1, 1.0, true, true, true))
                throw new InvalidOperationException("Strict level-breakout contract failed.");

            var levelPatterns = engine.DetectSwingLevelPatterns(
                new[]
                {
                    new CTraderStructureSwing { Index = 1, Price = 100.0, IsHigh = true },
                    new CTraderStructureSwing { Index = 2, Price = 90.0, IsHigh = false },
                    new CTraderStructureSwing { Index = 3, Price = 100.05, IsHigh = true }
                },
                new[] { 95.0, 100.0, 90.0, 89.0 },
                0.01);
            if (!levelPatterns.Any(value => value.Kind == CTraderSwingLevelPatternKind.EqualHighs) ||
                !levelPatterns.Any(value => value.Kind == CTraderSwingLevelPatternKind.DoubleTop && value.NecklineBroken))
            {
                throw new InvalidOperationException("Swing-level pattern contract failed.");
            }
        }

        private static void ValidateStrategyEngineContracts()
        {
            if (Math.Abs(CTraderStrategyEngine.ResolveEntryBufferMultiplier(StrategyEntryType.limit_0_5R) - 0.5) > 0.0000001 ||
                CTraderStrategyEngine.ResolveEntryBufferMultiplier(StrategyEntryType._0_market) != 0.0)
            {
                throw new InvalidOperationException("Strategy entry-mode contract failed.");
            }
            if (!CTraderStrategyEngine.IsSpecialEntryType(StrategyEntryType.fvg_mid) ||
                CTraderStrategyEngine.IsSpecialEntryType(StrategyEntryType._0_market))
            {
                throw new InvalidOperationException("Strategy special-entry contract failed.");
            }

            TradeType direction;
            if (!CTraderStrategyEngine.TryResolveCrossDirection(1.0, 3.0, 2.0, 2.0, out direction) || direction != TradeType.Buy ||
                !CTraderStrategyEngine.TryResolveCrossDirection(3.0, 1.0, 2.0, 2.0, out direction) || direction != TradeType.Sell)
            {
                throw new InvalidOperationException("Strategy cross-direction contract failed.");
            }
            if (!CTraderStrategyEngine.TryResolveTripleTrendDirection(1.0, 4.0, 2.0, 3.0, 2.0, out direction) || direction != TradeType.Buy)
                throw new InvalidOperationException("Strategy triple-trend contract failed.");
            if (!CTraderStrategyEngine.TryResolveBollingerReversionDirection(8.0, 11.0, 9.0, 13.0, 10.0, out direction) || direction != TradeType.Buy)
                throw new InvalidOperationException("Strategy Bollinger-reversion contract failed.");
            if (!CTraderStrategyEngine.TryResolveThresholdReversionDirection(20.0, 31.0, 30.0, 70.0, out direction) || direction != TradeType.Buy ||
                !CTraderStrategyEngine.TryResolveThresholdReversionDirection(80.0, 69.0, 30.0, 70.0, out direction) || direction != TradeType.Sell)
            {
                throw new InvalidOperationException("Strategy threshold-reversion contract failed.");
            }
            if (!CTraderStrategyEngine.TryResolveFvgContextDirection(true, false, 9.0, 11.0, 10.5, 10.0, out direction) || direction != TradeType.Buy ||
                !CTraderStrategyEngine.TryResolveFvgContextDirection(false, true, 9.0, 11.0, 9.5, 10.0, out direction) || direction != TradeType.Sell)
            {
                throw new InvalidOperationException("Strategy FVG-context contract failed.");
            }
            if (!CTraderStrategyEngine.TryResolveDonchianBreakoutDirection(12.0, 11.0, 9.0, out direction) || direction != TradeType.Buy)
                throw new InvalidOperationException("Strategy Donchian-breakout contract failed.");
            if (!CTraderStrategyEngine.TryResolvePriceActionDirection(true, false, true, false, out direction) || direction != TradeType.Buy ||
                CTraderStrategyEngine.TryResolvePriceActionDirection(false, false, true, true, out direction))
            {
                throw new InvalidOperationException("Strategy price-action direction contract failed.");
            }

            var signal = CTraderStrategyEngine.CreateSignal(
                "contract", BacktestStrategyMode.Off, "EURUSD", "m15.test",
                TradeType.Buy, TimeFrame.Minute15, new DateTime(2020, 1, 1));
            if (!signal.IsValid || signal.StrategyId != "contract" || signal.TradeType != TradeType.Buy)
                throw new InvalidOperationException("Strategy signal-construction contract failed.");
            if (CTraderStrategyEngine.ResolveAutoStopLossSource(0) != CTraderStrategyStopSource.EventInvalidation ||
                CTraderStrategyEngine.ResolveAutoStopLossSource(CTraderStrategyEngine.AutoStopLossSourceCount - 1) != CTraderStrategyStopSource.CandleRange5 ||
                CTraderStrategyEngine.ResolveAutoTakeProfitSource(0) != CTraderStrategyTargetSource.Liquidity ||
                CTraderStrategyEngine.ResolveAutoTakeProfitSource(CTraderStrategyEngine.AutoTakeProfitSourceCount - 1) != CTraderStrategyTargetSource.RewardRisk2)
            {
                throw new InvalidOperationException("Strategy automatic-protection priority contract failed.");
            }
            if (CTraderStrategyEngine.ResolveDirectionalConfluenceComponentScore(2, true) != 1 ||
                CTraderStrategyEngine.ResolveDirectionalConfluenceComponentScore(-2, true) != -1 ||
                CTraderStrategyEngine.ResolveDirectionalConfluenceComponentScore(1, false) != 0)
            {
                throw new InvalidOperationException("Strategy directional-confluence contract failed.");
            }
        }

        private static void ValidateExecutionEngineContracts()
        {
            if (!CTraderExecutionEngine.UsesNativeTrailing(StrategyExitMode.Trailing_Stop) ||
                CTraderExecutionEngine.UsesNativeTrailing(StrategyExitMode.Break_Even) ||
                !CTraderExecutionEngine.UsesNativeBreakEven(StrategyExitMode.Break_Even_Reversed_when_SL) ||
                !CTraderExecutionEngine.ReversesStoppedPosition(StrategyExitMode.Reversed_when_SL) ||
                CTraderExecutionEngine.ReversesStoppedPosition(StrategyExitMode.Off))
            {
                throw new InvalidOperationException("Execution exit-mode contract failed.");
            }
            if (Math.Abs(CTraderExecutionEngine.ResolveBreakEvenTriggerPips(100.0, 90.0, 0.5) - 20.0) > 0.0000001 ||
                Math.Abs(CTraderExecutionEngine.ResolveBreakEvenTriggerPips(100.0, 99.0, 1.0) - 10.1) > 0.0000001)
            {
                throw new InvalidOperationException("Execution break-even contract failed.");
            }
            if (!CTraderExecutionEngine.HasRequiredProtection(true, false, true, false) ||
                CTraderExecutionEngine.HasRequiredProtection(false, true, true, true) ||
                !CTraderExecutionEngine.IsProtectionCloseEnough(10.04, 10.0, true, 0.05) ||
                CTraderExecutionEngine.IsProtectionCloseEnough(10.06, 10.0, true, 0.05))
            {
                throw new InvalidOperationException("Execution protection-state contract failed.");
            }

            CTraderExecutionReversePlan reversePlan;
            if (CTraderExecutionEngine.TryBuildReversePlan(
                    null, TradeType.Buy, 100.0, 90.0, 99.0, 101.0, 2.0, out reversePlan) ||
                reversePlan.Error != "symbol_or_original_sl_unavailable")
            {
                throw new InvalidOperationException("Execution reverse-plan validation contract failed.");
            }
            var affordableEntries = new List<double> { 1.0 };
            var affordableWeights = new List<double> { 1.0 };
            if (CTraderExecutionEngine.TryResolveAffordableSplitLegs(
                    null, new[] { 1.0 }, new[] { 1.0 }, 0.9, 100.0,
                    affordableEntries, affordableWeights) ||
                affordableEntries.Count != 0 || affordableWeights.Count != 0)
            {
                throw new InvalidOperationException("Execution split-validation contract failed.");
            }
        }

        private static void ValidateSyncEngineContracts()
        {
            var now = new DateTime(2026, 8, 24, 12, 0, 0, DateTimeKind.Utc);
            if (!CTraderSyncEngine.IsDue(now, DateTime.MinValue, 30) ||
                CTraderSyncEngine.IsDue(now, now.AddSeconds(-29), 30) ||
                !CTraderSyncEngine.IsDue(now, now.AddSeconds(-30), 30))
            {
                throw new InvalidOperationException("Sync cadence contract failed.");
            }
            if (!CTraderSyncEngine.IsErrorAckStatus(" rejected ") ||
                CTraderSyncEngine.IsErrorAckStatus("FILLED") ||
                CTraderSyncEngine.ResolveAckRetryDelayMilliseconds(1) != 400 ||
                CTraderSyncEngine.ResolveAckRetryDelayMilliseconds(2) != 800)
            {
                throw new InvalidOperationException("Sync acknowledgement contract failed.");
            }
            if (CTraderSyncEngine.DeriveSyncEventCode("CLOSED", false, false, false, false) != "SNAPSHOT_CLOSED" ||
                CTraderSyncEngine.DeriveSyncEventCode("FILLED", true, false, false, false) != "STATUS_FILLED" ||
                CTraderSyncEngine.DeriveSyncEventCode("FILLED", false, true, false, false) != "PROTECTION_UPDATED" ||
                CTraderSyncEngine.ResolveSyncEventBucket("cancelled") != "closed" ||
                CTraderSyncEngine.ResolveSyncEventBucket("filled") != "changed")
            {
                throw new InvalidOperationException("Sync event-classification contract failed.");
            }

            var coverage = CTraderSyncEngine.ParseCoverage(
                "{\"items\":[{\"symbol\":\"EURUSD\",\"tf\":\"15\",\"existing_bars\":125,\"bars_number\":500,\"end\":1700000000}]}",
                "eurusd",
                "15");
            var fetchPlan = CTraderSyncEngine.BuildIncrementalFetchPlan(
                coverage.RemoteEnd, coverage.ExistingBars, coverage.TargetBars, 1700001800, 900);
            if (coverage.ExistingBars != 125 || coverage.TargetBars != 500 || coverage.RemoteEnd != 1700000000 ||
                !fetchPlan.ShouldFetch || fetchPlan.FetchStart != 1700000900 || fetchPlan.NeededBars != 2)
            {
                throw new InvalidOperationException("Sync incremental-coverage contract failed.");
            }
            var backfillPlan = CTraderSyncEngine.BuildIncrementalFetchPlan(0, 0, 500, 1700000000, 60);
            if (!backfillPlan.ShouldFetch || backfillPlan.FetchStart != 1699970000 || backfillPlan.NeededBars != 500 ||
                CTraderSyncEngine.ResolveIncrementalPostLimit(true, 100) != 500 ||
                CTraderSyncEngine.ResolveIncrementalPostLimit(false, 900) != 500 ||
                CTraderSyncEngine.ToUnixTimeSeconds(new DateTime(1970, 1, 1)) != 0)
            {
                throw new InvalidOperationException("Sync incremental-planning contract failed.");
            }

            int inserted;
            int duplicated;
            CTraderSyncEngine.ParseIncrementalResult("{\"inserted\":12,\"duplicated\":3}", out inserted, out duplicated);
            var barsPayload = CTraderSyncEngine.BuildBarsPayload("\"account_id\":\"A1\"", new[] { "{\"t\":1}" });
            var incrementalPayload = CTraderSyncEngine.BuildIncrementalBarsPayload(
                "\"account_id\":\"A1\"", new[] { "{\"symbol\":\"EURUSD\"}" });
            var syncPayload = CTraderSyncEngine.BuildSyncPayload(
                "\"account_id\":\"A1\"", 100, 101, 2, "Broker", "provider", "build",
                new[] { "{\"id\":1}" }, new string[0], new string[0], "[]", true,
                new string[0], new[] { Tuple.Create("EURUSD", 1.1, 1.2) });
            var ackPayload = CTraderSyncEngine.BuildAckPayload(
                "\"account_id\":\"A1\"", "sid", "token", "FILLED", "ticket", "", 1.1,
                10, 0.1, 1, 1, 2, 2, 10, 20);
            var tickets = new HashSet<string>(Enumerable.Range(1, 6).Select(value => value.ToString(CultureInfo.InvariantCulture)));
            if (inserted != 12 || duplicated != 3 ||
                barsPayload != "{\"account_id\":\"A1\",\"bars\":[{\"t\":1}]}" ||
                incrementalPayload != "{\"account_id\":\"A1\",\"sync_mode\":\"incremental\",\"items\":[{\"symbol\":\"EURUSD\"}]}" ||
                !syncPayload.Contains("\"queue_snapshot_hydrated\":true") ||
                !syncPayload.Contains("\"prices\":[{\"s\":\"EURUSD\",\"b\":1.10000,\"a\":1.20000}]") ||
                !ackPayload.Contains("\"execution_status\":\"FILLED\"") ||
                !ackPayload.Contains("\"sl_pips\":10.00,\"tp_pips\":20.00") ||
                CTraderSyncEngine.TrimClosedTicketSet(tickets, 5, 3) != 3 || tickets.Count != 3)
            {
                throw new InvalidOperationException("Sync payload/result/retention contract failed.");
            }
        }

        private static void ValidateChartEngineContracts()
        {
            if (CTraderChartEngine.GetMarkerFontSize(ChartMarkerFontSizeMode.None) != 0 ||
                CTraderChartEngine.GetMarkerFontSize(ChartMarkerFontSizeMode.Small) != 8 ||
                CTraderChartEngine.ResolveMarkerFontSize(
                    ChartMarkerFontSizeMode.Small, TimeFrame.Minute15, TimeFrame.Daily, true) != 12 ||
                CTraderChartEngine.GetDirectionalMarkerIcon(ChartMarkerSymbolMode.Triangles, true) != "▲" ||
                CTraderChartEngine.FormatDirectionalMarkerText(
                    "bos", false, ChartMarkerSymbolMode.Arrows, ChartLabelVisibilityMode.Yes) != "↓ BOS")
            {
                throw new InvalidOperationException("Chart marker policy contract failed.");
            }

            var splitterFrames = CTraderChartEngine.GetAutoSplitterTimeFrames(TimeFrame.Minute);
            int baseMinutes;
            int nth;
            var splitterBase = CTraderChartEngine.ResolveSplitterBaseTimeFrame(480, out baseMinutes, out nth);
            var htfFrames = CTraderChartEngine.GetEnabledHigherTimeFrames(
                TimeFrame.Minute15, HtfSlotMode.Auto, HtfSlotMode.Auto);
            if (splitterFrames.Count != 3 || splitterFrames[0] != TimeFrame.Minute15 ||
                splitterBase != TimeFrame.Hour4 || baseMinutes != 240 || nth != 2 ||
                htfFrames.Count != 2 || htfFrames[0] != TimeFrame.Hour4 || htfFrames[1] != TimeFrame.Daily ||
                CTraderChartEngine.GetMiniChartBars(TimeFrame.Weekly) != 4 ||
                CTraderChartEngine.GetMiniChartBars(TimeFrame.Hour4) != 12 ||
                Math.Abs(CTraderChartEngine.GetMiniChartSlotWidth(7, 4.0) - 28.0) > 0.0000001)
            {
                throw new InvalidOperationException("Chart HTF layout contract failed.");
            }

            if (CTraderChartEngine.NormalizeDisplayTimeFramePrefix("1h.eql") != "h1.eql" ||
                CTraderChartEngine.NormalizeArtifactDisplayLabel("r.1h.Key High", "h1") != "h1.r.Key High" ||
                CTraderChartEngine.NormalizeArtifactDisplayLabel("Key Low", "h4") != "h4.p.l" ||
                CTraderChartEngine.NormalizeEventLabelPriorityKey("CHOCH_CONFIRMED") != "CHOCH" ||
                CTraderChartEngine.GetEventLabelPriorityScore("bos.r") != 95)
            {
                throw new InvalidOperationException("Chart label contract failed.");
            }

            var now = new DateTime(2026, 8, 24, 12, 0, 0, DateTimeKind.Utc);
            if (CTraderChartEngine.ShouldRefresh(10, "same", 10, "same", DateTime.MinValue, now, 0) ||
                CTraderChartEngine.ShouldRefresh(10, "old", 11, "new", now.AddSeconds(-4), now, 5) ||
                !CTraderChartEngine.ShouldRefresh(10, "old", 11, "new", now.AddSeconds(-5), now, 5) ||
                CTraderChartEngine.AdvanceRefreshPhase(5, 6) != 0 ||
                CTraderChartEngine.NormalizeToolbarDirection("sell", "All") != "Sell" ||
                CTraderChartEngine.NormalizeToolbarOrderCount("9", "Auto") != "Auto" ||
                CTraderChartEngine.ResolveToolbarOrderCount("4") != 4 ||
                CTraderChartEngine.NormalizeToolbarTradeProfile("daily", "Scalp") != "Daily")
            {
                throw new InvalidOperationException("Chart refresh/toolbar contract failed.");
            }

            if (CTraderChartEngine.PadCell("abcdef", 4, false) != "abcd" ||
                CTraderChartEngine.BuildTextTableRow("A", "B") != " A   B " ||
                CTraderChartEngine.CountTextLines("a\nb") != 2 ||
                CTraderChartEngine.FormatDashboardNumber(1.6) != "2" ||
                CTraderChartEngine.FormatDashboardPercent(1.5) != "1.50")
            {
                throw new InvalidOperationException("Chart dashboard-formatting contract failed.");
            }
        }

        private StructureSnapshotV2 BuildStructureSnapshotV2(Bars sourceBars, int lookbackBars, int endIndex = -1)
        {
            var lastClosedBarIndex = ResolveStructureLastClosedBarIndex(sourceBars, endIndex);
            string cacheKey = null;
            if (sourceBars != null && lastClosedBarIndex >= 0)
            {
                cacheKey = string.Join(
                    "|",
                    new[]
                    {
                        sourceBars.GetHashCode().ToString(CultureInfo.InvariantCulture),
                        sourceBars.OpenTimes[lastClosedBarIndex].Ticks.ToString(CultureInfo.InvariantCulture),
                        Math.Max(lookbackBars, 10).ToString(CultureInfo.InvariantCulture),
                        ZoneFvgDisplacement.ToString(),
                        ZoneFvgBodyRatio.ToString(),
                        ZoneFvgGap.ToString(),
                        ZoneVolumeSurgePreset.ToString()
                    });
            }

            var snapshot = new StructureSnapshotV2
            {
                LastClosedBarIndex = lastClosedBarIndex
            };
            if (snapshot.LastClosedBarIndex < 0)
                return snapshot;

            return _structureEngine.GetOrCreateSnapshot(
                cacheKey,
                32,
                () => BuildStructureSnapshotFromAnalysisService(sourceBars, lookbackBars, snapshot.LastClosedBarIndex));
        }

        private StructureSnapshotV2 BuildStructureSnapshotFromAnalysisService(Bars sourceBars, int lookbackBars, int lastClosedBarIndex)
        {
            var snapshot = new StructureSnapshotV2 { LastClosedBarIndex = lastClosedBarIndex };
            if (sourceBars == null || lastClosedBarIndex < 0)
                return snapshot;

            int sourceIndexOffset;
            var request = new FortyTwo.Trading.Analysis.MarketAnalysisRequest
            {
                Symbol = BuildMarketAnalysisSymbolInput(),
                Config = BuildMarketAnalysisConfig(lookbackBars),
                Confluence = BuildMarketAnalysisConfluenceConfig(),
                Strategy = BuildMarketAnalysisStrategyConfig(),
                TimeFrames = new List<FortyTwo.Trading.Analysis.MarketTimeFrameInput>
                {
                    BuildMarketAnalysisTimeFrameInput(sourceBars, lastClosedBarIndex, lookbackBars, out sourceIndexOffset)
                }
            };
            var result = _structureEngine.Analyze(request);
            var frame = result.TimeFrames.FirstOrDefault();
            if (frame == null)
                return snapshot;

            snapshot.Swings = frame.Swings.Select(value => new SwingPoint
            {
                BarIndex = value.Index + sourceIndexOffset,
                Time = value.TimeUtc,
                Price = value.Price,
                IsHigh = value.IsHigh
            }).ToList();
            snapshot.Events = frame.Structures.Select(value => new StructureEventV2
            {
                Type = value.Type == FortyTwo.Trading.Analysis.MarketStructureEventType.Choch
                    ? StructureEventTypeV2.Choch
                    : value.Type == FortyTwo.Trading.Analysis.MarketStructureEventType.Sweep
                        ? StructureEventTypeV2.Sweep
                        : StructureEventTypeV2.Bos,
                TriggerBarIndex = value.TriggerIndex + sourceIndexOffset,
                ConfirmationBarIndex = value.ConfirmationIndex + sourceIndexOffset,
                ReferenceSwingIndex = value.ReferenceSwingIndex + sourceIndexOffset,
                ReferencePrice = value.ReferencePrice,
                IsBullish = value.Direction == FortyTwo.Trading.Analysis.MarketDirection.Bullish,
                BiasBefore = MapAnalysisStructureBias(value.BiasBefore),
                BiasAfter = MapAnalysisStructureBias(value.BiasAfter)
            }).ToList();
            snapshot.Zones = frame.Zones
                .Where(value => value.Type == FortyTwo.Trading.Analysis.MarketZoneType.Fvg ||
                                value.Type == FortyTwo.Trading.Analysis.MarketZoneType.InverseFvg ||
                                value.Type == FortyTwo.Trading.Analysis.MarketZoneType.OrderBlock ||
                                value.Type == FortyTwo.Trading.Analysis.MarketZoneType.BreakerBlock)
                .Select(value => new StructureZoneV2
                {
                    Type = value.Type == FortyTwo.Trading.Analysis.MarketZoneType.InverseFvg
                        ? StructureZoneTypeV2.InverseFvg
                        : value.Type == FortyTwo.Trading.Analysis.MarketZoneType.OrderBlock
                            ? StructureZoneTypeV2.OrderBlock
                            : value.Type == FortyTwo.Trading.Analysis.MarketZoneType.BreakerBlock
                                ? StructureZoneTypeV2.BreakerBlock
                                : StructureZoneTypeV2.Fvg,
                    State = value.State == FortyTwo.Trading.Analysis.MarketZoneState.Invalidated
                        ? StructureZoneStateV2.Invalidated
                        : value.State == FortyTwo.Trading.Analysis.MarketZoneState.Touched
                            ? StructureZoneStateV2.Touched
                            : StructureZoneStateV2.Active,
                    IsBullish = value.Direction == FortyTwo.Trading.Analysis.MarketDirection.Bullish,
                    OriginBarIndex = value.OriginIndex + sourceIndexOffset,
                    ConfirmationBarIndex = value.ConfirmationIndex + sourceIndexOffset,
                    TouchBarIndex = value.TouchIndex >= 0 ? value.TouchIndex + sourceIndexOffset : -1,
                    InvalidationBarIndex = value.InvalidationIndex >= 0 ? value.InvalidationIndex + sourceIndexOffset : -1,
                    Low = value.Low,
                    High = value.High
                }).ToList();
            return snapshot;
        }

        private FortyTwo.Trading.Analysis.MarketSymbolInput BuildMarketAnalysisSymbolInput()
        {
            return new FortyTwo.Trading.Analysis.MarketSymbolInput
            {
                Name = Symbol != null ? Symbol.Name ?? "" : "",
                PipSize = Symbol != null ? Symbol.PipSize : 0.00001,
                Digits = Symbol != null ? Symbol.Digits : 5
            };
        }

        private FortyTwo.Trading.Analysis.MarketTimeFrameInput BuildMarketAnalysisTimeFrameInput(
            Bars sourceBars,
            int lastClosedBarIndex,
            int lookbackBars,
            out int sourceIndexOffset)
        {
            sourceIndexOffset = 0;
            var safeLastClosedIndex = Math.Min(lastClosedBarIndex, sourceBars != null ? sourceBars.Count - 1 : -1);
            if (sourceBars != null && safeLastClosedIndex >= 0)
            {
                // Include a small pre-roll for swing confirmation and two-bar zone checks, but
                // never clone the entire loaded chart for a bounded lookback analysis.
                var requestedBars = Math.Max(20, lookbackBars) + 8;
                sourceIndexOffset = Math.Max(0, safeLastClosedIndex - requestedBars + 1);
            }
            var frame = new FortyTwo.Trading.Analysis.MarketTimeFrameInput
            {
                Name = Chart != null && Chart.TimeFrame != null ? Chart.TimeFrame.ToString() : "",
                LastClosedIndex = safeLastClosedIndex >= 0 ? safeLastClosedIndex - sourceIndexOffset : -1
            };
            if (sourceBars == null || frame.LastClosedIndex < 0)
                return frame;

            for (var i = sourceIndexOffset; i <= safeLastClosedIndex; i++)
            {
                frame.Candles.Add(new FortyTwo.Trading.Analysis.MarketCandle
                {
                    Index = i - sourceIndexOffset,
                    OpenTimeUtc = sourceBars.OpenTimes[i],
                    Open = sourceBars.OpenPrices[i],
                    High = sourceBars.HighPrices[i],
                    Low = sourceBars.LowPrices[i],
                    Close = sourceBars.ClosePrices[i],
                    Volume = GetSharedRuleBarVolume(sourceBars, i)
                });
            }
            return frame;
        }

        private FortyTwo.Trading.Analysis.MarketAnalysisConfig BuildMarketAnalysisConfig(int lookbackBars)
        {
            return new FortyTwo.Trading.Analysis.MarketAnalysisConfig
            {
                Scope = new FortyTwo.Trading.Analysis.AnalysisScopeConfig
                {
                    Swings = true,
                    Structures = true,
                    Zones = true,
                    KeyLevels = false,
                    CandlePatterns = false,
                    Confluences = false,
                    Trades = false
                },
                Swings = new FortyTwo.Trading.Analysis.SwingAnalysisConfig
                {
                    Strength = 2,
                    LookbackBars = Math.Max(lookbackBars, 10)
                },
                Structures = new FortyTwo.Trading.Analysis.StructureAnalysisConfig
                {
                    LookbackBars = Math.Max(lookbackBars, 12),
                    ConsumeBrokenLevels = true,
                    ConsumeSweptLevels = true,
                    DetectTwoBarSweeps = true,
                    ExternalBias = FortyTwo.Trading.Analysis.MarketDirection.Neutral
                },
                Zones = new FortyTwo.Trading.Analysis.ZoneAnalysisConfig
                {
                    LookbackBars = Math.Max(lookbackBars, 20),
                    FvgDisplacementRatio = ResolveZoneFvgDisplacementRatio(ZoneFvgDisplacement),
                    FvgBodyRatio = ResolveZoneFvgBodyRatio(ZoneFvgBodyRatio),
                    FvgGapRatio = ResolveZoneFvgGapPercent(ZoneFvgGap),
                    OrderBlockBodyRatio = 0.55,
                    OrderBlockOriginLookback = 5,
                    VolumeSurgeMultiplier = ZoneVolumeSurgePreset == VolumeSurgeMode.No ? 1.0 : GetVolumeSurgeMultiplier(ZoneVolumeSurgePreset)
                },
                Trades = new FortyTwo.Trading.Analysis.TradePlanAnalysisConfig
                {
                    StopBufferRatio = 0.10,
                    RewardRiskRatio = Math.Max(0.1, StrategyRewardRisk),
                    LimitEntryRatios = new List<double> { 0.25, 0.50, 0.75 }
                }
            };
        }

        private FortyTwo.Trading.Analysis.AnalysisConfluenceConfig BuildMarketAnalysisConfluenceConfig()
        {
            return new FortyTwo.Trading.Analysis.AnalysisConfluenceConfig
            {
                ConfluenceCatalog = _sharedRuleCatalog,
                EventCatalog = _sharedEventCatalog
            };
        }

        private FortyTwo.Trading.Analysis.AnalysisStrategyConfig BuildMarketAnalysisStrategyConfig()
        {
            return new FortyTwo.Trading.Analysis.AnalysisStrategyConfig
            {
                StrategyId = Convert.ToString(SelectedBacktestStrategy, CultureInfo.InvariantCulture) ?? "",
                AllowedDirection = FortyTwo.Trading.Analysis.MarketDirection.Neutral,
                MinimumConfluenceScore = 0,
                StrategyCatalog = _sharedStrategyCatalog
            };
        }

        private StructureBias MapAnalysisStructureBias(FortyTwo.Trading.Analysis.MarketDirection direction)
        {
            if (direction == FortyTwo.Trading.Analysis.MarketDirection.Bullish)
                return StructureBias.Bullish;
            if (direction == FortyTwo.Trading.Analysis.MarketDirection.Bearish)
                return StructureBias.Bearish;
            return StructureBias.Neutral;
        }

        private List<SwingPoint> CollectConfirmedSwings(Bars sourceBars, int lookbackBars, int endIndex = -1)
        {
            return BuildStructureSnapshotV2(sourceBars, lookbackBars, endIndex).Swings;
        }

        private void AddFvgLevelCandidates(List<double> candidates, Bars sourceBars, double tolerance)
        {
            if (sourceBars == null || sourceBars.Count < 3)
                return;

            var zones = BuildStructureSnapshotV2(sourceBars, ResolveWorkingLookbackBars(sourceBars)).Zones
                .Where(value => (value.Type == StructureZoneTypeV2.Fvg || value.Type == StructureZoneTypeV2.InverseFvg) && value.State == StructureZoneStateV2.Active)
                .OrderByDescending(value => value.ConfirmationBarIndex)
                .Take(8);
            foreach (var zone in zones)
            {
                AddDistinctChartLevel(candidates, zone.Low, tolerance);
                AddDistinctChartLevel(candidates, zone.High, tolerance);
            }
        }

        private void AddOrderBlockLevelCandidates(List<double> candidates, Bars sourceBars, double tolerance)
        {
            if (sourceBars == null || sourceBars.Count < 4)
                return;

            var zones = BuildStructureSnapshotV2(sourceBars, ResolveWorkingLookbackBars(sourceBars)).Zones
                .Where(value => (value.Type == StructureZoneTypeV2.OrderBlock || value.Type == StructureZoneTypeV2.BreakerBlock) && value.State == StructureZoneStateV2.Active)
                .OrderByDescending(value => value.ConfirmationBarIndex)
                .Take(6);
            foreach (var zone in zones)
            {
                AddDistinctChartLevel(candidates, zone.Low, tolerance);
                AddDistinctChartLevel(candidates, zone.High, tolerance);
            }
        }

        private void AddFvgZoneCandidates(List<ChartLevelCandidate> candidates, Bars sourceBars, double tolerance, int weight = 1)
        {
            if (candidates == null || sourceBars == null || sourceBars.Count < 3)
                return;

            var zones = BuildStructureSnapshotV2(sourceBars, ResolveWorkingLookbackBars(sourceBars)).Zones
                .Where(value => (value.Type == StructureZoneTypeV2.Fvg || value.Type == StructureZoneTypeV2.InverseFvg) && value.State == StructureZoneStateV2.Active)
                .OrderByDescending(value => value.ConfirmationBarIndex)
                .Take(8);
            foreach (var zone in zones)
            {
                candidates.Add(new ChartLevelCandidate { Price = zone.Low, Weight = weight, ZoneLow = zone.Low, ZoneHigh = zone.High, Kind = "FVG" });
                candidates.Add(new ChartLevelCandidate { Price = zone.High, Weight = weight, ZoneLow = zone.Low, ZoneHigh = zone.High, Kind = "FVG" });
            }
        }

        private void AddOrderBlockZoneCandidates(List<ChartLevelCandidate> candidates, Bars sourceBars, double tolerance, int weight = 1)
        {
            if (candidates == null || sourceBars == null || sourceBars.Count < 4)
                return;

            var zones = BuildStructureSnapshotV2(sourceBars, ResolveWorkingLookbackBars(sourceBars)).Zones
                .Where(value => (value.Type == StructureZoneTypeV2.OrderBlock || value.Type == StructureZoneTypeV2.BreakerBlock) && value.State == StructureZoneStateV2.Active)
                .OrderByDescending(value => value.ConfirmationBarIndex)
                .Take(6);
            foreach (var zone in zones)
            {
                candidates.Add(new ChartLevelCandidate { Price = zone.Low, Weight = weight, ZoneLow = zone.Low, ZoneHigh = zone.High, Kind = "OB" });
                candidates.Add(new ChartLevelCandidate { Price = zone.High, Weight = weight, ZoneLow = zone.Low, ZoneHigh = zone.High, Kind = "OB" });
            }
        }

        private void AddSessionLiquidityLevelCandidates(List<double> candidates, string sessionName, double tolerance)
        {
            if (Bars == null || Bars.Count < 10)
                return;

            var prevDate = GetReferenceNow().Date.AddDays(-1);
            DateTime startUtc;
            DateTime endUtc;
            if (!TryGetSessionUtcRange(sessionName, prevDate, out startUtc, out endUtc))
                return;

            double high;
            double low;
            DateTime highTime;
            DateTime lowTime;
            if (!TryGetRangeHighLow(Bars, startUtc, endUtc, out high, out low, out highTime, out lowTime))
                return;

            AddDistinctChartLevel(candidates, high, tolerance);
            AddDistinctChartLevel(candidates, low, tolerance);
        }

        private void AddPreviousPeriodLevelCandidates(List<double> candidates, string symbolName, TimeFrame timeFrame, double tolerance)
        {
            try
            {
                var sourceBars = MarketData.GetBars(timeFrame, symbolName);
                if (sourceBars == null || sourceBars.Count < 1)
                    return;

                int idx;
                if (!TryGetPreviousCompletedPeriodBarIndex(sourceBars, timeFrame, out idx))
                    return;

                AddDistinctChartLevel(candidates, sourceBars.HighPrices[idx], tolerance);
                AddDistinctChartLevel(candidates, sourceBars.LowPrices[idx], tolerance);
            }
            catch
            {
            }
        }

        private void AddEqualHighLowCandidates(List<double> candidates, Bars sourceBars, double tolerance)
        {
            foreach (var pattern in DetectSwingLevelPatterns(sourceBars, tolerance))
            {
                AddDistinctChartLevel(candidates, pattern.Level, tolerance);

                // Confirmed double tops/bottoms get an extra usable reference at the neckline.
                if (pattern.HasNeckline && pattern.NecklineBroken &&
                    (pattern.Type == SwingLevelPatternType.DoubleTop || pattern.Type == SwingLevelPatternType.DoubleBottom))
                {
                    AddDistinctChartLevel(candidates, pattern.NecklinePrice, tolerance);
                }
            }
        }

        private List<SwingLevelPattern> DetectSwingLevelPatterns(Bars sourceBars, double tolerance)
        {
            var swings = CollectConfirmedSwings(sourceBars, ResolveWorkingSwingLookbackBars(sourceBars));
            var closes = Enumerable.Range(0, sourceBars.Count).Select(index => sourceBars.ClosePrices[index]).ToList();
            return _structureEngine.DetectSwingLevelPatterns(
                    swings.Select(value => new CTraderStructureSwing
                    {
                        Index = value.BarIndex,
                        Price = value.Price,
                        IsHigh = value.IsHigh
                    }).ToList(),
                    closes,
                    tolerance)
                .Select(value => new SwingLevelPattern
                {
                    Type = (SwingLevelPatternType)value.Kind,
                    IndexA = value.IndexA,
                    IndexB = value.IndexB,
                    PriceA = value.PriceA,
                    PriceB = value.PriceB,
                    Level = value.Level,
                    NecklineIndex = value.NecklineIndex,
                    NecklinePrice = value.NecklinePrice,
                    HasNeckline = value.HasNeckline,
                    NecklineBroken = value.NecklineBroken
                })
                .ToList();
        }

        private void AddClusteredSwingLiquidityCandidates(List<double> candidates, Bars sourceBars, double tolerance)
        {
            var swings = CollectConfirmedSwings(sourceBars, ResolveWorkingSwingLookbackBars(sourceBars)).TakeLast(20).ToList();
            if (swings.Count < 2)
                return;

            var highs = swings.Where(s => s.IsHigh).ToList();
            var lows = swings.Where(s => !s.IsHigh).ToList();

            foreach (var cluster in highs.GroupBy(s => Math.Round(s.Price / (tolerance * 2.0))))
            {
                var list = cluster.ToList();
                if (list.Count >= 2)
                    AddDistinctChartLevel(candidates, list.Average(x => x.Price), tolerance);
            }

            foreach (var cluster in lows.GroupBy(s => Math.Round(s.Price / (tolerance * 2.0))))
            {
                var list = cluster.ToList();
                if (list.Count >= 2)
                    AddDistinctChartLevel(candidates, list.Average(x => x.Price), tolerance);
            }
        }

        private void AddFvgEntryCandidates(List<ChartEntryCandidate> candidates, Bars sourceBars, double tolerance)
        {
            if (sourceBars == null || sourceBars.Count < 3)
                return;

            var zones = BuildStructureSnapshotV2(sourceBars, ResolveWorkingLookbackBars(sourceBars)).Zones
                .Where(value => (value.Type == StructureZoneTypeV2.Fvg || value.Type == StructureZoneTypeV2.InverseFvg) && value.State == StructureZoneStateV2.Active)
                .OrderByDescending(value => value.ConfirmationBarIndex)
                .Take(8);
            foreach (var zone in zones)
            {
                candidates.Add(new ChartEntryCandidate
                {
                    Label = zone.Type == StructureZoneTypeV2.InverseFvg ? "iFVG" : "FVG",
                    Low = zone.Low,
                    High = zone.High,
                    Entry = NormalizePriceToSymbol(Symbol, (zone.Low + zone.High) * 0.5),
                    Time = sourceBars.OpenTimes[zone.Type == StructureZoneTypeV2.InverseFvg ? zone.ConfirmationBarIndex : zone.OriginBarIndex]
                });
            }
        }

        private void AddOrderBlockEntryCandidates(List<ChartEntryCandidate> candidates, Bars sourceBars, double tolerance)
        {
            if (sourceBars == null || sourceBars.Count < 4)
                return;

            var zones = BuildStructureSnapshotV2(sourceBars, ResolveWorkingLookbackBars(sourceBars)).Zones
                .Where(value => (value.Type == StructureZoneTypeV2.OrderBlock || value.Type == StructureZoneTypeV2.BreakerBlock) && value.State == StructureZoneStateV2.Active)
                .OrderByDescending(value => value.ConfirmationBarIndex)
                .Take(6);
            foreach (var zone in zones)
            {
                candidates.Add(new ChartEntryCandidate
                {
                    Label = zone.Type == StructureZoneTypeV2.BreakerBlock ? "BB" : "OB",
                    Low = zone.Low,
                    High = zone.High,
                    Entry = NormalizePriceToSymbol(Symbol, (zone.Low + zone.High) * 0.5),
                    Time = sourceBars.OpenTimes[zone.Type == StructureZoneTypeV2.BreakerBlock ? zone.ConfirmationBarIndex : zone.OriginBarIndex]
                });
            }
        }

        private List<double> CollectChartLiquidityLevels(Symbol symbol, string symbolName, string profileRaw)
        {
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || IsChartAllSymbolsSelection(symbolName))
                return new List<double>();

            var cacheKey = string.Format(
                CultureInfo.InvariantCulture,
                "{0}|{1}|liq|{2}|{3}|{4}|{5}|{6}",
                symbolName.ToUpperInvariant(),
                GetChartTradeProfileRaw(profileRaw),
                MinStopPips,
                true,
                true,
                true,
                Chart != null ? Chart.TimeFrame.ToString() : "");
            return GetOrCreateTimedCacheValue(
                _chartLiquidityCache,
                cacheKey,
                ChartStructureCacheTtl,
                () => CollectChartLiquidityLevelsCore(symbol, symbolName, profileRaw));
        }

        private List<double> CollectChartLiquidityLevelsCore(Symbol symbol, string symbolName, string profileRaw)
        {
            var candidates = new List<double>();
            var started = Stopwatch.StartNew();

            var tolerance = Math.Max(symbol.PipSize * 2.0, 0.0000001);
            try
            {
                foreach (var sourceTimeFrame in GetChartProtectionSourceTimeFrames(profileRaw))
                {
                    var sourceBars = MarketData.GetBars(sourceTimeFrame, symbolName);
                    if (sourceBars == null || sourceBars.Count < 5)
                        continue;

                    AddPreviousPeriodLevelCandidates(candidates, symbolName, sourceTimeFrame, tolerance);

                    foreach (var swing in CollectConfirmedSwings(sourceBars, ResolveWorkingSwingLookbackBars(sourceBars, sourceTimeFrame)).TakeLast(12))
                        AddDistinctChartLevel(candidates, swing.Price, tolerance);

                    AddEqualHighLowCandidates(candidates, sourceBars, tolerance);
                    AddClusteredSwingLiquidityCandidates(candidates, sourceBars, tolerance);
                }

                AddSessionLiquidityLevelCandidates(candidates, "London", tolerance);
                AddSessionLiquidityLevelCandidates(candidates, "NewYork", tolerance);
                AddSessionLiquidityLevelCandidates(candidates, "Asia", tolerance);
                AddPreviousPeriodLevelCandidates(candidates, symbolName, TimeFrame.Weekly, tolerance);
            }
            catch (Exception ex)
            {
                SafePrint("[ChartTrade] Liquidity levels failed for {0}: {1}", symbolName, ex.Message);
            }

            var result = candidates.OrderBy(v => v).ToList();
            LogSlowChartStep("CollectChartLiquidityLevels", started, string.Format(CultureInfo.InvariantCulture, "{0} {1} -> {2}", symbolName, GetChartTradeProfileRaw(profileRaw), result.Count));
            return result;
        }

        private List<double> CollectChartSwingStopLevels(Symbol symbol, string symbolName, string profileRaw, TradeType tradeType, double entryPrice)
        {
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || IsChartAllSymbolsSelection(symbolName) || entryPrice <= 0)
                return new List<double>();

            var cacheKey = string.Format(
                CultureInfo.InvariantCulture,
                "{0}|{1}|swingstop|{2}|{3}",
                symbolName.ToUpperInvariant(),
                GetChartTradeProfileRaw(profileRaw),
                tradeType,
                Chart != null ? Chart.TimeFrame.ToString() : "");
            var allCandidates = GetOrCreateTimedCacheValue(
                _chartSwingStopCache,
                cacheKey,
                ChartStructureCacheTtl,
                () => CollectChartSwingStopLevelsCore(symbol, symbolName, profileRaw, tradeType));

            return tradeType == TradeType.Buy
                ? allCandidates.Where(v => v < entryPrice).OrderByDescending(v => v).ToList()
                : allCandidates.Where(v => v > entryPrice).OrderBy(v => v).ToList();
        }

        private List<double> CollectChartSwingStopLevelsCore(Symbol symbol, string symbolName, string profileRaw, TradeType tradeType)
        {
            var candidates = new List<double>();
            var started = Stopwatch.StartNew();

            var tolerance = Math.Max(symbol.PipSize * 2.0, 0.0000001);
            try
            {
                foreach (var sourceTimeFrame in GetChartProtectionSourceTimeFrames(profileRaw))
                {
                    var sourceBars = MarketData.GetBars(sourceTimeFrame, symbolName);
                    if (sourceBars == null || sourceBars.Count < 5)
                        continue;

                    foreach (var swing in CollectConfirmedSwings(sourceBars, ResolveWorkingSwingLookbackBars(sourceBars, sourceTimeFrame)).TakeLast(16))
                    {
                        if (tradeType == TradeType.Buy)
                        {
                            if (!swing.IsHigh)
                                AddDistinctChartLevel(candidates, swing.Price, tolerance);
                        }
                        else
                        {
                            if (swing.IsHigh)
                                AddDistinctChartLevel(candidates, swing.Price, tolerance);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                SafePrint("[ChartTrade] Swing stops failed for {0}: {1}", symbolName, ex.Message);
            }

            var result = tradeType == TradeType.Buy
                ? candidates.OrderByDescending(v => v).ToList()
                : candidates.OrderBy(v => v).ToList();
            LogSlowChartStep("CollectChartSwingStopLevels", started, string.Format(CultureInfo.InvariantCulture, "{0} {1} {2} -> {3}", symbolName, GetChartTradeProfileRaw(profileRaw), tradeType, result.Count));
            return result;
        }

        private List<ChartEntryCandidate> CollectChartEntryCandidates(Symbol symbol, string symbolName, string profileRaw)
        {
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName))
                return new List<ChartEntryCandidate>();

            var cacheKey = string.Format(
                CultureInfo.InvariantCulture,
                "{0}|{1}|entry|{2}",
                symbolName.ToUpperInvariant(),
                GetChartTradeProfileRaw(profileRaw),
                Chart != null ? Chart.TimeFrame.ToString() : "");
            return GetOrCreateTimedCacheValue(
                _chartEntryCandidatesCache,
                cacheKey,
                ChartStructureCacheTtl,
                () => CollectChartEntryCandidatesCore(symbol, symbolName, profileRaw));
        }

        private List<ChartEntryCandidate> CollectChartEntryCandidatesCore(Symbol symbol, string symbolName, string profileRaw)
        {
            var candidates = new List<ChartEntryCandidate>();
            var started = Stopwatch.StartNew();

            var tolerance = Math.Max(symbol.PipSize * 2.0, 0.0000001);
            try
            {
                var sourceTimeFrame = GetChartEntrySourceTimeFrame(profileRaw);
                var sourceBars = MarketData.GetBars(sourceTimeFrame, symbolName);
                if (sourceBars == null || sourceBars.Count < 5)
                    return candidates;

                AddFvgEntryCandidates(candidates, sourceBars, tolerance);
                AddOrderBlockEntryCandidates(candidates, sourceBars, tolerance);
            }
            catch (Exception ex)
            {
                SafePrint("[ChartTrade] Entry levels failed for {0}: {1}", symbolName, ex.Message);
            }

            var result = candidates
                .Where(c => c.Entry > 0 && c.High >= c.Low)
                .GroupBy(c => Math.Round(c.Entry / tolerance) * tolerance)
                .Select(g => g.OrderByDescending(x => x.Time).First())
                .OrderByDescending(c => c.Time)
                .ToList();
            LogSlowChartStep("CollectChartEntryCandidates", started, string.Format(CultureInfo.InvariantCulture, "{0} {1} -> {2}", symbolName, GetChartTradeProfileRaw(profileRaw), result.Count));
            return result;
        }

        private ChartTradePlan BuildChartLimitPlanV2(Symbol symbol, string symbolName, TradeType tradeType, string profileRaw)
        {
            var started = Stopwatch.StartNew();
            var plan = new ChartTradePlan { IsValid = false, StructureTfLabel = GetChartTradeStructureTfLabel(profileRaw) };
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName))
                return plan;

            var currentPrice = tradeType == TradeType.Buy ? symbol.Ask : symbol.Bid;
            if (currentPrice <= 0)
                return plan;

            var entries = CollectChartEntryCandidates(symbol, symbolName, profileRaw);
            var liquidities = CollectChartLiquidityLevels(symbol, symbolName, profileRaw);
            if (entries.Count == 0 || liquidities.Count == 0)
                return plan;

            var lowerRange = liquidities.Where(v => v < currentPrice).DefaultIfEmpty(0).Max();
            var upperRange = liquidities.Where(v => v > currentPrice).DefaultIfEmpty(0).Min();
            var rrFloor = 1.5;
            var bestScore = double.MinValue;

            foreach (var candidate in entries)
            {
                var entry = NormalizePriceToSymbol(symbol, candidate.Entry);
                if (entry <= 0)
                    continue;

                if (tradeType == TradeType.Buy)
                {
                    if (entry >= currentPrice) continue;
                    if (lowerRange > 0 && entry < lowerRange) continue;
                    if (upperRange > 0 && entry > upperRange) continue;
                }
                else
                {
                    if (entry <= currentPrice) continue;
                    if (lowerRange > 0 && entry < lowerRange) continue;
                    if (upperRange > 0 && entry > upperRange) continue;
                }

                var swingStops = CollectChartSwingStopLevels(symbol, symbolName, profileRaw, tradeType, entry);
                var stop = tradeType == TradeType.Buy
                    ? swingStops.Where(v => v < entry).DefaultIfEmpty(0).FirstOrDefault()
                    : swingStops.Where(v => v > entry).DefaultIfEmpty(0).FirstOrDefault();
                var targetCandidates = tradeType == TradeType.Buy
                    ? liquidities.Where(v => v > entry).OrderBy(v => v).ToList()
                    : liquidities.Where(v => v < entry).OrderByDescending(v => v).ToList();

                if (stop <= 0 || targetCandidates.Count == 0)
                    continue;

                var minStopPips = ResolveMinStopPips(symbol);
                var stopBufferPips = Math.Max(GetChartProtectionBiasPips(symbol), Math.Max(1.0, minStopPips) * 0.5);
                var adjustedStop = tradeType == TradeType.Buy
                    ? NormalizePriceToSymbol(symbol, stop - (stopBufferPips * symbol.PipSize))
                    : NormalizePriceToSymbol(symbol, stop + (stopBufferPips * symbol.PipSize));
                if (!IsChartProtectionDistanceUsable(symbol, entry, adjustedStop))
                    continue;

                foreach (var rawTarget in targetCandidates)
                {
                    var adjustedTarget = tradeType == TradeType.Buy
                        ? NormalizePriceToSymbol(symbol, rawTarget - (GetChartProtectionBiasPips(symbol) * symbol.PipSize))
                        : NormalizePriceToSymbol(symbol, rawTarget + (GetChartProtectionBiasPips(symbol) * symbol.PipSize));
                    if (!IsChartProtectionDistanceUsable(symbol, entry, adjustedTarget))
                        continue;

                    var risk = Math.Abs(entry - adjustedStop);
                    var reward = Math.Abs(adjustedTarget - entry);
                    if (risk <= 0 || reward <= 0)
                        continue;

                    var rr = reward / risk;
                    if (rr < rrFloor)
                        continue;

                    string reason;
                    var action = tradeType == TradeType.Buy ? "BUY" : "SELL";
                    if (!TryValidateProtectionPrices(symbol, action, entry, adjustedStop, adjustedTarget, out reason))
                        continue;

                    var distanceScore = 1.0 / Math.Max(symbol.PipSize, Math.Abs(currentPrice - entry));
                    // Cap the RR reward in the score so the planner does not chase far 5-10R
                    // targets: a near target with RR 2-3 beats a distant one with RR 8.
                    var effectiveRr = Math.Min(rr, 3.0);
                    var score = (effectiveRr * 1000.0) + distanceScore;
                    if (score <= bestScore)
                        continue;

                    bestScore = score;
                    plan = new ChartTradePlan
                    {
                        IsValid = true,
                        EntryLabel = candidate.Label,
                        StructureTfLabel = GetChartTradeStructureTfLabel(profileRaw),
                        Entry = entry,
                        StopLoss = adjustedStop,
                        TakeProfit = adjustedTarget,
                        RewardRisk = rr
                    };
                }
            }

            LogSlowChartStep("BuildChartLimitPlanV2", started, string.Format(CultureInfo.InvariantCulture, "{0} {1} {2} valid={3} rr={4:F2}", symbolName, tradeType, GetChartTradeProfileRaw(profileRaw), plan.IsValid, plan.RewardRisk));
            return plan;
        }

        private ChartTradePlan BuildChartLimitPlanFromLegacy(Symbol symbol, string symbolName, TradeType tradeType, string profileRaw)
        {
            var plan = new ChartTradePlan
            {
                IsValid = false,
                EntryLabel = "legacy",
                StructureTfLabel = "Legacy"
            };
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName))
                return plan;

            var currentPrice = tradeType == TradeType.Buy ? symbol.Ask : symbol.Bid;
            if (currentPrice <= 0)
                return plan;

            var entry = tradeType == TradeType.Buy
                ? FindClosestChartLevel(symbolName, true, currentPrice, profileRaw)
                : FindClosestChartLevel(symbolName, false, currentPrice, profileRaw);
            if (!entry.HasValue || entry.Value <= 0)
                entry = BuildFallbackChartEntryPrice(symbol, tradeType, false, currentPrice);
            if (!entry.HasValue || entry.Value <= 0)
                return plan;

            var normalizedEntry = NormalizePriceToSymbol(symbol, entry.Value);
            var protection = BuildSharedChartProtectionPrices(symbol, symbolName, tradeType, normalizedEntry, Math.Max(1.0, ResolveMinStopPips(symbol)), profileRaw);
            if (protection == null)
                return plan;

            var sl = NormalizePriceToSymbol(symbol, protection.Item1);
            var tp = NormalizePriceToSymbol(symbol, protection.Item2);
            var risk = Math.Abs(normalizedEntry - sl);
            var reward = Math.Abs(tp - normalizedEntry);
            if (risk <= 0 || reward <= 0)
                return plan;

            string reason;
            var action = tradeType == TradeType.Buy ? "BUY" : "SELL";
            if (!TryValidateProtectionPrices(symbol, action, normalizedEntry, sl, tp, out reason))
                return plan;

            plan.IsValid = true;
            plan.Entry = normalizedEntry;
            plan.StopLoss = sl;
            plan.TakeProfit = tp;
            plan.RewardRisk = reward / risk;
            return plan;
        }

        private List<ChartLevelCandidate> CollectChartStructuralLevelCandidates(Symbol symbol, string symbolName, string profileRaw)
        {
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName))
                return new List<ChartLevelCandidate>();

            var cacheKey = string.Format(
                CultureInfo.InvariantCulture,
                "{0}|{1}|struct|{2}|{3}",
                symbolName.ToUpperInvariant(),
                GetChartTradeProfileRaw(profileRaw),
                Chart != null ? Chart.TimeFrame.ToString() : "",
                MinStopPips);
            return GetOrCreateTimedCacheValue(
                _chartStructuralLevelsCache,
                cacheKey,
                ChartStructureCacheTtl,
                () => CollectChartStructuralLevelCandidatesCore(symbol, symbolName, profileRaw));
        }

        private List<ChartLevelCandidate> CollectChartStructuralLevelCandidatesCore(Symbol symbol, string symbolName, string profileRaw)
        {
            var candidates = new List<ChartLevelCandidate>();
            var started = Stopwatch.StartNew();

            var tolerance = Math.Max(symbol.PipSize * 2.0, 0.0000001);
            try
            {
                foreach (var sourceTimeFrame in GetChartTradeStructureTimeFrames(profileRaw))
                {
                    var sourceBars = MarketData.GetBars(sourceTimeFrame, symbolName);
                    if (sourceBars == null || sourceBars.Count < 5)
                        continue;

                    int previousIndex;
                    if (TryGetPreviousCompletedPeriodBarIndex(sourceBars, sourceTimeFrame, out previousIndex))
                    {
                        AddChartLevelCandidate(candidates, sourceBars.HighPrices[previousIndex], tolerance, 2);
                        AddChartLevelCandidate(candidates, sourceBars.LowPrices[previousIndex], tolerance, 2);
                    }

                    var start = ResolveWorkingStartIndex(sourceBars, 2, 2, sourceTimeFrame);
                    var resistance = double.MinValue;
                    var support = double.MaxValue;
                    for (var i = start; i < sourceBars.Count - 2; i++)
                    {
                        resistance = Math.Max(resistance, sourceBars.HighPrices[i]);
                        support = Math.Min(support, sourceBars.LowPrices[i]);
                    }
                    if (resistance > double.MinValue)
                        AddChartLevelCandidate(candidates, resistance, tolerance, 1);
                    if (support < double.MaxValue)
                        AddChartLevelCandidate(candidates, support, tolerance, 1);

                    foreach (var swing in CollectConfirmedSwings(sourceBars, ResolveWorkingSwingLookbackBars(sourceBars, sourceTimeFrame)).TakeLast(10))
                        AddChartLevelCandidate(candidates, swing.Price, tolerance, 2);

                    var fvgLevels = new List<double>();
                    AddFvgLevelCandidates(fvgLevels, sourceBars, tolerance);
                    AddChartLevelCandidatesFromRaw(candidates, fvgLevels, tolerance, 1);

                    var obLevels = new List<double>();
                    AddOrderBlockLevelCandidates(obLevels, sourceBars, tolerance);
                    AddChartLevelCandidatesFromRaw(candidates, obLevels, tolerance, 1);

                    foreach (var zone in DetectScoredPriceZones(sourceBars, symbol, ResolveWorkingLookbackBars(sourceBars, sourceTimeFrame), sourceTimeFrame))
                    {
                        var zoneWeight = Math.Max(1, Math.Min(4, zone.Score / 4));
                        AddChartLevelCandidate(candidates, (zone.Low + zone.High) * 0.5, tolerance, zoneWeight);
                        AddChartLevelCandidate(candidates, zone.Low, tolerance, 1);
                        AddChartLevelCandidate(candidates, zone.High, tolerance, 1);
                    }
                }
            }
            catch (Exception ex)
            {
                SafePrint("[ChartTrade] Structural levels failed for {0}: {1}", symbolName, ex.Message);
            }

            LogSlowChartStep("CollectChartStructuralLevelCandidates", started, string.Format(CultureInfo.InvariantCulture, "{0} {1} -> {2}", symbolName, GetChartTradeProfileRaw(profileRaw), candidates.Count));
            return candidates;
        }

        private List<double> CollectChartStructuralLevels(Symbol symbol, string symbolName, string profileRaw)
        {
            return CollectChartStructuralLevelCandidates(symbol, symbolName, profileRaw)
                .Select(x => x.Price)
                .Distinct()
                .ToList();
        }

        private List<ChartLevelCandidate> GetRankedChartStructuralLevels(Symbol symbol, string symbolName, bool wantBelowReference, double referencePrice, string profileRaw = null)
        {
            var chartProfile = string.IsNullOrWhiteSpace(profileRaw) ? GetChartTradeProfileRaw(ReadChartTradeTypeComboSelection()) : GetChartTradeProfileRaw(profileRaw);
            return CollectChartStructuralLevelCandidates(symbol, symbolName, chartProfile)
                .Where(x => x.Price > 0)
                .Where(x => wantBelowReference ? x.Price < referencePrice : x.Price > referencePrice)
                .OrderByDescending(x => x.Weight)
                .ThenBy(x => Math.Abs(x.Price - referencePrice))
                .ToList();
        }

        private double? FindClosestChartLevel(string symbolName, bool wantBelowReference, double referencePrice, string profileRaw = null)
        {
            if (referencePrice <= 0) return null;

            var symbol = ResolveLoadedSymbol(symbolName);
            var candidates = GetRankedChartStructuralLevels(symbol, symbolName, wantBelowReference, referencePrice, profileRaw);

            if (candidates.Count == 0) return null;
            return candidates.First().Price;
        }

        private double? BuildFallbackChartEntryPrice(Symbol symbol, TradeType tradeType, bool isStopOrder, double currentPrice)
        {
            if (symbol == null || currentPrice <= 0 || symbol.PipSize <= 0) return null;

            var distancePips = Math.Max(1.0, ResolveMinStopPips(symbol));
            var distance = distancePips * symbol.PipSize;
            double entryPrice;

            if (isStopOrder)
            {
                entryPrice = tradeType == TradeType.Buy
                    ? currentPrice + distance
                    : currentPrice - distance;
            }
            else
            {
                entryPrice = tradeType == TradeType.Buy
                    ? currentPrice - distance
                    : currentPrice + distance;
            }

            return NormalizePriceToSymbol(symbol, entryPrice);
        }

        private double? FindClosestUsableChartLevel(Symbol symbol, string symbolName, bool wantBelowReference, double referencePrice, string profileRaw = null)
        {
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || referencePrice <= 0) return null;

            var filtered = GetRankedChartStructuralLevels(symbol, symbolName, wantBelowReference, referencePrice, profileRaw);

            // SL/TP must hug the market: pick the NEAREST usable level (weight only breaks ties).
            // Weight-first ordering is fine for entry selection but makes protections land on far
            // 1D/4H levels instead of the closest swing/FVG.
            foreach (var candidate in filtered
                .OrderBy(x => Math.Abs(x.Price - referencePrice))
                .ThenByDescending(x => x.Weight))
            {
                if (IsChartProtectionDistanceUsable(symbol, referencePrice, candidate.Price))
                    return candidate.Price;
            }

            return null;
        }

        private Tuple<double, double> BuildFallbackChartProtectionPrices(Symbol symbol, TradeType tradeType, double executionPrice, double? overrideDistancePips = null)
        {
            if (symbol == null || executionPrice <= 0 || symbol.PipSize <= 0) return null;

            var distancePips = Math.Max(1.0, overrideDistancePips ?? ResolveMinStopPips(symbol));
            var distance = distancePips * symbol.PipSize;
            var sl = tradeType == TradeType.Buy
                ? executionPrice - distance
                : executionPrice + distance;
            var tp = tradeType == TradeType.Buy
                ? executionPrice + distance
                : executionPrice - distance;

            return Tuple.Create(
                NormalizePriceToSymbol(symbol, sl),
                NormalizePriceToSymbol(symbol, tp));
        }

        // Fallback SL distance (pips) when no structural level is usable: at least the minimum
        // stop, scaled to current volatility instead of a fixed wide 100-pip floor (which made
        // scalp entries land far from price). Capped at 80 pips so it never becomes a swing-size
        // stop.
        private double ResolveChartFallbackStopPips(Symbol symbol)
        {
            var minStopPips = Math.Max(1.0, ResolveMinStopPips(symbol));
            var atrPips = ResolveAtrPips(symbol, null, 14);
            var atrBased = atrPips > 0 ? Math.Min(80.0, atrPips * 1.5) : minStopPips;
            return Math.Max(minStopPips, atrBased);
        }

        private bool IsChartProtectionDistanceUsable(Symbol symbol, double referencePrice, double levelPrice)
        {
            if (symbol == null || referencePrice <= 0 || levelPrice <= 0 || symbol.PipSize <= 0) return false;
            var distancePips = Math.Abs(referencePrice - levelPrice) / symbol.PipSize;
            if (double.IsNaN(distancePips) || double.IsInfinity(distancePips)) return false;
            if (distancePips < Math.Max(1.0, ResolveMinStopPips(symbol))) return false;
            return true;
        }

        private double GetChartProtectionBiasPips(Symbol symbol = null)
        {
            return Math.Max(1.0, Math.Min(10.0, Math.Max(1.0, ResolveMinStopPips(symbol ?? Symbol)) * 0.25));
        }

        private Tuple<double, double> ApplyChartProtectionBiasAndRisk(
            Symbol symbol,
            TradeType tradeType,
            double entryPrice,
            double slPrice,
            double tpPrice)
        {
            if (symbol == null || entryPrice <= 0 || slPrice <= 0 || tpPrice <= 0 || symbol.PipSize <= 0)
                return null;

            var biasDistance = GetChartProtectionBiasPips() * symbol.PipSize;
            if (tradeType == TradeType.Buy)
            {
                slPrice -= biasDistance;
                tpPrice -= biasDistance;
            }
            else
            {
                slPrice += biasDistance;
                tpPrice += biasDistance;
            }

            slPrice = NormalizePriceToSymbol(symbol, slPrice);
            tpPrice = NormalizePriceToSymbol(symbol, tpPrice);

            var slDistance = Math.Abs(entryPrice - slPrice);
            if (slDistance <= 0) return null;

            var minRewardRisk = Math.Max(1.5, 1.5);
            var minTpDistance = slDistance * minRewardRisk;
            var currentTpDistance = Math.Abs(tpPrice - entryPrice);
            if (currentTpDistance < minTpDistance)
            {
                tpPrice = tradeType == TradeType.Buy
                    ? entryPrice + minTpDistance
                    : entryPrice - minTpDistance;
                tpPrice = NormalizePriceToSymbol(symbol, tpPrice);
            }

            if (!IsChartProtectionDistanceUsable(symbol, entryPrice, slPrice)) return null;
            if (!IsChartProtectionDistanceUsable(symbol, entryPrice, tpPrice)) return null;

            string reason;
            var action = tradeType == TradeType.Buy ? "BUY" : "SELL";
            if (!TryValidateProtectionPrices(symbol, action, entryPrice, slPrice, tpPrice, out reason))
                return null;

            return Tuple.Create(
                NormalizePriceToSymbol(symbol, slPrice),
                NormalizePriceToSymbol(symbol, tpPrice));
        }

        private Tuple<double, double> BuildSharedChartProtectionPrices(Symbol symbol, string symbolName, TradeType tradeType, double entryPrice, double fallbackDistancePips, string profileRaw = null)
        {
            var started = Stopwatch.StartNew();
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || entryPrice <= 0 || symbol.PipSize <= 0)
                return null;

            var chartProfile = string.IsNullOrWhiteSpace(profileRaw) ? GetChartTradeProfileRaw(ReadChartTradeTypeComboSelection()) : GetChartTradeProfileRaw(profileRaw);
            double? rawSl = tradeType == TradeType.Buy
                ? FindClosestUsableChartLevel(symbol, symbolName, true, entryPrice, chartProfile)
                : FindClosestUsableChartLevel(symbol, symbolName, false, entryPrice, chartProfile);
            double? rawTp = tradeType == TradeType.Buy
                ? FindClosestUsableChartLevel(symbol, symbolName, false, entryPrice, chartProfile)
                : FindClosestUsableChartLevel(symbol, symbolName, true, entryPrice, chartProfile);

            var fallback = BuildFallbackChartProtectionPrices(symbol, tradeType, entryPrice, fallbackDistancePips);
            if (fallback == null) return null;

            if (!rawSl.HasValue) rawSl = fallback.Item1;
            if (!rawTp.HasValue) rawTp = fallback.Item2;

            var adjusted = ApplyChartProtectionBiasAndRisk(symbol, tradeType, entryPrice, rawSl.Value, rawTp.Value);
            if (adjusted != null)
            {
                LogSlowChartStep("BuildSharedChartProtectionPrices", started, string.Format(CultureInfo.InvariantCulture, "{0} {1} {2} direct", symbolName, tradeType, chartProfile));
                return adjusted;
            }

            var fallbackAdjusted = ApplyChartProtectionBiasAndRisk(symbol, tradeType, entryPrice, fallback.Item1, fallback.Item2);
            LogSlowChartStep("BuildSharedChartProtectionPrices", started, string.Format(CultureInfo.InvariantCulture, "{0} {1} {2} fallback", symbolName, tradeType, chartProfile));
            return fallbackAdjusted;
        }

        private double ResolveChartFinalRiskMoney(string profileRaw = null)
        {
            var balance = Account != null ? Math.Max(0, Account.Balance) : 0;
            var effectiveMaxRiskPercent = GetEffectiveManualMaxRiskPercent();
            var multiplier = GetTradeProfileRiskMultiplier(
                string.IsNullOrWhiteSpace(profileRaw) ? GetChartTradeProfileRaw(ReadChartTradeTypeComboSelection()) : profileRaw,
                "");
            return effectiveMaxRiskPercent > 0
                ? Math.Max(0, balance * (effectiveMaxRiskPercent / 100.0) * Math.Max(0.0, multiplier))
                : 0;
        }

        private void ExecuteChartQuickMarketOrder(TradeType tradeType)
        {
            var started = Stopwatch.StartNew();
            try
            {
                var symbolName = GetEffectiveChartEntrySymbolSelection();
                var selectedTradeProfile = GetChartTradeProfileRaw(ReadChartTradeTypeComboSelection());
                var structureTfLabel = GetChartTradeStructureTfLabel(selectedTradeProfile);
                if (string.IsNullOrWhiteSpace(symbolName))
                {
                    SafeLog("ERROR", "[ChartTrade] {0} MARKET rejected: no_symbol_selected (chart_symbol={1}; profile={2}; tf={3})", tradeType == TradeType.Buy ? "BUY" : "SELL", Chart != null ? Chart.SymbolName : "", selectedTradeProfile, structureTfLabel);
                    RefreshDebugPanelLite();
                    return;
                }

                var symbol = ResolveLoadedSymbol(symbolName);
                if (symbol == null)
                {
                    SafeLog("ERROR", "[ChartTrade] {0} MARKET {1} rejected: symbol_not_loaded (profile={2}; tf={3}); fix=ensure_symbol_has_live_quotes", tradeType == TradeType.Buy ? "BUY" : "SELL", symbolName, selectedTradeProfile, structureTfLabel);
                    RefreshDebugPanelLite();
                    return;
                }

                var action = tradeType == TradeType.Buy ? "BUY" : "SELL";
                Print(string.Format(CultureInfo.InvariantCulture, "[Click] {0} MARKET clicked symbol='{1}' loaded={2} profile='{3}' tf='{4}'", action, symbolName, symbol != null ? "yes" : "no", selectedTradeProfile, structureTfLabel));
                var tradableRejectReason = DetectSymbolTradeAvailabilityReason(symbol);
                if (!string.IsNullOrWhiteSpace(tradableRejectReason))
                {
                    SafeLog("ERROR", "[ChartTrade] {0} MARKET {1} rejected: {2}", action, symbolName, DescribeTradeAvailabilityReason(tradableRejectReason, symbolName));
                    RefreshDebugPanelLite();
                    return;
                }
                var executionPrice = tradeType == TradeType.Buy ? symbol.Ask : symbol.Bid;
                double? sl = null;
                double? tp = null;

                if (executionPrice <= 0)
                {
                    SafeLog("ERROR", "[ChartTrade] {0} MARKET {1} rejected: invalid_execution_price (bid={2:F5}; ask={3:F5})", action, symbolName, symbol.Bid, symbol.Ask);
                    RefreshDebugPanelLite();
                    return;
                }

            var marketProtection = BuildSharedChartProtectionPrices(symbol, symbolName, tradeType, executionPrice, ResolveChartFallbackStopPips(symbol), selectedTradeProfile);
                if (marketProtection != null)
                {
                    sl = marketProtection.Item1;
                    tp = marketProtection.Item2;
                }
                LogPerfStep("MarketOrder.ProtectionReady", started.ElapsedMilliseconds, string.Format(CultureInfo.InvariantCulture, "{0} {1}", symbolName, action), 25);

                if (!sl.HasValue || !tp.HasValue)
                {
                    SafeLog("ERROR", "[ChartTrade] {0} MARKET {1} rejected: no_sl_tp_levels (market={2:F5}; profile={3}; tf={4}); fix=check_structure_levels_for_this_symbol", action, symbolName, executionPrice, selectedTradeProfile, structureTfLabel);
                    RefreshDebugPanelLite();
                    return;
                }

                string protectionReason;
                if (!TryValidateProtectionPrices(symbol, action, executionPrice, sl.Value, tp.Value, out protectionReason))
                {
                    SafeLog("ERROR", "[ChartTrade] {0} MARKET {1} rejected: {2}", action, symbolName, protectionReason);
                    RefreshDebugPanelLite();
                    return;
                }

                var finalRiskMoney = ResolveChartFinalRiskMoney(selectedTradeProfile);
                var plan = BuildChartLimitPlanV2(symbol, symbolName, tradeType, selectedTradeProfile);
                if (!plan.IsValid)
                    plan = BuildChartLimitPlanFromLegacy(symbol, symbolName, tradeType, selectedTradeProfile);

                var pendingEntries = new List<double>();
                if (plan.IsValid)
                {
                    var orderCountOverride = ResolveChartOrderCount();
                    var ladderEntries = BuildChartSplitLimitEntries(symbol, symbolName, tradeType, executionPrice, NormalizePriceToSymbol(symbol, plan.Entry), NormalizePriceToSymbol(symbol, sl.Value), orderCountOverride);
                    pendingEntries = ladderEntries
                        .Where(v => Math.Abs(v - executionPrice) >= Math.Max(symbol.PipSize * 2.0, 0.0000001))
                        .ToList();
                    // Fixed count: the market order is the first leg, so at most N-1 limits.
                    if (orderCountOverride > 0)
                        pendingEntries = pendingEntries.Take(Math.Max(0, orderCountOverride - 1)).ToList();
                }

                var weights = BuildChartSplitRiskWeights(1 + pendingEntries.Count, true);
                var marketRiskMoney = Math.Max(0, finalRiskMoney * weights[0]);
                var volumeUnits = ResolveChartTradeVolumeForRisk(symbol, tradeType, executionPrice, sl.Value, marketRiskMoney, symbolName);
                LogPerfStep("MarketOrder.VolumeReady", started.ElapsedMilliseconds, string.Format(CultureInfo.InvariantCulture, "{0} {1} risk={2:F2}", symbolName, action, marketRiskMoney), 25);
                if (volumeUnits < symbol.VolumeInUnitsMin)
                {
                    var minRisk = EstimateRiskAmount(symbol, tradeType, executionPrice, sl.Value, symbol.VolumeInUnitsMin);
                    SafeLog("ERROR", "[ChartTrade] {0} MARKET {1} rejected: volume_too_small {2:F2}; min_vol={3:F2}; min_vol_risk={4:F2}; allowed={5:F2}", action, symbolName, volumeUnits, symbol.VolumeInUnitsMin, minRisk, marketRiskMoney);
                    RefreshDebugPanelLite();
                    return;
                }

                double approvedVolumeUnits;
                double approvedRiskMoney;
                double approvedMarginEstimate;
                double approvedMarginBudget;
                double approvedSl;
                double approvedTp;
                string gateRejectReason;
                if (!TryPassSharedCreationGate(
                    symbol,
                    action,
                    "market",
                    0,
                    executionPrice,
                    sl.Value,
                    tp.Value,
                    volumeUnits,
                    marketRiskMoney,
                    marketRiskMoney,
                    true,
                    out approvedSl,
                    out approvedTp,
                    out approvedVolumeUnits,
                    out approvedRiskMoney,
                    out approvedMarginEstimate,
                    out approvedMarginBudget,
                    out gateRejectReason))
                {
                    SafeLog("ERROR", "[ChartTrade] {0} MARKET {1} rejected: {2} | ctx={3}", action, symbolName, gateRejectReason, BuildSubmitContext(symbol, action, "market", 0, executionPrice, sl.Value, tp.Value, volumeUnits, marketRiskMoney, marketRiskMoney));
                    RefreshDebugPanelLite();
                    return;
                }
                if (approvedVolumeUnits < volumeUnits)
                    volumeUnits = approvedVolumeUnits;
                LogPerfStep("MarketOrder.GatePassed", started.ElapsedMilliseconds, string.Format(CultureInfo.InvariantCulture, "{0} {1} vol={2:F2}", symbolName, action, volumeUnits), 25);

                sl = approvedSl;
                tp = approvedTp;
                var sharedSl = NormalizePriceToSymbol(symbol, sl.Value);
                var sharedTp = NormalizePriceToSymbol(symbol, tp.Value);

                var slPips = CTraderExecutionEngine.ResolveDistancePips(symbol, executionPrice, sharedSl).GetValueOrDefault();
                var tpPips = CTraderExecutionEngine.ResolveDistancePips(symbol, executionPrice, sharedTp).GetValueOrDefault();
                var label = BuildChartTradeLabel(action, "Market", symbolName);
                var comment = label;
                var requestedLots = symbol.VolumeInUnitsToQuantity(volumeUnits);
                LogStructuredTradeEvent("chart", "SUBMIT", symbolName, action, "MARKET", requestedLots, executionPrice, sharedSl, sharedTp, "", structureTfLabel);
                var result = ExecuteMarketOrder(tradeType, symbol.Name, volumeUnits, label, slPips, tpPips, comment);
                LogPerfStep("MarketOrder.Submitted", started.ElapsedMilliseconds, string.Format(CultureInfo.InvariantCulture, "{0} {1}", symbolName, action), 25);

                if (result == null || !result.IsSuccessful)
                {
                    var brokerError = result != null ? Convert.ToString(result.Error, CultureInfo.InvariantCulture) : "null_result";
                    LogStructuredTradeEvent("chart", "FAILED", symbolName, action, "MARKET", requestedLots, executionPrice, sharedSl, sharedTp, "", brokerError);
                    SafeLog("ERROR", "[ChartTrade] {0} MARKET {1} failed: {2}", action, symbolName, brokerError);
                    RefreshDebugPanelLite();
                    return;
                }

                if (result.Position != null)
                {
                    var finalSl = sharedSl;
                    var finalTp = sharedTp;
                    ReanchorProtectionToFilledEntry(symbol, action, executionPrice, result.Position.EntryPrice, ref finalSl, ref finalTp);
                    string protectionError;
                    if (!TryEnsureStrategyPositionProtection(result.Position, symbol, action, finalSl, finalTp, out protectionError))
                    {
                        var closeResult = ClosePosition(result.Position);
                        SafeLog(
                            "ERROR",
                            "[ChartTrade] {0} MARKET {1} ({2}) closed after protection failure: {3}; close={4}",
                            action,
                            symbolName,
                            structureTfLabel,
                            protectionError,
                            closeResult != null && closeResult.IsSuccessful ? "ok" : "failed");
                        RefreshDebugPanelLite();
                        return;
                    }
                    TryApplySelectedExitModeForPosition(result.Position);
                }

                LogStructuredTradeEvent("chart", "SUCCEEDED", symbolName, action, "MARKET", requestedLots, result.Position != null ? result.Position.EntryPrice : executionPrice, sharedSl, sharedTp, result.Position != null ? result.Position.Id.ToString(CultureInfo.InvariantCulture) : "", structureTfLabel);

                // Same budget-aware leg selection as the limit ladder: drop pending legs whose
                // risk slice cannot cover min-volume risk and re-normalize the kept slices.
                var pendingWeights = weights.Skip(1).Take(pendingEntries.Count).ToArray();
                var affordablePending = new List<double>();
                var affordablePendingWeights = new List<double>();
                TryResolveAffordableSplitLegs(symbol, tradeType, pendingEntries, pendingWeights, sharedSl, finalRiskMoney, affordablePending, affordablePendingWeights);

                var placedPendingCount = 0;
                for (var i = 0; i < affordablePending.Count && i < affordablePendingWeights.Count; i++)
                {
                    var entry = affordablePending[i];
                    var sliceRiskMoney = finalRiskMoney > 0 ? Math.Max(0, finalRiskMoney * affordablePendingWeights[i]) : 0;
                    var pendingVolumeUnits = ResolveChartTradeVolumeForRisk(symbol, tradeType, entry, sharedSl, sliceRiskMoney, symbolName);
                    if (pendingVolumeUnits < symbol.VolumeInUnitsMin)
                        continue;

                    double approvedPendingVolumeUnits;
                    double approvedPendingRiskMoney;
                    double approvedPendingMarginEstimate;
                    double approvedPendingMarginBudget;
                    double approvedPendingSl;
                    double approvedPendingTp;
                    string pendingGateRejectReason;
                    if (!TryPassSharedCreationGate(
                        symbol,
                        action,
                        "limit",
                        entry,
                        executionPrice,
                        sharedSl,
                        sharedTp,
                        pendingVolumeUnits,
                        sliceRiskMoney,
                        sliceRiskMoney,
                        true,
                        out approvedPendingSl,
                        out approvedPendingTp,
                        out approvedPendingVolumeUnits,
                        out approvedPendingRiskMoney,
                        out approvedPendingMarginEstimate,
                        out approvedPendingMarginBudget,
                        out pendingGateRejectReason))
                        continue;

                    if (approvedPendingVolumeUnits < symbol.VolumeInUnitsMin)
                        continue;

                    var limitSlPips = CTraderExecutionEngine.ResolveDistancePips(symbol, entry, sharedSl).GetValueOrDefault();
                    var limitTpPips = CTraderExecutionEngine.ResolveDistancePips(symbol, entry, sharedTp).GetValueOrDefault();
                    var limitLabel = BuildChartTradeLabel(action, "LIMIT", symbolName);
                    var limitComment = BuildChartPendingComment(tradeType, false, symbolName) + ":m" + (i + 2).ToString(CultureInfo.InvariantCulture);
                    var limitLots = symbol.VolumeInUnitsToQuantity(approvedPendingVolumeUnits);
                    LogStructuredTradeEvent("chart", "SUBMIT", symbolName, action, "LIMIT", limitLots, entry, sharedSl, sharedTp, "", structureTfLabel + ":m" + (i + 2).ToString(CultureInfo.InvariantCulture));
                    var pendingResult = PlaceLimitOrder(
                        tradeType,
                        symbol.Name,
                        approvedPendingVolumeUnits,
                        entry,
                        limitLabel,
                        (double?)limitSlPips,
                        (double?)limitTpPips,
                        (ProtectionType?)null,
                        null,
                        limitComment
                    );

                    if (pendingResult == null || !pendingResult.IsSuccessful)
                        continue;

                    if (pendingResult.PendingOrder != null)
                    {
                        string modifyError;
                        if (!TryApplyPendingOrderProtection(pendingResult.PendingOrder, symbol, action, sharedSl, sharedTp, out modifyError))
                            continue;
                    }

                    placedPendingCount++;
                }

                SafeLog("INFO", "[ChartTrade] {0} MARKET {1} [{2}] sent with SL={3:F5} TP={4:F5}; sl_dist={5:F1}pips tp_dist={6:F1}pips; pending_legs={7}", action, symbolName, structureTfLabel, sharedSl, sharedTp, Math.Round(Math.Abs(executionPrice - sharedSl) / symbol.PipSize, 1), Math.Round(Math.Abs(sharedTp - executionPrice) / symbol.PipSize, 1), placedPendingCount);
                RebuildChartButtonPanel();
                RefreshDebugPanelLite();
            }
            catch (Exception ex)
            {
                SafeLog("ERROR", "[ChartTrade] MARKET failed: {0}", ex.Message);
                RefreshDebugPanelLite();
            }
            finally
            {
                LogSlowChartStep("ExecuteChartQuickMarketOrder", started, tradeType.ToString());
            }
        }

        private void ExecuteChartQuickPendingOrder(TradeType tradeType, bool isStopOrder, bool splitLimitOrder)
        {
            if (!isStopOrder && splitLimitOrder)
            {
                ExecuteChartQuickSplitLimitOrder(tradeType);
                return;
            }

            if (!isStopOrder)
            {
                ExecuteChartQuickPendingOrderV2(tradeType);
                return;
            }

            var started = Stopwatch.StartNew();
            try
            {
                var symbolName = GetEffectiveChartEntrySymbolSelection();
                var selectedTradeProfile = GetChartTradeProfileRaw(ReadChartTradeTypeComboSelection());
                var structureTfLabel = GetChartTradeStructureTfLabel(selectedTradeProfile);
                if (string.IsNullOrWhiteSpace(symbolName))
                {
                    SafeLog("ERROR", "[ChartTrade] {0} rejected: no_symbol_selected (chart_symbol={1}; profile={2}; tf={3})", tradeType == TradeType.Buy ? (isStopOrder ? "BUY STOP" : "BUY LIMIT") : (isStopOrder ? "SELL STOP" : "SELL LIMIT"), Chart != null ? Chart.SymbolName : "", selectedTradeProfile, structureTfLabel);
                    RefreshDebugPanelLite();
                    return;
                }

                var symbol = ResolveLoadedSymbol(symbolName);
                if (symbol == null)
                {
                    SafeLog("ERROR", "[ChartTrade] {0} {1} rejected: symbol_not_loaded (profile={2}); fix=ensure_symbol_has_live_quotes", tradeType == TradeType.Buy ? (isStopOrder ? "BUY STOP" : "BUY LIMIT") : (isStopOrder ? "SELL STOP" : "SELL LIMIT"), symbolName, selectedTradeProfile);
                    RefreshDebugPanelLite();
                    return;
                }

                var action = tradeType == TradeType.Buy ? "BUY" : "SELL";
                var orderTypeLabel = isStopOrder ? "STOP" : "LIMIT";
                Print(string.Format(CultureInfo.InvariantCulture, "[Click] {0} {1} clicked symbol='{2}' loaded={3} profile='{4}'", action, orderTypeLabel, symbolName, symbol != null ? "yes" : "no", selectedTradeProfile));
                var tradableRejectReason = DetectSymbolTradeAvailabilityReason(symbol);
                if (!string.IsNullOrWhiteSpace(tradableRejectReason))
                {
                    SafeLog("ERROR", "[ChartTrade] {0} {1} {2} rejected: {3}", action, orderTypeLabel, symbolName, DescribeTradeAvailabilityReason(tradableRejectReason, symbolName));
                    RefreshDebugPanelLite();
                    return;
                }
                var currentPrice = tradeType == TradeType.Buy ? symbol.Ask : symbol.Bid;
                if (currentPrice <= 0)
                {
                    SafeLog("ERROR", "[ChartTrade] {0} {1} {2} rejected: invalid_reference_price (bid={3:F5}; ask={4:F5})", action, orderTypeLabel, symbolName, symbol.Bid, symbol.Ask);
                    RefreshDebugPanelLite();
                    return;
                }

                var entry = isStopOrder
                    ? (tradeType == TradeType.Buy
                        ? FindClosestChartLevel(symbolName, false, currentPrice, selectedTradeProfile)
                        : FindClosestChartLevel(symbolName, true, currentPrice, selectedTradeProfile))
                    : (tradeType == TradeType.Buy
                        ? FindClosestChartLevel(symbolName, true, currentPrice, selectedTradeProfile)
                        : FindClosestChartLevel(symbolName, false, currentPrice, selectedTradeProfile));
                if (!entry.HasValue || entry.Value <= 0)
                {
                    entry = BuildFallbackChartEntryPrice(symbol, tradeType, isStopOrder, currentPrice);
                    if (!entry.HasValue || entry.Value <= 0)
                    {
                        var directionHint = isStopOrder
                            ? (tradeType == TradeType.Buy ? "above current price" : "below current price")
                            : (tradeType == TradeType.Buy ? "below current price" : "above current price");
                        SafeLog("ERROR", "[ChartTrade] {0} {1} {2} rejected: no structural entry level from {3} found {4}, and fallback entry from MinStopPips was unavailable", action, orderTypeLabel, symbolName, structureTfLabel, directionHint);
                        RefreshDebugPanelLite();
                        return;
                    }
                    SafeLog("INFO", "[ChartTrade] {0} {1} {2} using fallback entry: no structural {3} level found, entry={4:F5}", action, orderTypeLabel, symbolName, structureTfLabel, entry.Value);
                }

                var normalizedEntry = NormalizePriceToSymbol(symbol, entry.Value);
                double? sl = null;
                double? tp = null;
                var pendingProtection = BuildSharedChartProtectionPrices(symbol, symbolName, tradeType, normalizedEntry, Math.Max(1.0, MinStopPips), selectedTradeProfile);
                if (pendingProtection != null)
                {
                    sl = pendingProtection.Item1;
                    tp = pendingProtection.Item2;
                }
                LogPerfStep("PendingOrder.ProtectionReady", started.ElapsedMilliseconds, string.Format(CultureInfo.InvariantCulture, "{0} {1} {2}", symbolName, action, orderTypeLabel), 25);

                if (!sl.HasValue || !tp.HasValue)
                {
                    SafeLog("ERROR", "[ChartTrade] {0} {1} {2} rejected: no_sl_tp_levels", action, orderTypeLabel, symbolName);
                    RefreshDebugPanelLite();
                    return;
                }

                var finalRiskMoney = ResolveChartFinalRiskMoney(selectedTradeProfile);
                var volumeUnits = ResolveChartTradeVolumeForRisk(symbol, tradeType, normalizedEntry, sl.Value, finalRiskMoney, symbolName);
                LogPerfStep("PendingOrder.VolumeReady", started.ElapsedMilliseconds, string.Format(CultureInfo.InvariantCulture, "{0} {1} {2} risk={3:F2}", symbolName, action, orderTypeLabel, finalRiskMoney), 25);
                if (volumeUnits < symbol.VolumeInUnitsMin)
                {
                    SafeLog("ERROR", "[ChartTrade] {0} {1} {2} rejected: volume_too_small {3}", action, orderTypeLabel, symbolName, volumeUnits);
                    RefreshDebugPanelLite();
                    return;
                }

                double approvedVolumeUnits;
                double approvedRiskMoney;
                double approvedMarginEstimate;
                double approvedMarginBudget;
                double approvedSl;
                double approvedTp;
                string gateRejectReason;
                if (!TryPassSharedCreationGate(
                    symbol,
                    action,
                    isStopOrder ? "stop" : "limit",
                    normalizedEntry,
                    currentPrice,
                    sl.Value,
                    tp.Value,
                    volumeUnits,
                    finalRiskMoney,
                    finalRiskMoney,
                    true,
                    out approvedSl,
                    out approvedTp,
                    out approvedVolumeUnits,
                    out approvedRiskMoney,
                    out approvedMarginEstimate,
                    out approvedMarginBudget,
                    out gateRejectReason))
                {
                    SafeLog("ERROR", "[ChartTrade] {0} {1} {2} rejected: {3}", action, orderTypeLabel, symbolName, gateRejectReason);
                    RefreshDebugPanelLite();
                    return;
                }
                if (approvedVolumeUnits < volumeUnits)
                {
                    SafeLog(
                        "INFO",
                        "[ChartTrade] {0} {1} {2} volume reduced by shared gate: {3:F2} -> {4:F2} units (risk {5:F2}/{6:F2})",
                        action,
                        orderTypeLabel,
                        symbolName,
                        volumeUnits,
                        approvedVolumeUnits,
                        approvedRiskMoney,
                        finalRiskMoney
                    );
                    volumeUnits = approvedVolumeUnits;
                }
                LogPerfStep("PendingOrder.GatePassed", started.ElapsedMilliseconds, string.Format(CultureInfo.InvariantCulture, "{0} {1} {2} vol={3:F2}", symbolName, action, orderTypeLabel, volumeUnits), 25);

                sl = approvedSl;
                tp = approvedTp;

                var slPips = CTraderExecutionEngine.ResolveDistancePips(symbol, normalizedEntry, sl.Value).GetValueOrDefault();
                var tpPips = CTraderExecutionEngine.ResolveDistancePips(symbol, normalizedEntry, tp.Value).GetValueOrDefault();
                var label = BuildChartTradeLabel(action, orderTypeLabel, symbolName);
                var comment = BuildChartPendingComment(tradeType, isStopOrder, symbolName);
                var requestedLots = symbol.VolumeInUnitsToQuantity(volumeUnits);
                LogStructuredTradeEvent("chart", "SUBMIT", symbolName, action, orderTypeLabel, requestedLots, normalizedEntry, sl.Value, tp.Value, "", structureTfLabel);
                TradeResult result;
                if (isStopOrder)
                {
                    result = PlaceStopOrder(
                        tradeType,
                        symbol.Name,
                        volumeUnits,
                        normalizedEntry,
                        label,
                        (double?)slPips,
                        (double?)tpPips,
                        (ProtectionType?)null,
                        null,
                        comment
                    );
                }
                else
                {
                    result = PlaceLimitOrder(
                        tradeType,
                        symbol.Name,
                        volumeUnits,
                        normalizedEntry,
                        label,
                        (double?)slPips,
                        (double?)tpPips,
                        (ProtectionType?)null,
                        null,
                        comment
                    );
                }
                LogPerfStep("PendingOrder.Submitted", started.ElapsedMilliseconds, string.Format(CultureInfo.InvariantCulture, "{0} {1} {2}", symbolName, action, orderTypeLabel), 25);

                if (result == null || !result.IsSuccessful)
                {
                    var errorText = result != null ? Convert.ToString(result.Error, CultureInfo.InvariantCulture) : "unknown_error";
                    LogStructuredTradeEvent("chart", "FAILED", symbolName, action, orderTypeLabel, requestedLots, normalizedEntry, sl.Value, tp.Value, "", errorText);
                    SafeLog("ERROR", "[ChartTrade] {0} {1} {2} failed: {3}", action, orderTypeLabel, symbolName, errorText);
                    RefreshDebugPanelLite();
                    return;
                }

                if (result.PendingOrder != null)
                {
                    string modifyError;
                    if (!TryApplyPendingOrderProtection(result.PendingOrder, symbol, action, sl.Value, tp.Value, out modifyError))
                    {
                        SafeLog("ERROR", "[ChartTrade] {0} {1} {2} placed but SL/TP apply failed: {3}", action, orderTypeLabel, symbolName, modifyError);
                        RefreshDebugPanelLite();
                        return;
                    }
                }

                LogStructuredTradeEvent("chart", "SUCCEEDED", symbolName, action, orderTypeLabel, requestedLots, normalizedEntry, sl.Value, tp.Value, result.PendingOrder != null ? result.PendingOrder.Id.ToString(CultureInfo.InvariantCulture) : "", structureTfLabel);
                SafeLog("INFO", "[ChartTrade] {0} {1} {2} [{3}] placed E={4:F5} SL={5:F5} TP={6:F5}", action, orderTypeLabel, symbolName, structureTfLabel, normalizedEntry, sl.Value, tp.Value);
                RebuildChartButtonPanel();
                RefreshDebugPanelLite();
            }
            catch (Exception ex)
            {
                SafeLog("ERROR", "[ChartTrade] Pending order failed: {0}", ex.Message);
                RefreshDebugPanelLite();
            }
            finally
            {
                LogSlowChartStep("ExecuteChartQuickPendingOrder", started, string.Format(CultureInfo.InvariantCulture, "{0} stop={1}", tradeType, isStopOrder));
            }
        }

        private List<double> CollectChartSplitEntryLevels(Symbol symbol, string symbolName, TradeType tradeType, double baseEntry, double stopLoss)
        {
            var candidates = new List<double>();
            if (symbol == null || string.IsNullOrWhiteSpace(symbolName) || baseEntry <= 0 || stopLoss <= 0)
                return candidates;

            var tolerance = Math.Max(symbol.PipSize * 2.0, 0.0000001);
            try
            {
                var sourceTimeFrame = Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
                var sourceBars = MarketData.GetBars(sourceTimeFrame, symbolName);
                if (sourceBars == null || sourceBars.Count < 5)
                    return candidates;

                foreach (var swing in CollectConfirmedSwings(sourceBars, ResolveWorkingSwingLookbackBars(sourceBars, sourceTimeFrame)).TakeLast(16))
                    AddDistinctChartLevel(candidates, swing.Price, tolerance);

                AddPreviousPeriodLevelCandidates(candidates, symbolName, sourceTimeFrame, tolerance);
                AddEqualHighLowCandidates(candidates, sourceBars, tolerance);
                AddClusteredSwingLiquidityCandidates(candidates, sourceBars, tolerance);

                var fvgLevels = new List<double>();
                AddFvgLevelCandidates(fvgLevels, sourceBars, tolerance);
                foreach (var level in fvgLevels)
                    AddDistinctChartLevel(candidates, level, tolerance);

                var obLevels = new List<double>();
                AddOrderBlockLevelCandidates(obLevels, sourceBars, tolerance);
                foreach (var level in obLevels)
                    AddDistinctChartLevel(candidates, level, tolerance);
            }
            catch
            {
            }

            return tradeType == TradeType.Buy
                ? candidates.Where(v => v < baseEntry && v > stopLoss).OrderByDescending(v => v).ToList()
                : candidates.Where(v => v > baseEntry && v < stopLoss).OrderBy(v => v).ToList();
        }

        // Strategy split trades use fixed retracement steps from entry to SL:
        // leg 2 = 0.3, leg 3 = 0.5, leg 4 = 0.7, leg 5 = 0.9.
        // This keeps n.Trades deterministic across Now and Wait_confirm chain slots.
        private List<double> BuildStrategyEqualSplitEntries(Symbol symbol, TradeType tradeType, double baseEntry, double stopLoss, int totalLegCount)
        {
            return CTraderStrategyEngine.BuildSplitEntries(symbol, tradeType, baseEntry, stopLoss, totalLegCount, MinStopPips);
        }

        private List<double> BuildChartSplitLimitEntries(Symbol symbol, string symbolName, TradeType tradeType, double currentPrice, double baseEntry, double stopLoss, int orderCountOverride = 0)
        {
            var entries = new List<double>();
            if (symbol == null || symbol.PipSize <= 0 || currentPrice <= 0 || baseEntry <= 0 || stopLoss <= 0)
                return entries;

            var minOffset = Math.Max(MinStopPips, 1.0) * symbol.PipSize;
            var safeNearStop = tradeType == TradeType.Buy
                ? stopLoss + minOffset
                : stopLoss - minOffset;
            if ((tradeType == TradeType.Buy && safeNearStop >= baseEntry) ||
                (tradeType == TradeType.Sell && safeNearStop <= baseEntry))
            {
                entries.Add(baseEntry);
                return entries;
            }

            const int minLegCount = 2;
            const int maxLegCount = 5;
            var tolerance = Math.Max(symbol.PipSize * 0.5, 0.0000001);
            var usableRange = Math.Abs(baseEntry - safeNearStop);
            var spacingFloor = Math.Max(
                Math.Max(symbol.PipSize * Math.Max(8.0, MinStopPips * 2.0), usableRange / 4.0),
                tolerance);
            var structuralLevels = CollectChartSplitEntryLevels(symbol, symbolName, tradeType, baseEntry, stopLoss);
            var uniqueStructuralLevels = new List<double>();
            foreach (var level in structuralLevels)
            {
                if (level <= 0)
                    continue;

                var normalized = NormalizePriceToSymbol(symbol, level);
                if (tradeType == TradeType.Buy)
                {
                    if (normalized <= stopLoss || normalized >= baseEntry)
                        continue;
                }
                else
                {
                    if (normalized >= stopLoss || normalized <= baseEntry)
                        continue;
                }

                if (uniqueStructuralLevels.Any(v => Math.Abs(v - normalized) < spacingFloor))
                    continue;

                if (!uniqueStructuralLevels.Any(v => Math.Abs(v - normalized) < tolerance))
                    uniqueStructuralLevels.Add(normalized);
            }

            var maxLegsByRange = Math.Max(minLegCount, Math.Min(maxLegCount, (int)Math.Floor(usableRange / spacingFloor) + 1));
            // orderCountOverride: 0 = Auto (dynamic count, current logic); 1..5 = fixed
            // number of legs per click (still capped by what the range can physically fit).
            var desiredLegCount = orderCountOverride > 0
                ? Math.Max(1, Math.Min(orderCountOverride, maxLegsByRange))
                : Math.Max(minLegCount, Math.Min(maxLegsByRange, uniqueStructuralLevels.Count + 2));
            if (!entries.Any(v => Math.Abs(v - baseEntry) < tolerance))
                entries.Add(baseEntry);

            var midpointBetweenCurrentAndBase = NormalizePriceToSymbol(symbol, (currentPrice + baseEntry) / 2.0);
            var midpointValid = tradeType == TradeType.Buy
                ? midpointBetweenCurrentAndBase > baseEntry && midpointBetweenCurrentAndBase < currentPrice
                : midpointBetweenCurrentAndBase < baseEntry && midpointBetweenCurrentAndBase > currentPrice;
            if (midpointValid && Math.Abs(midpointBetweenCurrentAndBase - baseEntry) >= spacingFloor)
                entries.Add(midpointBetweenCurrentAndBase);

            foreach (var level in uniqueStructuralLevels)
            {
                if (entries.Count >= desiredLegCount)
                    break;
                if (!entries.Any(v => Math.Abs(v - level) < tolerance))
                    entries.Add(level);
            }

            if (entries.Count < desiredLegCount)
            {
                var anchors = new List<double> { baseEntry };
                anchors.AddRange(entries);
                anchors.Add(safeNearStop);

                var orderedAnchors = tradeType == TradeType.Buy
                    ? anchors.Distinct().OrderByDescending(v => v).ToList()
                    : anchors.Distinct().OrderBy(v => v).ToList();

                while (entries.Count < desiredLegCount)
                {
                    double bestCandidate = 0;
                    double widestGap = double.MinValue;

                    for (var i = 0; i < orderedAnchors.Count - 1; i++)
                    {
                        var outer = orderedAnchors[i];
                        var inner = orderedAnchors[i + 1];
                        var gap = Math.Abs(outer - inner);
                        if (gap < (spacingFloor * 1.5) || gap <= widestGap)
                            continue;

                        var midpoint = NormalizePriceToSymbol(symbol, (outer + inner) / 2.0);
                        if (tradeType == TradeType.Buy)
                        {
                            if (midpoint <= stopLoss || midpoint >= baseEntry)
                                continue;
                        }
                        else
                        {
                            if (midpoint >= stopLoss || midpoint <= baseEntry)
                                continue;
                        }

                        if (orderedAnchors.Any(v => Math.Abs(v - midpoint) < spacingFloor))
                            continue;
                        if (entries.Any(v => Math.Abs(v - midpoint) < tolerance))
                            continue;

                        widestGap = gap;
                        bestCandidate = midpoint;
                    }

                    if (bestCandidate <= 0)
                        break;

                    entries.Add(bestCandidate);
                    orderedAnchors.Add(bestCandidate);
                    orderedAnchors = tradeType == TradeType.Buy
                        ? orderedAnchors.OrderByDescending(v => v).ToList()
                        : orderedAnchors.OrderBy(v => v).ToList();
                }
            }

            var orderedEntries = tradeType == TradeType.Buy
                ? entries.ToList()
                : entries.ToList();

            var distinctEntries = new List<double>();
            foreach (var entry in orderedEntries)
            {
                if (!distinctEntries.Any(v => Math.Abs(v - entry) < tolerance))
                    distinctEntries.Add(entry);
            }

            return distinctEntries.Take(desiredLegCount).ToList();
        }

        private double[] BuildChartSplitRiskWeights(int legCount, bool marketFirst)
        {
            return CTraderAllocationEngine.BuildSplitRiskWeights(legCount, marketFirst);
        }

        // Filters a split ladder down to legs whose risk slice can cover the risk of the minimum
        // tradable volume at that leg's stop distance (thin slices on wide-stop symbols such as
        // XAUUSD otherwise make every leg fail with volume_too_small). Kept weights are re-scaled
        // to the original total weight so the risk budget is preserved. Returns false when no leg
        // is affordable (callers fall back to a single full-budget leg).
        private bool TryResolveAffordableSplitLegs(
            Symbol symbol,
            TradeType tradeType,
            IList<double> entries,
            IList<double> weights,
            double stopLoss,
            double finalRiskMoney,
            List<double> affordableEntries,
            List<double> affordableWeights)
        {
            return CTraderExecutionEngine.TryResolveAffordableSplitLegs(
                symbol,
                entries,
                weights,
                stopLoss,
                finalRiskMoney,
                affordableEntries,
                affordableWeights);
        }

        private void ExecuteChartQuickSplitLimitOrder(TradeType tradeType)
        {
            var started = Stopwatch.StartNew();
            try
            {
                var symbolName = GetEffectiveChartEntrySymbolSelection();
                var selectedTradeProfile = GetChartTradeProfileRaw(ReadChartTradeTypeComboSelection());
                if (string.IsNullOrWhiteSpace(symbolName))
                {
                    SafeLog("ERROR", "[ChartTrade] {0} X rejected: no_symbol_selected (chart_symbol={1}; profile={2})", tradeType == TradeType.Buy ? "BUY" : "SELL", Chart != null ? Chart.SymbolName : "", selectedTradeProfile);
                    RefreshDebugPanelLite();
                    return;
                }

                var symbol = ResolveLoadedSymbol(symbolName);
                if (symbol == null)
                {
                    SafeLog("ERROR", "[ChartTrade] {0} X {1} rejected: symbol_not_loaded (profile={2}); fix=ensure_symbol_has_live_quotes", tradeType == TradeType.Buy ? "BUY" : "SELL", symbolName, selectedTradeProfile);
                    RefreshDebugPanelLite();
                    return;
                }

                var action = tradeType == TradeType.Buy ? "BUY" : "SELL";
                Print(string.Format(CultureInfo.InvariantCulture, "[Click] {0} SPLIT_LIMIT clicked symbol='{1}' loaded={2} profile='{3}'", action, symbolName, symbol != null ? "yes" : "no", selectedTradeProfile));
                var tradableRejectReason = DetectSymbolTradeAvailabilityReason(symbol);
                if (!string.IsNullOrWhiteSpace(tradableRejectReason))
                {
                    SafeLog("ERROR", "[ChartTrade] {0} X {1} rejected: {2}", action, symbolName, DescribeTradeAvailabilityReason(tradableRejectReason, symbolName));
                    RefreshDebugPanelLite();
                    return;
                }

                var plan = BuildChartLimitPlanV2(symbol, symbolName, tradeType, selectedTradeProfile);
                if (!plan.IsValid)
                    plan = BuildChartLimitPlanFromLegacy(symbol, symbolName, tradeType, selectedTradeProfile);
                if (!plan.IsValid)
                {
                    SafeLog("ERROR", "[ChartTrade] {0} X {1} rejected: no_valid_entry_plan (profile={2}; tf={3}; market={4:F5})", action, symbolName, selectedTradeProfile, GetChartTradeStructureTfLabel(selectedTradeProfile), tradeType == TradeType.Buy ? symbol.Ask : symbol.Bid);
                    RefreshDebugPanelLite();
                    return;
                }
                LogPerfStep("SplitLimit.PlanReady", started.ElapsedMilliseconds, string.Format(CultureInfo.InvariantCulture, "{0} {1}", symbolName, action), 25);

                var currentPrice = tradeType == TradeType.Buy ? symbol.Ask : symbol.Bid;
                var baseEntry = NormalizePriceToSymbol(symbol, plan.Entry);
                var sl = NormalizePriceToSymbol(symbol, plan.StopLoss);
                var tp = NormalizePriceToSymbol(symbol, plan.TakeProfit);
                var sharedSl = NormalizePriceToSymbol(symbol, sl);
                var sharedTp = NormalizePriceToSymbol(symbol, tp);
                var entries = BuildChartSplitLimitEntries(symbol, symbolName, tradeType, currentPrice, baseEntry, sharedSl, ResolveChartOrderCount());
                if (entries.Count == 0)
                {
                    SafeLog("ERROR", "[ChartTrade] {0} X {1} rejected: no_valid_split_entries (base_entry={2:F5}; sl={3:F5}; market={4:F5})", action, symbolName, baseEntry, sharedSl, currentPrice);
                    RefreshDebugPanelLite();
                    return;
                }
                LogPerfStep("SplitLimit.EntriesReady", started.ElapsedMilliseconds, string.Format(CultureInfo.InvariantCulture, "{0} {1} legs={2}", symbolName, action, entries.Count), 25);

                var finalRiskMoney = ResolveChartFinalRiskMoney(selectedTradeProfile);
                var weights = BuildChartSplitRiskWeights(entries.Count, false);

                // Budget-aware leg selection: a leg is only tradable when its risk slice can cover
                // the risk of the minimum tradable volume at that leg's stop distance. Drop
                // unaffordable legs and re-normalize the kept slices so the risk budget is never
                // wasted (e.g. XAUUSD with a wide stop makes thin slices fall below min-volume
                // risk, which previously rejected the whole ladder). Fall back to a single
                // full-budget leg when nothing is affordable.
                var finalEntries = new List<double>();
                var finalWeights = new List<double>();
                if (!TryResolveAffordableSplitLegs(symbol, tradeType, entries, weights, sharedSl, finalRiskMoney, finalEntries, finalWeights))
                {
                    SafeLog("INFO", "[ChartTrade] {0} X {1} budget too small for ladder (risk={2:F2}); falling back to single leg", action, symbolName, finalRiskMoney);
                    finalEntries = new List<double> { entries[0] };
                    finalWeights = new List<double> { 1.0 };
                }

                SafeLog(
                    "INFO",
                    "[ChartTrade] {0} X {1} ladder entries: {2}",
                    action,
                    symbolName,
                    string.Join(", ", finalEntries.Select(v => v.ToString("F5", CultureInfo.InvariantCulture)).ToArray()));

                var placedCount = 0;
                var totalPlacedRisk = 0.0;
                var legFailReasons = new List<string>();
                var directionMinOffset = Math.Max(symbol.PipSize * 2.0, 0.0000001);
                for (var i = 0; i < finalEntries.Count && i < finalWeights.Count; i++)
                {
                    var entry = finalEntries[i];
                    var sliceRiskMoney = finalRiskMoney > 0 ? Math.Max(0, finalRiskMoney * finalWeights[i]) : 0;

                    // A limit order must rest on the correct side of the market: buy limits below
                    // the ask, sell limits above the bid. Wrong-side entries are rejected by the
                    // broker with a terse "invalid price" error, so catch them here with a clear
                    // reason instead.
                    if ((tradeType == TradeType.Buy && entry >= currentPrice - directionMinOffset) ||
                        (tradeType == TradeType.Sell && entry <= currentPrice + directionMinOffset))
                    {
                        var directionReason = tradeType == TradeType.Buy ? "buy_limit_above_market" : "sell_limit_below_market";
                        legFailReasons.Add("leg" + (i + 1).ToString(CultureInfo.InvariantCulture) + ":" + directionReason);
                        SafeLog("INFO", "[ChartTrade] {0} X {1} leg {2} skipped: {3} entry={4:F5} market={5:F5}", action, symbolName, i + 1, directionReason, entry, currentPrice);
                        continue;
                    }

                    var volumeUnits = ResolveChartTradeVolumeForRisk(symbol, tradeType, entry, sharedSl, sliceRiskMoney, symbolName);
                    if (volumeUnits < symbol.VolumeInUnitsMin)
                    {
                        legFailReasons.Add("leg" + (i + 1).ToString(CultureInfo.InvariantCulture) + ":volume_too_small");
                        SafeLog("INFO", "[ChartTrade] {0} X {1} leg {2} skipped: volume_too_small {3:F2}", action, symbolName, i + 1, volumeUnits);
                        continue;
                    }

                    double approvedVolumeUnits;
                    double approvedRiskMoney;
                    double approvedMarginEstimate;
                    double approvedMarginBudget;
                    double approvedSl;
                    double approvedTp;
                    string gateRejectReason;
                    if (!TryPassSharedCreationGate(
                        symbol,
                        action,
                        "limit",
                        entry,
                        entry,
                        sharedSl,
                        sharedTp,
                        volumeUnits,
                        sliceRiskMoney,
                        sliceRiskMoney,
                        true,
                        out approvedSl,
                        out approvedTp,
                        out approvedVolumeUnits,
                        out approvedRiskMoney,
                        out approvedMarginEstimate,
                        out approvedMarginBudget,
                        out gateRejectReason))
                    {
                        legFailReasons.Add("leg" + (i + 1).ToString(CultureInfo.InvariantCulture) + ":" + gateRejectReason);
                        SafeLog("INFO", "[ChartTrade] {0} X {1} leg {2} skipped: {3}", action, symbolName, i + 1, gateRejectReason);
                        continue;
                    }

                    if (approvedVolumeUnits < symbol.VolumeInUnitsMin)
                    {
                        legFailReasons.Add("leg" + (i + 1).ToString(CultureInfo.InvariantCulture) + ":volume_below_min_after_gate");
                        continue;
                    }

                    var approvedEntry = NormalizePriceToSymbol(symbol, entry);
                    var slPips = CTraderExecutionEngine.ResolveDistancePips(symbol, approvedEntry, sharedSl).GetValueOrDefault();
                    var tpPips = CTraderExecutionEngine.ResolveDistancePips(symbol, approvedEntry, sharedTp).GetValueOrDefault();
                    var legSuffix = finalEntries.Count > 1 ? "#" + (i + 1).ToString(CultureInfo.InvariantCulture) : "";
                    var label = BuildChartTradeLabel(action, "LIMIT", symbolName) + legSuffix;
                    var comment = BuildChartPendingComment(tradeType, false, symbolName) + (string.IsNullOrEmpty(legSuffix) ? "" : "|" + legSuffix);
                    var requestedLots = symbol.VolumeInUnitsToQuantity(approvedVolumeUnits);
                    LogStructuredTradeEvent("chart", "SUBMIT", symbolName, action, "LIMIT", requestedLots, approvedEntry, sharedSl, sharedTp, "", plan.StructureTfLabel + ":" + plan.EntryLabel + (string.IsNullOrEmpty(legSuffix) ? "" : "|" + legSuffix));

                    var result = PlaceLimitOrder(
                        tradeType,
                        symbol.Name,
                        approvedVolumeUnits,
                        approvedEntry,
                        label,
                        (double?)slPips,
                        (double?)tpPips,
                        (ProtectionType?)null,
                        null,
                        comment
                    );

                    if (result == null || !result.IsSuccessful)
                    {
                        var errorText = result != null ? Convert.ToString(result.Error, CultureInfo.InvariantCulture) : "unknown_error";
                        legFailReasons.Add("leg" + (i + 1).ToString(CultureInfo.InvariantCulture) + ":broker_reject " + errorText);
                        SafeLog("INFO", "[ChartTrade] {0} X {1} leg {2} failed: {3}", action, symbolName, i + 1, errorText);
                        continue;
                    }

                    if (result.PendingOrder != null)
                    {
                        string modifyError;
                        if (!TryApplyPendingOrderProtection(result.PendingOrder, symbol, action, sharedSl, sharedTp, out modifyError))
                        {
                            legFailReasons.Add("leg" + (i + 1).ToString(CultureInfo.InvariantCulture) + ":protection_apply_failed " + modifyError);
                            SafeLog("INFO", "[ChartTrade] {0} L {1} leg {2} placed but SL/TP apply failed: {3}", action, symbolName, i + 1, modifyError);
                            continue;
                        }
                    }

                    placedCount++;
                    totalPlacedRisk += Math.Abs(approvedRiskMoney);
                    LogStructuredTradeEvent("chart", "SUCCEEDED", symbolName, action, "LIMIT", requestedLots, approvedEntry, sharedSl, sharedTp, result.PendingOrder != null ? result.PendingOrder.Id.ToString(CultureInfo.InvariantCulture) : "", plan.StructureTfLabel + ":" + plan.EntryLabel + (string.IsNullOrEmpty(legSuffix) ? "" : "|" + legSuffix));
                }

                if (placedCount == 0)
                {
                    var failSummary = legFailReasons.Count > 0 ? string.Join("; ", legFailReasons) : "unknown";
                    var ladderContext = BuildSubmitContext(symbol, action, "limit", finalEntries.Count > 0 ? finalEntries[0] : entries[0], currentPrice, sharedSl, sharedTp, 0, finalRiskMoney, finalRiskMoney);
                    SafeLog("ERROR", "[ChartTrade] {0} L {1} rejected: no_split_orders_placed ({2}) | ctx={3}", action, symbolName, failSummary, ladderContext);
                    RefreshDebugPanelLite();
                    return;
                }

                SafeLog("INFO", "[ChartTrade] {0} L {1} placed {2} split limit orders using shared SL/TP. total_risk={3:F2}", action, symbolName, placedCount, totalPlacedRisk);
                RebuildChartButtonPanel();
                RefreshDebugPanelLite();
            }
            catch (Exception ex)
            {
                SafeLog("ERROR", "[ChartTrade] X LIMIT failed: {0}", ex.Message);
                RefreshDebugPanelLite();
            }
            finally
            {
                LogSlowChartStep("ExecuteChartQuickSplitLimitOrder", started, tradeType.ToString());
            }
        }

        private void ExecuteChartQuickPendingOrderV2(TradeType tradeType)
        {
            var started = Stopwatch.StartNew();
            try
            {
                var symbolName = GetEffectiveChartEntrySymbolSelection();
                var selectedTradeProfile = GetChartTradeProfileRaw(ReadChartTradeTypeComboSelection());
                if (string.IsNullOrWhiteSpace(symbolName))
                {
                    SafeLog("ERROR", "[ChartTrade] {0} LIMIT rejected: no_symbol_selected", tradeType == TradeType.Buy ? "BUY" : "SELL");
                    RefreshDebugPanelLite();
                    return;
                }

                var symbol = ResolveLoadedSymbol(symbolName);
                if (symbol == null)
                {
                    SafeLog("ERROR", "[ChartTrade] {0} LIMIT {1} rejected: symbol_not_loaded", tradeType == TradeType.Buy ? "BUY" : "SELL", symbolName);
                    RefreshDebugPanelLite();
                    return;
                }

                var action = tradeType == TradeType.Buy ? "BUY" : "SELL";
                Print(string.Format(CultureInfo.InvariantCulture, "[Click] {0} LIMIT clicked symbol='{1}' loaded={2} profile='{3}'", action, symbolName, symbol != null ? "yes" : "no", selectedTradeProfile));
                var tradableRejectReason = DetectSymbolTradeAvailabilityReason(symbol);
                if (!string.IsNullOrWhiteSpace(tradableRejectReason))
                {
                    SafeLog("ERROR", "[ChartTrade] {0} LIMIT {1} rejected: {2}", action, symbolName, DescribeTradeAvailabilityReason(tradableRejectReason, symbolName));
                    RefreshDebugPanelLite();
                    return;
                }
                var plan = BuildChartLimitPlanV2(symbol, symbolName, tradeType, selectedTradeProfile);
                if (!plan.IsValid)
                {
                    plan = BuildChartLimitPlanFromLegacy(symbol, symbolName, tradeType, selectedTradeProfile);
                    if (!plan.IsValid)
                    {
                        SafeLog("ERROR", "[ChartTrade] {0} LIMIT {1} rejected: no_valid_entry_plan from {2}, and legacy fallback also failed (profile={3}; market={4:F5}); fix=check_structure_levels_for_this_symbol", action, symbolName, GetChartTradeStructureTfLabel(selectedTradeProfile), selectedTradeProfile, tradeType == TradeType.Buy ? symbol.Ask : symbol.Bid);
                        RefreshDebugPanelLite();
                        return;
                    }

                    SafeLog("INFO", "[ChartTrade] {0} LIMIT {1} fallback: new model had no valid plan, using legacy entry/protection", action, symbolName);
                }
                LogPerfStep("LimitOrder.PlanReady", started.ElapsedMilliseconds, string.Format(CultureInfo.InvariantCulture, "{0} {1}", symbolName, action), 25);

                var entry = NormalizePriceToSymbol(symbol, plan.Entry);
                var sl = NormalizePriceToSymbol(symbol, plan.StopLoss);
                var tp = NormalizePriceToSymbol(symbol, plan.TakeProfit);
                var finalRiskMoney = ResolveChartFinalRiskMoney(selectedTradeProfile);
                var volumeUnits = ResolveChartTradeVolumeForRisk(symbol, tradeType, entry, sl, finalRiskMoney, symbolName);
                LogPerfStep("LimitOrder.VolumeReady", started.ElapsedMilliseconds, string.Format(CultureInfo.InvariantCulture, "{0} {1} risk={2:F2}", symbolName, action, finalRiskMoney), 25);
                if (volumeUnits < symbol.VolumeInUnitsMin)
                {
                    SafeLog("ERROR", "[ChartTrade] {0} LIMIT {1} rejected: volume_too_small {2}", action, symbolName, volumeUnits);
                    RefreshDebugPanelLite();
                    return;
                }

                double approvedVolumeUnits;
                double approvedRiskMoney;
                double approvedMarginEstimate;
                double approvedMarginBudget;
                double approvedSl;
                double approvedTp;
                string gateRejectReason;
                if (!TryPassSharedCreationGate(
                    symbol,
                    action,
                    "limit",
                    entry,
                    entry,
                    sl,
                    tp,
                    volumeUnits,
                    finalRiskMoney,
                    finalRiskMoney,
                    true,
                    out approvedSl,
                    out approvedTp,
                    out approvedVolumeUnits,
                    out approvedRiskMoney,
                    out approvedMarginEstimate,
                    out approvedMarginBudget,
                    out gateRejectReason))
                {
                    SafeLog("ERROR", "[ChartTrade] {0} LIMIT {1} rejected: {2} | ctx={3}", action, symbolName, gateRejectReason, BuildSubmitContext(symbol, action, "limit", entry, entry, sl, tp, volumeUnits, finalRiskMoney, finalRiskMoney));
                    RefreshDebugPanelLite();
                    return;
                }
                if (approvedVolumeUnits < volumeUnits)
                {
                    SafeLog(
                        "INFO",
                        "[ChartTrade] {0} LIMIT {1} volume reduced by shared gate: {2:F2} -> {3:F2} units (risk {4:F2}/{5:F2})",
                        action,
                        symbolName,
                        volumeUnits,
                        approvedVolumeUnits,
                        approvedRiskMoney,
                        finalRiskMoney
                    );
                    volumeUnits = approvedVolumeUnits;
                }
                LogPerfStep("LimitOrder.GatePassed", started.ElapsedMilliseconds, string.Format(CultureInfo.InvariantCulture, "{0} {1} vol={2:F2}", symbolName, action, volumeUnits), 25);

                sl = approvedSl;
                tp = approvedTp;

                var slPips = CTraderExecutionEngine.ResolveDistancePips(symbol, entry, sl).GetValueOrDefault();
                var tpPips = CTraderExecutionEngine.ResolveDistancePips(symbol, entry, tp).GetValueOrDefault();
                var label = BuildChartTradeLabel(action, "LIMIT", symbolName);
                var comment = BuildChartPendingComment(tradeType, false, symbolName);
                var requestedLots = symbol.VolumeInUnitsToQuantity(volumeUnits);
                LogStructuredTradeEvent("chart", "SUBMIT", symbolName, action, "LIMIT", requestedLots, entry, sl, tp, "", plan.StructureTfLabel + ":" + plan.EntryLabel);
                var result = PlaceLimitOrder(
                    tradeType,
                    symbol.Name,
                    volumeUnits,
                    entry,
                    label,
                    (double?)slPips,
                    (double?)tpPips,
                    (ProtectionType?)null,
                    null,
                    comment
                );
                LogPerfStep("LimitOrder.Submitted", started.ElapsedMilliseconds, string.Format(CultureInfo.InvariantCulture, "{0} {1}", symbolName, action), 25);

                if (result == null || !result.IsSuccessful)
                {
                    var errorText = result != null ? Convert.ToString(result.Error, CultureInfo.InvariantCulture) : "unknown_error";
                    LogStructuredTradeEvent("chart", "FAILED", symbolName, action, "LIMIT", requestedLots, entry, sl, tp, "", errorText);
                    SafeLog("ERROR", "[ChartTrade] {0} LIMIT {1} failed: {2}", action, symbolName, errorText);
                    RefreshDebugPanelLite();
                    return;
                }

                if (result.PendingOrder != null)
                {
                    string modifyError;
                    if (!TryApplyPendingOrderProtection(result.PendingOrder, symbol, action, sl, tp, out modifyError))
                    {
                        SafeLog("ERROR", "[ChartTrade] {0} LIMIT {1} placed but SL/TP apply failed: {2}", action, symbolName, modifyError);
                        RefreshDebugPanelLite();
                        return;
                    }
                }

                LogStructuredTradeEvent("chart", "SUCCEEDED", symbolName, action, "LIMIT", requestedLots, entry, sl, tp, result.PendingOrder != null ? result.PendingOrder.Id.ToString(CultureInfo.InvariantCulture) : "", plan.StructureTfLabel + ":" + plan.EntryLabel);
                SafeLog(
                    "INFO",
                    "[ChartTrade] {0} LIMIT {1} [{2}] {3} RR={4:F2} E={5:F5} SL={6:F5} TP={7:F5}",
                    action,
                    symbolName,
                    plan.StructureTfLabel,
                    plan.EntryLabel,
                    plan.RewardRisk,
                    entry,
                    sl,
                    tp
                );
                RebuildChartButtonPanel();
                RefreshDebugPanelLite();
            }
            catch (Exception ex)
            {
                SafeLog("ERROR", "[ChartTrade] LIMIT failed: {0}", ex.Message);
                RefreshDebugPanelLite();
            }
            finally
            {
                LogSlowChartStep("ExecuteChartQuickPendingOrderV2", started, tradeType.ToString());
            }
        }

        private double GetChartProtectionStepPrice(Symbol symbol)
        {
            return CTraderExecutionEngine.ResolveProtectionStepPrice(symbol, MinStopPips);
        }

        private bool TryApplyPendingOrderProtection(PendingOrder pendingOrder, Symbol symbol, string action, double slPrice, double tpPrice, out string errorText)
        {
            errorText = "";
            if (pendingOrder == null)
            {
                errorText = "pending_order_missing";
                return false;
            }
            var protectionPlan = CTraderExecutionEngine.BuildPendingProtectionPlan(
                symbol, action, pendingOrder.TargetPrice, slPrice, tpPrice);
            if (!protectionPlan.IsValid)
            {
                errorText = protectionPlan.Error;
                CancelPendingOrderAfterProtectionFailure(pendingOrder, ref errorText);
                return false;
            }

            var modifyResult = ModifyPendingOrderCompat(
                pendingOrder,
                pendingOrder.TargetPrice,
                protectionPlan.StopLossPips,
                protectionPlan.TakeProfitPips,
                pendingOrder.ExpirationTime);
            if (modifyResult != null && modifyResult.IsSuccessful)
                return true;

            errorText = modifyResult != null
                ? Convert.ToString(modifyResult.Error, CultureInfo.InvariantCulture)
                : "unknown_modify_error";
            CancelPendingOrderAfterProtectionFailure(pendingOrder, ref errorText);
            return false;
        }

        private void CancelPendingOrderAfterProtectionFailure(PendingOrder pendingOrder, ref string errorText)
        {
            if (pendingOrder == null)
                return;

            var cancelResult = CancelPendingOrder(pendingOrder);
            var cancelState = cancelResult != null && cancelResult.IsSuccessful
                ? "cancelled"
                : "cancel_failed:" + (cancelResult != null ? Convert.ToString(cancelResult.Error, CultureInfo.InvariantCulture) : "null_result");
            errorText = (errorText ?? "pending_protection_failed") + "; " + cancelState;
        }

        private double BuildSharedProtectionTarget(Symbol symbol, TradeType tradeType, bool isStopLoss, bool moveCloser, double referencePrice, IEnumerable<double> existingLevels)
        {
            return CTraderExecutionEngine.BuildSharedProtectionTarget(
                symbol,
                tradeType,
                isStopLoss,
                moveCloser,
                referencePrice,
                existingLevels,
                MinStopPips);
        }

        private int ApplySharedProtectionTarget(string symbolName, TradeType tradeType, bool isStopLoss, double targetPrice)
        {
            var modifiedCount = 0;
            var symbol = ResolveLoadedSymbol(symbolName);
            var pipSize = symbol != null && symbol.PipSize > 0 ? symbol.PipSize : 0.0000001;
            var positionTargets = Positions
                .Where(p => p != null && string.Equals(p.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase) && p.TradeType == tradeType)
                .ToList();

            foreach (var position in positionTargets)
            {
                var nextSl = isStopLoss ? (double?)targetPrice : position.StopLoss;
                var nextTp = isStopLoss ? position.TakeProfit : (double?)targetPrice;
                var result = ModifyPositionCompat(position, nextSl, nextTp);
                if (result.IsSuccessful) modifiedCount++;
                else SafePrint("[ChartTrade] Modify failed for {0} #{1}: {2}", symbolName, position.Id, result.Error);
            }

            var pendingTargets = PendingOrders
                .Where(o => o != null && string.Equals(o.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase) && o.TradeType == tradeType)
                .ToList();

            foreach (var order in pendingTargets)
            {
                var slPips = isStopLoss
                    ? (double?)Math.Round(Math.Abs(order.TargetPrice - targetPrice) / pipSize, 2)
                    : order.StopLossPips;
                var tpPips = isStopLoss
                    ? order.TakeProfitPips
                    : (double?)Math.Round(Math.Abs(order.TargetPrice - targetPrice) / pipSize, 2);

                var result = ModifyPendingOrderCompat(order, order.TargetPrice, slPips, tpPips, order.ExpirationTime);
                if (result != null && result.IsSuccessful) modifiedCount++;
                else SafePrint("[ChartTrade] Pending modify failed for {0} #{1}: {2}", symbolName, order.Id, result != null ? Convert.ToString(result.Error, CultureInfo.InvariantCulture) : "unknown_error");
            }

            return modifiedCount;
        }

        private void ClearChartProtection(bool isStopLoss)
        {
            try
            {
                var symbolName = ReadChartSymbolComboSelection();
                var selectedDirection = ReadChartDirectionComboSelection();
                var protectionName = isStopLoss ? "SL" : "TP";
                if (string.IsNullOrWhiteSpace(symbolName))
                {
                    Print(string.Format(CultureInfo.InvariantCulture, "[Click] CLEAR {0} clicked -> no symbol selected", protectionName));
                    return;
                }

                var positions = GetChartSelectedPositions(symbolName, selectedDirection);
                var orders = GetChartSelectedPendingOrders(symbolName, selectedDirection);
                if (positions.Count == 0 && orders.Count == 0)
                {
                    Print(string.Format(CultureInfo.InvariantCulture, "[Click] CLEAR {0} clicked symbol='{1}' dir='{2}' -> no positions/orders", protectionName, symbolName, selectedDirection));
                    return;
                }
                Print(string.Format(CultureInfo.InvariantCulture, "[Click] CLEAR {0} clicked symbol='{1}' dir='{2}' positions={3} orders={4}", protectionName, symbolName, selectedDirection, positions.Count, orders.Count));

                var modifiedCount = 0;
                foreach (var position in positions)
                {
                    var nextSl = isStopLoss ? (double?)null : position.StopLoss;
                    var nextTp = isStopLoss ? position.TakeProfit : (double?)null;
                    var result = ModifyPositionCompat(position, nextSl, nextTp);
                    if (result != null && result.IsSuccessful) modifiedCount++;
                    else SafePrint("[ChartTrade] Clear {0} failed for {1} position #{2}: {3}", protectionName, position.SymbolName, position.Id, result != null ? Convert.ToString(result.Error, CultureInfo.InvariantCulture) : "unknown_error");
                }

                foreach (var order in orders)
                {
                    var slPips = isStopLoss ? (double?)null : order.StopLossPips;
                    var tpPips = isStopLoss ? order.TakeProfitPips : (double?)null;
                    var result = ModifyPendingOrderCompat(order, order.TargetPrice, slPips, tpPips, order.ExpirationTime);
                    if (result != null && result.IsSuccessful) modifiedCount++;
                    else SafePrint("[ChartTrade] Clear {0} failed for {1} pending #{2}: {3}", protectionName, order.SymbolName, order.Id, result != null ? Convert.ToString(result.Error, CultureInfo.InvariantCulture) : "unknown_error");
                }

                SafePrint("[ChartTrade] Cleared {0} on {1} trade item(s) for {2} {3}", protectionName, modifiedCount, symbolName, selectedDirection);
                RebuildChartButtonPanel();
                RefreshDebugPanel();
            }
            catch (Exception ex)
            {
                SafePrint("[ChartTrade] Clear {0} failed: {1}", isStopLoss ? "SL" : "TP", ex.Message);
            }
        }

        private void SyncChartSymbolProtection()
        {
            try
            {
                Print("[Click] SYNC clicked");
                string symbolName;
                Symbol symbol;
                if (!TryGetChartSelectedSymbol(out symbolName, out symbol)) return;
                var selectedDirection = ReadChartDirectionComboSelection();

                var positions = GetChartSelectedPositions(symbolName, selectedDirection);
                if (positions.Count == 0)
                {
                    Print(string.Format(CultureInfo.InvariantCulture, "[Click] SYNC clicked symbol='{0}' dir='{1}' -> no open positions", symbolName, selectedDirection));
                    return;
                }
                Print(string.Format(CultureInfo.InvariantCulture, "[Click] SYNC clicked symbol='{0}' dir='{1}' positions={2}", symbolName, selectedDirection, positions.Count));

                var modifiedCount = 0;
                foreach (var tradeType in new[] { TradeType.Buy, TradeType.Sell })
                {
                    var sidePositions = positions.Where(p => p.TradeType == tradeType).ToList();
                    if (sidePositions.Count == 0) continue;

                    var referencePrice = tradeType == TradeType.Buy ? symbol.Bid : symbol.Ask;
                    var sharedSl = FindClosestChartProtectionPrice(symbolName, tradeType, true, referencePrice);
                    var sharedTp = FindClosestChartProtectionPrice(symbolName, tradeType, false, referencePrice);

                    foreach (var pos in sidePositions)
                    {
                        var nextSl = sharedSl.HasValue ? (double?)NormalizePriceToSymbol(symbol, sharedSl.Value) : pos.StopLoss;
                        var nextTp = sharedTp.HasValue ? (double?)NormalizePriceToSymbol(symbol, sharedTp.Value) : pos.TakeProfit;
                        var result = ModifyPositionCompat(pos, nextSl, nextTp);
                        if (result.IsSuccessful) modifiedCount++;
                        else SafePrint("[ChartTrade] Sync failed for {0} #{1}: {2}", symbolName, pos.Id, result.Error);
                    }
                }

                SafePrint("[ChartTrade] Sync updated {0} position(s) for {1} {2}", modifiedCount, symbolName, selectedDirection);
                RebuildChartButtonPanel();
                RefreshDebugPanel();
            }
            catch (Exception ex)
            {
                SafePrint("[ChartTrade] Sync failed: {0}", ex.Message);
            }
        }

        private void CloseChartSymbolPositions(double percentToClose)
        {
            try
            {
                var symbolName = ReadChartSymbolComboSelection();
                if (string.IsNullOrWhiteSpace(symbolName))
                {
                    Print("[Click] CLOSE clicked -> no symbol selected");
                    return;
                }

                var selectedDirection = ReadChartDirectionComboSelection();

                var positions = GetChartSelectedPositions(symbolName, selectedDirection);
                if (positions.Count == 0)
                {
                    Print(string.Format(CultureInfo.InvariantCulture, "[Click] CLOSE {0}% clicked symbol='{1}' dir='{2}' -> no open positions", percentToClose, symbolName, selectedDirection));
                    return;
                }
                Print(string.Format(CultureInfo.InvariantCulture, "[Click] CLOSE {0}% clicked symbol='{1}' dir='{2}' positions={3}", percentToClose, symbolName, selectedDirection, positions.Count));

                var closedCount = 0;
                var skippedCount = 0;
                foreach (var pos in positions)
                {
                    var posSymbol = ResolveLoadedSymbol(pos.SymbolName);
                    var posSide = pos.TradeType == TradeType.Buy ? "Buy" : "Sell";
                    var posPnl = double.IsNaN(pos.NetProfit) ? 0 : pos.NetProfit;
                    if (posSymbol == null)
                    {
                        skippedCount++;
                        SafePrint("[ChartTrade] Close skipped for {0} {1} #{2}: symbol_not_loaded pnl={3:F2}", pos.SymbolName, posSide, pos.Id, posPnl);
                        continue;
                    }

                    TradeResult result;
                    double closeVolume = pos.VolumeInUnits;
                    if (percentToClose >= 100)
                    {
                        result = ClosePosition(pos);
                    }
                    else
                    {
                        var volumeToClose = CTraderExecutionEngine.ResolveNormalizedPartialCloseVolume(
                            posSymbol, pos.VolumeInUnits, percentToClose);
                        if (volumeToClose < posSymbol.VolumeInUnitsMin)
                        {
                            skippedCount++;
                            SafePrint(
                                "[ChartTrade] Close skipped for {0} #{1}: partial_volume_below_min {2:F2}<{3:F2}",
                                pos.SymbolName,
                                pos.Id,
                                volumeToClose,
                                posSymbol.VolumeInUnitsMin
                            );
                            continue;
                        }
                        closeVolume = volumeToClose;
                        result = ClosePosition(pos, volumeToClose);
                    }

                    if (result.IsSuccessful)
                    {
                        closedCount++;
                        SafePrint("[ChartTrade] Close OK {0} {1} #{2} volume={3:F2}/{4:F2} pnl={5:F2}", pos.SymbolName, posSide, pos.Id, closeVolume, pos.VolumeInUnits, posPnl);
                    }
                    else SafePrint("[ChartTrade] Close failed for {0} {1} #{2}: {3} pnl={4:F2}", pos.SymbolName, posSide, pos.Id, result.Error, posPnl);
                }

                SafePrint("[ChartTrade] Closed {0} position(s), skipped {1} for {2} {3}", closedCount, skippedCount, symbolName, selectedDirection);
                RebuildChartButtonPanel();
                RefreshDebugPanel();
            }
            catch (Exception ex)
            {
                SafePrint("[ChartTrade] Close failed: {0}", ex.Message);
            }
        }

        private void CancelChartSymbolPendingOrders()
        {
            try
            {
                var symbolName = ReadChartSymbolComboSelection();
                if (string.IsNullOrWhiteSpace(symbolName))
                {
                    Print("[Click] CANCEL clicked -> no symbol selected");
                    return;
                }

                var selectedDirection = ReadChartDirectionComboSelection();

                var orders = GetChartSelectedPendingOrders(symbolName, selectedDirection);
                if (orders.Count == 0)
                {
                    Print(string.Format(CultureInfo.InvariantCulture, "[Click] CANCEL clicked symbol='{0}' dir='{1}' -> no pending orders", symbolName, selectedDirection));
                    return;
                }
                Print(string.Format(CultureInfo.InvariantCulture, "[Click] CANCEL clicked symbol='{0}' dir='{1}' orders={2}", symbolName, selectedDirection, orders.Count));

                var canceledCount = 0;
                foreach (var order in orders)
                {
                    var result = CancelPendingOrder(order);
                    if (result.IsSuccessful) canceledCount++;
                    else SafePrint("[ChartTrade] Cancel failed for {0} #{1}: {2}", symbolName, order.Id, result.Error);
                }

                SafePrint("[ChartTrade] Canceled {0} pending order(s) for {1} {2}", canceledCount, symbolName, selectedDirection);
                RebuildChartButtonPanel();
                RefreshDebugPanel();
            }
            catch (Exception ex)
            {
                SafePrint("[ChartTrade] Cancel failed: {0}", ex.Message);
            }
        }

        private void ShiftChartProtection(bool isStopLoss, bool moveCloser)
        {
            try
            {
                var symbolName = ReadChartSymbolComboSelection();
                var selectedDirection = ReadChartDirectionComboSelection();
                if (string.IsNullOrWhiteSpace(symbolName))
                {
                    Print("[Click] PROTECTION SHIFT clicked -> no symbol selected");
                    return;
                }

                var symbol = ResolveLoadedSymbol(symbolName);
                if (symbol == null)
                {
                    Print(string.Format(CultureInfo.InvariantCulture, "[Click] PROTECTION SHIFT clicked symbol='{0}' -> not loaded", symbolName));
                    return;
                }

                var positions = GetChartSelectedPositions(symbolName, selectedDirection);
                var orders = GetChartSelectedPendingOrders(symbolName, selectedDirection);
                if (positions.Count == 0 && orders.Count == 0)
                {
                    Print(string.Format(CultureInfo.InvariantCulture, "[Click] PROTECTION SHIFT clicked symbol='{0}' dir='{1}' -> no positions/orders", symbolName, selectedDirection));
                    return;
                }
                Print(string.Format(CultureInfo.InvariantCulture, "[Click] PROTECTION SHIFT clicked symbol='{0}' dir='{1}' sl={2} closer={3} positions={4} orders={5}", symbolName, selectedDirection, isStopLoss ? "SL" : "TP", moveCloser ? "yes" : "no", positions.Count, orders.Count));

                var totalModified = 0;
                foreach (var tradeType in new[] { TradeType.Buy, TradeType.Sell })
                {
                    var sidePositions = positions.Where(p => p.TradeType == tradeType).ToList();
                    var sideOrders = orders.Where(o => o.TradeType == tradeType).ToList();
                    if (sidePositions.Count == 0 && sideOrders.Count == 0) continue;

                    var referencePrice = sidePositions.Count > 0
                        ? (tradeType == TradeType.Buy ? symbol.Bid : symbol.Ask)
                        : sideOrders[0].TargetPrice;
                    var existingLevels = sidePositions
                        .Select(p => isStopLoss ? p.StopLoss : p.TakeProfit)
                        .Where(v => v.HasValue && v.Value > 0)
                        .Select(v => v.Value)
                        .Concat(sideOrders
                            .Select(o => isStopLoss ? o.StopLoss : o.TakeProfit)
                            .Where(v => v.HasValue && v.Value > 0)
                            .Select(v => v.Value))
                        .ToList();
                    var oppositeLevels = sidePositions
                        .Select(p => isStopLoss ? p.TakeProfit : p.StopLoss)
                        .Where(v => v.HasValue && v.Value > 0)
                        .Select(v => v.Value)
                        .Concat(sideOrders
                            .Select(o => isStopLoss ? o.TakeProfit : o.StopLoss)
                            .Where(v => v.HasValue && v.Value > 0)
                            .Select(v => v.Value))
                        .ToList();

                    var targetPrice = BuildSharedProtectionTarget(symbol, tradeType, isStopLoss, moveCloser, referencePrice, existingLevels);
                    string reason;
                    var action = tradeType == TradeType.Buy ? "BUY" : "SELL";
                    var validationReference = referencePrice;
                    var existingSl = sidePositions.FirstOrDefault(p => p.StopLoss.HasValue && p.StopLoss.Value > 0)?.StopLoss
                        ?? sideOrders.FirstOrDefault(o => o.StopLoss.HasValue && o.StopLoss.Value > 0)?.StopLoss
                        ?? 0;
                    var existingTp = sidePositions.FirstOrDefault(p => p.TakeProfit.HasValue && p.TakeProfit.Value > 0)?.TakeProfit
                        ?? sideOrders.FirstOrDefault(o => o.TakeProfit.HasValue && o.TakeProfit.Value > 0)?.TakeProfit
                        ?? 0;
                    if (isStopLoss && existingTp <= 0)
                        existingTp = BuildSharedProtectionTarget(symbol, tradeType, false, false, referencePrice, oppositeLevels);
                    if (!isStopLoss && existingSl <= 0)
                        existingSl = BuildSharedProtectionTarget(symbol, tradeType, true, false, referencePrice, oppositeLevels);
                    var checkSl = isStopLoss ? targetPrice : existingSl;
                    var checkTp = isStopLoss ? existingTp : targetPrice;

                    if (!TryValidateProtectionPrices(symbol, action, validationReference, checkSl, checkTp, out reason))
                    {
                        SafePrint("[ChartTrade] {0} {1} {2} rejected: {3}", symbolName, action, isStopLoss ? "SL" : "TP", reason);
                        continue;
                    }

                    totalModified += ApplySharedProtectionTarget(symbolName, tradeType, isStopLoss, targetPrice);
                }

                SafePrint("[ChartTrade] {0} {1} updated {2} trade item(s) for {3} {4}", isStopLoss ? "SL" : "TP", moveCloser ? "closer" : "farther", totalModified, symbolName, selectedDirection);
                RebuildChartButtonPanel();
                RefreshDebugPanel();
            }
            catch (Exception ex)
            {
                SafePrint("[ChartTrade] Protection shift failed: {0}", ex.Message);
            }
        }

        // Full sync payload builder: positions + orders + closed + metrics
        private void BuildAndDispatchSync(string accId)
        {
            string bal = Account.Balance.ToString(CultureInfo.InvariantCulture);
            string eq = Account.Equity.ToString(CultureInfo.InvariantCulture);
            string mar = Account.Margin.ToString(CultureInfo.InvariantCulture);
            string brk = Account.BrokerName;
            var pl = new List<string>();
            var ati = new HashSet<string>(Positions.Select(p => p.Id.ToString()));
            foreach (var pos in Positions)
            {
                var sid = ResolveSid(pos.Id.ToString(), pos.Comment).Replace("\"", "'");
                var s = ResolveLoadedSymbol(pos.SymbolName);
                double lotsVal = (s != null) ? s.VolumeInUnitsToQuantity(pos.VolumeInUnits) : (pos.VolumeInUnits / 100000.0);
                double tpPnl = 0, slPnl = 0, distTp = 0, distSl = 0, spreadVal = 0;
                if (s != null)
                {
                    spreadVal = double.IsNaN(s.Spread) ? 0 : s.Spread;
                    if (pos.TakeProfit.HasValue) { double pips = (pos.TakeProfit.Value - pos.EntryPrice) / s.PipSize; if (pos.TradeType == TradeType.Sell) pips = -pips; tpPnl = EstimatePnlFromPips(s, pips, pos.VolumeInUnits); distTp = Math.Abs(pips); }
                    if (pos.StopLoss.HasValue) { double pips = (pos.StopLoss.Value - pos.EntryPrice) / s.PipSize; if (pos.TradeType == TradeType.Sell) pips = -pips; slPnl = EstimatePnlFromPips(s, pips, pos.VolumeInUnits); distSl = Math.Abs(pips); }
                }
                double balTp = tpPnl, balSl = slPnl;
                var tk = pos.Id.ToString(); double pcv = 0; _partialClosedVolumes.TryGetValue(tk, out pcv);
                double rv = double.IsNaN(pos.VolumeInUnits) ? 0 : pos.VolumeInUnits; bool hp = pcv > 0;
                var syncSource = ResolveSyncedTradeSource(pos.Label, pos.Comment);
                pl.Add("{\"sid\":\"" + sid + "\",\"comment\":\"" + EscapeJson(pos.Comment) + "\",\"source\":\"" + EscapeJson(syncSource) + "\",\"ticket\":\"" + pos.Id + "\",\"symbol\":\"" + pos.SymbolName + "\",\"side\":\"" + pos.TradeType.ToString().ToUpper() + "\",\"type\":\"MARKET\",\"entry\":" + (double.IsNaN(pos.EntryPrice) ? 0 : pos.EntryPrice).ToString("F5", CultureInfo.InvariantCulture) + ",\"sl\":" + (pos.StopLoss ?? 0).ToString("F5", CultureInfo.InvariantCulture) + ",\"tp\":" + (pos.TakeProfit ?? 0).ToString("F5", CultureInfo.InvariantCulture) + ",\"volume\":" + (double.IsNaN(pos.VolumeInUnits) ? 0 : pos.VolumeInUnits).ToString("F2", CultureInfo.InvariantCulture) + ",\"lots\":" + (double.IsNaN(lotsVal) ? 0 : lotsVal).ToString("F2", CultureInfo.InvariantCulture) + ",\"pnl\":" + (double.IsNaN(pos.NetProfit) ? 0 : pos.NetProfit).ToString("F2", CultureInfo.InvariantCulture) + ",\"pips\":" + (double.IsNaN(pos.Pips) ? 0 : pos.Pips).ToString("F2", CultureInfo.InvariantCulture) + ",\"commission\":" + (double.IsNaN(pos.Commissions) ? 0 : pos.Commissions).ToString("F2", CultureInfo.InvariantCulture) + ",\"swap\":" + (double.IsNaN(pos.Swap) ? 0 : pos.Swap).ToString("F2", CultureInfo.InvariantCulture) + ",\"margin\":" + (double.IsNaN(pos.Margin) ? 0 : pos.Margin).ToString("F2", CultureInfo.InvariantCulture) + ",\"tp_pnl\":" + (double.IsNaN(tpPnl) ? 0 : tpPnl).ToString("F2", CultureInfo.InvariantCulture) + ",\"sl_pnl\":" + (double.IsNaN(slPnl) ? 0 : slPnl).ToString("F2", CultureInfo.InvariantCulture) + ",\"spread\":" + spreadVal.ToString("F2", CultureInfo.InvariantCulture) + ",\"distance_sl\":" + distSl.ToString("F2", CultureInfo.InvariantCulture) + ",\"distance_tp\":" + distTp.ToString("F2", CultureInfo.InvariantCulture) + ",\"balance_sl\":" + balSl.ToString("F2", CultureInfo.InvariantCulture) + ",\"balance_tp\":" + balTp.ToString("F2", CultureInfo.InvariantCulture) + ",\"label\":\"" + pos.Label + "\",\"status\":\"OPEN\",\"remaining_volume\":" + rv.ToString("F2", CultureInfo.InvariantCulture) + ",\"closed_volume_partial\":" + pcv.ToString("F2", CultureInfo.InvariantCulture) + ",\"has_partial\":" + (hp ? "true" : "false") + "}");
            }
            // Build orders list
            var ol = new List<string>();
            foreach (var order in PendingOrders)
            {
                var sid3 = ResolveSid(order.Id.ToString(), order.Comment).Replace("\"", "'");
                var s2 = ResolveLoadedSymbol(order.SymbolName); double lotsVal2 = (s2 != null) ? s2.VolumeInUnitsToQuantity(order.VolumeInUnits) : (order.VolumeInUnits / 100000.0);
                double pnlTp = 0, pnlSl = 0; if (s2 != null) { if (order.TakeProfit.HasValue) { double pp = Math.Abs(order.TargetPrice - order.TakeProfit.Value) / s2.PipSize; pnlTp = EstimatePnlFromPips(s2, pp, order.VolumeInUnits); } if (order.StopLoss.HasValue) { double pp = Math.Abs(order.TargetPrice - order.StopLoss.Value) / s2.PipSize; pnlSl = -EstimatePnlFromPips(s2, pp, order.VolumeInUnits); } }
                var syncSourceOrder = ResolveSyncedTradeSource(order.Label, order.Comment);
                ol.Add("{\"sid\":\"" + sid3 + "\",\"comment\":\"" + EscapeJson(order.Comment) + "\",\"source\":\"" + EscapeJson(syncSourceOrder) + "\",\"ticket\":\"" + order.Id + "\",\"symbol\":\"" + order.SymbolName + "\",\"side\":\"" + order.TradeType.ToString().ToUpper() + "\",\"type\":\"" + order.OrderType.ToString().ToUpper() + "\",\"target_price\":" + order.TargetPrice.ToString("F5", CultureInfo.InvariantCulture) + ",\"entry\":" + order.TargetPrice.ToString("F5", CultureInfo.InvariantCulture) + ",\"sl\":" + (order.StopLoss ?? 0).ToString("F5", CultureInfo.InvariantCulture) + ",\"tp\":" + (order.TakeProfit ?? 0).ToString("F5", CultureInfo.InvariantCulture) + ",\"volume\":" + (double.IsNaN(order.VolumeInUnits) ? 0 : order.VolumeInUnits).ToString("F2", CultureInfo.InvariantCulture) + ",\"lots\":" + (double.IsNaN(lotsVal2) ? 0 : lotsVal2).ToString("F2", CultureInfo.InvariantCulture) + ",\"label\":\"" + order.Label + "\",\"status\":\"PENDING\",\"margin\":0.0,\"pnl_tp\":" + pnlTp.ToString("F2", CultureInfo.InvariantCulture) + ",\"pnl_sl\":" + pnlSl.ToString("F2", CultureInfo.InvariantCulture) + "}");
            }
            // Build closed list
            var cl = new List<string>();
            var lim = DateTime.UtcNow.AddDays(-2);
            var hd = History
                .Where(deal => deal.ClosingTime >= lim)
                .OrderByDescending(deal => deal.ClosingTime)
                .Take(20)
                .ToList();
            foreach (var deal in hd) { if (_syncedClosedTickets.Contains(deal.PositionId.ToString())) continue; var sid2 = ResolveSid(deal.PositionId.ToString(), deal.Comment).Replace("\"", "'"); var syncSourceClosed = ResolveSyncedTradeSource(deal.Label, deal.Comment); cl.Add("{\"sid\":\"" + sid2 + "\",\"comment\":\"" + EscapeJson(deal.Comment) + "\",\"source\":\"" + EscapeJson(syncSourceClosed) + "\",\"ticket\":\"" + deal.PositionId + "\",\"symbol\":\"" + deal.SymbolName + "\",\"side\":\"" + deal.TradeType.ToString().ToUpper() + "\",\"volume\":" + (double.IsNaN(deal.VolumeInUnits) ? 0 : deal.VolumeInUnits).ToString("F2", CultureInfo.InvariantCulture) + ",\"pnl\":" + (double.IsNaN(deal.NetProfit) ? 0 : deal.NetProfit).ToString("F2", CultureInfo.InvariantCulture) + ",\"pips\":0.0,\"commission\":" + (double.IsNaN(deal.Commissions) ? 0 : deal.Commissions).ToString("F2", CultureInfo.InvariantCulture) + ",\"swap\":" + (double.IsNaN(deal.Swap) ? 0 : deal.Swap).ToString("F2", CultureInfo.InvariantCulture) + ",\"status\":\"CLOSED\",\"close_reason\":\"MANUAL_CLOSE\",\"closed_at\":\"" + deal.ClosingTime.ToString("O") + "\",\"label\":\"" + deal.Label + "\"}"); }
            // Build metrics
            var ml = new List<string>();
            var ssm = new HashSet<string>();
            foreach (var activeSymbol in GetActiveSymbols())
                if (!string.IsNullOrWhiteSpace(activeSymbol)) ssm.Add(activeSymbol);
            foreach (var sn in ssm.Take(100))
            {
                var s3 = ResolveLoadedSymbol(sn);
                if (s3 == null) continue;
                ml.Add("{\"symbol\":\"" + s3.Name + "\",\"pip_value\":" + (double.IsNaN(s3.PipValue) ? 0 : s3.PipValue).ToString("F5", CultureInfo.InvariantCulture) + ",\"spread\":" + (double.IsNaN(s3.Spread) ? 0 : s3.Spread).ToString("F2", CultureInfo.InvariantCulture) + ",\"min_vol\":" + (double.IsNaN(s3.VolumeInUnitsMin) ? 0 : s3.VolumeInUnitsMin).ToString("F2", CultureInfo.InvariantCulture) + ",\"step_vol\":" + (double.IsNaN(s3.VolumeInUnitsStep) ? 0 : s3.VolumeInUnitsStep).ToString("F2", CultureInfo.InvariantCulture) + ",\"pip_size\":" + (double.IsNaN(s3.PipSize) ? 0 : s3.PipSize).ToString("F8", CultureInfo.InvariantCulture) + ",\"min_stop_pips\":" + MinStopPips.ToString("F2", CultureInfo.InvariantCulture) + ",\"min_stop_price_distance\":" + ((double.IsNaN(s3.PipSize) ? 0 : s3.PipSize) * MinStopPips).ToString("F8", CultureInfo.InvariantCulture) + ",\"digits\":" + s3.Digits + "}");
            }
            var syncSymbols = GetActiveSymbols();
            var includePrices = ShouldPushPricesNow(DateTime.Now);
            var priceData = includePrices ? ReadPricesOnMainThread(syncSymbols) : new List<Tuple<string, double, double>>();
            if (includePrices && priceData.Count == 0)
            {
                _priceStatus = "IDLE";
                _lastPriceErr = "No prices available";
            }
            var queueActionsJson = BuildStrategyQueueActionsSyncJson();
            var queueTerminalKeys = _strategyQueueTerminalUpdates.Keys.ToList();
            var queueSnapshotComplete = _strategyQueueHydratedFromServer;
            // Dispatch
            _syncOnly = false;
            Task.Run(async () =>
            {
                try
                {
                    double b, e, m;
                    if (!double.TryParse(bal, NumberStyles.Any, CultureInfo.InvariantCulture, out b)) b = 0;
                    if (!double.TryParse(eq, NumberStyles.Any, CultureInfo.InvariantCulture, out e)) e = 0;
                    if (!double.TryParse(mar, NumberStyles.Any, CultureInfo.InvariantCulture, out m)) m = 0;
                    await SyncWithVpsAsync(accId, b, e, m, brk, pl, ol, cl, ati, ml, priceData, syncSymbols, queueActionsJson, queueTerminalKeys, queueSnapshotComplete);
                }
                catch (Exception ex) { _lastSyncErr = FormatServerErrorForPanel(ex.Message); _syncStatus = "ERROR"; }
                finally { _busySync = false; RefreshDebugPanel(); }
            });
        }

        private async Task PollSignalsAsync(string accountId)
        {
            if (ShouldUseLocalRuntime())
            {
                await PollSignalsLocalAsync(accountId);
                return;
            }
            _pollCount++;
            _pollStatus = "POLLING";
            HttpRequestMessage request = null;
            var startedAt = DateTime.Now;
            try
            {
                var url = BuildServerApiUrl("broker/pull") + "?account_id=" + accountId
                    + "&source_id=" + Uri.EscapeDataString(GetBridgeSourceId(accountId))
                    + "&client_id=" + Uri.EscapeDataString(accountId)
                    + "&platform=ctrader&max_items=50";
                using (request = new HttpRequestMessage(System.Net.Http.HttpMethod.Get, url))
                {
                    request.Headers.Add("x-api-key", EaApiKey);
                    var response = await SendWithTimeoutAsync(
                        request,
                        PollTimeoutSeconds
                    );

                    _serverStatus = (int)response.StatusCode < 500 ? "OK" : "SERVER_ERR";

                    if (response.IsSuccessStatusCode)
                    {
                        _lastPollLatencyMs = Math.Max(0, (long)(DateTime.Now - startedAt).TotalMilliseconds);
                        _pollConsecutiveFailures = 0;
                        MarkApiReachable();
                        _apiStatus = "OK";
                        _successPolls++;
                        _lastPollTime = DateTime.Now;
                        _pollStatus = "OK";
                        _lastPollErr = "None";

                        // Reset error counter on successful poll
                        if (_consecutiveErrors > 0)
                        {
                            ResetTransientErrorTracking("[Recovery] Error counter reset after successful poll");
                        }

                        var json = await response.Content.ReadAsStringAsync();
                        RunOnMainThread(() => ProcessResponse(json));
                    }
                    else
                    {
                        _lastPollLatencyMs = Math.Max(0, (long)(DateTime.Now - startedAt).TotalMilliseconds);
                        _pollConsecutiveFailures++;
                        _apiStatus = (response.StatusCode == HttpStatusCode.Unauthorized || response.StatusCode == HttpStatusCode.Forbidden) ? "KEY_INVALID" : "ERR_" + (int)response.StatusCode;
                        _pollStatus = "FAIL";
                        _lastPollErr = await response.Content.ReadAsStringAsync();
                        if (string.IsNullOrEmpty(_lastPollErr)) _lastPollErr = "HTTP " + (int)response.StatusCode;

                        // Increment error counter for non-successful responses
                        _consecutiveErrors++;
                        SafePrint("[Error] Poll failed: {0} (consecutive errors: {1})", _lastPollErr, _consecutiveErrors);
                    }
                }
            }
            catch (Exception ex)
            {
                _lastPollLatencyMs = Math.Max(0, (long)(DateTime.Now - startedAt).TotalMilliseconds);
                _pollConsecutiveFailures++;
                MarkApiOfflineCooldown();
                _pollStatus = "ERROR";
                _lastPollErr = ex.Message;

                // Increment error counter for exceptions
                _consecutiveErrors++;
                if (ShouldEmitTransientErrorLog())
                {
                    SafePrint("[Error] Poll exception: {0} (consecutive errors: {1})", ex.Message, _consecutiveErrors);
                    LogHttpExceptionDetail("poll", accountId, request, PollTimeoutSeconds, ex);
                }
            }
            finally
            {
                RefreshDebugPanel();
            }
        }

        private async Task PollSignalsLocalAsync(string accountId)
        {
            _pollCount++;
            _pollStatus = "LOCAL";
            try
            {
                var json = await RunLocalRuntimeAsync(new Dictionary<string, object>
                {
                    { "operation", "pull" },
                    { "project_root", GetBaseServerRootPath() },
                    { "user_id", LocalRuntimeUserId() },
                    { "account_id", accountId },
                    { "max_items", 50 },
                });
                _apiStatus = "LOCAL";
                _serverStatus = "LOCAL";
                _pollStatus = "OK";
                _lastPollErr = "None";
                _successPolls++;
                RunOnMainThread(() => ProcessResponse(json));
            }
            catch (Exception ex)
            {
                _pollStatus = "LOCAL_ERR";
                _lastPollErr = FormatServerErrorForPanel(ex.Message);
                SafePrint("[LocalPull] ERROR: {0}", _lastPollErr);
            }
            finally
            {
                RefreshDebugPanel();
            }
        }

        private string GetBalancedJsonArrayBody(string json, string key)
        {
            return CTraderTransportEngine.GetBalancedJsonArrayBody(json, key);
        }

        private void ProcessResponse(string json)
        {
            ResetPollCycle(0);
            if (string.IsNullOrEmpty(json) || !json.Contains("\"items\"")) return;
            ProcessServerQueueActions(json);
            var pullSummaryJson = GetJsonObject(json, "pull_summary");
            if (!string.IsNullOrEmpty(pullSummaryJson))
            {
                _lastPullServerTradeCount = GetJsonInt(pullSummaryJson, "trades");
                _lastPullServerSymbolCount = GetJsonInt(pullSummaryJson, "symbols");
                _lastPullServerStrategyCount = GetJsonInt(pullSummaryJson, "strategies");
            }

            var watchlistSymbols = GetJsonStringArray(json, "watchlist_symbols");
            _lastWatchlistSymbolCount = watchlistSymbols.Count;
            _lastWatchlistSymbolsText = watchlistSymbols.Count > 0 ? string.Join(",", watchlistSymbols.Take(12)) : "None";

            var requestedSymbols = GetJsonStringArray(json, "symbols");
            if (requestedSymbols.Count > 0)
            {
                ApplyTrackedSymbolsFromServer(requestedSymbols);
                if (_lastPullServerSymbolCount <= 0) _lastPullServerSymbolCount = requestedSymbols.Count;
            }
            var itemsBody = GetBalancedJsonArrayBody(json, "items");
            if (string.IsNullOrWhiteSpace(itemsBody)) return;
            // Balanced bracket parser — handles nested JSON in metadata
            var objects = new List<string>();
            int depth = 0, start = -1;
            for (int i = 0; i < itemsBody.Length; i++)
            {
                if (itemsBody[i] == '{')
                {
                    if (depth == 0) start = i;
                    depth++;
                }
                else if (itemsBody[i] == '}')
                {
                    depth--;
                    if (depth == 0 && start >= 0)
                    {
                        objects.Add(itemsBody.Substring(start, i - start + 1));
                        start = -1;
                    }
                }
            }
            _lastPollSummary.Read = objects.Count;
            if (_lastPullServerTradeCount <= 0) _lastPullServerTradeCount = objects.Count;
            foreach (var obj in objects) ExecuteSignal(obj);
        }

        private void ExecuteSignal(string json)
        {
            var id = GetJsonValue(json, "sid");
            if (string.IsNullOrEmpty(id)) id = GetJsonValue(json, "signal_id");
            var leaseToken = GetJsonValue(json, "lease_token");
            var taskType = GetJsonValue(json, "type").ToUpper();
            if (string.IsNullOrEmpty(taskType)) taskType = "OPEN";
            var action = GetJsonValue(json, "action").ToUpper();
            var symbolCode = GetJsonValue(json, "symbol").ToUpper();
            var ticketStr = GetJsonValue(json, "ticket");
            long ticketNum = 0;
            if (!string.IsNullOrEmpty(ticketStr)) long.TryParse(ticketStr, out ticketNum);

            if (string.IsNullOrEmpty(id)) return;

            // Dedup by lease: skip if this exact (sid, lease_token) already processed
            var leaseKey = BuildLeaseKey(id, leaseToken);
            if (!string.IsNullOrEmpty(leaseToken) && _processedLeases.Contains(leaseKey)) return;
            if (!string.IsNullOrEmpty(leaseToken)) _processedLeases.Add(leaseKey);

            SafePrint("[Debug] Task Received: type={0} action={1} symbol={2} ticket={3} (ID: {4})", taskType, action, symbolCode, ticketNum, id);

            BeginInvokeOnMainThread(() =>
            {
                try
                {
                    var symbol = ResolveLoadedSymbol(symbolCode);

                    if (symbol == null)
                    {
                        var msg = "Symbol not found: " + symbolCode;
                        RecordPollEvent("", id, symbolCode, action, "REJECTED_SYMBOL", msg, "error");
                        SafeAck(id, leaseToken, "REJECTED", "", msg);
                        return;
                    }

                    symbolCode = symbol.Name;

                    // Shared variables for all task types
                    var sl = ParseDouble(GetJsonValue(json, "sl"));
                    var tp = ParseDouble(GetJsonValue(json, "tp"));
                    if (tp <= 0) tp = ParseDouble(GetJsonValue(json, "tp1"));

                // --- CANCEL: close position or delete order ---
                if (taskType == "CANCEL")
                {
                    if (ticketNum > 0)
                    {
                        // Try position close first (open positions)
                        var pos = Positions.FirstOrDefault(p => p.Id == ticketNum);
                        if (pos != null)
                        {
                            var cRes = ClosePosition(pos);
                            if (cRes.IsSuccessful)
                            {
                                RecordPollEvent(ticketStr, id, symbolCode, action, "CANCELLED_POSITION", "cancel_close_ok", "closed");
                                SafeAck(id, leaseToken, "CANCELLED", ticketStr, "cancel_close_ok");
                            }
                            else
                            {
                                RecordPollEvent(ticketStr, id, symbolCode, action, "CANCEL_CLOSE_FAILED", cRes.Error.ToString(), "error");
                                SafeAck(id, leaseToken, "ERROR", ticketStr, "cancel_close_fail: " + cRes.Error);
                            }
                        }
                        else
                        {
                            // Try order cancel (pending orders)
                            var ord = PendingOrders.FirstOrDefault(o => o.Id == ticketNum);
                            if (ord != null)
                            {
                                var oRes = CancelPendingOrder(ord);
                                if (oRes.IsSuccessful)
                                {
                                    RecordPollEvent(ticketStr, id, symbolCode, action, "CANCELLED_ORDER", "cancel_order_ok", "closed");
                                    SafeAck(id, leaseToken, "CANCELLED", ticketStr, "cancel_order_ok");
                                }
                                else
                                {
                                    RecordPollEvent(ticketStr, id, symbolCode, action, "CANCEL_ORDER_FAILED", oRes.Error.ToString(), "error");
                                    SafeAck(id, leaseToken, "ERROR", ticketStr, "cancel_order_fail: " + oRes.Error);
                                }
                            }
                            else
                            {
                                // Ticket not found as position or order — close by comment/label fallback
                                var targets = Positions.Where(p => p.SymbolName == symbolCode && (CommentMatchesSid(p.Comment, id) || p.Label == MagicNumber.ToString())).ToList();
                                int successfulPositionCancels = 0;
                                foreach (var p in targets)
                                {
                                    var pRes = ClosePosition(p);
                                    if (pRes.IsSuccessful) successfulPositionCancels++;
                                    else SafePrint("[Error] Cancel close failed: {0}", pRes.Error);
                                }
                                var ordTargets = PendingOrders.Where(o => o.SymbolName == symbolCode && (CommentMatchesSid(o.Comment, id) || o.Label == MagicNumber.ToString())).ToList();
                                int successfulOrderCancels = 0;
                                foreach (var o in ordTargets)
                                {
                                    var oRes = CancelPendingOrder(o);
                                    if (oRes.IsSuccessful) successfulOrderCancels++;
                                    else SafePrint("[Error] Cancel order failed: {0}", oRes.Error);
                                }
                                int totalCancelled = successfulPositionCancels + successfulOrderCancels;
                                if (totalCancelled > 0)
                                {
                                    RecordPollEvent(ticketStr, id, symbolCode, action, "CANCELLED_MATCHED_ITEMS", "matched=" + totalCancelled.ToString(CultureInfo.InvariantCulture), "closed");
                                    SafeAck(id, leaseToken, "CANCELLED", ticketStr, "cancel_ok");
                                }
                                else
                                {
                                    RecordPollEvent(ticketStr, id, symbolCode, action, "CANCEL_MATCHED_ITEMS_FAILED", "matched=0", "error");
                                    SafeAck(id, leaseToken, "ERROR", ticketStr, "cancel_no_ticket");
                                }
                            }
                        }
                    }
                    else
                    {
                        // No ticket — close by comment/label fallback
                        var targets = Positions.Where(p => p.SymbolName == symbolCode && (CommentMatchesSid(p.Comment, id) || p.Label == MagicNumber.ToString())).ToList();
                        int successfulPositionCancels = 0;
                        foreach (var p in targets)
                        {
                            var pRes = ClosePosition(p);
                            if (pRes.IsSuccessful) successfulPositionCancels++;
                            else SafePrint("[Error] Cancel close failed: {0}", pRes.Error);
                        }
                        var ordTargets = PendingOrders.Where(o => o.SymbolName == symbolCode && (CommentMatchesSid(o.Comment, id) || o.Label == MagicNumber.ToString())).ToList();
                        int successfulOrderCancels = 0;
                        foreach (var o in ordTargets)
                        {
                            var oRes = CancelPendingOrder(o);
                            if (oRes.IsSuccessful) successfulOrderCancels++;
                            else SafePrint("[Error] Cancel order failed: {0}", oRes.Error);
                        }
                        int totalCancelled = successfulPositionCancels + successfulOrderCancels;
                        if (totalCancelled > 0)
                        {
                            RecordPollEvent(ticketStr, id, symbolCode, action, "CANCELLED_MATCHED_ITEMS", "matched=" + totalCancelled.ToString(CultureInfo.InvariantCulture), "closed");
                            SafeAck(id, leaseToken, "CANCELLED", ticketStr, "cancel_ok");
                        }
                        else
                        {
                            RecordPollEvent(ticketStr, id, symbolCode, action, "CANCEL_MATCHED_ITEMS_FAILED", "matched=0", "error");
                            SafeAck(id, leaseToken, "ERROR", ticketStr, "cancel_no_pos");
                        }
                    }
                    return;
                }

                // --- CLOSE: close positions by comment/label ---
                if (taskType == "CLOSE")
                {
                    if (ticketNum > 0)
                    {
                        var pos = Positions.FirstOrDefault(p => p.Id == ticketNum);
                        if (pos != null)
                        {
                            var cRes = ClosePosition(pos);
                            if (cRes.IsSuccessful)
                            {
                                RecordPollEvent(ticketStr, id, symbolCode, action, "CLOSED_POSITION", "close_ok", "closed");
                                SafeAck(id, leaseToken, "CLOSED", ticketStr, "close_ok");
                            }
                            else
                            {
                                RecordPollEvent(ticketStr, id, symbolCode, action, "CLOSE_FAILED", cRes.Error.ToString(), "error");
                                SafeAck(id, leaseToken, "ERROR", ticketStr, "close_fail: " + cRes.Error);
                            }
                            return;
                        }
                    }
                    var targets = Positions.Where(p => p.SymbolName == symbolCode && (CommentMatchesSid(p.Comment, id) || p.Label == MagicNumber.ToString())).ToList();
                    int successfulCloses = 0;
                    foreach (var p in targets)
                    {
                        var cRes = ClosePosition(p);
                        if (cRes.IsSuccessful) successfulCloses++;
                        else SafePrint("[Error] Close failed: {0}", cRes.Error);
                    }
                    if (successfulCloses > 0)
                    {
                        RecordPollEvent(ticketStr, id, symbolCode, action, "CLOSED_MATCHED_ITEMS", "matched=" + successfulCloses.ToString(CultureInfo.InvariantCulture), "closed");
                        SafeAck(id, leaseToken, "CLOSED", ticketStr, "close_ok");
                    }
                    else
                    {
                        RecordPollEvent(ticketStr, id, symbolCode, action, "CLOSE_MATCHED_ITEMS_FAILED", "matched=0", "error");
                        SafeAck(id, leaseToken, "ERROR", ticketStr, "close_no_pos");
                    }
                    return;
                }

                // --- MODIFY: update SL/TP on position or order ---
                if (taskType == "MODIFY")
                {
                    if (ticketNum > 0)
                    {
                        var pos = Positions.FirstOrDefault(p => p.Id == ticketNum);
                        if (pos != null)
                        {
                            var modifyProfile = GetJsonValue(json, "profile");
                            var modifyTf = GetJsonValue(json, "trade_tf");
                            if (string.IsNullOrWhiteSpace(modifyTf)) modifyTf = GetJsonValue(json, "chart_tf");
                            if (string.IsNullOrWhiteSpace(modifyTf)) modifyTf = GetJsonValue(json, "tf");
                            var modifyRiskMultiplier = GetTradeProfileRiskMultiplier(modifyProfile, modifyTf);
                            var modifyEffectiveMaxRiskPercent = GetEffectiveMaxRiskPercent();
                            var modifyFinalRiskMoney = modifyEffectiveMaxRiskPercent > 0
                                ? Account.Balance * (modifyEffectiveMaxRiskPercent / 100.0) * Math.Max(0.0, modifyRiskMultiplier)
                                : 0;
                            var nextSl = sl > 0 ? sl : (pos.StopLoss.HasValue ? pos.StopLoss.Value : 0);
                            var nextTp = tp > 0 ? tp : (pos.TakeProfit.HasValue ? pos.TakeProfit.Value : 0);
                            if (nextSl <= 0)
                            {
                                var rejectMsg = "modify_missing_stop_loss";
                                RecordPollEvent(ticketStr, id, symbolCode, action, "UPDATE_REJECTED", rejectMsg, "error");
                                SafeAck(id, leaseToken, "REJECTED", ticketStr, rejectMsg);
                                return;
                            }
                            string modifyProtectionReason;
                            if (!TryValidateProtectionPrices(symbol, action, pos.EntryPrice, nextSl, nextTp, out modifyProtectionReason))
                            {
                                var rejectMsg = "modify_protection_rejected: " + modifyProtectionReason;
                                RecordPollEvent(ticketStr, id, symbolCode, action, "UPDATE_REJECTED", rejectMsg, "error");
                                SafeAck(id, leaseToken, "REJECTED", ticketStr, rejectMsg);
                                return;
                            }
                            string modifyRiskRejectReason;
                            if (!TryPassRiskFirewall(
                                symbol,
                                action,
                                "market",
                                pos.EntryPrice,
                                pos.EntryPrice,
                                nextSl,
                                nextTp,
                                pos.VolumeInUnits,
                                modifyFinalRiskMoney,
                                modifyFinalRiskMoney,
                                false,
                                out modifyRiskRejectReason))
                            {
                                var rejectMsg = "modify_risk_gate_rejected: " + modifyRiskRejectReason;
                                RecordPollEvent(ticketStr, id, symbolCode, action, "UPDATE_REJECTED", rejectMsg, "error");
                                SafeAck(id, leaseToken, "REJECTED", ticketStr, rejectMsg);
                                return;
                            }
                            var mRes = ModifyPositionCompat(pos, nextSl, nextTp > 0 ? (double?)nextTp : (double?)null);
                            if (mRes.IsSuccessful)
                            {
                                RecordPollEvent(ticketStr, id, symbolCode, action, "UPDATED_POSITION", "sl_tp_modified", "changed");
                                SafeAck(id, leaseToken, "FILLED", ticketStr, "");
                            }
                            else
                            {
                                RecordPollEvent(ticketStr, id, symbolCode, action, "UPDATE_FAILED", mRes.Error.ToString(), "error");
                                SafeAck(id, leaseToken, "ERROR", ticketStr, "modify_fail: " + mRes.Error);
                            }
                            return;
                        }
                        var ord = PendingOrders.FirstOrDefault(o => o.Id == ticketNum);
                        if (ord != null)
                        {
                            double requestedModifyLots = ParseDouble(GetJsonValue(json, "lots"));
                            if (requestedModifyLots <= 0) requestedModifyLots = ParseDouble(GetJsonValue(json, "volume"));
                            double requestedTargetPrice = ParseDouble(GetJsonValue(json, "price"));
                            if (requestedTargetPrice <= 0) requestedTargetPrice = ParseDouble(GetJsonValue(json, "entry"));
                            double currentLots = symbol.VolumeInUnitsToQuantity(ord.VolumeInUnits);
                            bool wantsVolumeChange = requestedModifyLots > 0 && Math.Abs(requestedModifyLots - currentLots) > 0.0001;
                            double nextTargetPrice = requestedTargetPrice > 0 ? requestedTargetPrice : ord.TargetPrice;
                            var modifyProfile = GetJsonValue(json, "profile");
                            var modifyTf = GetJsonValue(json, "trade_tf");
                            if (string.IsNullOrWhiteSpace(modifyTf)) modifyTf = GetJsonValue(json, "chart_tf");
                            if (string.IsNullOrWhiteSpace(modifyTf)) modifyTf = GetJsonValue(json, "tf");
                            var modifyRiskMultiplier = GetTradeProfileRiskMultiplier(modifyProfile, modifyTf);
                            var modifyEffectiveMaxRiskPercent = GetEffectiveMaxRiskPercent();
                            var modifyFinalRiskMoney = modifyEffectiveMaxRiskPercent > 0
                                ? Account.Balance * (modifyEffectiveMaxRiskPercent / 100.0) * Math.Max(0.0, modifyRiskMultiplier)
                                : 0;
                            var nextSl = sl > 0 ? sl : (ord.StopLoss.HasValue ? ord.StopLoss.Value : 0);
                            var nextTp = tp > 0 ? tp : (ord.TakeProfit.HasValue ? ord.TakeProfit.Value : 0);
                            if (nextSl <= 0)
                            {
                                RecordPollEvent(ticketStr, id, symbolCode, action, "UPDATE_REJECTED", "modify_missing_stop_loss", "error");
                                SafeAck(id, leaseToken, "REJECTED", ticketStr, "modify_missing_stop_loss");
                                return;
                            }

                            if (wantsVolumeChange)
                            {
                                double newVolumeUnits = symbol.QuantityToVolumeInUnits(requestedModifyLots);
                                newVolumeUnits = symbol.NormalizeVolumeInUnits(newVolumeUnits, RoundingMode.Down);
                                if (newVolumeUnits < symbol.VolumeInUnitsMin)
                                {
                                    RecordPollEvent(ticketStr, id, symbolCode, action, "UPDATE_REJECTED", "modify_volume_too_small", "error");
                                    SafeAck(id, leaseToken, "ERROR", ticketStr, "modify_volume_too_small");
                                    return;
                                }

                                var modifyExecutionPrice = nextTargetPrice > 0 ? nextTargetPrice : ord.TargetPrice;

                                double modifyApprovedVolumeUnits;
                                double modifyApprovedRiskMoney;
                                double modifyApprovedMarginEstimate;
                                double modifyApprovedMarginBudget;
                                double modifyApprovedSl;
                                double modifyApprovedTp;
                                string modifyGateRejectReason;
                                if (!TryPassSharedCreationGate(
                                    symbol,
                                    action,
                                    ord.OrderType == PendingOrderType.Limit ? "limit" : "stop",
                                    modifyExecutionPrice,
                                    modifyExecutionPrice,
                                    nextSl,
                                    nextTp,
                                    newVolumeUnits,
                                    modifyFinalRiskMoney,
                                    modifyFinalRiskMoney,
                                    out modifyApprovedSl,
                                    out modifyApprovedTp,
                                    out modifyApprovedVolumeUnits,
                                    out modifyApprovedRiskMoney,
                                    out modifyApprovedMarginEstimate,
                                    out modifyApprovedMarginBudget,
                                    out modifyGateRejectReason))
                                {
                                    RecordPollEvent(ticketStr, id, symbolCode, action, "UPDATE_REJECTED", "modify_gate_rejected: " + modifyGateRejectReason, "error");
                                    SafeAck(id, leaseToken, "REJECTED", ticketStr, "modify_gate_rejected: " + modifyGateRejectReason);
                                    return;
                                }
                                newVolumeUnits = modifyApprovedVolumeUnits;
                                nextSl = modifyApprovedSl;
                                nextTp = modifyApprovedTp;

                                var cancelRes = CancelPendingOrder(ord);
                                if (!cancelRes.IsSuccessful)
                                {
                                    RecordPollEvent(ticketStr, id, symbolCode, action, "UPDATE_FAILED", "modify_cancel_fail: " + cancelRes.Error, "error");
                                    SafeAck(id, leaseToken, "ERROR", ticketStr, "modify_cancel_fail: " + cancelRes.Error);
                                    return;
                                }

                                TradeResult replaceRes = null;
                                var replacementBrokerComment = BuildBrokerComment(id);
                                if (ord.OrderType == PendingOrderType.Limit)
                                {
                                    replaceRes = PlaceLimitOrder(
                                        ord.TradeType,
                                        symbol.Name,
                                        newVolumeUnits,
                                        nextTargetPrice,
                                        ord.Label,
                                        (double?)null,
                                        (double?)null,
                                        (ProtectionType?)null,
                                        ord.ExpirationTime,
                                        replacementBrokerComment
                                    );
                                }
                                else
                                {
                                    replaceRes = PlaceStopOrder(
                                        ord.TradeType,
                                        symbol.Name,
                                        newVolumeUnits,
                                        nextTargetPrice,
                                        ord.Label,
                                        (double?)null,
                                        (double?)null,
                                        (ProtectionType?)null,
                                        ord.ExpirationTime,
                                        replacementBrokerComment
                                    );
                                }

                                if (!replaceRes.IsSuccessful || replaceRes.PendingOrder == null)
                                {
                                    RecordPollEvent(ticketStr, id, symbolCode, action, "UPDATE_FAILED", "modify_replace_fail", "error");
                                    SafeAck(id, leaseToken, "ERROR", ticketStr, "modify_replace_fail: " + (replaceRes != null ? replaceRes.Error.ToString() : "unknown"));
                                    return;
                                }

                                ord = replaceRes.PendingOrder;
                                ticketStr = ord.Id.ToString();
                                if (!string.IsNullOrWhiteSpace(ticketStr) && !string.IsNullOrWhiteSpace(id))
                                    _ticketSidMap[ticketStr] = id;
                            }
                            else
                            {
                                double modifyApprovedVolumeUnits;
                                double modifyApprovedRiskMoney;
                                double modifyApprovedMarginEstimate;
                                double modifyApprovedMarginBudget;
                                double modifyApprovedSl;
                                double modifyApprovedTp;
                                string modifyGateRejectReason;
                                if (!TryPassSharedCreationGate(
                                    symbol,
                                    action,
                                    ord.OrderType == PendingOrderType.Limit ? "limit" : "stop",
                                    nextTargetPrice,
                                    nextTargetPrice,
                                    nextSl,
                                    nextTp,
                                    ord.VolumeInUnits,
                                    modifyFinalRiskMoney,
                                    modifyFinalRiskMoney,
                                    out modifyApprovedSl,
                                    out modifyApprovedTp,
                                    out modifyApprovedVolumeUnits,
                                    out modifyApprovedRiskMoney,
                                    out modifyApprovedMarginEstimate,
                                    out modifyApprovedMarginBudget,
                                    out modifyGateRejectReason))
                                {
                                    RecordPollEvent(ticketStr, id, symbolCode, action, "UPDATE_REJECTED", "modify_gate_rejected: " + modifyGateRejectReason, "error");
                                    SafeAck(id, leaseToken, "REJECTED", ticketStr, "modify_gate_rejected: " + modifyGateRejectReason);
                                    return;
                                }
                                nextSl = modifyApprovedSl;
                                nextTp = modifyApprovedTp;
                            }

                            double? slPips = null;
                            double? tpPips = null;
                            if (nextSl > 0) slPips = Math.Round((action == "BUY" ? (nextTargetPrice - nextSl) : (nextSl - nextTargetPrice)) / symbol.PipSize, 2);
                            if (nextTp > 0) tpPips = Math.Round((action == "BUY" ? (nextTp - nextTargetPrice) : (nextTargetPrice - nextTp)) / symbol.PipSize, 2);
                            var mRes = ModifyPendingOrderCompat(ord, nextTargetPrice, slPips, tpPips, ord.ExpirationTime);
                            if (mRes.IsSuccessful)
                            {
                                RecordPollEvent(ticketStr, id, symbolCode, action, "UPDATED_ORDER", wantsVolumeChange ? "volume_and_sl_tp_modified" : "sl_tp_modified", "changed");
                                SafeAck(id, leaseToken, "PENDING", ticketStr, "");
                            }
                            else
                            {
                                RecordPollEvent(ticketStr, id, symbolCode, action, "UPDATE_FAILED", mRes.Error.ToString(), "error");
                                SafeAck(id, leaseToken, "ERROR", ticketStr, "modify_fail: " + mRes.Error);
                            }
                            return;
                        }
                    }
                    RecordPollEvent(ticketStr, id, symbolCode, action, "UPDATE_FAILED", "modify_no_ticket", "error");
                    SafeAck(id, leaseToken, "ERROR", "", "modify_no_ticket");
                    return;
                }

                // --- OPEN (default): create new position/order ---
                if (Positions.Any(p => CommentMatchesSid(p.Comment, id)))
                {
                    RecordPollEvent("ALREADY_OPEN", id, symbolCode, action, "UNCHANGED_OPEN_POSITION", "", "unchanged", false);
                    SafeAck(id, leaseToken, "FILLED", "ALREADY_OPEN", "");
                    return;
                }
                if (PendingOrders.Any(o => CommentMatchesSid(o.Comment, id)))
                {
                    RecordPollEvent("ALREADY_PLACED", id, symbolCode, action, "UNCHANGED_PENDING_ORDER", "", "unchanged", false);
                    SafeAck(id, leaseToken, "PENDING", "ALREADY_PLACED", "");
                    return;
                }

                var entry = ParseDouble(GetJsonValue(json, "entry"));
                var orderTypeStr = GetJsonValue(json, "order_type").ToLower();
                if (string.IsNullOrEmpty(orderTypeStr)) orderTypeStr = "market";
                var tradeProfile = GetJsonValue(json, "profile");
                var tradeTf = GetJsonValue(json, "trade_tf");
                if (string.IsNullOrWhiteSpace(tradeTf)) tradeTf = GetJsonValue(json, "chart_tf");
                if (string.IsNullOrWhiteSpace(tradeTf)) tradeTf = GetJsonValue(json, "tf");
                var profileRiskMultiplier = GetTradeProfileRiskMultiplier(tradeProfile, tradeTf);

                var currentPrice = (action == "BUY") ? symbol.Ask : symbol.Bid;
                var executionPrice = (orderTypeStr == "market" || entry <= 0) ? currentPrice : entry;

                string volStr = GetJsonValue(json, "risk_pct");
                if (string.IsNullOrEmpty(volStr)) volStr = GetJsonValue(json, "volume");
                double signalRiskPct = ParseDouble(volStr);

                double riskMoneyRaw = ParseDouble(GetJsonValue(json, "risk_money_planned"));
                if (riskMoneyRaw <= 0) riskMoneyRaw = ParseDouble(GetJsonValue(json, "risk_money"));
                double requestedRiskMoney = 0;

                if (riskMoneyRaw > 0)
                {
                    requestedRiskMoney = riskMoneyRaw;
                }
                else if (signalRiskPct > 0)
                {
                    requestedRiskMoney = Account.Balance * (signalRiskPct / 100.0);
                }
                else
                {
                    requestedRiskMoney = Account.Balance * (GetEffectiveMaxRiskPercent() / 100.0);
                }

                var effectiveMaxRiskPercent = GetEffectiveMaxRiskPercent();
                double maxRiskFromPct = effectiveMaxRiskPercent > 0
                    ? Account.Balance * (effectiveMaxRiskPercent / 100.0) * Math.Max(0.0, profileRiskMultiplier)
                    : 0;
                double finalRiskMoney = maxRiskFromPct > 0 ? Math.Min(requestedRiskMoney, maxRiskFromPct) : requestedRiskMoney;
                var tradeType = (action == "BUY") ? TradeType.Buy : TradeType.Sell;

                double volumeUnits = symbol.VolumeInUnitsMin;

                if (sl > 0)
                {
                    volumeUnits = ResolveVolumeUnitsForRisk(symbol, tradeType, executionPrice, sl, finalRiskMoney);
                    if (volumeUnits <= 0)
                    {
                        var msg = string.Format(
                            CultureInfo.InvariantCulture,
                            "Unable to compute risk-sized volume for {0}: entry={1:F5} sl={2:F5} risk_budget={3:F2}",
                            symbolCode,
                            executionPrice,
                            sl,
                            finalRiskMoney
                        );
                        RecordPollEvent("", id, symbolCode, action, "REJECTED_RISK_MODEL", msg, "error");
                        SafeAck(id, leaseToken, "REJECTED", "", msg);
                        return;
                    }
                }
                else
                {
                    double explicitLots = ParseDouble(GetJsonValue(json, "lots"));
                    if (explicitLots > 0)
                    {
                        volumeUnits = symbol.QuantityToVolumeInUnits(explicitLots);
                        volumeUnits = symbol.NormalizeVolumeInUnits(volumeUnits, RoundingMode.Down);
                    }
                    else volumeUnits = symbol.VolumeInUnitsMin;
                }

                if (volumeUnits < symbol.VolumeInUnitsMin)
                {
                    var msg = "Volume too small: " + volumeUnits;
                    RecordPollEvent("", id, symbolCode, action, "REJECTED_VOLUME", msg, "error");
                    SafeAck(id, leaseToken, "REJECTED", "", msg);
                    return;
                }

                // EXTRACT PARTIAL TPs — read tp_targets first, then fallback to raw_json.partial_tps
                var partials = new List<PartialTP>();

                // 1. Try tp_targets array from POLL response (preferred)
                var tpMatch = Regex.Match(json, "\"tp_targets\"\\s*:\\s*\\[([^\\]]*)\\]");
                if (tpMatch.Success)
                {
                    var tpVals = tpMatch.Groups[1].Value;
                    var tpPrices = Regex.Matches(tpVals, @"[\d]+\.?[\d]*");
                    var prices = new List<double>();
                    foreach (Match m in tpPrices)
                    {
                        var px = ParseDouble(m.Value);
                        if (px > 0) prices.Add(px);
                    }
                    if (prices.Count > 0)
                    {
                        // Safety filter: keep only targets that are true take-profit levels for side.
                        // BUY: TP above entry. SELL: TP below entry.
                        var filtered = prices
                            .Where(px => action == "BUY" ? px > executionPrice : px < executionPrice)
                            .Distinct()
                            .ToList();
                        if (action == "BUY") filtered = filtered.OrderBy(px => px).ToList();
                        else filtered = filtered.OrderByDescending(px => px).ToList();

                        prices = filtered;
                    }
                    if (prices.Count > 0)
                    {
                        double[] splits;
                        if (prices.Count >= 3) splits = new double[] { 50, 30, 20 };
                        else if (prices.Count == 2) splits = new double[] { 60, 40 };
                        else splits = new double[] { 100 };

                        for (int i = 0; i < prices.Count && i < splits.Length; i++)
                        {
                            partials.Add(new PartialTP { Price = prices[i], SizePct = splits[i] });
                        }
                    }
                }

                // 2. Fallback: raw_json.partial_tps (legacy)
                if (partials.Count == 0)
                {
                    var rawJson = GetJsonValue(json, "raw_json");
                    if (!string.IsNullOrEmpty(rawJson))
                    {
                        var pMatch = Regex.Match(rawJson, "\"partial_tps\"\\s*:\\s*\\[(.*?)\\]", RegexOptions.Singleline);
                        if (pMatch.Success)
                        {
                            var items = Regex.Matches(pMatch.Groups[1].Value, "\\{(.*?)\\}", RegexOptions.Singleline);
                            foreach (Match m in items)
                            {
                                var it = "{" + m.Groups[1].Value + "}";
                                var pPrice = ParseDouble(GetJsonValue(it, "price"));
                                var pPct = ParseDouble(GetJsonValue(it, "size_pct"));
                                if (pPrice > 0 && pPct > 0) partials.Add(new PartialTP { Price = pPrice, SizePct = pPct });
                            }
                        }
                    }
                }

                if (partials.Count > 0) _tradePartials[id] = partials;

                var strategyLabel = GetJsonValue(json, "strategy");
                var sourceLabel = NormalizeTradeSource(GetJsonValue(json, "source"), "");
                var entryModelLabel = GetJsonValue(json, "entry_model");
                if (string.IsNullOrWhiteSpace(entryModelLabel)) entryModelLabel = GetJsonValue(json, "entryModel");
                var label = !string.IsNullOrWhiteSpace(sourceLabel)
                    ? sourceLabel
                    : BuildBrokerLabel(strategyLabel, entryModelLabel, tradeProfile, tradeTf);
                var brokerComment = BuildBrokerComment(id, !string.IsNullOrWhiteSpace(sourceLabel) ? sourceLabel : strategyLabel, executionPrice, tp, sl);
                TradeResult res = null;
                var requestedSl = sl;
                var requestedTp = tp;
                var requestedVolumeUnits = volumeUnits;
                var fittedMarginEstimate = 0.0;
                var fittedMarginBudget = 0.0;
                var fittedMarginNote = "";

                if (executionPrice <= 0)
                {
                    var msg = "Invalid execution price: " + executionPrice;
                    RecordPollEvent("", id, symbolCode, action, "REJECTED_PRICE", msg, "error");
                    SafeAck(id, leaseToken, "REJECTED", "", msg);
                    SafePrint("[Error] Cannot execute {0} {1}: Ask/Bid price is 0. Check connection.", action, symbolCode);
                    return;
                }

                var tradableRejectReason = DetectSymbolTradeAvailabilityReason(symbol);
                if (!string.IsNullOrWhiteSpace(tradableRejectReason))
                {
                    var rejectMsg = tradableRejectReason + " | " + BuildSubmitContext(
                        symbol,
                        action,
                        orderTypeStr,
                        entry,
                        executionPrice,
                        sl,
                        tp,
                        volumeUnits,
                        requestedRiskMoney,
                        finalRiskMoney
                    );
                    LogValidationBlock(rejectMsg);
                    RecordPollEvent("", id, symbolCode, action, "REJECTED_MARKET_STATE", rejectMsg, "warning");
                    SafeAck(id, leaseToken, "REJECTED", "", rejectMsg);
                    return;
                }

                SafePrint("[Debug] Executing {0} {1} at {2}. SL: {3}, TP: {4}, Vol: {5}", action, symbolCode, executionPrice, sl, tp, volumeUnits);

                // Pre-check: reject if SL/TP are too close to entry (broker will reject anyway)
                if (symbol.PipSize > 0)
                {
                    if (sl > 0)
                    {
                        double slDistPips = Math.Abs(executionPrice - sl) / symbol.PipSize;
                        if (slDistPips < MinStopPips)
                        {
                            var adj = String.Equals(OnSlTpError, "Adjust", StringComparison.OrdinalIgnoreCase);
                            if (adj)
                            {
                                var reqSl = action == "SELL" ? executionPrice + MinStopPips * symbol.PipSize : executionPrice - MinStopPips * symbol.PipSize;
                                var reqPips = Math.Abs(reqSl - executionPrice) / symbol.PipSize;
                                var newVolume = volumeUnits;
                                // Cap volume to respect MaxRisk settings after SL adjustment
                                if (effectiveMaxRiskPercent > 0)
                                {
                                    var allowedRiskMoney = Account.Equity * effectiveMaxRiskPercent / 100;
                                    var riskAtCurrentVolume = EstimateRiskAmount(symbol, action == "BUY" ? TradeType.Buy : TradeType.Sell, executionPrice, reqSl, volumeUnits);
                                    if (riskAtCurrentVolume > allowedRiskMoney && riskAtCurrentVolume > 0)
                                    {
                                        var scaledVolume = volumeUnits * (allowedRiskMoney / riskAtCurrentVolume);
                                        if (scaledVolume < volumeUnits) newVolume = scaledVolume;
                                    }
                                }
                                newVolume = symbol.NormalizeVolumeInUnits(newVolume, RoundingMode.Down);
                                if (newVolume < symbol.VolumeInUnitsMin)
                                {
                                    var rejectMsg = string.Format("SL adjusted ({0:F0} pips) exceeds max risk — volume would be below minimum", reqPips);
                                    LogValidationBlock(rejectMsg);
                                    RecordPollEvent("", id, symbolCode, action, "REJECTED_RISK_LIMIT", rejectMsg, "warning");
                                    SafeAck(id, leaseToken, "FAIL", "", rejectMsg);
                                    return;
                                }
                                if (newVolume < volumeUnits)
                                    SafePrint("[Adjust] SL widened from {0:F5} to {1:F5} ({2:F1} → {3:F0} pips), vol reduced from {4} to {5} to respect max risk", sl, reqSl, slDistPips, reqPips, volumeUnits, newVolume);
                                else
                                    SafePrint("[Adjust] SL widened from {0:F5} to {1:F5} ({2:F1} → {3:F0} pips)", sl, reqSl, slDistPips, reqPips);
                                sl = reqSl;
                                volumeUnits = newVolume;
                            }
                            else
                            {
                                var rejectMsg = string.Format("SL too close: {0:F1} pips (min {1}). E={2:F5} SL={3:F5}", slDistPips, MinStopPips, executionPrice, sl);
                                LogValidationBlock(rejectMsg);
                                RecordPollEvent("", id, symbolCode, action, "REJECTED_SL_DISTANCE", rejectMsg, "warning");
                                SafeAck(id, leaseToken, "FAIL", "", rejectMsg);
                                return;
                            }
                        }
                    }
                    if (tp > 0)
                    {
                        double tpDistPips = Math.Abs(tp - executionPrice) / symbol.PipSize;
                        if (tpDistPips < MinStopPips)
                        {
                            var adj = String.Equals(OnSlTpError, "Adjust", StringComparison.OrdinalIgnoreCase);
                            if (adj)
                            {
                                var newTp = action == "SELL" ? executionPrice - MinStopPips * symbol.PipSize : executionPrice + MinStopPips * symbol.PipSize;
                                SafePrint("[Adjust] TP widened from {0:F5} to {1:F5} ({2:F1} pips → {3:F0} min)", tp, newTp, tpDistPips, MinStopPips);
                                tp = newTp;
                            }
                            else
                            {
                                var rejectMsg = string.Format("TP too close: {0:F1} pips (min {1}). E={2:F5} TP={3:F5}", tpDistPips, MinStopPips, executionPrice, tp);
                                LogValidationBlock(rejectMsg);
                                RecordPollEvent("", id, symbolCode, action, "REJECTED_TP_DISTANCE", rejectMsg, "warning");
                                SafeAck(id, leaseToken, "FAIL", "", rejectMsg);
                                return;
                            }
                        }
                    }
                }

                double approvedVolumeUnits;
                double approvedRiskMoney;
                double approvedSl;
                double approvedTp;
                string gateRejectReason;
                if (!TryPassSharedCreationGate(
                    symbol,
                    action,
                    orderTypeStr,
                    entry,
                    executionPrice,
                    sl,
                    tp,
                    volumeUnits,
                    requestedRiskMoney,
                    finalRiskMoney,
                    out approvedSl,
                    out approvedTp,
                    out approvedVolumeUnits,
                    out approvedRiskMoney,
                    out fittedMarginEstimate,
                    out fittedMarginBudget,
                    out gateRejectReason
                ))
                {
                    var rejectMsg = string.Format(
                        CultureInfo.InvariantCulture,
                        "VALIDATION_BLOCKED:{0} | {1}",
                        gateRejectReason,
                        BuildSubmitContext(
                            symbol,
                            action,
                            orderTypeStr,
                            entry,
                            executionPrice,
                            sl,
                            tp,
                            volumeUnits,
                            requestedRiskMoney,
                            finalRiskMoney
                        )
                    );
                    LogValidationBlock(rejectMsg);
                    RecordPollEvent("", id, symbolCode, action, "REJECTED_RISK_FIREWALL", rejectMsg, "warning");
                    SafeAck(id, leaseToken, "REJECTED", "", rejectMsg);
                    return;
                }
                if (approvedVolumeUnits < volumeUnits)
                {
                    SafePrint(
                        "[Adjust] Shared gate volume reduced from {0:F2} to {1:F2} units for {2} (risk={3:F2}, cap={4:F2})",
                        volumeUnits,
                        approvedVolumeUnits,
                        symbolCode,
                        approvedRiskMoney,
                        finalRiskMoney
                    );
                    volumeUnits = approvedVolumeUnits;
                }
                sl = approvedSl;
                tp = approvedTp;

                double submitReferencePrice = (orderTypeStr == "market" || entry <= 0) ? executionPrice : entry;
                double? submitSlPips = null;
                double? submitTpPips = null;
                if (symbol.PipSize > 0)
                {
                    if (sl > 0)
                    {
                        submitSlPips = Math.Round(Math.Abs(submitReferencePrice - sl) / symbol.PipSize, 2);
                    }
                    if (tp > 0)
                    {
                        submitTpPips = Math.Round(Math.Abs(tp - submitReferencePrice) / symbol.PipSize, 2);
                    }
                }

                if (!submitSlPips.HasValue || submitSlPips.Value <= 0)
                {
                    var rejectMsg = string.Format(
                        CultureInfo.InvariantCulture,
                        "VALIDATION_BLOCKED: invalid_stop_distance E={0:F5} SL={1:F5}",
                        submitReferencePrice,
                        sl
                    );
                    LogValidationBlock(rejectMsg);
                    RecordPollEvent("", id, symbolCode, action, "REJECTED_NO_SL", rejectMsg, "warning");
                    SafeAck(id, leaseToken, "REJECTED", "", rejectMsg);
                    return;
                }

                var requestedLots = symbol.VolumeInUnitsToQuantity(volumeUnits);
                LogStructuredTradeEvent(
                    "server",
                    "SUBMIT",
                    symbolCode,
                    action,
                    orderTypeStr.ToUpperInvariant(),
                    requestedLots,
                    submitReferencePrice,
                    sl,
                    tp,
                    "",
                    id);

                // Submit with protective SL/TP attached so the max-risk gate is enforced
                // at order creation time, then optionally refine to exact absolute prices after fill.
                if (orderTypeStr == "limit")
                {
                    res = PlaceLimitOrder(
                        tradeType,
                        symbol.Name,
                        volumeUnits,
                        entry,
                        label,
                        submitSlPips,
                        submitTpPips,
                        (ProtectionType?)null,
                        null,
                        brokerComment
                    );
                }
                else if (orderTypeStr == "stop")
                {
                    res = PlaceStopOrder(
                        tradeType,
                        symbol.Name,
                        volumeUnits,
                        entry,
                        label,
                        submitSlPips,
                        submitTpPips,
                        (ProtectionType?)null,
                        null,
                        brokerComment
                    );
                }
                else
                {
                    res = ExecuteMarketOrder(tradeType, symbol.Name, volumeUnits, label, submitSlPips, submitTpPips, brokerComment);
                }

                if (
                    (res == null || !res.IsSuccessful) &&
                    res != null &&
                    res.Error == ErrorCode.NoMoney &&
                    volumeUnits > symbol.VolumeInUnitsMin
                )
                {
                    var retryInputVolume = Math.Max(symbol.VolumeInUnitsMin, volumeUnits - Math.Max(symbol.VolumeInUnitsStep, 1));
                    double retryVolumeUnits;
                    double retryMarginEstimate;
                    double retryMarginBudget;
                    string retryMarginNote;
                    if (
                        TryFitVolumeToFreeMargin(
                            symbol,
                            tradeType,
                            retryInputVolume,
                            out retryVolumeUnits,
                            out retryMarginEstimate,
                            out retryMarginBudget,
                            out retryMarginNote
                        ) &&
                        retryVolumeUnits > 0 &&
                        retryVolumeUnits < volumeUnits
                    )
                    {
                        SafePrint(
                            "[Retry] Broker returned NoMoney. Retrying {0} {1} with reduced volume {2:F2} -> {3:F2} units ({4})",
                            action,
                            symbolCode,
                            volumeUnits,
                            retryVolumeUnits,
                            retryMarginNote
                        );
                        volumeUnits = retryVolumeUnits;
                        if (orderTypeStr == "limit")
                        {
                            res = PlaceLimitOrder(
                                tradeType,
                                symbol.Name,
                                volumeUnits,
                                entry,
                                label,
                                submitSlPips,
                                submitTpPips,
                                (ProtectionType?)null,
                                null,
                                brokerComment
                            );
                        }
                        else if (orderTypeStr == "stop")
                        {
                            res = PlaceStopOrder(
                                tradeType,
                                symbol.Name,
                                volumeUnits,
                                entry,
                                label,
                                submitSlPips,
                                submitTpPips,
                                (ProtectionType?)null,
                                null,
                                brokerComment
                            );
                        }
                        else
                        {
                            res = ExecuteMarketOrder(tradeType, symbol.Name, volumeUnits, label, submitSlPips, submitTpPips, brokerComment);
                        }
                    }
                }

                if (res != null && res.IsSuccessful)
                {
                    var ticket = (res.Position != null) ? res.Position.Id.ToString() : (res.PendingOrder != null ? res.PendingOrder.Id.ToString() : "OK");
                    if (!string.IsNullOrWhiteSpace(ticket) && !string.IsNullOrWhiteSpace(id))
                        _ticketSidMap[ticket] = id;

                    // Apply absolute SL/TP immediately after success to ensure 100% price accuracy
                    // If broker rejects SL/TP → close position, cancel trade. No naked positions.
                    if (sl > 0 || tp > 0)
                    {
                        if (res.Position != null)
                        {
                            var needsSl = sl > 0;
                            var needsTp = tp > 0;
                            var normalizedSl = needsSl ? NormalizePriceToSymbol(symbol, sl) : 0;
                            var normalizedTp = needsTp ? NormalizePriceToSymbol(symbol, tp) : 0;
                            string postFillProtectionReason;
                            if (!TryValidateProtectionPrices(symbol, action, res.Position.EntryPrice, normalizedSl, normalizedTp, out postFillProtectionReason))
                            {
                                var rejectMsg = "post_fill_protection_rejected: " + postFillProtectionReason;
                                SafePrint("[FATAL] {0} for {1} #{2}. Closing position.", rejectMsg, symbolCode, ticket);
                                var closeRes = ClosePosition(res.Position);
                                if (closeRes.IsSuccessful)
                                    SafePrint("[FATAL] Position closed after protection sanity failure for {0} #{1}", symbolCode, ticket);
                                else
                                    SafePrint("[CRITICAL] Close also failed for {0} #{1}: {2} - POSITION UNPROTECTED!", symbolCode, ticket, closeRes.Error);
                                RecordPollEvent(ticket, id, symbolCode, action, "CANCELLED_POSITION", rejectMsg, "closed");
                                SafeAck(id, leaseToken, "FAIL", ticket, rejectMsg);
                                return;
                            }

                            var currentSl = res.Position.StopLoss;
                            var currentTp = res.Position.TakeProfit;
                            var slCloseEnough = CTraderExecutionEngine.IsProtectionCloseEnough(
                                currentSl, normalizedSl, needsSl, symbol.PipSize * 0.5);
                            var tpCloseEnough = CTraderExecutionEngine.IsProtectionCloseEnough(
                                currentTp, normalizedTp, needsTp, symbol.PipSize * 0.5);

                            if (HasRequiredProtection(res.Position, needsSl, needsTp) && slCloseEnough && tpCloseEnough)
                            {
                                SafePrint("[Order] Broker-attached protection accepted SL={0} TP={1} for {2} #{3}", currentSl, currentTp, symbolCode, ticket);
                            }
                            else
                            {
                                var mRes = ModifyPositionCompat(res.Position, (needsSl ? (double?)normalizedSl : (double?)null), (needsTp ? (double?)normalizedTp : (double?)null));
                                if (mRes.IsSuccessful)
                                {
                                    SafePrint("[Order] SL/TP set SL={0} TP={1} for {2} #{3}", normalizedSl, normalizedTp, symbolCode, ticket);
                                }
                                else
                                {
                                    var protectedAfterSubmit = HasRequiredProtection(res.Position, needsSl, needsTp);
                                    if (protectedAfterSubmit)
                                    {
                                        SafePrint(
                                            "[WARN] Exact SL/TP refinement failed but broker protection exists. Requested SL={0} TP={1}; current SL={2} TP={3}; error={4}",
                                            normalizedSl,
                                            normalizedTp,
                                            res.Position.StopLoss,
                                            res.Position.TakeProfit,
                                            mRes.Error
                                        );
                                        RecordPollEvent(ticket, id, symbolCode, action, "PROTECTED_POSITION", "exact_sl_tp_refine_failed", "open");
                                    }
                                    else
                                    {
                                        var errDetail = string.Format("SL/TP rejected: {0} (SL={1} TP={2})", mRes.Error, normalizedSl, normalizedTp);
                                        SafePrint("[FATAL] {0} for {1} #{2}. Closing position.", errDetail, symbolCode, ticket);
                                        var closeRes = ClosePosition(res.Position);
                                        if (closeRes != null && closeRes.IsSuccessful)
                                            SafePrint("[FATAL] Position closed after SL/TP failure for {0} #{1}", symbolCode, ticket);
                                        else
                                            SafePrint("[CRITICAL] Close also failed for {0} #{1}: {2} - POSITION UNPROTECTED!", symbolCode, ticket, closeRes != null ? Convert.ToString(closeRes.Error, CultureInfo.InvariantCulture) : "null_result");
                                        RecordPollEvent(ticket, id, symbolCode, action, "CANCELLED_POSITION", errDetail, "closed");
                                        SafeAck(id, leaseToken, "FAIL", ticket, errDetail);
                                        return;
                                    }
                                }
                            }
                        }
                        else if (res.PendingOrder != null)
                        {
                            double? slPips = null;
                            double? tpPips = null;
                            if (sl > 0)
                            {
                                slPips = Math.Round((action == "BUY" ? (res.PendingOrder.TargetPrice - sl) : (sl - res.PendingOrder.TargetPrice)) / symbol.PipSize, 2);
                            }
                            if (tp > 0)
                            {
                                tpPips = Math.Round((action == "BUY" ? (tp - res.PendingOrder.TargetPrice) : (res.PendingOrder.TargetPrice - tp)) / symbol.PipSize, 2);
                            }
                            var mRes = ModifyPendingOrderCompat(res.PendingOrder, res.PendingOrder.TargetPrice, slPips, tpPips, res.PendingOrder.ExpirationTime);
                            if (mRes.IsSuccessful)
                            {
                                SafePrint("[Order] SL/TP set for pending order {0}", ticket);
                            }
                            else
                            {
                                var errDetail = string.Format("SL/TP rejected for pending order: {0}", mRes.Error);
                                SafePrint("[FATAL] {0}. Cancelling order.", errDetail);
                                CancelPendingOrder(res.PendingOrder);
                                RecordPollEvent(ticket, id, symbolCode, action, "CANCELLED_ORDER", errDetail, "closed");
                                SafeAck(id, leaseToken, "FAIL", ticket, errDetail);
                                return;
                            }
                        }
                    }

                    RecordPollEvent(ticket, id, symbolCode, action, (res.Position != null ? "CREATED_POSITION" : "CREATED_ORDER"), "", "created");
                    double lots = symbol.VolumeInUnitsToQuantity(volumeUnits);
                    double ackEntry = (res.Position != null ? res.Position.EntryPrice : (res.PendingOrder != null ? res.PendingOrder.TargetPrice : 0));
                    LogStructuredTradeEvent(
                        "server",
                        "SUCCEEDED",
                        symbolCode,
                        action,
                        orderTypeStr.ToUpperInvariant(),
                        lots,
                        ackEntry,
                        sl,
                        tp,
                        ticket,
                        id);
                    double ackSlPips = 0;
                    double ackTpPips = 0;
                    if (symbol.PipSize > 0 && ackEntry > 0)
                    {
                        if (sl > 0) ackSlPips = Math.Abs(ackEntry - sl) / symbol.PipSize;
                        if (tp > 0) ackTpPips = Math.Abs(tp - ackEntry) / symbol.PipSize;
                    }
                    SafeAck(
                        id,
                        leaseToken,
                        (res.Position != null ? "OPEN" : "PENDING"),
                        ticket,
                        "",
                        ackEntry,
                        finalRiskMoney,
                        lots,
                        requestedSl,
                        sl,
                        requestedTp,
                        tp,
                        ackSlPips,
                        ackTpPips
                    );
                }
                    else
                    {
                        var brokerError = res != null ? Convert.ToString(res.Error, CultureInfo.InvariantCulture) : "unknown";
                        var failureDetail = string.Format(
                            CultureInfo.InvariantCulture,
                            "BROKER_SUBMIT_FAILED:{0} | requested_volume_units={1:F2}; submitted_volume_units={2:F2}; margin_note={3} | {4}",
                            brokerError,
                            requestedVolumeUnits,
                            volumeUnits,
                            string.IsNullOrWhiteSpace(fittedMarginNote) ? "-" : fittedMarginNote,
                            BuildSubmitContext(
                                symbol,
                                action,
                                orderTypeStr,
                                entry,
                                executionPrice,
                                sl,
                                tp,
                                volumeUnits,
                                requestedRiskMoney,
                                finalRiskMoney
                            )
                        );
                        RecordPollEvent("", id, symbolCode, action, "CREATE_FAILED", failureDetail, "error");
                        LogStructuredTradeEvent(
                            "server",
                            "FAILED",
                            symbolCode,
                            action,
                            orderTypeStr.ToUpperInvariant(),
                            symbol.VolumeInUnitsToQuantity(volumeUnits),
                            submitReferencePrice,
                            sl,
                            tp,
                            "",
                            brokerError);
                        SafeLog("ERROR", "[CreateFailed] {0} :: {1}", id, failureDetail);
                        SafeAck(id, leaseToken, "REJECTED", "", failureDetail);
                    }
                }
                catch (Exception ex)
                {
                    var err = string.Format(
                        CultureInfo.InvariantCulture,
                        "execute_signal_failed: {0}",
                        ex.Message
                    );
                    RecordPollEvent(ticketStr, id, symbolCode, action, "EXECUTE_FAILED", err, "error");
                    SafeLog("ERROR", "[Error] ExecuteSignal failed for {0}: {1}", id, ex);
                    SafeAck(id, leaseToken, "ERROR", ticketStr, err);
                }
            });
        }

        private string BuildLeaseKey(string sid, string token)
        {
            return (sid ?? "") + ":" + (token ?? "");
        }

        private void ReleaseProcessedLease(string sid, string token)
        {
            if (string.IsNullOrWhiteSpace(sid) || string.IsNullOrWhiteSpace(token)) return;
            _processedLeases.Remove(BuildLeaseKey(sid, token));
        }

        private void CleanupOldEntries()
        {
            // Clean up old processed signal IDs to prevent memory growth
            if (_processedSignalIds.Count > 1000)
            {
                var toRemove = _processedSignalIds.Take(_processedSignalIds.Count - 500).ToList();
                foreach (var id in toRemove) _processedSignalIds.Remove(id);
                SafePrint("[Cleanup] Removed {0} old signal IDs from memory", toRemove.Count);
            }

            // Clean up old lease entries
            if (_processedLeases.Count > 1000)
            {
                var toRemove = _processedLeases.Take(_processedLeases.Count - 500).ToList();
                foreach (var l in toRemove) _processedLeases.Remove(l);
                SafePrint("[Cleanup] Removed {0} old lease entries from memory", toRemove.Count);
            }

            // Clean up old synced closed tickets
            var removedClosedTickets = CTraderSyncEngine.TrimClosedTicketSet(
                _syncedClosedTickets, 500, 250);
            if (removedClosedTickets > 0)
                SafePrint("[Cleanup] Removed {0} old closed tickets from memory", removedClosedTickets);

            // Clean up old partial TP tracking
            if (_executedPartials.Count > 200)
            {
                var toRemove = _executedPartials.Take(_executedPartials.Count - 100).ToList();
                foreach (var key in toRemove)
                {
                    _executedPartials.Remove(key);
                }
                SafePrint("[Cleanup] Removed {0} old partial TP keys from memory", toRemove.Count);
            }

            // Auto-clear error state after 5 minutes of successful operation
            if (_consecutiveErrors > 0 && (DateTime.Now - _lastErrorClearTime).TotalMinutes > 5)
            {
                ResetTransientErrorTracking("[Recovery] Error counter reset after 5 minutes of stable operation");
            }
        }

        private async Task SyncWithVpsAsync(string accId, double bal, double eq, double marg, string brokerName, List<string> posList, List<string> ordersList, List<string> closedList, HashSet<string> activeTicketIds, List<string> metricsList, List<Tuple<string, double, double>> priceData, List<string> syncSymbols, string queueActionsJson, List<string> queueTerminalKeysSent, bool queueSnapshotComplete)
        {
            if (ShouldUseLocalRuntime())
            {
                await SyncWithLocalRuntimeAsync(accId, bal, eq, marg, brokerName, posList, ordersList, closedList, queueActionsJson, queueSnapshotComplete);
                return;
            }
            _syncStatus = "SYNCING";
            HttpRequestMessage request = null;
            var startedAt = DateTime.Now;
            try
            {
                _lastPushPositionCount = posList != null ? posList.Count : 0;
                _lastPushOrderCount = ordersList != null ? ordersList.Count : 0;
                _lastPushClosedCount = closedList != null ? closedList.Count : 0;
                _lastPushSymbolCount = syncSymbols != null ? syncSymbols.Where(s => !string.IsNullOrWhiteSpace(s)).Distinct(StringComparer.OrdinalIgnoreCase).Count() : 0;
                _lastPushPriceSymbolCount = priceData != null ? priceData.Select(p => p.Item1).Where(s => !string.IsNullOrWhiteSpace(s)).Distinct(StringComparer.OrdinalIgnoreCase).Count() : 0;
                if (_lastPushPriceSymbolCount > 0) _priceStatus = "PUSHING";
                var resolvedProviderCode = ResolveProviderCode(brokerName);
                var payload = CTraderSyncEngine.BuildSyncPayload(
                    GetBridgeIdentityJson(accId),
                    bal,
                    eq,
                    marg,
                    brokerName,
                    resolvedProviderCode,
                    BuildVersion,
                    posList,
                    ordersList,
                    closedList,
                    queueActionsJson,
                    queueSnapshotComplete,
                    metricsList,
                    priceData);
                var content = new StringContent(payload, Encoding.UTF8, "application/json");
                using (request = new HttpRequestMessage(System.Net.Http.HttpMethod.Post, BuildServerApiUrl("broker/sync")))
                {
                    request.Headers.Add("x-api-key", EaApiKey);
                    request.Content = content;
                    var response = await SendWithTimeoutAsync(
                        request,
                        SyncTimeoutSeconds
                    );

                    _serverStatus = (int)response.StatusCode < 500 ? "OK" : "SERVER_ERR";

                    if (response.IsSuccessStatusCode)
                    {
                        _lastSyncLatencyMs = Math.Max(0, (long)(DateTime.Now - startedAt).TotalMilliseconds);
                        _syncConsecutiveFailures = 0;
                        MarkApiReachable();
                        _apiStatus = "OK";
                        WriteBridgeDebugLog("SyncWithVps: OK");
                        _syncCount++; _syncStatus = "OK"; _lastSyncTime = DateTime.Now; _lastSyncErr = "None";

                        // Reset error counter on successful sync
                        if (_consecutiveErrors > 0)
                        {
                            ResetTransientErrorTracking("[Recovery] Error counter reset after successful sync");
                        }

                        var json = await response.Content.ReadAsStringAsync();
                        await RunOnMainThreadAsync(() =>
                        {
                            ParseSyncResults(json, activeTicketIds);
                            ProcessServerQueueActions(json, true);
                            foreach (var terminalKey in queueTerminalKeysSent ?? new List<string>())
                                _strategyQueueTerminalUpdates.Remove(terminalKey);
                            return true;
                        });
                        if (_lastPushPriceSymbolCount > 0)
                        {
                            _priceCount++;
                            _priceStatus = "OK";
                            _lastPriceTime = DateTime.Now;
                            _lastPriceErr = "None";
                        }
                    }
                    else
                    {
                        _lastSyncLatencyMs = Math.Max(0, (long)(DateTime.Now - startedAt).TotalMilliseconds);
                        _syncConsecutiveFailures++;
                        WriteBridgeDebugLog("SyncWithVps: HTTP " + (int)response.StatusCode);
                        _apiStatus = (response.StatusCode == HttpStatusCode.Unauthorized || response.StatusCode == HttpStatusCode.Forbidden) ? "KEY_INVALID" : "ERR_" + (int)response.StatusCode;
                        _syncStatus = "FAIL (" + (int)response.StatusCode + ")";
                        var responseBody = await response.Content.ReadAsStringAsync();
                        _lastSyncErr = FormatServerErrorForPanel(responseBody);
                        if (string.IsNullOrEmpty(_lastSyncErr)) _lastSyncErr = "Server Rejected Payload";

                        // Increment error counter for failed sync
                        _consecutiveErrors++;
                        SafePrint("[Error] Sync failed: {0} (consecutive errors: {1})", _lastSyncErr, _consecutiveErrors);
                        LogServerErrorDetail("sync", accId, responseBody);
                        if (_lastPushPriceSymbolCount > 0)
                        {
                            _priceStatus = "FAIL (" + (int)response.StatusCode + ")";
                            _lastPriceErr = _lastSyncErr;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                _lastSyncLatencyMs = Math.Max(0, (long)(DateTime.Now - startedAt).TotalMilliseconds);
                _syncConsecutiveFailures++;
                WriteBridgeDebugLog("SyncWithVps EXCEPTION: " + ex.Message);
                MarkApiOfflineCooldown();
                _syncStatus = "ERROR";
                _lastSyncErr = FormatServerErrorForPanel(ex.Message);

                // Increment error counter for sync exceptions
                _consecutiveErrors++;
                if (ShouldEmitTransientErrorLog())
                {
                    SafePrint("[Error] Sync exception: {0} (consecutive errors: {1})", ex.Message, _consecutiveErrors);
                    LogHttpExceptionDetail("sync", accId, request, SyncTimeoutSeconds, ex);
                }
                if (_lastPushPriceSymbolCount > 0)
                {
                    _priceStatus = "ERROR";
                    _lastPriceErr = _lastSyncErr;
                }
            }
            finally
            {
                RefreshDebugPanel();
            }
        }

        private async Task SyncWithLocalRuntimeAsync(string accId, double bal, double eq, double marg, string brokerName, List<string> posList, List<string> ordersList, List<string> closedList, string queueActionsJson, bool queueSnapshotComplete)
        {
            try
            {
                var json = await RunLocalRuntimeAsync(new Dictionary<string, object>
                {
                    { "operation", "sync" },
                    { "project_root", GetBaseServerRootPath() },
                    { "user_id", LocalRuntimeUserId() },
                    { "account_id", accId },
                    { "balance", bal },
                    { "equity", eq },
                    { "margin", marg },
                    { "broker_name", brokerName ?? "" },
                    { "positions", posList ?? new List<string>() },
                    { "orders", ordersList ?? new List<string>() },
                    { "closed", closedList ?? new List<string>() },
                    { "queue_actions", queueActionsJson ?? "[]" },
                    { "queue_snapshot_complete", queueSnapshotComplete },
                });
                _serverStatus = "LOCAL";
                _apiStatus = "LOCAL";
                _syncStatus = "OK_LOCAL";
                _syncCount++;
                _lastSyncTime = DateTime.Now;
                _lastSyncErr = "None";
                RunOnMainThread(() => ProcessServerQueueActions(json, true));
            }
            catch (Exception ex)
            {
                _syncStatus = "LOCAL_ERR";
                _lastSyncErr = FormatServerErrorForPanel(ex.Message);
                SafePrint("[LocalSync] ERROR: {0}", _lastSyncErr);
            }
        }

        private async Task PushBarsAsync(string accId, List<string> symbols)
        {
            if (!IsBarsPersistenceEnabled())
            {
                _barStatus = "DISABLED";
                _lastBarErr = "Enable Bars save=No";
                return;
            }

            _barStatus = "PUSHING";
            HttpRequestMessage request = null;
            try
            {
                string[] tfs = { "1", "5", "15", "60", "240", "1440" };
                var barList = new List<string>();
                var barMarkers = new List<Tuple<string, long>>();
                var barFingerprints = new List<Tuple<string, string>>();
                int newBars = 0;

                var barBuild = await RunOnMainThreadAsync(() =>
                {
                    var localBars = new List<string>();
                    var localMarkers = new List<Tuple<string, long>>();
                    var localFingerprints = new List<Tuple<string, string>>();
                    var localNewBars = 0;
                    foreach (var sym in symbols)
                    {
                        Symbol resolvedSymbol;
                        if (!TryResolveQuotedSymbol(sym, out resolvedSymbol)) continue;
                        foreach (var tfStr in tfs)
                        {
                            try
                            {
                                TimeFrame tf;
                                switch (tfStr)
                                {
                                    case "1": tf = TimeFrame.Minute; break;
                                    case "5": tf = TimeFrame.Minute5; break;
                                    case "15": tf = TimeFrame.Minute15; break;
                                    case "60": tf = TimeFrame.Hour; break;
                                    case "240": tf = TimeFrame.Hour4; break;
                                    case "1440": tf = TimeFrame.Daily; break;
                                    default: continue;
                                }

                                var bars = MarketData.GetBars(tf, resolvedSymbol.Name);
                                if (bars == null || bars.Count < 1) continue;

                                var lastBar = bars.LastBar;
                                long barTime = ToUnixTime(lastBar.OpenTime);

                                string key = resolvedSymbol.Name + "_" + tfStr;
                                string fingerprint = barTime.ToString(CultureInfo.InvariantCulture) + "|" +
                                    lastBar.Open.ToString("F5", CultureInfo.InvariantCulture) + "|" +
                                    lastBar.High.ToString("F5", CultureInfo.InvariantCulture) + "|" +
                                    lastBar.Low.ToString("F5", CultureInfo.InvariantCulture) + "|" +
                                    lastBar.Close.ToString("F5", CultureInfo.InvariantCulture) + "|" +
                                    lastBar.TickVolume.ToString(CultureInfo.InvariantCulture);
                                string lastFingerprint;
                                if (_barLastFingerprint.TryGetValue(key, out lastFingerprint) &&
                                    string.Equals(lastFingerprint, fingerprint, StringComparison.Ordinal))
                                    continue;

                                localBars.Add(
                                    "{\"s\":\"" + resolvedSymbol.Name + "\"" +
                                    ",\"tf\":\"" + tfStr + "\"" +
                                    ",\"t\":" + barTime.ToString() +
                                    ",\"o\":" + lastBar.Open.ToString("F5", CultureInfo.InvariantCulture) +
                                    ",\"h\":" + lastBar.High.ToString("F5", CultureInfo.InvariantCulture) +
                                    ",\"l\":" + lastBar.Low.ToString("F5", CultureInfo.InvariantCulture) +
                                    ",\"c\":" + lastBar.Close.ToString("F5", CultureInfo.InvariantCulture) +
                                    ",\"v\":" + lastBar.TickVolume.ToString() + "}"
                                );
                                localMarkers.Add(Tuple.Create(key, barTime));
                                localFingerprints.Add(Tuple.Create(key, fingerprint));
                                localNewBars++;
                                if (localNewBars >= 10) break;
                            }
                            catch { }
                        }
                        if (localNewBars >= 10) break;
                    }
                    return Tuple.Create(localBars, localMarkers, localFingerprints, localNewBars);
                });
                barList = barBuild.Item1;
                barMarkers = barBuild.Item2;
                barFingerprints = barBuild.Item3;
                newBars = barBuild.Item4;

                if (newBars == 0)
                {
                    _barStatus = "IDLE"; _lastBarTime = DateTime.Now; _lastBarErr = "None";
                    return;
                }

                if (ShouldUseLocalRuntime())
                {
                    var localResult = await RunLocalRuntimeAsync(new Dictionary<string, object>
                    {
                        { "operation", "bars" },
                        { "project_root", GetBaseServerRootPath() },
                        { "user_id", LocalRuntimeUserId() },
                        { "account_id", accId },
                        { "raw_bars", barList },
                    });
                    _serverStatus = "LOCAL";
                    _apiStatus = "LOCAL";
                    _barStatus = "OK_LOCAL";
                    _lastBarErr = "None";
                    _barCount += newBars;
                    foreach (var marker in barMarkers)
                        if (marker != null) _barLastTime[marker.Item1] = marker.Item2;
                    foreach (var fingerprint in barFingerprints)
                        if (fingerprint != null) _barLastFingerprint[fingerprint.Item1] = fingerprint.Item2;
                    SafePrint("[LocalBars] parquet_saved={0} detail={1}", newBars, localResult);
                    return;
                }

                var payload = CTraderSyncEngine.BuildBarsPayload(GetBridgeIdentityJson(accId), barList);
                HttpResponseMessage response = null;
                var sendTimeoutSeconds = Math.Max(5, Math.Min(30, SyncTimeoutSeconds));
                var retriedAfterReset = false;
                try
                {
                    using (request = BuildAuthenticatedJsonRequest("broker/bars", payload))
                    {
                        response = await SendWithTimeoutAsync(request, sendTimeoutSeconds);
                    }
                }
                catch (Exception ex) when (IsConnectionResetException(ex))
                {
                    retriedAfterReset = true;
                    SafePrint("[Bar] Push retry: local API reset the connection; retrying once with a fresh socket.");
                    await Task.Delay(250);
                    using (request = BuildAuthenticatedJsonRequest("broker/bars", payload, true))
                    {
                        response = await SendWithTimeoutAsync(request, sendTimeoutSeconds);
                    }
                }

                if (response.IsSuccessStatusCode)
                {
                    foreach (var marker in barMarkers)
                    {
                        if (marker == null)
                            continue;
                        _barLastTime[marker.Item1] = marker.Item2;
                    }
                    foreach (var fingerprint in barFingerprints)
                        if (fingerprint != null) _barLastFingerprint[fingerprint.Item1] = fingerprint.Item2;

                    MarkApiReachable();
                    _barCount += newBars; _barStatus = "OK"; _lastBarTime = DateTime.Now; _lastBarErr = retriedAfterReset ? "Recovered after retry" : "None";
                    var responseBody = await response.Content.ReadAsStringAsync();
                    SafePrint(
                        "[Bar] persistence_accepted bars={0} symbols={1} result={2}",
                        newBars,
                        symbols.Count,
                        string.IsNullOrWhiteSpace(responseBody) ? "{}" : responseBody);
                }
                else
                {
                    _barStatus = "FAIL (" + (int)response.StatusCode + ")";
                    var responseBody = await response.Content.ReadAsStringAsync();
                    _lastBarErr = FormatServerErrorForPanel(responseBody);
                    SafePrint("[Bar] Push FAILED: {0}", _lastBarErr);
                    LogServerErrorDetail("bars", accId, responseBody);
                }
            }
            catch (Exception ex)
            {
                MarkApiOfflineCooldown();
                _barStatus = "ERROR";
                var detail = BuildExceptionDetail(ex);
                _lastBarErr = FormatServerErrorForPanel(detail);
                SafePrint("[Bar] Push ERROR: {0}", _lastBarErr);
                LogHttpExceptionDetail("bars", accId, request, Math.Max(5, Math.Min(30, SyncTimeoutSeconds)), ex);
            }
            if (_lastBarTime == DateTime.MinValue) _lastBarTime = DateTime.Now;
        }

        private async Task SyncBarsIncrementalAsync(string accId, List<string> symbols)
        {
            if (!IsBarsPersistenceEnabled())
                return;
            if (ShouldUseLocalRuntime())
            {
                await PushBarsAsync(accId, symbols);
                return;
            }
            if (!EnableIncrementalBars) return;
            HttpRequestMessage activeRequest = null;
            var activeOperation = "incbars.coverage";
            var sendTimeoutSeconds = Math.Max(5, Math.Min(30, SyncTimeoutSeconds));
            try
            {
                // 1. Get coverage from webhook
                var covUrl = BuildServerApiUrl("broker/symbols") + "?symbols=" + string.Join(",", symbols);
                HttpResponseMessage covResponse = null;
                try
                {
                    using (activeRequest = new HttpRequestMessage(System.Net.Http.HttpMethod.Get, covUrl))
                    {
                        activeRequest.Headers.Add("x-api-key", EaApiKey);
                        covResponse = await SendWithTimeoutAsync(activeRequest, sendTimeoutSeconds);
                    }
                }
                catch (Exception ex) when (IsConnectionResetException(ex))
                {
                    SafePrint("[IncBars] Coverage retry: local API reset the connection; retrying once with a fresh socket.");
                    await Task.Delay(250);
                    using (activeRequest = new HttpRequestMessage(System.Net.Http.HttpMethod.Get, covUrl))
                    {
                        activeRequest.Headers.Add("x-api-key", EaApiKey);
                        activeRequest.Headers.ConnectionClose = true;
                        covResponse = await SendWithTimeoutAsync(activeRequest, sendTimeoutSeconds);
                    }
                }
                catch (Exception ex) when (IsTimeoutException(ex))
                {
                    SafePrint("[IncBars] Coverage retry: local API timed out; retrying once with a fresh socket.");
                    await Task.Delay(250);
                    using (activeRequest = new HttpRequestMessage(System.Net.Http.HttpMethod.Get, covUrl))
                    {
                        activeRequest.Headers.Add("x-api-key", EaApiKey);
                        activeRequest.Headers.ConnectionClose = true;
                        covResponse = await SendWithTimeoutAsync(activeRequest, sendTimeoutSeconds);
                    }
                }
                if (!covResponse.IsSuccessStatusCode)
                {
                    var responseBody = await covResponse.Content.ReadAsStringAsync();
                    _lastIncrementalErr = FormatServerErrorForPanel(responseBody);
                    if (string.IsNullOrWhiteSpace(_lastIncrementalErr))
                        _lastIncrementalErr = "HTTP " + (int)covResponse.StatusCode;
                    SafePrint("[IncBars] Coverage failed: HTTP {0}: {1}", (int)covResponse.StatusCode, _lastIncrementalErr);
                    LogServerErrorDetail(activeOperation, accId, responseBody);
                    return;
                }
                MarkApiReachable();
                var covJson = await covResponse.Content.ReadAsStringAsync();

                // 2. Fetch bars from broker for each symbol+TF with gaps
                string[] tfs = { "1", "5", "15", "60", "240", "1440" };

                var syncBuild = await RunOnMainThreadAsync(() =>
                {
                    var sw = Stopwatch.StartNew();
                    var items = new List<string>();
                    int totalBars = 0;
                    bool isFirstSync = _incrementalSyncCount == 0;
                    int maxBars = CTraderSyncEngine.ResolveIncrementalPostLimit(
                        isFirstSync, IncrementalBarsMaxPerPost);
                    const int maxMainThreadMs = 250;

                    foreach (var sym in symbols)
                    {
                        if (sw.ElapsedMilliseconds >= maxMainThreadMs) break;
                        Symbol resolvedSymbol;
                        if (!TryResolveQuotedSymbol(sym, out resolvedSymbol)) continue;
                        var symUpper = resolvedSymbol.Name.ToUpperInvariant();
                        foreach (var tfStr in tfs)
                        {
                            if (sw.ElapsedMilliseconds >= maxMainThreadMs) break;
                            if (totalBars >= maxBars) break;
                            try
                            {
                                var coverage = CTraderSyncEngine.ParseCoverage(covJson, symUpper, tfStr);

                                TimeFrame tf;
                                switch (tfStr)
                                {
                                    case "1": tf = TimeFrame.Minute; break;
                                    case "5": tf = TimeFrame.Minute5; break;
                                    case "15": tf = TimeFrame.Minute15; break;
                                    case "60": tf = TimeFrame.Hour; break;
                                    case "240": tf = TimeFrame.Hour4; break;
                                    case "1440": tf = TimeFrame.Daily; break;
                                    default: continue;
                                }

                                var bars = MarketData.GetBars(tf, resolvedSymbol.Name);
                                if (bars == null || bars.Count < 1) continue;
                                var latestBar = bars.LastBar;
                                long latestTime = ToUnixTime(latestBar.OpenTime);
                                int tfSec = int.Parse(tfStr) * 60;

                                var fetchPlan = CTraderSyncEngine.BuildIncrementalFetchPlan(
                                    coverage.RemoteEnd,
                                    coverage.ExistingBars,
                                    coverage.TargetBars,
                                    latestTime,
                                    tfSec);
                                if (!fetchPlan.ShouldFetch) continue;
                                var fetchStart = fetchPlan.FetchStart;
                                var needed = fetchPlan.NeededBars;

                                var barArr = new List<string>();
                                int sent = 0;
                                for (int i = bars.Count - 1; i >= 0 && sent < needed && (totalBars + sent) < maxBars; i--)
                                {
                                    if (sw.ElapsedMilliseconds >= maxMainThreadMs) break;
                                    var b = bars[i];
                                    long bt = ToUnixTime(b.OpenTime);
                                    if (bt < fetchStart) break;
                                    if (bt >= latestTime) continue;
                                    barArr.Add(
                                        "{\"time\":" + bt.ToString() +
                                        ",\"open\":" + b.Open.ToString("F5", CultureInfo.InvariantCulture) +
                                        ",\"high\":" + b.High.ToString("F5", CultureInfo.InvariantCulture) +
                                        ",\"low\":" + b.Low.ToString("F5", CultureInfo.InvariantCulture) +
                                        ",\"close\":" + b.Close.ToString("F5", CultureInfo.InvariantCulture) +
                                        ",\"volume\":" + b.TickVolume.ToString() + "}");
                                    sent++;
                                }
                                if (sent > 0)
                                {
                                    barArr.Reverse();
                                    items.Add("{\"symbol\":\"" + symUpper + "\",\"tf\":\"" + tfStr + "\",\"bars\":[" + string.Join(",", barArr) + "]}");
                                    totalBars += sent;
                                }
                            }
                            catch { }
                        }
                        if (totalBars >= maxBars) break;
                    }
                    return Tuple.Create(items, totalBars);
                });

                var syncItems = syncBuild.Item1;
                var totalBars = syncBuild.Item2;

                if (totalBars == 0)
                {
                    _lastIncrementalErr = "None";
                    return;
                }

                // 3. POST to prices-sync
                var payload = CTraderSyncEngine.BuildIncrementalBarsPayload(
                    GetBridgeIdentityJson(accId), syncItems);
                activeOperation = "incbars.post";
                HttpResponseMessage postResponse = null;
                try
                {
                    using (activeRequest = BuildAuthenticatedJsonRequest("broker/prices-sync", payload))
                    {
                        postResponse = await SendWithTimeoutAsync(activeRequest, sendTimeoutSeconds);
                    }
                }
                catch (Exception ex) when (IsConnectionResetException(ex))
                {
                    SafePrint("[IncBars] POST retry: local API reset the connection; retrying once with a fresh socket.");
                    await Task.Delay(250);
                    using (activeRequest = BuildAuthenticatedJsonRequest("broker/prices-sync", payload, true))
                    {
                        postResponse = await SendWithTimeoutAsync(activeRequest, sendTimeoutSeconds);
                    }
                }
                catch (Exception ex) when (IsTimeoutException(ex))
                {
                    SafePrint("[IncBars] POST retry: local API timed out; retrying once with a fresh socket.");
                    await Task.Delay(250);
                    using (activeRequest = BuildAuthenticatedJsonRequest("broker/prices-sync", payload, true))
                    {
                        postResponse = await SendWithTimeoutAsync(activeRequest, sendTimeoutSeconds);
                    }
                }

                if (postResponse.IsSuccessStatusCode)
                {
                    MarkApiReachable();
                    var respJson = await postResponse.Content.ReadAsStringAsync();
                    int inserted;
                    int duplicated;
                    CTraderSyncEngine.ParseIncrementalResult(respJson, out inserted, out duplicated);
                    _incrementalSyncCount++;
                    _incrementalTotalInserted += inserted;
                    _lastIncrementalErr = "None";
                    SafePrint("[IncBars] sync={0} bars={1} ins={2} dup={3}", _incrementalSyncCount, totalBars, inserted, duplicated);
                }
                else
                {
                    var responseBody = await postResponse.Content.ReadAsStringAsync();
                    _lastIncrementalErr = FormatServerErrorForPanel(responseBody);
                    if (string.IsNullOrWhiteSpace(_lastIncrementalErr))
                        _lastIncrementalErr = "HTTP " + (int)postResponse.StatusCode;
                    SafePrint("[IncBars] POST failed: HTTP {0}: {1}", (int)postResponse.StatusCode, _lastIncrementalErr);
                    LogServerErrorDetail(activeOperation, accId, responseBody);
                }
            }
            catch (Exception ex) when (IsTimeoutException(ex))
            {
                var timeoutSummary = BuildHttpTimeoutSummary(activeOperation, activeRequest, sendTimeoutSeconds);
                _lastIncrementalErr = timeoutSummary;
                SafePrint("[IncBars] TIMEOUT: {0}", timeoutSummary);
            }
            catch (Exception ex)
            {
                MarkApiOfflineCooldown();
                var detail = BuildExceptionDetail(ex);
                _lastIncrementalErr = FormatServerErrorForPanel(detail);
                SafePrint("[IncBars] ERROR: {0}", _lastIncrementalErr);
                LogHttpExceptionDetail(activeOperation, accId, activeRequest, sendTimeoutSeconds, ex);
            }
        }

        private long ToUnixTime(DateTime dt)
        {
            return CTraderSyncEngine.ToUnixTimeSeconds(dt);
        }

        private string FormatServerErrorForPanel(string raw)
        {
            return CTraderTransportEngine.FormatServerErrorForPanel(raw);
        }

        private void AppendWrappedPanelLine(StringBuilder sb, string prefix, string text, int lineWidth, int maxLines)
        {
            var value = string.IsNullOrWhiteSpace(text) ? "" : text.Trim();
            if (string.IsNullOrEmpty(value)) return;
            var width = Math.Max(24, lineWidth);
            var lines = 0;
            var head = string.IsNullOrEmpty(prefix) ? "" : prefix;
            while (value.Length > 0 && lines < maxLines)
            {
                var room = width - (lines == 0 ? head.Length : 0);
                if (room < 12) room = width;
                if (value.Length <= room)
                {
                    sb.AppendLine((lines == 0 ? head : "") + value);
                    break;
                }
                var split = value.LastIndexOf(' ', Math.Min(room, value.Length - 1));
                if (split < Math.Max(8, room / 2)) split = room;
                var chunk = value.Substring(0, split).Trim();
                sb.AppendLine((lines == 0 ? head : "") + chunk);
                value = value.Substring(Math.Min(split, value.Length)).TrimStart();
                lines++;
            }
            if (value.Length > 0 && lines >= maxLines)
            {
                sb.AppendLine("...");
            }
        }

        private void ParseSyncResults(string json, HashSet<string> activeTicketIds)
        {
            ResetSyncSummary();
            var hasErrors = false;
            string firstError = null;
            var addedSids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var hasServerSummary = false;
            var resultSummaryJson = GetJsonObject(json, "result_summary");
            if (!string.IsNullOrEmpty(resultSummaryJson))
            {
                hasServerSummary = true;
                _lastSyncSummary.Read = GetJsonInt(resultSummaryJson, "read");
                _lastSyncSummary.Unchanged = GetJsonInt(resultSummaryJson, "unchanged");
                _lastSyncSummary.Created = GetJsonInt(resultSummaryJson, "created");
                _lastSyncSummary.Changed = GetJsonInt(resultSummaryJson, "changed");
                _lastSyncSummary.Closed = GetJsonInt(resultSummaryJson, "closed");
            }
            var requestSummaryJson = GetJsonObject(json, "request_summary");
            if (!string.IsNullOrEmpty(requestSummaryJson))
            {
                _lastPushPositionCount = GetJsonInt(requestSummaryJson, "positions");
                _lastPushOrderCount = GetJsonInt(requestSummaryJson, "orders");
                _lastPushClosedCount = GetJsonInt(requestSummaryJson, "closed");
                _lastPushSymbolCount = GetJsonInt(requestSummaryJson, "symbols");
                _lastPushPriceSymbolCount = GetJsonInt(requestSummaryJson, "price_symbols");
            }
            var priceSummaryJson = GetJsonObject(json, "price_summary");
            if (!string.IsNullOrEmpty(priceSummaryJson))
            {
                var updatedSymbols = GetJsonStringArray(priceSummaryJson, "symbols");
                var storedCount = GetJsonInt(priceSummaryJson, "stored");
                if (_lastPushPriceSymbolCount > 0 || updatedSymbols.Count > 0 || storedCount > 0)
                {
                    _lastPriceStoredCount = storedCount;
                    _lastPriceSymbolsText = updatedSymbols.Count > 0 ? string.Join(",", updatedSymbols.Take(12)) : "None";
                }
            }
            var resultsMatch = Regex.Match(json, "\"results\"\\s*:\\s*\\[(.*?)\\]", RegexOptions.Singleline);
            if (resultsMatch.Success)
            {
                var objects = Regex.Matches(resultsMatch.Groups[1].Value, "\\{(.*?)\\}", RegexOptions.Singleline);
                if (!hasServerSummary) _lastSyncSummary.Read = objects.Count;
                foreach (Match objMatch in objects)
                {
                    var obj = "{" + objMatch.Groups[1].Value + "}";
                    var ticket = GetJsonValue(obj, "ticket");
                    var sid = GetJsonValue(obj, "sid");
                    var status = GetJsonValue(obj, "status");
                    var sym = GetJsonValue(obj, "symbol");
                    var act = GetJsonValue(obj, "action");
                    var err = GetJsonValue(obj, "error");
                    var reason = GetJsonValue(obj, "reason");

                    if (status == "Ok")
                    {
                        if (status == "Ok" && !activeTicketIds.Contains(ticket)) _syncedClosedTickets.Add(ticket);
                        continue;
                    }
                    if (status == "Skip")
                    {
                        continue;
                    }
                    if (string.Equals(status, "NoChange", StringComparison.OrdinalIgnoreCase))
                    {
                        if (!hasServerSummary) _lastSyncSummary.Unchanged++;
                        if (!string.IsNullOrEmpty(ticket) && !string.IsNullOrEmpty(sid) && sid != "null")
                            _ticketSidMap[ticket] = sid;
                        continue;
                    }
                    if (string.Equals(status, "Added", StringComparison.OrdinalIgnoreCase))
                    {
                        if (!hasServerSummary) _lastSyncSummary.Created++;
                        if (!string.IsNullOrWhiteSpace(sid) && sid != "null") addedSids.Add(sid.Trim());
                        AddSyncEvent(ticket, sid, sym, act, "DISCOVERED_TRADE", reason, "created");
                        if (!string.IsNullOrEmpty(ticket) && !string.IsNullOrEmpty(sid) && sid != "null")
                            _ticketSidMap[ticket] = sid;
                        continue;
                    }
                    if (string.Equals(status, "Error", StringComparison.OrdinalIgnoreCase))
                    {
                        hasErrors = true;
                        if (string.IsNullOrEmpty(firstError)) firstError = !string.IsNullOrEmpty(err) ? err : reason;
                        AddSyncEvent(ticket, sid, sym, act, "SYNC_ERROR", !string.IsNullOrEmpty(err) ? err : reason, "error");
                        continue;
                    }
                    if (!string.IsNullOrEmpty(ticket) && !string.IsNullOrEmpty(sid) && sid != "null")
                    {
                        _ticketSidMap[ticket] = sid;
                    }
                }
            }

            var updatesMatch = Regex.Match(json, "\"tradeUpdates\"\\s*:\\s*\\[(.*?)\\]", RegexOptions.Singleline);
            if (updatesMatch.Success)
            {
                var updates = Regex.Matches(updatesMatch.Groups[1].Value, "\\{(.*?)\\}", RegexOptions.Singleline);
                foreach (Match updateMatch in updates)
                {
                    var obj = "{" + updateMatch.Groups[1].Value + "}";
                    var sid = GetJsonValue(obj, "sid");
                    if (String.IsNullOrWhiteSpace(sid) || addedSids.Contains(sid.Trim())) continue;
                    var symbol = GetJsonValue(obj, "symbol");
                    var exec = GetJsonValue(obj, "execution_status");
                    var statusChanged = JsonBool(GetJsonValue(obj, "status_changed"));
                    var slChanged = JsonBool(GetJsonValue(obj, "sl_changed"));
                    var tpChanged = JsonBool(GetJsonValue(obj, "tp_changed"));
                    var partialChanged = JsonBool(GetJsonValue(obj, "partial_changed"));
                    var rejectionReason = GetJsonValue(obj, "rejection_reason");
                    var oldSl = GetJsonValue(obj, "sl_before");
                    var newSl = GetJsonValue(obj, "sl");
                    var oldTp = GetJsonValue(obj, "tp_before");
                    var newTp = GetJsonValue(obj, "tp");
                    var detailParts = new List<string>();
                    if (statusChanged && !string.IsNullOrWhiteSpace(exec))
                        detailParts.Add("state=" + exec.Trim().ToUpperInvariant());
                    if (slChanged) detailParts.Add("SL " + PanelValue(oldSl, "-") + "->" + PanelValue(newSl, "-"));
                    if (tpChanged) detailParts.Add("TP " + PanelValue(oldTp, "-") + "->" + PanelValue(newTp, "-"));
                    if (partialChanged) detailParts.Add("partials updated");
                    if (!string.IsNullOrWhiteSpace(rejectionReason)) detailParts.Add(rejectionReason.Trim());
                    var eventCode = DeriveSyncEventCode(exec, statusChanged, slChanged, tpChanged, partialChanged);
                    var bucket = CTraderSyncEngine.ResolveSyncEventBucket(exec);
                    if (!hasServerSummary)
                    {
                        if (bucket == "closed") _lastSyncSummary.Closed++;
                        else _lastSyncSummary.Changed++;
                    }
                    AddSyncEvent("", sid, symbol, "", eventCode, String.Join(", ", detailParts.Where(x => !String.IsNullOrWhiteSpace(x))), bucket);
                }
            }

            var closedRowsMatch = Regex.Match(json, "\"closedRows\"\\s*:\\s*\\[(.*?)\\]", RegexOptions.Singleline);
            if (closedRowsMatch.Success)
            {
                var closedRows = Regex.Matches(closedRowsMatch.Groups[1].Value, "\\{(.*?)\\}", RegexOptions.Singleline);
                foreach (Match rowMatch in closedRows)
                {
                    var obj = "{" + rowMatch.Groups[1].Value + "}";
                    var sid = GetJsonValue(obj, "sid");
                    if (String.IsNullOrWhiteSpace(sid)) continue;
                    if (_syncEvents.Any(x => string.Equals(x.Sid ?? "", sid.Trim(), StringComparison.OrdinalIgnoreCase) && string.Equals(x.Bucket ?? "", "closed", StringComparison.OrdinalIgnoreCase)))
                        continue;
                    var symbol = GetJsonValue(obj, "symbol");
                    var exec = GetJsonValue(obj, "execution_status");
                    var closeReason = GetJsonValue(obj, "close_reason");
                    if (!hasServerSummary) _lastSyncSummary.Closed++;
                    AddSyncEvent("", sid, symbol, "", (exec ?? "").Trim().ToUpperInvariant() == "CANCELLED" ? "SNAPSHOT_CANCELLED" : "SNAPSHOT_CLOSED", closeReason, "closed");
                }
            }

            if (hasErrors)
            {
                _syncStatus = "PARTIAL";
                if (!string.IsNullOrEmpty(firstError)) _lastSyncErr = firstError;
            }
        }

        private async Task AckAsync(
            string sid,
            string token,
            string status,
            string ticket,
            string err,
            double entryExec = 0,
            double riskMoneyPlanned = 0,
            double volumeLots = 0,
            double requestedSl = 0,
            double usedSl = 0,
            double requestedTp = 0,
            double usedTp = 0,
            double slPips = 0,
            double tpPips = 0
        )
        {
            var accountId = Account != null ? Account.UserId.ToString() : "";
            if (ShouldUseLocalRuntime())
            {
                await RunLocalRuntimeAsync(new Dictionary<string, object>
                {
                    { "operation", "ack" },
                    { "project_root", GetBaseServerRootPath() },
                    { "user_id", LocalRuntimeUserId() },
                    { "account_id", accountId },
                    { "payload", new Dictionary<string, object>
                        {
                            { "trade_id", sid },
                            { "lease_token", token ?? "" },
                            { "execution_status", status },
                            { "broker_trade_id", ticket ?? "" },
                            { "error", err ?? "" },
                            { "message", err ?? "" },
                            { "entry_exec", entryExec },
                            { "risk_money_planned", riskMoneyPlanned },
                            { "volume", volumeLots },
                            { "requested_sl", requestedSl },
                            { "used_sl", usedSl },
                            { "requested_tp", requestedTp },
                            { "used_tp", usedTp },
                            { "sl_pips", slPips },
                            { "tp_pips", tpPips },
                        }
                    },
                });
                return;
            }
            var payload = CTraderSyncEngine.BuildAckPayload(
                GetBridgeIdentityJson(accountId),
                sid,
                token,
                status,
                ticket,
                err,
                entryExec,
                riskMoneyPlanned,
                volumeLots,
                requestedSl,
                usedSl,
                requestedTp,
                usedTp,
                slPips,
                tpPips);
            var content = new StringContent(payload, Encoding.UTF8, "application/json");
            content.Headers.Add("x-api-key", EaApiKey);
            var response = await _httpClient.PostAsync(BuildServerApiUrl("broker/ack"), content);
            if (!response.IsSuccessStatusCode)
            {
                var body = await response.Content.ReadAsStringAsync();
                throw new Exception("HTTP " + ((int)response.StatusCode).ToString(CultureInfo.InvariantCulture) + " " + response.ReasonPhrase + (string.IsNullOrWhiteSpace(body) ? "" : (": " + body)));
            }
        }

        // Reliable ack: runs on thread pool so it completes even inside BeginInvokeOnMainThread
        private void SafeAck(
            string sid,
            string token,
            string status,
            string ticket,
            string err,
            double entryExec = 0,
            double riskMoneyPlanned = 0,
            double volumeLots = 0,
            double requestedSl = 0,
            double usedSl = 0,
            double requestedTp = 0,
            double usedTp = 0,
            double slPips = 0,
            double tpPips = 0
        )
        {
            Task.Run(async () =>
            {
                const int maxAttempts = CTraderSyncEngine.AckMaxAttempts;
                try
                {
                    for (int attempt = 1; attempt <= maxAttempts; attempt++)
                    {
                        try
                        {
                            await AckAsync(
                                sid,
                                token,
                                status,
                                ticket,
                                err,
                                entryExec,
                                riskMoneyPlanned,
                                volumeLots,
                                requestedSl,
                                usedSl,
                                requestedTp,
                                usedTp,
                                slPips,
                                tpPips
                            );
                            if (attempt > 1)
                            {
                                SafeLog(
                                    "INFO",
                                    "[Ack] {0} recovered for {1} on retry {2}/{3}",
                                    status,
                                    sid,
                                    attempt,
                                    maxAttempts
                                );
                            }
                            break;
                        }
                        catch (Exception ex)
                        {
                            if (attempt >= maxAttempts)
                            {
                                ReleaseProcessedLease(sid, token);
                                throw new Exception(
                                    string.Format(
                                        CultureInfo.InvariantCulture,
                                        "ack failed after {0} attempts: {1}",
                                        maxAttempts,
                                        ex.Message
                                    ),
                                    ex
                                );
                            }
                            await Task.Delay(CTraderSyncEngine.ResolveAckRetryDelayMilliseconds(attempt));
                        }
                    }
                    SafeLog(
                        IsErrorStatus(status) ? "ERROR" : "INFO",
                        IsErrorStatus(status) ? "[Error] [Ack] {0} sent for {1}" : "[Ack] {0} sent for {1}",
                        status,
                        sid
                    );
                }
                catch (Exception ex)
                {
                    SafeLog("ERROR", "[Error] [Ack] {0} failed for {1}: {2}", status, sid, ex.Message);
                }
            });
        }

        private void RefreshDebugPanel()
        {
            // Network/trade callbacks only update panel text. Overlay work is owned by the
            // phased timer scheduler so callbacks cannot unexpectedly trigger a full redraw.
            RunOnMainThread(() => RefreshDebugPanelNow(false));
        }

        private void RefreshDebugPanelLite()
        {
            RunOnMainThread(() => RefreshDebugPanelNow(false));
        }

        private void RefreshVisualDashboardAnalysis()
        {
            if (Chart == null || Bars == null || Bars.Count < 3)
                return;

            var symbolName = ResolveSharedStrategySymbol(Chart.SymbolName ?? (Symbol != null ? Symbol.Name : ""));
            if (string.IsNullOrWhiteSpace(symbolName))
                return;

            var timeFrame = Chart.TimeFrame;
            var cacheKey = string.Format(
                CultureInfo.InvariantCulture,
                "{0}|{1}|{2}|{3}",
                symbolName,
                GetMiniChartLabel(timeFrame),
                BuildTradeTriggerClosedBarsKey(symbolName, timeFrame),
                (_toggleStrategyMarkers ? "strategy" : "no-strategy") + "|" + SelectedBacktestStrategy + "|" + BuildDashboardAnalysisToggleKey());
            if (string.Equals(cacheKey, _visualAnalysisCacheKey, StringComparison.Ordinal))
                return;

            var directionalDashboard = BuildDirectionalDashboardTexts(symbolName, timeFrame);
            _buyDashboardText = directionalDashboard.Item1;
            _sellDashboardText = directionalDashboard.Item2;
            if (_toggleStrategyMarkers)
                BuildVisualStrategyDashboardText(symbolName, timeFrame);
            _visualAnalysisCacheKey = cacheKey;
        }

        private Tuple<string, string> BuildDirectionalDashboardTexts(string symbolName, TimeFrame baseTimeFrame)
        {
            var buyItems = new Dictionary<string, DirectionalDashboardItem>(StringComparer.OrdinalIgnoreCase);
            var sellItems = new Dictionary<string, DirectionalDashboardItem>(StringComparer.OrdinalIgnoreCase);
            var selectedRules = new HashSet<StrategyCustomRuleOption>(GetSelectedStrategyCustomRuleOptions());
            var frames = GetTradeTriggerTimeFrames(baseTimeFrame);

            foreach (var timeFrame in frames)
            {
                foreach (var trigger in CollectTradeTriggerCandidates(symbolName, timeFrame))
                {
                    var item = new DirectionalDashboardItem
                    {
                        Category = "T",
                        TypeKey = trigger.Option.ToString(),
                        Text = trigger.Name,
                        BarTime = trigger.BarTime,
                        CloseTime = trigger.BarTime.AddMinutes(Math.Max(1, TimeFrameToMinutes(trigger.SourceTimeFrame))),
                        DirectionKey = trigger.IsDirectionless ? "N" : trigger.IsBullish ? "B" : "S",
                        TimeFrameMinutes = TimeFrameToMinutes(trigger.SourceTimeFrame),
                        Priority = trigger.Priority,
                        Importance = GetDirectionalDashboardTriggerImportance(trigger)
                    };
                    if (trigger.IsDirectionless || trigger.IsBullish)
                        AddMostRecentDirectionalDashboardItem(buyItems, item);
                    if (trigger.IsDirectionless || !trigger.IsBullish)
                        AddMostRecentDirectionalDashboardItem(sellItems, item);
                }

                Bars sourceBars;
                try { sourceBars = GetBarsForCurrentMasterTimer(timeFrame, symbolName); }
                catch { sourceBars = null; }
                var latestClosedIndex = sourceBars != null ? sourceBars.Count - 2 : -1;
                if (sourceBars == null || latestClosedIndex < 1)
                    continue;

                var previous = BuildSharedIndicatorSnapshot(sourceBars, latestClosedIndex - 1);
                var current = BuildSharedIndicatorSnapshot(sourceBars, latestClosedIndex);
                foreach (StrategyCustomRuleOption option in Enum.GetValues(typeof(StrategyCustomRuleOption)))
                {
                    if (option == StrategyCustomRuleOption.Off)
                        continue;

                    var isSoftConfluence = IsStrategySoftConfluenceRule(option);
                    var isSelectedRule = selectedRules.Contains(option);
                    if (!isSoftConfluence && !isSelectedRule && !IsMaterialDirectionalDashboardState(option))
                        continue;

                    AddDirectionalRuleDashboardItem(
                        buyItems,
                        option,
                        symbolName,
                        sourceBars,
                        timeFrame,
                        latestClosedIndex,
                        previous,
                        current,
                        true,
                        isSoftConfluence,
                        isSelectedRule);
                    AddDirectionalRuleDashboardItem(
                        sellItems,
                        option,
                        symbolName,
                        sourceBars,
                        timeFrame,
                        latestClosedIndex,
                        previous,
                        current,
                        false,
                        isSoftConfluence,
                        isSelectedRule);
                }
            }

            return Tuple.Create(
                FormatDirectionalDashboardText(buyItems.Values, baseTimeFrame),
                FormatDirectionalDashboardText(sellItems.Values, baseTimeFrame));
        }

        private void AddDirectionalRuleDashboardItem(
            Dictionary<string, DirectionalDashboardItem> items,
            StrategyCustomRuleOption option,
            string symbolName,
            Bars sourceBars,
            TimeFrame timeFrame,
            int latestClosedIndex,
            SharedIndicatorSnapshot previous,
            SharedIndicatorSnapshot current,
            bool bullish,
            bool isSoftConfluence,
            bool isSelectedRule)
        {
            if (!DashboardRuleSupportsDirection(option, bullish, isSelectedRule))
                return;

            bool matched;
            string label;
            if (!TryEvaluateStrategyCustomRuleOption(
                option,
                symbolName,
                sourceBars,
                timeFrame,
                latestClosedIndex,
                previous,
                current,
                bullish,
                out matched,
                out label) || !matched)
                return;

            var category = isSoftConfluence ? "C" : isSelectedRule ? "R" : "S";
            var compactLabel = string.IsNullOrWhiteSpace(label) ? option.ToString() : label;
            if (isSoftConfluence)
                compactLabel = FormatStrategyConfluenceDirectionLabel(option, compactLabel, bullish);
            var timeFrameLabel = GetMiniChartLabel(timeFrame);
            AddMostRecentDirectionalDashboardItem(items, new DirectionalDashboardItem
            {
                Category = category,
                TypeKey = GetDirectionalDashboardRuleTypeKey(option),
                Text = timeFrameLabel + "." + compactLabel,
                BarTime = sourceBars.OpenTimes[latestClosedIndex],
                TimeFrameMinutes = TimeFrameToMinutes(timeFrame),
                Priority = GetDirectionalDashboardRulePriority(option),
                Importance = 1
            });
        }

        private static int GetDirectionalDashboardTriggerImportance(TradeTriggerEvent trigger)
        {
            if (!trigger.HasCanonicalEvent)
                return 2;
            switch (trigger.CanonicalEvent.EventType)
            {
                case CanonicalEventType.Choch:
                case CanonicalEventType.Bos:
                case CanonicalEventType.SweepReclaim:
                    return 3;
                default:
                    return 2;
            }
        }

        private bool DashboardRuleSupportsDirection(StrategyCustomRuleOption option, bool bullish, bool isSelectedRule)
        {
            if (IsStrategySoftConfluenceRule(option))
                return true;
            switch (option)
            {
                case StrategyCustomRuleOption.__Any_Bullish:
                case StrategyCustomRuleOption.__Bullish:
                case StrategyCustomRuleOption.EMA_SmallAboveLong:
                case StrategyCustomRuleOption.EMA_PriceAboveMid:
                case StrategyCustomRuleOption.VWAP_PriceAbove:
                case StrategyCustomRuleOption.BB_PriceAboveMid:
                case StrategyCustomRuleOption.RSI_Above50:
                case StrategyCustomRuleOption.RSI_Oversold:
                case StrategyCustomRuleOption.LTF_Bullish:
                case StrategyCustomRuleOption.HTF_Bullish:
                    return bullish;
                case StrategyCustomRuleOption.__Any_Bearish:
                case StrategyCustomRuleOption.__Bearish:
                case StrategyCustomRuleOption.EMA_SmallBelowLong:
                case StrategyCustomRuleOption.EMA_PriceBelowMid:
                case StrategyCustomRuleOption.VWAP_PriceBelow:
                case StrategyCustomRuleOption.BB_PriceBelowMid:
                case StrategyCustomRuleOption.RSI_Below50:
                case StrategyCustomRuleOption.RSI_Overbought:
                case StrategyCustomRuleOption.LTF_Bearish:
                case StrategyCustomRuleOption.HTF_Bearish:
                    return !bullish;
                case StrategyCustomRuleOption.LTF_Sideways:
                case StrategyCustomRuleOption.HTF_Sideways:
                    return isSelectedRule;
                default:
                    return false;
            }
        }

        private static bool IsMaterialDirectionalDashboardState(StrategyCustomRuleOption option)
        {
            switch (option)
            {
                case StrategyCustomRuleOption.EMA_SmallAboveLong:
                case StrategyCustomRuleOption.EMA_SmallBelowLong:
                case StrategyCustomRuleOption.VWAP_PriceAbove:
                case StrategyCustomRuleOption.VWAP_PriceBelow:
                case StrategyCustomRuleOption.RSI_Above50:
                case StrategyCustomRuleOption.RSI_Below50:
                case StrategyCustomRuleOption.RSI_Oversold:
                case StrategyCustomRuleOption.RSI_Overbought:
                case StrategyCustomRuleOption.LTF_Bullish:
                case StrategyCustomRuleOption.LTF_Bearish:
                case StrategyCustomRuleOption.HTF_Bullish:
                case StrategyCustomRuleOption.HTF_Bearish:
                    return true;
                default:
                    return false;
            }
        }

        private static string GetDirectionalDashboardRuleTypeKey(StrategyCustomRuleOption option)
        {
            switch (option)
            {
                case StrategyCustomRuleOption.EMA_SmallAboveLong:
                case StrategyCustomRuleOption.EMA_SmallBelowLong:
                    return "EMA_TREND";
                case StrategyCustomRuleOption.VWAP_PriceAbove:
                case StrategyCustomRuleOption.VWAP_PriceBelow:
                    return "VWAP";
                case StrategyCustomRuleOption.RSI_Above50:
                case StrategyCustomRuleOption.RSI_Below50:
                case StrategyCustomRuleOption.RSI_Oversold:
                case StrategyCustomRuleOption.RSI_Overbought:
                    return "RSI";
                case StrategyCustomRuleOption.LTF_Bullish:
                case StrategyCustomRuleOption.LTF_Bearish:
                    return "LTF_BIAS";
                case StrategyCustomRuleOption.HTF_Bullish:
                case StrategyCustomRuleOption.HTF_Bearish:
                    return "HTF_BIAS";
                default:
                    return option.ToString();
            }
        }

        private static int GetDirectionalDashboardRulePriority(StrategyCustomRuleOption option)
        {
            return option == StrategyCustomRuleOption.RSI_Oversold || option == StrategyCustomRuleOption.RSI_Overbought
                ? 2
                : 1;
        }

        private void AddMostRecentDirectionalDashboardItem(
            Dictionary<string, DirectionalDashboardItem> items,
            DirectionalDashboardItem candidate)
        {
            if (items == null || candidate == null || string.IsNullOrWhiteSpace(candidate.Text))
                return;
            var key = string.Equals(candidate.Category, "T", StringComparison.Ordinal)
                ? BuildSimilarTradeTriggerKey(
                    candidate.Text,
                    candidate.CloseTime == DateTime.MinValue
                        ? candidate.BarTime.AddMinutes(Math.Max(1, candidate.TimeFrameMinutes))
                        : candidate.CloseTime,
                    candidate.DirectionKey)
                : string.Format(
                    CultureInfo.InvariantCulture,
                    "{0}|{1}|{2}",
                    candidate.Category,
                    candidate.TimeFrameMinutes,
                    candidate.TypeKey ?? "");
            DirectionalDashboardItem existing;
            if (items.TryGetValue(key, out existing) &&
                (existing.TimeFrameMinutes > candidate.TimeFrameMinutes ||
                 (existing.TimeFrameMinutes == candidate.TimeFrameMinutes &&
                  (existing.BarTime > candidate.BarTime ||
                   (existing.BarTime == candidate.BarTime && existing.Priority >= candidate.Priority)))))
                return;
            items[key] = candidate;
        }

        private string FormatDirectionalDashboardText(IEnumerable<DirectionalDashboardItem> items, TimeFrame baseTimeFrame)
        {
            var baseTimeFrameMinutes = Math.Max(1, TimeFrameToMinutes(baseTimeFrame));
            var values = (items ?? Enumerable.Empty<DirectionalDashboardItem>())
                .Where(item => item != null && !string.IsNullOrWhiteSpace(item.Text))
                .OrderByDescending(item => item.TimeFrameMinutes > baseTimeFrameMinutes)
                .ThenByDescending(item => item.Importance)
                .ThenByDescending(item => item.TimeFrameMinutes)
                .ThenByDescending(item => item.BarTime)
                .ThenByDescending(item => item.Priority)
                .GroupBy(item => item.Text, StringComparer.OrdinalIgnoreCase)
                .Select(group => group.First())
                .ToList();
            if (values.Count == 0)
                return "none";

            const int maxVisibleItems = 5;
            var visible = values.Take(maxVisibleItems).ToList();
            var hiddenCount = Math.Max(0, values.Count - visible.Count);
            var groups = new List<string>();
            var confluenceItems = visible
                .Where(item => !string.Equals(item.Category, "S", StringComparison.Ordinal))
                .Select(item => item.Text)
                .ToList();
            var stateItems = visible
                .Where(item => string.Equals(item.Category, "S", StringComparison.Ordinal))
                .Select(item => item.Text)
                .ToList();
            if (confluenceItems.Count > 0)
                groups.Add("C[" + string.Join(" | ", confluenceItems) + "]");
            if (stateItems.Count > 0)
                groups.Add("S[" + string.Join(" | ", stateItems) + "]");
            return string.Join(" ", groups) +
                (hiddenCount > 0 ? " +" + hiddenCount.ToString(CultureInfo.InvariantCulture) : "");
        }

        private string BuildRecentEventsDashboardText(string symbolName, Bars sourceBars, TimeFrame timeFrame, int latestClosedIndex)
        {
            var matches = new List<string>();
            var recentCanonicalEvents = GetCanonicalEventsForSymbolTimeFrame(symbolName, timeFrame, 256)
                .OrderByDescending(evt => evt.BarTime)
                .ThenByDescending(evt => evt.Score)
                .ToList();
            var firstIndex = latestClosedIndex;

            for (var barIndex = latestClosedIndex; barIndex >= firstIndex; barIndex--)
            {
                var previous = BuildSharedIndicatorSnapshot(sourceBars, barIndex - 1);
                var current = BuildSharedIndicatorSnapshot(sourceBars, barIndex);
                var patterns = GetDetectedSharedRulePatternSet(sourceBars, timeFrame, barIndex);
                var barTime = sourceBars.OpenTimes[barIndex];
                var eventsOnBar = recentCanonicalEvents.Where(evt => evt.BarTime == barTime).ToList();
                foreach (StrategyCustomEventOption option in Enum.GetValues(typeof(StrategyCustomEventOption)))
                {
                    if (option == StrategyCustomEventOption.Off ||
                        option.ToString().StartsWith("__Any", StringComparison.Ordinal) ||
                        !IsDashboardEventOptionEnabled(option))
                        continue;

                    bool bullish;
                    bool bearish;
                    bool directionless;
                    string label;
                    if (!TryEvaluateStrategyCustomEventOption(
                        option,
                        symbolName,
                        sourceBars,
                        timeFrame,
                        barIndex,
                        previous,
                        current,
                        patterns,
                        recentCanonicalEvents,
                        eventsOnBar,
                        out bullish,
                        out bearish,
                        out directionless,
                        out label))
                        continue;

                    if (!bullish && !bearish && !directionless)
                        continue;

                    var direction = bullish && bearish ? "B/S" : bullish ? "B" : bearish ? "S" : "";
                    var item = string.Format(
                        CultureInfo.InvariantCulture,
                        "{0}{1}",
                        string.IsNullOrWhiteSpace(label) ? option.ToString() : label,
                        direction);
                    if (!matches.Contains(item))
                        matches.Add(item);
                }
            }

            return matches.Count == 0 ? "-" : string.Join(", ", matches);
        }

        private string BuildTradeTriggerSequenceDashboardText(string symbolName, TimeFrame timeFrame)
        {
            var sequence = GetTradeTriggerSequence(symbolName, timeFrame);
            return sequence.Count == 0
                ? "none"
                : "[" + string.Join(", ", sequence.Select(item => item.Name)) + "]";
        }

        private string BuildDashboardAnalysisToggleKey()
        {
            return string.Join(
                ",",
                new[]
                {
                    _toggleChochDetections, _toggleBosDetections, _toggleSweepDetections, _toggleRejectionDetections,
                    _toggleBreakoutDetections, _togglePullbackDetections, _toggleContinuationDetections, _toggleImpulseDetections,
                    _togglePinBarPatterns, _toggleEngulfingPatterns, _toggleBigCandlePatterns, _toggleMorningStarPatterns,
                    _toggleEveningStarPatterns, _toggleHammerPatterns, _toggleHangingManPatterns, _toggleShootingStarPatterns,
                    _toggleInvertedHammerPatterns, _togglePiercingLinePatterns, _toggleDarkCloudCoverPatterns,
                    _toggleThreeWhiteSoldiersPatterns, _toggleThreeBlackCrowsPatterns, _toggleHaramiPatterns,
                    _toggleEmaEvents, _toggleVwapEvents, _toggleBollingerEvents, _toggleRsiEvents,
                    _toggleStochasticEvents, _toggleMacdEvents, _toggleDivergence
                }.Select(value => value ? "1" : "0").Concat(
                    GetSelectedStrategyCustomRuleOptions().Select(option => option.ToString())));
        }

        private bool IsDashboardEventOptionEnabled(StrategyCustomEventOption option)
        {
            StrategyCustomEventOption baseOption;
            StrategyEventFollowUpOutcome followUpOutcome;
            var isFollowUp = TryMapStrategyFollowUpEventOption(option, out baseOption, out followUpOutcome);
            if (!isFollowUp)
                baseOption = option;

            CanonicalEventType canonicalType;
            string canonicalLabel;
            if (TryMapStrategyCustomCanonicalEventOption(baseOption, out canonicalType, out canonicalLabel))
            {
                if (!IsCanonicalStructureEventEnabled(canonicalType))
                    return false;
                return DashboardFollowUpMatches(isFollowUp, followUpOutcome, GetStructureEventFollowUpFilter(canonicalType));
            }

            string artifactKind;
            if (TryMapStrategyArtifactReactionEventOption(baseOption, out canonicalType, out artifactKind, out canonicalLabel))
            {
                if (!IsCanonicalStructureEventEnabled(canonicalType))
                    return false;
                return DashboardFollowUpMatches(isFollowUp, followUpOutcome, GetStructureEventFollowUpFilter(canonicalType));
            }

            if (GetCustomEventPatternBarSpan(baseOption) > 0)
            {
                bool enabled;
                StructureEventFollowUpFilter filter;
                GetCandleDashboardVisualState(baseOption, out enabled, out filter);
                return enabled && DashboardFollowUpMatches(isFollowUp, followUpOutcome, filter);
            }

            if (IsIndicatorCustomEventOption(baseOption))
            {
                if (isFollowUp)
                    return false;
                switch (baseOption)
                {
                    case StrategyCustomEventOption.Pxe_PriceEmaCross:
                    case StrategyCustomEventOption.Emx_EmaFastMidCross:
                    case StrategyCustomEventOption.Emt_EmaMidSlowCross:
                        return _toggleEmaEvents;
                    case StrategyCustomEventOption.Vwx_PriceVwapCross:
                    case StrategyCustomEventOption.Vwr_VwapRejection:
                        return _toggleVwapEvents;
                    case StrategyCustomEventOption.Bbx_BollingerMidCross:
                    case StrategyCustomEventOption.Bbr_BollingerBandReject:
                        return _toggleBollingerEvents;
                    case StrategyCustomEventOption.R50_RsiMidlineCross:
                    case StrategyCustomEventOption.Ros_RsiExitOversold:
                    case StrategyCustomEventOption.Rob_RsiExitOverbought:
                        return _toggleRsiEvents;
                    case StrategyCustomEventOption.Stx_StochCross:
                    case StrategyCustomEventOption.Sto_StochExitExtreme:
                        return _toggleStochasticEvents;
                    case StrategyCustomEventOption.Mdx_MacdSignalCross:
                    case StrategyCustomEventOption.Md0_MacdZeroCross:
                        return _toggleMacdEvents;
                    case StrategyCustomEventOption.Div_Divergence:
                        return _toggleDivergence;
                    default:
                        return false;
                }
            }

            return false;
        }

        private static bool DashboardFollowUpMatches(bool isFollowUp, StrategyEventFollowUpOutcome outcome, StructureEventFollowUpFilter filter)
        {
            if (filter == StructureEventFollowUpFilter.Any)
                return !isFollowUp;
            if (!isFollowUp)
                return false;
            return filter == StructureEventFollowUpFilter.Continue
                ? outcome == StrategyEventFollowUpOutcome.Continue
                : outcome == StrategyEventFollowUpOutcome.Reverse;
        }

        private StructureEventFollowUpFilter GetStructureEventFollowUpFilter(CanonicalEventType eventType)
        {
            switch (eventType)
            {
                case CanonicalEventType.Choch: return _chochEventFollowUpFilter;
                case CanonicalEventType.Bos: return _bosEventFollowUpFilter;
                case CanonicalEventType.SweepReclaim: return _sweepEventFollowUpFilter;
                case CanonicalEventType.Rejection: return _rejectionEventFollowUpFilter;
                case CanonicalEventType.Breakout: return _breakoutEventFollowUpFilter;
                case CanonicalEventType.Pullback: return _pullbackEventFollowUpFilter;
                case CanonicalEventType.Continuation: return _continuationEventFollowUpFilter;
                case CanonicalEventType.Impulse: return _impulseEventFollowUpFilter;
                default: return StructureEventFollowUpFilter.Any;
            }
        }

        private void GetCandleDashboardVisualState(StrategyCustomEventOption option, out bool enabled, out StructureEventFollowUpFilter filter)
        {
            enabled = false;
            filter = StructureEventFollowUpFilter.Any;
            switch (option)
            {
                case StrategyCustomEventOption.Pin_PinBar: enabled = _togglePinBarPatterns; filter = _pinBarPatternFollowUpFilter; break;
                case StrategyCustomEventOption.Eng_Engulfing: enabled = _toggleEngulfingPatterns; filter = _engulfingPatternFollowUpFilter; break;
                case StrategyCustomEventOption.Big_BigCandle: enabled = _toggleBigCandlePatterns; filter = _bigCandlePatternFollowUpFilter; break;
                case StrategyCustomEventOption.Mor_MorningStar: enabled = _toggleMorningStarPatterns; filter = _morningStarPatternFollowUpFilter; break;
                case StrategyCustomEventOption.Eve_EveningStar: enabled = _toggleEveningStarPatterns; filter = _eveningStarPatternFollowUpFilter; break;
                case StrategyCustomEventOption.Ham_Hammer: enabled = _toggleHammerPatterns; filter = _hammerPatternFollowUpFilter; break;
                case StrategyCustomEventOption.Hgm_HangingMan: enabled = _toggleHangingManPatterns; filter = _hangingManPatternFollowUpFilter; break;
                case StrategyCustomEventOption.Sst_ShootingStar: enabled = _toggleShootingStarPatterns; filter = _shootingStarPatternFollowUpFilter; break;
                case StrategyCustomEventOption.Ihm_InvertedHammer: enabled = _toggleInvertedHammerPatterns; filter = _invertedHammerPatternFollowUpFilter; break;
                case StrategyCustomEventOption.Prc_PiercingLine: enabled = _togglePiercingLinePatterns; filter = _piercingLinePatternFollowUpFilter; break;
                case StrategyCustomEventOption.Dcc_DarkCloudCover: enabled = _toggleDarkCloudCoverPatterns; filter = _darkCloudCoverPatternFollowUpFilter; break;
                case StrategyCustomEventOption.Tws_ThreeWhiteSoldiers: enabled = _toggleThreeWhiteSoldiersPatterns; filter = _threeWhiteSoldiersPatternFollowUpFilter; break;
                case StrategyCustomEventOption.Tbc_ThreeBlackCrows: enabled = _toggleThreeBlackCrowsPatterns; filter = _threeBlackCrowsPatternFollowUpFilter; break;
                case StrategyCustomEventOption.Har_Harami: enabled = _toggleHaramiPatterns; filter = _haramiPatternFollowUpFilter; break;
            }
        }

        private string BuildRecentConfluenceDashboardText(string symbolName, Bars sourceBars, TimeFrame timeFrame, int latestClosedIndex)
        {
            var matches = new List<string>();
            var tradeDirection = GetTradeTriggerSequence(symbolName, timeFrame)
                .Where(item => !item.IsDirectionless)
                .Select(item => (bool?)item.IsBullish)
                .FirstOrDefault();
            var firstIndex = latestClosedIndex;
            for (var barIndex = latestClosedIndex; barIndex >= firstIndex; barIndex--)
            {
                var previous = BuildSharedIndicatorSnapshot(sourceBars, barIndex - 1);
                var current = BuildSharedIndicatorSnapshot(sourceBars, barIndex);
                foreach (StrategyCustomRuleOption option in Enum.GetValues(typeof(StrategyCustomRuleOption)))
                {
                    if (option == StrategyCustomRuleOption.Off)
                        continue;

                    var directional = IsStrategySoftConfluenceRule(option);
                    if (directional && tradeDirection.HasValue)
                    {
                        bool aligned;
                        string alignmentLabel;
                        if (TryEvaluateStrategyCustomRuleOption(
                            option,
                            symbolName,
                            sourceBars,
                            timeFrame,
                            barIndex,
                            previous,
                            current,
                            tradeDirection,
                            out aligned,
                            out alignmentLabel))
                        {
                            var alignment = FormatStrategyConfluenceAlignmentLabel(option, alignmentLabel, aligned);
                            if (!matches.Contains(alignment))
                                matches.Add(alignment);
                        }
                        continue;
                    }

                    var directions = directional ? new bool?[] { true, false } : new bool?[] { null };
                    foreach (var requiredBullish in directions)
                    {
                        bool matched;
                        string label;
                        if (!TryEvaluateStrategyCustomRuleOption(
                            option,
                            symbolName,
                            sourceBars,
                            timeFrame,
                            barIndex,
                            previous,
                            current,
                            requiredBullish,
                            out matched,
                            out label) || !matched)
                            continue;

                        var item = directional && requiredBullish.HasValue
                            ? FormatStrategyConfluenceDirectionLabel(option, label, requiredBullish.Value)
                            : (string.IsNullOrWhiteSpace(label) ? option.ToString() : label);
                        if (!matches.Contains(item))
                            matches.Add(item);
                    }
                }
            }

            return matches.Count == 0 ? "none" : string.Join(", ", matches);
        }

        private string BuildVisualStrategyDashboardText(string symbolName, TimeFrame timeFrame)
        {
            var mode = SelectedBacktestStrategy;
            if (mode == BacktestStrategyMode.Off)
                return "off";
            if (mode == BacktestStrategyMode.PriceActionEventDetectorV1 ||
                mode == BacktestStrategyMode.AiSnapshotContextV1)
                return "detector only";

            BacktestStrategySignal signal;
            if (!TryBuildVisualOnlyStrategySignal(symbolName, timeFrame, mode, out signal) || !signal.IsValid)
                return "no signal";

            var direction = signal.TradeType == TradeType.Buy ? "BUY" : "SELL";
            AddVisualOnlyStrategyMarker(symbolName, mode, signal);
            return string.Format(CultureInfo.InvariantCulture, "{0}:{1}", GetBacktestStrategyModeDisplayName(mode), direction);
        }

        private bool TryBuildVisualOnlyStrategySignal(string symbolName, TimeFrame timeFrame, BacktestStrategyMode mode, out BacktestStrategySignal signal)
        {
            signal = default(BacktestStrategySignal);
            var matched = false;
            switch (mode)
            {
                case BacktestStrategyMode.CustomTrade:
                    matched = TryBuildCustomTradeSignal(symbolName, timeFrame, out signal);
                    break;
                case BacktestStrategyMode.HtfEventMarket:
                case BacktestStrategyMode.LtfEventMarket:
                case BacktestStrategyMode.PriceActionEventDetectorV1:
                {
                    CanonicalMarketEvent evt;
                    matched = mode == BacktestStrategyMode.HtfEventMarket
                        ? TryGetLatestBacktestStrategyEvent(symbolName, timeFrame, out evt)
                        : TryGetLatestBacktestStrategyEventForTimeFrames(symbolName, new[] { timeFrame }, out evt);
                    if (matched)
                    {
                        signal = new BacktestStrategySignal
                        {
                            IsValid = true,
                            StrategyMode = mode,
                            StrategyId = mode.ToString(),
                            SymbolName = symbolName,
                            SourceLabel = BuildCanonicalMarketEventName(evt),
                            TradeType = evt.IsBullish ? TradeType.Buy : TradeType.Sell,
                            SourceTimeFrame = evt.SourceTimeFrame,
                            SignalTime = evt.BarTime
                        };
                    }
                    break;
                }
                case BacktestStrategyMode.Trend:
                case BacktestStrategyMode.Impulse:
                    matched = TryBuildEventDrivenStrategySignal(symbolName, timeFrame, mode, out signal);
                    break;
                case BacktestStrategyMode.PriceActionV1:
                    matched = TryBuildPriceActionTriggerSignal(symbolName, timeFrame, "price_action_v1", false, 1, 1, false, out signal);
                    break;
                case BacktestStrategyMode.PriceActionFvgContextV1:
                    matched = TryBuildPriceActionFvgContextSignal(symbolName, timeFrame, out signal);
                    break;
                case BacktestStrategyMode.ArtifactSuggestedLevelsV1:
                    matched = TryBuildPriceActionTriggerSignal(symbolName, timeFrame, "artifact_suggested_levels_v1", true, 1, 1, false, out signal);
                    break;
                case BacktestStrategyMode.ArtifactSuggestedLevelsV2:
                    matched = TryBuildPriceActionTriggerSignal(symbolName, timeFrame, "artifact_suggested_levels_v2", true, 2, 2, false, out signal);
                    break;
                case BacktestStrategyMode.ArtifactSuggestedLevelsV2LimitBodyMid:
                    matched = TryBuildPriceActionTriggerSignal(symbolName, timeFrame, "artifact_suggested_levels_v2_limit_body_mid", true, 2, 2, true, out signal);
                    break;
                default:
                    matched = TryBuildIndicatorStrategySignal(symbolName, timeFrame, mode, out signal);
                    break;
            }

            if (!matched || !signal.IsValid)
                return false;

            signal.StrategyMode = mode;
            signal.SymbolName = symbolName;
            if (!IsVisualStrategySignalOnLatestClosedBar(symbolName, signal))
                return false;
            if (IsPriceActionTriggerStrategy(mode) && !HasLatestClosedPriceActionTrigger(symbolName, timeFrame, signal.TradeType))
                return false;
            if (mode == BacktestStrategyMode.CustomTrade || mode == BacktestStrategyMode.PriceActionEventDetectorV1)
                return true;
            if (mode == BacktestStrategyMode.HtfEventMarket || mode == BacktestStrategyMode.LtfEventMarket)
                return TryPassStrategyCustomEventGate(symbolName, timeFrame, signal.TradeType);
            return TryApplyStrategyCustomEventGate(symbolName, timeFrame, ref signal);
        }

        private bool IsVisualStrategySignalOnLatestClosedBar(string symbolName, BacktestStrategySignal signal)
        {
            if (signal.SignalTime == DateTime.MinValue || signal.SourceTimeFrame == null)
                return false;

            try
            {
                var sourceBars = GetBarsForCurrentMasterTimer(signal.SourceTimeFrame, symbolName);
                if (sourceBars == null || sourceBars.Count < 2)
                    return false;
                return sourceBars.OpenTimes[sourceBars.Count - 2] == signal.SignalTime;
            }
            catch
            {
                return false;
            }
        }

        private static bool IsPriceActionTriggerStrategy(BacktestStrategyMode mode)
        {
            return mode == BacktestStrategyMode.PriceActionV1 ||
                mode == BacktestStrategyMode.ArtifactSuggestedLevelsV1 ||
                mode == BacktestStrategyMode.ArtifactSuggestedLevelsV2 ||
                mode == BacktestStrategyMode.ArtifactSuggestedLevelsV2LimitBodyMid;
        }

        private bool HasLatestClosedPriceActionTrigger(string symbolName, TimeFrame timeFrame, TradeType tradeType)
        {
            Symbol symbol;
            Bars sourceBars;
            int signalIndex;
            int previousIndex;
            if (!TryGetBacktestStrategyBars(symbolName, timeFrame, out symbol, out sourceBars, out signalIndex, out previousIndex))
                return false;

            var bullish = tradeType == TradeType.Buy;
            var patternMatch = bullish
                ? IsBullishPinBar(sourceBars, signalIndex) || IsBullishEngulfing(sourceBars, previousIndex, signalIndex)
                : IsBearishPinBar(sourceBars, signalIndex) || IsBearishEngulfing(sourceBars, previousIndex, signalIndex);
            if (patternMatch)
                return true;

            var signalTime = sourceBars.OpenTimes[signalIndex];
            return GetCanonicalEventsForSymbolTimeFrame(symbolName, timeFrame, 24)
                .Any(evt =>
                    evt.BarTime == signalTime &&
                    evt.IsBullish == bullish &&
                    (evt.EventType == CanonicalEventType.Bos || evt.EventType == CanonicalEventType.Choch));
        }

        private void AddVisualOnlyStrategyMarker(string symbolName, BacktestStrategyMode mode, BacktestStrategySignal signal)
        {
            var signalTime = signal.SignalTime == DateTime.MinValue && Bars != null && Bars.Count >= 2
                ? Bars.OpenTimes[Bars.Count - 2]
                : signal.SignalTime;
            var markerPrice = signal.EntryPrice;
            if (!(markerPrice > 0) && Bars != null && Bars.Count >= 2)
                markerPrice = Bars.ClosePrices[Bars.Count - 2];

            AddStrategyChartMarker(new StrategyChartMarker
            {
                PositionId = BuildVisualStrategyMarkerId(symbolName, mode, signal.TradeType, signalTime),
                SymbolName = symbolName,
                TradeType = signal.TradeType,
                Kind = StrategyMarkerKind.Entry,
                Time = signalTime,
                Price = markerPrice,
                Text = string.Format(
                    CultureInfo.InvariantCulture,
                    "{0} {1}",
                    CompactPanelText(GetBacktestStrategyModeDisplayName(mode), 12),
                    signal.TradeType == TradeType.Buy ? "B" : "S")
            });
        }

        private void AddCustomTradeTriggerMarker(string symbolName, BacktestStrategySignal signal)
        {
            if (string.IsNullOrWhiteSpace(symbolName) || signal.SignalTime == DateTime.MinValue)
                return;

            var markerPrice = signal.EntryPrice;
            try
            {
                var sourceBars = GetBarsForCurrentMasterTimer(signal.SourceTimeFrame, symbolName);
                var triggerIndex = ResolveSourceBarIndex(sourceBars, signal.SignalTime);
                if (IsValidBarIndex(sourceBars, triggerIndex))
                    markerPrice = signal.TradeType == TradeType.Buy
                        ? sourceBars.LowPrices[triggerIndex]
                        : sourceBars.HighPrices[triggerIndex];
            }
            catch
            {
            }

            AddStrategyChartMarker(new StrategyChartMarker
            {
                PositionId = BuildVisualStrategyMarkerId(symbolName, BacktestStrategyMode.CustomTrade, signal.TradeType, signal.SignalTime),
                SymbolName = symbolName,
                TradeType = signal.TradeType,
                Kind = StrategyMarkerKind.Trigger,
                Time = signal.SignalTime,
                Price = markerPrice,
                Text = signal.SourceLabel ?? "event"
            });
        }

        private static long BuildVisualStrategyMarkerId(string symbolName, BacktestStrategyMode mode, TradeType tradeType, DateTime signalTime)
        {
            unchecked
            {
                long hash = 1469598103934665603L;
                var value = string.Format(CultureInfo.InvariantCulture, "{0}|{1}|{2}|{3}", symbolName, mode, tradeType, signalTime.Ticks);
                foreach (var character in value)
                    hash = (hash ^ character) * 1099511628211L;
                return hash > 0 ? -hash : hash;
            }
        }

        private void RefreshDebugPanelNow()
        {
            RefreshDebugPanelNow(true, true);
        }

        private void RefreshDebugPanelNow(bool includeVisualOverlays)
        {
            RefreshDebugPanelNow(includeVisualOverlays, includeVisualOverlays);
        }

        private ChartStaticText DrawStaticTextIfChanged(
            string objectName,
            string text,
            VerticalAlignment verticalAlignment,
            HorizontalAlignment horizontalAlignment,
            Color color,
            ref string lastText,
            ref string lastColorKey)
        {
            return CTraderChartEngine.DrawStaticTextIfChanged(
                Chart, objectName, text, verticalAlignment, horizontalAlignment, color,
                ref lastText, ref lastColorKey);
        }

        private void RefreshDebugPanelNow(bool includeVisualOverlays, bool refreshAnalysis)
        {
            try
            {
                var isBacktesting = IsBacktestingRuntime();
                if (isBacktesting)
                    return;
                var dashboardAnalysisNeedsInitialization = string.IsNullOrWhiteSpace(_visualAnalysisCacheKey);
                if (AreChartVisualsEnabled() && (refreshAnalysis || dashboardAnalysisNeedsInitialization))
                {
                    try
                    {
                        RefreshVisualDashboardAnalysis();
                    }
                    catch (Exception ex)
                    {
                        _visualAnalysisCacheKey = "";
                        if (string.Equals(_buyDashboardText, "loading", StringComparison.OrdinalIgnoreCase))
                            _buyDashboardText = "retry";
                        if (string.Equals(_sellDashboardText, "loading", StringComparison.OrdinalIgnoreCase))
                            _sellDashboardText = "retry";
                        SafePrint("[Dashboard] Directional analysis failed; retrying: {0}", ex.Message);
                    }
                }
                if (includeVisualOverlays)
                    DrawChartVisualOverlays();

                if (!_legacyDashboardObjectsCleaned)
                {
                    foreach (var objectName in new[]
                    {
                        "Panel_HEARTBEAT", "Panel_TR", "Panel_DBG_HDR", "Panel_DBG_BODY", "Panel_DBG_MSG",
                        "Panel_GATE_HDR", "Panel_GATE_BODY", "Panel_GATE_ROW1", "Panel_GATE_ROW2", "Panel_GATE_ROW3",
                        "Panel_GATE_ROW4", "Panel_GATE_ROW5", "Panel_GATE_SUM_HDR", "Panel_GATE_SUM_BODY",
                        "Panel_GATE_SUM_SYM", "Panel_GATE_SUM_WIN", "Panel_GATE_SUM_LOSE", "Panel_TL", "Panel_BL",
                        "Panel_BR", "Panel_ERR"
                    })
                        Chart.RemoveObject(objectName);
                    _legacyDashboardObjectsCleaned = true;
                }

                if (!AreChartVisualsEnabled())
                {
                    Chart.RemoveObject("Panel_GATE");
                    Chart.RemoveObject("Panel_QUEUE");
                    Chart.RemoveObject("Panel_DBG");
                    return;
                }

                var riskState = BuildPanelRiskGateStateSafe();
                if (isBacktesting)
                {
                    if (!string.IsNullOrWhiteSpace(_lastPanelMessage) && !string.Equals(_lastPanelMessage, "Ready", StringComparison.OrdinalIgnoreCase))
                    {
                        var backtestMessagePanel = Chart.DrawStaticText(
                            "Panel_DBG",
                            _lastPanelMessage,
                            _lastPanelMessageIsError ? VerticalAlignment.Bottom : VerticalAlignment.Top,
                            _lastPanelMessageIsError ? HorizontalAlignment.Right : HorizontalAlignment.Left,
                            _lastPanelMessageColor);
                        TryStyleChartText(backtestMessagePanel, 10, "Courier New", false);
                        TrySetPropertyValue(backtestMessagePanel, "Margin", "0 -8 0 0");
                    }

                    var backtestGateLines = BuildRiskDashboardLines(riskState);
                    var backtestMetricText = string.Join(Environment.NewLine, backtestGateLines);
                    if (!string.IsNullOrWhiteSpace(backtestMetricText))
                    {
                        var backtestMetricPanel = Chart.DrawStaticText("Panel_GATE", backtestMetricText, VerticalAlignment.Top, HorizontalAlignment.Center, Color.White);
                        TryStyleChartText(backtestMetricPanel, 9, "Courier New", false);
                        TrySetPropertyValue(backtestMetricPanel, "Margin", "0 -8 0 0");
                    }
                    if (includeVisualOverlays)
                        RefreshChartSummaryPanel(riskState);
                    return;
                }

                Func<string, string> compactStatus = status =>
                {
                    if (string.IsNullOrWhiteSpace(status)) return "?";
                    var s = status.Trim().ToUpperInvariant();
                    if (s == "WAITING") return "WAIT";
                    if (s == "POLLING") return "POLL";
                    if (s == "SYNCING") return "SYNC";
                    if (s == "UNREACHABLE") return "DOWN";
                    if (s.StartsWith("FAIL", StringComparison.Ordinal)) return "FAIL";
                    return s;
                };

                var panelHeader = string.Format(
                    CultureInfo.InvariantCulture,
                    "v{0} {1}",
                    BuildVersion,
                    DateTime.Now.ToString("HH:mm:ss"));
                var serverLine = Is42TradeServerSyncEnabled()
                    ? string.Format(
                        CultureInfo.InvariantCulture,
                        "Server:{0} API:{1} PULL:{2} SYNC:{3}",
                        compactStatus(_serverStatus),
                        compactStatus(_apiStatus),
                        compactStatus(_pollStatus),
                        compactStatus(_syncStatus))
                    : "Server: disabled";

                var leftPanel = new StringBuilder();
                leftPanel.AppendLine(panelHeader);
                leftPanel.AppendLine(serverLine);
                leftPanel.AppendLine(GetBottomRightSessionContextText() + " | " + GetBottomRightNewsContextText(DateTime.Now));
                leftPanel.AppendLine("Scan: " + BuildStrategyScanDashboardText());
                var dashboardSymbolName = ResolveSharedStrategySymbol(Chart.SymbolName ?? (Symbol != null ? Symbol.Name : ""));
                leftPanel.AppendLine("Triggers: " + BuildTradeTriggerSequenceDashboardText(dashboardSymbolName, Chart.TimeFrame));
                leftPanel.AppendLine("Buy: " + (string.IsNullOrWhiteSpace(_buyDashboardText) ? "-" : _buyDashboardText));
                leftPanel.AppendLine("Sell: " + (string.IsNullOrWhiteSpace(_sellDashboardText) ? "-" : _sellDashboardText));
                if (!string.IsNullOrWhiteSpace(_lastPanelMessage) && !string.Equals(_lastPanelMessage, "Ready", StringComparison.OrdinalIgnoreCase))
                    leftPanel.AppendLine((_lastPanelMessageIsError ? "! " : "M ") + CompactPanelDebugMessage(_lastPanelMessage));
                var debugPanelColor =
                    (_lastPanelMessageIsError ||
                     _serverStatus == "OFFLINE" ||
                     _serverStatus == "CLIENT_ERR" ||
                     _apiStatus == "UNREACHABLE" ||
                     _apiStatus == "PREP_ERR" ||
                     _pollStatus == "FAIL" ||
                     _pollStatus == "ERROR" ||
                     _syncStatus == "FAIL" ||
                     _syncStatus == "ERROR")
                        ? Color.Red
                        : _lastPanelMessageColor;
                var debugPanelText = leftPanel.ToString();
                var debugPanel = DrawStaticTextIfChanged("Panel_DBG", debugPanelText, VerticalAlignment.Bottom, HorizontalAlignment.Right, debugPanelColor, ref _lastDrawnDebugPanelText, ref _lastDrawnDebugPanelColorKey);
                if (debugPanel != null)
                    TryStyleChartText(debugPanel, 10, "Courier New", false);

                var metricText = string.Join(Environment.NewLine, BuildRiskDashboardLines(riskState));
                if (!string.IsNullOrWhiteSpace(metricText))
                {
                    if (!string.Equals(_lastDrawnMetricPanelText, metricText, StringComparison.Ordinal))
                    {
                        _lastDrawnMetricPanelText = metricText;
                        var metricPanel = Chart.DrawStaticText("Panel_GATE", metricText, VerticalAlignment.Top, HorizontalAlignment.Center, Color.White);
                        TryStyleChartText(metricPanel, 9, "Courier New", false);
                        TrySetPropertyValue(metricPanel, "Margin", "0 -8 0 0");
                    }
                }

                var queueText = BuildStrategyActionQueueDashboardText();
                if (!string.Equals(_lastDrawnQueuePanelText, queueText, StringComparison.Ordinal))
                {
                    _lastDrawnQueuePanelText = queueText;
                    var queuePanel = Chart.DrawStaticText("Panel_QUEUE", queueText, VerticalAlignment.Top, HorizontalAlignment.Right, Color.LightGray);
                    TryStyleChartText(queuePanel, 9, "Courier New", false);
                    TrySetPropertyValue(queuePanel, "Margin", "0 -8 0 0");
                }

                if (includeVisualOverlays)
                    RefreshChartSummaryPanel(riskState);
            }
            catch (Exception ex)
            {
                SafeLog("WARN", "[Panel] Draw failed: {0}", ex.Message);
            }
        }

        private static string BuildChartCacheKey(params object[] parts)
        {
            return string.Join("|", parts.Select(p => p == null ? "" : Convert.ToString(p, CultureInfo.InvariantCulture) ?? ""));
        }

        private List<T> GetOrCreateTimedCacheValue<T>(
            Dictionary<string, TimedCacheEntry<List<T>>> cache,
            string key,
            TimeSpan ttl,
            Func<List<T>> factory)
        {
            return CTraderCacheEngine.GetOrCreateTimedList(cache, key, ttl, factory);
        }

        private void LogSlowChartStep(string stepName, Stopwatch stopwatch, string detail = null)
        {
            if (stopwatch == null)
                return;

            stopwatch.Stop();
            if (stopwatch.ElapsedMilliseconds < 120)
                return;

            if (string.IsNullOrWhiteSpace(detail))
                SafePrint("[Perf] {0}: {1}ms", stepName, stopwatch.ElapsedMilliseconds);
            else
                SafePrint("[Perf] {0}: {1}ms ({2})", stepName, stopwatch.ElapsedMilliseconds, detail);
        }

        private string GetJsonValue(string json, string key)
        {
            var m = Regex.Match(json, string.Format("\"{0}\"\\s*:\\s*\"?([^,\"]*)\"?", key));
            return m.Success ? m.Groups[1].Value.Trim() : "";
        }

        private void EnsureSharedConfigCatalogLoaded()
        {
            if (_sharedCatalogLoaded)
                return;

            try
            {
                var configRoot = GetBaseServerConfigPath();
                var stopwatch = Stopwatch.StartNew();
                LoadSharedConfigDirectory(Path.Combine(configRoot, "rules"), _sharedRuleCatalog);
                LoadSharedConfigDirectory(Path.Combine(configRoot, "events"), _sharedEventCatalog);
                LoadSharedConfigDirectory(Path.Combine(configRoot, "strategies"), _sharedStrategyCatalog);
                _sharedCatalogLoaded = true;
                stopwatch.Stop();
                LogPerfStep(
                    "SharedCatalogLoad",
                    stopwatch.ElapsedMilliseconds,
                    string.Format(
                        CultureInfo.InvariantCulture,
                        "rules={0} events={1} strategies={2}",
                        _sharedRuleCatalog.Count,
                        _sharedEventCatalog.Count,
                        _sharedStrategyCatalog.Count),
                    5);
            }
            catch (Exception ex)
            {
                SafeLog("ERROR", "[SharedCatalog] Load failed: {0}", ex.Message);
            }
        }

        private void LoadSharedConfigDirectory(string directoryPath, Dictionary<string, Dictionary<string, object>> destination)
        {
            if (destination == null)
                return;

            var loaded = new Dictionary<string, Dictionary<string, object>>(StringComparer.OrdinalIgnoreCase);
            if (Directory.Exists(directoryPath))
            {
                foreach (var filePath in Directory.GetFiles(directoryPath, "*.json", SearchOption.TopDirectoryOnly))
                {
                    try
                    {
                        var parsed = CTraderRuleEngine.ParseJson(System.IO.File.ReadAllText(filePath)) as Dictionary<string, object>;
                        if (parsed == null)
                            continue;
                        var id = ConvertToInvariantString(GetDictionaryValue(parsed, "id"));
                        if (string.IsNullOrWhiteSpace(id))
                            id = ConvertToInvariantString(GetDictionaryValue(parsed, "key"));
                        if (string.IsNullOrWhiteSpace(id))
                            id = Path.GetFileNameWithoutExtension(filePath);
                        if (!string.IsNullOrWhiteSpace(id))
                            loaded[id.Trim()] = parsed;
                    }
                    catch (Exception ex)
                    {
                        SafeLog("ERROR", "[SharedCatalog] Invalid file {0}: {1}", filePath, ex.Message);
                    }
                }
            }

            destination.Clear();
            foreach (var pair in loaded)
                destination[pair.Key] = pair.Value;
        }

        private List<string> GetConfiguredSharedStrategyIds()
        {
            var requested = Regex.Split(SharedStrategyConfigIds ?? "", "[,;\\s]+")
                .Select(value => (value ?? "").Trim())
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (requested.Any(value => value == "*"))
            {
                return _sharedStrategyCatalog
                    .Where(pair => SharedConfigStrategyIsActive(pair.Value))
                    .Select(pair => pair.Key)
                    .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                    .ToList();
            }
            return requested;
        }

        private bool SharedConfigStrategyIsActive(Dictionary<string, object> strategy)
        {
            var status = ConvertToInvariantString(GetDictionaryValue(strategy, "status"));
            return string.IsNullOrWhiteSpace(status) || string.Equals(status, "active", StringComparison.OrdinalIgnoreCase);
        }

        private bool SharedConfigDefinitionHasOpenTradeAction(Dictionary<string, object> definition)
        {
            var actions = GetDictionaryValue(definition, "actions") as List<object>;
            if (actions == null || actions.Count == 0)
                return false;

            foreach (var rawAction in actions)
            {
                Dictionary<string, object> action;
                if (!TryGetRuleObject(rawAction, out action))
                    continue;
                var actionName = ConvertToInvariantString(GetDictionaryValue(action, "action")).Trim().ToLowerInvariant();
                if (actionName == "trade" || actionName.StartsWith("trade.open", StringComparison.Ordinal))
                    return true;
            }
            return false;
        }

        private bool TryResolveSharedConfigStrategy(
            string symbolName,
            TimeFrame strategyTimeFrame,
            Bars sourceBars,
            int latestClosedIndex,
            TradeType? preferredTradeType,
            out TradeType resolvedTradeType,
            out DateTime signalTime,
            out string sourceLabel,
            out string note,
            out double eventSlDistance)
        {
            resolvedTradeType = TradeType.Buy;
            signalTime = DateTime.MinValue;
            sourceLabel = "";
            note = "";
            eventSlDistance = 0;
            EnsureSharedConfigCatalogLoaded();

            foreach (var strategyId in GetConfiguredSharedStrategyIds())
            {
                Dictionary<string, object> strategy;
                if (!_sharedStrategyCatalog.TryGetValue(strategyId, out strategy) || strategy == null)
                {
                    LogStrategyInfoOnce("shared_missing", strategyId, "shared strategy file not found");
                    continue;
                }
                if (!SharedConfigStrategyIsActive(strategy) || !SharedConfigStrategyMatchesMarket(strategy, symbolName, strategyTimeFrame))
                    continue;

                Symbol resolvedSymbol;
                TryResolveQuotedSymbol(symbolName, out resolvedSymbol);
                var context = BuildSharedRuleContext(sourceBars, latestClosedIndex, resolvedSymbol, strategyTimeFrame, null);
                var parameters = GetDictionaryValue(strategy, "params") as Dictionary<string, object>;
                context["params"] = parameters ?? new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
                context["strategy"] = strategy;
                PopulateSharedConfigIndicators(context, strategy, sourceBars, latestClosedIndex);

                var definitions = new List<object>();
                var rules = GetDictionaryValue(strategy, "rules") as List<object>;
                var events = GetDictionaryValue(strategy, "events") as List<object>;
                if (rules != null) definitions.AddRange(rules);
                if (events != null) definitions.AddRange(events);

                foreach (var rawDefinition in definitions)
                {
                    Dictionary<string, object> definition;
                    if (!TryGetRuleObject(rawDefinition, out definition))
                        continue;
                    if (!SharedConfigDefinitionHasOpenTradeAction(definition))
                        continue;
                    TradeType direction;
                    if (!TryResolveSharedConfigTradeType(definition, preferredTradeType, out direction))
                        continue;
                    if (preferredTradeType.HasValue && preferredTradeType.Value != direction)
                        continue;

                    var requireBullishDirection = direction == TradeType.Buy;
                    var result = EvaluateSharedConfigDefinition(
                        definition,
                        context,
                        symbolName,
                        sourceBars,
                        strategyTimeFrame,
                        latestClosedIndex,
                        requireBullishDirection);
                    if (result == null || !result.Matched)
                        continue;
                    if (string.Equals(result.Direction, "bullish", StringComparison.OrdinalIgnoreCase) && !requireBullishDirection)
                        continue;
                    if (string.Equals(result.Direction, "bearish", StringComparison.OrdinalIgnoreCase) && requireBullishDirection)
                        continue;

                    var previousSnapshot = BuildSharedIndicatorSnapshot(sourceBars, Math.Max(0, latestClosedIndex - 1));
                    var currentSnapshot = BuildSharedIndicatorSnapshot(sourceBars, latestClosedIndex);
                    if (!TryPassSelectedStrategyCustomRules(
                        symbolName,
                        sourceBars,
                        strategyTimeFrame,
                        latestClosedIndex,
                        previousSnapshot,
                        currentSnapshot,
                        requireBullishDirection))
                    {
                        SafePrint(
                            "[SharedStrategy] Reject {0} {1} {2}: selected_confluence_failed",
                            strategyId,
                            symbolName,
                            requireBullishDirection ? "BUY" : "SELL");
                        continue;
                    }

                    resolvedTradeType = direction;
                    signalTime = sourceBars.OpenTimes[latestClosedIndex];
                    var definitionId = ConvertToInvariantString(GetDictionaryValue(definition, "id"));
                    sourceLabel = strategyId + ":" + (string.IsNullOrWhiteSpace(definitionId) ? "signal" : definitionId);
                    note = string.Format(CultureInfo.InvariantCulture, "[shared_strategy={0}]", sourceLabel);
                    eventSlDistance = Math.Max(sourceBars.HighPrices[latestClosedIndex] - sourceBars.LowPrices[latestClosedIndex], 0);
                    return true;
                }
            }
            return false;
        }

        private bool SharedConfigStrategyMatchesMarket(Dictionary<string, object> strategy, string symbolName, TimeFrame timeFrame)
        {
            var market = GetDictionaryValue(strategy, "market") as Dictionary<string, object>;
            var conditions = GetDictionaryValue(strategy, "conditions") as Dictionary<string, object>;
            var configuredSymbol = ConvertToInvariantString(GetDictionaryValue(market, "symbol"));
            if (!string.IsNullOrWhiteSpace(configuredSymbol) &&
                !string.Equals(NormalizeSymbolAlias(configuredSymbol), NormalizeSymbolAlias(symbolName), StringComparison.OrdinalIgnoreCase))
                return false;

            var configuredTimeFrame = ConvertToInvariantString(GetDictionaryValue(market, "tf"));
            var actualTimeFrame = GetTimeFrameShortLabel(timeFrame);
            if (!string.IsNullOrWhiteSpace(configuredTimeFrame) &&
                !string.Equals(NormalizeTimeFrameToken(configuredTimeFrame), NormalizeTimeFrameToken(actualTimeFrame), StringComparison.OrdinalIgnoreCase))
                return false;

            var symbols = GetDictionaryValue(conditions, "symbols") as List<object>;
            if (symbols != null && symbols.Count > 0 && !symbols.Any(value =>
                string.Equals(NormalizeSymbolAlias(ConvertToInvariantString(value)), NormalizeSymbolAlias(symbolName), StringComparison.OrdinalIgnoreCase)))
                return false;
            var timeFrames = GetDictionaryValue(conditions, "timeframes") as List<object>;
            if (timeFrames != null && timeFrames.Count > 0 && !timeFrames.Any(value =>
                string.Equals(NormalizeTimeFrameToken(ConvertToInvariantString(value)), NormalizeTimeFrameToken(actualTimeFrame), StringComparison.OrdinalIgnoreCase)))
                return false;
            return true;
        }

        private string NormalizeTimeFrameToken(string value)
        {
            return (value ?? "").Trim().ToLowerInvariant().Replace("minutes", "m").Replace("minute", "m").Replace("hours", "h").Replace("hour", "h");
        }

        private SharedRuleResult EvaluateSharedConfigDefinition(
            Dictionary<string, object> definition,
            Dictionary<string, object> context,
            string symbolName,
            Bars sourceBars,
            TimeFrame timeFrame,
            int barIndex,
            bool? requireBullishDirection = null)
        {
            Dictionary<string, object> referenced = null;
            var ruleId = ConvertToInvariantString(GetDictionaryValue(definition, "rule_id"));
            var eventId = ConvertToInvariantString(GetDictionaryValue(definition, "event_id"));
            if (!string.IsNullOrWhiteSpace(ruleId)) _sharedRuleCatalog.TryGetValue(ruleId, out referenced);
            if (referenced == null && !string.IsNullOrWhiteSpace(eventId)) _sharedEventCatalog.TryGetValue(eventId, out referenced);
            var source = referenced ?? definition;

            var implementation = GetDictionaryValue(source, "implementation") as Dictionary<string, object>;
            var implementationType = ConvertToInvariantString(GetDictionaryValue(implementation, "type"));
            if (string.Equals(implementationType, "builtin", StringComparison.OrdinalIgnoreCase))
            {
                var handler = ConvertToInvariantString(GetDictionaryValue(implementation, "handler"));
                StrategyCustomRuleOption ruleOption;
                if (TryParseStrategyCustomRuleOptionName(handler, out ruleOption))
                {
                    var previous = BuildSharedIndicatorSnapshot(sourceBars, Math.Max(0, barIndex - 1));
                    var current = BuildSharedIndicatorSnapshot(sourceBars, barIndex);
                    bool matches;
                    string shortLabel;
                    if (TryEvaluateStrategyCustomRuleOption(ruleOption, symbolName, sourceBars, timeFrame, barIndex, previous, current, requireBullishDirection, out matches, out shortLabel))
                        return new SharedRuleResult { RuleId = ruleId, RuleName = shortLabel, Matched = matches, RawValue = matches };
                }
                StrategyCustomEventOption eventOption;
                if (Enum.TryParse(handler, true, out eventOption))
                {
                    var exactBarTime = sourceBars != null && barIndex >= 0 && barIndex < sourceBars.Count
                        ? sourceBars.OpenTimes[barIndex]
                        : DateTime.MinValue;
                    var trigger = CollectTradeTriggerCandidates(symbolName, timeFrame)
                        .Where(item => TradeTriggerMatchesSelectedOption(item, eventOption))
                        .Where(item => item.SourceTimeFrame == timeFrame && item.BarTime == exactBarTime)
                        .Where(item => !requireBullishDirection.HasValue || item.IsDirectionless || item.IsBullish == requireBullishDirection.Value)
                        .OrderByDescending(item => !item.IsDirectionless)
                        .ThenByDescending(item => item.Priority)
                        .FirstOrDefault();
                    if (!string.IsNullOrWhiteSpace(trigger.Name))
                    {
                        return new SharedRuleResult
                        {
                            RuleId = eventId,
                            RuleName = trigger.Name,
                            Matched = true,
                            RawValue = true,
                            Direction = trigger.IsDirectionless ? "na" : trigger.IsBullish ? "bullish" : "bearish"
                        };
                    }
                }
                return EvaluateSharedRuleInput(handler, context);
            }
            return EvaluateSharedRuleObject(source, context);
        }

        private bool TryResolveSharedConfigTradeType(Dictionary<string, object> definition, TradeType? fallback, out TradeType tradeType)
        {
            tradeType = fallback ?? TradeType.Buy;
            var bias = ConvertToInvariantString(GetDictionaryValue(definition, "bias")).ToLowerInvariant();
            if (bias == "bearish" || bias == "sell" || bias == "short") tradeType = TradeType.Sell;
            else if (bias == "bullish" || bias == "buy" || bias == "long") tradeType = TradeType.Buy;

            var actions = GetDictionaryValue(definition, "actions") as List<object>;
            if (actions == null || actions.Count == 0)
                return !string.IsNullOrWhiteSpace(bias) || fallback.HasValue;
            foreach (var rawAction in actions)
            {
                Dictionary<string, object> action;
                if (!TryGetRuleObject(rawAction, out action))
                    continue;
                var actionName = ConvertToInvariantString(GetDictionaryValue(action, "action")).ToLowerInvariant();
                if (actionName.Contains("short") || actionName.Contains("sell"))
                {
                    tradeType = TradeType.Sell;
                    return true;
                }
                if (actionName.Contains("long") || actionName.Contains("buy"))
                {
                    tradeType = TradeType.Buy;
                    return true;
                }
                var tradePlan = GetDictionaryValue(action, "trade_plan") as Dictionary<string, object>;
                var direction = ConvertToInvariantString(GetDictionaryValue(tradePlan, "direction")).ToLowerInvariant();
                if (direction == "sell" || direction == "short")
                {
                    tradeType = TradeType.Sell;
                    return true;
                }
                if (direction == "buy" || direction == "long")
                {
                    tradeType = TradeType.Buy;
                    return true;
                }
            }
            return !string.IsNullOrWhiteSpace(bias) || fallback.HasValue;
        }

        private bool TryResolveSharedCloseAction(Dictionary<string, object> definition, TradeType positionTradeType, out string actionName)
        {
            actionName = "";
            var actions = GetDictionaryValue(definition, "actions") as List<object>;
            if (actions == null)
                return false;

            foreach (var rawAction in actions)
            {
                Dictionary<string, object> action;
                if (!TryGetRuleObject(rawAction, out action))
                    continue;
                var candidate = ConvertToInvariantString(GetDictionaryValue(action, "action")).Trim().ToLowerInvariant();
                var applies = candidate == "trade.close" || candidate == "position.close" || candidate == "trade.exit" || candidate == "position.exit";
                if (candidate == "trade.close.long" || candidate == "position.close.long")
                    applies = positionTradeType == TradeType.Buy;
                else if (candidate == "trade.close.short" || candidate == "position.close.short")
                    applies = positionTradeType == TradeType.Sell;
                if (!applies)
                    continue;
                actionName = candidate;
                return true;
            }
            return false;
        }

        private List<KeyValuePair<string, Dictionary<string, object>>> GetSharedStrategiesForPosition(Position position)
        {
            var matches = new List<KeyValuePair<string, Dictionary<string, object>>>();
            if (position == null)
                return matches;

            var configuredIds = GetConfiguredSharedStrategyIds();
            var label = position.Label ?? "";
            var comment = position.Comment ?? "";
            foreach (var strategyId in configuredIds)
            {
                Dictionary<string, object> strategy;
                if (!_sharedStrategyCatalog.TryGetValue(strategyId, out strategy) || strategy == null || !SharedConfigStrategyIsActive(strategy))
                    continue;
                var explicitlyOwned = label.Equals(strategyId, StringComparison.OrdinalIgnoreCase) ||
                    label.StartsWith(strategyId + "#", StringComparison.OrdinalIgnoreCase) ||
                    comment.IndexOf(strategyId, StringComparison.OrdinalIgnoreCase) >= 0;
                if (explicitlyOwned || configuredIds.Count == 1)
                    matches.Add(new KeyValuePair<string, Dictionary<string, object>>(strategyId, strategy));
            }
            return matches;
        }

        private TimeFrame ResolveSharedPositionActionTimeFrame(Position position, Dictionary<string, object> strategy)
        {
            TimeFrame parsed;
            var market = GetDictionaryValue(strategy, "market") as Dictionary<string, object>;
            var configured = ConvertToInvariantString(GetDictionaryValue(market, "tf"));
            if (TryParseTimeFrameToken(configured, out parsed))
                return parsed;

            var conditions = GetDictionaryValue(strategy, "conditions") as Dictionary<string, object>;
            var timeFrames = GetDictionaryValue(conditions, "timeframes") as List<object>;
            if (timeFrames != null)
            {
                foreach (var raw in timeFrames)
                    if (TryParseTimeFrameToken(ConvertToInvariantString(raw), out parsed))
                        return parsed;
            }

            foreach (var token in Regex.Split(position != null ? position.Comment ?? "" : "", "[^A-Za-z0-9]+"))
            {
                if (!Regex.IsMatch(token ?? "", "[A-Za-z]"))
                    continue;
                if (TryParseTimeFrameToken(token, out parsed))
                    return parsed;
            }
            return Chart != null ? Chart.TimeFrame : TimeFrame.Minute;
        }

        private List<SharedPositionActionWatcher> BuildSharedPositionActionWatchers()
        {
            var watchers = new List<SharedPositionActionWatcher>();
            if (Positions == null || Positions.Count == 0 || string.IsNullOrWhiteSpace(SharedStrategyConfigIds))
                return watchers;

            foreach (var position in Positions)
            {
                if (position == null || !IsStrategyManagedExposure(position.Label, position.Comment))
                    continue;
                foreach (var strategyPair in GetSharedStrategiesForPosition(position))
                {
                    var strategy = strategyPair.Value;
                    var timeFrame = ResolveSharedPositionActionTimeFrame(position, strategy);
                    if (!SharedConfigStrategyMatchesMarket(strategy, position.SymbolName, timeFrame))
                        continue;
                    var definitions = new List<object>();
                    var rules = GetDictionaryValue(strategy, "rules") as List<object>;
                    var events = GetDictionaryValue(strategy, "events") as List<object>;
                    if (rules != null) definitions.AddRange(rules);
                    if (events != null) definitions.AddRange(events);
                    foreach (var rawDefinition in definitions)
                    {
                        Dictionary<string, object> definition;
                        string actionName;
                        if (!TryGetRuleObject(rawDefinition, out definition) || !TryResolveSharedCloseAction(definition, position.TradeType, out actionName))
                            continue;
                        var definitionId = ConvertToInvariantString(GetDictionaryValue(definition, "id"));
                        if (string.IsNullOrWhiteSpace(definitionId))
                            definitionId = ConvertToInvariantString(GetDictionaryValue(definition, "rule_id"));
                        if (string.IsNullOrWhiteSpace(definitionId))
                            definitionId = "exit";
                        var watcher = new SharedPositionActionWatcher
                        {
                            Key = position.Id.ToString(CultureInfo.InvariantCulture) + "|" + strategyPair.Key + "|" + definitionId + "|" + actionName,
                            Position = position,
                            StrategyId = strategyPair.Key,
                            DefinitionId = definitionId,
                            ActionName = actionName,
                            TimeFrame = timeFrame,
                            Strategy = strategy,
                            Definition = definition
                        };
                        if (!_suppressedPositionActionQueueKeys.Contains(watcher.Key))
                            watchers.Add(watcher);
                    }
                }
            }
            return watchers;
        }

        private void ProcessSharedPositionRuleActions()
        {
            var watchers = BuildSharedPositionActionWatchers();
            var activeKeys = new HashSet<string>(watchers.Select(item => item.Key), StringComparer.OrdinalIgnoreCase);
            foreach (var staleKey in _sharedPositionActionLastBarTicks.Keys.Where(key => !activeKeys.Contains(key)).ToList())
                _sharedPositionActionLastBarTicks.Remove(staleKey);

            foreach (var watcher in watchers)
            {
                Bars bars;
                try { bars = MarketData.GetBars(watcher.TimeFrame, watcher.Position.SymbolName); }
                catch { bars = null; }
                if (bars == null || bars.Count < 3)
                    continue;
                var latestClosedIndex = bars.Count - 2;
                var barTicks = bars.OpenTimes[latestClosedIndex].Ticks;
                long lastTicks;
                if (_sharedPositionActionLastBarTicks.TryGetValue(watcher.Key, out lastTicks) && lastTicks == barTicks)
                    continue;
                _sharedPositionActionLastBarTicks[watcher.Key] = barTicks;

                var resolvedSymbol = ResolveLoadedSymbol(watcher.Position.SymbolName);
                var context = BuildSharedRuleContext(bars, latestClosedIndex, resolvedSymbol, watcher.TimeFrame, null);
                context["params"] = GetDictionaryValue(watcher.Strategy, "params") as Dictionary<string, object> ?? new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
                context["strategy"] = watcher.Strategy;
                context["position"] = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
                {
                    { "id", watcher.Position.Id },
                    { "direction", watcher.Position.TradeType == TradeType.Buy ? "buy" : "sell" },
                    { "entry", watcher.Position.EntryPrice },
                    { "sl", watcher.Position.StopLoss.HasValue ? watcher.Position.StopLoss.Value : 0 },
                    { "tp", watcher.Position.TakeProfit.HasValue ? watcher.Position.TakeProfit.Value : 0 },
                    { "volume", watcher.Position.VolumeInUnits }
                };
                PopulateSharedConfigIndicators(context, watcher.Strategy, bars, latestClosedIndex);
                var result = EvaluateSharedConfigDefinition(
                    watcher.Definition,
                    context,
                    watcher.Position.SymbolName,
                    bars,
                    watcher.TimeFrame,
                    latestClosedIndex,
                    watcher.Position.TradeType == TradeType.Buy);
                if (result == null || !result.Matched)
                    continue;

                var closeResult = ClosePosition(watcher.Position);
                if (closeResult != null && closeResult.IsSuccessful)
                {
                    _strategyQueueTerminalUpdates[watcher.Key] = "RELEASED";
                    SafePrint("[ActionQueue] EXEC {0} #{1} {2} tf={3} rule={4}", watcher.Position.SymbolName, watcher.Position.Id, watcher.ActionName, GetTimeFrameShortLabel(watcher.TimeFrame), watcher.DefinitionId);
                }
                else
                {
                    _sharedPositionActionLastBarTicks.Remove(watcher.Key);
                    SafeLog("ERROR", "[ActionQueue] Close failed {0} #{1} action={2} rule={3} error={4}", watcher.Position.SymbolName, watcher.Position.Id, watcher.ActionName, watcher.DefinitionId, closeResult != null ? closeResult.Error.ToString() : "no result");
                }
            }
        }

        private string BuildStrategyActionQueueDashboardText()
        {
            var rows = new List<Tuple<string, int, DateTime, string>>();
            foreach (var pending in _pendingStrategyEntries.Values)
            {
                var signal = pending.Signal;
                rows.Add(Tuple.Create(
                    pending.SymbolName ?? "",
                    TimeFrameToMinutes(signal.SourceTimeFrame),
                    signal.SignalTime,
                    string.Format(
                        CultureInfo.InvariantCulture,
                        "{0,-8} {1,-2} {2,-4} {3,-22} {4,-16}|",
                        CompactActionQueueSymbol(pending.SymbolName),
                        signal.TradeType == TradeType.Buy ? "B" : "S",
                        GetTimeFrameShortLabel(signal.SourceTimeFrame),
                        CompactActionQueueText(BuildActionQueueTrigger(pending), 22),
                        CompactActionQueueText(BuildActionQueueEntryAt(pending), 16))));
            }
            foreach (var watcher in BuildSharedPositionActionWatchers())
            {
                rows.Add(Tuple.Create(
                    watcher.Position.SymbolName ?? "",
                    TimeFrameToMinutes(watcher.TimeFrame),
                    watcher.Position.EntryTime,
                    string.Format(
                        CultureInfo.InvariantCulture,
                        "{0,-8} {1,-2} {2,-4} {3,-22} {4,-16}|",
                        CompactActionQueueSymbol(watcher.Position.SymbolName),
                        watcher.Position.TradeType == TradeType.Buy ? "B" : "S",
                        GetTimeFrameShortLabel(watcher.TimeFrame),
                        CompactActionQueueText(watcher.DefinitionId, 22),
                        CompactActionQueueText("exit." + GetTimeFrameShortLabel(watcher.TimeFrame), 16))));
            }

            var orderedRows = rows
                .OrderBy(item => item.Item1, StringComparer.OrdinalIgnoreCase)
                .ThenByDescending(item => item.Item2)
                .ThenBy(item => item.Item3)
                .Select(item => item.Item4)
                .ToList();

            var builder = new StringBuilder();
            builder.AppendLine(string.Format(
                CultureInfo.InvariantCulture,
                "{0,-8} {1,-2} {2,-4} {3,-22} {4,-16}|",
                "SYMBOL",
                "SIDE",
                "TF",
                "TRIGGER",
                "ENTRY AT"));
            if (orderedRows.Count == 0)
                builder.Append(string.Format(
                    CultureInfo.InvariantCulture,
                    "{0,-8} {1,-2} {2,-4} {3,-22} {4,-16}|",
                    "-",
                    "-",
                    "-",
                    "-",
                    "empty"));
            else
                builder.Append(string.Join(Environment.NewLine, orderedRows.Take(12)));
            if (orderedRows.Count > 12)
                builder.AppendLine().Append(CompactActionQueueText("+" + (orderedRows.Count - 12) + " more", 59)).Append("|");
            return builder.ToString();
        }

        private string ResolveActionQueueTriggerLabel(BacktestStrategySignal signal)
        {
            var sourceLabel = signal.SourceLabel ?? "";
            if (string.IsNullOrWhiteSpace(sourceLabel))
                return "-";

            var timeFramePrefix = GetTimeFrameShortLabel(signal.SourceTimeFrame) + ".";
            var matchingLabel = sourceLabel
                .Split(new[] { '+' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(label => label.Trim())
                .Where(label => label.StartsWith(timeFramePrefix, StringComparison.OrdinalIgnoreCase))
                .OrderByDescending(GetEventLabelPriorityScore)
                .FirstOrDefault();
            return string.IsNullOrWhiteSpace(matchingLabel) ? "-" : matchingLabel;
        }

        private string CompactActionQueueText(string value, int width)
        {
            var text = string.IsNullOrWhiteSpace(value) ? "-" : value.Trim();
            if (text.Length > width)
                text = text.Substring(0, width);
            return text.PadRight(width);
        }

        private string BuildActionQueueEntryAt(PendingStrategyEntry pending)
        {
            if (pending == null)
                return "-";

            var signal = pending.Signal;
            var timeFrame = GetTimeFrameShortLabel(signal.SourceTimeFrame);
            var direction = signal.TradeType == TradeType.Buy ? "b" : "s";
            if (pending.EntryBarMode == StrategyEntryBarMode.First_bar_reverse_trend)
                direction = signal.TradeType == TradeType.Buy ? "s" : "b";
            else if (pending.EntryBarMode == StrategyEntryBarMode.First_bar_after_trigger)
                direction = "any";
            return "#" + Math.Max(1, signal.TradeChainSlot).ToString(CultureInfo.InvariantCulture) + "." + timeFrame + "." + direction;
        }

        private string BuildActionQueueTrigger(PendingStrategyEntry pending)
        {
            if (pending == null)
                return "-";

            var signal = pending.Signal;
            var eventLabel = ResolveActionQueueTriggerLabel(signal);
            // Queue rows identify the actual trigger bar, not when this cBot happened to scan it.
            var triggerBarTime = signal.SignalTime;
            if (triggerBarTime != DateTime.MinValue)
            {
                return string.Format(
                    CultureInfo.InvariantCulture,
                    "{0}@{1:HH:mm:ss}",
                    eventLabel,
                    triggerBarTime);
            }

            return eventLabel;
        }

        private DateTime ResolveActionQueueEventCloseTime(string symbolName, BacktestStrategySignal signal)
        {
            if (string.IsNullOrWhiteSpace(symbolName) || signal.SignalTime == DateTime.MinValue)
                return DateTime.MinValue;

            try
            {
                var sourceBars = MarketData.GetBars(signal.SourceTimeFrame, symbolName);
                return ResolveSourceBarEndTime(sourceBars, signal.SignalTime, signal.SourceTimeFrame);
            }
            catch
            {
                return ResolveSourceBarEndTime(null, signal.SignalTime, signal.SourceTimeFrame);
            }
        }

        private string CompactActionQueueSymbol(string symbolName)
        {
            var value = string.IsNullOrWhiteSpace(symbolName) ? "-" : symbolName.Trim().ToUpperInvariant();
            return value.Length <= 9 ? value : value.Substring(0, 9);
        }

        private void PopulateSharedConfigIndicators(Dictionary<string, object> context, Dictionary<string, object> strategy, Bars bars, int barIndex)
        {
            var indicators = GetDictionaryValue(context, "indicators") as Dictionary<string, object>;
            if (indicators == null)
            {
                indicators = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
                context["indicators"] = indicators;
            }
            var previousIndicators = GetDictionaryValue(context, "prev_indicators") as Dictionary<string, object>;
            if (previousIndicators == null)
            {
                previousIndicators = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
                context["prev_indicators"] = previousIndicators;
            }
            var definitions = GetDictionaryValue(strategy, "indicators") as List<object>;
            if (definitions == null)
                return;
            PopulateSharedConfigIndicatorsAtIndex(indicators, definitions, context, bars, barIndex);
            PopulateSharedConfigIndicatorsAtIndex(previousIndicators, definitions, context, bars, Math.Max(0, barIndex - 1));
        }

        private void PopulateSharedConfigIndicatorsAtIndex(
            Dictionary<string, object> indicators,
            List<object> definitions,
            Dictionary<string, object> context,
            Bars bars,
            int barIndex)
        {
            foreach (var rawDefinition in definitions)
            {
                Dictionary<string, object> definition;
                if (!TryGetRuleObject(rawDefinition, out definition))
                    continue;
                var id = ConvertToInvariantString(GetDictionaryValue(definition, "id"));
                var type = ConvertToInvariantString(GetDictionaryValue(definition, "type")).ToLowerInvariant();
                var length = Math.Max(1, (int)Math.Round(ResolveSharedConfigNumber(GetDictionaryValue(definition, "length"), context, 14)));
                var value = double.NaN;
                if (type == "ema") value = ComputeExponentialMovingAverage(bars, barIndex, length);
                else if (type == "sma") value = ComputeSimpleMovingAverage(bars, barIndex, length);
                else if (type == "rsi") value = ComputeRelativeStrengthIndex(bars, barIndex, length);
                else if (type == "roc") value = ComputeRateOfChange(bars, barIndex, length);
                else if (type == "highest_high") value = SharedConfigHighest(bars, barIndex, length, true);
                else if (type == "lowest_low") value = SharedConfigHighest(bars, barIndex, length, false);
                if (!string.IsNullOrWhiteSpace(id)) SetSharedIndicatorValue(indicators, id, value);
                if ((type == "ema" || type == "sma") && !string.IsNullOrWhiteSpace(type))
                    SetSharedIndicatorValue(indicators, type + "_" + length.ToString(CultureInfo.InvariantCulture), value);
            }
        }

        private double ResolveSharedConfigNumber(object value, Dictionary<string, object> context, double fallback)
        {
            Dictionary<string, object> map;
            if (TryGetRuleObject(value, out map) && map.Count == 1 && map.ContainsKey("var"))
            {
                var resolved = SharedRuleValueAtPath(context, ConvertToInvariantString(map["var"]));
                var number = ToSharedRuleNumber(resolved);
                return SharedRuleFinite(number) ? number : fallback;
            }
            var direct = ToSharedRuleNumber(value);
            return SharedRuleFinite(direct) ? direct : fallback;
        }

        private double SharedConfigHighest(Bars bars, int barIndex, int length, bool high)
        {
            if (bars == null || barIndex < 0 || barIndex >= bars.Count)
                return double.NaN;
            var start = Math.Max(0, barIndex - Math.Max(1, length) + 1);
            var value = high ? double.MinValue : double.MaxValue;
            for (var index = start; index <= barIndex; index++)
                value = high ? Math.Max(value, bars.HighPrices[index]) : Math.Min(value, bars.LowPrices[index]);
            return value;
        }

