        private Dictionary<string, object> BuildSharedRuleContext(Bars sourceBars, int barIndex, Symbol symbol, TimeFrame timeFrame, Dictionary<string, object> extraContext = null)
        {
            var context = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
            var barsList = new List<Dictionary<string, object>>();
            if (sourceBars != null)
            {
                for (var i = 0; i < sourceBars.Count; i++)
                    barsList.Add(BuildSharedRuleBarContext(sourceBars, i));
            }

            context["bars"] = barsList;
            context["index"] = barIndex;
            context["bar"] = barIndex >= 0 && barIndex < barsList.Count ? barsList[barIndex] : null;
            context["prev"] = barIndex > 0 && barIndex - 1 < barsList.Count ? barsList[barIndex - 1] : null;
            context["symbol"] = symbol != null ? symbol.Name : "";
            context["tf"] = GetTimeFrameShortLabel(timeFrame);
            context["timeframe"] = GetTimeFrameShortLabel(timeFrame);
            context["market"] = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
            {
                { "symbol", symbol != null ? symbol.Name : "" },
                { "tf", GetTimeFrameShortLabel(timeFrame) }
            };
            var indicators = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
            var prevIndicators = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
            PopulateSharedIndicatorDictionary(indicators, BuildSharedIndicatorSnapshot(sourceBars, barIndex));
            PopulateSharedIndicatorDictionary(prevIndicators, BuildSharedIndicatorSnapshot(sourceBars, Math.Max(0, barIndex - 1)));
            context["indicators"] = indicators;
            context["prev_indicators"] = prevIndicators;
            context["levels"] = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);

            if (extraContext != null)
            {
                foreach (var pair in extraContext)
                    context[pair.Key] = pair.Value;
            }

            return context;
        }

        private Dictionary<string, object> BuildSharedRuleBarContext(Bars sourceBars, int index)
        {
            return new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
            {
                { "time", ToUnixSecondsSafe(sourceBars != null && index >= 0 && index < sourceBars.Count ? sourceBars.OpenTimes[index] : DateTime.MinValue) },
                { "open", sourceBars != null && index >= 0 && index < sourceBars.Count ? sourceBars.OpenPrices[index] : 0.0 },
                { "high", sourceBars != null && index >= 0 && index < sourceBars.Count ? sourceBars.HighPrices[index] : 0.0 },
                { "low", sourceBars != null && index >= 0 && index < sourceBars.Count ? sourceBars.LowPrices[index] : 0.0 },
                { "close", sourceBars != null && index >= 0 && index < sourceBars.Count ? sourceBars.ClosePrices[index] : 0.0 },
                { "volume", sourceBars != null && index >= 0 && index < sourceBars.Count ? GetSharedRuleBarVolume(sourceBars, index) : 0.0 },
            };
        }

        private double GetSharedRuleBarVolume(Bars sourceBars, int index)
        {
            try
            {
                return sourceBars != null && index >= 0 && index < sourceBars.TickVolumes.Count
                    ? sourceBars.TickVolumes[index]
                    : 0.0;
            }
            catch
            {
                return 0.0;
            }
        }

        private double GetVolumeSurgeMultiplier(VolumeSurgeMode mode)
        {
            switch (mode)
            {
                case VolumeSurgeMode._5pct:
                    return 1.05;
                case VolumeSurgeMode._10pct:
                    return 1.10;
                case VolumeSurgeMode._15pct:
                    return 1.15;
                case VolumeSurgeMode._20pct:
                    return 1.20;
                default:
                    return 1.0;
            }
        }

        private double ResolveZoneFvgDisplacementRatio(ZoneFvgDisplacementPreset preset)
        {
            switch (preset)
            {
                case ZoneFvgDisplacementPreset.Loose:
                    return 1.05;
                case ZoneFvgDisplacementPreset.Normal:
                    return 1.15;
                case ZoneFvgDisplacementPreset.Tight:
                    return 1.30;
                case ZoneFvgDisplacementPreset.Strict:
                    return 1.50;
                default:
                    return 0.0; // No = requirement disabled
            }
        }

        private double ResolveZoneFvgBodyRatio(ZoneFvgBodyRatioPreset preset)
        {
            switch (preset)
            {
                case ZoneFvgBodyRatioPreset.Low:
                    return 0.40;
                case ZoneFvgBodyRatioPreset.Medium:
                    return 0.55;
                case ZoneFvgBodyRatioPreset.High:
                    return 0.70;
                case ZoneFvgBodyRatioPreset.Full:
                    return 0.85;
                default:
                    return 0.0; // No = requirement disabled
            }
        }

        private double ResolveZoneFvgGapPercent(ZoneFvgGapPreset preset)
        {
            switch (preset)
            {
                case ZoneFvgGapPreset.Tiny:
                    return 0.05;
                case ZoneFvgGapPreset.Small:
                    return 0.10;
                case ZoneFvgGapPreset.Normal:
                    return 0.18;
                case ZoneFvgGapPreset.Large:
                    return 0.30;
                default:
                    return 0.0; // No = requirement disabled
            }
        }

        private int ResolveZoneLookbackBars(ZoneLookbackPreset preset, TimeFrame sourceTimeFrame = null, Bars sourceBars = null)
        {
            switch (preset)
            {
                case ZoneLookbackPreset.Bars50:
                    return 50;
                case ZoneLookbackPreset.Bars80:
                    return 80;
                case ZoneLookbackPreset.Bars120:
                    return 120;
                case ZoneLookbackPreset.Bars200:
                    return 200;
                case ZoneLookbackPreset._1d:
                    return ResolveLookbackBarsForMinutes(1440, sourceTimeFrame, sourceBars);
                case ZoneLookbackPreset._3d:
                    return ResolveLookbackBarsForMinutes(1440 * 3, sourceTimeFrame, sourceBars);
                case ZoneLookbackPreset._1w:
                    return ResolveLookbackBarsForMinutes(10080, sourceTimeFrame, sourceBars);
                case ZoneLookbackPreset._2w:
                    return ResolveLookbackBarsForMinutes(10080 * 2, sourceTimeFrame, sourceBars);
                case ZoneLookbackPreset._1mo:
                    return ResolveLookbackBarsForMinutes(43200, sourceTimeFrame, sourceBars);
                default:
                    return 0; // No Limit = scan all available bars
            }
        }

        private int ResolveLookbackBarsForMinutes(int totalMinutes, TimeFrame sourceTimeFrame = null, Bars sourceBars = null)
        {
            var effectiveBars = sourceBars ?? Bars;
            if (effectiveBars != null && effectiveBars.Count <= 0)
                return 0;

            var tfMinutes = ResolveLookbackSourceTimeFrameMinutes(sourceTimeFrame, effectiveBars);
            var bars = (int)Math.Ceiling(totalMinutes / (double)tfMinutes);
            if (effectiveBars != null && effectiveBars.Count > 0)
                return Math.Min(effectiveBars.Count, Math.Max(1, bars));
            return Math.Max(1, bars);
        }

        private int ResolveLookbackSourceTimeFrameMinutes(TimeFrame sourceTimeFrame = null, Bars sourceBars = null)
        {
            var effectiveTimeFrame = sourceTimeFrame ?? (Chart != null ? Chart.TimeFrame : TimeFrame.Minute);
            var tfMinutes = Math.Max(0, TimeFrameToMinutes(effectiveTimeFrame));
            if (tfMinutes > 0)
                return tfMinutes;

            if (sourceBars != null && sourceBars.Count >= 2)
            {
                try
                {
                    var minutes = (int)Math.Round((sourceBars.OpenTimes[sourceBars.Count - 1] - sourceBars.OpenTimes[sourceBars.Count - 2]).TotalMinutes);
                    if (minutes > 0)
                        return minutes;
                }
                catch
                {
                }
            }

            return 1;
        }

        private int ResolveWorkingLookbackBars(Bars sourceBars, TimeFrame sourceTimeFrame = null)
        {
            if (sourceBars == null || sourceBars.Count <= 0)
                return 0;

            var configured = ResolveZoneLookbackBars(ZoneLookback, sourceTimeFrame, sourceBars);
            if (configured <= 0)
                return sourceBars.Count;

            return Math.Min(sourceBars.Count, Math.Max(1, configured));
        }

        private int ResolveWorkingStartIndex(Bars sourceBars, int minimumStartIndex = 2, int reserveClosedBars = 2, TimeFrame sourceTimeFrame = null)
        {
            if (sourceBars == null || sourceBars.Count <= 0)
                return 0;

            var lookbackBars = ResolveWorkingLookbackBars(sourceBars, sourceTimeFrame);
            return Math.Max(minimumStartIndex, sourceBars.Count - Math.Max(1, lookbackBars));
        }

        private int ResolveWorkingSwingLookbackBars(Bars sourceBars, TimeFrame sourceTimeFrame = null)
        {
            return Math.Max(2, ResolveWorkingLookbackBars(sourceBars, sourceTimeFrame));
        }

        private int ResolveZoneMaxCount(ZoneMaxCountPreset preset)
        {
            switch (preset)
            {
                case ZoneMaxCountPreset.Few:
                    return 4;
                case ZoneMaxCountPreset.Normal:
                    return 8;
                case ZoneMaxCountPreset.Many:
                    return 12;
                case ZoneMaxCountPreset.Max:
                    return 16;
                default:
                    return int.MaxValue; // No Limit
            }
        }

        // Event is only valid when its volume is higher than the previous comparable window by
        // the Strategies-group Vol Surge percentage. For multi-candle events (patternSpan > 1) the
        // AVERAGE volume of the pattern candles is compared against the AVERAGE of the same
        // number of candles BEFORE the pattern — never candle-to-candle inside the group.
        // Fails closed when volume data is unavailable.
        private bool HasEventVolumeSurge(Bars sourceBars, int index, int patternSpan = 1)
        {
            return HasVolumeSurgeForMode(sourceBars, index, patternSpan, StrategyVolumeSurgePreset);
        }

        // OB/FVG visual zones use their own configurable surge (Zones Vol Surge, default No).
        private bool HasZoneVolumeSurge(Bars sourceBars, int index, int patternSpan = 1)
        {
            return HasVolumeSurgeForMode(sourceBars, index, patternSpan, ZoneVolumeSurgePreset);
        }

        private bool HasVolumeSurgeForMode(Bars sourceBars, int index, int patternSpan, VolumeSurgeMode mode)
        {
            if (mode == VolumeSurgeMode.No)
                return true;
            if (sourceBars == null || index <= 0 || index >= sourceBars.Count)
                return false;

            var span = Math.Max(1, patternSpan);
            var currentStart = index - span + 1;
            var previousStart = currentStart - span;
            if (currentStart < 0 || previousStart < 0)
                return false;

            var currentTotal = 0.0;
            var previousTotal = 0.0;
            var currentCount = 0;
            var previousCount = 0;
            for (var i = currentStart; i <= index; i++)
            {
                var currentVolume = GetSharedRuleBarVolume(sourceBars, i);
                if (currentVolume > 0)
                {
                    currentTotal += currentVolume;
                    currentCount++;
                }
            }
            for (var i = previousStart; i < currentStart; i++)
            {
                var previousVolume = GetSharedRuleBarVolume(sourceBars, i);
                if (previousVolume > 0)
                {
                    previousTotal += previousVolume;
                    previousCount++;
                }
            }
            if (currentCount == 0 || previousCount == 0)
                return false;

            var currentAvg = currentTotal / currentCount;
            var previousAvg = previousTotal / previousCount;
            if (!(previousAvg > 0))
                return false;
            return currentAvg > previousAvg * GetVolumeSurgeMultiplier(mode);
        }

        // Strategy-level volume surge: the signal bar must surge vs the previous bar per the
        // Strategies-group Vol Surge setting. No = always pass.
        private bool HasStrategyBarVolumeSurge(string symbolName, TimeFrame timeFrame, DateTime signalTime)
        {
            if (StrategyVolumeSurgePreset == VolumeSurgeMode.No)
                return true;
            if (string.IsNullOrWhiteSpace(symbolName) || timeFrame == null || signalTime == DateTime.MinValue)
                return false;

            try
            {
                var bars = MarketData.GetBars(timeFrame, symbolName);
                if (bars == null || bars.Count < 2)
                    return false;
                for (var i = 0; i < bars.Count; i++)
                {
                    if (bars.OpenTimes[i] == signalTime)
                        return HasVolumeSurgeForMode(bars, i, 1, StrategyVolumeSurgePreset);
                }
                return false;
            }
            catch
            {
                return false;
            }
        }

        private long ToUnixSecondsSafe(DateTime value)
        {
            try
            {
                if (value == DateTime.MinValue)
                    return 0;
                return new DateTimeOffset(DateTime.SpecifyKind(value, DateTimeKind.Utc)).ToUnixTimeSeconds();
            }
            catch
            {
                return 0;
            }
        }

