        SessionHighLow,
        OrderBlockEdge,
        FvgEdge,
        RewardRisk2
    }

    internal enum CTraderWaitConfirmDecisionKind
    {
        Waiting,
        Confirm,
        Cancel,
        Expire
    }

    internal sealed class CTraderWaitConfirmDecision
    {
        public CTraderWaitConfirmDecisionKind Kind;
        public int AgeBars;
        public int ConfirmationOffset = -1;
        public double ConfirmationEntry;
        public double ChaseR;
        public double RiskMultiplier;
        public bool PullbackSeen;
        public string Reason = "";
    }

    // Owns the durable Wait_confirm lifecycle and its deterministic price rules.
    internal sealed class CTraderWaitConfirmQueueEngine
    {
        public readonly Dictionary<string, TVBridgeCBot.PendingStrategyEntry> Waiting =
            new Dictionary<string, TVBridgeCBot.PendingStrategyEntry>(StringComparer.OrdinalIgnoreCase);
        public readonly HashSet<string> TerminalKeys =
            new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        public CTraderWaitConfirmDecision Evaluate(
            double[] opens,
            double[] closes,
            bool isBuy,
            double originalEntry,
            double originalRisk,
            double invalidationPrice,
            int maxBars,
            bool requirePullback,
            double maxChaseR,
            double maxRiskMultiplier,
            bool invalidateOnClose)
        {
            var decision = new CTraderWaitConfirmDecision();
            if (opens == null || closes == null || opens.Length != closes.Length || opens.Length < 2)
            {
                decision.Kind = CTraderWaitConfirmDecisionKind.Waiting;
                decision.Reason = "bars_unavailable";
                return decision;
            }

            decision.AgeBars = opens.Length - 1;
            maxBars = Math.Max(1, maxBars);
            maxChaseR = Math.Max(0, maxChaseR);
            maxRiskMultiplier = Math.Max(1.0, maxRiskMultiplier);
            var risk = Math.Max(0, originalRisk);
            if (!(originalEntry > 0) || !(risk > 0) || !(invalidationPrice > 0))
            {
                decision.Kind = CTraderWaitConfirmDecisionKind.Cancel;
                decision.Reason = "original_reference_invalid";
                return decision;
            }

            var pullbackSeen = false;
            for (var offset = 1; offset < opens.Length; offset++)
            {
                if (offset > maxBars)
                {
                    decision.Kind = CTraderWaitConfirmDecisionKind.Expire;
                    decision.PullbackSeen = pullbackSeen;
                    decision.Reason = "max_bars_exceeded";
                    return decision;
                }
                var open = opens[offset];
                var close = closes[offset];
                if (invalidateOnClose && (isBuy ? close <= invalidationPrice : close >= invalidationPrice))
                {
                    decision.Kind = CTraderWaitConfirmDecisionKind.Cancel;
                    decision.PullbackSeen = pullbackSeen;
                    decision.Reason = "invalidation_close";
                    return decision;
                }

                var direction = close == open ? 0 : close > open ? 1 : -1;
                var confirmsDirection = isBuy ? direction > 0 : direction < 0;
                if (!confirmsDirection)
                {
                    if (isBuy ? direction < 0 : direction > 0)
                        pullbackSeen = true;
                    continue;
                }

                decision.ConfirmationOffset = offset;
                decision.ConfirmationEntry = close;
                decision.PullbackSeen = pullbackSeen;
                if (offset != opens.Length - 1)
                {
                    decision.Kind = CTraderWaitConfirmDecisionKind.Cancel;
                    decision.Reason = "confirmation_no_longer_fresh";
                    return decision;
                }
                if (offset > maxBars)
                {
                    decision.Kind = CTraderWaitConfirmDecisionKind.Expire;
                    decision.Reason = "max_bars_exceeded";
                    return decision;
                }
                if (requirePullback && !pullbackSeen)
                {
                    decision.Kind = CTraderWaitConfirmDecisionKind.Cancel;
                    decision.Reason = "pullback_missing";
                    return decision;
                }

                var adverseEntryMove = isBuy
                    ? Math.Max(0, close - originalEntry)
                    : Math.Max(0, originalEntry - close);
                decision.ChaseR = adverseEntryMove / risk;
                if (decision.ChaseR > maxChaseR + 0.0000001)
                {
                    decision.Kind = CTraderWaitConfirmDecisionKind.Cancel;
                    decision.Reason = "chase_r_exceeded";
                    return decision;
                }

                decision.RiskMultiplier = Math.Abs(close - invalidationPrice) / risk;
                if (decision.RiskMultiplier > maxRiskMultiplier + 0.0000001)
                {
                    decision.Kind = CTraderWaitConfirmDecisionKind.Cancel;
                    decision.Reason = "risk_multiplier_exceeded";
                    return decision;
                }

                decision.Kind = CTraderWaitConfirmDecisionKind.Confirm;
                decision.Reason = "confirmed";
                return decision;
            }

            decision.PullbackSeen = pullbackSeen;
            if (decision.AgeBars >= maxBars)
            {
                decision.Kind = CTraderWaitConfirmDecisionKind.Expire;
                decision.Reason = "max_bars_reached";
                return decision;
            }

            decision.Kind = CTraderWaitConfirmDecisionKind.Waiting;
            decision.Reason = pullbackSeen ? "waiting_confirmation" : "waiting_pullback";
            return decision;
        }

        public CTraderWaitConfirmDecision EvaluateFinalRisk(
            bool isBuy,
            double originalEntry,
            double originalRisk,
            double finalEntry,
            double finalStopLoss,
            double maxChaseR,
            double maxRiskMultiplier)
        {
            var decision = new CTraderWaitConfirmDecision
            {
                ConfirmationEntry = finalEntry,
                Kind = CTraderWaitConfirmDecisionKind.Confirm,
                Reason = "confirmed"
            };
            if (!(originalEntry > 0) || !(originalRisk > 0) || !(finalEntry > 0) || !(finalStopLoss > 0))
            {
                decision.Kind = CTraderWaitConfirmDecisionKind.Cancel;
                decision.Reason = "reference_invalid";
                return decision;
            }

            decision.ChaseR = (isBuy
                ? Math.Max(0, finalEntry - originalEntry)
                : Math.Max(0, originalEntry - finalEntry)) / originalRisk;
            decision.RiskMultiplier = Math.Abs(finalEntry - finalStopLoss) / originalRisk;
            if (decision.ChaseR > Math.Max(0, maxChaseR) + 0.0000001)
            {
                decision.Kind = CTraderWaitConfirmDecisionKind.Cancel;
                decision.Reason = "chase_r_exceeded";
            }
            else if (decision.RiskMultiplier > Math.Max(1.0, maxRiskMultiplier) + 0.0000001)
            {
                decision.Kind = CTraderWaitConfirmDecisionKind.Cancel;
                decision.Reason = "risk_multiplier_exceeded";
            }
            return decision;
        }
    }

    // Owns strategy signal and price-plan semantics that do not depend on live account state.
    internal static class CTraderStrategyEngine
    {
        public const int AutoStopLossSourceCount = 5;
        public const int AutoTakeProfitSourceCount = 7;

        public static bool IsFirstDirectionalBarAfter(
            Bars sourceBars,
            int patternEndIndex,
            int confirmationIndex,
            bool bullish)
        {
            if (sourceBars == null || patternEndIndex < 0 || confirmationIndex <= patternEndIndex || confirmationIndex >= sourceBars.Count)
                return false;

            var directions = new List<int>();
            for (var index = patternEndIndex + 1; index <= confirmationIndex; index++)
            {
                var open = sourceBars.OpenPrices[index];
                var close = sourceBars.ClosePrices[index];
                directions.Add(close == open ? 0 : close > open ? 1 : -1);
            }
            return IsFirstDirectionalBarAtEnd(directions, bullish);
        }

        public static bool IsFirstDirectionalBarAtEnd(IReadOnlyList<int> directions, bool bullish)
        {
            if (directions == null || directions.Count == 0)
                return false;
            var expectedDirection = bullish ? 1 : -1;
            for (var index = 0; index < directions.Count; index++)
            {
                if (directions[index] != expectedDirection)
                    continue;
                return index == directions.Count - 1;
            }
            return false;
        }

        public static int ResolvePatternToEntryBars(int patternEndIndex, int confirmationIndex)
        {
            return patternEndIndex >= 0 && confirmationIndex >= patternEndIndex
                ? Math.Max(1, confirmationIndex - patternEndIndex)
                : 1;
        }

        public static string FormatEntryModeLeg(string entryMode, int legNumber, int patternToEntryBars)
        {
            return string.Format(
                CultureInfo.InvariantCulture,
                "{0}.{1}-{2}",
                string.IsNullOrWhiteSpace(entryMode) ? "Now" : entryMode.Trim(),
                Math.Max(1, legNumber),
                Math.Max(1, patternToEntryBars));
        }

        public static CTraderStrategyStopSource ResolveAutoStopLossSource(int priorityIndex)
        {
            switch (priorityIndex)
            {
                case 0: return CTraderStrategyStopSource.EventInvalidation;
                case 1: return CTraderStrategyStopSource.ProtectiveSwing;
                case 2: return CTraderStrategyStopSource.Pattern;
                case 3: return CTraderStrategyStopSource.CandleWick;
                case 4: return CTraderStrategyStopSource.CandleRange5;
                default: throw new ArgumentOutOfRangeException(nameof(priorityIndex));
            }
        }

        public static CTraderStrategyTargetSource ResolveAutoTakeProfitSource(int priorityIndex)
        {
            switch (priorityIndex)
            {
                case 0: return CTraderStrategyTargetSource.Liquidity;
                case 1: return CTraderStrategyTargetSource.HtfKeyLevel;
                case 2: return CTraderStrategyTargetSource.LtfKeyLevel;
                case 3: return CTraderStrategyTargetSource.SessionHighLow;
                case 4: return CTraderStrategyTargetSource.OrderBlockEdge;
                case 5: return CTraderStrategyTargetSource.FvgEdge;
                case 6: return CTraderStrategyTargetSource.RewardRisk2;
                default: throw new ArgumentOutOfRangeException(nameof(priorityIndex));
            }
        }

        public static int ResolveDirectionalConfluenceComponentScore(int biasScore, bool bullish)
        {
            if (biasScore >= 2)
                return bullish ? 1 : -1;
            if (biasScore <= -2)
                return bullish ? -1 : 1;
            return 0;
        }

        public static double ResolveRewardRisk(TVBridgeCBot.StrategyTakeProfitMode mode)
        {
            switch (mode)
            {
                case TVBridgeCBot.StrategyTakeProfitMode.RR_0_3: return 0.3;
                case TVBridgeCBot.StrategyTakeProfitMode.RR_0_5: return 0.5;
                case TVBridgeCBot.StrategyTakeProfitMode.RR_0_7: return 0.7;
                case TVBridgeCBot.StrategyTakeProfitMode.RR_1: return 1.0;
                case TVBridgeCBot.StrategyTakeProfitMode.RR_1_3: return 1.3;
                case TVBridgeCBot.StrategyTakeProfitMode.RR_1_5: return 1.5;
                case TVBridgeCBot.StrategyTakeProfitMode.RR_1_7: return 1.7;
                case TVBridgeCBot.StrategyTakeProfitMode.RR_2: return 2.0;
                case TVBridgeCBot.StrategyTakeProfitMode.RR_2_5: return 2.5;
                case TVBridgeCBot.StrategyTakeProfitMode.RR_3: return 3.0;
                default: return 1.5;
            }
        }

        public static bool IsRewardRiskMode(TVBridgeCBot.StrategyTakeProfitMode mode)
        {
            switch (mode)
            {
                case TVBridgeCBot.StrategyTakeProfitMode.RR_0_3:
                case TVBridgeCBot.StrategyTakeProfitMode.RR_0_5:
                case TVBridgeCBot.StrategyTakeProfitMode.RR_0_7:
                case TVBridgeCBot.StrategyTakeProfitMode.RR_1:
                case TVBridgeCBot.StrategyTakeProfitMode.RR_1_3:
                case TVBridgeCBot.StrategyTakeProfitMode.RR_1_5:
                case TVBridgeCBot.StrategyTakeProfitMode.RR_1_7:
                case TVBridgeCBot.StrategyTakeProfitMode.RR_2:
                case TVBridgeCBot.StrategyTakeProfitMode.RR_2_5:
                case TVBridgeCBot.StrategyTakeProfitMode.RR_3:
                    return true;
                default:
                    return false;
            }
        }

        public static bool TryValidatePrices(Symbol symbol, string action, double referencePrice, double stopLoss, double takeProfit, out string reason)
        {
            reason = "";
            if (symbol == null)
            {
                reason = "invalid_symbol";
                return false;
            }
            if (referencePrice <= 0)
            {
                reason = "invalid_reference_price";
                return false;
            }

            var isBuy = string.Equals(action, "BUY", StringComparison.OrdinalIgnoreCase);
            var isSell = string.Equals(action, "SELL", StringComparison.OrdinalIgnoreCase);
            if (!isBuy && !isSell)
            {
                reason = "invalid_action";
                return false;
            }

            var minMove = symbol.PipSize > 0 ? symbol.PipSize * 0.5 : 0.0;
            if (stopLoss > 0 && isBuy && stopLoss >= referencePrice - minMove)
            {
                reason = string.Format(CultureInfo.InvariantCulture, "rule=ProtectionDirection violated; sl_wrong_side ref={0:F5} sl={1:F5} side=BUY; fix=SL_must_be_below_entry", referencePrice, stopLoss);
                return false;
            }
            if (stopLoss > 0 && isSell && stopLoss <= referencePrice + minMove)
            {
                reason = string.Format(CultureInfo.InvariantCulture, "rule=ProtectionDirection violated; sl_wrong_side ref={0:F5} sl={1:F5} side=SELL; fix=SL_must_be_above_entry", referencePrice, stopLoss);
                return false;
            }
            if (takeProfit > 0 && isBuy && takeProfit <= referencePrice + minMove)
            {
                reason = string.Format(CultureInfo.InvariantCulture, "rule=ProtectionDirection violated; tp_wrong_side ref={0:F5} tp={1:F5} side=BUY; fix=TP_must_be_above_entry", referencePrice, takeProfit);
                return false;
            }
            if (takeProfit > 0 && isSell && takeProfit >= referencePrice - minMove)
            {
                reason = string.Format(CultureInfo.InvariantCulture, "rule=ProtectionDirection violated; tp_wrong_side ref={0:F5} tp={1:F5} side=SELL; fix=TP_must_be_below_entry", referencePrice, takeProfit);
                return false;
            }
            return true;
        }

        public static double AddLevelBuffer(Symbol symbol, TradeType tradeType, double price, bool isStopLoss, double buffer)
        {
            if (symbol == null || price <= 0)
                return 0;
            var adjusted = tradeType == TradeType.Buy ? price - buffer : price + buffer;
            return CTraderRiskEngine.NormalizePrice(symbol, adjusted);
        }

        public static double ResolveDistanceTarget(Symbol symbol, TradeType tradeType, double entryPrice, bool isStopLoss, double distance)
        {
            if (symbol == null || entryPrice <= 0 || !(distance > 0))
                return 0;
            var isBuy = tradeType == TradeType.Buy;
            var price = isStopLoss
                ? (isBuy ? entryPrice - distance : entryPrice + distance)
                : (isBuy ? entryPrice + distance : entryPrice - distance);
            return CTraderRiskEngine.NormalizePrice(symbol, price);
        }

        public static double ResolveEntryBufferMultiplier(TVBridgeCBot.StrategyEntryType entryType)
        {
            switch (entryType)
            {
                case TVBridgeCBot.StrategyEntryType._0_1_limit: return 0.1;
                case TVBridgeCBot.StrategyEntryType._0_2_limit: return 0.2;
                case TVBridgeCBot.StrategyEntryType.limit_0_25R: return 0.25;
                case TVBridgeCBot.StrategyEntryType._0_3_limit: return 0.3;
                case TVBridgeCBot.StrategyEntryType._0_4_limit: return 0.4;
                case TVBridgeCBot.StrategyEntryType._0_5_limit:
                case TVBridgeCBot.StrategyEntryType.limit_0_5R: return 0.5;
                case TVBridgeCBot.StrategyEntryType._0_6_limit: return 0.6;
                case TVBridgeCBot.StrategyEntryType._0_7_limit: return 0.7;
                case TVBridgeCBot.StrategyEntryType.limit_0_75R: return 0.75;
                case TVBridgeCBot.StrategyEntryType._0_8_limit: return 0.8;
                default: return 0.0;
            }
        }

        public static bool IsSpecialEntryType(TVBridgeCBot.StrategyEntryType entryType)
        {
            switch (entryType)
            {
                case TVBridgeCBot.StrategyEntryType.candle_mid:
                case TVBridgeCBot.StrategyEntryType.candle_retest:
                case TVBridgeCBot.StrategyEntryType.ltf_Key_levels:
                case TVBridgeCBot.StrategyEntryType.HTF_Key_levels:
                case TVBridgeCBot.StrategyEntryType.fvg_mid:
                case TVBridgeCBot.StrategyEntryType.ob_mid:
                case TVBridgeCBot.StrategyEntryType.reclaim_retest:
                    return true;
                default:
                    return false;
            }
        }

        public static TVBridgeCBot.BacktestStrategySignal CreateSignal(
            string strategyId,
            TVBridgeCBot.BacktestStrategyMode strategyMode,
            string symbolName,
            string sourceLabel,
            TradeType tradeType,
            TimeFrame sourceTimeFrame,
            DateTime signalTime)
        {
            return new TVBridgeCBot.BacktestStrategySignal
            {
                IsValid = true,
                StrategyId = strategyId ?? "",
                StrategyMode = strategyMode,
                SymbolName = symbolName ?? "",
                SourceLabel = sourceLabel ?? "",
                TradeType = tradeType,
                SourceTimeFrame = sourceTimeFrame,
                SignalTime = signalTime
            };
        }

        public static bool TryBuildImpulseSignal(
            Symbol symbol,
            double open, double high, double low, double close,
            double minimumBodyPercent, double priceTolerance, double rewardRisk,
            TimeFrame sourceTimeFrame, DateTime signalTime,
            out TVBridgeCBot.BacktestStrategySignal signal)
        {
            signal = default(TVBridgeCBot.BacktestStrategySignal);
            if (symbol == null)
                return false;
            bool bullish;
            double bodyPercent;
            if (!CTraderCandlePatternEngine.TryResolveBigCandleDirection(
                    open, high, low, close,
                    minimumBodyPercent, priceTolerance,
                    out bullish, out bodyPercent))
                return false;
            var candleRange = Math.Abs(high - low);
            var entryPrice = CTraderRiskEngine.NormalizePrice(
                symbol,
                bullish ? close - candleRange * 0.25 : close + candleRange * 0.25);
            if (!(entryPrice > 0) || !(candleRange > 0))
                return false;
            var stopLoss = CTraderRiskEngine.NormalizePrice(
                symbol,
                bullish ? entryPrice - candleRange : entryPrice + candleRange);
            var ratio = Math.Max(0.1, rewardRisk);
            var takeProfit = CTraderRiskEngine.NormalizePrice(
                symbol,
                bullish ? entryPrice + candleRange * ratio : entryPrice - candleRange * ratio);
            signal = new TVBridgeCBot.BacktestStrategySignal
            {
                IsValid = true,
                StrategyMode = TVBridgeCBot.BacktestStrategyMode.Impulse,
                StrategyId = "follow_trend_big_candle",
                SourceLabel = string.Format(CultureInfo.InvariantCulture, "BC {0:0.#}%", bodyPercent),
                TradeType = bullish ? TradeType.Buy : TradeType.Sell,
                SourceTimeFrame = sourceTimeFrame,
                SignalTime = signalTime,
                UseLimitOrder = true,
                EntryPrice = entryPrice,
                StopLoss = stopLoss,
                TakeProfit = takeProfit,
                Note = string.Format(
                    CultureInfo.InvariantCulture,
                    "[body={0:0.#}% close={1} entry=1/4c rr={2:0.##}]",
                    bodyPercent,
                    bullish ? "high" : "low",
                    ratio)
            };
            return true;
        }

        public static bool TryBuildTrendSignal(
            Symbol symbol,
            string symbolName,
            Bars sourceBars,
            int signalIndex,
            int candleCount,
            int stopOffsetFromEnd,
            double rewardRisk,
            TimeFrame sourceTimeFrame,
            DateTime signalTime,
            out TVBridgeCBot.BacktestStrategySignal signal)
        {
            signal = default(TVBridgeCBot.BacktestStrategySignal);
            if (symbol == null || sourceBars == null || candleCount < 1 || signalIndex < candleCount - 1 || signalIndex >= sourceBars.Count)
                return false;
            var startIndex = signalIndex - candleCount + 1;
            var bullishSequence = true;
            var bearishSequence = true;
            for (var index = startIndex; index <= signalIndex; index++)
            {
                if (sourceBars.ClosePrices[index] <= sourceBars.OpenPrices[index])
                    bullishSequence = false;
                if (sourceBars.ClosePrices[index] >= sourceBars.OpenPrices[index])
                    bearishSequence = false;
            }
            if (!bullishSequence && !bearishSequence)
                return false;
            var tradeType = bullishSequence ? TradeType.Buy : TradeType.Sell;
            var entryPrice = CTraderRiskEngine.NormalizePrice(symbol, sourceBars.ClosePrices[signalIndex]);
            var stopIndex = Math.Max(startIndex, Math.Min(signalIndex, signalIndex - Math.Max(0, stopOffsetFromEnd)));
            var rawStop = tradeType == TradeType.Buy
                ? Math.Min(sourceBars.LowPrices[stopIndex], Math.Min(sourceBars.OpenPrices[stopIndex], sourceBars.ClosePrices[stopIndex]))
                : Math.Max(sourceBars.HighPrices[stopIndex], Math.Max(sourceBars.OpenPrices[stopIndex], sourceBars.ClosePrices[stopIndex]));
            if (tradeType == TradeType.Buy && rawStop >= entryPrice)
            {
                for (var index = startIndex; index <= signalIndex; index++)
                    rawStop = Math.Min(rawStop, sourceBars.LowPrices[index]);
            }
            else if (tradeType == TradeType.Sell && rawStop <= entryPrice)
            {
                for (var index = startIndex; index <= signalIndex; index++)
                    rawStop = Math.Max(rawStop, sourceBars.HighPrices[index]);
            }
            var stopLoss = CTraderRiskEngine.NormalizePrice(symbol, rawStop);
            var riskDistance = tradeType == TradeType.Buy ? entryPrice - stopLoss : stopLoss - entryPrice;
            if (!(riskDistance > 0))
                return false;
            var ratio = Math.Max(0.1, rewardRisk);
            signal = new TVBridgeCBot.BacktestStrategySignal
            {
                IsValid = true,
                StrategyId = "follow_trend",
                StrategyMode = TVBridgeCBot.BacktestStrategyMode.Trend,
                SymbolName = symbolName ?? "",
                SourceLabel = tradeType == TradeType.Buy ? "n green" : "n red",
                TradeType = tradeType,
                SourceTimeFrame = sourceTimeFrame,
                SignalTime = signalTime,
                EntryPrice = entryPrice,
                StopLoss = stopLoss,
                TakeProfit = CTraderRiskEngine.NormalizePrice(
                    symbol,
                    tradeType == TradeType.Buy ? entryPrice + riskDistance * ratio : entryPrice - riskDistance * ratio),
                Note = string.Format(
                    CultureInfo.InvariantCulture,
                    "[Continue N={0} SL#{1} RR={2:0.##}]",
                    candleCount,
                    Math.Max(0, stopOffsetFromEnd),
                    ratio)
            };
            return true;
        }

        public static bool TryResolveCrossDirection(
            double leftPrevious, double leftCurrent,
            double rightPrevious, double rightCurrent,
            out TradeType tradeType)
        {
            tradeType = TradeType.Buy;
            if (CTraderTechnicalEngine.CrossesAbove(leftPrevious, leftCurrent, rightPrevious, rightCurrent))
                return true;
            if (CTraderTechnicalEngine.CrossesBelow(leftPrevious, leftCurrent, rightPrevious, rightCurrent))
            {
                tradeType = TradeType.Sell;
                return true;
            }
            return false;
        }

        public static bool TryResolveTripleTrendDirection(
            double fastPrevious, double fastCurrent,
            double middlePrevious, double middleCurrent,
            double slowCurrent,
            out TradeType tradeType)
        {
            tradeType = TradeType.Buy;
            if (CTraderTechnicalEngine.CrossesAbove(fastPrevious, fastCurrent, middlePrevious, middleCurrent) &&
                fastCurrent > middleCurrent && middleCurrent > slowCurrent)
                return true;
            if (CTraderTechnicalEngine.CrossesBelow(fastPrevious, fastCurrent, middlePrevious, middleCurrent) &&
                fastCurrent < middleCurrent && middleCurrent < slowCurrent)
            {
                tradeType = TradeType.Sell;
                return true;
            }
            return false;
        }

        public static bool TryResolveBollingerReversionDirection(
            double previousClose, double currentClose,
            double previousLower, double previousUpper, double currentMiddle,
            out TradeType tradeType)
        {
            tradeType = TradeType.Buy;
            if (previousClose < previousLower && currentClose > currentMiddle)
                return true;
            if (previousClose > previousUpper && currentClose < currentMiddle)
            {
                tradeType = TradeType.Sell;
                return true;
            }
            return false;
        }

        public static bool TryResolveThresholdReversionDirection(
            double previousValue, double currentValue,
            double lowerThreshold, double upperThreshold,
            out TradeType tradeType)
        {
            tradeType = TradeType.Buy;
            if (CTraderTechnicalEngine.CrossesAbove(previousValue, currentValue, lowerThreshold, lowerThreshold))
                return true;
            if (CTraderTechnicalEngine.CrossesBelow(previousValue, currentValue, upperThreshold, upperThreshold))
            {
                tradeType = TradeType.Sell;
                return true;
            }
            return false;
        }

        public static bool TryResolveFvgContextDirection(
            bool bullishBias, bool bearishBias,
            double barLow, double barHigh, double barClose, double zoneMid,
            out TradeType tradeType)
        {
            tradeType = TradeType.Buy;
            if (!(zoneMid > 0) || barLow > zoneMid || barHigh < zoneMid)
                return false;
            if (bullishBias && barClose > zoneMid)
                return true;
            if (bearishBias && barClose < zoneMid)
            {
                tradeType = TradeType.Sell;
                return true;
            }
            return false;
        }

        public static bool TryResolveDonchianBreakoutDirection(
            double close, double channelHigh, double channelLow, out TradeType tradeType)
        {
            tradeType = TradeType.Buy;
            if (close > channelHigh)
                return true;
            if (close < channelLow)
            {
                tradeType = TradeType.Sell;
                return true;
            }
            return false;
        }

        public static bool TryResolvePriceActionDirection(
            bool bullishBias, bool bearishBias,
            bool bullishTrigger, bool bearishTrigger,
            out TradeType tradeType)
        {
            tradeType = TradeType.Buy;
            if (bullishBias && bullishTrigger)
                return true;
            if (bearishBias && bearishTrigger)
            {
                tradeType = TradeType.Sell;
                return true;
            }
            return false;
        }

        public static bool TryResolveCandleEntry(
            Symbol symbol, TradeType tradeType, double executionPrice,
            double open, double high, double low, bool midpoint,
            out double entryPrice)
        {
            entryPrice = 0;
            if (symbol == null || executionPrice <= 0)
                return false;
            var rawEntry = midpoint ? (high + low) * 0.5 : open;
            var normalized = CTraderRiskEngine.NormalizePrice(symbol, rawEntry);
            if (tradeType == TradeType.Buy ? normalized >= executionPrice : normalized <= executionPrice)
                return false;
            entryPrice = normalized;
            return entryPrice > 0;
        }

        public static bool TryApplyEntryType(
            Symbol symbol,
            TVBridgeCBot.StrategyEntryType entryType,
            TradeType tradeType,
            double executionPrice,
            double currentEntry,
            double stopLoss,
            Func<double?> specialEntryResolver,
            out bool useLimitOrder,
            out double entryPrice,
            out string rejectReason)
        {
            useLimitOrder = false;
            entryPrice = currentEntry;
            rejectReason = "";
            if (symbol == null || currentEntry <= 0 || stopLoss <= 0)
            {
                rejectReason = "entry_mode_invalid_input";
                return false;
            }
            var riskDistance = Math.Abs(currentEntry - stopLoss);
            if (!(riskDistance > 0))
            {
                rejectReason = "entry_mode_invalid_risk_distance";
                return false;
            }
            var specialEntry = IsSpecialEntryType(entryType) && specialEntryResolver != null
                ? specialEntryResolver()
                : null;
            if (specialEntry.HasValue)
            {
                useLimitOrder = true;
                entryPrice = specialEntry.Value;
                return true;
            }
            if (IsSpecialEntryType(entryType))
            {
                rejectReason = "entry_mode_unresolved mode=" + entryType;
                return false;
            }
            if (entryType == TVBridgeCBot.StrategyEntryType._0_limit)
            {
                useLimitOrder = true;
                var tinyBuffer = Math.Max(symbol.PipSize, symbol.TickSize);
                if (!(tinyBuffer > 0))
                {
                    rejectReason = "entry_mode_invalid_tick_size";
                    return false;
                }
                entryPrice = CTraderRiskEngine.NormalizePrice(
                    symbol,
                    tradeType == TradeType.Buy ? currentEntry - tinyBuffer : currentEntry + tinyBuffer);
                if (tradeType == TradeType.Buy && entryPrice >= executionPrice)
                    entryPrice = CTraderRiskEngine.NormalizePrice(symbol, executionPrice - tinyBuffer);
                else if (tradeType == TradeType.Sell && entryPrice <= executionPrice)
                    entryPrice = CTraderRiskEngine.NormalizePrice(symbol, executionPrice + tinyBuffer);
                return true;
            }
            var multiplier = ResolveEntryBufferMultiplier(entryType);
            if (multiplier <= 0)
                return true;
            useLimitOrder = true;
            var buffer = riskDistance * multiplier;
            if (!(buffer > 0))
            {
                rejectReason = "entry_mode_invalid_retracement";
                return false;
            }
            entryPrice = CTraderRiskEngine.NormalizePrice(
                symbol,
                tradeType == TradeType.Buy ? currentEntry - buffer : currentEntry + buffer);
            return true;
        }

        public static bool TrySelectEntryLevel(
            Symbol symbol, IEnumerable<double> levels,
            TradeType tradeType, double executionPrice, double stopLoss,
            out double entryPrice)
        {
            entryPrice = 0;
            if (symbol == null || levels == null || executionPrice <= 0 || stopLoss <= 0)
                return false;
            var selected = tradeType == TradeType.Buy
                ? levels.Where(level => level > stopLoss && level < executionPrice).OrderBy(level => Math.Abs(level - executionPrice)).FirstOrDefault()
                : levels.Where(level => level < stopLoss && level > executionPrice).OrderBy(level => Math.Abs(level - executionPrice)).FirstOrDefault();
            if (!(selected > 0))
                return false;
            entryPrice = CTraderRiskEngine.NormalizePrice(symbol, selected);
            return entryPrice > 0;
        }

        public static bool TrySelectWeightedEntryLevel(
            Symbol symbol, IEnumerable<CTraderStrategyLevelCandidate> levels,
            TradeType tradeType, double executionPrice, double stopLoss,
            out double entryPrice)
        {
            entryPrice = 0;
            if (symbol == null || levels == null || executionPrice <= 0 || stopLoss <= 0)
                return false;
            var selected = tradeType == TradeType.Buy
                ? levels.Where(level => level != null && level.Price > stopLoss && level.Price < executionPrice)
                    .OrderBy(level => Math.Abs(level.Price - executionPrice)).ThenByDescending(level => level.Weight).FirstOrDefault()
                : levels.Where(level => level != null && level.Price < stopLoss && level.Price > executionPrice)
                    .OrderBy(level => Math.Abs(level.Price - executionPrice)).ThenByDescending(level => level.Weight).FirstOrDefault();
            if (selected == null || selected.Price <= 0)
                return false;
            entryPrice = CTraderRiskEngine.NormalizePrice(symbol, selected.Price);
            return entryPrice > 0;
        }

        public static bool TrySelectWeightedProtectionLevel(
            IEnumerable<CTraderStrategyLevelCandidate> levels,
            TradeType tradeType, double entryPrice, bool isStopLoss,
            out double price)
        {
            price = 0;
            if (levels == null || entryPrice <= 0)
                return false;
            var wantBelow = tradeType == TradeType.Buy ? isStopLoss : !isStopLoss;
            var selected = levels
                .Where(candidate => candidate != null && candidate.Price > 0)
                .Where(candidate => wantBelow ? candidate.Price < entryPrice : candidate.Price > entryPrice)
                .OrderBy(candidate => Math.Abs(candidate.Price - entryPrice))
                .ThenByDescending(candidate => candidate.Weight)
                .FirstOrDefault();
            if (selected == null || selected.Price <= 0)
                return false;
            price = selected.Price;
            return true;
        }

        public static double SelectProtectiveSwing(
            IEnumerable<CTraderStructureSwing> swings,
            TradeType tradeType, int signalIndex,
            double patternEdge, double tolerance)
        {
            if (!(patternEdge > 0))
                return 0;
            var values = swings ?? Enumerable.Empty<CTraderStructureSwing>();
            var selected = tradeType == TradeType.Buy
                ? values.Where(swing => swing != null && !swing.IsHigh && swing.Index <= signalIndex && swing.Price <= patternEdge + tolerance)
                    .OrderBy(swing => Math.Abs(patternEdge - swing.Price)).ThenByDescending(swing => swing.Index).FirstOrDefault()
                : values.Where(swing => swing != null && swing.IsHigh && swing.Index <= signalIndex && swing.Price >= patternEdge - tolerance)
                    .OrderBy(swing => Math.Abs(swing.Price - patternEdge)).ThenByDescending(swing => swing.Index).FirstOrDefault();
            return selected != null && selected.Price > 0 ? selected.Price : patternEdge;
        }

        public static double ResolveRetracementEntry(Symbol symbol, TradeType tradeType, double baseEntry, double stopLoss, double retracementRatio)
        {
            if (symbol == null || !(baseEntry > 0) || !(stopLoss > 0))
                return 0;
            var ratio = Math.Max(0.0, Math.Min(1.0, retracementRatio));
            var entry = tradeType == TradeType.Buy
                ? baseEntry - ((baseEntry - stopLoss) * ratio)
                : baseEntry + ((stopLoss - baseEntry) * ratio);
            return CTraderRiskEngine.NormalizePrice(symbol, entry);
        }

        public static List<double> BuildRetracementEntries(Symbol symbol, TradeType tradeType, double baseEntry, double stopLoss, IEnumerable<double> ratios)
        {
            var entries = new List<double>();
            if (symbol == null || !(baseEntry > 0) || !(stopLoss > 0))
                return entries;
            var tolerance = Math.Max(symbol.PipSize * 0.5, 0.0000001);
            foreach (var ratio in ratios ?? Enumerable.Empty<double>())
            {
                var entry = ResolveRetracementEntry(symbol, tradeType, baseEntry, stopLoss, ratio);
                var valid = tradeType == TradeType.Buy
                    ? entry > stopLoss && entry < baseEntry
                    : entry < stopLoss && entry > baseEntry;
                if (entry > 0 && valid && !entries.Any(existing => Math.Abs(existing - entry) < tolerance))
                    entries.Add(entry);
            }
            return entries;
        }

        public static bool TryResolveCandleWickStopLoss(
            Symbol symbol, TradeType tradeType, double entryPrice,
            double open, double high, double low, double close,
            double wickMultiplier, double buffer, out double stopLoss)
        {
            stopLoss = 0;
            if (symbol == null || entryPrice <= 0)
                return false;
            var multiplier = Math.Max(0.1, wickMultiplier);
            if (tradeType == TradeType.Buy)
            {
                var anchor = Math.Min(entryPrice, Math.Min(open, close));
                if (!(anchor > low))
                    return false;
                stopLoss = CTraderRiskEngine.NormalizePrice(symbol, anchor - ((anchor - low) * multiplier) - Math.Max(0, buffer));
            }
            else
            {
                var anchor = Math.Max(entryPrice, Math.Max(open, close));
                if (!(anchor < high))
                    return false;
                stopLoss = CTraderRiskEngine.NormalizePrice(symbol, anchor + ((high - anchor) * multiplier) + Math.Max(0, buffer));
            }
            return stopLoss > 0;
        }

        public static bool TryResolveRangeProtection(
            Symbol symbol, TradeType tradeType, double entryPrice,
            IEnumerable<double> lows, IEnumerable<double> highs,
            bool isStopLoss, double buffer, out double price)
        {
            price = 0;
            if (symbol == null || entryPrice <= 0 || lows == null || highs == null)
                return false;
            var lowValues = lows.ToList();
            var highValues = highs.ToList();
            if (lowValues.Count == 0 || highValues.Count == 0)
                return false;
            var raw = tradeType == TradeType.Buy
                ? (isStopLoss ? lowValues.Min() - buffer : highValues.Max() + buffer)
                : (isStopLoss ? highValues.Max() + buffer : lowValues.Min() - buffer);
            var valid = tradeType == TradeType.Buy
                ? (isStopLoss ? raw < entryPrice : raw > entryPrice)
                : (isStopLoss ? raw > entryPrice : raw < entryPrice);
            if (!valid)
                return false;
            price = CTraderRiskEngine.NormalizePrice(symbol, raw);
            return price > 0;
        }

        public static bool TryResolvePatternStopLoss(
            Symbol symbol, TradeType tradeType, double entryPrice,
            double patternLow, double patternHigh, double buffer, out double stopLoss)
        {
            stopLoss = 0;
            if (symbol == null || entryPrice <= 0)
                return false;
            var raw = tradeType == TradeType.Buy ? patternLow : patternHigh;
            if (!(raw > 0) || (tradeType == TradeType.Buy ? raw >= entryPrice : raw <= entryPrice))
                return false;
            stopLoss = CTraderRiskEngine.NormalizePrice(symbol, tradeType == TradeType.Buy ? raw - buffer : raw + buffer);
            return stopLoss > 0;
        }

        public static bool TryResolveInvalidationStopLoss(
            Symbol symbol, TradeType tradeType, double entryPrice,
            IEnumerable<double> relatedLevels, double zoneLow, double zoneHigh,
            double patternLow, double patternHigh, double buffer, bool furthest,
            out double stopLoss)
        {
            stopLoss = 0;
            if (symbol == null || entryPrice <= 0)
                return false;
            var isBuy = tradeType == TradeType.Buy;
            var candidates = (relatedLevels ?? Enumerable.Empty<double>()).Where(level => level > 0).ToList();
            if (zoneHigh > zoneLow && zoneLow > 0)
            {
                if (furthest)
                {
                    candidates.Add(zoneLow);
                    candidates.Add(zoneHigh);
                }
                else
                {
                    candidates.Add(isBuy ? zoneLow : zoneHigh);
                }
                candidates.Add((zoneLow + zoneHigh) * 0.5);
            }
            if (patternLow > 0 && (furthest || isBuy)) candidates.Add(patternLow);
            if (patternHigh > 0 && (furthest || !isBuy)) candidates.Add(patternHigh);
            var selected = isBuy
                ? (furthest
                    ? candidates.Where(level => level < entryPrice).OrderBy(level => level).FirstOrDefault()
                    : candidates.Where(level => level < entryPrice).OrderByDescending(level => level).FirstOrDefault())
                : (furthest
                    ? candidates.Where(level => level > entryPrice).OrderByDescending(level => level).FirstOrDefault()
                    : candidates.Where(level => level > entryPrice).OrderBy(level => level).FirstOrDefault());
            if (!(selected > 0))
                return false;
            stopLoss = CTraderRiskEngine.NormalizePrice(symbol, isBuy ? selected - buffer : selected + buffer);
            return stopLoss > 0;
        }

        public static bool TrySelectDirectionalLevel(
            IEnumerable<double> levels, TradeType tradeType, double entryPrice, bool isStopLoss, out double price)
        {
            price = 0;
            if (levels == null || entryPrice <= 0)
                return false;
            var wantBelow = tradeType == TradeType.Buy ? isStopLoss : !isStopLoss;
            price = wantBelow
                ? levels.Where(level => level > 0 && level < entryPrice).OrderByDescending(level => level).FirstOrDefault()
                : levels.Where(level => level > entryPrice).OrderBy(level => level).FirstOrDefault();
            return price > 0;
        }

        public static double ResolveRewardRiskTarget(
            Symbol symbol, TradeType tradeType, double entryPrice, double stopLoss,
            double rewardRisk, double multiplier)
        {
            if (symbol == null || entryPrice <= 0 || stopLoss <= 0)
                return 0;
            var riskDistance = tradeType == TradeType.Buy ? entryPrice - stopLoss : stopLoss - entryPrice;
            if (!(riskDistance > 0))
                return 0;
            var ratio = Math.Max(0.1, rewardRisk) * (multiplier > 0 ? multiplier : 1.0);
            var target = tradeType == TradeType.Buy
                ? entryPrice + riskDistance * ratio
                : entryPrice - riskDistance * ratio;
            var normalized = CTraderRiskEngine.NormalizePrice(symbol, target);
            var outwardTick = Math.Max(symbol.TickSize, 0.0000001);
            if (tradeType == TradeType.Buy && normalized < target)
                normalized = CTraderRiskEngine.NormalizePrice(symbol, normalized + outwardTick);
            else if (tradeType == TradeType.Sell && normalized > target)
                normalized = CTraderRiskEngine.NormalizePrice(symbol, normalized - outwardTick);
            return normalized;
        }

        public static double EnforceMinimumRewardRisk(
            Symbol symbol, TradeType tradeType, double entryPrice, double stopLoss,
            double takeProfit, double minimumRewardRisk)
        {
            if (symbol == null || entryPrice <= 0 || stopLoss <= 0)
                return takeProfit;
            var riskDistance = tradeType == TradeType.Buy ? entryPrice - stopLoss : stopLoss - entryPrice;
            if (!(riskDistance > 0))
                return takeProfit;
            var minimumRewardDistance = riskDistance * Math.Max(0.1, minimumRewardRisk);
            var currentRewardDistance = tradeType == TradeType.Buy ? takeProfit - entryPrice : entryPrice - takeProfit;
            if (currentRewardDistance >= minimumRewardDistance)
                return takeProfit;
            var rawTarget = tradeType == TradeType.Buy ? entryPrice + minimumRewardDistance : entryPrice - minimumRewardDistance;
            var normalized = CTraderRiskEngine.NormalizePrice(symbol, rawTarget);
            var outwardTick = Math.Max(symbol.TickSize, 0.0000001);
            if (tradeType == TradeType.Buy && normalized < rawTarget)
                normalized = CTraderRiskEngine.NormalizePrice(symbol, normalized + outwardTick);
            else if (tradeType == TradeType.Sell && normalized > rawTarget)
                normalized = CTraderRiskEngine.NormalizePrice(symbol, normalized - outwardTick);
            return normalized;
        }

        public static List<double> BuildSplitEntries(
            Symbol symbol, TradeType tradeType, double baseEntry, double stopLoss,
            int totalLegCount, double minimumStopPips)
        {
            var entries = new List<double>();
            if (symbol == null || symbol.PipSize <= 0 || baseEntry <= 0 || stopLoss <= 0)
                return entries;
            var legCount = Math.Max(1, Math.Min(5, totalLegCount));
            var minOffset = Math.Max(minimumStopPips, 1.0) * symbol.PipSize;
            var safeNearStop = tradeType == TradeType.Buy ? stopLoss + minOffset : stopLoss - minOffset;
            entries.Add(CTraderRiskEngine.NormalizePrice(symbol, baseEntry));
            if (legCount == 1 || (tradeType == TradeType.Buy ? safeNearStop >= baseEntry : safeNearStop <= baseEntry))
                return entries;
            var ratios = new[] { 0.3, 0.5, 0.7, 0.9 };
            var tolerance = Math.Max(symbol.PipSize * 0.5, 0.0000001);
            for (var index = 1; index < legCount; index++)
            {
                var candidate = CTraderRiskEngine.NormalizePrice(symbol, baseEntry + ((safeNearStop - baseEntry) * ratios[index - 1]));
                var valid = tradeType == TradeType.Buy ? candidate < baseEntry && candidate > stopLoss : candidate > baseEntry && candidate < stopLoss;
                if (valid && !entries.Any(existing => Math.Abs(existing - candidate) < tolerance))
                    entries.Add(candidate);
            }
            return entries;
        }
    }

    // Broker protection values prepared before cTrader modify/submit calls.
    internal sealed class CTraderExecutionProtectionPlan
    {
        public bool IsValid;
        public double TargetPrice;
        public double StopLossPrice;
        public double TakeProfitPrice;
        public double? StopLossPips;
        public double? TakeProfitPips;
        public string Error;
    }

    internal sealed class CTraderExecutionReversePlan
    {
        public bool IsValid;
        public TradeType TradeType;
        public string Action;
        public double EntryPrice;
        public double StopLoss;
        public double TakeProfit;
        public double RiskDistance;
        public string Error;
    }

    // Owns deterministic execution plans. Broker API calls and live account gates stay in TVBridgeCBot.
    internal static class CTraderExecutionEngine
    {
        public static bool UsesNativeTrailing(TVBridgeCBot.StrategyExitMode mode)
        {
            return mode == TVBridgeCBot.StrategyExitMode.Trailing_Stop ||
                mode == TVBridgeCBot.StrategyExitMode.Trailing_Stop_Reversed_when_SL;
        }

        public static bool UsesNativeBreakEven(TVBridgeCBot.StrategyExitMode mode)
        {
            return mode == TVBridgeCBot.StrategyExitMode.Break_Even ||
                mode == TVBridgeCBot.StrategyExitMode.Break_Even_Reversed_when_SL;
        }

        public static bool ReversesStoppedPosition(TVBridgeCBot.StrategyExitMode mode)
        {
            return mode == TVBridgeCBot.StrategyExitMode.Reversed_when_SL ||
                mode == TVBridgeCBot.StrategyExitMode.Trailing_Stop_Reversed_when_SL ||
                mode == TVBridgeCBot.StrategyExitMode.Break_Even_Reversed_when_SL;
        }

        public static double ResolveBreakEvenTriggerPips(double entryPrice, double stopLoss, double pipSize)
        {
            return pipSize > 0
                ? Math.Max(10.1, Math.Abs(entryPrice - stopLoss) / pipSize)
                : 0;
        }

        public static double? ResolveDistancePips(
            Symbol symbol,
            double referencePrice,
            double protectionPrice,
            int decimals = 2)
        {
            if (symbol == null || symbol.PipSize <= 0 || !(referencePrice > 0) || !(protectionPrice > 0))
                return null;
            return Math.Round(Math.Abs(referencePrice - protectionPrice) / symbol.PipSize, decimals);
        }

        public static bool HasRequiredProtection(
            bool hasStopLoss,
            bool hasTakeProfit,
            bool needsStopLoss,
            bool needsTakeProfit)
        {
            return (!needsStopLoss || hasStopLoss) && (!needsTakeProfit || hasTakeProfit);
        }

        public static bool IsProtectionCloseEnough(
            double? currentPrice,
            double expectedPrice,
            bool required,
            double tolerance)
        {
            return !required ||
                (currentPrice.HasValue && Math.Abs(currentPrice.Value - expectedPrice) <= tolerance);
        }

        public static double ResolveAdjustedProtectionPrice(
            Symbol symbol,
            string action,
            double entryPrice,
            bool isStopLoss,
            double minimumStopPips)
        {
            if (symbol == null || symbol.PipSize <= 0 || !(entryPrice > 0))
                return 0;
            var distance = Math.Max(1.0, minimumStopPips) * symbol.PipSize;
            var isSell = string.Equals(action, "SELL", StringComparison.OrdinalIgnoreCase);
            var price = isStopLoss
                ? (isSell ? entryPrice + distance : entryPrice - distance)
                : (isSell ? entryPrice - distance : entryPrice + distance);
            return CTraderRiskEngine.NormalizePrice(symbol, price);
        }

        public static HashSet<long> CapturePositionIds(IEnumerable<Position> positions)
        {
            return new HashSet<long>((positions ?? Enumerable.Empty<Position>())
                .Where(position => position != null)
                .Select(position => (long)position.Id));
        }

        public static Position FindPositionCreatedAfterSubmit(
            IEnumerable<Position> positions,
            ISet<long> previousPositionIds,
            string symbolName,
            string label,
            TradeType tradeType)
        {
            return (positions ?? Enumerable.Empty<Position>())
                .Where(position => position != null)
                .Where(position => previousPositionIds == null || !previousPositionIds.Contains((long)position.Id))
                .Where(position => string.Equals(position.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase))
                .Where(position => position.TradeType == tradeType)
                .Where(position => string.Equals(position.Label, label, StringComparison.OrdinalIgnoreCase))
                .OrderByDescending(position => position.Id)
                .FirstOrDefault();
        }

        public static bool TryBuildReversePlan(
            Symbol symbol,
            TradeType closedTradeType,
            double closedEntryPrice,
            double closedStopLoss,
            double bid,
            double ask,
            double rewardRisk,
            out CTraderExecutionReversePlan plan)
        {
            plan = new CTraderExecutionReversePlan();
            if (symbol == null || symbol.PipSize <= 0 || !(closedEntryPrice > 0) || !(closedStopLoss > 0))
            {
                plan.Error = "symbol_or_original_sl_unavailable";
                return false;
            }

            var riskDistance = Math.Abs(closedEntryPrice - closedStopLoss);
            if (!CTraderTechnicalEngine.IsFinite(riskDistance) || !(riskDistance > 0))
            {
                plan.Error = "invalid_original_risk_distance";
                return false;
            }

            var reverseTradeType = closedTradeType == TradeType.Buy ? TradeType.Sell : TradeType.Buy;
            var executionPrice = reverseTradeType == TradeType.Buy ? ask : bid;
            if (!CTraderTechnicalEngine.IsFinite(executionPrice) || !(executionPrice > 0))
            {
                plan.Error = "invalid_execution_price";
                return false;
            }

            var ratio = Math.Max(0.1, rewardRisk);
            plan.IsValid = true;
            plan.TradeType = reverseTradeType;
            plan.Action = reverseTradeType == TradeType.Buy ? "BUY" : "SELL";
            plan.EntryPrice = executionPrice;
            plan.RiskDistance = riskDistance;
            plan.StopLoss = CTraderRiskEngine.NormalizePrice(
                symbol,
                reverseTradeType == TradeType.Buy ? executionPrice - riskDistance : executionPrice + riskDistance);
            plan.TakeProfit = CTraderRiskEngine.NormalizePrice(
                symbol,
                reverseTradeType == TradeType.Buy ? executionPrice + riskDistance * ratio : executionPrice - riskDistance * ratio);
            return true;
        }

        public static void ReanchorProtectionToFilledEntry(
            Symbol symbol,
            string action,
            double plannedEntry,
            double filledEntry,
            ref double stopLoss,
            ref double takeProfit)
        {
            if (symbol == null || plannedEntry <= 0 || filledEntry <= 0)
                return;
            string reason;
            if (CTraderStrategyEngine.TryValidatePrices(symbol, action, filledEntry, stopLoss, takeProfit, out reason))
                return;

            var stopDistance = stopLoss > 0 ? Math.Abs(stopLoss - plannedEntry) : 0;
            var targetDistance = takeProfit > 0 ? Math.Abs(takeProfit - plannedEntry) : 0;
            var isSell = string.Equals(action, "SELL", StringComparison.OrdinalIgnoreCase);
            if (stopDistance > 0)
            {
                stopLoss = CTraderRiskEngine.NormalizePrice(
                    symbol,
                    isSell ? filledEntry + stopDistance : filledEntry - stopDistance);
            }
            if (targetDistance > 0)
            {
                takeProfit = CTraderRiskEngine.NormalizePrice(
                    symbol,
                    isSell ? filledEntry - targetDistance : filledEntry + targetDistance);
            }
        }

        public static CTraderExecutionProtectionPlan BuildPendingProtectionPlan(
            Symbol symbol,
            string action,
            double targetPrice,
            double stopLossPrice,
            double takeProfitPrice)
        {
            var plan = new CTraderExecutionProtectionPlan { Error = "" };
            if (symbol == null || symbol.PipSize <= 0)
            {
                plan.Error = "symbol_missing";
                return plan;
            }

            plan.TargetPrice = CTraderRiskEngine.NormalizePrice(symbol, targetPrice);
            plan.StopLossPrice = stopLossPrice > 0 ? CTraderRiskEngine.NormalizePrice(symbol, stopLossPrice) : 0;
            plan.TakeProfitPrice = takeProfitPrice > 0 ? CTraderRiskEngine.NormalizePrice(symbol, takeProfitPrice) : 0;
            if (!(plan.StopLossPrice > 0))
            {
                plan.Error = "pending_stop_loss_missing";
                return plan;
            }

            string reason;
            if (!CTraderStrategyEngine.TryValidatePrices(
                    symbol, action, plan.TargetPrice, plan.StopLossPrice, plan.TakeProfitPrice, out reason))
            {
                plan.Error = "pending_protection_rejected: " + reason;
                return plan;
            }

            var isBuy = string.Equals(action, "BUY", StringComparison.OrdinalIgnoreCase);
            plan.StopLossPips = Math.Round(
                (isBuy ? plan.TargetPrice - plan.StopLossPrice : plan.StopLossPrice - plan.TargetPrice) / symbol.PipSize,
                2);
            if (plan.TakeProfitPrice > 0)
            {
                plan.TakeProfitPips = Math.Round(
                    (isBuy ? plan.TakeProfitPrice - plan.TargetPrice : plan.TargetPrice - plan.TakeProfitPrice) / symbol.PipSize,
                    2);
            }
            if (plan.StopLossPips.Value <= 0)
            {
                plan.Error = "pending_sl_pips_invalid";
                return plan;
            }
            if (plan.TakeProfitPips.HasValue && plan.TakeProfitPips.Value <= 0)
            {
                plan.Error = "pending_tp_pips_invalid";
                return plan;
            }

            plan.IsValid = true;
            return plan;
        }

        public static bool TryResolveAffordableSplitLegs(
            Symbol symbol,
            IList<double> entries,
            IList<double> weights,
            double stopLoss,
            double finalRiskMoney,
            List<double> affordableEntries,
            List<double> affordableWeights)
        {
            affordableEntries.Clear();
            affordableWeights.Clear();
            if (symbol == null || entries == null || weights == null || stopLoss <= 0)
                return false;

            var totalInputWeight = 0.0;
            var alignedCount = Math.Min(entries.Count, weights.Count);
            for (var i = 0; i < alignedCount; i++)
                totalInputWeight += weights[i];
            for (var i = 0; i < alignedCount; i++)
            {
                var sliceRiskMoney = finalRiskMoney > 0 ? Math.Max(0, finalRiskMoney * weights[i]) : 0;
                if (!(sliceRiskMoney > 0))
                    continue;
                var minRiskForLeg = CTraderRiskEngine.EstimateRisk(
                    symbol, entries[i], stopLoss, symbol.VolumeInUnitsMin);
                if (minRiskForLeg > 0 && sliceRiskMoney < minRiskForLeg)
                    continue;
                affordableEntries.Add(entries[i]);
                affordableWeights.Add(weights[i]);
            }
            if (affordableEntries.Count == 0)
                return false;

            var keptWeightSum = affordableWeights.Sum();
            if (keptWeightSum > 0 && totalInputWeight > 0)
            {
                var scale = totalInputWeight / keptWeightSum;
                for (var i = 0; i < affordableWeights.Count; i++)
                    affordableWeights[i] *= scale;
            }
            return true;
        }

        public static double ResolveNormalizedPartialCloseVolume(
            Symbol symbol,
            double positionVolume,
            double percentToClose)
        {
            if (symbol == null || !(positionVolume > 0) || !(percentToClose > 0))
                return 0;
            if (percentToClose >= 100)
                return positionVolume;
            var volume = symbol.NormalizeVolumeInUnits(
                positionVolume * (percentToClose / 100.0),
                RoundingMode.Down);
            if (volume > positionVolume)
                volume = positionVolume;
            return volume;
        }

        public static double ResolveProtectionStepPrice(Symbol symbol, double minimumStopPips)
        {
            var pipDistance = symbol != null && symbol.PipSize > 0 ? symbol.PipSize : 0;
            var tickDistance = symbol != null && symbol.TickSize > 0 ? symbol.TickSize : 0;
            var pipBlock = pipDistance > 0
                ? pipDistance * Math.Max(5.0, Math.Min(25.0, Math.Max(1.0, minimumStopPips) * 0.5))
                : 0;
            var tickBlock = tickDistance > 0 ? tickDistance * 5.0 : 0;
            var step = Math.Max(Math.Max(pipDistance, tickDistance), Math.Max(pipBlock, tickBlock));
            return step > 0 ? step : 0.0001;
        }

        public static double BuildSharedProtectionTarget(
            Symbol symbol,
            TradeType tradeType,
            bool isStopLoss,
            bool moveCloser,
            double referencePrice,
            IEnumerable<double> existingLevels,
            double minimumStopPips)
        {
            var step = ResolveProtectionStepPrice(symbol, minimumStopPips);
            var minDistance = symbol != null && symbol.PipSize > 0
                ? symbol.PipSize * Math.Max(1.0, minimumStopPips)
                : step;
            var levels = existingLevels != null
                ? existingLevels.Where(value => value > 0).Distinct()
                : Enumerable.Empty<double>();
            var wantBelow = tradeType == TradeType.Buy ? isStopLoss : !isStopLoss;
            var baseLevel = wantBelow
                ? levels.Where(value => value < referencePrice).OrderByDescending(value => value).FirstOrDefault()
                : levels.Where(value => value > referencePrice).OrderBy(value => value).FirstOrDefault();
            if (!(baseLevel > 0))
                baseLevel = wantBelow ? referencePrice - minDistance : referencePrice + minDistance;

            var direction = wantBelow ? -1.0 : 1.0;
            var nextTarget = baseLevel + (moveCloser ? -direction * step : direction * step);
            var boundaryDistance = moveCloser && symbol != null
                ? symbol.PipSize * 0.5
                : minDistance;
            nextTarget = wantBelow
                ? Math.Min(nextTarget, referencePrice - boundaryDistance)
                : Math.Max(nextTarget, referencePrice + boundaryDistance);
            return CTraderRiskEngine.NormalizePrice(symbol, nextTarget);
        }
    }

    // Central risk and PnL arithmetic. Live gate policy remains in TVBridgeCBot.
    internal static class CTraderRiskEngine
    {
        public static double CalculateStopLossPips(Symbol symbol, double entryPrice, double stopLossPrice)
        {
            if (symbol == null || entryPrice <= 0 || stopLossPrice <= 0 || symbol.PipSize <= 0)
                return 0;
            var pips = Math.Abs(entryPrice - stopLossPrice) / symbol.PipSize;
            return IsFinite(pips) ? Math.Max(0, pips) : 0;
        }

        public static double EstimateRisk(Symbol symbol, double entryPrice, double stopLossPrice, double volumeUnits)
        {
            if (symbol == null || volumeUnits <= 0 || entryPrice <= 0 || stopLossPrice <= 0)
                return 0;
            return EstimateAbsolutePnl(symbol, entryPrice - stopLossPrice, volumeUnits);
        }

        public static double EstimateSignedPnl(Symbol symbol, double priceDistance, double volumeUnits)
        {
            var amount = EstimateAbsolutePnl(symbol, priceDistance, volumeUnits);
            if (!(amount > 0))
                return 0;
            return priceDistance < 0 ? -amount : amount;
        }

        public static double EstimateSignedPnlFromPips(Symbol symbol, double pips, double volumeUnits)
        {
            return symbol == null || symbol.PipSize <= 0
                ? 0
                : EstimateSignedPnl(symbol, pips * symbol.PipSize, volumeUnits);
        }

        public static double NormalizePrice(Symbol symbol, double price)
        {
            return symbol == null || price <= 0
                ? price
                : Math.Round(price, symbol.Digits, MidpointRounding.AwayFromZero);
        }

        public static double EstimateAbsolutePnl(Symbol symbol, double priceDistance, double volumeUnits)
        {
            if (symbol == null || volumeUnits <= 0)
                return 0;

            if (symbol.PipSize > 0)
            {
                try
                {
                    var stopLossPips = Math.Abs(priceDistance) / symbol.PipSize;
                    if (stopLossPips > 0)
                    {
                        var amountRisked = symbol.AmountRisked(volumeUnits, stopLossPips);
                        if (IsFinite(amountRisked) && amountRisked > 0)
                            return Math.Max(0, amountRisked);
                    }
                }
                catch
                {
                }
            }

            return EstimateAbsolutePnlLegacy(symbol, priceDistance, volumeUnits);
        }

        public static double EstimateAbsolutePnlLegacy(Symbol symbol, double priceDistance, double volumeUnits)
        {
            if (symbol == null || volumeUnits <= 0)
                return 0;
            var absDistance = Math.Abs(priceDistance);
            if (!(absDistance > 0))
                return 0;

            double lots;
            try
            {
                lots = symbol.VolumeInUnitsToQuantity(volumeUnits);
            }
            catch
            {
                lots = 0;
            }

            if (lots > 0 && symbol.PipSize > 0)
            {
                var pipDistance = absDistance / symbol.PipSize;
                var pipValue = double.IsNaN(symbol.PipValue) ? 0 : Math.Abs(symbol.PipValue);
                var pipAmount = pipDistance * pipValue * lots;
                if (pipDistance > 0 && pipValue > 0 && IsFinite(pipAmount))
                    return Math.Max(0, pipAmount);
            }

            if (lots > 0 && symbol.TickSize > 0)
            {
                var tickDistanceLots = absDistance / symbol.TickSize;
                var tickValueLots = double.IsNaN(symbol.TickValue) ? 0 : Math.Abs(symbol.TickValue);
                var tickLotsAmount = tickDistanceLots * tickValueLots * lots;
                if (tickDistanceLots > 0 && tickValueLots > 0 && IsFinite(tickLotsAmount))
                    return Math.Max(0, tickLotsAmount);
            }

            if (symbol.TickSize <= 0)
                return 0;
            var tickDistance = absDistance / symbol.TickSize;
            var tickValue = double.IsNaN(symbol.TickValue) ? 0 : Math.Abs(symbol.TickValue);
            if (tickDistance <= 0 || tickValue <= 0)
                return 0;
            var amount = tickDistance * tickValue * volumeUnits;
            return IsFinite(amount) ? Math.Max(0, amount) : 0;
        }

        private static bool IsFinite(double value)
        {
            return !double.IsNaN(value) && !double.IsInfinity(value);
        }
    }

    internal sealed class RiskGateState
    {
        public int OpenPositionsCount;
        public int PendingOrdersCount;
        public double UsedMarginAmount;
        public double UsedMarginPercent;
        public double ExistingOpenRiskAmount;
        public double MaxSingleOpenRiskAmount;
        public double MaxSingleOpenRiskPercent;
        public double CandidateRiskAmount;
        public double TotalOpenRiskAmount;
        public double TotalOpenRiskPercent;
        public double DailyClosedPnl;
        public double DailyFloatingPnl;
        public double DailyTotalPnl;
        public double CurrentWinAmount;
        public double CurrentLoseAmount;
        public double ClosedTodayWinAmount;
        public double ClosedTodayLoseAmount;
        public double DailyNetWinAmount;
        public double DailyNetWinPercent;
        public double DailyNetLossAmount;
        public double DailyNetLossPercent;
        public double PossibleWinAmount;
        public double PossibleLoseAmount;
        public double PossibleSlOutcomeAmount;
        public double DailyClosedNetLossAmount;
        public double DailyLossAmount;
        public double DailyLossPercent;
        public double PeakEquitySeen;
        public double CurrentEquity;
        public double EquityDrawdownAmount;
        public double EquityDrawdownPercent;
        public double AccountBalance;
    }

    // Pure risk-policy decisions. Account/history collection and external gates stay in TVBridgeCBot.
    internal static class CTraderRiskPolicyEngine
    {
        public static bool TryPassPerTradeRisk(
            RiskGateState state,
            double requestedRiskMoney,
            double finalRiskMoney,
            double entryPrice,
            double stopLoss,
            out string rejectReason)
        {
            rejectReason = "";
            if (state == null || finalRiskMoney <= 0)
                return true;
            var tolerance = Math.Max(1.0, finalRiskMoney * 0.02);
            if (state.CandidateRiskAmount <= finalRiskMoney + tolerance)
                return true;
            rejectReason = string.Format(
                CultureInfo.InvariantCulture,
                "rule=MaxRiskPerTrade violated; per_trade_risk {0:F2}>{1:F2}; requested={2:F2}; entry={3:F5}; sl={4:F5}; fix=reduce_volume_or_raise_MaxRiskPreset",
                state.CandidateRiskAmount,
                finalRiskMoney,
                requestedRiskMoney,
                entryPrice,
                stopLoss);
            return false;
        }

        public static bool TryPassSameDirectionRisk(
            RiskGateState state,
            double sameDirectionRiskAmount,
            double maximumPercent,
            string symbolName,
            string action,
            out string rejectReason)
        {
            rejectReason = "";
            if (state == null || maximumPercent <= 0)
                return true;
            var actualPercent = state.AccountBalance > 0
                ? (sameDirectionRiskAmount / state.AccountBalance) * 100.0
                : 0.0;
            if (actualPercent <= maximumPercent)
                return true;
            rejectReason = string.Format(
                CultureInfo.InvariantCulture,
                "rule=MaxRiskPctPerIdea violated; max_risk_pct_per_idea {0:F2}>{1:F2}; symbol={2}; side={3}; fix=reduce_volume_or_close_same_direction_positions",
                actualPercent,
                maximumPercent,
                symbolName,
                action);
            return false;
        }

        public static bool TryPassTotalOpenRisk(RiskGateState state, double maximumPercent, out string rejectReason)
        {
            rejectReason = "";
            if (state == null || maximumPercent <= 0 || state.TotalOpenRiskPercent <= maximumPercent)
                return true;
            rejectReason = string.Format(
                CultureInfo.InvariantCulture,
                "rule=MaxTotalOpenRiskPct violated; total_open_risk_pct {0:F2}>{1:F2}; total_open_risk={2:F2}; balance={3:F2}; fix=close_positions_or_reduce_size",
                state.TotalOpenRiskPercent,
                maximumPercent,
                state.TotalOpenRiskAmount,
                state.AccountBalance);
            return false;
        }

        public static bool TryPassEquityDrawdown(RiskGateState state, double maximumPercent, out string rejectReason)
        {
            rejectReason = "";
            if (state == null || maximumPercent <= 0 || state.EquityDrawdownPercent < maximumPercent)
                return true;
            rejectReason = string.Format(
                CultureInfo.InvariantCulture,
                "rule=MaxEquityDrawdownPct violated; equity_drawdown_pct {0:F2}>={1:F2}; ftmo_ref={2:F2}; equity={3:F2}; fix=stop_trading",
                state.EquityDrawdownPercent,
                maximumPercent,
                state.PeakEquitySeen,
                state.CurrentEquity);
            return false;
        }

        public static bool TryGetDailyPnlLimitBreach(
            RiskGateState state,
            double maximumDailyWinAmount,
            double maximumDailyLossAmount,
            double maximumDailyLossPercent,
            double dayStartBalance,
            out string reason)
        {
            reason = "";
            if (state == null)
                return false;
            if (maximumDailyWinAmount > 0 && state.DailyTotalPnl >= maximumDailyWinAmount)
            {
                reason = string.Format(
                    CultureInfo.InvariantCulture,
                    "rule=MaxDailyWin violated; daily_net_pnl {0:F2}>={1:F2}; daily_net_win_pct={2:F2}; closed_pnl={3:F2}; floating_pnl={4:F2}; fix=stop_trading_until_next_day",
                    state.DailyTotalPnl,
                    maximumDailyWinAmount,
                    state.DailyNetWinPercent,
                    state.DailyClosedPnl,
                    state.DailyFloatingPnl);
                return true;
            }
            if (maximumDailyLossAmount > 0 && state.DailyTotalPnl <= -maximumDailyLossAmount)
            {
                reason = string.Format(
                    CultureInfo.InvariantCulture,
                    "rule=MaxDailyLossNet violated; daily_net_pnl {0:F2}<=-{1:F2}; daily_net_loss_pct={2:F2}; closed_pnl={3:F2}; floating_pnl={4:F2}; fix=stop_trading_until_next_day",
                    state.DailyTotalPnl,
                    maximumDailyLossAmount,
                    state.DailyNetLossPercent,
                    state.DailyClosedPnl,
                    state.DailyFloatingPnl);
                return true;
            }
            if (maximumDailyLossPercent > 0 && state.DailyLossPercent >= maximumDailyLossPercent)
            {
                reason = string.Format(
                    CultureInfo.InvariantCulture,
                    "rule=MaxDailyLossPct violated; daily_loss_pct {0:F2}>={1:F2}; daily_loss={2:F2}; day_start_balance={3:F2}; equity={4:F2}; fix=stop_trading_until_next_day",
                    state.DailyLossPercent,
                    maximumDailyLossPercent,
                    state.DailyLossAmount,
                    dayStartBalance,
                    state.CurrentEquity);
                return true;
            }
            return false;
        }
    }

    // Owns deterministic risk-budget allocation across strategy chains and split entries.
    internal static class CTraderAllocationEngine
    {
        public static double[] BuildChainRiskWeights(int legsPerSignal, int tradeChainSlot, IList<int> enabledSlots)
        {
            var legCount = Math.Max(1, legsPerSignal);
            var slots = enabledSlots == null || enabledSlots.Count == 0
                ? new List<int> { Math.Max(1, tradeChainSlot) }
                : enabledSlots.ToList();
            var slotIndex = slots.IndexOf(Math.Max(1, tradeChainSlot));
            if (slotIndex < 0)
                slotIndex = 0;

            var totalLegCount = Math.Max(1, slots.Count * legCount);
            var totalScore = totalLegCount * (totalLegCount + 1) / 2.0;
            var firstGlobalLeg = slotIndex * legCount;
            return Enumerable.Range(firstGlobalLeg, legCount)
                .Select(index => (index + 1) / totalScore)
                .ToArray();
        }

        public static double[] BuildSplitRiskWeights(int legCount, bool marketFirst)
        {
            if (legCount <= 0)
                return new double[0];

            var scores = new List<double>();
            if (marketFirst)
            {
                for (var i = 0; i < legCount; i++)
                    scores.Add(i + 2.0);
            }
            else
            {
                for (var i = 0; i < legCount; i++)
                {
                    if (i == 0) scores.Add(2.0);
                    else if (i == 1) scores.Add(1.0);
                    else scores.Add(i + 2.0);
                }
            }

            var total = scores.Sum();
            return scores.Select(score => score / total).ToArray();
        }
    }

    // Session math is isolated from strategy selection and timezone lookup.
    internal static class CTraderSessionEngine
    {
        public static DateTime BuildLocalDateTime(DateTime localDate, TimeSpan timeOfDay)
        {
            return new DateTime(
                localDate.Year,
                localDate.Month,
                localDate.Day,
                timeOfDay.Hours,
                timeOfDay.Minutes,
                timeOfDay.Seconds,
                DateTimeKind.Unspecified);
        }

        public static bool IsWithin(TimeSpan timeOfDay, TimeSpan start, TimeSpan end)
        {
            return end > start
                ? timeOfDay >= start && timeOfDay < end
                : timeOfDay >= start || timeOfDay < end;
        }
    }

    // Deterministic indicator math shared by strategy, rule, event, and chart paths.
    internal static class CTraderTechnicalEngine
    {
        public static bool IsFinite(double value)
        {
            return !double.IsNaN(value) && !double.IsInfinity(value);
        }

        public static bool CrossesAbove(double leftPrevious, double leftCurrent, double rightPrevious, double rightCurrent)
        {
            return IsFinite(leftPrevious) && IsFinite(leftCurrent) && IsFinite(rightPrevious) && IsFinite(rightCurrent) &&
                   leftPrevious <= rightPrevious && leftCurrent > rightCurrent;
        }

        public static bool CrossesBelow(double leftPrevious, double leftCurrent, double rightPrevious, double rightCurrent)
        {
            return IsFinite(leftPrevious) && IsFinite(leftCurrent) && IsFinite(rightPrevious) && IsFinite(rightCurrent) &&
                   leftPrevious >= rightPrevious && leftCurrent < rightCurrent;
        }

        public static double ComputeEmaAtIndex(Bars bars, int period, int index)
        {
            if (bars == null || period <= 0 || index < 0 || index >= bars.Count)
                return double.NaN;
            var start = Math.Max(0, index - Math.Max(period * 4, period + 2));
            var ema = bars.ClosePrices[start];
            var multiplier = 2.0 / (period + 1.0);
            for (var i = start + 1; i <= index; i++)
                ema += (bars.ClosePrices[i] - ema) * multiplier;
            return ema;
        }

        public static double ComputeRollingVwap(Bars bars, int length, int index)
        {
            if (bars == null || length <= 0 || index < 0 || index >= bars.Count)
                return double.NaN;
            var start = Math.Max(0, index - length + 1);
            double sumPv = 0;
            double sumV = 0;
            for (var i = start; i <= index; i++)
            {
                var typical = (bars.HighPrices[i] + bars.LowPrices[i] + bars.ClosePrices[i]) / 3.0;
                var volume = 1.0;
                try
                {
                    var tickVolume = Convert.ToDouble(bars.TickVolumes[i], CultureInfo.InvariantCulture);
                    if (IsFinite(tickVolume) && tickVolume > 0)
                        volume = tickVolume;
                }
                catch
                {
                }
                sumPv += typical * volume;
                sumV += volume;
            }
            return sumV > 0 ? sumPv / sumV : double.NaN;
        }

        public static double ComputeMedianRange(Bars bars, int index, int lookback)
        {
            if (bars == null || index < 0 || index >= bars.Count || lookback <= 0)
                return 0;
            var start = Math.Max(0, index - lookback + 1);
            var ranges = new List<double>();
            for (var i = start; i <= index; i++)
            {
                var range = bars.HighPrices[i] - bars.LowPrices[i];
                if (IsFinite(range) && range > 0)
                    ranges.Add(range);
            }
            if (ranges.Count == 0)
                return 0;
            ranges.Sort();
            var mid = ranges.Count / 2;
            return ranges.Count % 2 == 0 ? (ranges[mid - 1] + ranges[mid]) * 0.5 : ranges[mid];
        }

        public static double ComputeSimpleMovingAverage(Bars bars, int endIndex, int period)
        {
            if (bars == null || period <= 0 || endIndex < period - 1)
                return double.NaN;
            double sum = 0;
            var start = endIndex - period + 1;
            for (var i = start; i <= endIndex; i++)
                sum += bars.ClosePrices[i];
            return sum / period;
        }

        public static double ComputeExponentialMovingAverage(Bars bars, int endIndex, int period)
        {
            if (bars == null || period <= 0 || endIndex < period - 1)
                return double.NaN;
            double ema = 0;
            for (var i = 0; i < period; i++)
                ema += bars.ClosePrices[i];
            ema /= period;
            var multiplier = 2.0 / (period + 1.0);
            for (var i = period; i <= endIndex; i++)
                ema = ((bars.ClosePrices[i] - ema) * multiplier) + ema;
            return ema;
        }

        public static double ComputeRateOfChange(Bars bars, int endIndex, int period)
        {
            if (bars == null || period <= 0 || endIndex < period)
                return double.NaN;
            var previousClose = bars.ClosePrices[endIndex - period];
            return !IsFinite(previousClose) || Math.Abs(previousClose) < 0.0000001
                ? double.NaN
                : ((bars.ClosePrices[endIndex] - previousClose) / previousClose) * 100.0;
        }

        public static double ComputeRelativeStrengthIndex(Bars bars, int endIndex, int period)
        {
            if (bars == null || period <= 0 || endIndex <= period)
                return double.NaN;
            double gain = 0;
            double loss = 0;
            for (var i = 1; i <= period; i++)
            {
                var delta = bars.ClosePrices[i] - bars.ClosePrices[i - 1];
                if (delta >= 0) gain += delta;
                else loss -= delta;
            }
            var averageGain = gain / period;
            var averageLoss = loss / period;
            for (var i = period + 1; i <= endIndex; i++)
            {
                var delta = bars.ClosePrices[i] - bars.ClosePrices[i - 1];
                averageGain = ((averageGain * (period - 1)) + (delta > 0 ? delta : 0)) / period;
                averageLoss = ((averageLoss * (period - 1)) + (delta < 0 ? -delta : 0)) / period;
            }
            if (averageLoss <= 0)
                return averageGain <= 0 ? 50.0 : 100.0;
            var rs = averageGain / averageLoss;
            return 100.0 - (100.0 / (1.0 + rs));
        }

        public static double ComputeRollingStandardDeviation(Bars bars, int endIndex, int period, double mean)
        {
            if (bars == null || period <= 0 || endIndex < period - 1 || !IsFinite(mean))
                return double.NaN;
            double varianceSum = 0;
            var start = endIndex - period + 1;
            for (var i = start; i <= endIndex; i++)
            {
                var diff = bars.ClosePrices[i] - mean;
                varianceSum += diff * diff;
            }
            return Math.Sqrt(varianceSum / period);
        }

        public static double ComputeRangeMidpoint(Bars bars, int endIndex, int period)
        {
            if (bars == null || period <= 0 || endIndex < period - 1)
                return double.NaN;
            var start = endIndex - period + 1;
            var highest = double.MinValue;
            var lowest = double.MaxValue;
            for (var i = start; i <= endIndex; i++)
            {
                highest = Math.Max(highest, bars.HighPrices[i]);
                lowest = Math.Min(lowest, bars.LowPrices[i]);
            }
            return IsFinite(highest) && IsFinite(lowest) ? (highest + lowest) / 2.0 : double.NaN;
        }

        public static double ComputeRawStochasticK(Bars bars, int endIndex, int period)
        {
            if (bars == null || period <= 0 || endIndex < period - 1)
                return double.NaN;
            var start = endIndex - period + 1;
            var highest = double.MinValue;
            var lowest = double.MaxValue;
            for (var i = start; i <= endIndex; i++)
            {
                highest = Math.Max(highest, bars.HighPrices[i]);
                lowest = Math.Min(lowest, bars.LowPrices[i]);
            }
            var range = highest - lowest;
            return !IsFinite(range) || range <= 0 ? 50.0 : ((bars.ClosePrices[endIndex] - lowest) / range) * 100.0;
        }

        public static double ComputeSmoothedStochasticK(Bars bars, int endIndex, int period, int smoothPeriod)
        {
            if (bars == null || period <= 0 || smoothPeriod <= 0 || endIndex < period + smoothPeriod - 2)
                return double.NaN;
            double sum = 0;
            for (var i = 0; i < smoothPeriod; i++)
            {
                var raw = ComputeRawStochasticK(bars, endIndex - i, period);
                if (!IsFinite(raw)) return double.NaN;
                sum += raw;
            }
            return sum / smoothPeriod;
        }

        public static double ComputeAverageTrueRange(Bars bars, int endIndex, int period)
        {
            if (bars == null || endIndex < 1 || endIndex >= bars.Count || period <= 0)
                return double.NaN;
            var start = Math.Max(1, endIndex - period + 1);
            double total = 0;
            var count = 0;
            for (var i = start; i <= endIndex; i++)
            {
                var high = bars.HighPrices[i];
                var low = bars.LowPrices[i];
                var previousClose = bars.ClosePrices[i - 1];
                var trueRange = Math.Max(high - low, Math.Max(Math.Abs(high - previousClose), Math.Abs(low - previousClose)));
                if (!IsFinite(trueRange) || trueRange <= 0) continue;
                total += trueRange;
                count++;
            }
            return count > 0 ? total / count : double.NaN;
        }
    }

    internal sealed class CTraderChartSplitterStyle
    {
        public Color Color;
        public int Thickness;
        public string LineStyle;
    }

    // Owns reusable chart policy, layout, object lifecycle, and primitive cTrader rendering.
    internal static class CTraderChartEngine
    {
        public static void TrySetPropertyValue(object target, string propertyName, object value)
        {
            if (target == null || string.IsNullOrWhiteSpace(propertyName) || value == null) return;
            try
            {
                var property = target.GetType().GetProperty(propertyName);
                if (property == null || !property.CanWrite) return;
                var targetType = Nullable.GetUnderlyingType(property.PropertyType) ?? property.PropertyType;
                var converted = targetType == value.GetType()
                    ? value
                    : Convert.ChangeType(value, targetType, CultureInfo.InvariantCulture);
                property.SetValue(target, converted, null);
            }
            catch
            {
            }
        }

        public static void TrySetEnumPropertyValue(object target, string propertyName, string enumName)
        {
            if (target == null || string.IsNullOrWhiteSpace(propertyName) || string.IsNullOrWhiteSpace(enumName)) return;
            try
            {
                var property = target.GetType().GetProperty(propertyName);
                if (property == null || !property.CanWrite) return;
                var targetType = Nullable.GetUnderlyingType(property.PropertyType) ?? property.PropertyType;
                if (!targetType.IsEnum) return;
                property.SetValue(target, Enum.Parse(targetType, enumName, true), null);
            }
            catch
            {
            }
        }

        public static void TryStyleText(object chartText, int fontSize, string fontFamily, bool isBold)
        {
            if (chartText == null) return;
            TrySetPropertyValue(chartText, "FontSize", fontSize);
            TrySetPropertyValue(chartText, "FontFamily", fontFamily);
            TrySetPropertyValue(chartText, "IsBold", isBold);
        }

        public static void TrySetBackground(object chartObject)
        {
            if (chartObject == null) return;
            TrySetPropertyValue(chartObject, "IsBackground", true);
            TrySetPropertyValue(chartObject, "IsInteractive", false);
            TrySetPropertyValue(chartObject, "ZIndex", -10);
        }

        public static bool TryInvokeVoidMethod(object target, string methodName, params object[] args)
        {
            if (target == null || string.IsNullOrWhiteSpace(methodName)) return false;
            try
            {
                foreach (var method in target.GetType().GetMethods().Where(candidate => candidate.Name == methodName))
                {
                    if (method.GetParameters().Length != (args != null ? args.Length : 0)) continue;
                    method.Invoke(target, args);
                    return true;
                }
            }
            catch
            {
            }
            return false;
        }

        public static bool TryClearCollection(object target)
        {
            if (target == null) return false;
            try
            {
                var method = target.GetType().GetMethod("Clear", Type.EmptyTypes);
                if (method == null) return false;
                method.Invoke(target, null);
                return true;
            }
            catch
            {
                return false;
            }
        }

        public static bool TryAddToCollection(object collection, object item)
        {
            if (collection == null || item == null) return false;
            try
            {
                var method = collection.GetType().GetMethod("Add");
                if (method == null) return false;
                method.Invoke(collection, new[] { item });
                return true;
            }
            catch
            {
                return false;
            }
        }

        public static string PadCell(string value, int width, bool alignRight)
        {
            var safe = string.IsNullOrEmpty(value) ? "" : value;
            if (safe.Length > width)
                safe = safe.Substring(0, width);
            return alignRight ? safe.PadLeft(width, ' ') : safe.PadRight(width, ' ');
        }

        public static string BuildTextTableRow(params string[] cells)
        {
            return cells == null || cells.Length == 0 ? "" : " " + string.Join("   ", cells) + " ";
        }

        public static string BuildOffsetText(int blankLines, string content)
        {
            return blankLines <= 0 ? content ?? "" : new string('\n', blankLines) + (content ?? "");
        }

        public static int CountTextLines(string text)
        {
            return string.IsNullOrEmpty(text) ? 0 : text.Split(new[] { '\n' }, StringSplitOptions.None).Length;
        }

        public static string FormatDashboardNumber(double value)
        {
            if (double.IsNaN(value) || double.IsInfinity(value)) return "-";
            var absolute = Math.Abs(value);
            if (absolute >= 1.0)
                return Math.Round(value, 0, MidpointRounding.AwayFromZero).ToString("0", CultureInfo.InvariantCulture);
            if (absolute <= 0.0000001)
                return "0";
            return value.ToString("0.##", CultureInfo.InvariantCulture);
        }

        public static string FormatDashboardPercent(double value)
        {
            return double.IsNaN(value) || double.IsInfinity(value)
                ? "-"
                : value.ToString("0.00", CultureInfo.InvariantCulture);
        }

        public static string FormatCompactDecimal(double value)
        {
            if (double.IsNaN(value) || double.IsInfinity(value)) return "-";
            return Math.Abs(value - Math.Round(value)) < 0.0001
                ? Math.Round(value).ToString("0", CultureInfo.InvariantCulture)
                : value.ToString("0.#", CultureInfo.InvariantCulture);
        }

        public static bool ShouldRefresh(
            int previousBarsCount,
            string previousStateKey,
            int currentBarsCount,
            string currentStateKey,
            DateTime previousRefreshUtc,
            DateTime nowUtc,
            double minimumIntervalSeconds)
        {
            if (previousBarsCount == currentBarsCount &&
                string.Equals(previousStateKey, currentStateKey, StringComparison.Ordinal))
                return false;
            return previousRefreshUtc == DateTime.MinValue ||
                (nowUtc - previousRefreshUtc).TotalSeconds >= Math.Max(0, minimumIntervalSeconds);
        }

        public static int AdvanceRefreshPhase(int currentPhase, int phaseCount)
        {
            return phaseCount <= 0 ? 0 : (Math.Max(0, currentPhase) + 1) % phaseCount;
        }

        public static void CommitBreakdown(List<string> breakdown, int beforeCount, int afterCount, string label)
        {
            var added = afterCount - beforeCount;
            if (breakdown != null && added > 0)
                breakdown.Add((label ?? "") + ":" + added.ToString(CultureInfo.InvariantCulture));
        }

        public static string NormalizeToolbarDirection(string raw, string fallback)
        {
            var value = string.IsNullOrWhiteSpace(raw) ? fallback : raw.Trim();
            if (string.Equals(value, "Buy", StringComparison.OrdinalIgnoreCase)) return "Buy";
            if (string.Equals(value, "Sell", StringComparison.OrdinalIgnoreCase)) return "Sell";
            return "All";
        }

        public static bool DirectionMatchesTradeType(string selectedDirection, TradeType tradeType)
        {
            var normalized = NormalizeToolbarDirection(selectedDirection, "All");
            return normalized == "All" ||
                (normalized == "Buy" && tradeType == TradeType.Buy) ||
                (normalized == "Sell" && tradeType == TradeType.Sell);
        }

        public static string NormalizeToolbarOrderCount(string raw, string fallback)
        {
            var value = string.IsNullOrWhiteSpace(raw) ? fallback : raw.Trim();
            return value == "1" || value == "2" || value == "3" || value == "4" || value == "5"
                ? value
                : "Auto";
        }

        public static int ResolveToolbarOrderCount(string value)
        {
            var normalized = NormalizeToolbarOrderCount(value, "Auto");
            if (normalized == "Auto") return 0;
            int count;
            return int.TryParse(normalized, NumberStyles.Integer, CultureInfo.InvariantCulture, out count)
                ? Math.Max(1, Math.Min(5, count))
                : 0;
        }

        public static string NormalizeToolbarTradeProfile(string raw, string fallback)
        {
            var value = string.IsNullOrWhiteSpace(raw) ? fallback : raw.Trim();
            if (string.Equals(value, "Swing", StringComparison.OrdinalIgnoreCase)) return "Swing";
            if (string.Equals(value, "Daily", StringComparison.OrdinalIgnoreCase)) return "Daily";
            return "Scalp";
        }

        public static Color WithAlpha(Color color, int alpha)
        {
            return Color.FromArgb(alpha, color.R, color.G, color.B);
        }

        public static int GetMarkerFontLevel(TVBridgeCBot.ChartMarkerFontSizeMode mode)
        {
            switch (mode)
            {
                case TVBridgeCBot.ChartMarkerFontSizeMode.None: return -1;
                case TVBridgeCBot.ChartMarkerFontSizeMode.Tiny: return 0;
                case TVBridgeCBot.ChartMarkerFontSizeMode.Medium: return 2;
                case TVBridgeCBot.ChartMarkerFontSizeMode.Large: return 3;
                default: return 1;
            }
        }

        public static int GetMarkerFontSize(TVBridgeCBot.ChartMarkerFontSizeMode mode)
        {
            switch (mode)
            {
                case TVBridgeCBot.ChartMarkerFontSizeMode.None: return 0;
                case TVBridgeCBot.ChartMarkerFontSizeMode.Tiny: return 6;
                case TVBridgeCBot.ChartMarkerFontSizeMode.Medium: return 10;
                case TVBridgeCBot.ChartMarkerFontSizeMode.Large: return 12;
                default: return 8;
            }
        }

        public static int ResolveMarkerFontSize(
            TVBridgeCBot.ChartMarkerFontSizeMode mode,
            TimeFrame chartTimeFrame,
            TimeFrame sourceTimeFrame,
            bool visualsEnabled)
        {
            if (!visualsEnabled || mode == TVBridgeCBot.ChartMarkerFontSizeMode.None)
                return 0;
            var level = GetMarkerFontLevel(mode);
            var chartMinutes = Math.Max(1, CTraderTimeFrameEngine.ToMinutes(chartTimeFrame));
            var sourceMinutes = Math.Max(1, CTraderTimeFrameEngine.ToMinutes(sourceTimeFrame));
            if (sourceMinutes > chartMinutes)
            {
                if (sourceMinutes >= 1440) level += 3;
                else if (sourceMinutes >= 240) level += 2;
                else if (sourceMinutes >= 60) level += 1;
                else if (sourceMinutes >= 15) level += 1;
            }
            switch (Math.Max(0, Math.Min(3, level)))
            {
                case 0: return 6;
                case 1: return 8;
                case 2: return 10;
                default: return 12;
            }
        }

        public static string GetDirectionalMarkerIcon(TVBridgeCBot.ChartMarkerSymbolMode mode, bool isBullish)
        {
            return mode == TVBridgeCBot.ChartMarkerSymbolMode.Triangles
                ? (isBullish ? "▲" : "▼")
                : (isBullish ? "↑" : "↓");
        }

        public static string FormatDirectionalMarkerText(
            string label,
            bool isBullish,
            TVBridgeCBot.ChartMarkerSymbolMode symbolMode,
            TVBridgeCBot.ChartLabelVisibilityMode labelVisibility)
        {
            var icon = GetDirectionalMarkerIcon(symbolMode, isBullish);
            if (labelVisibility == TVBridgeCBot.ChartLabelVisibilityMode.No)
                return icon;
            return icon + " " + (string.IsNullOrWhiteSpace(label) ? "evt" : label.Trim().ToUpperInvariant());
        }

        public static ChartIconType GetDirectionalChartIconType(bool isBullish)
        {
            return isBullish ? ChartIconType.UpArrow : ChartIconType.DownArrow;
        }

        public static double ResolveDirectionalLabelPrice(
            bool isBullish,
            double wickPrice,
            double barRange,
            int slotIndex,
            double fallbackRange,
            double pipSize)
        {
            var effectiveRange = Math.Max(Math.Max(barRange, fallbackRange), pipSize > 0 ? pipSize * 8.0 : 0.0000001);
            var textPad = Math.Max(pipSize > 0 ? pipSize * (0.8 + slotIndex * 0.4) : 0.0000001,
                effectiveRange * (0.012 + slotIndex * 0.007));
            return isBullish ? wickPrice - textPad : wickPrice + textPad;
        }

        public static List<TimeFrame> GetAutoSplitterTimeFrames(TimeFrame chartTimeFrame)
        {
            var minutes = Math.Max(1, CTraderTimeFrameEngine.ToMinutes(chartTimeFrame));
            if (minutes <= 1) return new List<TimeFrame> { TimeFrame.Minute15, TimeFrame.Hour, TimeFrame.Hour4 };
            if (minutes <= 5) return new List<TimeFrame> { TimeFrame.Hour, TimeFrame.Hour4 };
            if (minutes <= 60) return new List<TimeFrame> { TimeFrame.Hour4 };
            return new List<TimeFrame>();
        }

        public static CTraderChartSplitterStyle ResolveAutoSplitterStyle(TimeFrame splitTimeFrame, Color baseColor)
        {
            var minutes = Math.Max(1, CTraderTimeFrameEngine.ToMinutes(splitTimeFrame));
            var alpha = minutes >= 1440 ? 92 : minutes >= 240 ? 64 : minutes >= 60 ? 68 : 54;
            return new CTraderChartSplitterStyle
            {
                Color = WithAlpha(baseColor, alpha),
                Thickness = 1,
                LineStyle = minutes >= 1440 ? "Lines" : "Dots"
            };
        }

        public static TimeFrame ResolveSplitterBaseTimeFrame(int stepMinutes, out int baseMinutes, out int nth)
        {
            var candidates = new[]
            {
                Tuple.Create(TimeFrame.Weekly, 10080), Tuple.Create(TimeFrame.Daily, 1440),
                Tuple.Create(TimeFrame.Hour4, 240), Tuple.Create(TimeFrame.Hour, 60),
                Tuple.Create(TimeFrame.Minute30, 30), Tuple.Create(TimeFrame.Minute15, 15),
                Tuple.Create(TimeFrame.Minute5, 5), Tuple.Create(TimeFrame.Minute, 1)
            };
            foreach (var candidate in candidates)
            {
                if (stepMinutes % candidate.Item2 != 0) continue;
                baseMinutes = candidate.Item2;
                nth = stepMinutes / candidate.Item2;
                return candidate.Item1;
            }
            baseMinutes = stepMinutes;
            nth = 1;
            return null;
        }

        public static List<TimeFrame> GetAutoHigherTimeFrames(TimeFrame chartTimeFrame)
        {
            var minutes = Math.Max(1, CTraderTimeFrameEngine.ToMinutes(chartTimeFrame));
            if (minutes <= 1) return new List<TimeFrame> { TimeFrame.Minute15, TimeFrame.Hour };
            if (minutes <= 5) return new List<TimeFrame> { TimeFrame.Hour, TimeFrame.Hour4 };
            if (minutes <= 15) return new List<TimeFrame> { TimeFrame.Hour4, TimeFrame.Daily };
            if (minutes <= 60) return new List<TimeFrame> { TimeFrame.Daily, TimeFrame.Weekly };
            return new List<TimeFrame> { TimeFrame.Weekly };
        }

        public static TimeFrame ResolveHtfSlotTimeFrame(
            TimeFrame chartTimeFrame,
            int slotIndex,
            TVBridgeCBot.HtfSlotMode selection)
        {
            switch (selection)
            {
                case TVBridgeCBot.HtfSlotMode.Off: return null;
                case TVBridgeCBot.HtfSlotMode.Auto:
                    var frames = GetAutoHigherTimeFrames(chartTimeFrame);
                    return slotIndex >= 0 && slotIndex < frames.Count ? frames[slotIndex] : null;
                case TVBridgeCBot.HtfSlotMode.m15: return TimeFrame.Minute15;
                case TVBridgeCBot.HtfSlotMode.h1: return TimeFrame.Hour;
                case TVBridgeCBot.HtfSlotMode.h4: return TimeFrame.Hour4;
                case TVBridgeCBot.HtfSlotMode.d1: return TimeFrame.Daily;
                case TVBridgeCBot.HtfSlotMode.w1: return TimeFrame.Weekly;
                default: return null;
            }
        }

        public static List<TimeFrame> GetEnabledHigherTimeFrames(
            TimeFrame chartTimeFrame,
            TVBridgeCBot.HtfSlotMode first,
            TVBridgeCBot.HtfSlotMode second)
        {
            var result = new List<TimeFrame>();
            var selections = new[] { first, second };
            for (var index = 0; index < selections.Length; index++)
            {
                var frame = ResolveHtfSlotTimeFrame(chartTimeFrame, index, selections[index]);
                if (frame != null && !result.Contains(frame)) result.Add(frame);
            }
            return result;
        }

        public static int GetMiniChartBars(TimeFrame timeFrame)
        {
            var minutes = Math.Max(1, CTraderTimeFrameEngine.ToMinutes(timeFrame));
            if (minutes >= 10080) return 4;
            if (minutes >= 1440) return 7;
            if (minutes >= 240) return 12;
            return 24;
        }

        public static double GetMiniChartSlotWidth(int miniBarCount, double candleWidthBars)
        {
            return Math.Max(4.0, Math.Max(2, miniBarCount) * candleWidthBars);
        }

        public static string NormalizeDisplayTimeFramePrefix(string value)
        {
            var text = string.IsNullOrWhiteSpace(value) ? "" : value.Trim();
            var replacements = new[]
            {
                new[] { "1m.", "m1." }, new[] { "5m.", "m5." }, new[] { "15m.", "m15." },
                new[] { "30m.", "m30." }, new[] { "1h.", "h1." }, new[] { "4h.", "h4." },
                new[] { "1d.", "d1." }, new[] { "1w.", "w1." }, new[] { "1mn.", "mn1." },
                new[] { "1mo.", "mn1." }
            };
            foreach (var replacement in replacements)
                if (text.StartsWith(replacement[0], StringComparison.OrdinalIgnoreCase))
                    return replacement[1] + text.Substring(replacement[0].Length);
            return text;
        }

        public static string NormalizeArtifactDisplayLabel(string labelText, string timeFrameLabel)
        {
            var normalized = NormalizeDisplayTimeFramePrefix(labelText);
            var reactionPrefixes = new[]
            {
                new[] { "r.1m.", "m1.r." }, new[] { "r.5m.", "m5.r." }, new[] { "r.15m.", "m15.r." },
                new[] { "r.30m.", "m30.r." }, new[] { "r.1h.", "h1.r." }, new[] { "r.4h.", "h4.r." },
                new[] { "r.1d.", "d1.r." }, new[] { "r.1w.", "w1.r." }, new[] { "r.1mn.", "mn1.r." },
                new[] { "r.1mo.", "mn1.r." }, new[] { "r.m1.", "m1.r." }, new[] { "r.m5.", "m5.r." },
                new[] { "r.m15.", "m15.r." }, new[] { "r.m30.", "m30.r." }, new[] { "r.h1.", "h1.r." },
                new[] { "r.h4.", "h4.r." }, new[] { "r.d1.", "d1.r." }, new[] { "r.w1.", "w1.r." },
                new[] { "r.mn1.", "mn1.r." }
            };
            foreach (var replacement in reactionPrefixes)
            {
                if (!normalized.StartsWith(replacement[0], StringComparison.OrdinalIgnoreCase)) continue;
                normalized = replacement[1] + normalized.Substring(replacement[0].Length);
                break;
            }
            var tf = string.IsNullOrWhiteSpace(timeFrameLabel) ? "" : timeFrameLabel.Trim().ToLowerInvariant();
            var replacements = new[]
            {
                new[] { "Key High", string.IsNullOrEmpty(tf) ? "p.h" : tf + ".p.h" },
                new[] { "Key Low", string.IsNullOrEmpty(tf) ? "p.l" : tf + ".p.l" },
                new[] { "Bar High", string.IsNullOrEmpty(tf) ? "p.h" : tf + ".p.h" },
                new[] { "Bar Low", string.IsNullOrEmpty(tf) ? "p.l" : tf + ".p.l" },
                new[] { "Range High", string.IsNullOrEmpty(tf) ? "rng.h" : tf + ".rng.h" },
                new[] { "Range Low", string.IsNullOrEmpty(tf) ? "rng.l" : tf + ".rng.l" },
                new[] { "Swing High", string.IsNullOrEmpty(tf) ? "sw.h" : tf + ".sw.h" },
                new[] { "Swing Low", string.IsNullOrEmpty(tf) ? "sw.l" : tf + ".sw.l" },
                new[] { "Resistance", string.IsNullOrEmpty(tf) ? "rng.h" : tf + ".rng.h" },
                new[] { "Resitence", string.IsNullOrEmpty(tf) ? "rng.h" : tf + ".rng.h" },
                new[] { "Support", string.IsNullOrEmpty(tf) ? "rng.l" : tf + ".rng.l" },
                new[] { "Supply", "Sup" }, new[] { "Demand", "Dem" }, new[] { "SPLY", "Sup" },
                new[] { "DEM", "Dem" }, new[] { "RES", string.IsNullOrEmpty(tf) ? "rng.h" : tf + ".rng.h" },
                new[] { "SUP", string.IsNullOrEmpty(tf) ? "rng.l" : tf + ".rng.l" }
            };
            foreach (var replacement in replacements)
            {
                if (string.Equals(normalized, replacement[0], StringComparison.OrdinalIgnoreCase)) return replacement[1];
                if (normalized.StartsWith(replacement[0] + " ", StringComparison.OrdinalIgnoreCase))
                    return replacement[1] + normalized.Substring(replacement[0].Length);
            }
            return normalized;
        }

        public static string NormalizeEventLabelPriorityKey(string label)
        {
            var key = string.IsNullOrWhiteSpace(label) ? "" : label.Trim().ToUpperInvariant();
            if (key.EndsWith("_CONFIRMED", StringComparison.OrdinalIgnoreCase)) key = key.Substring(0, key.Length - 10);
            if (key.EndsWith("_REJECTED", StringComparison.OrdinalIgnoreCase)) key = key.Substring(0, key.Length - 9);
            if (key.EndsWith(".C", StringComparison.OrdinalIgnoreCase) || key.EndsWith("_C", StringComparison.OrdinalIgnoreCase) ||
                key.EndsWith(".R", StringComparison.OrdinalIgnoreCase) || key.EndsWith("_R", StringComparison.OrdinalIgnoreCase))
                key = key.Substring(0, key.Length - 2);
            var space = key.IndexOf(' ');
            return space >= 0 ? key.Substring(0, space) : key;
        }

        public static int GetEventLabelPriorityScore(string label)
        {
            switch (NormalizeEventLabelPriorityKey(label))
            {
                case "CHOCH": return 100; case "BOS": return 95; case "SR": case "SWP": case "SWEEP": return 90;
                case "BR": return 86; case "RJ": return 84; case "IM": return 80; case "PB": return 72; case "CT": return 68;
                case "MOR": case "EVE": return 92; case "3WS": case "3BC": return 88; case "ENG": return 84;
                case "DCC": case "PRC": return 80; case "PIN": case "HAM": case "SST": return 76;
                case "IHM": case "HGM": return 74; case "BIG": return 70; case "HAR": return 62;
                case "MD0": return 78; case "MDX": return 74; case "EMX": return 72; case "STX": case "STO": return 70;
                case "PXE": case "VWX": case "BBX": case "R50": return 68; case "ROS": case "ROB": return 66;
                case "VWR": case "BBR": return 64; case "EMT": return 62; default: return 0;
            }
        }

        public static string RemoveObjectsByPrefixes(Chart chart, params string[] prefixes)
        {
            if (chart == null || prefixes == null || prefixes.Length == 0) return "";
            try
            {
                var names = chart.Objects
                    .Where(item => item != null && !string.IsNullOrWhiteSpace(item.Name) &&
                        prefixes.Any(prefix => item.Name.StartsWith(prefix, StringComparison.Ordinal)))
                    .Select(item => item.Name)
                    .ToList();
                foreach (var name in names)
                {
                    try { chart.RemoveObject(name); } catch { }
                }
                return "";
            }
            catch (Exception ex)
            {
                return ex.Message;
            }
        }

        public static bool ObjectsOverBudget(Chart chart, int maximumObjects)
        {
            try { return chart != null && chart.Objects.Count >= maximumObjects; }
            catch { return false; }
        }

        public static int DrawBlurredCandle(
            Chart chart, string objectPrefix, int objectIndex, DateTime startTime, DateTime endTime,
            double high, double low, double open, double close, Color wickFillColor,
            Color wickBorderColor, Color bodyFillColor, Color bodyBorderColor)
        {
            if (chart == null || endTime <= startTime) return objectIndex;
            var mini = string.Equals(objectPrefix, "MINI", StringComparison.OrdinalIgnoreCase);
            var bodyHigh = Math.Max(open, close);
            var bodyLow = Math.Min(open, close);
            var duration = Math.Max(1.0, (endTime - startTime).TotalMinutes);
            var wickStart = startTime.AddMinutes(duration * (mini ? 0.44 : 0.47));
            var wickEnd = startTime.AddMinutes(duration * (mini ? 0.56 : 0.53));
            if (wickEnd <= wickStart) wickEnd = wickStart.AddMinutes(1);
            if (high > bodyHigh)
                DrawCandleRectangle(chart, objectPrefix + "_WICK_U_" + objectIndex.ToString(CultureInfo.InvariantCulture), wickStart, high, wickEnd, bodyHigh, wickFillColor, wickBorderColor, mini ? 1 : 0);
            if (bodyLow > low)
                DrawCandleRectangle(chart, objectPrefix + "_WICK_L_" + objectIndex.ToString(CultureInfo.InvariantCulture), wickStart, bodyLow, wickEnd, low, wickFillColor, wickBorderColor, mini ? 1 : 0);
            DrawCandleRectangle(chart, objectPrefix + "_BODY_" + objectIndex.ToString(CultureInfo.InvariantCulture), startTime, bodyHigh, endTime, bodyLow, bodyFillColor, bodyBorderColor, 1);
            return objectIndex + 1;
        }

        private static void DrawCandleRectangle(Chart chart, string name, DateTime startTime, double high, DateTime endTime, double low, Color fill, Color border, int thickness)
        {
            var rectangle = chart.DrawRectangle(name, startTime, high, endTime, low, fill);
            TrySetPropertyValue(rectangle, "IsFilled", true);
            TrySetPropertyValue(rectangle, "Color", fill);
            TrySetPropertyValue(rectangle, "BorderColor", border);
            TrySetPropertyValue(rectangle, "Thickness", thickness);
            TrySetBackground(rectangle);
        }

        public static int DrawIndicatorSegment(
            Chart chart, Bars bars, int objectIndex, string prefix, int index, double previousValue,
            double currentValue, Color color, int thickness, string lineStyle)
        {
            if (chart == null || bars == null || index <= 0 || index >= bars.Count ||
                double.IsNaN(previousValue) || double.IsInfinity(previousValue) ||
                double.IsNaN(currentValue) || double.IsInfinity(currentValue))
                return objectIndex;
            var line = chart.DrawTrendLine(prefix + objectIndex.ToString(CultureInfo.InvariantCulture),
                bars.OpenTimes[index - 1], previousValue, bars.OpenTimes[index], currentValue, color);
            TrySetPropertyValue(line, "Thickness", 1);
            TrySetEnumPropertyValue(line, "LineStyle", lineStyle);
            TrySetPropertyValue(line, "ZIndex", 2);
            return objectIndex + 1;
        }

        public static ChartStaticText DrawStaticTextIfChanged(
            Chart chart, string objectName, string text, VerticalAlignment verticalAlignment,
            HorizontalAlignment horizontalAlignment, Color color, ref string lastText, ref string lastColorKey)
        {
            var normalized = text ?? "";
            var colorKey = color.ToString();
            if (string.Equals(lastText, normalized, StringComparison.Ordinal) &&
                string.Equals(lastColorKey, colorKey, StringComparison.Ordinal)) return null;
            lastText = normalized;
            lastColorKey = colorKey;
            return chart != null ? chart.DrawStaticText(objectName, normalized, verticalAlignment, horizontalAlignment, color) : null;
        }
    }

    // Server-reported bar coverage used by incremental synchronization planning.
    internal sealed class CTraderSyncCoverage
    {
        public int ExistingBars;
        public int TargetBars = 500;
        public long RemoteEnd;
    }

    internal sealed class CTraderIncrementalFetchPlan
    {
        public bool ShouldFetch;
        public long FetchStart;
        public int NeededBars;
    }

    // Owns deterministic sync cadence, payload, acknowledgement, and incremental-bar policy.
    internal static class CTraderSyncEngine
    {
        public const int AckMaxAttempts = 3;

        public static bool IsDue(DateTime now, DateTime lastAttempt, double intervalSeconds)
        {
            return lastAttempt == DateTime.MinValue ||
                (now - lastAttempt).TotalSeconds >= Math.Max(0, intervalSeconds);
        }

        public static bool IsErrorAckStatus(string status)
        {
            var normalized = string.IsNullOrWhiteSpace(status) ? "" : status.Trim().ToUpperInvariant();
            return normalized == "FAIL" || normalized == "ERROR" || normalized == "REJECTED";
        }

        public static int ResolveAckRetryDelayMilliseconds(int failedAttempt)
        {
            return 400 * Math.Max(1, failedAttempt);
        }

        public static string DeriveSyncEventCode(
            string executionStatus,
            bool statusChanged,
            bool stopLossChanged,
            bool takeProfitChanged,
            bool partialChanged)
        {
            var execution = (executionStatus ?? "").Trim().ToUpperInvariant();
            if (execution == "CLOSED") return "SNAPSHOT_CLOSED";
            if (execution == "CANCELLED") return "SNAPSHOT_CANCELLED";
            if (statusChanged && execution == "FILLED") return "STATUS_FILLED";
            if (statusChanged && execution == "PENDING") return "STATUS_PENDING";
            if (stopLossChanged || takeProfitChanged) return "PROTECTION_UPDATED";
            if (partialChanged) return "PARTIALS_UPDATED";
            if (statusChanged && !string.IsNullOrEmpty(execution)) return "STATUS_UPDATED";
            return "SYNC_UPDATED";
        }

        public static string ResolveSyncEventBucket(string executionStatus)
        {
            var execution = (executionStatus ?? "").Trim().ToUpperInvariant();
            return execution == "CLOSED" || execution == "CANCELLED" ? "closed" : "changed";
        }

        public static string BuildSyncPayload(
            string bridgeIdentityJson,
            double balance,
            double equity,
            double margin,
            string brokerName,
            string providerCode,
            string buildVersion,
            IEnumerable<string> positions,
            IEnumerable<string> orders,
            IEnumerable<string> closed,
            string queueActionsJson,
            bool queueSnapshotComplete,
            IEnumerable<string> symbolMetrics,
            IEnumerable<Tuple<string, double, double>> prices)
        {
            var priceRows = (prices ?? Enumerable.Empty<Tuple<string, double, double>>())
                .Where(price => price != null)
                .Select(price => "{\"s\":\"" + EscapeFragment(price.Item1) + "\",\"b\":" +
                    price.Item2.ToString("F5", CultureInfo.InvariantCulture) + ",\"a\":" +
                    price.Item3.ToString("F5", CultureInfo.InvariantCulture) + "}");
            return "{" + (bridgeIdentityJson ?? "")
                + ",\"balance\":" + balance.ToString("F2", CultureInfo.InvariantCulture)
                + ",\"equity\":" + equity.ToString("F2", CultureInfo.InvariantCulture)
                + ",\"margin\":" + margin.ToString("F2", CultureInfo.InvariantCulture)
                + ",\"broker_name\":\"" + (brokerName ?? "").Replace("\"", "'") + "\""
                + ",\"provider_code\":\"" + (providerCode ?? "").Replace("\"", "'") + "\""
                + ",\"build_version\":\"" + (buildVersion ?? "") + "\""
                + ",\"positions\":[" + string.Join(",", positions ?? Enumerable.Empty<string>()) + "]"
                + ",\"orders\":[" + string.Join(",", orders ?? Enumerable.Empty<string>()) + "]"
                + ",\"closed\":[" + string.Join(",", closed ?? Enumerable.Empty<string>()) + "]"
                + ",\"queue_actions\":" + (string.IsNullOrWhiteSpace(queueActionsJson) ? "[]" : queueActionsJson)
                + ",\"queue_snapshot_complete\":" + (queueSnapshotComplete ? "true" : "false")
                + ",\"queue_snapshot_hydrated\":" + (queueSnapshotComplete ? "true" : "false")
                + ",\"symbol_metrics\":[" + string.Join(",", symbolMetrics ?? Enumerable.Empty<string>()) + "]"
                + ",\"prices\":[" + string.Join(",", priceRows) + "]}";
        }

        public static string BuildAckPayload(
            string bridgeIdentityJson,
