    public sealed class MarketAnalysisService
    {
        public MarketAnalysisResult Analyze(MarketAnalysisRequest request)
        {
            if (request == null)
                throw new ArgumentNullException("request");

            var config = request.Config ?? new MarketAnalysisConfig();
            var result = new MarketAnalysisResult { Symbol = request.Symbol != null ? request.Symbol.Name ?? "" : "" };
            foreach (var frame in request.TimeFrames ?? new List<MarketTimeFrameInput>())
            {
                if (frame == null || frame.Candles == null || frame.Candles.Count == 0)
                    continue;
                result.TimeFrames.Add(AnalyzeTimeFrame(request.Symbol, frame, config, request.Confluence, request.Strategy));
            }
            return result;
        }

        private TimeFrameAnalysisResult AnalyzeTimeFrame(
            MarketSymbolInput symbol,
            MarketTimeFrameInput frame,
            MarketAnalysisConfig config,
            AnalysisConfluenceConfig confluence,
            AnalysisStrategyConfig strategy)
        {
            var candles = frame.Candles;
            var lastClosed = frame.LastClosedIndex >= 0
                ? Math.Min(frame.LastClosedIndex, candles.Count - 1)
                : candles.Count - 1;
            var output = new TimeFrameAnalysisResult { TimeFrame = frame.Name ?? "", LastClosedIndex = lastClosed };
            if (lastClosed < 0)
                return output;

            var scope = config.Scope ?? new AnalysisScopeConfig();
            if (scope.Swings || scope.Structures || scope.Zones || scope.Confluences || scope.Trades)
                output.Swings = DetectSwings(candles, lastClosed, config.Swings);
            if (scope.Structures || scope.Zones || scope.Confluences || scope.Trades)
                output.Structures = DetectStructures(candles, output.Swings, lastClosed, config.Structures, config.Swings);
            if (scope.Zones || scope.Confluences || scope.Trades)
                output.Zones = DetectZones(candles, output.Structures, output.Swings, lastClosed, config.Zones, symbol);
            if (scope.KeyLevels || scope.Confluences || scope.Trades)
                output.KeyLevels = DetectKeyLevels(candles, lastClosed, frame.Name, config.KeyLevels);
            if (scope.CandlePatterns || scope.Confluences || scope.Trades)
                output.CandlePatterns = DetectCandlePatterns(candles, lastClosed, config.CandlePatterns, confluence);
            if (scope.Confluences || scope.Trades)
                output.Confluences = CalculateConfluences(symbol, frame.Name, output, config.Confluence);
            if (scope.Trades)
                output.Trades = CalculateTrades(symbol, frame.Name, candles, output, config.Trades, strategy);
            return output;
        }

        public List<SwingInfo> DetectSwings(List<MarketCandle> candles, int lastClosedIndex, SwingAnalysisConfig config)
        {
            var values = new List<SwingInfo>();
            if (candles == null || config == null || lastClosedIndex < 2)
                return values;

            var strength = Math.Max(1, config.Strength);
            var start = Math.Max(strength, lastClosedIndex - Math.Max(config.LookbackBars, strength * 2 + 2) + 1);
            var finalPivot = lastClosedIndex - strength;
            for (var i = start; i <= finalPivot; i++)
            {
                var high = candles[i].High;
                var low = candles[i].Low;
                var isHigh = true;
                var isLow = true;
                var highStrict = false;
                var lowStrict = false;
                for (var offset = 1; offset <= strength; offset++)
                {
                    var left = candles[i - offset];
                    var right = candles[i + offset];
                    if (left.High > high || right.High > high) isHigh = false;
                    if (left.Low < low || right.Low < low) isLow = false;
                    if (left.High < high || right.High < high) highStrict = true;
                    if (left.Low > low || right.Low > low) lowStrict = true;
                }
                if (isHigh && highStrict)
                    values.Add(new SwingInfo { Index = i, TimeUtc = candles[i].OpenTimeUtc, Price = high, IsHigh = true, ConfirmationIndex = i + strength });
                if (isLow && lowStrict)
                    values.Add(new SwingInfo { Index = i, TimeUtc = candles[i].OpenTimeUtc, Price = low, IsHigh = false, ConfirmationIndex = i + strength });
            }
            return values.OrderBy(value => value.Index).ThenByDescending(value => value.IsHigh).ToList();
        }

        public List<StructureEventInfo> DetectStructures(
            List<MarketCandle> candles,
            List<SwingInfo> swings,
            int lastClosedIndex,
            StructureAnalysisConfig config,
            SwingAnalysisConfig swingConfig)
        {
            var values = new List<StructureEventInfo>();
            if (candles == null || swings == null || config == null || lastClosedIndex < 2)
                return values;

            var start = Math.Max(2, lastClosedIndex - Math.Max(config.LookbackBars, 12) + 1);
            SwingInfo previousHigh = null;
            SwingInfo latestHigh = null;
            SwingInfo previousLow = null;
            SwingInfo latestLow = null;
            var bias = config.ExternalBias;
            var brokenHighs = new HashSet<int>();
            var brokenLows = new HashSet<int>();
            var sweptHighs = new HashSet<int>();
            var sweptLows = new HashSet<int>();

            for (var barIndex = start; barIndex <= lastClosedIndex; barIndex++)
            {
                var updated = false;
                foreach (var swing in swings.Where(value => value.ConfirmationIndex == barIndex))
                {
                    updated = true;
                    if (swing.IsHigh) { previousHigh = latestHigh; latestHigh = swing; }
                    else { previousLow = latestLow; latestLow = swing; }
                }

                if (config.ExternalBias == MarketDirection.Neutral && updated && previousHigh != null && latestHigh != null && previousLow != null && latestLow != null)
                {
                    if (latestHigh.Price > previousHigh.Price && latestLow.Price > previousLow.Price) bias = MarketDirection.Bullish;
                    else if (latestHigh.Price < previousHigh.Price && latestLow.Price < previousLow.Price) bias = MarketDirection.Bearish;
                }

                var candle = candles[barIndex];
                if (latestHigh != null && candle.Close > latestHigh.Price && (!config.ConsumeBrokenLevels || brokenHighs.Add(latestHigh.Index)))
                {
                    var before = bias;
                    var type = before == MarketDirection.Bearish ? MarketStructureEventType.Choch : MarketStructureEventType.Bos;
                    values.Add(NewStructure(type, barIndex, latestHigh, MarketDirection.Bullish, before, MarketDirection.Bullish));
                    bias = MarketDirection.Bullish;
                }
                if (latestLow != null && candle.Close < latestLow.Price && (!config.ConsumeBrokenLevels || brokenLows.Add(latestLow.Index)))
                {
                    var before = bias;
                    var type = before == MarketDirection.Bullish ? MarketStructureEventType.Choch : MarketStructureEventType.Bos;
                    values.Add(NewStructure(type, barIndex, latestLow, MarketDirection.Bearish, before, MarketDirection.Bearish));
                    bias = MarketDirection.Bearish;
                }

                if (latestHigh != null && latestHigh.ConfirmationIndex < barIndex && (!config.ConsumeSweptLevels || !sweptHighs.Contains(latestHigh.Index)))
                {
                    var oneBar = candle.High > latestHigh.Price && candle.Open <= latestHigh.Price && candle.Close < latestHigh.Price;
                    var twoBar = config.DetectTwoBarSweeps && barIndex > 0 && candles[barIndex - 1].High > latestHigh.Price && candles[barIndex - 1].Close >= latestHigh.Price && candle.Close < latestHigh.Price;
                    if (oneBar || twoBar)
                    {
                        if (config.ConsumeSweptLevels) sweptHighs.Add(latestHigh.Index);
                        values.Add(NewStructure(MarketStructureEventType.Sweep, oneBar ? barIndex : barIndex - 1, latestHigh, MarketDirection.Bearish, bias, bias, barIndex));
                    }
                }
                if (latestLow != null && latestLow.ConfirmationIndex < barIndex && (!config.ConsumeSweptLevels || !sweptLows.Contains(latestLow.Index)))
                {
                    var oneBar = candle.Low < latestLow.Price && candle.Open >= latestLow.Price && candle.Close > latestLow.Price;
                    var twoBar = config.DetectTwoBarSweeps && barIndex > 0 && candles[barIndex - 1].Low < latestLow.Price && candles[barIndex - 1].Close <= latestLow.Price && candle.Close > latestLow.Price;
                    if (oneBar || twoBar)
                    {
                        if (config.ConsumeSweptLevels) sweptLows.Add(latestLow.Index);
                        values.Add(NewStructure(MarketStructureEventType.Sweep, oneBar ? barIndex : barIndex - 1, latestLow, MarketDirection.Bullish, bias, bias, barIndex));
                    }
                }
            }
            return values.OrderBy(value => value.ConfirmationIndex).ThenBy(value => value.Type).ToList();
        }

        private StructureEventInfo NewStructure(MarketStructureEventType type, int trigger, SwingInfo swing, MarketDirection direction, MarketDirection before, MarketDirection after, int confirmation = -1)
        {
            return new StructureEventInfo
            {
                Type = type,
                TriggerIndex = trigger,
                ConfirmationIndex = confirmation >= 0 ? confirmation : trigger,
                ReferenceSwingIndex = swing.Index,
                ReferencePrice = swing.Price,
                Direction = direction,
                BiasBefore = before,
                BiasAfter = after
            };
        }

        public List<ZoneInfo> DetectZones(List<MarketCandle> candles, List<StructureEventInfo> structures, List<SwingInfo> swings, int lastClosedIndex, ZoneAnalysisConfig config, MarketSymbolInput symbol)
        {
            var values = new List<ZoneInfo>();
            if (candles == null || config == null || lastClosedIndex < 3)
                return values;
            var start = Math.Max(2, lastClosedIndex - Math.Max(config.LookbackBars, 20) + 1);
            for (var i = start; i <= lastClosedIndex; i++)
            {
                var bullish = candles[i].Low > candles[i - 2].High;
                var bearish = candles[i].High < candles[i - 2].Low;
                if ((!bullish && !bearish) || !IsQualifiedFvg(candles, i, bullish, config) || !HasVolumeSurge(candles, i - 1, config.VolumeSurgeMultiplier))
                    continue;
                var zone = new ZoneInfo
                {
                    Type = MarketZoneType.Fvg,
                    Direction = bullish ? MarketDirection.Bullish : MarketDirection.Bearish,
                    OriginIndex = i - 2,
                    ConfirmationIndex = i,
                    Low = bullish ? candles[i - 2].High : candles[i].High,
                    High = bullish ? candles[i].Low : candles[i - 2].Low
                };
                ResolveZoneLifecycle(candles, zone, lastClosedIndex);
                values.Add(zone);
                if (zone.State == MarketZoneState.Invalidated)
                {
                    var inverse = new ZoneInfo
                    {
                        Type = MarketZoneType.InverseFvg,
                        Direction = Opposite(zone.Direction),
                        OriginIndex = zone.OriginIndex,
                        ConfirmationIndex = zone.InvalidationIndex,
                        Low = zone.Low,
                        High = zone.High
                    };
                    ResolveZoneLifecycle(candles, inverse, lastClosedIndex);
                    values.Add(inverse);
                }
            }

            var usedOrigins = new HashSet<string>(StringComparer.Ordinal);
            foreach (var structure in structures ?? new List<StructureEventInfo>())
            {
                if (structure.Type == MarketStructureEventType.Sweep || structure.ConfirmationIndex < start || structure.ConfirmationIndex > lastClosedIndex)
                    continue;
                var candle = candles[structure.ConfirmationIndex];
                var range = Math.Max(candle.High - candle.Low, 0.0000001);
                var body = Math.Abs(candle.Close - candle.Open);
                var directional = structure.Direction == MarketDirection.Bullish ? candle.Close > candle.Open : candle.Close < candle.Open;
                if (!directional || body / range < config.OrderBlockBodyRatio || !HasVolumeSurge(candles, structure.ConfirmationIndex, config.VolumeSurgeMultiplier))
                    continue;
                var origin = FindOppositeCandle(candles, structure.ConfirmationIndex, structure.Direction, config.OrderBlockOriginLookback);
                if (origin < 0)
                    continue;
                var key = origin.ToString(CultureInfo.InvariantCulture) + ":" + structure.Direction;
                if (!usedOrigins.Add(key))
                    continue;
                var zone = new ZoneInfo
                {
                    Type = MarketZoneType.OrderBlock,
                    Direction = structure.Direction,
                    OriginIndex = origin,
                    ConfirmationIndex = structure.ConfirmationIndex,
                    Low = candles[origin].Low,
                    High = candles[origin].High
                };
                ResolveZoneLifecycle(candles, zone, lastClosedIndex);
                values.Add(zone);
                if (zone.State == MarketZoneState.Invalidated)
                {
                    var breaker = new ZoneInfo
                    {
                        Type = MarketZoneType.BreakerBlock,
                        Direction = Opposite(zone.Direction),
                        OriginIndex = zone.OriginIndex,
                        ConfirmationIndex = zone.InvalidationIndex,
                        Low = zone.Low,
                        High = zone.High
                    };
                    ResolveZoneLifecycle(candles, breaker, lastClosedIndex);
                    values.Add(breaker);
                }
            }

            AddClusterZones(values, swings, candles, lastClosedIndex, config, symbol);
            return values.OrderBy(value => value.ConfirmationIndex).ThenBy(value => value.Type).ToList();
        }

        private void AddClusterZones(List<ZoneInfo> zones, List<SwingInfo> swings, List<MarketCandle> candles, int lastClosedIndex, ZoneAnalysisConfig config, MarketSymbolInput symbol)
        {
            var tolerance = Math.Max(symbol != null ? symbol.PipSize * config.ClusterTolerancePips : 0, 0.0000001);
            foreach (var isHigh in new[] { true, false })
            {
                var candidates = (swings ?? new List<SwingInfo>()).Where(value => value.IsHigh == isHigh).OrderBy(value => value.Price).ToList();
                var used = new HashSet<int>();
                foreach (var pivot in candidates)
                {
                    if (used.Contains(pivot.Index)) continue;
                    var cluster = candidates.Where(value => !used.Contains(value.Index) && Math.Abs(value.Price - pivot.Price) <= tolerance).ToList();
                    if (cluster.Count < Math.Max(2, config.ClusterMinimumTouches)) continue;
                    foreach (var item in cluster) used.Add(item.Index);
                    var latest = cluster.OrderByDescending(value => value.Index).First();
                    var zone = new ZoneInfo
                    {
                        Type = isHigh ? MarketZoneType.Supply : MarketZoneType.Demand,
                        Direction = isHigh ? MarketDirection.Bearish : MarketDirection.Bullish,
                        OriginIndex = cluster.Min(value => value.Index),
                        ConfirmationIndex = latest.ConfirmationIndex,
                        Low = cluster.Min(value => value.Price),
                        High = cluster.Max(value => value.Price)
                    };
                    ResolveZoneLifecycle(candles, zone, lastClosedIndex);
                    zones.Add(zone);
                }
            }
        }

        public List<KeyLevelInfo> DetectKeyLevels(List<MarketCandle> candles, int lastClosedIndex, string timeFrame, KeyLevelAnalysisConfig config)
        {
            var values = new List<KeyLevelInfo>();
            if (candles == null || config == null || lastClosedIndex < 0)
                return values;
            var closed = candles.Take(lastClosedIndex + 1).ToList();
            var days = closed.GroupBy(value => value.OpenTimeUtc.Date).OrderBy(value => value.Key).ToList();
            if (config.IncludePreviousDay && days.Count >= 2) AddPeriodLevels(values, days[days.Count - 2], timeFrame, "PDH", "PDL");
            if (config.IncludeCurrentDay && days.Count >= 1) AddPeriodLevels(values, days[days.Count - 1], timeFrame, "Today High", "Today Low");
            var weeks = closed.GroupBy(value => GetIsoWeekKey(value.OpenTimeUtc)).OrderBy(value => value.Key, StringComparer.Ordinal).ToList();
            if (config.IncludePreviousWeek && weeks.Count >= 2) AddPeriodLevels(values, weeks[weeks.Count - 2], timeFrame, "PWH", "PWL");
            AddSessionLevels(values, closed, timeFrame, config.Sessions);
            return values;
        }

        private void AddSessionLevels(List<KeyLevelInfo> values, List<MarketCandle> candles, string timeFrame, List<SessionWindowConfig> sessions)
        {
            if (candles == null || candles.Count == 0 || sessions == null || sessions.Count == 0)
                return;
            var inferredDuration = candles.Count > 1 ? candles[candles.Count - 1].OpenTimeUtc - candles[candles.Count - 2].OpenTimeUtc : TimeSpan.Zero;
            var referenceTime = candles[candles.Count - 1].OpenTimeUtc.Add(inferredDuration > TimeSpan.Zero ? inferredDuration : TimeSpan.FromMinutes(1));
            foreach (var session in sessions)
            {
                if (session == null || string.IsNullOrWhiteSpace(session.Name)) continue;
                DateTime bestStart = DateTime.MinValue;
                DateTime bestEnd = DateTime.MinValue;
                for (var dayOffset = 0; dayOffset <= 7; dayOffset++)
                {
                    var date = referenceTime.Date.AddDays(-dayOffset);
                    var start = date.Add(session.StartUtc);
                    var end = date.Add(session.EndUtc);
                    if (end <= start) end = end.AddDays(1);
                    if (end <= referenceTime && end > bestEnd) { bestStart = start; bestEnd = end; }
                }
                if (bestStart == DateTime.MinValue) continue;
                var period = candles.Where(value => value.OpenTimeUtc >= bestStart && value.OpenTimeUtc < bestEnd).ToList();
                AddPeriodLevels(values, period, timeFrame, session.Name + " High", session.Name + " Low");
            }
        }

        private void AddPeriodLevels(List<KeyLevelInfo> values, IEnumerable<MarketCandle> period, string timeFrame, string highName, string lowName)
        {
            var list = period.ToList();
            if (list.Count == 0) return;
            var high = list.OrderByDescending(value => value.High).First();
            var low = list.OrderBy(value => value.Low).First();
            values.Add(new KeyLevelInfo { Name = highName, TimeFrame = timeFrame ?? "", TimeUtc = high.OpenTimeUtc, Price = high.High, IsHigh = true });
            values.Add(new KeyLevelInfo { Name = lowName, TimeFrame = timeFrame ?? "", TimeUtc = low.OpenTimeUtc, Price = low.Low, IsHigh = false });
        }

        private List<CandlePatternInfo> DetectCandlePatterns(List<MarketCandle> candles, int lastClosedIndex, CandlePatternAnalysisConfig config, AnalysisConfluenceConfig confluence)
        {
            var values = new List<CandlePatternInfo>();
            if (candles == null || config == null || lastClosedIndex < 0)
                return values;
            var start = Math.Max(2, lastClosedIndex - Math.Max(3, config.LookbackBars) + 1);
            for (var i = start; i <= lastClosedIndex; i++)
            {
                var current = candles[i];
                var previous = candles[i - 1];
                var body = Body(current);
                var range = Range(current);
                var bodyRatio = range > 0 ? body / range : 0;
                var upper = UpperWick(current);
                var lower = LowerWick(current);
                var priorUp = IsPriorTrend(candles, i, config.TrendContextBars, true);
                var priorDown = IsPriorTrend(candles, i, config.TrendContextBars, false);

                if (range > 0 && bodyRatio <= config.DojiBodyRatio)
                {
                    if (lower >= range * 0.6 && upper <= range * 0.1) AddPattern(values, confluence, candles, i, i, "Dragonfly Doji", "DOJI.D", MarketDirection.Bullish);
                    else if (upper >= range * 0.6 && lower <= range * 0.1) AddPattern(values, confluence, candles, i, i, "Gravestone Doji", "DOJI.G", MarketDirection.Bearish);
                    else if (upper >= range * 0.35 && lower >= range * 0.35) AddPattern(values, confluence, candles, i, i, "Long-Legged Doji", "DOJI.L", MarketDirection.Neutral);
                    else AddPattern(values, confluence, candles, i, i, "Doji", "DOJI", MarketDirection.Neutral);
                }
                if (body > 0 && lower >= body * config.WickDominanceRatio && upper <= body * 0.5 && bodyRatio <= config.SmallBodyRatio)
                    AddPattern(values, confluence, candles, i, i, priorUp ? "Hanging Man" : "Hammer", priorUp ? "HGM" : "HAM", priorUp ? MarketDirection.Bearish : MarketDirection.Bullish);
                if (body > 0 && upper >= body * config.WickDominanceRatio && lower <= body * 0.5 && bodyRatio <= config.SmallBodyRatio)
                    AddPattern(values, confluence, candles, i, i, priorUp ? "Shooting Star" : "Inverted Hammer", priorUp ? "SST" : "IHM", priorUp ? MarketDirection.Bearish : MarketDirection.Bullish);
                if (range > 0 && bodyRatio >= config.LongBodyRatio && upper <= range * 0.05 && lower <= range * 0.05)
                    AddPattern(values, confluence, candles, i, i, current.Close > current.Open ? "Bullish Marubozu" : "Bearish Marubozu", "MAR", current.Close > current.Open ? MarketDirection.Bullish : MarketDirection.Bearish);

                var bullishEngulf = previous.Close < previous.Open && current.Close > current.Open && current.Open <= previous.Close && current.Close >= previous.Open && body > Body(previous);
                var bearishEngulf = previous.Close > previous.Open && current.Close < current.Open && current.Open >= previous.Close && current.Close <= previous.Open && body > Body(previous);
                if (bullishEngulf) AddPattern(values, confluence, candles, i - 1, i, "Bullish Engulfing", "ENG", MarketDirection.Bullish);
                if (bearishEngulf) AddPattern(values, confluence, candles, i - 1, i, "Bearish Engulfing", "ENG", MarketDirection.Bearish);

                var prevBodyHigh = Math.Max(previous.Open, previous.Close);
                var prevBodyLow = Math.Min(previous.Open, previous.Close);
                var bodyHigh = Math.Max(current.Open, current.Close);
                var bodyLow = Math.Min(current.Open, current.Close);
                var previousBody = Body(previous);
                var previousRange = Range(previous);
                var previousBodyRatio = previousRange > 0 ? previousBody / previousRange : 0;
                var contained = previousBody > 0 &&
                                previousBodyRatio >= config.LongBodyRatio &&
                                bodyHigh <= prevBodyHigh &&
                                bodyLow >= prevBodyLow &&
                                body <= previousBody * 0.75;
                var haramiCross = range > 0 && body <= range * config.DojiBodyRatio;
                var haramiPriorPressure = InferMarketCandlePriorPressure(candles, i - 2, Math.Max(4, config.TrendContextBars));
                var secondBarDirections = values
                    .Where(value => value != null && value.EndIndex == i &&
                        !string.Equals(value.Code, "HAR", StringComparison.OrdinalIgnoreCase) &&
                        value.Direction != MarketDirection.Neutral)
                    .Select(value => value.Direction)
                    .Distinct()
                    .ToList();
                var hasSecondPatternDirection = secondBarDirections.Count == 1;
                if (contained && hasSecondPatternDirection)
                {
                    var haramiDirection = secondBarDirections[0];
                    var bullishHarami = haramiDirection == MarketDirection.Bullish;
                    AddPattern(
                        values,
                        confluence,
                        candles,
                        i - 1,
                        i,
                        bullishHarami ? "Bullish Harami" : "Bearish Harami",
                        "HAR",
                        haramiDirection);
                    if (haramiCross)
                    {
                        AddPattern(
                            values,
                            confluence,
                            candles,
                            i - 1,
                            i,
                            bullishHarami ? "Bullish Harami Cross" : "Bearish Harami Cross",
                            "HAR",
                            haramiDirection);
                    }
                }
                else
                {
                    if (contained && previous.Close < previous.Open && current.Close > current.Open && string.Equals(haramiPriorPressure, "down", StringComparison.OrdinalIgnoreCase))
                        AddPattern(values, confluence, candles, i - 1, i, "Bullish Harami", "HAR", MarketDirection.Bullish);
                    if (contained && previous.Close > previous.Open && current.Close < current.Open && string.Equals(haramiPriorPressure, "up", StringComparison.OrdinalIgnoreCase))
                        AddPattern(values, confluence, candles, i - 1, i, "Bearish Harami", "HAR", MarketDirection.Bearish);
                    if (contained && haramiCross && previous.Close < previous.Open && string.Equals(haramiPriorPressure, "down", StringComparison.OrdinalIgnoreCase))
                        AddPattern(values, confluence, candles, i - 1, i, "Bullish Harami Cross", "HAR", MarketDirection.Bullish);
                    if (contained && haramiCross && previous.Close > previous.Open && string.Equals(haramiPriorPressure, "up", StringComparison.OrdinalIgnoreCase))
                        AddPattern(values, confluence, candles, i - 1, i, "Bearish Harami Cross", "HAR", MarketDirection.Bearish);
                }

                var tolerance = Math.Min(Range(previous), range) * 0.1;
                if (tolerance > 0 && Math.Abs(previous.High - current.High) <= tolerance && priorUp && (current.Close < current.Open || bodyRatio <= config.SmallBodyRatio)) AddPattern(values, confluence, candles, i - 1, i, "Tweezer Top", "TWZ", MarketDirection.Bearish);
                if (tolerance > 0 && Math.Abs(previous.Low - current.Low) <= tolerance && priorDown && (current.Close > current.Open || bodyRatio <= config.SmallBodyRatio)) AddPattern(values, confluence, candles, i - 1, i, "Tweezer Bottom", "TWZ", MarketDirection.Bullish);

                DetectThreeCandlePatterns(values, confluence, candles, i, config);
            }
            return values;
        }

        private string InferMarketCandlePriorPressure(List<MarketCandle> candles, int endIndex, int lookback)
        {
            if (candles == null || endIndex < 1 || endIndex >= candles.Count)
                return "neutral";

            var startIndex = Math.Max(0, endIndex - Math.Max(2, lookback) + 1);
            var first = candles[startIndex];
            var last = candles[endIndex];
            if (first == null || last == null)
                return "neutral";

            var firstClose = first.Close;
            var lastClose = last.Close;
            var bullishCount = 0;
            var bearishCount = 0;
            for (var j = startIndex; j <= endIndex; j++)
            {
                var candle = candles[j];
                if (candle == null)
                    continue;
                if (candle.Close > candle.Open)
                    bullishCount++;
                else if (candle.Close < candle.Open)
                    bearishCount++;
            }

            if (lastClose < firstClose && bearishCount >= bullishCount + 1)
                return "down";
            if (lastClose > firstClose && bullishCount >= bearishCount + 1)
                return "up";
            return "neutral";
        }

        private void DetectThreeCandlePatterns(List<CandlePatternInfo> values, AnalysisConfluenceConfig confluence, List<MarketCandle> candles, int i, CandlePatternAnalysisConfig config)
        {
            if (i < 2) return;
            var first = candles[i - 2];
            var middle = candles[i - 1];
            var last = candles[i];
            var firstRatio = Body(first) / Math.Max(Range(first), 0.0000001);
            var middleRatio = Body(middle) / Math.Max(Range(middle), 0.0000001);
            if (first.Close < first.Open && firstRatio >= config.LongBodyRatio && middleRatio <= config.SmallBodyRatio && last.Close > last.Open && last.Close > (first.Open + first.Close) * 0.5)
                AddPattern(values, confluence, candles, i - 2, i, "Morning Star", "MOR", MarketDirection.Bullish);
            if (first.Close > first.Open && firstRatio >= config.LongBodyRatio && middleRatio <= config.SmallBodyRatio && last.Close < last.Open && last.Close < (first.Open + first.Close) * 0.5)
                AddPattern(values, confluence, candles, i - 2, i, "Evening Star", "EVE", MarketDirection.Bearish);
            var soldiers = first.Close > first.Open && middle.Close > middle.Open && last.Close > last.Open && middle.Close > first.Close && last.Close > middle.Close;
            var crows = first.Close < first.Open && middle.Close < middle.Open && last.Close < last.Open && middle.Close < first.Close && last.Close < middle.Close;
            if (soldiers) AddPattern(values, confluence, candles, i - 2, i, "Three White Soldiers", "3WS", MarketDirection.Bullish);
            if (crows) AddPattern(values, confluence, candles, i - 2, i, "Three Black Crows", "3BC", MarketDirection.Bearish);
        }

        private void AddPattern(List<CandlePatternInfo> values, AnalysisConfluenceConfig confluence, List<MarketCandle> candles, int start, int end, string name, string code, MarketDirection direction)
        {
            if (confluence != null && !confluence.IsPatternEnabled(code) && !confluence.IsPatternEnabled(name)) return;
            values.Add(new CandlePatternInfo
            {
                Name = name,
                Code = code,
                Direction = direction,
                StartIndex = start,
                EndIndex = end,
                TimeUtc = candles[end].OpenTimeUtc,
                Low = candles.Skip(start).Take(end - start + 1).Min(value => value.Low),
                High = candles.Skip(start).Take(end - start + 1).Max(value => value.High)
            });
        }

        private List<ConfluenceInfo> CalculateConfluences(MarketSymbolInput symbol, string timeFrame, TimeFrameAnalysisResult result, ConfluenceCalculationConfig config)
        {
            var values = new List<ConfluenceInfo>();
            var tolerance = Math.Max(symbol != null ? symbol.PipSize * Math.Max(0, config.TolerancePips) : 0, 0.0000001);
            foreach (var pattern in result.CandlePatterns.Where(value => value.Direction != MarketDirection.Neutral))
            {
                var anchor = pattern.Direction == MarketDirection.Bullish ? pattern.Low : pattern.High;
                var reasons = new List<string>();
                foreach (var level in result.KeyLevels.Where(value => Math.Abs(value.Price - anchor) <= tolerance)) reasons.Add(level.Name);
                foreach (var swing in result.Swings.Where(value => Math.Abs(value.Price - anchor) <= tolerance)) reasons.Add(swing.IsHigh ? "Swing High" : "Swing Low");
                foreach (var zone in result.Zones.Where(value => value.State != MarketZoneState.Invalidated && anchor >= value.Low - tolerance && anchor <= value.High + tolerance)) reasons.Add(zone.Type.ToString());
                reasons = reasons.Distinct(StringComparer.OrdinalIgnoreCase).ToList();
                if (reasons.Count < Math.Max(0, config.MinimumScore)) continue;
                values.Add(new ConfluenceInfo { TimeFrame = timeFrame ?? "", PatternCode = pattern.Code, PatternIndex = pattern.EndIndex, Direction = pattern.Direction, Score = reasons.Count, Reasons = reasons });
            }
            return values;
        }

        private List<TradePlanInfo> CalculateTrades(MarketSymbolInput symbol, string timeFrame, List<MarketCandle> candles, TimeFrameAnalysisResult result, TradePlanAnalysisConfig config, AnalysisStrategyConfig strategy)
        {
            var values = new List<TradePlanInfo>();
            if (config == null || !config.Enabled || symbol == null || !(symbol.PipSize > 0)) return values;
            foreach (var pattern in result.CandlePatterns.Where(value => value.Direction != MarketDirection.Neutral))
            {
                if (strategy != null && strategy.AllowedDirection != MarketDirection.Neutral && strategy.AllowedDirection != pattern.Direction) continue;
                var confluence = result.Confluences.FirstOrDefault(value => value.PatternIndex == pattern.EndIndex && value.Direction == pattern.Direction);
                var requiredScore = strategy != null ? Math.Max(0, strategy.MinimumConfluenceScore) : 0;
                if (requiredScore > 0 && (confluence == null || confluence.Score < requiredScore)) continue;
                var baseEntry = NormalizePrice(candles[pattern.EndIndex].Close, symbol.Digits);
                var height = Math.Max(pattern.High - pattern.Low, symbol.PipSize);
                var buffer = Math.Max(symbol.PipSize, height * Math.Max(0, config.StopBufferRatio));
                var candidateSwings = result.Swings.Where(value => value.Index <= pattern.EndIndex && value.IsHigh == (pattern.Direction == MarketDirection.Bearish)).ToList();
                double swingPrice;
                if (pattern.Direction == MarketDirection.Bullish)
                {
                    var eligible = candidateSwings.Where(value => value.Price <= pattern.Low + symbol.PipSize * 2).OrderBy(value => Math.Abs(pattern.Low - value.Price)).ThenByDescending(value => value.Index).FirstOrDefault();
                    swingPrice = eligible != null ? eligible.Price : pattern.Low;
                }
                else
                {
                    var eligible = candidateSwings.Where(value => value.Price >= pattern.High - symbol.PipSize * 2).OrderBy(value => Math.Abs(value.Price - pattern.High)).ThenByDescending(value => value.Index).FirstOrDefault();
                    swingPrice = eligible != null ? eligible.Price : pattern.High;
                }
                var stop = NormalizePrice(pattern.Direction == MarketDirection.Bullish ? swingPrice - buffer : swingPrice + buffer, symbol.Digits);
                var risk = Math.Abs(baseEntry - stop);
                if (!(risk > 0)) continue;
                var plan = new TradePlanInfo
                {
                    StrategyId = strategy != null ? strategy.StrategyId ?? "" : "",
                    TimeFrame = timeFrame ?? "",
                    SourcePattern = pattern.Code,
                    Direction = pattern.Direction,
                    SignalIndex = pattern.EndIndex,
                    BaseEntry = baseEntry,
                    StopLoss = stop,
                    TakeProfit = NormalizePrice(pattern.Direction == MarketDirection.Bullish ? baseEntry + risk * Math.Max(0.1, config.RewardRiskRatio) : baseEntry - risk * Math.Max(0.1, config.RewardRiskRatio), symbol.Digits),
                    ConfluenceScore = confluence != null ? confluence.Score : 0
                };
                foreach (var ratio in config.LimitEntryRatios ?? new List<double>())
                {
                    var clamped = Math.Max(0, Math.Min(1, ratio));
                    var entry = pattern.Direction == MarketDirection.Bullish ? baseEntry - (baseEntry - stop) * clamped : baseEntry + (stop - baseEntry) * clamped;
                    plan.LimitEntries.Add(NormalizePrice(entry, symbol.Digits));
                }
                values.Add(plan);
            }
            return values;
        }

        private bool IsQualifiedFvg(List<MarketCandle> candles, int rightIndex, bool bullish, ZoneAnalysisConfig config)
        {
            var left = candles[rightIndex - 2];
            var middle = candles[rightIndex - 1];
            var right = candles[rightIndex];
            var leftRange = Math.Max(Range(left), 0.0000001);
            var middleRange = Math.Max(Range(middle), 0.0000001);
            var rightRange = Math.Max(Range(right), 0.0000001);
            var middleBody = Body(middle);
            var dominant = (config.FvgDisplacementRatio <= 0 || (middleRange >= leftRange * config.FvgDisplacementRatio && middleRange >= rightRange * config.FvgDisplacementRatio && middleBody >= Body(left) * config.FvgDisplacementRatio && middleBody >= Body(right) * config.FvgDisplacementRatio)) && (config.FvgBodyRatio <= 0 || middleBody / middleRange >= config.FvgBodyRatio);
            if (!dominant) return false;
            var gap = bullish ? right.Low - left.High : left.Low - right.High;
            var directional = bullish ? middle.Close > middle.Open : middle.Close < middle.Open;
            return directional && (config.FvgGapRatio <= 0 || gap >= middleRange * config.FvgGapRatio);
        }

        private bool HasVolumeSurge(List<MarketCandle> candles, int index, double multiplier)
        {
            if (multiplier <= 1.0) return true;
            if (candles == null || index <= 0 || index >= candles.Count) return false;
            return candles[index].Volume > 0 && candles[index - 1].Volume > 0 && candles[index].Volume > candles[index - 1].Volume * multiplier;
        }

        private void ResolveZoneLifecycle(List<MarketCandle> candles, ZoneInfo zone, int lastClosedIndex)
        {
            zone.State = MarketZoneState.Active;
            zone.TouchIndex = -1;
            zone.InvalidationIndex = -1;
            for (var i = Math.Max(0, zone.ConfirmationIndex + 1); i <= lastClosedIndex; i++)
            {
                if (zone.TouchIndex < 0 && candles[i].High >= zone.Low && candles[i].Low <= zone.High) zone.TouchIndex = i;
                var invalid = zone.Direction == MarketDirection.Bullish ? candles[i].Close < zone.Low : candles[i].Close > zone.High;
                if (!invalid) continue;
                zone.State = MarketZoneState.Invalidated;
                zone.InvalidationIndex = i;
                return;
            }
            if (zone.TouchIndex >= 0) zone.State = MarketZoneState.Touched;
        }

        private int FindOppositeCandle(List<MarketCandle> candles, int confirmationIndex, MarketDirection direction, int maxBack)
        {
            for (var i = confirmationIndex - 1; i >= Math.Max(1, confirmationIndex - Math.Max(1, maxBack)); i--)
            {
                if (direction == MarketDirection.Bullish && candles[i].Close < candles[i].Open) return i;
                if (direction == MarketDirection.Bearish && candles[i].Close > candles[i].Open) return i;
            }
            return -1;
        }

        private bool IsPriorTrend(List<MarketCandle> candles, int index, int period, bool bullish)
        {
            var start = index - Math.Max(2, period);
            if (start < 0 || index <= 0) return false;
            return bullish ? candles[index - 1].Close > candles[start].Close : candles[index - 1].Close < candles[start].Close;
        }

        private string GetIsoWeekKey(DateTime value)
        {
            var mondayBasedDay = ((int)value.DayOfWeek + 6) % 7;
            var thursday = value.Date.AddDays(3 - mondayBasedDay);
            var week = CultureInfo.InvariantCulture.Calendar.GetWeekOfYear(thursday, CalendarWeekRule.FirstFourDayWeek, DayOfWeek.Monday);
            return thursday.Year.ToString("0000", CultureInfo.InvariantCulture) + "-" + week.ToString("00", CultureInfo.InvariantCulture);
        }

        private double NormalizePrice(double value, int digits) { return Math.Round(value, Math.Max(0, digits), MidpointRounding.AwayFromZero); }
        private double Range(MarketCandle candle) { return Math.Max(0, candle.High - candle.Low); }
        private double Body(MarketCandle candle) { return Math.Abs(candle.Close - candle.Open); }
        private double UpperWick(MarketCandle candle) { return Math.Max(0, candle.High - Math.Max(candle.Open, candle.Close)); }
        private double LowerWick(MarketCandle candle) { return Math.Max(0, Math.Min(candle.Open, candle.Close) - candle.Low); }
        private MarketDirection Opposite(MarketDirection direction) { return direction == MarketDirection.Bullish ? MarketDirection.Bearish : direction == MarketDirection.Bearish ? MarketDirection.Bullish : MarketDirection.Neutral; }
    }
}
